function fitIntercomConversationTags() {
  const container = elements.intercomConversationTags;
  if (!container || container.hidden) return;
  const tags = [...container.querySelectorAll(":scope > button.composer-intercom-tag:not(.overflow)")];
  const overflow = container.querySelector("button.composer-intercom-tag.overflow");
  const menuItems = [...container.querySelectorAll(".composer-intercom-overflow-menu-item")];
  if (!tags.length || !overflow || menuItems.length !== tags.length) return;

  const availableWidth = container.clientWidth;
  if (availableWidth <= 0) return;

  for (const tag of tags) tag.hidden = false;
  overflow.hidden = false;

  const containerStyle = getComputedStyle(container);
  const gap = Number.parseFloat(containerStyle.columnGap || containerStyle.gap) || 0;
  const tagWidths = tags.map((tag) => tag.getBoundingClientRect().width);
  const overflowWidths = new Map();
  const maxOverflowDigits = String(tags.length).length;
  for (let digits = 1; digits <= maxOverflowDigits; digits += 1) {
    overflow.textContent = `+${"0".repeat(digits)}`;
    overflowWidths.set(digits, overflow.getBoundingClientRect().width);
  }
  let visibleCount = 0;

  for (let count = tags.length; count >= 0; count -= 1) {
    const hiddenCount = tags.length - count;
    const itemCount = count + (hiddenCount ? 1 : 0);
    const tagsWidth = tagWidths.slice(0, count).reduce((total, width) => total + width, 0);
    const overflowWidth = hiddenCount ? overflowWidths.get(String(hiddenCount).length) || 0 : 0;
    const requiredWidth = tagsWidth + overflowWidth + Math.max(0, itemCount - 1) * gap;
    if (requiredWidth <= availableWidth + 0.5) {
      visibleCount = count;
      break;
    }
  }

  tags.forEach((tag, index) => { tag.hidden = index >= visibleCount; });
  menuItems.forEach((item, index) => { item.hidden = index < visibleCount; });
  const hiddenCount = tags.length - visibleCount;
  overflow.hidden = hiddenCount === 0;
  if (hiddenCount) {
    const label = `Show ${hiddenCount} more agent conversation${hiddenCount === 1 ? "" : "s"}`;
    overflow.textContent = `+${hiddenCount}`;
    overflow.title = `${label}.`;
    overflow.setAttribute("aria-label", label);
    if (intercomConversationOverflowOpen) setIntercomConversationOverflowOpen(true);
  } else {
    setIntercomConversationOverflowOpen(false);
  }
}

function scheduleIntercomConversationTagLayout() {
  if (intercomConversationTagLayoutFrame) return;
  intercomConversationTagLayoutFrame = requestAnimationFrame(() => {
    intercomConversationTagLayoutFrame = 0;
    fitIntercomConversationTags();
  });
}

function installIntercomConversationTagResizeHandling() {
  const container = elements.intercomConversationTags;
  if (!container) return;
  if (typeof ResizeObserver === "function") {
    intercomConversationTagResizeObserver = new ResizeObserver(scheduleIntercomConversationTagLayout);
    intercomConversationTagResizeObserver.observe(container);
    if (container.parentElement) intercomConversationTagResizeObserver.observe(container.parentElement);
  } else {
    window.addEventListener("resize", scheduleIntercomConversationTagLayout, { passive: true });
  }
  container.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !intercomConversationOverflowOpen) return;
    event.preventDefault();
    event.stopPropagation();
    setIntercomConversationOverflowOpen(false, { restoreFocus: true });
  });
  container.addEventListener("focusout", () => {
    queueMicrotask(() => {
      if (intercomConversationOverflowOpen && !container.contains(document.activeElement)) setIntercomConversationOverflowOpen(false);
    });
  });
  document.addEventListener("pointerdown", (event) => {
    if (intercomConversationOverflowOpen && !container.contains(event.target)) setIntercomConversationOverflowOpen(false);
  });
}

function updateIntercomConversationTag(tag, conversation) {
  const label = intercomConversationLabel(conversation);
  tag.setAttribute("aria-label", `Open agent conversation ${label}`);
  tag.title = `${label} · ${conversation.messageCount} message${conversation.messageCount === 1 ? "" : "s"}`;
  const visualSignature = JSON.stringify([label, conversation.messageCount]);
  if (tag.dataset.intercomVisualSignature === visualSignature) return;
  const children = [make("span", "composer-intercom-tag-icon", "↔"), make("span", "composer-intercom-tag-label", label)];
  if (conversation.messageCount > 0) children.push(make("span", "composer-intercom-tag-count", String(conversation.messageCount)));
  tag.replaceChildren(...children);
  tag.dataset.intercomVisualSignature = visualSignature;
}

function renderIntercomConversationTags(tabId = activeTabId) {
  const container = elements.intercomConversationTags;
  if (!container) return;
  const conversations = intercomConversationSummariesByTab.get(tabId) || [];
  if (!conversations.length) {
    intercomConversationOverflowOpen = false;
    container.classList.remove("overflow-open");
    container.replaceChildren();
    container.hidden = true;
    return;
  }

  let overflow = container.querySelector("button.composer-intercom-tag.overflow");
  if (!overflow) {
    overflow = make("button", "composer-intercom-tag overflow", `+${conversations.length}`);
    overflow.type = "button";
    overflow.hidden = true;
    overflow.setAttribute("aria-haspopup", "dialog");
    overflow.setAttribute("aria-expanded", "false");
    overflow.setAttribute("aria-controls", "intercomConversationOverflowMenu");
    overflow.addEventListener("click", () => {
      const opening = !intercomConversationOverflowOpen;
      setIntercomConversationOverflowOpen(opening, { focusMenu: opening });
    });
  }
  let menu = container.querySelector(".composer-intercom-overflow-menu");
  if (!menu) {
    menu = make("div", "composer-intercom-overflow-menu");
    menu.id = "intercomConversationOverflowMenu";
    menu.hidden = true;
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "More agent conversations");
  }
  container.append(overflow, menu);

  const existingTags = new Map([...container.querySelectorAll(":scope > .composer-intercom-tag[data-intercom-conversation-id]")]
    .map((tag) => [tag.dataset.intercomConversationId, tag]));
  const existingMenuItems = new Map([...menu.querySelectorAll(".composer-intercom-overflow-menu-item[data-intercom-conversation-id]")]
    .map((tag) => [tag.dataset.intercomConversationId, tag]));
  const orderedTags = [];
  const orderedMenuItems = [];
  const seenConversationIds = new Set();
  for (const conversation of conversations) {
    if (seenConversationIds.has(conversation.id)) continue;
    seenConversationIds.add(conversation.id);
    let tag = existingTags.get(conversation.id);
    if (tag) existingTags.delete(conversation.id);
    else {
      tag = make("button", "composer-intercom-tag");
      tag.type = "button";
      tag.dataset.intercomConversationId = conversation.id;
      tag.setAttribute("aria-haspopup", "dialog");
      tag.setAttribute("aria-controls", "intercomConversationDialog");
      tag.addEventListener("click", () => openIntercomConversation(tag.dataset.intercomConversationId));
    }
    updateIntercomConversationTag(tag, conversation);
    orderedTags.push(tag);

    let menuItem = existingMenuItems.get(conversation.id);
    if (menuItem) existingMenuItems.delete(conversation.id);
    else {
      menuItem = make("button", "composer-intercom-tag composer-intercom-overflow-menu-item");
      menuItem.type = "button";
      menuItem.dataset.intercomConversationId = conversation.id;
      menuItem.setAttribute("aria-haspopup", "dialog");
      menuItem.setAttribute("aria-controls", "intercomConversationDialog");
      menuItem.addEventListener("click", () => {
        const conversationId = menuItem.dataset.intercomConversationId;
        setIntercomConversationOverflowOpen(false);
        overflow.focus();
        openIntercomConversation(conversationId);
      });
    }
    updateIntercomConversationTag(menuItem, conversation);
    orderedMenuItems.push(menuItem);
  }

  for (const staleTag of existingTags.values()) staleTag.remove();
  for (const staleItem of existingMenuItems.values()) staleItem.remove();
  const currentTags = [...container.querySelectorAll(":scope > .composer-intercom-tag[data-intercom-conversation-id]")];
  if (currentTags.length !== orderedTags.length || orderedTags.some((tag, index) => currentTags[index] !== tag)) {
    for (const tag of orderedTags) container.insertBefore(tag, overflow);
  }
  const currentMenuItems = [...menu.querySelectorAll(":scope > .composer-intercom-overflow-menu-item")];
  if (currentMenuItems.length !== orderedMenuItems.length || orderedMenuItems.some((tag, index) => currentMenuItems[index] !== tag)) {
    for (const menuItem of orderedMenuItems) menu.append(menuItem);
  }
  container.append(overflow, menu);
  container.hidden = false;
  scheduleIntercomConversationTagLayout();
}

async function refreshIntercomConversationSummaries(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const requestSerial = ++intercomSummaryRequestSerial;
  const response = await api("/api/intercom/conversations", { tabId: tabContext.tabId });
  if (requestSerial !== intercomSummaryRequestSerial || !isCurrentTabContext(tabContext)) return;
  const seenConversationIds = new Set();
  const conversations = [];
  for (const value of Array.isArray(response.data?.conversations) ? response.data.conversations : []) {
    const conversation = normalizeIntercomConversationSummary(value);
    if (!conversation || seenConversationIds.has(conversation.id)) continue;
    seenConversationIds.add(conversation.id);
    conversations.push(conversation);
  }
  const previous = intercomConversationSummariesByTab.get(tabContext.tabId) || [];
  intercomConversationSummariesByTab.set(tabContext.tabId, conversations);
  if (intercomConversationSummarySignature(previous) !== intercomConversationSummarySignature(conversations) && !elements.intercomConversationDialog?.open) {
    renderIntercomConversationTags(tabContext.tabId);
  }
  if (intercomConversationDialogState?.tabId === tabContext.tabId && !seenConversationIds.has(intercomConversationDialogState.conversationId)) {
    closeIntercomConversationDialog({ restoreFocus: false });
  }
}

function scheduleIntercomConversationRefresh(tabContext = activeTabContext(), delayMs = 180) {
  clearTimeout(intercomSummaryRefreshTimer);
  const scheduledContext = { ...tabContext };
  intercomSummaryRefreshTimer = setTimeout(() => {
    intercomSummaryRefreshTimer = null;
    if (!isCurrentTabContext(scheduledContext)) return;
    refreshIntercomConversationSummaries(scheduledContext).catch((error) => {
      if (isCurrentTabContext(scheduledContext)) addEvent(`agent conversation refresh failed: ${error.message || String(error)}`, "warn");
    });
  }, delayMs);
}

function setIntercomConversationStatus(message = "", level = "") {
  const status = elements.intercomConversationStatus;
  if (!status) return;
  status.textContent = message;
  status.classList.toggle("error", level === "error");
  status.classList.toggle("warn", level === "warn");
}

function formatIntercomMessageTime(value) {
  const timestamp = Date.parse(value || "");
  if (!Number.isFinite(timestamp)) return "";
  return new Date(timestamp).toLocaleString([], { dateStyle: "medium", timeStyle: "short" });
}

function renderIntercomConversationMessage(article, message, conversation) {
  const participant = message.direction === "local" ? conversation.participants.local : conversation.participants.peer;
  const senderLabel = intercomParticipantLabel(participant, message.direction === "local" ? "Local agent" : "Peer agent");
  const formattedTime = formatIntercomMessageTime(message.timestamp);
  const signature = JSON.stringify([message.direction, senderLabel, message.text, message.timestamp, message.truncatedText]);
  if (intercomMessageRenderSignatures.get(article) === signature) return;

  article.className = `intercom-conversation-message ${message.direction}`;
  article.dataset.intercomMessageId = message.id;
  article.setAttribute("aria-label", `${senderLabel} message`);
  const header = make("header", "intercom-conversation-message-header");
  header.append(make("strong", "intercom-conversation-message-sender", senderLabel));
  if (formattedTime) {
    const time = make("time", "intercom-conversation-message-time", formattedTime);
    time.dateTime = message.timestamp;
    header.append(time);
  }
  const text = make("p", "intercom-conversation-message-text");
  text.textContent = message.text;
  const children = [header, text];
  if (message.truncatedText) children.push(make("span", "intercom-conversation-truncated", "Message truncated"));
  article.replaceChildren(...children);
  intercomMessageRenderSignatures.set(article, signature);
}

function renderIntercomConversationDetail(conversation) {
  const transcript = elements.intercomConversationTranscript;
  if (!transcript || !conversation) return;
  const state = intercomConversationDialogState;
  const signature = JSON.stringify([
    conversation.id,
    conversation.truncatedBefore,
    intercomConversationLabel(conversation),
    conversation.messages.map((message) => [message.id, message.direction, message.text, message.timestamp, message.truncatedText]),
  ]);
  if (state?.detailSignature === signature) return;
  if (state) state.detailSignature = signature;

  const existingArticles = new Map([...transcript.querySelectorAll(":scope > .intercom-conversation-message[data-intercom-message-id]")]
    .map((article) => [article.dataset.intercomMessageId, article]));
  const shouldFollow = !existingArticles.size || transcript.scrollHeight - transcript.scrollTop - transcript.clientHeight < 80;
  const previousScrollTop = transcript.scrollTop;
  const anchor = shouldFollow ? null : [...existingArticles.values()]
    .find((article) => article.offsetTop + article.offsetHeight > transcript.scrollTop);
  const anchorOffset = anchor ? anchor.getBoundingClientRect().top - transcript.getBoundingClientRect().top : 0;
  const orderedArticles = [];

  for (const message of conversation.messages) {
    let article = existingArticles.get(message.id);
    if (article) existingArticles.delete(message.id);
    else article = make("article", `intercom-conversation-message ${message.direction}`);
    renderIntercomConversationMessage(article, message, conversation);
    orderedArticles.push(article);
  }
  for (const staleArticle of existingArticles.values()) staleArticle.remove();
  transcript.querySelector(":scope > .intercom-conversation-empty")?.remove();

  let cursor = transcript.firstElementChild;
  for (const article of orderedArticles) {
    if (article === cursor) cursor = cursor.nextElementSibling;
    else transcript.insertBefore(article, cursor);
  }
  if (!orderedArticles.length) transcript.append(make("p", "intercom-conversation-empty", "No messages are available in this conversation."));

  requestAnimationFrame(() => {
    if (state !== intercomConversationDialogState) return;
    if (shouldFollow) transcript.scrollTop = transcript.scrollHeight;
    else if (anchor?.isConnected) {
      const currentAnchorOffset = anchor.getBoundingClientRect().top - transcript.getBoundingClientRect().top;
      transcript.scrollTop += currentAnchorOffset - anchorOffset;
    }
    else transcript.scrollTop = previousScrollTop;
  });
}

function updateIntercomSummaryFromDetail(conversation) {
  const state = intercomConversationDialogState;
  if (!state || !conversation) return;
  const summaries = intercomConversationSummariesByTab.get(state.tabId) || [];
  const index = summaries.findIndex((summary) => summary.id === conversation.id);
  if (index < 0) return;
  const next = [...summaries];
  next[index] = { ...next[index], ...normalizeIntercomConversationSummary(conversation) };
  intercomConversationSummariesByTab.set(state.tabId, next);
}

function scheduleIntercomConversationDetailRefresh() {
  clearTimeout(intercomDetailRefreshTimer);
  intercomDetailRefreshTimer = null;
  const state = intercomConversationDialogState;
  if (!state || !elements.intercomConversationDialog?.open) return;
  intercomDetailRefreshTimer = setTimeout(() => {
    intercomDetailRefreshTimer = null;
    refreshIntercomConversationDetail({ announceLoading: false });
  }, INTERCOM_DETAIL_REFRESH_MS);
}

async function refreshIntercomConversationDetail({ announceLoading = false } = {}) {
  const state = intercomConversationDialogState;
  if (!state || !elements.intercomConversationDialog?.open) return;
  const requestSerial = ++intercomDetailRequestSerial;
  if (announceLoading) setIntercomConversationStatus("Loading agent messages…");
  try {
    const path = `/api/intercom/conversations?conversation=${encodeURIComponent(state.conversationId)}`;
    const response = await api(path, { tabId: state.tabId });
    if (requestSerial !== intercomDetailRequestSerial || state !== intercomConversationDialogState || !isCurrentTabContext(state)) return;
    const conversation = normalizeIntercomConversationDetail(response.data?.conversation);
    if (!conversation || conversation.id !== state.conversationId) throw new Error("Agent conversation is unavailable.");
    elements.intercomConversationTitle.textContent = intercomParticipantLabel(conversation.participants.peer, "Agent conversation");
    elements.intercomConversationParticipants.textContent = intercomConversationLabel(conversation);
    renderIntercomConversationDetail(conversation);
    updateIntercomSummaryFromDetail(conversation);
    const notices = [];
    if (conversation.truncatedBefore) notices.push("Earlier messages are unavailable.");
    if (conversation.messages.some((message) => message.truncatedText)) notices.push("One or more messages were truncated.");
    setIntercomConversationStatus(notices.join(" "), notices.length ? "warn" : "");
  } catch (error) {
    if (requestSerial === intercomDetailRequestSerial && state === intercomConversationDialogState && isCurrentTabContext(state)) {
      setIntercomConversationStatus(error.message || String(error), "error");
    }
  } finally {
    if (requestSerial === intercomDetailRequestSerial && state === intercomConversationDialogState) scheduleIntercomConversationDetailRefresh();
  }
}

function openIntercomConversation(conversationId) {
  if (!activeTabId || !INTERCOM_CONVERSATION_ID_PATTERN.test(String(conversationId || "")) || !elements.intercomConversationDialog) return;
  const summary = (intercomConversationSummariesByTab.get(activeTabId) || []).find((conversation) => conversation.id === conversationId);
  if (!summary) return;
  intercomDetailRequestSerial += 1;
  clearTimeout(intercomDetailRefreshTimer);
  intercomConversationDialogState = { ...activeTabContext(), conversationId, detailSignature: "" };
  elements.intercomConversationTitle.textContent = intercomParticipantLabel(summary.participants.peer, "Agent conversation");
  elements.intercomConversationParticipants.textContent = intercomConversationLabel(summary);
  elements.intercomConversationTranscript.replaceChildren();
  setIntercomConversationStatus("Loading agent messages…");
  if (!elements.intercomConversationDialog.open) elements.intercomConversationDialog.showModal();
  queueMicrotask(() => elements.intercomConversationCloseButton?.focus({ preventScroll: true }));
  refreshIntercomConversationDetail({ announceLoading: false });
}

function resetIntercomConversationDialog() {
  intercomDetailRequestSerial += 1;
  clearTimeout(intercomDetailRefreshTimer);
  intercomDetailRefreshTimer = null;
  intercomConversationDialogState = null;
  elements.intercomConversationTranscript?.replaceChildren();
  if (elements.intercomConversationParticipants) elements.intercomConversationParticipants.textContent = "";
  setIntercomConversationStatus("");
  renderIntercomConversationTags(activeTabId);
}

function closeIntercomConversationDialog({ restoreFocus = true } = {}) {
  const dialog = elements.intercomConversationDialog;
  if (!dialog?.open) {
    resetIntercomConversationDialog();
    return;
  }
  if (!restoreFocus) modalSurfaceState.delete(dialog);
  dialog.close();
}

function normalizeFeatureCategory(value) {
  return value === "lightweight-feature" || value === "complex-feature" ? value : "";
}

function normalizeFeatureDecisionKind(value) {
  return value === "feature_lightweight" || value === "feature_complex" ? value : "";
}

function normalizeFeatureDecisionReason(value) {
  if (typeof value !== "string") return "";
  return value
    .replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200e\u200f\u202a-\u202e\u2066-\u2069]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, FEATURE_DECISION_REASON_MAX_CHARS)
    .trimEnd();
}

// Accepts the structured {kind,reason} classifier payload and the legacy exact label.
// Every other payload fails closed so the popup stays unavailable.
function parseFeatureDecisionPayload(value) {
  if (typeof value !== "string" || !value || value.length > FEATURE_DECISION_PAYLOAD_MAX_CHARS) return null;
  const legacyKind = normalizeFeatureDecisionKind(value);
  if (legacyKind) return { kind: legacyKind, reason: "" };
  if (!value.startsWith("{")) return null;
  let parsed;
  try {
    parsed = JSON.parse(value);
  } catch {
    return null;
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return null;
  const keys = Object.keys(parsed);
  if (keys.length !== 2 || !keys.includes("kind") || !keys.includes("reason")) return null;
  if (typeof parsed.reason !== "string") return null;
  const kind = normalizeFeatureDecisionKind(parsed.kind);
  const reason = normalizeFeatureDecisionReason(parsed.reason);
  return kind && reason ? { kind, reason } : null;
}

function featureDecisionKindLabel(kind) {
  return kind === "feature_complex" ? "Complex feature" : "Lightweight feature";
}

function formatFeatureDecisionText(decision) {
  if (!decision) return "";
  const reason = decision.reason || `The classifier reported ${decision.kind} without a reason.`;
  return `Decision: ${featureDecisionKindLabel(decision.kind)} (${decision.kind})\nReason: ${reason}`;
}

function featureDecisionForTab(tabId) {
  const category = normalizeFeatureCategory(featureCategoryByTab.get(tabId));
  const decision = featureDecisionOutputByTab.get(tabId) || null;
  if (!decision || !normalizeFeatureDecisionKind(decision.kind)) return null;
  if (category === "lightweight-feature" && decision.kind === "feature_lightweight") return decision;
  if (category === "complex-feature" && decision.kind === "feature_complex") return decision;
  return null;
}

function featureDecisionOutputForTab(tabId) {
  return formatFeatureDecisionText(featureDecisionForTab(tabId));
}

function closeFeatureDecisionDialog({ restoreFocus = true } = {}) {
  const dialog = elements.featureDecisionDialog;
  if (!dialog?.open) {
    featureDecisionDialogTabId = null;
    if (elements.featureDecisionDialogOutput) elements.featureDecisionDialogOutput.textContent = "";
    return;
  }
  if (!restoreFocus) modalSurfaceState.delete(dialog);
  dialog.close();
}

function syncFeatureDecisionDialog() {
  const dialog = elements.featureDecisionDialog;
  if (!dialog?.open) return;
  const output = featureDecisionOutputForTab(featureDecisionDialogTabId);
  if (featureDecisionDialogTabId !== activeTabId || !output || elements.featureDecisionDialogOutput?.textContent !== output) {
    closeFeatureDecisionDialog({ restoreFocus: false });
  }
}

function openFeatureDecisionDialog() {
  const tabId = activeTabId;
  const output = featureDecisionOutputForTab(tabId);
  const dialog = elements.featureDecisionDialog;
  if (!tabId || !output || !dialog || !elements.featureDecisionDialogOutput) return;
  featureDecisionDialogTabId = tabId;
  elements.featureDecisionDialogOutput.textContent = output;
  if (!dialog.open) dialog.showModal();
  queueMicrotask(() => elements.featureDecisionDialogCloseButton?.focus({ preventScroll: true }));
}

function clearFeatureDecisionStateForTab(tabId, { render = false } = {}) {
  if (!tabId) return;
  featureCategoryByTab.delete(tabId);
  featureDecisionOutputByTab.delete(tabId);
  if (featureDecisionDialogTabId === tabId) closeFeatureDecisionDialog({ restoreFocus: false });
  if (render && tabId === activeTabId) renderFeatureCategoryTag(tabId);
}

function renderFeatureCategoryTag(tabId = activeTabId) {
  const tag = elements.featureCategoryTag;
  if (!tag) return;
  const enabled = isOptionalFeatureEnabled("featureSystemPrompt");
  const category = enabled ? normalizeFeatureCategory(featureCategoryByTab.get(tabId)) : "";
  const output = enabled ? featureDecisionOutputForTab(tabId) : "";
  tag.hidden = !category;
  tag.disabled = !output;
  tag.textContent = category;
  tag.setAttribute("aria-label", output ? `Show classifier decision and reason for ${category}` : category || "Feature category");
  tag.classList.toggle("lightweight-feature", category === "lightweight-feature");
  tag.classList.toggle("complex-feature", category === "complex-feature");
  syncFeatureDecisionDialog();
}

function handleFeatureDecisionOutputStatus(statusText, tabId = activeTabId) {
  if (!tabId) return;
  optionalFeatureAvailability.featureSystemPrompt = true;
  const decision = parseFeatureDecisionPayload(statusText);
  if (decision) featureDecisionOutputByTab.set(tabId, decision);
  else featureDecisionOutputByTab.delete(tabId);
  renderOptionalFeatureControls();
  if (tabId === activeTabId) renderFeatureCategoryTag(tabId);
  else if (featureDecisionDialogTabId === tabId) syncFeatureDecisionDialog();
}

function handleFeatureCategoryStatus(statusText, tabId = activeTabId) {
  if (!tabId) return;
  optionalFeatureAvailability.featureSystemPrompt = true;
  const category = normalizeFeatureCategory(statusText);
  if (category) featureCategoryByTab.set(tabId, category);
  else clearFeatureDecisionStateForTab(tabId);
  renderOptionalFeatureControls();
  if (tabId === activeTabId) renderFeatureCategoryTag(tabId);
  else if (featureDecisionDialogTabId === tabId) syncFeatureDecisionDialog();
}

function trackSkillUsage(tabId, skillName, kind = "used", source = "", details = {}) {
  const name = normalizeSkillName(skillName);
  if (!tabId || !name) return;
  const map = skillUsageMapForTab(tabId);
  if (!map) return;
  const now = Date.now();
  const entry = map.get(name) || { name, firstSeenAt: now, lastSeenAt: now, kinds: new Set(), sources: new Set(), paths: new Set() };
  entry.lastSeenAt = now;
  if (["used", "loaded", "read"].includes(kind)) entry.kinds.add(kind);
  else entry.kinds.add("used");
  if (source) entry.sources.add(source);
  if (details?.path) {
    entry.path = details.path;
    entry.paths ||= new Set();
    entry.paths.add(details.path);
  }
  map.set(name, entry);
  if (map.size > SKILL_USAGE_LIMIT_PER_TAB) {
    const keep = [...map.values()].sort((a, b) => b.lastSeenAt - a.lastSeenAt).slice(0, SKILL_USAGE_LIMIT_PER_TAB);
    map.clear();
    for (const item of keep) map.set(item.name, item);
  }
  persistSkillUsage();
  if (tabId === activeTabId) renderSessionSkillTags(tabId);
}

function trackSkillsFromText(tabId, text, { kind = "used", source = "" } = {}) {
  // Intentionally do not tag /skill:name mentions. A skill tag means the
  // agent read that skill's full SKILL.md context, not only its command/name.
}

function trackSkillsFromValue(tabId, value, { keyHint = "", kind = "used", source = "", depth = 0 } = {}) {
  if (!tabId || value === undefined || value === null || depth > 5) return 0;
  if (Array.isArray(value)) {
    return value.reduce((count, item) => count + trackSkillsFromValue(tabId, item, { keyHint, kind, source, depth: depth + 1 }), 0);
  }
  if (typeof value === "string") {
    const skillInfo = skillInfoFromPath(value);
    if (!skillInfo) return 0;
    trackSkillUsage(tabId, skillInfo.name, "read", source, { path: skillInfo.path });
    return 1;
  }
  if (typeof value !== "object") return 0;
  let tracked = 0;
  for (const [key, nested] of Object.entries(value)) {
    const hint = String(key || "").toLowerCase();
    tracked += trackSkillsFromValue(tabId, nested, { keyHint: hint, kind, source, depth: depth + 1 });
  }
  return tracked;
}

function trackSkillsFromToolInvocation(tabId, toolName, args, { sourcePrefix = "tool" } = {}) {
  if (!tabId) return false;
  const name = String(toolName || "").trim();
  if (name.toLowerCase() !== "read") return false;
  const source = `${sourcePrefix}:${name}`;
  return trackSkillsFromValue(tabId, args, { kind: "read", source }) > 0;
}

function trackSkillsFromMessage(tabId, message) {
  if (!tabId || !message) return;
  const role = String(message.role || "");
  if (role === "toolExecution" || role === "toolCall") {
    trackSkillsFromToolInvocation(tabId, message.toolName || message.name, message.arguments ?? message.args ?? {}, { sourcePrefix: `message:${role}` });
    return;
  }
  if (role === "user" || role === "assistant" || role === "assistantEvent" || role === "native") {
    trackSkillsFromText(tabId, textFromContent(message.content), { kind: "used", source: `message:${role}` });
    return;
  }
  if (role === "bashExecution") {
    trackSkillsFromText(tabId, `${message.command || ""}\n${message.output || ""}`, { kind: "used", source: "message:bash" });
  }
}

function trackSkillsFromMessages(messages = latestMessages, tabId = activeTabId) {
  for (const message of messages || []) trackSkillsFromMessage(tabId, message);
}

function assistantMessageUpdateType(event) {
  return event?.assistantMessageEvent?.type || "";
}

// Skill usage is recorded only at semantic tool boundaries. Argument/output
// delta cadence (`toolcall_*`, `tool_execution_update`) must never enter skill
// tracking: those raw fragments are transcript-owned stream content.
function eventMayAffectSkillUsage(event) {
  const type = event?.type || "";
  return ["tool_execution_start", "tool_execution_end"].includes(type)
    || (type === "response" && event.command === "new_session");
}

function beginToolBoundaryRun(event) {
  const tabId = event?.tabId || activeTabId || "";
  if (!tabId || event?.replayed === true) return;
  toolBoundaryRunEpochByTab.set(tabId, (toolBoundaryRunEpochByTab.get(tabId) || 0) + 1);
}

function toolBoundaryRunIdentity(event, tabId) {
  const explicit = String(event?.agentRunId || event?.turnId || "").trim();
  return explicit || `epoch-${toolBoundaryRunEpochByTab.get(tabId) || 0}`;
}

function toolBoundaryRecordKey(event, phase) {
  const tabId = event?.tabId || activeTabId || "";
  const toolCallId = String(event?.toolCallId || event?.id || "").trim();
  if (!toolCallId) return "";
  return `${tabId}:${toolBoundaryRunIdentity(event, tabId)}:${toolCallId}:${phase}`;
}

function rememberToolBoundaryRecordKey(key) {
  if (!key || recordedToolBoundaryKeys.has(key)) return false;
  recordedToolBoundaryKeys.add(key);
  while (recordedToolBoundaryKeys.size > TOOL_BOUNDARY_RECORD_LIMIT) {
    const oldest = recordedToolBoundaryKeys.values().next().value;
    if (oldest === undefined) break;
    recordedToolBoundaryKeys.delete(oldest);
  }
  return true;
}

// One record per tool boundary within an agent run. Redelivered or replayed
// boundaries must not duplicate skill tags or event-log lines.
function claimToolBoundaryRecord(event, phase) {
  const key = toolBoundaryRecordKey(event, phase);
  return key ? rememberToolBoundaryRecordKey(key) : true;
}

function trackSkillsFromEvent(event) {
  const tabId = event?.tabId || activeTabId;
  if (!tabId || !event) return;
  if (["tool_execution_start", "tool_execution_end"].includes(event.type)) {
    // Start is preferred, but unusable start args do not consume the claim;
    // completion may still provide the authoritative invocation arguments.
    const key = toolBoundaryRecordKey(event, "skills");
    if (key && recordedToolBoundaryKeys.has(key)) return;
    const args = event.args ?? event.arguments ?? event.invocation?.args;
    const tracked = trackSkillsFromToolInvocation(tabId, event.toolName, args, { sourcePrefix: `event:${event.type}` });
    if (tracked && key) rememberToolBoundaryRecordKey(key);
    return;
  }
  if (event.type === "response" && event.command === "new_session") {
    recordedToolBoundaryKeys.clear();
    toolBoundaryRunEpochByTab.delete(tabId);
    clearSkillUsageForTab(tabId);
  }
}

function skillPathForEntry(entry) {
  if (entry?.path) return entry.path;
  if (entry?.paths instanceof Set && entry.paths.size) {
    const paths = [...entry.paths];
    return paths[paths.length - 1] || "";
  }
  return "";
}

function skillEditorApiPath({ name = "", path = "" } = {}) {
  const params = new URLSearchParams();
  if (name) params.set("name", name);
  if (path) params.set("path", path);
  const query = params.toString();
  return query ? `/api/skill-file?${query}` : "/api/skill-file";
}

function setSkillEditorStatus(message = "", level = "muted") {
  const status = elements.skillEditorStatus;
  if (!status) return;
  status.textContent = message;
  status.className = `skill-editor-status ${level || "muted"}`;
  status.hidden = !message;
}

async function closeSkillEditor({ force = false } = {}) {
  if (!force && activeSkillEditor?.dirty && elements.skillEditorDialog?.open) {
    if (!(await confirmDiscardEdits({ what: "unsaved skill edits", target: activeSkillEditor.path || activeSkillEditor.name || "SKILL.md" }))) return;
    activeSkillEditor.dirty = false;
  }
  if (elements.skillEditorDialog?.open) elements.skillEditorDialog.close();
  else activeSkillEditor = null;
}

function updateSkillEditorMeta(data = activeSkillEditor || {}) {
  if (!elements.skillEditorMeta) return;
  const parts = [data.name ? `Skill: ${data.name}` : "Skill", data.path || "path unavailable"].filter(Boolean);
  elements.skillEditorMeta.textContent = parts.join(" · ");
}

async function openSkillEditor(entry) {
  const name = normalizeSkillName(entry?.name || "");
  const path = skillPathForEntry(entry);
  if (!name || !elements.skillEditorDialog || !elements.skillEditorText) return;
  const tabId = activeTabId;
  activeSkillEditor = { name, path, tabId, mtimeMs: null };
  if (elements.skillEditorTitle) elements.skillEditorTitle.textContent = `Edit skill: ${name}`;
  if (elements.skillEditorText) elements.skillEditorText.value = "";
  if (elements.skillEditorSaveButton) elements.skillEditorSaveButton.disabled = true;
  updateSkillEditorMeta(activeSkillEditor);
  setSkillEditorStatus("Loading skill context…", "muted");
  if (!elements.skillEditorDialog.open) elements.skillEditorDialog.showModal();

  try {
    const response = await api(skillEditorApiPath({ name, path }), { tabId });
    if (activeSkillEditor?.tabId !== tabId || activeSkillEditor?.name !== name) return;
    const data = response.data || {};
    activeSkillEditor = { name: normalizeSkillName(data.name || name), path: data.path || path, tabId, mtimeMs: data.mtimeMs };
    if (elements.skillEditorTitle) elements.skillEditorTitle.textContent = `Edit skill: ${activeSkillEditor.name}`;
    if (elements.skillEditorText) elements.skillEditorText.value = data.content || "";
    if (elements.skillEditorSaveButton) elements.skillEditorSaveButton.disabled = false;
    updateSkillEditorMeta(activeSkillEditor);
    setSkillEditorStatus("Edit this SKILL.md, then save. Reload the tab if title/description metadata should refresh immediately.", "muted");
    queueMicrotask(() => elements.skillEditorText?.focus());
  } catch (error) {
    if (elements.skillEditorSaveButton) elements.skillEditorSaveButton.disabled = true;
    setSkillEditorStatus(`Failed to open skill: ${error.message || String(error)}`, "error");
  }
}

async function saveSkillEditor() {
  if (!activeSkillEditor || !elements.skillEditorText || !elements.skillEditorSaveButton) return;
  const editor = activeSkillEditor;
  const previousLabel = elements.skillEditorSaveButton.textContent;
  elements.skillEditorSaveButton.disabled = true;
  elements.skillEditorSaveButton.textContent = "Saving…";
  setSkillEditorStatus("Saving skill…", "muted");
  try {
    const response = await api("/api/skill-file", {
      method: "POST",
      tabId: editor.tabId,
      body: {
        name: editor.name,
        path: editor.path,
        mtimeMs: editor.mtimeMs,
        content: elements.skillEditorText.value,
      },
    });
    const data = response.data || {};
    const savedName = normalizeSkillName(data.name || editor.name);
    activeSkillEditor = { name: savedName, path: data.path || editor.path, tabId: editor.tabId, mtimeMs: data.mtimeMs };
    const map = skillUsageMapForTab(editor.tabId, { create: false });
    if (map && savedName !== editor.name) map.delete(editor.name);
    trackSkillUsage(editor.tabId, savedName, "read", "skill-editor", { path: activeSkillEditor.path });
    if (elements.skillEditorTitle) elements.skillEditorTitle.textContent = `Edit skill: ${savedName}`;
    updateSkillEditorMeta(activeSkillEditor);
    setSkillEditorStatus("Saved SKILL.md. Reload/restart affected tabs before relying on updated skill metadata or newly loaded instructions.", "ok");
  } catch (error) {
    setSkillEditorStatus(`Failed to save skill: ${error.message || String(error)}`, "error");
  } finally {
    elements.skillEditorSaveButton.textContent = previousLabel || "Save skill";
    elements.skillEditorSaveButton.disabled = false;
  }
}

function renderBusyPromptBehaviorTag() {
  const tag = elements.busyPromptBehaviorTag;
  if (!tag) return;
  const behavior = normalizeBusyPromptBehavior(busyPromptBehavior);
  const label = BUSY_PROMPT_BEHAVIOR_LABELS[behavior] || BUSY_PROMPT_BEHAVIOR_LABELS.followUp;
  tag.textContent = label;
  tag.classList.toggle("follow-up", behavior === "followUp");
  tag.classList.toggle("steer", behavior === "steer");
  tag.title = behavior === "steer"
    ? "While Pi is running, normal prompt submit steers the active run. Click to change."
    : "While Pi is running, normal prompt submit queues a follow-up. Click to change.";
  tag.setAttribute("aria-label", tag.title);
  renderBusyPromptBehaviorMenu();
  renderSessionSkillTags(activeTabId);
}

function setBusyPromptBehaviorMenuOpen(open, { focusCurrent = false } = {}) {
  if (open && followUpQueueOpen) setFollowUpQueueOpen(false);
  busyPromptBehaviorMenuOpen = !!open;
  elements.busyPromptBehaviorTag?.setAttribute("aria-expanded", busyPromptBehaviorMenuOpen ? "true" : "false");
  elements.busyPromptBehaviorTag?.classList.toggle("menu-open", busyPromptBehaviorMenuOpen);
  if (elements.busyPromptBehaviorMenu) elements.busyPromptBehaviorMenu.hidden = !busyPromptBehaviorMenuOpen;
  if (!busyPromptBehaviorMenuOpen) {
    scheduleDeferredUiFlushAfterDropdownClose();
    return;
  }
  renderBusyPromptBehaviorMenu();
  if (focusCurrent) {
    requestAnimationFrame(() => {
      const current = busyPromptBehaviorMenuItems().find((item) => item.getAttribute("aria-checked") === "true") || busyPromptBehaviorMenuItems()[0];
      current?.focus({ preventScroll: true });
    });
  }
}

function focusBusyPromptBehaviorMenuItem(direction = 1) {
  const items = busyPromptBehaviorMenuItems();
  if (!items.length) return;
  const currentIndex = Math.max(0, items.indexOf(document.activeElement));
  const nextIndex = (currentIndex + direction + items.length) % items.length;
  items[nextIndex].focus({ preventScroll: true });
}

function chooseBusyPromptBehaviorFromMenu(value) {
  setBusyPromptBehavior(value);
  setBusyPromptBehaviorMenuOpen(false);
  focusPromptInput({ defer: true });
}

function setBusyPromptBehavior(value, { persist = true } = {}) {
  const next = normalizeBusyPromptBehavior(value);
  busyPromptBehavior = next;
  webuiSettings = { ...webuiSettings, busyPromptBehavior: next };
  if (persist) persistBusyPromptBehavior(next);
  renderBusyPromptBehaviorTag();
}

function restoreBusyPromptBehaviorSetting() {
  setBusyPromptBehavior(readStoredBusyPromptBehavior(), { persist: false });
}

function clampAutocompleteMaxVisible(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 12;
  return Math.max(3, Math.min(20, Math.floor(number)));
}

function applyNativeSettingsForBrowser(settings = {}, { syncThinkingVisibility = false } = {}) {
  if (!settings || typeof settings !== "object") return;
  webuiSettings = { ...webuiSettings, ...settings, warnings: { ...(webuiSettings.warnings || {}), ...(settings.warnings || {}) } };
  if (settings.autocompleteMaxVisible !== undefined) autocompleteMaxVisible = clampAutocompleteMaxVisible(settings.autocompleteMaxVisible);
  if (SETTINGS_DOUBLE_ESCAPE_OPTIONS.some((option) => option.value === settings.doubleEscapeAction)) doubleEscapeAction = settings.doubleEscapeAction;
  if (SETTINGS_TREE_FILTER_OPTIONS.includes(settings.treeFilterMode)) treeFilterMode = settings.treeFilterMode;
  if (BUSY_PROMPT_BEHAVIOR_VALUES.has(settings.busyPromptBehavior)) setBusyPromptBehavior(settings.busyPromptBehavior);
  if (syncThinkingVisibility && typeof settings.hideThinkingBlock === "boolean") setThinkingOutputVisible(!settings.hideThinkingBlock);
}

async function refreshNativeSettings(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const response = await api("/api/settings", { tabId: tabContext.tabId });
  if (!isCurrentTabContext(tabContext)) return;
  applyNativeSettingsForBrowser(response.data?.settings || {});
}

function mobileComposerSecondaryNodes() {
  return [
    elements.workflowModeControls,
    elements.composerContextTags,
    elements.busyPromptBehaviorMenu,
    elements.followUpQueueTrigger,
    elements.btwButton,
    elements.conversationVoiceMenu,
    elements.conversationModeEndButton,
  ].filter(Boolean);
}

function rememberMobileComposerOriginalPositions() {
  for (const node of mobileComposerSecondaryNodes()) {
    if (!mobileComposerOriginalPositions.has(node)) {
      mobileComposerOriginalPositions.set(node, { parent: node.parentNode, nextSibling: node.nextSibling });
    }
  }
}

function restoreMobileComposerOriginalPositions() {
  for (const [node, { parent, nextSibling }] of mobileComposerOriginalPositions) {
    if (!parent) continue;
    if (nextSibling?.parentNode === parent) parent.insertBefore(node, nextSibling);
    else parent.append(node);
  }
}

function syncMobileComposerDisclosureLayout() {
  rememberMobileComposerOriginalPositions();
  const useMobileDisclosure = isMobileView() && !isMobileShellV2Active();
  document.body.classList.toggle("mobile-composer-disclosure", useMobileDisclosure);
  if (!useMobileDisclosure) {
    restoreMobileComposerOriginalPositions();
    return;
  }
  for (const node of mobileComposerSecondaryNodes()) elements.composerActionsPanel.append(node);
}

function setComposerActionsOpen(open, { restoreFocus = false } = {}) {
  if (isMobileShellV2Active()) return;
  syncMobileComposerDisclosureLayout();
  const shouldOpen = open && isMobileView();
  if (shouldOpen) {
    composerActionsFocusReturn = document.activeElement instanceof HTMLElement ? document.activeElement : elements.composerActionsButton;
    if (followUpQueueOpen) setFollowUpQueueOpen(false);
    setMobileTabsExpanded(false);
    setMobileFooterExpanded(false);
  }
  document.body.classList.toggle("composer-actions-open", shouldOpen);
  elements.composerActionsButton.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
  elements.composerActionsButton.textContent = shouldOpen ? "−" : "More";
  elements.composerActionsButton.setAttribute("aria-label", shouldOpen ? "Minimize more composer actions" : "Show more composer actions");
  elements.composerActionsButton.title = shouldOpen ? "Minimize more composer actions" : "Show more composer actions";
  elements.composerActionsPanel.setAttribute("aria-hidden", shouldOpen || !isMobileView() ? "false" : "true");
  if (!shouldOpen) {
    setPublishMenuOpen(false);
    setNativeCommandMenuOpen(false);
    setAppRunnerMenuOpen(false);
    setOptionsMenuOpen(false);
    setBusyPromptBehaviorMenuOpen(false);
    const focusReturn = restoreFocus ? composerActionsFocusReturn : null;
    composerActionsFocusReturn = null;
    if (focusReturn?.isConnected) requestAnimationFrame(() => focusReturn.focus({ preventScroll: true }));
  }
  scheduleMobileDropdownScrollBoundsUpdate();
  if (!shouldOpen) scheduleDeferredUiFlushAfterDropdownClose();
}

function isUserBashActive(tabId = activeTabId) {
  return !!tabId && userBashByTab.has(tabId);
}

function userBashQueueForTab(tabId) {
  if (!tabId) return [];
  let queue = userBashQueuesByTab.get(tabId);
  if (!queue) {
    queue = [];
    userBashQueuesByTab.set(tabId, queue);
  }
  return queue;
}

function queuedUserBashCount(tabId = activeTabId) {
  return tabId ? userBashQueueForTab(tabId).length : 0;
}

function isUserBashRunningOrQueued(tabId = activeTabId) {
  return isUserBashActive(tabId) || queuedUserBashCount(tabId) > 0;
}

function isRunActive() {
  return !!currentState?.isStreaming || !!currentState?.isCompacting || isUserBashRunningOrQueued() || runIndicatorLocallyActive;
}

function isAbortAvailable() {
  return runIndicatorIsActive() || isUserBashActive();
}

function resizePromptInput() {
  const input = elements.promptInput;
  input.style.height = "auto";
  const style = getComputedStyle(input);
  const maxHeight = Number.parseFloat(style.maxHeight);
  const borderBlock = Number.parseFloat(style.borderTopWidth) + Number.parseFloat(style.borderBottomWidth);
  const naturalHeight = input.scrollHeight + borderBlock;
  const isCapped = Number.isFinite(maxHeight) && naturalHeight > Math.ceil(maxHeight);
  input.style.height = `${Math.ceil(isCapped ? maxHeight : naturalHeight)}px`;
  input.style.overflowY = isCapped ? "auto" : "hidden";
}

function updateComposerModeButtons() {
  const runActive = isRunActive();
  const abortAvailable = isAbortAvailable();
  const abortHoldSnapshot = isAbortLongPressActive();
  const nextSignature = [
    activeTabGeneration,
    runActive ? "run" : "idle",
    abortAvailable ? "abort" : "no-abort",
    abortHoldSnapshot ? `hold:${abortLongPressLabel()}` : "no-hold",
    abortRequestInFlight ? "aborting" : "ready",
    busyPromptBehavior,
  ].join("|");
  if (nextSignature === composerModeRenderSignature) return;
  composerModeRenderSignature = nextSignature;

  const target = runActive ? elements.composerRow : elements.composerActionsPanel;
  const before = runActive ? elements.abortButton : null;
  for (const button of [elements.steerButton, elements.followUpButton]) {
    if (button.parentElement !== target) target.insertBefore(button, before);
    button.hidden = !runActive;
    button.disabled = !runActive;
  }
  const abortHoldActive = isAbortLongPressActive();
  if (!abortAvailable && !abortHoldActive) resetAbortLongPressAffordance();
  elements.abortButton.hidden = !abortAvailable && !abortHoldActive;
  elements.abortButton.disabled = (!abortAvailable && !abortHoldActive) || abortRequestInFlight;
  if (abortHoldActive) {
    renderAbortLongPressAffordance();
  } else {
    const abortText = abortRequestInFlight ? "Aborting…" : "Abort";
    const abortTitle = abortAvailable ? abortButtonReadyTitle() : "Abort is available while Pi is running";
    if (elements.abortButton.textContent !== abortText) elements.abortButton.textContent = abortText;
    if (elements.abortButton.title !== abortTitle) elements.abortButton.title = abortTitle;
    if (elements.abortButton.getAttribute("aria-label") !== abortTitle) elements.abortButton.setAttribute("aria-label", abortTitle);
  }
  renderBusyPromptBehaviorTag();
  renderSendButtonMode(runActive);
  document.body.classList.toggle("pi-run-active", runActive || abortAvailable);
  scheduleComposerActionSlotLayoutRestore();
}

// While Pi is running, Send does not start a new turn: it queues a follow-up or steers the active
// run (per the busy-behavior tag). Say so on the button instead of silently acting differently.
function renderSendButtonMode(runActive = isRunActive()) {
  const button = elements.sendButton;
  if (!button) return;
  const behavior = normalizeBusyPromptBehavior(busyPromptBehavior);
  const label = !runActive ? "Send" : behavior === "steer" ? "Steer" : "Queue";
  const title = !runActive
    ? "Send prompt — Shift+F10 opens visibility options"
    : behavior === "steer"
      ? "Pi is running: Enter steers the active run with this text. Change the behavior via the tag above the prompt."
      : "Pi is running: Enter queues this text as a follow-up. Change the behavior via the tag above the prompt.";
  if (button.textContent !== label) button.textContent = label;
  if (button.title !== title) button.title = title;
  button.setAttribute("aria-label", runActive ? `${label} (Send while Pi is running)` : "Send");
  button.classList.toggle("send-busy-mode", runActive);
}

function scheduleComposerModeButtonsUpdate() {
  if (composerModeButtonsFrame !== null) return;
  const flush = () => {
    composerModeButtonsFrame = null;
    updateComposerModeButtons();
  };
  if (typeof requestAnimationFrame === "function") composerModeButtonsFrame = requestAnimationFrame(flush);
  else composerModeButtonsFrame = setTimeout(flush, 0);
}

function isFooterPickerOpen() {
  return footerModelPickerOpen || footerThinkingPickerOpen || footerBranchPickerOpen;
}

function footerActivePickerTarget() {
  if (footerBranchPickerOpen) return elements.statusBar.querySelector(".footer-branch.footer-meta-action");
  if (footerThinkingPickerOpen) return elements.statusBar.querySelector(".footer-thinking.footer-meta-action");
  if (footerModelPickerOpen) return elements.statusBar.querySelector(".footer-model.footer-meta-action, .footer-tui-model");
  return null;
}

function clearFooterPickerPosition() {
  document.documentElement.style.removeProperty("--footer-model-picker-bottom");
  document.documentElement.style.removeProperty("--footer-model-picker-left");
  document.documentElement.style.removeProperty("--footer-model-picker-right");
}

function updateFooterModelPickerPosition() {
  if (isMobileShellV2Active()) {
    clearFooterPickerPosition();
    return;
  }
  if (!isFooterPickerOpen()) {
    clearFooterPickerPosition();
    return;
  }
  if (isMobileView()) {
    document.documentElement.style.removeProperty("--footer-model-picker-left");
    document.documentElement.style.removeProperty("--footer-model-picker-right");
    const viewportHeight = window.innerHeight || window.visualViewport?.height || document.documentElement.clientHeight;
    const statusTop = elements.statusBar.getBoundingClientRect().top;
    const bottom = Math.max(8, Math.round(viewportHeight - statusTop + 6));
    document.documentElement.style.setProperty("--footer-model-picker-bottom", `${bottom}px`);
    return;
  }
  document.documentElement.style.removeProperty("--footer-model-picker-bottom");
  const picker = elements.statusBar.querySelector(".footer-model-picker");
  const target = footerActivePickerTarget();
  if (!picker || !target) {
    document.documentElement.style.removeProperty("--footer-model-picker-left");
    document.documentElement.style.removeProperty("--footer-model-picker-right");
    return;
  }
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth;
  const statusRect = elements.statusBar.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const pickerWidth = picker.offsetWidth || Math.min(544, viewportWidth - 16);
  const minLeft = 8 - statusRect.left;
  const maxLeft = Math.max(minLeft, viewportWidth - pickerWidth - 8 - statusRect.left);
  const targetCenterLeft = targetRect.left - statusRect.left + (targetRect.width / 2) - (pickerWidth / 2);
  const left = Math.min(maxLeft, Math.max(minLeft, targetCenterLeft));
  document.documentElement.style.setProperty("--footer-model-picker-left", `${Math.round(left)}px`);
  document.documentElement.style.setProperty("--footer-model-picker-right", "auto");
}

function setMobileFooterExpanded(expanded, { restoreFocus = false } = {}) {
  if (isMobileShellV2Active()) return;
  mobileFooterExpanded = expanded && isMobileView();
  if (mobileFooterExpanded) {
    setComposerActionsOpen(false);
    setMobileTabsExpanded(false);
    if (isFooterPickerOpen()) {
      footerModelPickerOpen = false;
      footerThinkingPickerOpen = false;
      footerBranchPickerOpen = false;
      document.body.classList.remove("footer-model-picker-open");
      elements.statusBar.querySelectorAll(".footer-model-picker").forEach((node) => node.remove());
    }
  }
  document.body.classList.toggle("footer-details-expanded", mobileFooterExpanded);
  const button = elements.statusBar.querySelector(".footer-details-toggle");
  if (button) {
    button.textContent = mobileFooterExpanded ? "−" : "Details";
    button.setAttribute("aria-label", mobileFooterExpanded ? "Minimize Git footer details" : "Show Git footer details");
    button.setAttribute("title", mobileFooterExpanded ? "Minimize Git footer details" : "Show Git footer details");
    button.setAttribute("aria-expanded", mobileFooterExpanded ? "true" : "false");
  }
  if (mobileFooterExpanded && button) {
    elements.statusBar.setAttribute("aria-label", "Git footer details");
    activateDrawerModal(elements.statusBar, button, {
      close: () => setMobileFooterExpanded(false, { restoreFocus: true }),
    });
  } else {
    elements.statusBar.removeAttribute("aria-label");
    deactivateDrawerModal(elements.statusBar, { restoreFocus });
  }
  updateFooterModelPickerPosition();
}

function setMobileTabsExpanded(expanded, { restoreFocus = false } = {}) {
  if (isMobileShellV2Active()) return;
  const shouldExpand = expanded && isMobileView();
  if (shouldExpand) {
    mobileTabsFocusReturn = elements.terminalTabsToggleButton;
    setComposerActionsOpen(false);
    setMobileFooterExpanded(false);
  }
  mobileTabsExpanded = shouldExpand;
  document.body.classList.toggle("mobile-tabs-expanded", mobileTabsExpanded);
  elements.terminalTabsToggleButton.setAttribute("aria-expanded", mobileTabsExpanded ? "true" : "false");
  if (mobileTabsExpanded) {
    activateDrawerModal(elements.terminalTabsShell, elements.terminalTabsToggleButton, {
      close: () => {
        setNewTabMenuOpen(false);
        setMobileTabsExpanded(false, { restoreFocus: true });
      },
    });
  } else {
    deactivateDrawerModal(elements.terminalTabsShell, { restoreFocus: false });
  }
  if (elements.terminalTabsBackdrop) elements.terminalTabsBackdrop.hidden = !mobileTabsExpanded;
  if (elements.terminalTabsDrawerContent) {
    if (isMobileView()) elements.terminalTabsDrawerContent.setAttribute("aria-hidden", mobileTabsExpanded ? "false" : "true");
    else elements.terminalTabsDrawerContent.removeAttribute("aria-hidden");
  }
  if (!mobileTabsExpanded) {
    const focusReturn = restoreFocus ? mobileTabsFocusReturn : null;
    mobileTabsFocusReturn = null;
    if (focusReturn?.isConnected) requestAnimationFrame(() => focusReturn.focus({ preventScroll: true }));
  }
}

function modalFocusableElements(surface) {
  if (!surface) return [];
  return [...surface.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')]
    .filter((node) => !node.hidden && node.getAttribute("aria-hidden") !== "true" && node.getClientRects().length > 0);
}

function installDialogModalPrimitive(dialog) {
  if (!dialog || dialog.dataset.modalPrimitive === "true") return;
  dialog.dataset.modalPrimitive = "true";
  const showModal = dialog.showModal.bind(dialog);
  dialog.showModal = () => {
    modalSurfaceState.set(dialog, { trigger: document.activeElement instanceof HTMLElement ? document.activeElement : null });
    showModal();
  };
  dialog.addEventListener("close", () => {
    const trigger = modalSurfaceState.get(dialog)?.trigger;
    modalSurfaceState.delete(dialog);
    const openModal = document.querySelector("dialog:modal");
    if (trigger?.isConnected && (!openModal || trigger.closest("dialog:modal"))) queueMicrotask(() => trigger.focus({ preventScroll: true }));
  });
}

function installModalPrimitives() {
  document.querySelectorAll("dialog").forEach(installDialogModalPrimitive);
}

function dismissUndoToast() {
  clearTimeout(undoToastTimer);
  undoToastTimer = null;
  activeUndoAction = null;
  if (!elements.undoToast) return;
  const returnFocus = elements.undoToast.contains(document.activeElement) ? undoToastFocusReturn : null;
  undoToastFocusReturn = null;
  elements.undoToast.hidden = true;
  elements.undoToast.classList.remove("expiring", "undoing", "error");
  elements.undoToastButton.disabled = false;
  if (returnFocus?.isConnected) queueMicrotask(() => returnFocus.focus({ preventScroll: true }));
}

function settleUndoToast(message, { error = false, timeoutMs = 3500 } = {}) {
  if (!elements.undoToast) return;
  clearTimeout(undoToastTimer);
  undoToastTimer = null;
  activeUndoAction = null;
  elements.undoToast.hidden = false;
  elements.undoToast.classList.remove("undoing");
  elements.undoToast.classList.toggle("error", error);
  const hadFocus = elements.undoToast.contains(document.activeElement);
  elements.undoToastMessage.textContent = message;
  elements.undoToastTime.hidden = true;
  elements.undoToastButton.hidden = true;
  if (hadFocus) elements.undoToastDismissButton.focus({ preventScroll: true });
  undoToastTimer = setTimeout(dismissUndoToast, timeoutMs);
}

function offerUndo({ message, undo, successMessage = "Action undone.", timeoutMs = 10000 } = {}) {
  if (!message || typeof undo !== "function" || !elements.undoToast) return;
  dismissUndoToast();
  undoToastFocusReturn = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  activeUndoAction = { undo, successMessage };
  elements.undoToastMessage.textContent = message;
  elements.undoToastTime.textContent = `Undo available for ${Math.round(timeoutMs / 1000)} seconds`;
  elements.undoToastTime.hidden = false;
  elements.undoToastButton.hidden = false;
  elements.undoToastButton.disabled = false;
  elements.undoToast.hidden = false;
  elements.undoToast.style.setProperty("--undo-timeout", `${timeoutMs}ms`);
  elements.undoToast.classList.remove("expiring", "error", "undoing");
  void elements.undoToast.offsetWidth;
  elements.undoToast.classList.add("expiring");
  undoToastTimer = setTimeout(dismissUndoToast, timeoutMs);
}

async function runOfferedUndo() {
  const pending = activeUndoAction;
  if (!pending || !elements.undoToast) return;
  clearTimeout(undoToastTimer);
  undoToastTimer = null;
  activeUndoAction = null;
  elements.undoToast.classList.remove("expiring");
  elements.undoToast.classList.add("undoing");
  elements.undoToastMessage.textContent = "Undoing…";
  elements.undoToastTime.hidden = true;
  elements.undoToastButton.disabled = true;
  try {
    await pending.undo();
    settleUndoToast(pending.successMessage);
    addEvent(pending.successMessage, "success");
  } catch (error) {
    const message = `Could not undo: ${error.message || String(error)}`;
    settleUndoToast(message, { error: true, timeoutMs: 7000 });
    addEvent(message, "error");
  }
}

function finishApplicationConfirmation(confirmed) {
  const resolve = activeConfirmationResolve;
  activeConfirmationResolve = null;
  if (elements.confirmationDialog?.open) elements.confirmationDialog.close();
  resolve?.(!!confirmed);
}

function appConfirm({ title = "Confirm action", summary = "Continue?", affected = "The selected item", undoable = false, confirmLabel = "Continue", danger = true } = {}) {
  if (!elements.confirmationDialog?.showModal) {
    return Promise.resolve(window.confirm([title, summary, affected, undoable ? "This can be undone." : "This cannot be undone."].filter(Boolean).join("\n\n")));
  }
  if (activeConfirmationResolve) finishApplicationConfirmation(false);
  elements.confirmationTitle.textContent = title;
  elements.confirmationSummary.textContent = summary;
  elements.confirmationAffected.textContent = affected;
  elements.confirmationUndo.textContent = undoable ? "This action can be undone." : "This action cannot be undone.";
  elements.confirmationConfirmButton.textContent = confirmLabel;
  elements.confirmationConfirmButton.classList.toggle("danger", danger);
  elements.confirmationConfirmButton.classList.toggle("primary", !danger);
  return new Promise((resolve) => {
    activeConfirmationResolve = resolve;
    elements.confirmationDialog.showModal();
    queueMicrotask(() => elements.confirmationCancelButton?.focus());
  });
}

// Ask before an action would throw away unsaved edits. Resolves true when it is fine to proceed.
function confirmDiscardEdits({ what = "unsaved edits", target = "" } = {}) {
  return appConfirm({
    title: `Discard ${what}?`,
    summary: target ? `${target} has changes that have not been saved.` : "There are changes that have not been saved.",
    affected: target || "The current editor contents",
    undoable: false,
    confirmLabel: "Discard changes",
  });
}

// Application value prompt (replaces blocking window.prompt): resolves with the entered value,
// or null when cancelled. Text prompts may validate and keep the dialog open.
let activeTextPromptResolve = null;
let textPromptMode = "text";

function appPromptText({ title = "Enter a value", summary = "", defaultValue = "", placeholder = "", confirmLabel = "OK", validate = null, selectRange = null } = {}) {
  const dialog = elements.textPromptDialog;
  if (!dialog?.showModal) {
    const value = window.prompt([title, summary].filter(Boolean).join("\n\n"), defaultValue);
    return Promise.resolve(value === null ? null : String(value));
  }
  if (activeTextPromptResolve) finishTextPrompt(null);
  textPromptMode = "text";
  elements.textPromptTitle.textContent = title;
  elements.textPromptSummary.textContent = summary;
  elements.textPromptSummary.hidden = !summary;
  elements.textPromptInput.hidden = false;
  elements.textPromptInput.value = defaultValue;
  elements.textPromptInput.placeholder = placeholder;
  if (elements.textPromptSelect) elements.textPromptSelect.hidden = true;
  elements.textPromptError.hidden = true;
  elements.textPromptError.textContent = "";
  elements.textPromptConfirmButton.textContent = confirmLabel;
  dialog.dataset.validate = validate ? "1" : "";
  textPromptValidator = typeof validate === "function" ? validate : null;
  return new Promise((resolve) => {
    activeTextPromptResolve = resolve;
    dialog.showModal();
    queueMicrotask(() => {
      const input = elements.textPromptInput;
      input.focus();
      if (Array.isArray(selectRange)) input.setSelectionRange(selectRange[0], selectRange[1]);
      else input.select();
    });
  });
}

function appPromptSelect({ title = "Choose an option", summary = "", options = [], placeholder = "Choose…", confirmLabel = "Continue" } = {}) {
  const normalizedOptions = options
    .map((option) => ({ value: String(option?.value ?? ""), label: String(option?.label ?? option?.value ?? "") }))
    .filter((option) => option.value && option.label);
  const dialog = elements.textPromptDialog;
  if (!dialog?.showModal || !elements.textPromptSelect) {
    const lines = normalizedOptions.map((option, index) => `${index + 1}. ${option.label}`);
    const choice = window.prompt([title, summary, ...lines].filter(Boolean).join("\n"), "");
    if (choice === null) return Promise.resolve(null);
    const selected = normalizedOptions[Number.parseInt(String(choice), 10) - 1];
    return Promise.resolve(selected?.value || null);
  }
  if (activeTextPromptResolve) finishTextPrompt(null);
  textPromptMode = "select";
  elements.textPromptTitle.textContent = title;
  elements.textPromptSummary.textContent = summary;
  elements.textPromptSummary.hidden = !summary;
  elements.textPromptInput.hidden = true;
  const select = elements.textPromptSelect;
  select.hidden = false;
  select.replaceChildren();
  const placeholderOption = document.createElement("option");
  placeholderOption.value = "";
  placeholderOption.textContent = placeholder;
  placeholderOption.disabled = true;
  placeholderOption.selected = true;
  select.append(placeholderOption);
  for (const option of normalizedOptions) {
    const element = document.createElement("option");
    element.value = option.value;
    element.textContent = option.label;
    select.append(element);
  }
  select.value = "";
  elements.textPromptError.hidden = true;
  elements.textPromptError.textContent = "";
  elements.textPromptConfirmButton.textContent = confirmLabel;
  textPromptValidator = (value) => value ? "" : "Choose an option.";
  return new Promise((resolve) => {
    activeTextPromptResolve = resolve;
    dialog.showModal();
    queueMicrotask(() => select.focus());
  });
}

let textPromptValidator = null;

function finishTextPrompt(value) {
  const resolve = activeTextPromptResolve;
  activeTextPromptResolve = null;
  textPromptValidator = null;
  if (elements.textPromptDialog?.open) elements.textPromptDialog.close();
  resolve?.(value);
}

function submitTextPrompt() {
  const control = textPromptMode === "select" ? elements.textPromptSelect : elements.textPromptInput;
  const value = String(control?.value ?? "");
  const problem = textPromptValidator ? textPromptValidator(value) : "";
  if (problem) {
    elements.textPromptError.textContent = String(problem);
    elements.textPromptError.hidden = false;
    control?.focus();
    return;
  }
  finishTextPrompt(value);
}

function appConfirmText(message, options = {}) {
  const text = String(message || "Continue?").trim();
  const [firstLine, ...rest] = text.split("\n");
  return appConfirm({
    title: options.title || firstLine || "Confirm action",
    summary: options.summary || rest.join("\n").trim() || firstLine || "Continue?",
    affected: options.affected || "The current workspace, session, or server state described above",
    undoable: options.undoable === true,
    confirmLabel: options.confirmLabel || "Continue",
    danger: options.danger !== false,
  });
}

function finishGitWorktreeBaseChoice(baseRef = null) {
  const resolve = activeGitWorktreeBaseResolve;
  activeGitWorktreeBaseResolve = null;
  if (elements.gitWorktreeBaseDialog?.open) elements.gitWorktreeBaseDialog.close();
  resolve?.(baseRef);
}

function chooseGitWorktreeBase(branch) {
  const branchName = cleanStatusText(branch) || "the new branch";
  if (!elements.gitWorktreeBaseDialog?.showModal) {
    const choice = window.prompt(`Create ${branchName} from:\n1. origin/main (default)\n2. Current workspace HEAD\n\nEnter 1 or 2. Cancel to abort.`, "1");
    if (choice === null) return Promise.resolve(null);
    return Promise.resolve(String(choice).trim() === "2" ? "HEAD" : "origin/main");
  }
  if (activeGitWorktreeBaseResolve) finishGitWorktreeBaseChoice(null);
  elements.gitWorktreeBaseBranch.textContent = branchName;
  elements.gitWorktreeBaseOriginMain.checked = true;
  elements.gitWorktreeBaseCurrentHead.checked = false;
  return new Promise((resolve) => {
    activeGitWorktreeBaseResolve = resolve;
    elements.gitWorktreeBaseDialog.showModal();
    queueMicrotask(() => elements.gitWorktreeBaseOriginMain?.focus());
  });
}

function handleDrawerModalKeydown(event) {
  if (!activeDrawerModal || event.defaultPrevented) return;
  if (event.key === "Escape") {
    if (activeDrawerModal.surface === elements.terminalTabsShell && openTerminalTabGroupKey) {
      event.preventDefault();
      event.stopPropagation();
      const openGroup = [...elements.tabBar.querySelectorAll(".terminal-tab-group")]
        .find((group) => group.dataset.groupKey === openTerminalTabGroupKey);
      clearOpenTerminalTabGroup(openTerminalTabGroupKey, { force: true });
      openGroup?.querySelector(".terminal-tab-group-button")?.focus({ preventScroll: true });
      return;
    }
    event.preventDefault();
    activeDrawerModal.close?.();
    return;
  }
  if (event.key !== "Tab") return;
  const focusable = modalFocusableElements(activeDrawerModal.surface);
  if (!focusable.length) {
    event.preventDefault();
    activeDrawerModal.surface.focus({ preventScroll: true });
    return;
  }
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (!activeDrawerModal.surface.contains(document.activeElement)) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus({ preventScroll: true });
  } else if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus({ preventScroll: true });
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus({ preventScroll: true });
  }
}

function activateDrawerModal(surface, trigger, { close } = {}) {
  if (activeDrawerModal?.surface === surface) {
    activeDrawerModal.trigger = trigger;
    activeDrawerModal.close = close;
    return;
  }
  activeDrawerModal = {
    surface,
    trigger,
    close,
    previousRole: surface.getAttribute("role"),
    previousTabindex: surface.getAttribute("tabindex"),
  };
  surface.setAttribute("role", "dialog");
  surface.setAttribute("aria-modal", "true");
  surface.setAttribute("tabindex", "-1");
  document.addEventListener("keydown", handleDrawerModalKeydown, true);
}

function deactivateDrawerModal(surface, { restoreFocus = true } = {}) {
  if (activeDrawerModal?.surface !== surface) {
    surface?.removeAttribute("aria-modal");
    return;
  }
  const { trigger, previousRole, previousTabindex } = activeDrawerModal;
  activeDrawerModal = null;
  surface.removeAttribute("aria-modal");
  if (previousRole === null) surface.removeAttribute("role");
  else surface.setAttribute("role", previousRole);
  if (previousTabindex === null) surface.removeAttribute("tabindex");
  else surface.setAttribute("tabindex", previousTabindex);
  document.removeEventListener("keydown", handleDrawerModalKeydown, true);
  if (restoreFocus && trigger?.isConnected) queueMicrotask(() => trigger.focus({ preventScroll: true }));
}

function syncMobileSidePanelState(collapsed) {
  const overlay = isControlDeckOverlayPresentation();
  const showBackdrop = !collapsed && overlay;
  elements.sidePanelBackdrop.hidden = !showBackdrop;
  if (showBackdrop) {
    mobileCanonicalUnmount();
    activateDrawerModal(elements.sidePanel, elements.sidePanelExpandButton, {
      close: () => setSidePanelCollapsed(true, { persist: false }),
    });
  } else {
    deactivateDrawerModal(elements.sidePanel);
    if (collapsed && overlay && isMobileShellV2Active()) queueMicrotask(() => renderMobilePhoneExperience());
  }
}

function syncControlDeckCollapsedClasses() {
  const presentation = effectiveControlDeckPresentation();
  const activeSide = presentation === "left" ? "left" : "right";
  if (presentation !== "overlay") {
    const singleCollapsed = presentation !== "both" && Boolean(controlDeckLayout.collapsedPanels?.[activeSide]);
    document.body.classList.toggle("side-panel-collapsed", singleCollapsed);
  }
  const overlayClosed = presentation === "overlay" && document.body.classList.contains("side-panel-collapsed");
  const leftCollapsed = presentation !== "overlay" && Boolean(controlDeckLayout.collapsedPanels?.left);
  const rightCollapsed = presentation !== "overlay" && Boolean(controlDeckLayout.collapsedPanels?.right);
  document.body.classList.toggle("side-panel-left-collapsed", leftCollapsed);
  document.body.classList.toggle("side-panel-right-collapsed", rightCollapsed);
  elements.toggleSidePanelButton?.setAttribute("aria-expanded", rightCollapsed ? "false" : "true");
  elements.toggleSidePanelLeftButton?.setAttribute("aria-expanded", leftCollapsed ? "false" : "true");
  elements.sidePanelExpandButton?.setAttribute("aria-expanded", overlayClosed || rightCollapsed ? "false" : "true");
  elements.sidePanelLeftExpandButton?.setAttribute("aria-expanded", leftCollapsed ? "false" : "true");
}

function setSidePanelCollapsed(collapsed, { persist = true, focusPanel = false, side = null } = {}) {
  if (collapsed) setSidePanelSectionEditMode(false);
  const presentation = effectiveControlDeckPresentation();
  const targetSide = side || (presentation === "left" ? "left" : "right");
  if (presentation === "overlay") {
    document.body.classList.toggle("side-panel-collapsed", collapsed);
  } else {
    controlDeckLayout.collapsedPanels = { ...controlDeckLayout.collapsedPanels, [targetSide]: collapsed };
    document.body.classList.toggle("side-panel-collapsed", collapsed && presentation !== "both");
  }
  syncControlDeckCollapsedClasses();
  elements.toggleSidePanelButton?.setAttribute("title", controlDeckLayout.collapsedPanels.right ? "Expand right Control Deck" : "Collapse right Control Deck");
  elements.toggleSidePanelButton?.setAttribute("aria-label", controlDeckLayout.collapsedPanels.right ? "Expand right Control Deck" : "Collapse right Control Deck");
  elements.toggleSidePanelLeftButton?.setAttribute("title", controlDeckLayout.collapsedPanels.left ? "Expand left Control Deck" : "Collapse left Control Deck");
  elements.toggleSidePanelLeftButton?.setAttribute("aria-label", controlDeckLayout.collapsedPanels.left ? "Expand left Control Deck" : "Collapse left Control Deck");
  syncMobileSidePanelState(presentation === "overlay" ? collapsed : true);
  updateSidePanelResizeHandle(currentSidePanelWidth(targetSide), targetSide);
  reconcileControlDeckHosts();
  requestAnimationFrame(syncResizablePanelWidthsForViewport);
  if (collapsed) closeSidePanelContextMenu({ returnFocus: false });
  if (focusPanel && !collapsed) (targetSide === "left" ? elements.toggleSidePanelLeftButton : elements.toggleSidePanelButton)?.focus?.({ preventScroll: true });
  if (!persist || presentation === "overlay") return;
  if (targetSide === "right") {
    try { localStorage.setItem(SIDE_PANEL_STORAGE_KEY, collapsed ? "1" : "0"); } catch { /* cache is best effort */ }
  }
  cacheControlDeckLayout(controlDeckLayout, "collapsedPanels");
  markDurableUiLayoutDirty("sidePanel", "collapsedPanels");
}

function restoreSidePanelState() {
  if (isMobileShellV2Active()) return;
  if (isControlDeckOverlayPresentation()) {
    setSidePanelCollapsed(true, { persist: false });
    return;
  }
  const stored = readStoredSidePanelCollapsed();
  const panels = controlDeckLayout.collapsedPanels || {};
  if (effectiveControlDeckPresentation() === "both") {
    setSidePanelCollapsed(Boolean(panels.right ?? stored ?? false), { persist: false, side: "right" });
    setSidePanelCollapsed(Boolean(panels.left ?? false), { persist: false, side: "left" });
  } else {
    const side = effectiveControlDeckPresentation() === "left" ? "left" : "right";
    setSidePanelCollapsed(Boolean(panels[side] ?? stored ?? false), { persist: false, side });
  }
}

function readStoredWorkspaceDashboardCollapsed() {
  try {
    const stored = localStorage.getItem(WORKSPACE_DASHBOARD_STORAGE_KEY);
    return stored === null ? true : stored === "1";
  } catch {
    return true;
  }
}

function persistWorkspaceDashboardCollapsed(collapsed) {
  try {
    localStorage.setItem(WORKSPACE_DASHBOARD_STORAGE_KEY, collapsed ? "1" : "0");
  } catch {
    // Ignore storage failures; this is only a browser preference.
  }
}

function setWorkspaceDashboardCollapsed(collapsed, { persist = true } = {}) {
  workspaceDashboardCollapsed = !!collapsed;
  if (elements.workspaceDashboard) elements.workspaceDashboard.hidden = workspaceDashboardCollapsed;
  if (elements.workspaceDashboardToggleButton) {
    elements.workspaceDashboardToggleButton.setAttribute("aria-expanded", workspaceDashboardCollapsed ? "false" : "true");
    const tooltip = workspaceDashboardCollapsed ? "Show workspace overview" : "Hide workspace overview";
    const tooltipDetail = `${tooltip}:\n• Shows current tab, cwd, model, context, session, and queue.\n• Opens common workspace/session actions from one place.`;
    elements.workspaceDashboardToggleButton.removeAttribute("title");
    elements.workspaceDashboardToggleButton.setAttribute("aria-label", tooltip);
    elements.workspaceDashboardToggleButton.setAttribute("data-tooltip", tooltipDetail);
  }
  if (persist) persistWorkspaceDashboardCollapsed(workspaceDashboardCollapsed);
}

function restoreWorkspaceDashboardState() {
  setWorkspaceDashboardCollapsed(readStoredWorkspaceDashboardCollapsed(), { persist: false });
}

function normalizeInterfaceDensity(value) {
  return value === "compact" ? "compact" : "comfortable";
}

function setInterfaceDensity(value, { persist = true } = {}) {
  interfaceDensity = normalizeInterfaceDensity(value);
  document.documentElement.dataset.density = interfaceDensity;
  if (persist) {
    try {
      localStorage.setItem(INTERFACE_DENSITY_STORAGE_KEY, interfaceDensity);
    } catch {
      // Browser storage is optional; density still applies to this page.
    }
  }
}

function restoreInterfaceDensity() {
  let stored = "comfortable";
  try {
    stored = localStorage.getItem(INTERFACE_DENSITY_STORAGE_KEY) || stored;
  } catch {
    // Use the accessible default.
  }
  setInterfaceDensity(stored, { persist: false });
}

function bindMobileViewChanges() {
  if (!mobileViewMedia) return;
  const syncForViewport = (event) => {
    applyMobileShellViewport();
    syncComposerActionGridAvailability();
    syncMobileComposerDisclosureLayout();
    setSidePanelSectionEditMode(false);
    if (isMobileShellV2Active()) return;
    setComposerActionsOpen(false);
    setMobileFooterExpanded(false);
    setMobileTabsExpanded(false);
    if (event.matches || isSidePanelOverlayView()) {
      setSidePanelCollapsed(true, { persist: false });
      return;
    }
    const stored = readStoredSidePanelCollapsed();
    setSidePanelCollapsed(stored ?? false, { persist: false });
  };
  if (typeof mobileViewMedia.addEventListener === "function") mobileViewMedia.addEventListener("change", syncForViewport);
  else mobileViewMedia.addListener?.(syncForViewport);
}

function bindSidePanelOverlayViewChanges() {
  if (!sidePanelOverlayMedia || sidePanelOverlayMedia === mobileViewMedia) return;
  const syncForViewport = (event) => {
    applyMobileShellViewport();
    if (isMobileShellV2Active()) return;
    if (event.matches) {
      setSidePanelCollapsed(true, { persist: false });
      updateTerminalSplitUi();
      return;
    }
    const stored = readStoredSidePanelCollapsed();
    setSidePanelCollapsed(stored ?? false, { persist: false });
    updateTerminalSplitUi();
  };
  if (typeof sidePanelOverlayMedia.addEventListener === "function") sidePanelOverlayMedia.addEventListener("change", syncForViewport);
  else sidePanelOverlayMedia.addListener?.(syncForViewport);
}

function updateVisualViewportVars() {
  const viewport = window.visualViewport;
  const viewportHeight = viewport?.height || window.innerHeight || document.documentElement.clientHeight;
  const offsetTop = viewport?.offsetTop || 0;
  const layoutHeight = window.innerHeight || viewportHeight;
  if (viewportHeight > maxVisualViewportHeight) maxVisualViewportHeight = viewportHeight;
  const keyboardInset = viewport ? Math.max(0, Math.round(layoutHeight - viewportHeight - offsetTop)) : 0;
  const promptFocused = document.activeElement === elements.promptInput;
  const keyboardOpen = isMobileView() && promptFocused && (keyboardInset > 80 || maxVisualViewportHeight - viewportHeight > 120);
  document.documentElement.style.setProperty("--visual-viewport-height", `${Math.round(viewportHeight)}px`);
  document.documentElement.style.setProperty("--visual-viewport-offset-top", `${Math.round(offsetTop)}px`);
  document.documentElement.style.setProperty("--keyboard-inset-bottom", `${keyboardInset}px`);
  document.body.classList.toggle("mobile-keyboard-open", keyboardOpen);
  if (keyboardOpen && !isMobileShellV2Active()) {
    setComposerActionsOpen(false);
    setMobileTabsExpanded(false);
    setMobileFooterExpanded(false);
    setFooterModelPickerOpen(false);
    setFooterBranchPickerOpen(false);
    syncMobileChatToBottomForInput();
  }
  updateFooterModelPickerPosition();
  updateMobileDropdownScrollBounds();
}

function installViewportHandlers() {
  updateVisualViewportVars();
  const update = () => updateVisualViewportVars();
  window.visualViewport?.addEventListener("resize", update, { passive: true });
  window.visualViewport?.addEventListener("scroll", update, { passive: true });
  window.addEventListener("resize", update, { passive: true });
  window.addEventListener("orientationchange", () => setTimeout(update, 80));
}

function installMobileShellNavigationBridge() {
  const urlTarget = mobileNavigationTargetFromSearch(window.location.search);
  if (urlTarget) receiveMobileNavigationTarget(urlTarget);
  navigator.serviceWorker?.addEventListener("message", (event) => {
    if (event.data?.type === "pi-webui:navigate:v1") receiveMobileNavigationTarget(event.data.target);
  });
}

function registerPwaServiceWorker() {
  if (!("serviceWorker" in navigator)) return;
  if (!window.isSecureContext) {
    addEvent("PWA install needs HTTPS or localhost for service-worker support on most mobile browsers.", "warn");
    return;
  }
  navigator.serviceWorker.register("/service-worker.js").catch((error) => {
    addEvent(`PWA service worker registration failed: ${error.message}`, "warn");
  });
}

function readStoredServerStartCwd() {
  try {
    return localStorage.getItem(SERVER_START_CWD_STORAGE_KEY) || "";
  } catch {
    return "";
  }
}

function rememberServerStartCwd(cwd) {
  const value = typeof cwd === "string" ? cwd.trim() : "";
  if (!value) return;
  try {
    localStorage.setItem(SERVER_START_CWD_STORAGE_KEY, value);
  } catch {
    // Ignore storage failures; the offline start helper can still show a generic command.
  }
  if (backendOffline) renderServerOfflinePanel();
}

function quoteCommandArg(value) {
  const text = String(value || ".");
  if (!/[\s"'`$]/.test(text)) return text;
  if (!text.includes("'")) return `'${text}'`;
  return `"${text.replace(/(["`$])/g, "\\$1")}"`;
}

function currentPortArg() {
  const port = window.location.port || "";
  return port && port !== DEFAULT_WEBUI_PORT ? ` --port ${port}` : "";
}

function serverStartCommandText() {
  return `pi-webui${currentPortArg()}`;
}

function serverStartSlashCommandText() {
  return `/webui-start${currentPortArg()}`;
}

function renderServerOfflinePanel() {
  if (elements.serverOfflineCommand) elements.serverOfflineCommand.textContent = serverStartCommandText();
  if (elements.serverOfflineSlashCommand) elements.serverOfflineSlashCommand.textContent = serverStartSlashCommandText();
}

function setServerRestartOverlay(active, message = "Waiting for the server to come back…", { phase = "restarting" } = {}) {
  serverRestartInProgress = !!active;
  const updating = phase === "updating";
  document.body.classList.toggle("server-restarting", serverRestartInProgress);
  if (elements.serverRestartPanel) {
    elements.serverRestartPanel.hidden = !serverRestartInProgress;
    elements.serverRestartPanel.dataset.phase = updating ? "updating" : "restarting";
  }
  if (elements.serverRestartKicker) elements.serverRestartKicker.textContent = updating ? "Updating" : "Restarting";
  if (elements.serverRestartTitle) elements.serverRestartTitle.textContent = updating ? "Applying exact update" : "Restarting Pi Web UI server";
  if (elements.serverRestartMessage) elements.serverRestartMessage.textContent = message;
  if (serverRestartInProgress) hideUpdateNotification();
  if (serverRestartInProgress && elements.serverOfflinePanel) elements.serverOfflinePanel.hidden = true;
}

function setBackendOffline(offline, error) {
  backendOffline = !!offline;
  mobileConnectionState = backendOffline ? "offline" : mobileConnectionState === "reconnecting" ? "reconnecting" : "online";
  mobileConnectionLabel = backendOffline ? "Paused/offline" : mobileConnectionState === "reconnecting" ? "Reconnecting" : "Online";
  recordMobileDiagnostic(backendOffline ? "backend offline" : "backend online", error?.message || "");
  const showOfflinePanel = backendOffline && !serverRestartInProgress;
  document.body.classList.toggle("server-offline", showOfflinePanel);
  if (elements.serverOfflinePanel) elements.serverOfflinePanel.hidden = !showOfflinePanel;
  renderServerOfflinePanel();
  if (backendOffline) {
    hideUpdateNotification();
    if (!serverRestartInProgress && !backendOfflineNoticeShown) {
      backendOfflineNoticeShown = true;
      addEvent(`Pi Web UI server is offline${error?.message ? `: ${error.message}` : ""}`, "warn");
    }
    renderMobilePhoneExperience();
    return;
  }
  if (backendOfflineNoticeShown) addEvent("Pi Web UI server is back online", "info");
  backendOfflineNoticeShown = false;
  renderMobilePhoneExperience();
}

async function copyText(text) {
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.append(textarea);
  textarea.select();
  const copied = document.execCommand("copy");
  textarea.remove();
  if (!copied) throw new Error("Clipboard copy failed");
}

function messageCopyFallbackText(body) {
  return String(body?.innerText || body?.textContent || "").replace(/\n{3,}/g, "\n\n").trimEnd();
}

function messageCopyText(message, body = null) {
  if (!message) return messageCopyFallbackText(body);
  if (message.role === "assistant") {
    const content = message.content === undefined || message.content === null ? "" : textFromContent(message.content);
    const text = stripTodoProgressLines(content).trimEnd();
    return text || messageCopyFallbackText(body);
  }
  if (message.role === "bashExecution") return stripAnsi([`$ ${message.command || ""}`, message.output || ""].filter(Boolean).join("\n\n")).trimEnd();
  if (message.role === "compactionSummary") return String(message.summary || "Context was compacted.").trimEnd();
  if (message.role === "toolResult") {
    const content = message.content === undefined || message.content === null ? "" : textFromContent(message.content);
    return stripAnsi(content).trimEnd() || messageCopyFallbackText(body);
  }
  if (message.role === "toolExecution") {
    const tool = normalizeToolExecution(message);
    const hasArgs = tool.args && Object.keys(tool.args).length > 0;
    const sections = [`tool: ${tool.name}`];
    if (hasArgs) sections.push(`arguments:\n${JSON.stringify(tool.args, null, 2)}`);
    if (tool.text) sections.push(`${tool.isPartial ? "live output" : "output"}:\n${tool.text}`);
    if (tool.details?.fullOutputPath) sections.push(`full output: ${tool.details.fullOutputPath}`);
    return sections.join("\n\n").trimEnd() || messageCopyFallbackText(body);
  }
  if (message.role === "thinking") return visibleThinkingText(message.thinking || textFromContent(message.content)).trimEnd() || messageCopyFallbackText(body);
  if (message.role === "toolCall") return toolCallDisplayText(message).trimEnd() || messageCopyFallbackText(body);
  if (message.role === "assistantEvent") {
    return (typeof message.content === "string" ? message.content : JSON.stringify(message.content ?? {}, null, 2)).trimEnd();
  }
  const content = message.content === undefined || message.content === null ? "" : textFromContent(message.content);
  return stripAnsi(content).trimEnd() || messageCopyFallbackText(body);
}

function setMessageCopyButtonState(button, copied) {
  clearTimeout(button._messageCopyResetTimer);
  button.classList.toggle("copied", copied);
  const icon = button.querySelector(".message-copy-icon");
  if (icon) icon.textContent = copied ? "✓" : "⧉";
  button.title = copied ? "Copied" : "Copy message";
  button.setAttribute("aria-label", button.title);
  if (copied) {
    button._messageCopyResetTimer = setTimeout(() => setMessageCopyButtonState(button, false), 1400);
  }
}

async function copyMessageBubble(button) {
  const bubble = button.closest(".message");
  const body = bubble?._copyBody || bubble?.querySelector(":scope > .message-body, :scope > .message-collapse > .message-body");
  const text = messageCopyText(bubble?._copyMessage, body);
  if (!text.trim()) {
    addEvent("message has no text to copy", "warn");
    return;
  }
  button.disabled = true;
  try {
    await copyText(text);
    setMessageCopyButtonState(button, true);
  } catch (error) {
    addEvent(`message copy failed: ${error.message || String(error)}`, "warn");
  } finally {
    button.disabled = false;
  }
}

function attachMessageCopyButton(bubble, message, body) {
  if (!bubble || !body) return null;
  bubble._copyMessage = message;
  bubble._copyBody = body;
  const existing = bubble.querySelector(":scope > .message-copy-button");
  if (existing) return existing;
  const button = make("button", "message-copy-button");
  button.type = "button";
  button.append(make("span", "message-copy-icon", "⧉"));
  setMessageCopyButtonState(button, false);
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    copyMessageBubble(button);
  });
  bubble.classList.add("has-copy-action");
  bubble.append(button);
  return button;
}

function userMessageEditText(message) {
  return textFromContent(message?.content).trim();
}

function messageEntryId(message) {
  for (const key of ["entryId", "id", "sessionEntryId", "messageId"]) {
    const value = message?.[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return "";
}

function userMessageOrdinalAtIndex(messageIndex) {
  if (!Number.isInteger(messageIndex) || messageIndex < 0) return -1;
  let ordinal = -1;
  for (let index = 0; index <= messageIndex && index < latestMessages.length; index += 1) {
    if (latestMessages[index]?.role === "user") ordinal += 1;
  }
  return ordinal;
}

async function resolveForkMessageForEdit(message, messageIndex, tabId = activeTabId) {
  const directEntryId = messageEntryId(message);
  const text = userMessageEditText(message);
  if (directEntryId) return { entryId: directEntryId, text };
  const response = await api("/api/fork-messages", { tabId });
  const forkMessages = Array.isArray(response.data?.messages) ? response.data.messages : [];
  const ordinal = userMessageOrdinalAtIndex(messageIndex);
  const ordinalMatch = ordinal >= 0 ? forkMessages[ordinal] : null;
  if (ordinalMatch?.entryId && userMessageEditText({ content: ordinalMatch.text }) === text) return ordinalMatch;
  const exactMatches = forkMessages.filter((item) => item?.entryId && String(item.text || "").trim() === text);
  if (exactMatches.length === 1) return exactMatches[0];
  if (exactMatches.length > 1 && ordinalMatch?.entryId) return ordinalMatch;
  throw new Error("Could not map this transcript message to a fork point. Use /fork for the full selector.");
}

function setEditRetryStatus(message = "", level = "info") {
  if (!elements.editRetryStatus) return;
  elements.editRetryStatus.textContent = message;
  elements.editRetryStatus.hidden = !message;
  elements.editRetryStatus.className = `edit-retry-status ${level} ${message ? "" : "muted"}`.trim();
}

function setEditRetryBusy(busy, label = "Working…") {
  for (const button of [elements.editRetryForkButton, elements.editRetrySendButton, elements.editRetryCancelButton].filter(Boolean)) button.disabled = !!busy;
  if (elements.editRetrySendButton) elements.editRetrySendButton.textContent = busy ? label : "Fork & run";
  if (elements.editRetryForkButton) elements.editRetryForkButton.textContent = busy ? "Forking…" : "Fork only";
}

function openEditRetryDialog(message, messageIndex = -1) {
  const text = userMessageEditText(message);
  if (!text) {
    addEvent("user message has no editable text", "warn");
    return;
  }
  activeEditRetry = { message, messageIndex, tabId: activeTabId };
  if (elements.editRetryMessage) elements.editRetryMessage.textContent = `Fork from user message #${messageIndex >= 0 ? messageIndex + 1 : "?"}, edit it, then run or leave the edited prompt in the composer.`;
  if (elements.editRetryText) {
    elements.editRetryText.value = text;
    elements.editRetryText.style.height = "auto";
  }
  setEditRetryStatus();
  setEditRetryBusy(false);
  if (!elements.editRetryDialog.open) elements.editRetryDialog.showModal();
  queueMicrotask(() => {
    elements.editRetryText?.focus();
    elements.editRetryText?.select();
  });
}

function closeEditRetryDialog() {
  activeEditRetry = null;
  if (elements.editRetryDialog?.open) elements.editRetryDialog.close();
}

async function submitEditRetry({ send = false } = {}) {
  if (!activeEditRetry) return;
  const editedText = String(elements.editRetryText?.value || "").trim();
  if (!editedText) {
    setEditRetryStatus("Prompt cannot be empty.", "error");
    elements.editRetryText?.focus();
    return;
  }
  const { message, messageIndex, tabId } = activeEditRetry;
  const tabContext = activeTabContext(tabId || activeTabId);
  setEditRetryBusy(true, "Forking…");
  setEditRetryStatus("Resolving fork point…");
  try {
    const forkMessage = await resolveForkMessageForEdit(message, messageIndex, tabContext.tabId);
    setEditRetryStatus("Forking session…");
    const result = await api("/api/fork", { method: "POST", body: { entryId: forkMessage.entryId }, tabId: tabContext.tabId });
    const forkTab = await switchToResponseTab(result);
    const forkTabId = forkTab?.id || activeTabId;
    closeEditRetryDialog();
    if (send) {
      addEvent("forked session in a new tab; sending edited prompt", "info");
      await sendPrompt("prompt", editedText, { targetTabId: forkTabId, throwOnError: true });
    } else {
      elements.promptInput.value = editedText;
      resizePromptInput();
      focusPromptInput({ defer: true });
      addEvent("forked session in a new tab; edited prompt restored in composer", "info");
    }
  } catch (error) {
    setEditRetryStatus(error.message || String(error), "error");
    if (send) {
      elements.promptInput.value = editedText;
      resizePromptInput();
    }
  } finally {
    setEditRetryBusy(false);
  }
}

function attachMessageEditRetryButton(bubble, message, messageIndex, { streaming = false, transient = false } = {}) {
  if (!bubble || streaming || transient || message?.role !== "user") return null;
  const text = userMessageEditText(message);
  if (!text) return null;
  const existing = bubble.querySelector(":scope > .message-edit-retry-button");
  if (existing) return existing;
  const button = make("button", "message-edit-retry-button", "↺");
  button.type = "button";
  button.title = "Edit this prompt and retry from here";
  button.setAttribute("aria-label", button.title);
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditRetryDialog(message, messageIndex);
  });
  bubble.classList.add("has-edit-retry-action");
  bubble.append(button);
  return button;
}

function safeHttpUrl(value, base = window.location.href) {
  const text = String(value || "").trim();
  if (!text) return "";
  try {
    const url = new URL(text, base);
    return url.protocol === "http:" || url.protocol === "https:" ? url.href : "";
  } catch {
    return "";
  }
}

function triggerNativeDownload(download) {
  const url = safeHttpUrl(download?.url);
  if (!url) return false;
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = String(download.fileName || "");
  anchor.rel = "noopener";
  anchor.hidden = true;
  document.body.append(anchor);
  try {
    anchor.click();
    return true;
  } finally {
    anchor.remove();
  }
}

function isStandalonePwaWindow() {
  return window.matchMedia?.("(display-mode: standalone)")?.matches === true || window.navigator.standalone === true;
}

function alternateLoopbackBrowserUrl(value) {
  const url = safeHttpUrl(value);
  if (!url) return "";
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname.toLowerCase();
    if (hostname === "127.0.0.1" || hostname === "[::1]" || hostname === "::1") parsed.hostname = "localhost";
    else if (hostname === "localhost") parsed.hostname = "127.0.0.1";
    else return "";
    return parsed.href;
  } catch {
    return "";
  }
}

function nativeDownloadOpenUrl(download, { externalBrowser = false } = {}) {
  const rawUrl = download?.openUrl || download?.url;
  const url = safeHttpUrl(rawUrl);
  if (!url) return "";
  let openUrl = url;
  if (!download?.openUrl) {
    try {
      const inlineUrl = new URL(url);
      inlineUrl.searchParams.set("disposition", "inline");
      openUrl = inlineUrl.href;
    } catch {
      openUrl = url;
    }
  }
  return externalBrowser && isStandalonePwaWindow() ? alternateLoopbackBrowserUrl(openUrl) || openUrl : openUrl;
}

function openNativeDownloadInBrowser(download) {
  const url = nativeDownloadOpenUrl(download, { externalBrowser: true });
  if (!url) return false;
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.target = "_blank";
  anchor.rel = "noopener";
  anchor.hidden = true;
  document.body.append(anchor);
  try {
    anchor.click();
    return true;
  } finally {
    anchor.remove();
  }
}

function openNativeExportDownloadPrompt(download, serverPath = "") {
  const url = nativeDownloadOpenUrl(download, { externalBrowser: true });
  if (!url) return false;
  const fileName = String(download?.fileName || "session export");
  const savedPath = String(serverPath || "").trim();
  openNativeCommandDialog({ title: "/export", message: "Session export is ready." });
  const details = [make("p", "native-command-note", `File: ${fileName}`)];
  if (savedPath) details.push(make("p", "native-command-note native-export-path", `Saved to:\n${savedPath}`));
  details.push(make("p", "native-command-note muted", "Open it in your browser, or cancel and use the transcript download URL later."));
  elements.nativeCommandBody.append(...details);
  elements.nativeCommandActions.replaceChildren();
  addNativeCommandAction("Cancel", closeNativeCommandDialog);
  if (savedPath) {
    addNativeCommandAction("Copy path", async () => {
      try {
        await copyText(savedPath);
        addEvent("copied export file path", "info");
      } catch (error) {
        addEvent(`copy export path failed: ${error.message || String(error)}`, "error");
      }
    });
  }
  addNativeCommandAction("Copy URL", async () => {
    try {
      await copyText(url);
      addEvent("copied export browser URL", "info");
    } catch (error) {
      addEvent(`copy export URL failed: ${error.message || String(error)}`, "error");
    }
  });
  addNativeCommandAction("Open in browser", () => {
    if (openNativeDownloadInBrowser(download)) addEvent(`opened export: ${fileName}`, "info");
    else addEvent("could not open export URL", "error");
    closeNativeCommandDialog();
  }, "primary");
  return true;
}

function handleNativeDownloadResponse(download, command, serverPath = "") {
  if (String(command || "").toLowerCase() === "export") return openNativeExportDownloadPrompt(download, serverPath);
  return triggerNativeDownload(download);
}

async function copyServerStartCommand() {
  const command = serverStartCommandText();
  try {
    await copyText(command);
    addEvent("copied Pi Web UI start command", "info");
  } catch (error) {
    addEvent(`copy failed; manually run: ${command}`, "warn");
  }
}

async function retryServerConnection() {
  const button = elements.retryServerConnectionButton;
  if (button) {
    button.disabled = true;
    button.textContent = "Retrying…";
  }
  try {
    await api("/api/health", { scoped: false });
  } catch (error) {
    setBackendOffline(true, error);
    addEvent("Pi Web UI server is still offline", "warn");
    return;
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = "Retry connection";
    }
  }

  try {
    await initializeTabs();
  } catch (error) {
    addEvent(error.message || String(error), "error");
  }
}

function scopedApiPath(path, tabId = activeTabId) {
  if (!tabId || !path.startsWith("/api/") || path === "/api/tabs" || path.startsWith("/api/tabs?") || path.startsWith("/api/tabs/")) return path;
  const url = new URL(path, window.location.origin);
  url.searchParams.set("tab", tabId);
  return `${url.pathname}${url.search}${url.hash}`;
}

// Identical GET requests that overlap in time (boot fans out several refresh paths that ask for
// the same catalogs) share one in-flight fetch. Callers still get their own resolved value.
const inFlightGetRequests = new Map();

async function api(path, { method = "GET", body, tabId = activeTabId, scoped = true, signal } = {}) {
  const url = scoped ? scopedApiPath(path, tabId) : path;
  if (method === "GET" && !signal) {
    const pending = inFlightGetRequests.get(url);
    if (pending) return pending;
    const request = apiUncached(url, { method, body, signal }).finally(() => {
      if (inFlightGetRequests.get(url) === request) inFlightGetRequests.delete(url);
    });
    inFlightGetRequests.set(url, request);
    return request;
  }
  return apiUncached(url, { method, body, signal });
}

async function apiUncached(url, { method = "GET", body, signal } = {}) {
  let response;
  try {
    response = await fetch(url, {
      method,
      headers: body === undefined ? undefined : { "content-type": "application/json" },
      body: body === undefined ? undefined : JSON.stringify(body),
      signal,
    });
  } catch (error) {
    // Aborted autocomplete requests are expected while the user keeps typing;
    // they do not indicate that the Web UI backend became unreachable.
    if (signal?.aborted || error?.name === "AbortError") throw error;
    const offlineError = error instanceof Error ? error : new Error(String(error));
    offlineError.backendOffline = true;
    setBackendOffline(true, offlineError);
    throw offlineError;
  }
  setBackendOffline(false);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    if (response.status === 401 && data.remoteAuthRequired) {
      const returnPath = `${window.location.pathname}${window.location.search || ""}` || "/";
      window.location.assign(`/remote-auth?return=${encodeURIComponent(returnPath)}`);
    }
    const error = new Error(data.error || data.message || JSON.stringify(data));
    error.statusCode = response.status;
    error.data = data;
    throw error;
  }
  return data;
}

function formatWebuiVersion(version) {
  const text = String(version || "").trim();
  if (!text) return "";
  return text.startsWith("v") ? text : `v${text}`;
}

function isWebuiDevMetadata(data) {
  return data?.webuiDev === true || String(data?.webuiMode || "").toLowerCase() === "dev";
}

function renderPiVersionButton() {
  const button = elements.piVersionButton;
  if (!button) return;
  const label = formatWebuiVersion(piVersion);
  button.hidden = !label;
  button.textContent = label ? `Pi ${label}` : "";
  const state = componentUpdateTagState("pi");
  const stateText = componentUpdateTagStateText(state);
  if (state) button.dataset.updateState = state;
  else delete button.dataset.updateState;
  if (label) {
    const base = `View Pi ${label} release notes`;
    button.title = stateText ? `${base} — ${stateText}` : base;
    button.setAttribute("aria-label", stateText ? `${base}, ${stateText}` : base);
  }
}

function renderWebuiVersionButton() {
  const button = elements.webuiVersionButton;
  if (!button) return;
  const label = formatWebuiVersion(webuiVersion);
  button.hidden = !label;
  button.textContent = label ? `Web UI ${label}` : "";
  const state = componentUpdateTagState("webui");
  const stateText = componentUpdateTagStateText(state);
  if (state) button.dataset.updateState = state;
  else delete button.dataset.updateState;
  if (label) {
    const base = `Open Pi Web UI ${label} package and update details`;
    button.title = stateText ? `${base} — ${stateText}` : base;
    button.setAttribute("aria-label", stateText ? `${base}, ${stateText}` : base);
  }
}

function renderWebuiDevBadge() {
  const badge = elements.webuiDevBadge;
  if (!badge) return;
  badge.hidden = !webuiDevServer;
  const version = formatWebuiVersion(webuiVersion);
  badge.title = `Pi Web UI${version ? ` ${version}` : ""} dev server`;
}

function setWebuiVersion(version) {
  const text = String(version || "").trim();
  if (text === webuiVersion) return;
  webuiVersion = text;
  renderWebuiVersionButton();
  renderWebuiDevBadge();
}

function setPiVersion(version) {
  const text = String(version || "").trim().replace(/^v/i, "");
  if (text === piVersion) return;
  piVersion = text;
  renderPiVersionButton();
}

function setWebuiDevServer(dev) {
  const next = !!dev;
  if (next === webuiDevServer) return;
  webuiDevServer = next;
  renderWebuiDevBadge();
}

function piReleasePageUrl(version = piVersion) {
  const cleanVersion = String(version || "").trim().replace(/^v/i, "");
  if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(cleanVersion)) return "";
  return `https://github.com/earendil-works/pi/releases/tag/v${encodeURIComponent(cleanVersion)}`;
}

function formatPiReleaseDate(value) {
  const date = new Date(value);
  if (!value || Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(date);
}

function setPiReleaseNotesLink(value) {
  const link = elements.piReleaseNotesGithubLink;
  if (!link) return;
  const href = safeHttpUrl(value);
  link.hidden = !href;
  if (href) link.href = href;
  else link.removeAttribute("href");
}

function openWebuiNpmPageInNewTab() {
  const href = safeHttpUrl(PI_WEBUI_NPM_URL);
  if (!href) return false;
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.target = "_blank";
  anchor.rel = "noopener noreferrer";
  anchor.hidden = true;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  return true;
}

async function confirmOpenWebuiNpmPage() {
  const confirmed = await appConfirm({
    title: "Open npm package page?",
    summary: "Open @firstpick/pi-package-webui on npm in a new browser tab?",
    affected: "A new tab will open to the public Pi Web UI package page.",
    undoable: true,
    confirmLabel: "Open npm",
    danger: false,
  });
  if (!confirmed) return;
  if (!openWebuiNpmPageInNewTab()) addEvent("Pi Web UI npm package URL is unavailable", "error");
}

async function openPiReleaseNotes() {
  const dialog = elements.piReleaseNotesDialog;
  if (!dialog) return;
  const installedVersion = piVersion;
  const availableVersion = latestUpdateStatus?.pi?.updateAvailable ? latestUpdateStatus.pi.latestVersion : "";
  const displayedVersion = availableVersion || installedVersion;
  const label = formatWebuiVersion(displayedVersion);
  elements.piReleaseNotesTitle.textContent = label ? `Pi ${label} release notes` : "Pi release notes";
  elements.piReleaseNotesStatus.textContent = "Loading release notes from GitHub…";
  elements.piReleaseNotesBody.setAttribute("aria-busy", "true");
  elements.piReleaseNotesBody.replaceChildren(make("p", "muted", "Loading…"));
  setPiReleaseNotesLink(piReleasePageUrl(displayedVersion));
  renderComponentUpdateDialogs();
  if (!dialog.open) dialog.showModal();
  refreshUpdateStatus({ notify: false }).catch((error) => addEvent(`Pi/Web UI update check failed: ${error.message || String(error)}`, "warn"));

  try {
    const response = await api("/api/pi-release-notes", { scoped: false });
    if (installedVersion !== piVersion) return;
    const release = response.data || {};
    const releaseVersion = String(release.version || "").trim().replace(/^v/i, "");
    const releaseLabel = formatWebuiVersion(releaseVersion || displayedVersion);
    elements.piReleaseNotesTitle.textContent = releaseLabel ? `Pi ${releaseLabel} release notes` : (release.title || "Pi release notes");
    renderMarkdown(elements.piReleaseNotesBody, release.body || "No release notes were provided for this release.");
    const published = formatPiReleaseDate(release.publishedAt);
    elements.piReleaseNotesStatus.textContent = `${published ? `Published ${published}` : "Loaded from GitHub"}${release.truncated ? " · Long notes were truncated" : ""}`;
    setPiReleaseNotesLink(release.url || piReleasePageUrl(release.version));
  } catch (error) {
    elements.piReleaseNotesStatus.textContent = "Release notes could not be loaded.";
    elements.piReleaseNotesBody.replaceChildren(make("p", "pi-release-notes-error", error.message || String(error)));
  } finally {
    elements.piReleaseNotesBody.removeAttribute("aria-busy");
  }
}

async function refreshWebuiVersion() {
  const health = await api("/api/health", { scoped: false });
  if (health.bootIdentity) serverBootIdentity = health.bootIdentity;
  setWebuiVersion(health.webuiVersion);
  setPiVersion(health.piVersion);
  setWebuiDevServer(isWebuiDevMetadata(health));
}

function packageUpdateText(label, status = {}) {
  const current = formatWebuiVersion(status.currentVersion || "");
  const latest = formatWebuiVersion(status.latestVersion || "");
  if (current && latest) return `${label} ${current} → ${latest}`;
  if (latest) return `${label} ${latest}`;
  return label;
}

function updateNotificationItems(status = latestUpdateStatus) {
  const items = [];
  if (status?.pi?.updateAvailable) items.push(packageUpdateText("Pi", status.pi));
  if (status?.webui?.updateAvailable) items.push(packageUpdateText("Web UI", status.webui));
  return items;
}

function updateNotificationDismissKey(status = latestUpdateStatus) {
  const parts = [status?.pi?.latestVersion, status?.webui?.latestVersion]
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  return parts.length ? parts.join("|") : "";
}

function storedDismissedUpdateKey() {
  try {
    return localStorage.getItem(UPDATE_NOTIFICATION_DISMISS_STORAGE_KEY) || "";
  } catch {
    return "";
  }
}

function rememberDismissedUpdateKey(key) {
  if (!key) return;
  try {
    localStorage.setItem(UPDATE_NOTIFICATION_DISMISS_STORAGE_KEY, key);
  } catch {
    // Ignore private-mode storage failures.
  }
}

function hideUpdateNotification({ remember = false } = {}) {
  const panel = elements.updateNotification;
  if (!panel) return;
  clearTimeout(updateNotificationHideTimer);
  if (remember) rememberDismissedUpdateKey(updateNotificationDismissKey());
  panel.classList.remove("show");
  updateNotificationHideTimer = setTimeout(() => {
    panel.hidden = true;
  }, 360);
}

function renderUpdateNotification(status = latestUpdateStatus, { force = false } = {}) {
  const panel = elements.updateNotification;
  if (!panel) return;
  latestUpdateStatus = status || latestUpdateStatus;
  const items = updateNotificationItems(latestUpdateStatus);
  const dismissKey = updateNotificationDismissKey(latestUpdateStatus);
  const shouldShow = !!latestUpdateStatus?.updateAvailable && items.length > 0 && !updateRequestInProgress;
  if (!shouldShow || (!force && dismissKey && storedDismissedUpdateKey() === dismissKey)) {
    hideUpdateNotification();
    return;
  }

  const canRunUpdate = latestUpdateStatus.canRunUpdate !== false && !latestUpdateStatus.nativeJobDiscoveryError;
  const hasPiUpdate = !!latestUpdateStatus.pi?.updateAvailable;
  const hasPackageUpdate = !!latestUpdateStatus.webui?.updateAvailable;
  if (elements.updateNotificationTitle) elements.updateNotificationTitle.textContent = items.length === 1 ? `${items[0]} available` : "Pi updates available";
  if (elements.updateNotificationMessage) {
    const message = canRunUpdate
      ? "Choose Pi or Web UI separately. Confirm the exact native command and installation before it runs."
      : "Updates must start locally, with no other update in progress. Open a version tag for status and recovery guidance.";
    elements.updateNotificationMessage.textContent = message;
  }
  const details = [
    items.join(" · "),
    latestUpdateStatus.webuiDev && latestUpdateStatus.webui?.updateAvailable ? "The current Web UI is a source checkout and remains untouched; only separately verified, eligible targets can enter the exact update plan." : "",
    latestUpdateStatus.packages?.note || "",
  ].filter(Boolean).join(" ");
  if (elements.updateNotificationDetail) elements.updateNotificationDetail.textContent = details;
  if (elements.updateNotificationUpdateButton) {
    elements.updateNotificationUpdateButton.hidden = !canRunUpdate || !hasPiUpdate;
    elements.updateNotificationUpdateButton.disabled = updateRequestInProgress || latestUpdateStatus.updateInProgress;
    elements.updateNotificationUpdateButton.textContent = "Update Pi";
  }
  if (elements.updateNotificationUpdateAllButton) {
    elements.updateNotificationUpdateAllButton.hidden = !canRunUpdate || !hasPackageUpdate;
    elements.updateNotificationUpdateAllButton.disabled = updateRequestInProgress || latestUpdateStatus.updateInProgress;
    elements.updateNotificationUpdateAllButton.classList.toggle("primary", !hasPiUpdate);
    elements.updateNotificationUpdateAllButton.textContent = "Update Web UI";
  }
  clearTimeout(updateNotificationHideTimer);
  panel.hidden = false;
  requestAnimationFrame(() => panel.classList.add("show"));
}

async function refreshUpdateStatus({ force = false, notify = true } = {}) {
  const path = force ? "/api/update-status?refresh=1" : "/api/update-status";
  const response = await api(path, { scoped: false });
  latestUpdateStatus = response.data || null;
  for (const target of COMPONENT_UPDATE_TARGETS) {
    if (latestUpdateStatus?.nativeJobs && Object.hasOwn(latestUpdateStatus.nativeJobs, target)) {
      if (latestUpdateStatus.nativeJobs[target] || !uncertainApplyJobs[target]) observedNativeJobs[target] = latestUpdateStatus.nativeJobs[target];
    }
  }
  if (latestUpdateStatus?.nativeJobs && !latestUpdateStatus.nativeJobDiscoveryError) nativeJobPollError = "";
  if (latestUpdateStatus?.pi?.activeRuntimeVersion && latestUpdateStatus.pi.activeRuntimeVersion !== "unknown") setPiVersion(latestUpdateStatus.pi.activeRuntimeVersion);
  if (notify) renderUpdateNotification(latestUpdateStatus);
  renderComponentUpdateIndicators();
  renderComponentUpdateDialogs();
  syncComponentUpdatePolling();
  return latestUpdateStatus;
}

function scheduleUpdateStatusRefresh() {
  clearTimeout(updateStatusRefreshTimer);
  updateStatusRefreshTimer = setTimeout(() => {
    updateStatusRefreshTimer = null;
    refreshUpdateStatus({ force: true }).catch((error) => addEvent(`Pi/Web UI update check failed: ${error.message || String(error)}`, "warn"));
    scheduleUpdateStatusRefresh();
  }, UPDATE_STATUS_REFRESH_MS);
}

const COMPONENT_UPDATE_TARGETS = ["pi", "webui"];

function componentUpdateLabel(target) {
  return target === "pi" ? "Pi" : "Web UI";
}

function componentUpdateJob(target) {
  const job = latestUpdateStatus?.componentUpdates?.[target];
  return job && typeof job === "object" ? job : null;
}

function nativeUpdateJob(target) {
  return observedNativeJobs[target];
}

function nativeUpdateUnsettled(job) {
  return job && !["success", "partial", "failed", "unchanged", "unknown"].includes(job.phase);
}

function componentUpdateTagState(target) {
  const job = nativeUpdateJob(target);
  if (job?.phase === "unknown" || latestUpdateStatus?.nativeJobDiscoveryError || nativeJobPollError) return "unknown";
  if (job?.phase === "partial") return "partial";
  if (job?.phase === "failed") return "failed";
  if (job?.phase === "success") return "succeeded";
  if (nativeUpdateUnsettled(job)) return "running";
  if (latestUpdateStatus?.[target]?.updateAvailable) return "available";
  return "";
}

function componentUpdateTagStateText(state) {
  switch (state) {
    case "running": return "update running";
    case "failed": return "update failed";
    case "partial": return "update partially succeeded";
    case "unknown": return "update status unknown";
    case "succeeded": return "update succeeded";
    case "available": return "update available";
    default: return "";
  }
}

function anyComponentUpdateRunning() {
  return COMPONENT_UPDATE_TARGETS.some((target) => nativeUpdateUnsettled(nativeUpdateJob(target)));
}

function renderComponentUpdateIndicators() {
  renderPiVersionButton();
  renderWebuiVersionButton();
}

function componentUpdateStatusText(target) {
  const label = componentUpdateLabel(target);
  const job = nativeUpdateJob(target);
  const pkg = latestUpdateStatus?.[target] || {};
  if (latestUpdateStatus?.nativeJobDiscoveryError || nativeJobPollError) {
    return { text: `Update status cannot be verified: ${latestUpdateStatus?.nativeJobDiscoveryError || nativeJobPollError}. Do not retry until the host is checked.`, level: "error" };
  }
  if (!job && latestUpdateStatus?.updateInProgress) {
    return { text: "An update is in progress, but its job ID is not available. Do not retry until its status is known.", level: "warn" };
  }
  if (job) {
    const id = `Job ${job.transactionId || "unknown"}`;
    const error = job.error ? ` ${String(job.error).slice(0, 600)}` : "";
    switch (job.phase) {
      case "unknown": return { text: `${id}: completion is unknown.${error} Do not retry or restart; check the host and recover manually.`, level: "error" };
      case "partial": return { text: `${id}: partial result. Some installations failed or were unverified.${error} Verified healthy active changes may have restarted; inspect each receipt before any retry.`, level: "warn" };
      case "failed": return { text: `${id}: update failed or could not be verified.${error} Inspect receipts and installation health before retrying.`, level: "error" };
      case "unchanged": return { text: `${id}: commands finished but no installation changed. No automatic restart was needed.`, level: "info" };
      case "success": return { text: `${id}: changed installations verified. Any healthy changed active component was automatically restarted after idle; unchanged or separate PATH installations were not.`, level: "success" };
      case "restart-authorized": return { text: `${id}: commands completed and healthy changed active components are waiting for idle before automatic restart.`, level: "warn" };
      case "restart-in-progress": return { text: `${id}: automatic restart is in progress; reconnecting to the same job.`, level: "warn" };
      case "restart-pending": return { text: `${id}: successor health and session restoration are not yet confirmed. Do not infer restart success.`, level: "warn" };
      default: return { text: `${id}: ${job.phase || "status pending"}. Waiting for command completion and verification.`, level: "warn" };
    }
  }
  const current = formatWebuiVersion((target === "pi" ? pkg.pathInstallationVersion : pkg.currentVersion) || (target === "pi" ? piVersion : webuiVersion) || "");
  const latest = formatWebuiVersion(pkg.latestVersion || "");
  const availability = pkg.updateAvailable ? `${label} ${current || "current"} → ${latest || "new version"} is available.` : "";
  const guidance = target === "pi" ? pkg.pathGuidance : (latestUpdateStatus?.webuiDev ? "Active source checkout stays unchanged; separately proven installations may be eligible." : "");
  if (guidance) return { text: [availability, guidance].filter(Boolean).join(" "), level: "warn" };
  if (availability) return { text: availability, level: "info" };
  if (pkg.checked && latest) return { text: `${label} is up to date.`, level: "info" };
  if (pkg.skippedReason) return { text: `Update check skipped: ${pkg.skippedReason}.`, level: "info" };
  return { text: "", level: "info" };
}

function componentUpdateButtonState(target) {
  const label = componentUpdateLabel(target);
  const job = nativeUpdateJob(target);
  if (componentUpdateStartInProgress) return { disabled: true, label: "Starting…" };
  if (nativeJobPollError || latestUpdateStatus?.nativeJobDiscoveryError || latestUpdateStatus?.canRunUpdate === false ||
      latestUpdateStatus?.updateInProgress || anyComponentUpdateRunning() || job?.phase === "unknown" ||
      updateRequestInProgress) {
    return { disabled: true, label: `Update ${label}` };
  }
  return { disabled: false, label: `Update ${label}` };
}

function renderComponentUpdatePanel(target, statusElement, buttonElement) {
  if (!statusElement || !buttonElement) return;
  const { text, level } = componentUpdateStatusText(target);
  statusElement.hidden = false;
  statusElement.textContent = text;
  statusElement.dataset.level = level;
  if (nativeUpdateUnsettled(nativeUpdateJob(target))) statusElement.dataset.updateRunning = "";
  else delete statusElement.dataset.updateRunning;
  const output = target === "pi" ? elements.piComponentUpdateOutput : elements.webuiComponentUpdateOutput;
  const job = nativeUpdateJob(target);
  if (output) {
    const lines = (job?.receipts || []).map((receipt) => [
      `${receipt.id || "Installation"}: ${receipt.status || "unknown"}${receipt.afterVersion ? ` (installed ${receipt.afterVersion})` : ""}`,
      receipt.stdout ? `stdout: ${String(receipt.stdout).slice(0, 2000)}` : "",
      receipt.stderr ? `stderr: ${String(receipt.stderr).slice(0, 2000)}` : "",
      receipt.error ? `error: ${String(receipt.error).slice(0, 600)}` : "",
    ].filter(Boolean).join("\n"));
    const verification = (job?.verifiedTargets || []).map((item) => `${item.id}: verification ${item.status || "unproven"}`);
    output.textContent = [...lines, ...verification].join("\n\n").slice(0, 8000);
    output.hidden = !output.textContent;
  }
  const buttonState = componentUpdateButtonState(target);
  buttonElement.disabled = buttonState.disabled;
  buttonElement.textContent = buttonState.label;
}

function renderComponentUpdateDialogs() {
  renderComponentUpdatePanel("pi", elements.piComponentUpdateStatus, elements.piComponentUpdateButton);
  const pkg = latestUpdateStatus?.webui || {};
  if (elements.webuiPackageCurrentVersion) {
    elements.webuiPackageCurrentVersion.textContent = formatWebuiVersion(pkg.currentVersion || webuiVersion || "") || "Unknown";
  }
  if (elements.webuiPackageLatestVersion) {
    elements.webuiPackageLatestVersion.textContent = formatWebuiVersion(pkg.latestVersion || "") || (pkg.checked ? "Unknown" : "Not checked");
  }
  renderComponentUpdatePanel("webui", elements.webuiComponentUpdateStatus, elements.webuiComponentUpdateButton);
}

function syncComponentUpdatePolling() {
  if (anyComponentUpdateRunning() || latestUpdateStatus?.updateInProgress) {
    if (componentUpdatePollTimer === null) {
      componentUpdatePollTimer = setTimeout(async () => {
        componentUpdatePollTimer = null;
        try {
          for (const target of COMPONENT_UPDATE_TARGETS) {
            const job = nativeUpdateJob(target);
            if (nativeUpdateUnsettled(job) && job.transactionId) {
              observedNativeJobs[target] = (await api(`/api/update/transactions/${encodeURIComponent(job.transactionId)}`, { scoped: false })).data;
            }
          }
          await refreshUpdateStatus({ notify: false });
          for (const target of COMPONENT_UPDATE_TARGETS) {
            if (uncertainApplyJobs[target] && observedNativeJobs[target]?.phase === "planned" &&
                latestUpdateStatus?.nativeJobs?.[target] === null && !latestUpdateStatus.updateInProgress) {
              uncertainApplyJobs[target] = null;
              observedNativeJobs[target] = null;
            } else if (uncertainApplyJobs[target] && observedNativeJobs[target]?.phase !== "planned" &&
                observedNativeJobs[target]?.phase !== "launching") uncertainApplyJobs[target] = null;
          }
          renderComponentUpdateDialogs();
          syncComponentUpdatePolling();
        } catch (error) {
          nativeJobPollError = error.message || String(error);
          renderComponentUpdateDialogs();
          syncComponentUpdatePolling();
        }
      }, COMPONENT_UPDATE_POLL_MS);
    }
  } else if (componentUpdatePollTimer !== null) {
    clearTimeout(componentUpdatePollTimer);
    componentUpdatePollTimer = null;
  }
}

function componentUpdateConfirmationText(plan) {
  const context = plan.context || {};
  const active = plan.active || {};
  const installations = (plan.targets || []).map((item) => [
    `${item.id}: ${item.packageName} ${item.beforeVersion} at ${item.installedRoot}`,
    `Affected root: ${item.effectRoot}`,
    `Executable: ${item.command.command}`,
    `Command argv: ${JSON.stringify(item.command.args)}`,
  ].join("\n")).join("\n\n");
  return [
    `Update ${componentUpdateLabel(plan.requested)} with this exact plan?`,
    `Active Pi: ${active.pi || "unknown"} at ${active.piRoot || "unknown"}.`,
    plan.pathPi?.eligible
      ? `Confirmed PATH Pi: ${plan.pathPi.version} at ${plan.pathPi.packageRoot}; executable ${plan.pathPi.executable}; CLI ${plan.pathPi.cli}. It may differ from active Pi.`
      : `PATH Pi unproven: ${plan.pathPi?.guidance || "No verified PATH Pi version/root was returned; only confirmed commands below are eligible."}`,
    `Active Web UI: ${active.webui || "unknown"} at ${active.webuiRoot || "unknown"}.`,
    `Shell: ${context.shell || "unknown"}\nWorking directory: ${context.cwd || "unknown"}\nAgent directory: ${context.agentDir || "unknown"}\nNpm prefix: ${context.npmPrefix || "not applicable"}`,
    installations,
    plan.refusals?.length ? `Skipped/manual: ${plan.refusals.join(" · ")}` : "",
    plan.warning || "Native package lifecycle scripts may run under your existing configuration; no automatic elevation or sandbox is provided.",
    "Known affected work must be idle. Only changed, verified healthy active components restart automatically after all commands finish and work is idle. Native updates cannot be rolled back automatically.",
    `Plan digest: ${plan.digest}`,
  ].filter(Boolean).join("\n\n");
}

async function startComponentUpdate(target) {
  if (componentUpdateStartInProgress) return;
  const label = componentUpdateLabel(target);
  if (componentUpdateButtonState(target).disabled) return;
  componentUpdateStartInProgress = true;
  renderComponentUpdateDialogs();
  let plan;
  try {
    plan = (await api("/api/update/plan", { method: "POST", body: { targets: [target] }, scoped: false }))?.data?.plan;
  } catch (error) {
    addEvent(error.message || String(error), "error");
    componentUpdateStartInProgress = false;
    renderComponentUpdateDialogs();
    return;
  }
  if (plan?.requested !== target || !plan.transactionId || !plan.digest || !Array.isArray(plan.targets) || !plan.targets.length) {
    addEvent("Update preview is incomplete; no command was launched.", "error");
    componentUpdateStartInProgress = false;
    renderComponentUpdateDialogs();
    return;
  }
  const confirmed = await appConfirmText(componentUpdateConfirmationText(plan), {
    affected: plan.targets.map((item) => `${item.id}: ${item.installedRoot}`).join(" · "),
    confirmLabel: `Run ${label} update`,
    danger: false,
  });
  if (!confirmed) {
    componentUpdateStartInProgress = false;
    renderComponentUpdateDialogs();
    return;
  }
  try {
    const response = await api("/api/update/apply", { method: "POST", body: { transactionId: plan.transactionId, planDigest: plan.digest }, scoped: false });
    if (response?.data?.transactionId !== plan.transactionId) throw new Error("Accepted job identity did not match the confirmed plan.");
    uncertainApplyJobs[target] = null;
    observedNativeJobs[target] = { transactionId: plan.transactionId, plan, phase: response.data.phase, receipts: [], verifiedTargets: [] };
    latestUpdateStatus = { ...(latestUpdateStatus || {}), updateInProgress: true };
    addEvent(`${label} job ${plan.transactionId} launched; watching its durable status`, "info");
  } catch (error) {
    nativeJobPollError = error.message || String(error);
    uncertainApplyJobs[target] = plan.transactionId;
    observedNativeJobs[target] = { transactionId: plan.transactionId, plan, phase: "launching", receipts: [], verifiedTargets: [] };
    latestUpdateStatus = { ...(latestUpdateStatus || {}), updateInProgress: true };
    addEvent(`${label} launch was not confirmed: ${nativeJobPollError}. Checking job ${plan.transactionId} before any retry.`, "error");
  } finally {
    componentUpdateStartInProgress = false;
    renderComponentUpdateIndicators();
    renderComponentUpdateDialogs();
    syncComponentUpdatePolling();
  }
}

async function openWebuiPackageDialog() {
  const dialog = elements.webuiPackageDialog;
  if (!dialog) return;
  renderComponentUpdateDialogs();
  if (!dialog.open) dialog.showModal();
  try {
    await refreshUpdateStatus({ notify: false });
  } catch (error) {
    addEvent(`Pi/Web UI update check failed: ${error.message || String(error)}`, "warn");
  }
}

function initializeUpdateNotifications() {
  setTimeout(() => {
    refreshUpdateStatus().catch((error) => addEvent(`Pi/Web UI update check failed: ${error.message || String(error)}`, "warn"));
    scheduleUpdateStatusRefresh();
  }, UPDATE_STATUS_INITIAL_DELAY_MS);
}

function formatBytes(bytes) {
  const value = Number(bytes) || 0;
  if (value < 1024) return `${value} B`;
  const units = ["KB", "MB", "GB"];
  let scaled = value / 1024;
  for (const unit of units) {
    if (scaled < 1024 || unit === units[units.length - 1]) return `${scaled.toFixed(scaled >= 10 ? 1 : 2)} ${unit}`;
    scaled /= 1024;
  }
  return `${value} B`;
}

function inferMimeTypeFromName(name = "") {
  const ext = String(name).split(".").pop()?.toLowerCase() || "";
  const map = {
    md: "text/markdown",
    markdown: "text/markdown",
    txt: "text/plain",
    log: "text/plain",
    csv: "text/csv",
    json: "application/json",
    xml: "application/xml",
    yaml: "application/x-yaml",
    yml: "application/x-yaml",
    toml: "application/toml",
    pdf: "application/pdf",
    doc: "application/msword",
    docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    mp3: "audio/mpeg",
    wav: "audio/wav",
    m4a: "audio/mp4",
    mp4: "video/mp4",
    mov: "video/quicktime",
    webm: "video/webm",
  };
  return map[ext] || "application/octet-stream";
}

function attachmentKind(mimeType = "", name = "") {
  const type = String(mimeType || inferMimeTypeFromName(name));
  if (type.startsWith("image/")) return "image";
  if (type.startsWith("video/")) return "video";
  if (type.startsWith("audio/")) return "audio";
  if (type.startsWith("text/") || /(?:json|xml|pdf|word|excel|powerpoint|document|spreadsheet|presentation|markdown|csv)/i.test(type)) return "doc";
  return "file";
}

function attachmentIcon(kind) {
  return kind === "image" ? "🖼️" : kind === "video" ? "🎞️" : kind === "audio" ? "🎵" : kind === "doc" ? "📄" : "📎";
}

function normalizeTextAttachmentContent(text) {
  return String(text || "").replace(/\r\n?/g, "\n");
}

function textLineCount(text) {
  const normalized = normalizeTextAttachmentContent(text);
  return normalized ? normalized.split("\n").length : 0;
}

function shouldAttachTextInsteadOfComposerInput(text) {
  const normalized = normalizeTextAttachmentContent(text);
  return normalized.trim().length > 0 && textLineCount(normalized) > LONG_INPUT_ATTACHMENT_LINE_THRESHOLD;
}

function longInputAttachmentFileName() {
  const stamp = new Date().toISOString().replace(/\.\d{3}Z$/, "Z").replace(/:/g, "-");
  return `webui-input-${stamp}.txt`;
}

function makeTextAttachmentFile(text, name = longInputAttachmentFileName(), mimeType = LONG_INPUT_ATTACHMENT_MIME_TYPE) {
  const normalized = normalizeTextAttachmentContent(text);
  const fileName = String(name || longInputAttachmentFileName());
  const type = String(mimeType || LONG_INPUT_ATTACHMENT_MIME_TYPE);
  if (typeof File === "function") return new File([normalized], fileName, { type });
  const blob = new Blob([normalized], { type });
  try {
    blob.name = fileName;
    blob.lastModified = Date.now();
  } catch {
    // Older browsers may expose non-extensible Blob instances; the attachment record still carries the name.
  }
  return blob;
}

function isEditableTextAttachment(attachment) {
  const name = String(attachment?.name || "");
  const mimeType = String(attachment?.mimeType || attachment?.file?.type || inferMimeTypeFromName(name)).split(";", 1)[0].trim().toLowerCase();
  return mimeType.startsWith("text/") || /(?:json|xml|yaml|toml|markdown|csv)/i.test(mimeType) || /\.(?:txt|md|markdown|csv|json|xml|ya?ml|toml|ini|log)$/i.test(name);
}

function attachmentsForTab(tabId = activeTabId) {
  return tabId ? tabAttachments.get(tabId) || [] : [];
}

function ensureAttachmentsForTab(tabId = activeTabId) {
  if (!tabId) return [];
  if (!tabAttachments.has(tabId)) tabAttachments.set(tabId, []);
  return tabAttachments.get(tabId);
}

function hasComposerPayload() {
  return !!elements.promptInput.value.trim() || attachmentsForTab().some((attachment) => !attachment.requiresReselect);
}

function renderAttachmentTray() {
  const tray = elements.attachmentTray;
  if (!tray) return;
  const attachments = attachmentsForTab();
  tray.innerHTML = "";
  tray.hidden = attachments.length === 0;
  if (attachments.length === 0) return;

  for (const attachment of attachments) {
    const pill = make("span", "attachment-pill");
    pill.title = attachment.requiresReselect ? `${attachment.name}\nReselect required; only metadata was restored.` : `${attachment.name}\n${attachment.mimeType}\n${formatBytes(attachment.size)}`;
    pill.classList.toggle("requires-reselect", attachment.requiresReselect === true);
    let icon = make("span", "attachment-pill-icon", attachmentIcon(attachment.kind));
    if (attachment.kind === "image" && attachment.previewUrl) {
      // Show the actual picture so a pasted screenshot can be checked at a glance.
      const thumb = make("img", "attachment-pill-thumb");
      thumb.src = attachment.previewUrl;
      thumb.alt = "";
      thumb.decoding = "async";
      thumb.loading = "lazy";
      const thumbButton = make("button", "attachment-pill-thumb-button");
      thumbButton.type = "button";
      thumbButton.title = `Preview ${attachment.name}`;
      thumbButton.setAttribute("aria-label", `Preview ${attachment.name}`);
      thumbButton.append(thumb);
      thumbButton.addEventListener("click", () => openImageLightbox(attachment.previewUrl, attachment.name));
      icon = thumbButton;
    }
    const name = make("span", "attachment-pill-name", attachment.name);
    const meta = make("span", "attachment-pill-meta", attachment.requiresReselect ? `${attachment.kind} · ${formatBytes(attachment.size)} · Reselect required` : `${attachment.kind} · ${formatBytes(attachment.size)}`);
    const edit = !attachment.requiresReselect && isEditableTextAttachment(attachment) ? make("button", "attachment-edit-button", "Edit") : null;
    if (edit) {
      edit.type = "button";
      edit.setAttribute("aria-label", `Open and edit ${attachment.name}`);
      edit.addEventListener("click", () => openTextAttachmentEditor(attachment.id));
    }
    const remove = make("button", "attachment-remove-button", "×");
    remove.type = "button";
    remove.setAttribute("aria-label", `Remove ${attachment.name}`);
    remove.addEventListener("click", () => removeAttachment(attachment.id));
    pill.append(icon, name, meta);
    if (edit) pill.append(edit);
    if (attachment.requiresReselect) {
      const reselect = make("button", "attachment-edit-button", "Reselect");
      reselect.type = "button";
      reselect.setAttribute("aria-label", `Reselect ${attachment.name}`);
      reselect.addEventListener("click", () => openMobileAttachmentPicker("files"));
      pill.append(reselect);
    }
    pill.append(remove);
    tray.append(pill);
  }
}

function removeAttachment(id, tabId = activeTabId) {
  const attachments = attachmentsForTab(tabId);
  const index = attachments.findIndex((attachment) => attachment.id === id);
  if (index === -1) return;
  const [removed] = attachments.splice(index, 1);
  if (removed?.previewUrl) URL.revokeObjectURL(removed.previewUrl);
  if (activeTextAttachmentEditor?.tabId === tabId && activeTextAttachmentEditor?.attachmentId === id) closeTextAttachmentEditor({ force: true });
  if (attachments.length === 0) tabAttachments.delete(tabId);
  if (tabId === activeTabId) renderAttachmentTray();
  persistMobileContinuityState();
}

function clearAttachments(tabId = activeTabId) {
  const attachments = attachmentsForTab(tabId);
  for (const attachment of attachments) {
    if (attachment.previewUrl) URL.revokeObjectURL(attachment.previewUrl);
  }
  if (activeTextAttachmentEditor?.tabId === tabId) closeTextAttachmentEditor({ force: true });
  if (tabId) tabAttachments.delete(tabId);
  if (tabId === activeTabId) renderAttachmentTray();
  persistMobileContinuityState();
}

function addAttachmentFiles(fileList, source = "picker") {
  const files = Array.from(fileList || []).filter(Boolean);
  if (!files.length) return { added: 0, skipped: [] };
  const attachments = ensureAttachmentsForTab();
  if (!attachments.length && !activeTabId) return { added: 0, skipped: ["no active tab"] };
  if (attachments.some((attachment) => attachment.requiresReselect)) {
    attachments.splice(0, attachments.length, ...attachments.filter((attachment) => !attachment.requiresReselect));
  }
  let totalBytes = attachments.reduce((sum, attachment) => sum + attachment.size, 0);
  let added = 0;
  const skipped = [];

  for (const file of files) {
    const name = file.name || `${source}-attachment`;
    if (attachments.length >= ATTACHMENT_MAX_FILES) {
      skipped.push(`${name}: attachment limit is ${ATTACHMENT_MAX_FILES}`);
      continue;
    }
    if (file.size > ATTACHMENT_MAX_FILE_BYTES) {
      skipped.push(`${name}: larger than ${formatBytes(ATTACHMENT_MAX_FILE_BYTES)}`);
      continue;
    }
    if (totalBytes + file.size > ATTACHMENT_MAX_TOTAL_BYTES) {
      skipped.push(`${name}: total attachment limit is ${formatBytes(ATTACHMENT_MAX_TOTAL_BYTES)}`);
      continue;
    }
    const mimeType = file.type || inferMimeTypeFromName(name);
    const kind = attachmentKind(mimeType, name);
    attachments.push({
      id: `att-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      file,
      name,
      mimeType,
      size: file.size || 0,
      source,
      kind,
      previewUrl: kind === "image" ? URL.createObjectURL(file) : undefined,
    });
    totalBytes += file.size || 0;
    added++;
  }

  renderAttachmentTray();
  persistMobileContinuityState();
  if (added) addEvent(`attached ${added} ${added === 1 ? "file" : "files"} from ${source}`, "info");
  if (skipped.length) addEvent(`skipped attachments: ${skipped.join("; ")}`, "warn");
  return { added, skipped };
}

function attachLongTextAsFile(text, source = "input text") {
  if (!shouldAttachTextInsteadOfComposerInput(text)) return false;
  const normalized = normalizeTextAttachmentContent(text);
  const lineCount = textLineCount(normalized);
  const result = addAttachmentFiles([makeTextAttachmentFile(normalized)], `${lineCount}-line ${source}`);
  return result.added > 0;
}

function attachmentById(tabId, id) {
  return attachmentsForTab(tabId).find((attachment) => attachment.id === id) || null;
}

async function closeTextAttachmentEditor({ force = false } = {}) {
  if (!force && activeTextAttachmentEditor?.dirty && elements.attachmentTextDialog?.open) {
    if (!(await confirmDiscardEdits({ what: "unsaved attachment edits", target: "The attachment text" }))) return;
    activeTextAttachmentEditor.dirty = false;
  }
  if (elements.attachmentTextDialog?.open) elements.attachmentTextDialog.close();
  else activeTextAttachmentEditor = null;
}

function setAttachmentTextStatus(message = "", level = "muted") {
  if (!elements.attachmentTextStatus) return;
  elements.attachmentTextStatus.textContent = message;
  elements.attachmentTextStatus.className = `attachment-text-status ${level || "muted"}`;
}

function renderTextAttachmentEditorMeta() {
  if (!activeTextAttachmentEditor || !elements.attachmentTextMeta) return;
  const attachment = attachmentById(activeTextAttachmentEditor.tabId, activeTextAttachmentEditor.attachmentId);
  if (!attachment) {
    elements.attachmentTextMeta.textContent = "Attachment no longer exists.";
    return;
  }
  const text = elements.attachmentTextEditor?.value || "";
  const lineCount = textLineCount(text);
  elements.attachmentTextMeta.textContent = `${attachment.name} · ${attachment.mimeType} · ${formatBytes(attachment.size)} · ${lineCount} ${lineCount === 1 ? "line" : "lines"}`;
}

function readFileAsText(file) {
  if (typeof file?.text === "function") return file.text();
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error || new Error("Failed to read text attachment"));
    reader.onload = () => resolve(String(reader.result || ""));
    reader.readAsText(file);
  });
}

async function openTextAttachmentEditor(attachmentId, tabId = activeTabId) {
  const attachment = attachmentById(tabId, attachmentId);
  if (!attachment) return;
  if (!isEditableTextAttachment(attachment)) {
    addEvent(`${attachment.name || "attachment"} is not editable text`, "warn");
    return;
  }

  activeTextAttachmentEditor = { tabId, attachmentId };
  if (elements.attachmentTextTitle) elements.attachmentTextTitle.textContent = `Edit ${attachment.name || "text attachment"}`;
  if (elements.attachmentTextEditor) elements.attachmentTextEditor.value = "";
  if (elements.attachmentTextSaveButton) elements.attachmentTextSaveButton.disabled = true;
  renderTextAttachmentEditorMeta();
  setAttachmentTextStatus("Loading text attachment…", "muted");
  if (elements.attachmentTextDialog && !elements.attachmentTextDialog.open) elements.attachmentTextDialog.showModal();

  try {
    const text = await readFileAsText(attachment.file);
    if (activeTextAttachmentEditor?.tabId !== tabId || activeTextAttachmentEditor?.attachmentId !== attachmentId) return;
    if (elements.attachmentTextEditor) elements.attachmentTextEditor.value = normalizeTextAttachmentContent(text);
    if (elements.attachmentTextSaveButton) elements.attachmentTextSaveButton.disabled = false;
    renderTextAttachmentEditorMeta();
    setAttachmentTextStatus("Edit the text, then save it back to the attachment.", "muted");
    queueMicrotask(() => elements.attachmentTextEditor?.focus());
  } catch (error) {
    if (elements.attachmentTextSaveButton) elements.attachmentTextSaveButton.disabled = true;
    setAttachmentTextStatus(`Failed to open text attachment: ${error.message || String(error)}`, "error");
  }
}

function totalAttachmentBytesWithReplacement(tabId, attachmentId, nextSize) {
  return attachmentsForTab(tabId).reduce((sum, attachment) => sum + (attachment.id === attachmentId ? nextSize : attachment.size || 0), 0);
}

function saveTextAttachmentEdit() {
  if (!activeTextAttachmentEditor) return;
  const { tabId, attachmentId } = activeTextAttachmentEditor;
  const attachment = attachmentById(tabId, attachmentId);
  if (!attachment) {
    setAttachmentTextStatus("Attachment no longer exists.", "error");
    return;
  }

  const text = elements.attachmentTextEditor?.value || "";
  const name = attachment.name || longInputAttachmentFileName();
  const mimeType = attachment.mimeType || inferMimeTypeFromName(name) || LONG_INPUT_ATTACHMENT_MIME_TYPE;
  const nextFile = makeTextAttachmentFile(text, name, mimeType);
  if (nextFile.size > ATTACHMENT_MAX_FILE_BYTES) {
    setAttachmentTextStatus(`Edited file is larger than ${formatBytes(ATTACHMENT_MAX_FILE_BYTES)}.`, "error");
    return;
  }
  if (totalAttachmentBytesWithReplacement(tabId, attachmentId, nextFile.size) > ATTACHMENT_MAX_TOTAL_BYTES) {
    setAttachmentTextStatus(`Edited attachments exceed ${formatBytes(ATTACHMENT_MAX_TOTAL_BYTES)} total.`, "error");
    return;
  }

  if (attachment.previewUrl) URL.revokeObjectURL(attachment.previewUrl);
  attachment.file = nextFile;
  attachment.name = name;
  attachment.mimeType = nextFile.type || mimeType;
  attachment.size = nextFile.size || 0;
  attachment.kind = attachmentKind(attachment.mimeType, attachment.name);
  attachment.previewUrl = undefined;
  if (tabId === activeTabId) renderAttachmentTray();
  addEvent(`updated text attachment ${attachment.name} (${formatBytes(attachment.size)})`, "info");
  closeTextAttachmentEditor({ force: true });
}

function clipboardFiles(dataTransfer) {
  const files = [];
  const seen = new Set();
  for (const file of Array.from(dataTransfer?.files || [])) {
    const key = `${file.name}:${file.size}:${file.type}`;
    if (!seen.has(key)) {
      seen.add(key);
      files.push(file);
    }
  }
  for (const item of Array.from(dataTransfer?.items || [])) {
    if (item.kind !== "file") continue;
    const file = item.getAsFile?.();
    if (!file) continue;
    const key = `${file.name}:${file.size}:${file.type}`;
    if (!seen.has(key)) {
      seen.add(key);
      files.push(file);
    }
  }
  return files;
}

function handleAttachmentPaste(event) {
  const files = clipboardFiles(event.clipboardData);
  if (files.length) {
    event.preventDefault();
    addAttachmentFiles(files, "clipboard");
    return;
  }

  const text = event.clipboardData?.getData("text/plain") || "";
  if (!attachLongTextAsFile(text, "clipboard text")) return;
  event.preventDefault();
}

function isFileDrag(event) {
  return Array.from(event.dataTransfer?.types || []).includes("Files");
}

function handleComposerDragOver(event) {
  if (event.target?.closest?.("#followUpQueueOverlay") || !isFileDrag(event)) return;
  event.preventDefault();
  elements.composer.classList.add("drag-over");
}

function handleComposerDragLeave(event) {
  if (event.target?.closest?.("#followUpQueueOverlay")) return;
  if (!elements.composer.contains(event.relatedTarget)) elements.composer.classList.remove("drag-over");
}

function handleComposerDrop(event) {
  if (event.target?.closest?.("#followUpQueueOverlay") || !isFileDrag(event)) return;
  event.preventDefault();
  elements.composer.classList.remove("drag-over");
  addAttachmentFiles(event.dataTransfer?.files, "drop");
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error || new Error("Failed to read attachment"));
    reader.onload = () => {
      const result = String(reader.result || "");
      const comma = result.indexOf(",");
      resolve(comma === -1 ? result : result.slice(comma + 1));
    };
    reader.readAsDataURL(file);
  });
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error || new Error("Failed to read background image"));
    reader.onload = () => resolve(String(reader.result || ""));
    reader.readAsDataURL(file);
  });
}

function sanitizeBackgroundName(name) {
  const safe = String(name || "custom background").replace(/[\r\n]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 120);
  return safe || "custom background";
}

function backgroundMimeType(file) {
  const declared = String(file?.type || "").split(";", 1)[0].trim().toLowerCase();
  if (BACKGROUND_IMAGE_MIME_TYPES.has(declared)) return declared;
  const ext = String(file?.name || "").split(".").pop()?.toLowerCase() || "";
  const byExt = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", webp: "image/webp", gif: "image/gif" };
  return byExt[ext] || declared || "application/octet-stream";
}

function normalizeCustomBackgroundRecord(value) {
  if (!value || typeof value !== "object") return null;
  const dataUrl = String(value.dataUrl || "");
  const match = dataUrl.match(/^data:(image\/(?:png|jpeg|webp|gif));base64,[A-Za-z0-9+/]+={0,2}$/i);
  if (!match) return null;
  return {
    name: sanitizeBackgroundName(value.name),
    mimeType: match[1].toLowerCase(),
    size: Math.max(0, Number(value.size) || 0),
    dataUrl,
    updatedAt: Number(value.updatedAt) || Date.now(),
  };
}

function dataUrlToBlob(dataUrl) {
  const match = String(dataUrl || "").match(/^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/]+={0,2})$/i);
  if (!match) throw new Error("Invalid background data URL");
  const binary = atob(match[2]);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
  return new Blob([bytes], { type: match[1].toLowerCase() });
}

function revokeCustomBackgroundObjectUrl() {
  if (!customBackgroundObjectUrl) return;
  URL.revokeObjectURL(customBackgroundObjectUrl);
  customBackgroundObjectUrl = null;
}

function setCustomBackgroundRecord(background, { objectUrl = null } = {}) {
  const record = normalizeCustomBackgroundRecord(background);
  revokeCustomBackgroundObjectUrl();
  customBackground = record;
  if (!record) return null;
  if (objectUrl) customBackgroundObjectUrl = objectUrl;
  else {
    try {
      customBackgroundObjectUrl = URL.createObjectURL(dataUrlToBlob(record.dataUrl));
    } catch {
      customBackgroundObjectUrl = null;
    }
  }
  return record;
}

function idbRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("IndexedDB request failed"));
  });
}

function idbTransactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error || new Error("IndexedDB transaction failed"));
    transaction.onabort = () => reject(transaction.error || new Error("IndexedDB transaction aborted"));
  });
}

function openCustomBackgroundDb() {
  return new Promise((resolve, reject) => {
    const indexedDb = window.indexedDB;
    if (!indexedDb) {
      reject(new Error("IndexedDB unavailable"));
      return;
    }
    const request = indexedDb.open(CUSTOM_BACKGROUND_IDB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(CUSTOM_BACKGROUND_IDB_STORE)) db.createObjectStore(CUSTOM_BACKGROUND_IDB_STORE);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("Failed to open background storage"));
  });
}

function customBackgroundThemeKey(themeName = currentThemeName) {
  return String(themeName || DEFAULT_THEME_NAME).trim() || DEFAULT_THEME_NAME;
}

async function readCustomBackgroundFromIndexedDb(themeName = currentThemeName) {
  const db = await openCustomBackgroundDb();
  try {
    return await idbRequest(db.transaction(CUSTOM_BACKGROUND_IDB_STORE, "readonly").objectStore(CUSTOM_BACKGROUND_IDB_STORE).get(customBackgroundThemeKey(themeName)));
  } finally {
    db.close();
  }
}

async function readLegacyCustomBackgroundFromIndexedDb() {
  const db = await openCustomBackgroundDb();
  try {
    return await idbRequest(db.transaction(CUSTOM_BACKGROUND_IDB_STORE, "readonly").objectStore(CUSTOM_BACKGROUND_IDB_STORE).get(CUSTOM_BACKGROUND_LEGACY_ID));
  } finally {
    db.close();
  }
}

async function writeCustomBackgroundToIndexedDb(background, themeName = currentThemeName) {
  const db = await openCustomBackgroundDb();
  try {
    const transaction = db.transaction(CUSTOM_BACKGROUND_IDB_STORE, "readwrite");
    transaction.objectStore(CUSTOM_BACKGROUND_IDB_STORE).put(background, customBackgroundThemeKey(themeName));
    await idbTransactionDone(transaction);
  } finally {
    db.close();
  }
}

async function deleteCustomBackgroundFromIndexedDb(themeName = currentThemeName) {
  const db = await openCustomBackgroundDb();
  try {
    const transaction = db.transaction(CUSTOM_BACKGROUND_IDB_STORE, "readwrite");
    transaction.objectStore(CUSTOM_BACKGROUND_IDB_STORE).delete(customBackgroundThemeKey(themeName));
    await idbTransactionDone(transaction);
  } finally {
    db.close();
  }
}

async function deleteLegacyCustomBackgroundFromIndexedDb() {
  const db = await openCustomBackgroundDb();
  try {
    const transaction = db.transaction(CUSTOM_BACKGROUND_IDB_STORE, "readwrite");
    transaction.objectStore(CUSTOM_BACKGROUND_IDB_STORE).delete(CUSTOM_BACKGROUND_LEGACY_ID);
    await idbTransactionDone(transaction);
  } finally {
    db.close();
  }
}

function readCustomBackgroundFromLocalStorage(themeName = currentThemeName, { includeLegacy = false } = {}) {
  try {
    const parsed = JSON.parse(localStorage.getItem(CUSTOM_BACKGROUNDS_STORAGE_KEY) || "{}");
    const record = parsed && typeof parsed === "object" ? normalizeCustomBackgroundRecord(parsed[customBackgroundThemeKey(themeName)]) : null;
    if (record) return record;
  } catch {
    // Fall through to legacy storage below.
  }
  if (!includeLegacy) return null;
  try {
    return normalizeCustomBackgroundRecord(JSON.parse(localStorage.getItem(CUSTOM_BACKGROUND_STORAGE_KEY) || "null"));
  } catch {
    return null;
  }
}

function writeCustomBackgroundToLocalStorage(background, themeName = currentThemeName) {
  const record = normalizeCustomBackgroundRecord(background);
  if (!record) throw new Error("Invalid background image data");
  const key = customBackgroundThemeKey(themeName);
  const parsed = JSON.parse(localStorage.getItem(CUSTOM_BACKGROUNDS_STORAGE_KEY) || "{}");
  const backgrounds = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  backgrounds[key] = record;
  localStorage.setItem(CUSTOM_BACKGROUNDS_STORAGE_KEY, JSON.stringify(backgrounds));
}

function removeCustomBackgroundFromLocalStorage(themeName = currentThemeName, { includeLegacy = false } = {}) {
  const key = customBackgroundThemeKey(themeName);
  try {
    const parsed = JSON.parse(localStorage.getItem(CUSTOM_BACKGROUNDS_STORAGE_KEY) || "{}");
    const backgrounds = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    delete backgrounds[key];
    localStorage.setItem(CUSTOM_BACKGROUNDS_STORAGE_KEY, JSON.stringify(backgrounds));
  } catch {
    // Ignore fallback cleanup failures.
  }
  if (includeLegacy) {
    try {
      localStorage.removeItem(CUSTOM_BACKGROUND_STORAGE_KEY);
    } catch {
      // Ignore legacy cleanup failures.
    }
  }
}

async function readStoredCustomBackground(themeName = currentThemeName, { includeLegacy = false } = {}) {
  try {
    const stored = normalizeCustomBackgroundRecord(await readCustomBackgroundFromIndexedDb(themeName));
    if (stored) return stored;
    if (includeLegacy) {
      const legacy = normalizeCustomBackgroundRecord(await readLegacyCustomBackgroundFromIndexedDb());
      if (legacy) return legacy;
    }
  } catch {
    // Fall back to localStorage for older browsers or private browsing modes.
  }
  return readCustomBackgroundFromLocalStorage(themeName, { includeLegacy });
}

async function persistCustomBackground(background, themeName = currentThemeName) {
  const record = normalizeCustomBackgroundRecord(background);
  if (!record) throw new Error("Invalid background image data");
  try {
    await writeCustomBackgroundToIndexedDb(record, themeName);
    removeCustomBackgroundFromLocalStorage(themeName);
    return;
  } catch {
    // Fall back to localStorage when IndexedDB is unavailable.
  }
  writeCustomBackgroundToLocalStorage(record, themeName);
}

async function clearStoredCustomBackground(themeName = currentThemeName, { includeLegacy = false } = {}) {
  await Promise.allSettled([
    deleteCustomBackgroundFromIndexedDb(themeName),
    includeLegacy ? deleteLegacyCustomBackgroundFromIndexedDb() : Promise.resolve(),
    Promise.resolve().then(() => removeCustomBackgroundFromLocalStorage(themeName, { includeLegacy })),
  ]);
}

function customBackgroundCssImage(background = customBackground) {
  if (!background?.dataUrl) return null;
  return `url("${customBackgroundObjectUrl || background.dataUrl}")`;
}

function renderBackgroundControl() {
  if (!elements.backgroundStatus) return;
  const active = !!customBackground?.dataUrl;
  const themeLabel = displayThemeName(currentThemeName) || currentThemeName || "theme";
  elements.backgroundStatus.textContent = customBackgroundLoading
    ? `Loading ${themeLabel} background…`
    : active
      ? `${themeLabel}: ${customBackground.name || "background"}`
      : `${themeLabel}: theme default`;
  if (elements.backgroundChooseButton) {
    elements.backgroundChooseButton.disabled = customBackgroundLoading;
    elements.backgroundChooseButton.textContent = active ? "Change image" : "Choose image";
  }
  if (elements.backgroundInput) elements.backgroundInput.disabled = customBackgroundLoading;
  if (elements.backgroundClearButton) {
    elements.backgroundClearButton.hidden = !active;
    elements.backgroundClearButton.disabled = customBackgroundLoading;
  }
}

function applyCustomBackgroundOverride({ render = true } = {}) {
  const activeImage = customBackgroundCssImage();
  document.body.classList.toggle("custom-background-active", !!activeImage);
  if (activeImage) document.documentElement.style.setProperty("--theme-background-image", activeImage);
  if (render) renderBackgroundControl();
}

function reapplyCurrentThemeBackground() {
  const theme = availableThemes.find((item) => item.name === currentThemeName);
  if (theme && isOptionalFeatureEnabled("themeBundle")) applyTheme(theme, { persist: false });
  else {
    document.documentElement.style.setProperty("--theme-background-image", "none");
    applyCustomBackgroundOverride();
  }
}

async function loadCustomBackgroundForTheme(themeName = currentThemeName, { includeLegacy = false } = {}) {
  const themeKey = customBackgroundThemeKey(themeName);
  customBackgroundLoading = true;
  renderBackgroundControl();
  try {
    const background = await readStoredCustomBackground(themeKey, { includeLegacy });
    if (customBackgroundThemeKey(currentThemeName) !== themeKey) return;
    setCustomBackgroundRecord(background);
    if (background && includeLegacy) {
      persistCustomBackground(background, themeKey).catch(() => {});
    }
  } catch (error) {
    if (customBackgroundThemeKey(currentThemeName) === themeKey) {
      addEvent(`failed to load ${displayThemeName(themeKey) || themeKey} background: ${error.message || String(error)}`, "warn");
      setCustomBackgroundRecord(null);
    }
  } finally {
    if (customBackgroundThemeKey(currentThemeName) === themeKey) {
      customBackgroundLoading = false;
      applyCustomBackgroundOverride();
    }
  }
}

async function setCustomBackgroundFromFile(file) {
  if (!file) return;
  const mimeType = backgroundMimeType(file);
  if (!BACKGROUND_IMAGE_MIME_TYPES.has(mimeType)) {
    addEvent("background must be a PNG, JPEG, WebP, or GIF image", "error");
    return;
  }
  if ((file.size || 0) > CUSTOM_BACKGROUND_MAX_FILE_BYTES) {
    addEvent(`background image is larger than ${formatBytes(CUSTOM_BACKGROUND_MAX_FILE_BYTES)}`, "error");
    return;
  }

  const themeName = customBackgroundThemeKey(currentThemeName);
  customBackgroundLoading = true;
  renderBackgroundControl();
  try {
    const rawDataUrl = await readFileAsDataUrl(file);
    const dataUrl = rawDataUrl.replace(/^data:;base64,/i, `data:${mimeType};base64,`);
    const background = normalizeCustomBackgroundRecord({
      name: file.name,
      mimeType,
      size: file.size || 0,
      dataUrl,
      updatedAt: Date.now(),
    });
    if (!background) throw new Error("Unsupported or invalid background image data");
    let objectUrl = null;
    try {
      objectUrl = URL.createObjectURL(file);
    } catch {
      objectUrl = null;
    }
    const targetStillActive = customBackgroundThemeKey(currentThemeName) === themeName;
    if (targetStillActive) {
      setCustomBackgroundRecord(background, { objectUrl });
      applyCustomBackgroundOverride({ render: false });
    } else if (objectUrl) {
      URL.revokeObjectURL(objectUrl);
    }
    try {
      await persistCustomBackground(background, themeName);
      addEvent(`custom background saved for ${displayThemeName(themeName) || themeName}: ${background.name}`);
    } catch (error) {
      addEvent(`background changed for this page, but persistent save failed: ${error.message || String(error)}`, "warn");
    }
  } catch (error) {
    addEvent(`failed to set background: ${error.message || String(error)}`, "error");
  } finally {
    if (customBackgroundThemeKey(currentThemeName) === themeName) {
      customBackgroundLoading = false;
      renderBackgroundControl();
    }
  }
}

async function clearCustomBackground() {
  const themeName = customBackgroundThemeKey(currentThemeName);
  const hadBackground = !!customBackground?.dataUrl;
  setCustomBackgroundRecord(null);
  customBackgroundLoading = true;
  renderBackgroundControl();
  await clearStoredCustomBackground(themeName, { includeLegacy: true });
  customBackgroundLoading = false;
  reapplyCurrentThemeBackground();
  renderBackgroundControl();
  if (hadBackground) addEvent(`custom background removed for ${displayThemeName(themeName) || themeName}`);
}

async function initializeCustomBackground() {
  await loadCustomBackgroundForTheme(currentThemeName, { includeLegacy: true });
}

async function prepareAttachmentsForPrompt(attachments, tabId) {
  if (!attachments.length) return { images: [], uploadedFiles: [], inlineImageIds: new Set() };
  const files = [];
  const images = [];
  const inlineImageIds = new Set();
  let inlineImageBytes = 0;

  for (const attachment of attachments) {
    const data = await readFileAsBase64(attachment.file);
    files.push({
      id: attachment.id,
      name: attachment.name,
      mimeType: attachment.mimeType,
      size: attachment.size,
      data,
    });
    if (
      INLINE_IMAGE_MIME_TYPES.has(attachment.mimeType) &&
      attachment.size <= ATTACHMENT_INLINE_IMAGE_MAX_BYTES &&
      inlineImageBytes + attachment.size <= ATTACHMENT_INLINE_IMAGE_TOTAL_MAX_BYTES
    ) {
      images.push({ type: "image", data, mimeType: attachment.mimeType });
      inlineImageIds.add(attachment.id);
      inlineImageBytes += attachment.size;
    }
  }

  const response = await api("/api/attachments", { method: "POST", body: { files }, tabId });
  return { images, uploadedFiles: response.data?.files || [], inlineImageIds };
}

function composeMessageWithAttachments(message, uploadedFiles, inlineImageIds) {
  if (!uploadedFiles.length) return message;
  const baseMessage = message || "Please inspect the attached file(s).";
  const lines = uploadedFiles.map((file, index) => {
    const inlineNote = inlineImageIds.has(file.id) ? "sent inline and saved at" : "saved at";
    return `- ${index + 1}. ${file.name || "attachment"} (${file.mimeType || "application/octet-stream"}, ${formatBytes(file.size)}): ${inlineNote} ${file.path}`;
  });
  return `${baseMessage}\n\nAttached files:\n${lines.join("\n")}`;
}

function storedThemeName() {
  try {
    return localStorage.getItem(THEME_STORAGE_KEY) || DEFAULT_THEME_NAME;
  } catch {
    return DEFAULT_THEME_NAME;
  }
}

function storeThemeName(name) {
  try {
    localStorage.setItem(THEME_STORAGE_KEY, name);
  } catch {
    // Ignore storage failures; theme switching should still work for this page load.
  }
}

function storedThemeMode() {
  try {
    const raw = localStorage.getItem(THEME_MODE_STORAGE_KEY);
    return THEME_SCHEME_MODES.has(raw) ? raw : null;
  } catch {
    return null;
  }
}

function storeThemeMode(mode) {
  try {
    localStorage.setItem(THEME_MODE_STORAGE_KEY, mode);
  } catch {
    // Ignore storage failures; the mode still applies for this page load.
  }
}

function storedSchemeTheme(scheme) {
  const key = scheme === "dark" ? THEME_DARK_STORAGE_KEY : THEME_LIGHT_STORAGE_KEY;
  const fallback = scheme === "dark" ? THEME_DARK_DEFAULT : THEME_LIGHT_DEFAULT;
  try {
    return localStorage.getItem(key) || fallback;
  } catch {
    return fallback;
  }
}

function storeSchemeTheme(scheme, name) {
  const key = scheme === "dark" ? THEME_DARK_STORAGE_KEY : THEME_LIGHT_STORAGE_KEY;
  try {
    localStorage.setItem(key, name);
  } catch {
    // Ignore storage failures.
  }
}

function loadDisabledOptionalFeatures() {
  try {
    const parsed = JSON.parse(localStorage.getItem(OPTIONAL_FEATURES_STORAGE_KEY) || "[]");
    return Array.isArray(parsed) ? parsed.filter((id) => OPTIONAL_FEATURE_BY_ID.has(id)) : [];
  } catch {
    return [];
  }
}

let disabledOptionalFeatures = new Set(loadDisabledOptionalFeatures());
const optionalFeatureManagedAccessEnabled = new Map();
const optionalFeatureAccessInProgress = new Set();

function storeDisabledOptionalFeatures() {
  try {
    localStorage.setItem(OPTIONAL_FEATURES_STORAGE_KEY, JSON.stringify([...disabledOptionalFeatures].sort()));
  } catch {
    // Optional feature toggles should still work for this page load.
  }
}

function reconcileDisabledOptionalFeaturesFromStorage() {
  const nextDisabled = new Set(loadDisabledOptionalFeatures());
  let changed = nextDisabled.size !== disabledOptionalFeatures.size;
  if (!changed) {
    for (const featureId of nextDisabled) {
      if (!disabledOptionalFeatures.has(featureId)) {
        changed = true;
        break;
      }
    }
  }
  if (!changed) return false;
  disabledOptionalFeatures = nextDisabled;
  renderOptionalFeatureDependentDisplays();
  return true;
}

function isOptionalFeatureDetected(featureId) {
  return optionalFeatureAvailability[featureId] === true;
}

function isOptionalFeatureDisabled(featureId) {
  const feature = OPTIONAL_FEATURE_BY_ID.get(featureId);
  if (feature?.manageWith === "tools" && optionalFeatureManagedAccessEnabled.has(featureId)) {
    return optionalFeatureManagedAccessEnabled.get(featureId) === false;
  }
  return disabledOptionalFeatures.has(featureId);
}

function isOptionalFeatureEnabled(featureId) {
  return isOptionalFeatureDetected(featureId) && !isOptionalFeatureDisabled(featureId);
}

function defaultWorkflowModeState(patch = {}) {
  return {
    available: false,
    enabled: false,
    phase: "off",
    behavior: "persistent",
    statusText: "",
    updatedAt: "",
    ...patch,
  };
}

function normalizeWorkflowModeState(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const enabled = source.enabled === true;
  const phase = enabled && source.phase === "running" ? "running" : enabled ? "armed" : "off";
  const behavior = source.behavior === "once" ? "once" : "persistent";
  return defaultWorkflowModeState({
    ...source,
    available: source.available === true,
    enabled,
    phase,
    behavior,
    statusText: cleanStatusText(source.statusText || ""),
  });
}

function workflowModeStateFromStatus(statusText = "") {
  const text = cleanStatusText(statusText || "");
  const match = text.match(/^workflow\s*:\s*(on|once|running)$/i);
  return normalizeWorkflowModeState({
    available: true,
    enabled: !!match,
    behavior: match?.[1]?.toLowerCase() === "once" ? "once" : "persistent",
    phase: match?.[1]?.toLowerCase() === "running" ? "running" : match ? "armed" : "off",
    statusText: text,
    updatedAt: new Date().toISOString(),
  });
}

function workflowModeStateFromRpcPayload(lines) {
  const raw = String(lines?.[0] || "").trim();
  if (!raw.startsWith(WORKFLOW_MODE_RPC_PAYLOAD_PREFIX)) return null;
  try {
    const payload = JSON.parse(raw.slice(WORKFLOW_MODE_RPC_PAYLOAD_PREFIX.length));
    if (payload?.type !== WORKFLOW_MODE_RPC_PAYLOAD_TYPE || payload.version !== WORKFLOW_MODE_RPC_PAYLOAD_VERSION) return null;
    if (typeof payload.enabled !== "boolean" || !["persistent", "once"].includes(payload.behavior) || !["off", "armed", "running"].includes(payload.phase)) return null;
    return normalizeWorkflowModeState({
      available: true,
      enabled: payload.enabled,
      behavior: payload.behavior,
      phase: payload.phase,
      statusText: payload.enabled ? `Workflow: ${payload.phase === "running" ? "running" : payload.behavior === "once" ? "once" : "on"}` : "",
      updatedAt: typeof payload.updatedAt === "string" ? payload.updatedAt : new Date().toISOString(),
    });
  } catch {
    return null;
  }
}

function updateWorkflowModeForTab(tabId = activeTabId, mode = {}, { render = true } = {}) {
  if (!tabId) return normalizeWorkflowModeState(mode);
  const previous = workflowModeByTab.get(tabId) || {};
  const next = normalizeWorkflowModeState({ ...previous, ...mode });
  workflowModeByTab.set(tabId, next);
  if (tabId === activeTabId && render) renderWorkflowModeControls();
  return next;
}

function activeWorkflowMode() {
  return normalizeWorkflowModeState(workflowModeByTab.get(activeTabId) || {});
}

function workflowModeCommandName() {
  return resolveAvailableCommandName("workflow", { rpcOnly: true }) || "";
}

function workflowOverlayHasContent() {
  if (!isOptionalFeatureEnabled("workflows")) return false;
  const inspector = activeWorkflowInspectorPayload();
  if (inspector?.runs?.length) return true;
  if (getWidgetLines("workflow").length) return true;
  return !!parseWorkflowSubprocessPayload(getWidgetLines("workflow:subprocess"));
}

function workflowOverlayIsMinimized() {
  return Boolean(activeTabId && workflowOverlayMinimizedByTab.has(activeTabId));
}

function renderWorkflowOverlayControls() {
  const openAvailable = workflowOverlayHasContent() && workflowOverlayIsMinimized();
  if (elements.workflowOverlayOpenButton) {
    elements.workflowOverlayOpenButton.hidden = !openAvailable;
    elements.workflowOverlayOpenButton.setAttribute("aria-expanded", openAvailable ? "false" : "true");
    applyStyledTooltip(elements.workflowOverlayOpenButton, "Open the minimized workflow overlay.", { ariaLabel: true, align: "end" });
  }
  if (elements.workflowModeControls) {
    elements.workflowModeControls.hidden = Boolean(elements.workflowModeButton?.hidden) && !openAvailable;
    elements.workflowModeControls.classList.toggle("has-open-control", openAvailable);
  }
}

function setWorkflowOverlayMinimized(minimized) {
  if (!activeTabId || !workflowOverlayHasContent()) return;
  const tabId = activeTabId;
  if (minimized) workflowOverlayMinimizedByTab.add(tabId);
  else workflowOverlayMinimizedByTab.delete(tabId);
  renderWidgets();
  renderWorkflowModeControls();
  requestAnimationFrame(() => {
    if (activeTabId !== tabId) return;
    const focusTarget = minimized
      ? elements.workflowOverlayOpenButton
      : elements.widgetArea.querySelector(".workflow-overlay-close-button");
    focusTarget?.focus({ preventScroll: true });
  });
}

function renderWorkflowModeControls() {
  const mode = activeWorkflowMode();
  const commandName = workflowModeCommandName();
  const commandAvailable = !!commandName && isOptionalFeatureEnabled("workflows");
  const active = mode.enabled === true;
  const pending = !!activeTabId && workflowModeTogglePendingByTab.has(activeTabId);
  document.body.classList.toggle("workflow-mode-active", active);
  elements.composer?.classList.toggle("workflow-mode-active", active);

  if (elements.workflowModeButton) {
    elements.workflowModeButton.hidden = !commandAvailable && !active;
    elements.workflowModeButton.disabled = !commandName || pending;
    elements.workflowModeButton.classList.toggle("active", active);
    elements.workflowModeButton.setAttribute("aria-pressed", active ? "true" : "false");
    if (pending) elements.workflowModeButton.setAttribute("aria-busy", "true");
    else elements.workflowModeButton.removeAttribute("aria-busy");
    const tooltip = pending
      ? "Updating JavaScript Workflow Mode for this Pi tab."
      : commandName
        ? `${active ? "Disable" : "Enable"} JavaScript Workflow Mode for this Pi tab via /${commandName} mode ${active ? "off" : "on"}.`
        : "Workflow Mode is unavailable because the /workflow command is not loaded.";
    applyStyledTooltip(elements.workflowModeButton, tooltip, { ariaLabel: true, align: "end" });
  }
  renderWorkflowOverlayControls();

  if (elements.workflowModeChip) {
    elements.workflowModeChip.hidden = !active;
    elements.workflowModeChip.disabled = !commandName || pending;
    elements.workflowModeChip.textContent = mode.phase === "running" ? "Workflow: running" : mode.behavior === "once" ? "Workflow: once" : "Workflow: on";
    elements.workflowModeChip.setAttribute("aria-pressed", "true");
    elements.workflowModeChip.title = "Workflow Mode is active. Click to return this tab to normal Pi prompting.";
    elements.workflowModeChip.setAttribute("aria-label", `${elements.workflowModeChip.textContent}. Click to disable Workflow Mode.`);
  }
}

function handleWorkflowModeStatus(statusText, tabId = activeTabId) {
  updateWorkflowModeForTab(tabId, workflowModeStateFromStatus(statusText), { render: tabId === activeTabId });
}

async function setWorkflowModeEnabled(enabled) {
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  const commandName = workflowModeCommandName();
  if (!commandName) {
    addEvent("Workflow Mode is unavailable because the /workflow command is not loaded.", "warn");
    await refreshCommands(tabContext);
    return;
  }

  workflowModeTogglePendingByTab.add(tabContext.tabId);
  renderWorkflowModeControls();
  setComposerActionsOpen(false);
  try {
    await sendPrompt("prompt", `/${commandName} mode ${enabled ? "on" : "off"}`, { targetTabId: tabContext.tabId, throwOnError: true });
    if (!isCurrentTabContext(tabContext)) return;
    updateWorkflowModeForTab(tabContext.tabId, {
      available: true,
      enabled: enabled === true,
      phase: enabled ? "armed" : "off",
      statusText: enabled ? "Workflow: on" : "",
      updatedAt: new Date().toISOString(),
    });
    addEvent(enabled ? "Workflow Mode enabled for this tab." : "Workflow Mode disabled for this tab.", "info");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
  } finally {
    workflowModeTogglePendingByTab.delete(tabContext.tabId);
    if (isCurrentTabContext(tabContext)) renderWorkflowModeControls();
  }
}

function toggleWorkflowMode() {
  return setWorkflowModeEnabled(!activeWorkflowMode().enabled);
}

function defaultConversationModeState(patch = {}) {
  return {
    featureId: "naturalConversation",
    available: false,
    enabled: false,
    uiState: "off",
    statusText: "",
    partialTranscript: "",
    allowedTools: ["read", "grep", "find", "ls"],
    provider: "browser-shell",
    startedAt: null,
    packageInstalled: false,
    loadedCommands: [],
    updatedAt: "",
    ...patch,
  };
}

function normalizeConversationModeState(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const enabled = source.enabled === true;
  return defaultConversationModeState({
    ...source,
    available: source.available === true,
    enabled,
    uiState: enabled ? cleanStatusText(source.uiState || "listening").toLowerCase() || "listening" : "off",
    statusText: cleanStatusText(source.statusText || ""),
    partialTranscript: cleanStatusText(source.partialTranscript || ""),
    allowedTools: Array.isArray(source.allowedTools) && source.allowedTools.length ? source.allowedTools.map((name) => String(name)).filter(Boolean) : ["read", "grep", "find", "ls"],
    packageInstalled: source.packageInstalled === true,
    loadedCommands: Array.isArray(source.loadedCommands) ? source.loadedCommands.map((name) => String(name)).filter(Boolean) : [],
  });
}

function updateConversationModeForTab(tabId = activeTabId, mode = {}, { render = true, voiceLoop = false } = {}) {
  if (!tabId) return normalizeConversationModeState(mode);
  const previous = conversationModeByTab.get(tabId) || tabs.find((tab) => tab.id === tabId)?.conversationMode || {};
  let patch = mode && typeof mode === "object" ? mode : {};
  if (!voiceLoop && patch.enabled !== false && voiceConversationActiveFor(tabId)) {
    // While the browser voice loop runs, it owns uiState/statusText; server
    // snapshots would otherwise reset "speaking"/"transcribing" to "listening".
    patch = { ...patch };
    delete patch.uiState;
    delete patch.statusText;
  }
  const next = normalizeConversationModeState({ ...previous, ...patch });
  conversationModeByTab.set(tabId, next);
  if (tabId === activeTabId && render) renderConversationModeControls();
  return next;
}

function activeConversationMode() {
  return normalizeConversationModeState(conversationModeByTab.get(activeTabId) || activeTab()?.conversationMode || {});
}

function conversationModeCommandName() {
  for (const name of NATURAL_CONVERSATION_COMMAND_NAMES) {
    const resolved = resolveAvailableCommandName(name, { rpcOnly: true });
    if (resolved) return resolved;
  }
  return "";
}

function conversationModeButtonLabel(mode = activeConversationMode()) {
  return mode.enabled ? "End Conversation" : "Start Natural Conversation";
}

function conversationModePartialPreview(text = "") {
  const normalized = cleanStatusText(text || "");
  if (!normalized) return "";
  return normalized.length > 42 ? `${normalized.slice(0, 39)}…` : normalized;
}

// Declared before renderConversationModeControls ever runs (it is called
// during initial render passes) so the voice-menu block never hits a TDZ.
let conversationVoiceSwitching = false;
let conversationVoicesLoadedForTab = null;
let conversationVoiceMenuOpen = false;
let conversationVoiceLastData = null;
let conversationVoicePending = null;

// Same open/close contract as the Common-Pi-options menu: click toggles the
// panel (hover/focus-within still work on desktop via CSS), so it also works
// on touch devices where :hover never fires.
function setConversationVoiceMenuOpen(open) {
  if (open && followUpQueueOpen) setFollowUpQueueOpen(false);
  conversationVoiceMenuOpen = !!open;
  elements.conversationVoiceButton?.setAttribute("aria-expanded", conversationVoiceMenuOpen ? "true" : "false");
  elements.conversationVoiceButton?.classList.toggle("menu-open", conversationVoiceMenuOpen);
  elements.conversationVoiceMenu?.classList.toggle("open", conversationVoiceMenuOpen);
  scheduleMobileDropdownScrollBoundsUpdate();
}

function conversationModeDisplayText(mode = activeConversationMode()) {
  if (!mode.enabled) return "Voice: off";
  // Voice-switch progress ("downloading de_DE-thorsten-high 42%", "testing …")
  // arrives via the package status text; show it verbatim instead of the bare state.
  const progressDetail = /^voice\s*:\s*((?:downloading|testing)\s.+)$/i.exec(mode.statusText || "")?.[1];
  const uiState = progressDetail || mode.uiState || "listening";
  const provider = nativeConversationAudioEngaged() ? "native audio" : voiceConversationVisibleProviderLabel();
  const prefix = provider ? `Voice: ${uiState} · ${provider}` : `Voice: ${uiState}`;
  const partial = uiState === "transcribing" ? conversationModePartialPreview(mode.partialTranscript) : "";
  return partial ? `${prefix} — “${partial}”` : prefix;
}

function conversationModeUnavailableText() {
  return optionalFeatureUnavailableMessage("naturalConversation");
}

function renderConversationModeControls() {
  const mode = activeConversationMode();
  const commandName = conversationModeCommandName();
  const commandAvailable = !!commandName && isOptionalFeatureEnabled("naturalConversation");
  const active = mode.enabled === true;
  document.body.classList.toggle("conversation-mode-active", active);
  elements.composer?.classList.toggle("conversation-mode-active", active);

  if (elements.optionsConversationModeButton) {
    elements.optionsConversationModeButton.hidden = !commandAvailable && !active;
    elements.optionsConversationModeButton.disabled = !commandName;
    elements.optionsConversationModeButton.classList.toggle("active", active);
    elements.optionsConversationModeButton.querySelector("span").textContent = conversationModeButtonLabel(mode);
    const tooltip = commandName
      ? `${active ? "End" : "Start"} Natural Conversation Mode for this Pi tab via /${commandName}. Safety is owned by @firstpick/pi-package-natural-conversation.`
      : conversationModeUnavailableText();
    applyStyledTooltip(elements.optionsConversationModeButton, tooltip, { ariaLabel: false, align: "end" });
    elements.optionsConversationModeButton.setAttribute("aria-pressed", active ? "true" : "false");
  }

  if (elements.conversationModeChip) {
    elements.conversationModeChip.hidden = !active;
    elements.conversationModeChip.textContent = conversationModeDisplayText(mode);
    elements.conversationModeChip.setAttribute("data-voice-state", active ? mode.uiState || "listening" : "off");
    const chipAction = mode.uiState === "paused" ? "Click to resume browser listening." : "Click to pause browser listening; use End conversation to leave the safe mode.";
    elements.conversationModeChip.title = `Natural Conversation Mode is active in this tab (${voiceConversationProviderLabel()}). Thinking is forced off; tools are limited to ${mode.allowedTools.join(", ")}. ${chipAction}`;
    elements.conversationModeChip.setAttribute("aria-label", `Natural Conversation Mode ${mode.uiState || "listening"}. ${chipAction}`);
  }

  if (elements.conversationModeEndButton) {
    elements.conversationModeEndButton.hidden = !active;
    elements.conversationModeEndButton.disabled = !commandName;
    elements.conversationModeEndButton.title = commandName ? `End Natural Conversation Mode with /${commandName} off.` : conversationModeUnavailableText();
  }

  if (elements.conversationVoiceMenu) {
    elements.conversationVoiceMenu.hidden = !active;
    if (!active && conversationVoiceMenuOpen) setConversationVoiceMenuOpen(false);
    if (elements.conversationVoiceButton) elements.conversationVoiceButton.disabled = conversationVoiceSwitching || !commandName;
    if (active && commandName && conversationVoicesLoadedForTab !== activeTabId) void loadConversationVoices();
  }

  const awaitingRemoteMicConsent = active && !remoteMicConsentGranted(activeTabId);
  if (elements.remoteMicStreamingConsent) {
    elements.remoteMicStreamingConsent.hidden = !awaitingRemoteMicConsent;
    if (awaitingRemoteMicConsent && elements.remoteMicStreamingConsentText) {
      elements.remoteMicStreamingConsentText.textContent = remoteMicConsentDisclosureText();
    }
  }
  if (elements.remoteMicStreamingConsentButton) {
    // The consent button stays disabled unless its disclosure is visible.
    elements.remoteMicStreamingConsentButton.disabled = !awaitingRemoteMicConsent;
  }

  syncVoiceConversationLoop();
}

function handleNaturalConversationStatus(statusText, tabId = activeTabId) {
  const text = cleanStatusText(statusText || "");
  const match = text.match(/voice\s*:\s*([a-z0-9_-]+)/i);
  updateConversationModeForTab(tabId, {
    available: true,
    enabled: !!text,
    uiState: text ? (match?.[1] || "listening").toLowerCase() : "off",
    statusText: text,
    loadedCommands: NATURAL_CONVERSATION_COMMAND_NAMES.filter((name) => hasLoadedRpcCommand(name)),
  });
}

async function refreshNaturalConversationMode(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  try {
    const response = await api("/api/conversation-mode", { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    updateConversationModeForTab(tabContext.tabId, response.data?.mode || {}, { render: true });
    if (response.data?.available) optionalFeatureAvailability.naturalConversation = true;
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(`natural conversation status check failed: ${error.message || String(error)}`, "warn");
  }
}

async function setNaturalConversationModeEnabled(enabled) {
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  const commandName = conversationModeCommandName();
  if (!commandName) {
    addEvent(conversationModeUnavailableText(), "warn");
    await Promise.allSettled([refreshCommands(tabContext), refreshOptionalFeaturePackageStatuses()]);
    return;
  }
  try {
    const response = await api("/api/conversation-mode", { method: "POST", body: { enabled: enabled === true }, tabId: tabContext.tabId });
    if (enabled !== true) {
      stopVoiceConversationLoop();
      remoteMicConsentTabs.delete(tabContext.tabId);
    }
    applyResponseTab(response);
    if (!isCurrentTabContext(tabContext)) return;
    updateConversationModeForTab(tabContext.tabId, response.data?.mode || {}, { render: true });
    addEvent(enabled ? "Natural Conversation Mode started." : "Natural Conversation Mode ended.", "info");
    if (enabled) addTransientMessage({ role: "native", title: "/talk", content: "Natural Conversation Mode is active. Thinking is off; write/shell workflows are blocked by the package safety controller.", level: "info" });
    await Promise.allSettled([refreshState(tabContext), refreshCommands(tabContext)]);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
  }
}

function toggleNaturalConversationMode() {
  const mode = activeConversationMode();
  return setNaturalConversationModeEnabled(!mode.enabled);
}

// --- Conversation voice dropdown (native Piper voices via /talk voice) -------
// The list comes from GET /api/conversation-voices (server reads voice.json
// and the piper voice directory); switching posts to /api/conversation-voice,
// which runs `/talk voice <id>` in the package over RPC. Missing voices are
// downloaded by the package; progress streams back through the voice chip's
// status text ("Voice: downloading <id> <pct>%").

function conversationVoiceLanguageLabel(voiceId) {
  const locale = String(voiceId || "").split("-", 1)[0] || "";
  const language = locale.split("_")[0]?.toUpperCase() || "";
  return ["DE", "EN"].includes(language) ? language : language;
}

function conversationVoiceGenderLabel(voiceId) {
  const id = String(voiceId || "").toLowerCase();
  if (id.includes("thorsten")) return "M";
  if (id.includes("lessac") || id.includes("alba")) return "F";
  return "";
}

function conversationVoiceShortLabel(voiceId) {
  // "de_DE-thorsten-medium" → "DE M Thorsten med" keeps the controls compact.
  const text = String(voiceId || "").trim();
  if (!text) return "Voice";
  const parts = text.split("-").filter(Boolean);
  const language = conversationVoiceLanguageLabel(text);
  const gender = conversationVoiceGenderLabel(text);
  const quality = parts.at(-1) || "";
  const qualityLabel = quality === "medium" ? "med" : quality === "high" ? "high" : quality;
  const nameParts = parts.length >= 3 ? parts.slice(1, -1) : parts.slice(1);
  const name = nameParts.join(" ").replace(/\b\w/g, (char) => char.toUpperCase());
  return [language, gender, name, qualityLabel].filter(Boolean).join(" ") || text;
}

function conversationVoiceById(data, voiceId) {
  const wanted = String(voiceId || "").trim();
  const voices = Array.isArray(data?.voices) ? data.voices : [];
  return voices.find((voice) => voice?.id === wanted) || null;
}

function conversationVoiceDownloadSizeText(voice) {
  const sizeMb = Number(voice?.sizeMb);
  return Number.isFinite(sizeMb) && sizeMb > 0 ? ` (${sizeMb} MB)` : "";
}

function conversationVoiceStartMessage(voice, voiceId) {
  const wanted = String(voiceId || voice?.id || "voice").trim();
  if (voice?.downloaded) return `Selecting conversation voice ${wanted}…`;
  return `Downloading conversation voice ${wanted}${conversationVoiceDownloadSizeText(voice)}, then selecting it…`;
}

function showConversationVoiceFeedback(message, level = "info") {
  const text = cleanStatusText(message || "");
  if (!text) return;
  addEvent(text, level);
  addTransientMessage({ role: level === "error" ? "error" : "native", title: "/talk voice", content: text, level });
}

function renderConversationVoicePanelNotice(message, level = "info") {
  const panel = elements.conversationVoiceMenuPanel;
  if (!panel) return;
  panel.innerHTML = "";
  const notice = document.createElement("div");
  notice.className = "composer-publish-menu-item composer-conversation-voice-item composer-conversation-voice-notice";
  notice.classList.toggle("error", level === "error");
  notice.setAttribute("role", level === "error" ? "alert" : "status");
  notice.textContent = message;
  panel.appendChild(notice);
}

function renderConversationVoiceOptions(data = conversationVoiceLastData) {
  const panel = elements.conversationVoiceMenuPanel;
  if (!panel) return;
  const source = data || conversationVoiceLastData || {};
  conversationVoiceLastData = source;
  const voices = Array.isArray(source?.voices) ? source.voices : [];
  panel.innerHTML = "";
  if (elements.conversationVoiceButtonLabel) {
    elements.conversationVoiceButtonLabel.textContent = source?.current ? conversationVoiceShortLabel(source.current) : "Voice";
  }
  if (conversationVoicePending) {
    const pending = document.createElement("div");
    pending.className = "composer-publish-menu-item composer-conversation-voice-item composer-conversation-voice-notice pending";
    pending.setAttribute("role", "status");
    pending.setAttribute("aria-live", "polite");
    pending.textContent = conversationVoicePending.message;
    panel.appendChild(pending);
  }
  if (voices.length === 0) {
    const empty = document.createElement("button");
    empty.className = "composer-publish-menu-item composer-conversation-voice-item";
    empty.type = "button";
    empty.disabled = true;
    empty.textContent = "No Piper voices — run /talk setup";
    panel.appendChild(empty);
    return;
  }
  for (const voice of voices) {
    const item = document.createElement("button");
    const pendingForItem = conversationVoicePending?.voiceId === voice.id;
    item.className = "composer-publish-menu-item composer-conversation-voice-item";
    item.type = "button";
    item.setAttribute("role", "menuitem");
    item.dataset.voiceId = voice.id;
    item.classList.toggle("active", voice.current === true);
    item.classList.toggle("pending", pendingForItem);
    const label = conversationVoiceShortLabel(voice.id);
    item.textContent = pendingForItem
      ? conversationVoicePending.message
      : voice.current
        ? `${label} ✓`
        : voice.downloaded
          ? label
          : `${label} ↓${conversationVoiceDownloadSizeText(voice)}`;
    item.title = voice.current
      ? `${voice.note || voice.id} — current voice`
      : voice.downloaded
        ? `${voice.note || voice.id} — select this installed Piper voice`
        : `${voice.note || voice.id} — download and select with /talk voice ${voice.id}`;
    if (!voice.current) {
      item.setAttribute("aria-label", voice.downloaded ? `Select conversation voice ${voice.id}` : `Download and select conversation voice ${voice.id}`);
    }
    item.disabled = conversationVoiceSwitching || voice.current === true;
    let pointerActivated = false;
    const chooseVoice = (event) => {
      event.preventDefault();
      event.stopPropagation();
      void switchConversationVoice(voice.id);
    };
    item.addEventListener("pointerdown", (event) => {
      pointerActivated = true;
      chooseVoice(event);
    });
    item.addEventListener("click", (event) => {
      if (pointerActivated) {
        pointerActivated = false;
        event.preventDefault();
        event.stopPropagation();
        return;
      }
      chooseVoice(event);
    });
    panel.appendChild(item);
  }
}

async function loadConversationVoices(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  try {
    const response = await api("/api/conversation-voices", { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    conversationVoicesLoadedForTab = tabContext.tabId;
    conversationVoiceLastData = response.data;
    renderConversationVoiceOptions(response.data);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      conversationVoicesLoadedForTab = null;
      const message = `conversation voice list failed: ${error.message || String(error)}`;
      addEvent(message, "warn");
      renderConversationVoicePanelNotice(message, "error");
    }
  }
}

async function switchConversationVoice(voiceId) {
  const wanted = String(voiceId || "").trim();
  if (!wanted) return;
  if (conversationVoiceSwitching) {
    if (conversationVoicePending?.voiceId === wanted) return;
    addEvent(`Already switching conversation voice to ${conversationVoicePending?.voiceId || "another voice"}; wait for it to finish.`, "warn");
    return;
  }
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  const voice = conversationVoiceById(conversationVoiceLastData, wanted);
  const downloading = voice?.downloaded !== true;
  const startMessage = conversationVoiceStartMessage(voice, wanted);
  conversationVoiceSwitching = true;
  const label = conversationVoiceShortLabel(wanted);
  conversationVoicePending = { voiceId: wanted, phase: downloading ? "downloading" : "selecting", message: downloading ? `${label} ↓${conversationVoiceDownloadSizeText(voice)}…` : `${label}…` };
  setConversationVoiceMenuOpen(true);
  renderConversationVoiceOptions();
  if (elements.conversationVoiceButton) elements.conversationVoiceButton.disabled = true;
  if (elements.conversationVoiceButtonLabel) elements.conversationVoiceButtonLabel.textContent = `→ ${conversationVoiceShortLabel(wanted)}…`;
  updateConversationModeForTab(tabContext.tabId, {
    uiState: downloading ? "downloading" : "testing",
    statusText: downloading ? `Voice: downloading ${wanted} starting` : `Voice: testing ${wanted}`,
  }, { render: true, voiceLoop: true });
  showConversationVoiceFeedback(`${startMessage} Progress appears on the Voice chip.`, "info");
  try {
    const response = await api("/api/conversation-voice", { method: "POST", body: { voice: wanted }, tabId: tabContext.tabId });
    if (isCurrentTabContext(tabContext)) {
      applyResponseTab(response);
      conversationVoiceLastData = response.data;
      conversationVoicesLoadedForTab = tabContext.tabId;
      const current = response.data?.current || wanted;
      const output = cleanStatusText(response.data?.response?.data?.output || response.data?.response?.data?.message || "");
      renderConversationVoiceOptions(response.data);
      showConversationVoiceFeedback(`${downloading ? "Downloaded and selected" : "Selected"} conversation voice ${current}.${output ? ` ${output}` : ""}`, "info");
      setConversationVoiceMenuOpen(false);
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      updateConversationModeForTab(tabContext.tabId, { uiState: "error", statusText: "Voice: error" }, { render: true, voiceLoop: true });
      showConversationVoiceFeedback(`Voice switch failed: ${error.message || String(error)}`, "error");
      await loadConversationVoices(tabContext);
    }
  } finally {
    conversationVoiceSwitching = false;
    conversationVoicePending = null;
    if (isCurrentTabContext(tabContext)) {
      if (elements.conversationVoiceButton) elements.conversationVoiceButton.disabled = false;
      renderConversationVoiceOptions();
      renderConversationModeControls();
    }
  }
}

// --- Natural Conversation browser voice loop (Phase 3) -----------------------
// Browser Web Speech STT/TTS drives the active tab's conversation mode. The
// controller logic lives in voice-conversation.mjs (dynamically imported so
// app.js stays parseable as a plain script) and is tab-scoped: switching tabs
// or disabling the mode tears the loop down.

const remoteMicConsentTabs = new Set();
const VOICE_CONVERSATION_SILENCE_TIMEOUT_MS = 8000;
let voiceConversation = null;
let voiceConversationTabId = null;
let voiceConversationStartToken = 0;
let voiceConversationStartingForTab = null;
let voiceConversationModulePromise = null;

function isLocalhostWebui() {
  const hostname = String(location.hostname || "").toLowerCase();
  return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "[::1]" || hostname === "::1";
}

function remoteMicConsentGranted(tabId = activeTabId) {
  if (isLocalhostWebui()) return true;
  return !!tabId && remoteMicConsentTabs.has(tabId);
}

function remoteMicConsentDisclosureText() {
  const host = location.host || "this Pi host";
  const provider = browserSpeechRecognitionCtor() ? "your browser's speech service" : "a browser speech service (unavailable in this browser)";
  return `Remote session: enabling the microphone captures audio in this browser tab and transcribes it with ${provider}; audio snippets may leave this device to your browser vendor. Only the resulting text transcripts are sent to Pi at ${host} — raw audio is never streamed to the Pi host. Consent applies to this tab only and ends with the conversation. Use End conversation to stop capture at any time.`;
}

function browserSpeechRecognitionCtor() {
  return window.SpeechRecognition || window.webkitSpeechRecognition || null;
}

function voiceConversationProviderLabel() {
  const stt = browserSpeechRecognitionCtor() ? "browser mic" : "no browser STT";
  const tts = window.speechSynthesis ? "browser voice" : "no browser TTS";
  return `${stt}, ${tts}`;
}

function voiceConversationVisibleProviderLabel() {
  const hasStt = !!browserSpeechRecognitionCtor();
  const hasTts = !!window.speechSynthesis;
  if (hasStt && hasTts) return "browser STT/TTS";
  if (hasStt) return "browser STT";
  if (hasTts) return "browser TTS only";
  return "speech unsupported";
}

function voiceConversationActiveFor(tabId = activeTabId) {
  return !!voiceConversation && !!tabId && voiceConversationTabId === tabId && voiceConversation.isActive();
}

function updateVoiceConversationModeFromController(tabId = voiceConversationTabId) {
  if (!tabId || !voiceConversation) return;
  const state = voiceConversation.getState?.() || {};
  const uiState = state.uiState || "listening";
  updateConversationModeForTab(tabId, { uiState, statusText: `Voice: ${uiState}`, partialTranscript: state.partialTranscript || "" }, { render: true, voiceLoop: true });
}

function toggleVoiceConversationPaused() {
  if (!activeTabId || !activeConversationMode().enabled) return;
  if (!voiceConversationActiveFor(activeTabId)) {
    if (!remoteMicConsentGranted(activeTabId)) {
      addEvent("Remote Web UI session: allow remote microphone streaming before resuming the browser voice loop.", "warn");
      renderConversationModeControls();
      return;
    }
    void startVoiceConversationLoop(activeTabId);
    return;
  }
  const next = voiceConversation.togglePaused?.();
  updateVoiceConversationModeFromController(activeTabId);
  addEvent(next?.userPaused ? "Browser voice loop paused; Natural Conversation safety remains active." : "Browser voice loop resumed.", "info");
}

function loadVoiceConversationModule() {
  if (!voiceConversationModulePromise) {
    voiceConversationModulePromise = import("./voice-conversation.mjs?v=1");
    voiceConversationModulePromise.catch(() => {
      voiceConversationModulePromise = null;
    });
  }
  return voiceConversationModulePromise;
}

function speakableTextFromMarkdown(text) {
  return String(text || "")
    .replace(/```[\s\S]*?```/g, " Code block omitted. ")
    .replace(/`([^`\n]+)`/g, "$1")
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^\s*[-*+]\s+/gm, "")
    .replace(/(\*\*|__|\*|_|~~)(\S(?:[^*_~]*\S)?)\1/g, "$2")
    .replace(/\s+/g, " ")
    .trim();
}

function latestAssistantSpokenText() {
  for (let index = latestMessages.length - 1; index >= 0; index -= 1) {
    const message = latestMessages[index];
    if (message?.role !== "assistant") continue;
    const finalMessage = assistantDisplayMessages(message).find((item) => item?.title === "final output");
    return finalMessage ? textFromContent(finalMessage.content) : "";
  }
  return "";
}

function assistantTextAsksQuestion(text) {
  const lines = String(text || "").trim().split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const lastLine = lines[lines.length - 1] || "";
  return /\?["')\]]*$/.test(lastLine);
}

async function startVoiceConversationLoop(tabId = activeTabId) {
  if (!tabId || voiceConversationActiveFor(tabId) || voiceConversationStartingForTab === tabId) return;
  if (voiceConversation) stopVoiceConversationLoop();
  if (!remoteMicConsentGranted(tabId)) {
    const mode = normalizeConversationModeState(conversationModeByTab.get(tabId) || {});
    if (mode.uiState !== "paused") {
      updateConversationModeForTab(tabId, { uiState: "paused", statusText: "Voice: paused" }, { render: true, voiceLoop: true });
      addEvent("Remote Web UI session: the microphone stays off until you allow remote microphone streaming for this tab.", "warn");
    }
    return;
  }
  const token = ++voiceConversationStartToken;
  voiceConversationStartingForTab = tabId;
  let module = null;
  try {
    module = await loadVoiceConversationModule();
  } catch (error) {
    addEvent(`failed to load the voice conversation module: ${error?.message || String(error)}`, "error");
    return;
  } finally {
    voiceConversationStartingForTab = null;
  }
  if (token !== voiceConversationStartToken || tabId !== activeTabId) return;
  if (!activeConversationMode().enabled) return;
  const controller = module.createVoiceConversationController({
    recognitionFactory: () => {
      const Recognition = browserSpeechRecognitionCtor();
      if (!Recognition) return null;
      try {
        const recognition = new Recognition();
        recognition.lang = navigator.language || "en-US";
        return recognition;
      } catch {
        return null;
      }
    },
    synthesis: window.speechSynthesis || null,
    utteranceFactory: (text) => new SpeechSynthesisUtterance(text),
    sendTranscript: async (text, { reason } = {}) => {
      if (!voiceConversationActiveFor(tabId) || tabId !== activeTabId) return;
      if (reason === "interrupt" && currentState?.isStreaming) {
        await sendPrompt("steer", `[Voice interruption: the user started speaking over the current answer.] ${text}`, { targetTabId: tabId, throwOnError: true });
        return;
      }
      await sendPrompt("prompt", text, { targetTabId: tabId, throwOnError: true });
    },
    sendSilenceEvent: async ({ silentSeconds } = {}) => {
      if (!voiceConversationActiveFor(tabId) || tabId !== activeTabId) return;
      await sendPrompt("prompt", module.voiceSilenceEventMessage(silentSeconds), { targetTabId: tabId, throwOnError: true });
    },
    onPartialTranscript: (partialTranscript) => {
      if (voiceConversationTabId !== tabId) return;
      updateConversationModeForTab(tabId, { uiState: partialTranscript ? "transcribing" : undefined, partialTranscript }, { render: true, voiceLoop: true });
    },
    onStateChange: (uiState, state = {}) => {
      if (voiceConversationTabId !== tabId || uiState === "off") return;
      updateConversationModeForTab(tabId, { uiState, statusText: `Voice: ${uiState}`, partialTranscript: state.partialTranscript || "" }, { render: true, voiceLoop: true });
    },
    onEvent: (message, level = "info") => addEvent(message, level),
    bargeInEnabled: false,
    silenceTimeoutMs: VOICE_CONVERSATION_SILENCE_TIMEOUT_MS,
  });
  voiceConversation = controller;
  voiceConversationTabId = tabId;
  controller.start();
}

function stopVoiceConversationLoop() {
  voiceConversationStartToken += 1;
  const controller = voiceConversation;
  voiceConversation = null;
  voiceConversationTabId = null;
  if (controller) {
    try {
      controller.stop();
    } catch {
      // Tearing down a broken speech engine must not break the UI.
    }
  }
}

// The package's native audio loop (mic + Piper TTS on the Pi host) announces
// itself through its "natural-conversation-audio" widget. While it is armed —
// listening or paused — the browser Web Speech loop must stand down entirely,
// otherwise both loops transcribe the same speech and speak every answer twice
// (native Piper voice + browser voice).
function nativeConversationAudioEngaged() {
  return widgets.has("natural-conversation-audio");
}

function syncVoiceConversationLoop() {
  const mode = activeConversationMode();
  const shouldRun = mode.enabled === true && !!activeTabId && !nativeConversationAudioEngaged();
  if (voiceConversation && (!shouldRun || voiceConversationTabId !== activeTabId)) stopVoiceConversationLoop();
  if (shouldRun && !voiceConversationActiveFor(activeTabId)) void startVoiceConversationLoop(activeTabId);
}

async function handleVoiceConversationTurnEnd(tabContext = activeTabContext()) {
  const tabId = tabContext.tabId;
  if (!voiceConversationActiveFor(tabId)) return;
  try {
    await refreshMessages(tabContext);
  } catch {
    // Speak whatever transcript state we already have.
  }
  if (!isCurrentTabContext(tabContext) || !voiceConversationActiveFor(tabId)) return;
  const spoken = speakableTextFromMarkdown(latestAssistantSpokenText());
  voiceConversation.handleAssistantTurnEnd(spoken, { askedQuestion: assistantTextAsksQuestion(spoken) });
}

function renderOptionalFeatureDependentDisplays() {
  renderOptionalFeatureControls();
  if (elements.optionalFeatureMigrationDialog?.open) renderOptionalFeatureMigrationDialog();
  renderThemeSelect();
  renderWidgets();
  renderStatus();
  renderCommands();
  cancelStreamBubbleHide();
  streamBubble?.remove();
  streamBubble = null;
  streamText = null;
  streamBubbleVisibleSince = 0;
  renderAllMessages({ preserveScroll: true, forceRebuild: true });
  if (streamRawText) renderStreamingAssistantText();
}

function setOptionalFeatureDisabled(featureId, disabled) {
  if (!OPTIONAL_FEATURE_BY_ID.has(featureId)) return;
  if (disabled) disabledOptionalFeatures.add(featureId);
  else disabledOptionalFeatures.delete(featureId);
  if (featureId === "remoteWebui") syncRemoteWebuiControlVisibility(false);
  if (featureId === "gitFooterStatus") {
    statusEntries.delete(GIT_FOOTER_WEBUI_STATUS_KEY);
    clearGitFooterWebuiPayloadCache();
    for (const tabId of new Set([...gitFooterPayloadStateByTab.keys(), ...gitFooterPayloadSettlementTimersByTab.keys(), ...gitFooterPayloadRefreshInFlightByTab])) clearGitFooterPayloadState(tabId);
  }
  if (featureId === "featureSystemPrompt") {
    if (disabled) {
      for (const tabId of new Set([...featureCategoryByTab.keys(), ...featureDecisionOutputByTab.keys()])) clearFeatureDecisionStateForTab(tabId);
    }
    renderFeatureCategoryTag();
  }
  if (featureId === "btwCommand") {
    statusEntries.delete(BTW_WEBUI_STATUS_KEY);
    widgets.delete(BTW_OUTPUT_WIDGET_KEY);
    widgets.delete(BTW_FOOTER_WIDGET_KEY);
    latestBtwWidgetPayload = null;
    btwWidgetDismissedIdsByTab.delete(activeTabId);
    btwWidgetComposerOpen = false;
    btwWidgetInputDraft = "";
  }
  if (featureId === "remoteWebui") {
    statusEntries.delete(REMOTE_WEBUI_CONTROLS_STATUS_KEY);
    statusEntries.delete("pi-remote-webui");
    widgets.delete("pi-remote-webui");
  }
  if (featureId === "naturalConversation" && disabled && !activeConversationMode().enabled) {
    statusEntries.delete(NATURAL_CONVERSATION_STATUS_KEY);
    updateConversationModeForTab(activeTabId, { available: false, enabled: false, uiState: "off", statusText: "" }, { render: false });
  }
  if (featureId === "codexFastMode") {
    if (disabled) {
      statusEntries.delete(CODEX_FAST_MODE_STATUS_KEY);
      codexFastModeState = { ...codexFastModeState, available: false, enabled: false, statusKnown: false, busy: false };
      codexFastModeNotice = "";
      renderCodexFastModeControl();
    } else {
      refreshCodexFastMode().catch(() => null);
    }
  }
  storeDisabledOptionalFeatures();
  renderOptionalFeatureDependentDisplays();
  const tabContext = activeTabContext();
  refreshCommands(tabContext).catch((error) => {
    if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
  });
}

function displayThemeName(name) {
  return String(name || "")
    .split(/[-_]+/)
    .filter(Boolean)
    .map((part) => part.length <= 3 ? part.toUpperCase() : `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(" ");
}

function resolveThemeValue(theme, value, fallback, seen = new Set()) {
  if (Number.isInteger(value)) {
    try {
      return themeColorToRgb(value, theme?.vars || {}, fallback);
    } catch {
      return fallback;
    }
  }
  const raw = String(value ?? "").trim();
  if (!raw) return fallback;
  if (/^(#|rgb\(|rgba\(|hsl\(|hsla\()/i.test(raw)) return raw;
  if (seen.has(raw)) return fallback;
  seen.add(raw);
  return resolveThemeValue(theme, theme?.vars?.[raw] ?? theme?.colors?.[raw], fallback, seen);
}

function themeColor(theme, key, fallback) {
  return resolveThemeValue(theme, theme?.colors?.[key] ?? theme?.vars?.[key], fallback);
}

function themeExportColor(theme, key, fallback) {
  return resolveThemeValue(theme, theme?.export?.[key], fallback);
}

const LOCAL_BACKGROUND_IMAGE_PATTERN = /^(?:none|url\(["']?\/(?!\/)[A-Za-z0-9._~!$&'()*+,=:@%\/-]+["']?\))$/i;
const BACKGROUND_OVERLAY_PATTERN = /^(?:none|linear-gradient\([^;\r\n{}<>]+\))$/i;
const SAFE_BACKGROUND_TOKEN_PATTERN = /^[A-Za-z0-9%._ -]+$/;

function themeExportCssValue(theme, key, fallback, pattern = /^[^;\r\n{}<>]+$/) {
  const raw = String(theme?.export?.[key] ?? "").trim();
  if (!raw) return fallback;
  return pattern.test(raw) ? raw : fallback;
}

function hexToRgb(color) {
  const raw = String(color || "").trim();
  const match = raw.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!match) return null;
  const hex = match[1].length === 3 ? match[1].split("").map((ch) => ch + ch).join("") : match[1];
  return {
    r: Number.parseInt(hex.slice(0, 2), 16),
    g: Number.parseInt(hex.slice(2, 4), 16),
    b: Number.parseInt(hex.slice(4, 6), 16),
  };
}

function colorWithAlpha(color, alpha, fallback) {
  const rgb = hexToRgb(color);
  if (!rgb) return fallback;
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
}

function rgbTriplet(color, fallback) {
  const rgb = hexToRgb(color);
  if (!rgb) return fallback;
  return `${rgb.r}, ${rgb.g}, ${rgb.b}`;
}

function cssColorToRgb(color) {
  const hex = hexToRgb(color);
  if (hex) return hex;
  const match = String(color || "").trim().match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i);
  if (!match) return null;
  const [r, g, b] = match.slice(1, 4).map((value) => Math.min(255, Math.max(0, Number(value))));
  if (![r, g, b].every(Number.isFinite)) return null;
  return { r, g, b };
}

function mixRgb(left, right, amount) {
  const t = Math.min(1, Math.max(0, amount));
  return {
    r: left.r + (right.r - left.r) * t,
    g: left.g + (right.g - left.g) * t,
    b: left.b + (right.b - left.b) * t,
  };
}

function rgbColor(rgb) {
  return `rgb(${Math.round(rgb.r)}, ${Math.round(rgb.g)}, ${Math.round(rgb.b)})`;
}

function rgbaColor(rgb, alpha) {
  return `rgba(${Math.round(rgb.r)}, ${Math.round(rgb.g)}, ${Math.round(rgb.b)}, ${alpha})`;
}

function relativeLuminance(color) {
  const rgb = cssColorToRgb(color);
  if (!rgb) return 0;
  const channel = (value) => {
    const normalized = value / 255;
    return normalized <= 0.03928 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(rgb.r) + 0.7152 * channel(rgb.g) + 0.0722 * channel(rgb.b);
}

function applyTheme(theme, { persist = false, announce = false } = {}) {
  if (!theme) return;
  const root = document.documentElement;
  const current = getComputedStyle(root);
  const fallback = (name, value) => current.getPropertyValue(name).trim() || value;

  const accent = themeColor(theme, "accent", fallback("--ctp-blue", "#89b4fa"));
  const accent2 = themeColor(theme, "borderAccent", themeColor(theme, "accent2", fallback("--ctp-teal", "#94e2d5")));
  const green = themeColor(theme, "success", fallback("--ctp-green", "#a6e3a1"));
  const red = themeColor(theme, "error", fallback("--ctp-red", "#f38ba8"));
  const yellow = themeColor(theme, "warning", fallback("--ctp-yellow", "#f9e2af"));
  const text = themeColor(theme, "userMessageText", themeColor(theme, "text", fallback("--ctp-text", "#cdd6f4")));
  const muted = themeColor(theme, "muted", fallback("--ctp-subtext", "#bac2de"));
  const dim = themeColor(theme, "dim", fallback("--ctp-overlay", "#6c7086"));
  const borderMuted = themeColor(theme, "borderMuted", dim);
  const selectedBg = themeColor(theme, "selectedBg", fallback("--ctp-surface", "#313244"));
  const cardBg = themeExportColor(theme, "cardBg", themeColor(theme, "userMessageBg", fallback("--ctp-base", "#1e1e2e")));
  const pageBg = themeExportColor(theme, "pageBg", fallback("--ctp-crust", "#11111b"));
  const infoBg = themeExportColor(theme, "infoBg", themeColor(theme, "customMessageBg", fallback("--ctp-mantle", "#181825")));
  const pendingBg = themeColor(theme, "toolPendingBg", infoBg);
  const pink = themeColor(theme, "mdHeading", themeColor(theme, "customMessageLabel", fallback("--ctp-pink", "#f5c2e7")));
  const mauve = themeColor(theme, "customMessageLabel", themeColor(theme, "thinkingHigh", fallback("--ctp-mauve", "#cba6f7")));
  const peach = themeColor(theme, "syntaxNumber", yellow);
  const sky = themeColor(theme, "mdListBullet", accent2);
  const sapphire = themeColor(theme, "thinkingLow", accent);
  const lavender = themeColor(theme, "thinkingHigh", mauve);
  const isLight = relativeLuminance(pageBg) > 0.62;
  const panelAlpha = isLight ? 0.86 : 0.72;
  const panel2Alpha = isLight ? 0.90 : 0.78;
  const panel3Alpha = isLight ? 0.94 : 0.92;
  const borderAlpha = isLight ? 0.34 : 0.22;

  const vars = {
    "--theme-color-scheme": isLight ? "light" : "dark",
    "--ctp-rosewater": themeColor(theme, "customMessageText", text),
    "--ctp-flamingo": pink,
    "--ctp-pink": pink,
    "--ctp-mauve": mauve,
    "--ctp-red": red,
    "--ctp-maroon": themeColor(theme, "toolDiffRemoved", red),
    "--ctp-peach": peach,
    "--ctp-yellow": yellow,
    "--ctp-green": green,
    "--ctp-teal": accent2,
    "--ctp-sky": sky,
    "--ctp-sapphire": sapphire,
    "--ctp-blue": accent,
    "--ctp-lavender": lavender,
    "--ctp-text": text,
    "--ctp-subtext": muted,
    "--ctp-overlay": borderMuted,
    "--ctp-surface": selectedBg,
    "--ctp-base": cardBg,
    "--ctp-mantle": pendingBg,
    "--ctp-crust": pageBg,
    "--ctp-text-rgb": rgbTriplet(text, "205, 214, 244"),
    "--ctp-subtext-rgb": rgbTriplet(muted, "186, 194, 222"),
    "--ctp-overlay-rgb": rgbTriplet(borderMuted, "108, 112, 134"),
    "--ctp-surface-rgb": rgbTriplet(selectedBg, "49, 50, 68"),
    "--ctp-base-rgb": rgbTriplet(cardBg, "30, 30, 46"),
    "--ctp-mantle-rgb": rgbTriplet(pendingBg, "24, 24, 37"),
    "--ctp-crust-rgb": rgbTriplet(pageBg, "17, 17, 27"),
    "--bg": pageBg,
    "--panel": colorWithAlpha(cardBg, panelAlpha, cardBg),
    "--panel-2": colorWithAlpha(selectedBg, panel2Alpha, selectedBg),
    "--panel-3": colorWithAlpha(pendingBg, panel3Alpha, pendingBg),
    "--text": text,
    "--muted": muted,
    "--border": colorWithAlpha(lavender, borderAlpha, lavender),
    "--accent": mauve,
    "--accent-2": accent2,
    "--accent-3": pink,
    "--danger": red,
    "--warning": yellow,
    "--ok": green,
    "--shadow": colorWithAlpha(isLight ? borderMuted : pageBg, isLight ? 0.24 : 0.78, isLight ? "rgba(108, 111, 133, 0.24)" : "rgba(17, 17, 27, 0.78)"),
    "--glow-mauve": colorWithAlpha(mauve, isLight ? 0.24 : 0.42, mauve),
    "--glow-blue": colorWithAlpha(accent, isLight ? 0.22 : 0.36, accent),
    "--glow-pink": colorWithAlpha(pink, isLight ? 0.22 : 0.34, pink),
    "--glow-teal": colorWithAlpha(accent2, isLight ? 0.20 : 0.26, accent2),
    "--panel-gradient": `linear-gradient(145deg, ${colorWithAlpha(selectedBg, panel2Alpha, selectedBg)}, ${colorWithAlpha(pendingBg, panel3Alpha, pendingBg)} 52%, ${colorWithAlpha(pageBg, isLight ? 0.92 : 0.9, pageBg)})`,
    "--neon-gradient": `linear-gradient(120deg, ${pink}, ${mauve} 32%, ${accent} 66%, ${accent2})`,
    "--context-card-gradient": `linear-gradient(100deg, ${colorWithAlpha(green, isLight ? 0.48 : 0.62, green)} 0%, ${colorWithAlpha(yellow, isLight ? 0.50 : 0.66, yellow)} 36%, ${colorWithAlpha(accent, isLight ? 0.50 : 0.64, accent)} 62%, ${colorWithAlpha(red, isLight ? 0.62 : 0.78, red)} 100%)`,
    "--background-glow-pink": colorWithAlpha(pink, isLight ? 0.16 : 0.34, pink),
    "--background-glow-blue": colorWithAlpha(accent, isLight ? 0.15 : 0.32, accent),
    "--background-glow-teal": colorWithAlpha(accent2, isLight ? 0.12 : 0.20, accent2),
    "--syntax-comment": themeColor(theme, "syntaxComment", muted),
    "--syntax-keyword": themeColor(theme, "syntaxKeyword", mauve),
    "--syntax-function": themeColor(theme, "syntaxFunction", accent),
    "--syntax-variable": themeColor(theme, "syntaxVariable", text),
    "--syntax-string": themeColor(theme, "syntaxString", green),
    "--syntax-number": themeColor(theme, "syntaxNumber", peach),
    "--syntax-type": themeColor(theme, "syntaxType", yellow),
    "--syntax-operator": themeColor(theme, "syntaxOperator", accent2),
    "--syntax-punctuation": themeColor(theme, "syntaxPunctuation", muted),
    "--theme-background-image": themeExportCssValue(theme, "backgroundImage", "none", LOCAL_BACKGROUND_IMAGE_PATTERN),
    "--theme-background-overlay": themeExportCssValue(theme, "backgroundOverlay", "linear-gradient(180deg, rgba(17, 17, 27, 0), rgba(17, 17, 27, 0))", BACKGROUND_OVERLAY_PATTERN),
    "--theme-background-size": themeExportCssValue(theme, "backgroundSize", "cover", SAFE_BACKGROUND_TOKEN_PATTERN),
    "--theme-background-position": themeExportCssValue(theme, "backgroundPosition", "center", SAFE_BACKGROUND_TOKEN_PATTERN),
    "--theme-background-repeat": themeExportCssValue(theme, "backgroundRepeat", "no-repeat", SAFE_BACKGROUND_TOKEN_PATTERN),
  };

  for (const [name, value] of Object.entries(vars)) root.style.setProperty(name, value);
  applyCustomBackgroundOverride({ render: false });
  root.style.colorScheme = isLight ? "light" : "dark";
  document.body.classList.toggle("theme-light", isLight);
  document.body.classList.toggle("theme-dark", !isLight);
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", pageBg);
  currentThemeName = theme.name;
  if (elements.themeSelect && elements.themeSelect.value !== theme.name) elements.themeSelect.value = theme.name;
  if (persist) {
    storeSchemeTheme(isLight ? "light" : "dark", theme.name);
    storeThemeName(theme.name);
  }
  if (announce) addEvent(`theme changed to ${theme.label || displayThemeName(theme.name) || theme.name}`);
}

function osPrefersDark() {
  return !!(colorSchemeMedia && colorSchemeMedia.matches);
}

function effectiveScheme() {
  if (themeSchemeMode === "auto") return osPrefersDark() ? "dark" : "light";
  return themeSchemeMode === "dark" ? "dark" : "light";
}

function themeIsLight(theme) {
  if (!theme) return false;
  return relativeLuminance(themeExportColor(theme, "pageBg", "#11111b")) > 0.62;
}

function effectiveThemeName() {
  const scheme = effectiveScheme();
  const name = storedSchemeTheme(scheme);
  if (availableThemes.some((theme) => theme.name === name)) return name;
  const fallback = scheme === "dark" ? THEME_DARK_DEFAULT : THEME_LIGHT_DEFAULT;
  if (availableThemes.some((theme) => theme.name === fallback)) return fallback;
  return availableThemes[0]?.name || fallback;
}

function renderThemeSchemeToggle() {
  const group = elements.themeSchemeToggle;
  if (!group) return;
  for (const button of group.querySelectorAll("[data-scheme-mode]")) {
    const active = button.dataset.schemeMode === themeSchemeMode;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  }
}

// Apply the theme for the current scheme (mode + OS). Never persists: the scheme
// slots and the legacy key only record explicit user picks, so one degraded theme
// bundle load cannot clobber stored choices.
async function applySchemeTheme(options = {}) {
  await setThemeByName(effectiveThemeName(), { ...options, persist: false });
}

// A theme picked from the selector/search is assigned to its own light/dark slot.
// Persistence happens inside applyTheme, only after the theme was validated and applied.
async function chooseTheme(name, options = {}) {
  await setThemeByName(name, { ...options, persist: true });
}

function handleOsSchemeChange() {
  if (themeSchemeMode !== "auto") return;
  applySchemeTheme({ announce: true }).catch((error) => addEvent(error.message || String(error), "error"));
}

function updateColorSchemeListener() {
  if (!colorSchemeMedia) return;
  if (typeof colorSchemeMedia.addEventListener === "function") {
    colorSchemeMedia.removeEventListener("change", handleOsSchemeChange);
    if (themeSchemeMode === "auto") colorSchemeMedia.addEventListener("change", handleOsSchemeChange);
  } else {
    colorSchemeMedia.removeListener?.(handleOsSchemeChange);
    if (themeSchemeMode === "auto") colorSchemeMedia.addListener?.(handleOsSchemeChange);
  }
}

async function setThemeSchemeMode(mode, { announce = false } = {}) {
  if (!THEME_SCHEME_MODES.has(mode)) return;
  if (themeSchemeMode === mode) {
    renderThemeSchemeToggle();
    return;
  }
  themeSchemeMode = mode;
  storeThemeMode(mode);
  updateColorSchemeListener();
  renderThemeSchemeToggle();
  await applySchemeTheme({ announce });
}

// First run with the scheme switch: migrate a pre-existing single theme into the slot
// matching its own light/dark scheme and default the mode to that scheme, so existing
// users see no change and auto stays opt-in.
function seedThemeSchemeFromStoredTheme() {
  const stored = storedThemeName();
  const storedTheme = availableThemes.find((theme) => theme.name === stored);
  // Degraded load (empty bundle or stored theme missing): fall back for this page
  // load only, without persisting, so the migration retries once the bundle is healthy.
  if (!storedTheme) return "dark";
  const scheme = themeIsLight(storedTheme) ? "light" : "dark";
  storeSchemeTheme(scheme, stored);
  storeThemeMode(scheme);
  return scheme;
}

function themeDisplayLabel(theme) {
  return theme?.label || displayThemeName(theme?.name) || theme?.name || "";
}

function themeSearchText(theme) {
  return [themeDisplayLabel(theme), theme?.name, theme?.author].filter(Boolean).join(" ");
}

function renderThemeSearchResults(themes = []) {
  if (!elements.themeSearchResults) return;
  elements.themeSearchResults.replaceChildren();
  if (elements.themeSearchInput?.hidden) return;
  if (!themes.length) {
    elements.themeSearchResults.append(make("div", "model-search-empty", "No themes match the search"));
    elements.themeSearchResults.hidden = false;
    return;
  }
  for (const theme of themes) {
    const selected = theme.name === currentThemeName;
    const button = make("button", `model-search-result theme-search-result${selected ? " active" : ""}`);
    button.type = "button";
    button.setAttribute("role", "option");
    button.setAttribute("aria-selected", String(selected));
    button.title = themeSearchText(theme);
    const title = make("span", "theme-search-result-title");
    title.append(make("span", "model-search-result-main", themeDisplayLabel(theme)));
    const badges = make("span", "theme-search-result-badges");
    badges.append(make("span", `theme-search-result-scheme ${themeIsLight(theme) ? "light" : "dark"}`, themeIsLight(theme) ? "Light" : "Dark"));
    if (theme.custom) badges.append(make("span", `theme-scope-badge ${theme.scope}`, themeScopeLabel(theme.scope)));
    title.append(badges);
    button.append(title);
    button.addEventListener("click", () => {
      if (elements.themeSelect) elements.themeSelect.value = theme.name;
      chooseTheme(theme.name, { announce: true }).catch((error) => addEvent(error.message || String(error), "error"));
    });
    elements.themeSearchResults.append(button);
  }
  elements.themeSearchResults.hidden = false;
}

function populateThemeSelect(themes = availableThemes, query = "") {
  if (!elements.themeSelect) return [];
  const normalizedQuery = String(query || "").trim().toLowerCase();
  const matchingThemes = themes.filter((theme) => !normalizedQuery || themeSearchText(theme).toLowerCase().includes(normalizedQuery));
  renderThemeSearchResults(matchingThemes);
  return matchingThemes;
}

function showThemeSearchInput({ focus = true } = {}) {
  if (!elements.themeSearchInput) return;
  elements.themeSearchInput.hidden = false;
  elements.themeSearchResults.hidden = false;
  elements.themeSelect.classList.add("model-select-expanded");
  populateThemeSelect(availableThemes, elements.themeSearchInput.value);
  if (focus) {
    requestAnimationFrame(() => {
      elements.themeSearchInput.focus();
      elements.themeSearchInput.select();
    });
  }
}

function hideThemeSearchInput() {
  if (!elements.themeSearchInput) return;
  elements.themeSearchInput.hidden = true;
  elements.themeSearchInput.value = "";
  if (elements.themeSearchResults) {
    elements.themeSearchResults.hidden = true;
    elements.themeSearchResults.replaceChildren();
  }
  elements.themeSelect?.classList.remove("model-select-expanded");
  scheduleDeferredUiFlushAfterDropdownClose();
}

function toggleThemeSearchInput() {
  if (elements.themeSearchInput?.hidden) showThemeSearchInput();
  else hideThemeSearchInput();
}

function themeScopeLabel(scope) {
  if (scope === "project") return "Project";
  if (scope === "global") return "Global";
  return "Bundled";
}

function cloneThemeDraft(theme) {
  return JSON.parse(JSON.stringify(theme));
}

function themeDraftFromCatalog(theme, name = theme?.name) {
  return {
    name,
    ...(theme?.vars && Object.keys(theme.vars).length ? { vars: cloneThemeDraft(theme.vars) } : {}),
    colors: cloneThemeDraft(theme?.colors || {}),
    ...(theme?.export && Object.keys(theme.export).length ? { export: cloneThemeDraft(theme.export) } : {}),
  };
}

function themeCustomizerValue(raw) {
  const value = String(raw ?? "").trim();
  if (/^(?:0|[1-9]\d{0,2})$/.test(value)) return Number(value);
  return value;
}

function themeCustomizerDraftSignature(state = themeCustomizerState) {
  if (!state?.validTheme) return "";
  return JSON.stringify({
    scope: elements.themeCustomizerScope?.value || "",
    fileName: `${elements.themeCustomizerName?.value.trim() || ""}.json`,
    theme: state.validTheme,
  });
}

function setThemeCustomizerStatus(message, kind = "muted") {
  if (!elements.themeCustomizerStatus) return;
  const urgent = kind === "error";
  elements.themeCustomizerStatus.textContent = message;
  elements.themeCustomizerStatus.className = `theme-customizer-status ${kind}`;
  elements.themeCustomizerStatus.setAttribute("role", urgent ? "alert" : "status");
  elements.themeCustomizerStatus.setAttribute("aria-live", urgent ? "assertive" : "polite");
}

function invalidateThemeCustomizerOverwrite() {
  if (themeCustomizerState) themeCustomizerState.overwrite = null;
  if (elements.themeCustomizerOverwrite) elements.themeCustomizerOverwrite.hidden = true;
}

function updateThemeCustomizerActions() {
  const state = themeCustomizerState;
  const name = elements.themeCustomizerName?.value.trim() || "";
  const validName = /^[A-Za-z0-9][A-Za-z0-9._-]{0,74}$/.test(name) && !name.includes("..");
  const scope = elements.themeCustomizerScope?.value;
  const projectUnavailable = scope === "project" && !themeCatalogScopes.project?.trusted;
  if (elements.themeCustomizerSaveButton) {
    elements.themeCustomizerSaveButton.disabled = !state?.draftValid || !validName || projectUnavailable || !!state?.saving || !!state?.overwrite;
    elements.themeCustomizerSaveButton.textContent = state?.saving ? "Saving…" : "Save theme";
  }
  if (elements.themeCustomizerOverwriteButton) elements.themeCustomizerOverwriteButton.disabled = !!state?.saving;
  if (elements.themeCustomizerCancelButton) elements.themeCustomizerCancelButton.disabled = !!state?.saving;
  if (elements.themeCustomizerResetButton) elements.themeCustomizerResetButton.disabled = !!state?.saving;
  if (!validName) setThemeCustomizerStatus("Use 1–75 letters, numbers, dots, underscores, or hyphens; consecutive dots are not allowed.", "error");
  else if (projectUnavailable) setThemeCustomizerStatus("This project is not saved as trusted in Pi. Choose Global themes or trust the project in Pi first.", "warn");
}

function themeCustomizerColor(theme, token) {
  try {
    return themeColorToRgb(theme.colors[token], theme.vars || {}, "#000000");
  } catch {
    return "#000000";
  }
}

function renderThemeCustomizerVisualFields(theme) {
  const container = elements.themeCustomizerVisualFields;
  if (!container || !theme) return;
  const groups = THEME_TOKEN_GROUPS.map((group) => {
    const fieldset = make("fieldset", "theme-token-group");
    fieldset.dataset.themeTokenGroup = group.id;
    fieldset.append(make("legend", undefined, group.label));
    const grid = make("div", "theme-token-grid");
    for (const { name, label } of group.tokens) {
      const row = make("div", "theme-token-row");
      row.dataset.themeToken = name;
      const inputId = `theme-token-${name}`;
      const copy = document.createElement("label");
      copy.className = "theme-token-label";
      copy.htmlFor = inputId;
      copy.append(document.createTextNode(label), make("code", undefined, name));
      const swatch = document.createElement("input");
      swatch.className = "theme-token-swatch";
      swatch.type = "color";
      const value = document.createElement("input");
      value.id = inputId;
      value.className = "theme-token-value";
      value.type = "text";
      value.autocomplete = "off";
      value.spellcheck = false;
      value.value = String(theme.colors[name] ?? "");
      value.setAttribute("aria-label", `${label} value`);
      const swatchNote = make("span", "theme-token-swatch-note");
      const syncSwatch = () => {
        const raw = value.value.trim();
        const directValue = themeCustomizerValue(raw);
        const direct = /^#[0-9a-f]{6}$/i.test(raw) || (typeof directValue === "number" && directValue >= 0 && directValue <= 255);
        swatch.disabled = !direct;
        swatch.value = direct ? themeColorToRgb(directValue, {}, "#000000") : themeCustomizerColor(theme, name);
        swatch.setAttribute("aria-label", direct
          ? `Choose ${label} color`
          : `${label} uses ${raw ? `variable ${raw}` : "the terminal default"}. Edit the raw value to replace it with a color.`);
        swatchNote.hidden = direct;
        swatchNote.textContent = raw ? `Variable ${raw}; edit the value to replace it.` : "Terminal default; edit the value to replace it.";
      };
      value.addEventListener("input", () => {
        syncSwatch();
        updateThemeCustomizerFromVisual();
      });
      swatch.addEventListener("input", () => {
        value.value = swatch.value;
        syncSwatch();
        updateThemeCustomizerFromVisual();
      });
      syncSwatch();
      row.append(copy, swatch, value, swatchNote);
      grid.append(row);
    }
    fieldset.append(grid);
    return fieldset;
  });
  container.replaceChildren(...groups);
}

function renderThemeCustomizerOptionalFields(theme) {
  if (!theme) return;
  if (elements.themeCustomizerThinkingMax) elements.themeCustomizerThinkingMax.value = String(theme.colors.thinkingMax ?? "");
  if (elements.themeCustomizerVars) elements.themeCustomizerVars.value = JSON.stringify(theme.vars || {}, null, 2);
  if (elements.themeCustomizerExportFields) {
    const fields = PI_THEME_EXPORT_FIELDS.map((name) => {
      const label = document.createElement("label");
      label.textContent = name;
      const input = document.createElement("input");
      input.type = "text";
      input.autocomplete = "off";
      input.spellcheck = false;
      input.dataset.themeExport = name;
      input.value = String(theme.export?.[name] ?? "");
      input.addEventListener("input", updateThemeCustomizerFromVisual);
      label.append(input);
      return label;
    });
    elements.themeCustomizerExportFields.replaceChildren(...fields);
  }
}

function themeCustomizerCandidateFromVisual() {
  const state = themeCustomizerState;
  if (!state?.validTheme) throw new Error("No valid theme draft is available.");
  const candidate = cloneThemeDraft(state.validTheme);
  candidate.name = elements.themeCustomizerName.value.trim();
  candidate.colors = { ...candidate.colors };
  for (const input of elements.themeCustomizerVisualFields.querySelectorAll("[data-theme-token] .theme-token-value")) {
    candidate.colors[input.closest("[data-theme-token]").dataset.themeToken] = themeCustomizerValue(input.value);
  }
  const thinkingMax = elements.themeCustomizerThinkingMax.value.trim();
  if (thinkingMax) candidate.colors.thinkingMax = themeCustomizerValue(thinkingMax);
  else delete candidate.colors.thinkingMax;
  let vars;
  try {
    vars = JSON.parse(elements.themeCustomizerVars.value || "{}");
  } catch (error) {
    throw new Error(`Variables JSON is invalid: ${error.message}`);
  }
  if (!vars || typeof vars !== "object" || Array.isArray(vars)) throw new Error("Variables must be a JSON object.");
  if (Object.keys(vars).length) candidate.vars = vars;
  else delete candidate.vars;
  const exportColors = {};
  for (const input of elements.themeCustomizerExportFields.querySelectorAll("[data-theme-export]")) {
    if (input.value.trim()) exportColors[input.dataset.themeExport] = themeCustomizerValue(input.value);
  }
  if (Object.keys(exportColors).length) candidate.export = exportColors;
  else delete candidate.export;
  return candidate;
}

function acceptThemeCustomizerDraft(candidate, { syncJson = true, syncControls = false } = {}) {
  const state = themeCustomizerState;
  if (!state) return false;
  const validation = validateTheme(candidate, { allowWebuiExport: true });
  if (!validation.ok) {
    state.draftValid = false;
    invalidateThemeCustomizerOverwrite();
    setThemeCustomizerStatus(validation.issues.map(({ path, message }) => `${path}: ${message}`).join(" · "), "error");
    updateThemeCustomizerActions();
    return false;
  }
  const canonical = canonicalizeTheme(candidate, { allowWebuiExport: true });
  state.validTheme = canonical;
  state.draftValid = true;
  invalidateThemeCustomizerOverwrite();
  if (syncJson && elements.themeCustomizerJson) elements.themeCustomizerJson.value = serializeTheme(canonical, { allowWebuiExport: true });
  if (syncControls) {
    elements.themeCustomizerName.value = canonical.name;
    renderThemeCustomizerVisualFields(canonical);
    renderThemeCustomizerOptionalFields(canonical);
  }
  applyTheme(canonical, { persist: false });
  setThemeCustomizerStatus("Valid draft previewed. Nothing has been written to browser storage or disk.", "success");
  updateThemeCustomizerActions();
  return true;
}

function updateThemeCustomizerFromVisual() {
  if (!themeCustomizerState) return;
  invalidateThemeCustomizerOverwrite();
  try {
    acceptThemeCustomizerDraft(themeCustomizerCandidateFromVisual(), { syncJson: true });
  } catch (error) {
    themeCustomizerState.draftValid = false;
    setThemeCustomizerStatus(error.message || String(error), "error");
    updateThemeCustomizerActions();
  }
}

function updateThemeCustomizerFromJson() {
  if (!themeCustomizerState) return;
  invalidateThemeCustomizerOverwrite();
  let candidate;
  try {
    candidate = JSON.parse(elements.themeCustomizerJson.value);
  } catch (error) {
    themeCustomizerState.draftValid = false;
    setThemeCustomizerStatus(`Advanced JSON is invalid: ${error.message}. The last valid preview remains active.`, "error");
    updateThemeCustomizerActions();
    return;
  }
  acceptThemeCustomizerDraft(candidate, { syncJson: false, syncControls: true });
}

function restoreThemeCustomizerOpeningState(generation) {
  const state = themeCustomizerState;
  if (!state || state.generation !== generation || state.restored) return;
  state.restored = true;
  applyTheme(state.opening.theme, { persist: false });
  setCustomBackgroundRecord(state.opening.background);
  customBackgroundLoading = false;
  applyCustomBackgroundOverride();
  renderThemeSelect();
}

function closeThemeCustomizer({ restore = true } = {}) {
  const state = themeCustomizerState;
  if (!state) {
    if (elements.themeCustomizerDialog?.open) elements.themeCustomizerDialog.close();
    return;
  }
  if (state.saving) {
    setThemeCustomizerStatus("Wait for the theme save to finish before closing or switching tabs.", "warn");
    return false;
  }
  const generation = state.generation;
  state.closing = true;
  if (restore) restoreThemeCustomizerOpeningState(generation);
  themeCustomizerState = null;
  if (elements.themeCustomizerDialog?.open) elements.themeCustomizerDialog.close();
  return true;
}

function themeCustomizerNameForSource(theme) {
  const raw = theme?.custom ? theme.name : `${theme?.name || "custom-theme"}-custom`;
  return raw.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[^A-Za-z0-9]+/, "").slice(0, 75) || "custom-theme";
}

function installThemeCatalog(data) {
  availableThemes = Array.isArray(data?.themes) ? data.themes : [];
  themeCatalogScopes = data?.scopes && typeof data.scopes === "object" ? data.scopes : themeCatalogScopes;
  optionalFeatureAvailability.themeBundle = availableThemes.length > 0;
  renderOptionalFeatureControls();
  renderThemeSelect();
}

async function refreshThemeCatalog(tabContext = activeTabContext()) {
  const response = await api("/api/themes", { tabId: tabContext.tabId });
  if (tabContext.tabId && !isCurrentTabContext(tabContext)) return response.data;
  installThemeCatalog(response.data || {});
  return response.data || {};
}

async function openThemeCustomizer() {
  if (!elements.themeCustomizerDialog || !availableThemes.length) return;
  const generation = ++themeCustomizerGeneration;
  const tabContext = activeTabContext();
  const openingTheme = availableThemes.find((theme) => theme.name === currentThemeName) || availableThemes[0];
  const opening = {
    theme: cloneThemeDraft(openingTheme),
    background: customBackground ? cloneThemeDraft(customBackground) : null,
  };
  themeCustomizerState = { generation, tabContext, opening, validTheme: null, draftValid: false, initialTheme: null, overwrite: null, saving: false, restored: false };
  setThemeCustomizerStatus("Loading project and global theme destinations…");
  try {
    await refreshThemeCatalog(tabContext);
  } catch (error) {
    if (themeCustomizerState?.generation === generation) setThemeCustomizerStatus(`Theme catalog refresh failed: ${error.message || String(error)}`, "warn");
  }
  if (themeCustomizerState?.generation !== generation) return;
  const source = availableThemes.find((theme) => theme.name === openingTheme.name) || openingTheme;
  const draft = canonicalizeTheme(themeDraftFromCatalog(source, themeCustomizerNameForSource(source)), { allowWebuiExport: true });
  themeCustomizerState.source = source;
  themeCustomizerState.initialTheme = cloneThemeDraft(draft);
  const projectTrusted = themeCatalogScopes.project?.trusted === true;
  elements.themeCustomizerProjectOption.disabled = !projectTrusted;
  elements.themeCustomizerScope.value = source.custom ? source.scope : projectTrusted ? "project" : "global";
  elements.themeCustomizerScopeHint.textContent = projectTrusted
    ? "Project saves use this active trusted tab’s .pi/themes directory; global saves use Pi’s agent themes directory."
    : "This active project is not saved as trusted in Pi, so only Global themes is available.";
  elements.themeCustomizerSourceBadge.textContent = `${themeScopeLabel(source.scope)} source`;
  elements.themeCustomizerSourceBadge.className = `theme-scope-badge ${source.scope || "bundled"}`;
  elements.themeCustomizerName.value = draft.name;
  renderThemeCustomizerVisualFields(draft);
  renderThemeCustomizerOptionalFields(draft);
  elements.themeCustomizerJson.value = serializeTheme(draft, { allowWebuiExport: true });
  themeCustomizerState.validTheme = draft;
  themeCustomizerState.draftValid = true;
  invalidateThemeCustomizerOverwrite();
  applyTheme(draft, { persist: false });
  setThemeCustomizerStatus("Valid draft previewed. Nothing has been written to browser storage or disk.", "success");
  updateThemeCustomizerActions();
  if (!elements.themeCustomizerDialog.open) elements.themeCustomizerDialog.showModal();
  queueMicrotask(() => elements.themeCustomizerName?.focus({ preventScroll: true }));
}

function showThemeCustomizerOverwrite(details) {
  const state = themeCustomizerState;
  if (!state) return;
  const scope = details?.scope;
  const fileName = details?.fileName;
  if (scope !== elements.themeCustomizerScope.value || fileName !== `${elements.themeCustomizerName.value.trim()}.json` || !Number.isFinite(details?.mtimeMs)) {
    setThemeCustomizerStatus("The server returned conflict details for a different target. Refresh the catalog and try again.", "error");
    return;
  }
  state.overwrite = { signature: themeCustomizerDraftSignature(state), scope, fileName, mtimeMs: details.mtimeMs };
  elements.themeCustomizerOverwriteMessage.textContent = `${themeScopeLabel(scope)} themes / ${fileName} already exists. Replace only this file with the current unchanged draft?`;
  elements.themeCustomizerOverwrite.hidden = false;
  setThemeCustomizerStatus("Review the exact target, then confirm replacement. Any draft, name, or destination change cancels this confirmation.", "warn");
  updateThemeCustomizerActions();
  elements.themeCustomizerOverwriteButton.focus();
}

async function saveThemeCustomizer({ overwrite = false } = {}) {
  const state = themeCustomizerState;
  if (!state?.draftValid || !state.validTheme || state.saving) return;
  if (!isCurrentTabContext(state.tabContext)) {
    setThemeCustomizerStatus("The active tab changed. Cancel and reopen Customize so the project destination is bound to the intended tab.", "warn");
    return;
  }
  const confirmation = state.overwrite;
  if (overwrite && (!confirmation || confirmation.signature !== themeCustomizerDraftSignature(state))) {
    invalidateThemeCustomizerOverwrite();
    setThemeCustomizerStatus("The overwrite confirmation no longer matches this target and draft. Save again to request a fresh confirmation.", "warn");
    updateThemeCustomizerActions();
    return;
  }
  const name = elements.themeCustomizerName.value.trim();
  const scope = elements.themeCustomizerScope.value;
  state.saving = true;
  updateThemeCustomizerActions();
  try {
    const response = await api("/api/themes/custom", {
      method: "POST",
      tabId: state.tabContext.tabId,
      body: {
        scope,
        fileName: `${name}.json`,
        theme: state.validTheme,
        overwrite,
        expectedMtimeMs: overwrite ? confirmation.mtimeMs : null,
      },
    });
    if (themeCustomizerState?.generation !== state.generation) return;
    invalidateThemeCustomizerOverwrite();
    await refreshThemeCatalog(state.tabContext);
    if (themeCustomizerState?.generation !== state.generation) return;
    applyTheme(state.validTheme, { persist: false });
    elements.themeCustomizerSourceBadge.textContent = `${themeScopeLabel(scope)} saved`;
    elements.themeCustomizerSourceBadge.className = `theme-scope-badge ${scope}`;
    setThemeCustomizerStatus(`Saved ${response.data?.fileName || `${name}.json`} to ${themeScopeLabel(scope)} themes. The WebUI catalog is refreshed. In Pi TUI, run /reload or restart, then choose it with /theme. No Pi or browser theme setting was changed.`, "success");
  } catch (error) {
    if (themeCustomizerState?.generation !== state.generation) return;
    const code = error.data?.code;
    if (code === "THEME_EXISTS") showThemeCustomizerOverwrite(error.data?.details);
    else if (code === "THEME_CHANGED") {
      invalidateThemeCustomizerOverwrite();
      setThemeCustomizerStatus("The target changed after confirmation and was not overwritten. Review the current file, then save again for a fresh target-bound confirmation.", "error");
    } else {
      const issues = error.data?.details?.issues;
      setThemeCustomizerStatus(Array.isArray(issues) && issues.length
        ? issues.map(({ path, message }) => `${path}: ${message}`).join(" · ")
        : error.message || String(error), "error");
    }
  } finally {
    if (themeCustomizerState?.generation === state.generation) {
      state.saving = false;
      updateThemeCustomizerActions();
    }
  }
}

function resetThemeCustomizerDraft() {
  const state = themeCustomizerState;
  if (!state?.initialTheme) return;
  const reset = cloneThemeDraft(state.initialTheme);
  elements.themeCustomizerName.value = reset.name;
  renderThemeCustomizerVisualFields(reset);
  renderThemeCustomizerOptionalFields(reset);
  acceptThemeCustomizerDraft(reset, { syncJson: true });
}

function renderThemeSelect({ unavailableLabel = "Theme bundle unavailable" } = {}) {
  if (!elements.themeSelect) return;
  elements.themeSelect.replaceChildren();
  if (isOptionalFeatureDisabled("themeBundle")) {
    const option = make("option", undefined, "Theme feature disabled");
    option.value = "";
    elements.themeSelect.append(option);
    elements.themeSelect.disabled = true;
    if (elements.themeCustomizeButton) elements.themeCustomizeButton.disabled = true;
    return;
  }
  if (!availableThemes.length) {
    const option = make("option", undefined, unavailableLabel);
    option.value = "";
    elements.themeSelect.append(option);
    elements.themeSelect.disabled = true;
    if (elements.themeCustomizeButton) elements.themeCustomizeButton.disabled = true;
    return;
  }
  elements.themeSelect.disabled = false;
  if (elements.themeCustomizeButton) elements.themeCustomizeButton.disabled = false;
  for (const theme of availableThemes) {
    const suffix = theme.custom ? ` · ${themeScopeLabel(theme.scope)}` : "";
    const option = make("option", undefined, `${theme.label || displayThemeName(theme.name) || theme.name}${suffix}`);
    option.value = theme.name;
    elements.themeSelect.append(option);
  }
  elements.themeSelect.value = currentThemeName;
  populateThemeSelect(availableThemes, elements.themeSearchInput?.value || "");
}

async function setThemeByName(name, options = {}) {
  if (!isOptionalFeatureEnabled("themeBundle")) return;
  const theme = availableThemes.find((item) => item.name === name);
  if (!theme) return;
  currentThemeName = theme.name;
  if (elements.themeSelect && elements.themeSelect.value !== theme.name) elements.themeSelect.value = theme.name;
  populateThemeSelect(availableThemes, elements.themeSearchInput?.value || "");
  setCustomBackgroundRecord(null);
  customBackgroundLoading = true;
  applyTheme(theme, options);
  renderBackgroundControl();
  await loadCustomBackgroundForTheme(theme.name, { includeLegacy: !!options.includeLegacy });
}

async function initializeThemes() {
  let response;
  try {
    response = await api("/api/themes", { scoped: false });
  } catch (error) {
    availableThemes = [];
    optionalFeatureAvailability.themeBundle = false;
    renderOptionalFeatureControls();
    const label = error.statusCode === 404 ? "Restart Web UI to load themes" : "Theme bundle unavailable";
    renderThemeSelect({ unavailableLabel: label });
    throw error;
  }
  availableThemes = Array.isArray(response.data?.themes) ? response.data.themes : [];
  themeCatalogScopes = response.data?.scopes && typeof response.data.scopes === "object" ? response.data.scopes : themeCatalogScopes;
  optionalFeatureAvailability.themeBundle = availableThemes.length > 0;
  renderOptionalFeatureControls();
  themeSchemeMode = storedThemeMode() ?? seedThemeSchemeFromStoredTheme();
  renderThemeSelect();
  renderThemeSchemeToggle();
  updateColorSchemeListener();
  await applySchemeTheme({ includeLegacy: true });
  if (!availableThemes.length) addEvent("theme bundle unavailable; using built-in default theme", "warn");
}

function activeTab() {
  return tabs.find((tab) => tab.id === activeTabId) || null;
}

function activeTabContext(tabId = activeTabId) {
  return { tabId: tabId || null, generation: activeTabGeneration };
}

function transcriptStreamOwner(tabId = activeTabId, generation = activeTabGeneration) {
  return `${tabId || ""}:${generation}`;
}

function unknownTranscriptEvidenceText(event) {
  const update = event?.assistantMessageEvent || {};
  const value = update.delta ?? update.content ?? update.text ?? update.thinking ?? "";
  if (typeof value === "string") return value.slice(0, UNKNOWN_TRANSCRIPT_EVIDENCE_TEXT_LIMIT);
  try {
    return JSON.stringify(value).slice(0, UNKNOWN_TRANSCRIPT_EVIDENCE_TEXT_LIMIT);
  } catch {
    return "[unserializable transcript evidence]";
  }
}

function preserveUnknownTranscriptEvidence(event, classification, owner) {
  const update = event?.assistantMessageEvent || {};
  const evidence = {
    owner: String(owner || ""),
    subtype: classification?.subtype || "(missing)",
    fields: Object.keys(update).slice(0, 16),
    text: unknownTranscriptEvidenceText(event),
    receivedAt: Date.now(),
  };
  appendBoundedStreamDiagnostic(unknownTranscriptEvidence, evidence, UNKNOWN_TRANSCRIPT_EVIDENCE_LIMIT);
  if (owner) {
    unknownTranscriptOwnersPendingReconcile.add(owner);
    while (unknownTranscriptOwnersPendingReconcile.size > UNKNOWN_TRANSCRIPT_EVIDENCE_LIMIT) {
      const oldest = unknownTranscriptOwnersPendingReconcile.values().next().value;
      if (oldest === undefined) break;
      unknownTranscriptOwnersPendingReconcile.delete(oldest);
    }
  }
  if (streamIsolationDebugLedger) {
    appendBoundedStreamDiagnostic(streamIsolationDebugLedger.unknownEvidence, evidence, UNKNOWN_TRANSCRIPT_EVIDENCE_LIMIT);
  }
}

function reconcileUnknownTranscriptEvidenceAtBarrier(event) {
  const tabContext = activeTabContext(event?.tabId || activeTabId);
  const owner = transcriptStreamOwner(tabContext.tabId, tabContext.generation);
  if (!unknownTranscriptOwnersPendingReconcile.delete(owner)) return false;
  if (!isCurrentTabContext(tabContext)) return false;
  scheduleSemanticReconcile({ messages: true }, tabContext);
  return true;
}

function setActiveTabId(tabId, { remember = false } = {}) {
  const nextTabId = tabId || null;
  if (nextTabId !== activeTabId) {
    activeTabGeneration += 1;
    intercomSummaryRequestSerial += 1;
    clearTimeout(intercomSummaryRefreshTimer);
    intercomSummaryRefreshTimer = null;
    closeIntercomConversationDialog({ restoreFocus: false });
    closeFeatureDecisionDialog({ restoreFocus: false });
    closeSessionSummaryOverlay({ restoreFocus: false });
  }
  activeTabId = nextTabId;
  renderMainOutputLoading();
  bindGitWorkflowToActiveTab();
  renderIntercomConversationTags(nextTabId);
  renderFeatureCategoryTag(nextTabId);
  renderSessionSummaryControls();
  if (remember) rememberActiveTab();
  return activeTabContext(nextTabId);
}

function isCurrentTabContext(context) {
  return !!context && context.tabId === activeTabId && context.generation === activeTabGeneration;
}

function normalizeFileTreePath(value = "") {
  return String(value || "").trim().replace(/\\/g, "/").replace(/^\.\/+/, "").replace(/^\/+/, "").replace(/\/+$/g, "");
}

function fileApiPath(basePath, filePath = "") {
  const path = normalizeFileTreePath(filePath);
  if (!path) return basePath;
  const params = new URLSearchParams({ path });
  return `${basePath}?${params.toString()}`;
}

function fileParentPath(filePath = "") {
  const normalized = normalizeFileTreePath(filePath);
  const index = normalized.lastIndexOf("/");
  return index === -1 ? FILE_TREE_ROOT_PATH : normalized.slice(0, index);
}

function fileDisplayName(path = "") {
  const normalized = normalizeFileTreePath(path);
  return normalized ? normalized.split("/").pop() || normalized : ".";
}

function fileEntryIcon(entry = {}) {
  if (entry.type === "directory") return "DIR";
  if (entry.type === "file") return entry.extension === ".md" || entry.extension === ".markdown" ? "Md" : "TXT";
  if (entry.type === "error") return "!";
  return "·";
}

function normalizeFileTreeGitStatus(status = {}) {
  if (!status || status.changed !== true) return null;
  const kind = ["changed", "modified", "staged", "untracked", "conflicted"].includes(String(status.kind || "")) ? String(status.kind) : "changed";
  return {
    changed: true,
    kind,
    status: String(status.status || "").slice(0, 4),
    direct: status.direct === true,
    changedDescendants: Math.max(0, Number(status.changedDescendants || 0) || 0),
  };
}

function fileTreeGitStatusForEntry(entry = {}) {
  return fileTreeState.gitStatusByPath.get(normalizeFileTreePath(entry.path || "")) || null;
}

function fileTreeEntryGitIgnored(entry = {}) {
  return entry?.gitIgnored === true;
}

function fileTreeGitIgnoredTitle(gitIgnored = false) {
  return gitIgnored ? "Ignored by Git" : "";
}

function fileTreeGitStatusClasses(status) {
  const normalized = normalizeFileTreeGitStatus(status);
  if (!normalized) return "";
  return `git-changed git-${normalized.kind} ${normalized.direct ? "git-direct" : "git-descendants"}`;
}

function fileTreeGitStatusTitle(status) {
  const normalized = normalizeFileTreeGitStatus(status);
  if (!normalized) return "";
  if (normalized.direct) {
    const state = normalized.status ? ` (${normalized.status})` : "";
    return `Git ${normalized.kind}${state}`;
  }
  const count = normalized.changedDescendants || 0;
  return count > 0 ? `Git changes in ${count} descendant${count === 1 ? "" : "s"}` : "Git changes in this folder";
}

function fileTreeGitStatusBadge(status) {
  const normalized = normalizeFileTreeGitStatus(status);
  if (!normalized) return null;
  const label = normalized.direct ? (normalized.status || "●") : (normalized.changedDescendants > 1 ? `Δ${normalized.changedDescendants}` : "Δ");
  const badge = make("span", `file-tree-git-badge ${normalized.kind} ${normalized.direct ? "direct" : "descendants"}`, label);
  badge.title = fileTreeGitStatusTitle(normalized);
  badge.setAttribute("aria-label", badge.title);
  return badge;
}

function updateFileTreeGitStatus(gitStatus, entries = []) {
  const next = new Map();
  for (const status of Array.isArray(gitStatus?.entries) ? gitStatus.entries : []) {
    const path = normalizeFileTreePath(status.path || "");
    const normalized = normalizeFileTreeGitStatus(status);
    if (path && normalized) next.set(path, normalized);
  }
  for (const entry of entries) {
    const path = normalizeFileTreePath(entry?.path || "");
    const normalized = normalizeFileTreeGitStatus(entry?.gitStatus);
    if (path && normalized) next.set(path, normalized);
  }
  fileTreeState.gitStatusRoot = String(gitStatus?.root || "");
  fileTreeState.gitStatusByPath = next;
}

function setFileTreeStatus(message = "", level = "muted") {
  if (!elements.fileTreeStatus) return;
  elements.fileTreeStatus.textContent = message;
  elements.fileTreeStatus.className = `file-tree-status ${level || "muted"}`;
}

function setFileViewerStatus(message = "", level = "muted") {
  if (!elements.fileViewerStatus) return;
  elements.fileViewerStatus.textContent = message;
  elements.fileViewerStatus.className = `file-viewer-status ${level || "muted"}`;
}

function emptyFileTreeState(requestSerial = 0) {
  return { root: "", entriesByPath: new Map(), expanded: new Set(), loading: new Set(), selectedPath: "", requestSerial, searchQuery: "", searchEntries: [], searchLoading: false, searchTruncated: false, searchTotal: 0, gitStatusRoot: "", gitStatusByPath: new Map() };
}

function fileTreeSearchQueryText() {
  return String(elements.fileTreeSearchInput?.value || "").trim();
}

function fileSearchApiPath(query = "") {
  const params = new URLSearchParams({ q: query });
  return `/api/files/search?${params.toString()}`;
}

function fileTreeEntriesStatus(entries = [], { truncated = false, total = entries.length, searchQuery = "" } = {}) {
  const count = entries.length;
  if (searchQuery) {
    if (!count) return `0 matches for “${searchQuery}”.`;
    const label = count === 1 ? "match" : "matches";
    return truncated ? `Showing first ${count} ${label} for “${searchQuery}”.` : `${count} ${label} for “${searchQuery}”.`;
  }
  return truncated ? `Showing ${count} of ${total || count} entries.` : `${count} item${count === 1 ? "" : "s"}.`;
}

function updateFileTreeSearchControls() {
  const query = fileTreeSearchQueryText();
  if (elements.fileTreeSearchClearButton) {
    elements.fileTreeSearchClearButton.hidden = !query;
    elements.fileTreeSearchClearButton.disabled = !query;
  }
}

function resetFileTreeState() {
  clearTimeout(fileTreeSearchTimer);
  fileTreeSearchTimer = null;
  fileTreeSearchRequestSerial += 1;
  fileTreeState = emptyFileTreeState(fileTreeState.requestSerial + 1);
  fileTreeLastRenderSignature = "";
  if (elements.fileTreeSearchInput) elements.fileTreeSearchInput.value = "";
  updateFileTreeSearchControls();
  renderFileTree();
}

function fileEntryByPath(filePath = "") {
  const normalized = normalizeFileTreePath(filePath);
  if (!normalized) return { name: ".", path: "", type: "directory", directory: true };
  for (const entries of fileTreeState.entriesByPath.values()) {
    const found = entries.find((entry) => normalizeFileTreePath(entry.path) === normalized);
    if (found) return found;
  }
  return null;
}

function fileTreeControlKey(node) {
  const path = normalizeFileTreePath(node?.dataset?.path || "");
  return node?.classList?.contains("file-tree-item") && path ? `file-tree:${path}` : "";
}

function fileTreeEntryRenderSignature(entry = {}) {
  return [
    normalizeFileTreePath(entry.path || ""),
    String(entry.name || ""),
    String(entry.type || ""),
    entry.directory === true,
    String(entry.extension || ""),
    String(entry.error || ""),
    fileTreeEntryGitIgnored(entry),
  ];
}

function fileTreeRenderSignature() {
  const entriesByPath = [...fileTreeState.entriesByPath.entries()]
    .map(([path, entries]) => [normalizeFileTreePath(path), (Array.isArray(entries) ? entries : []).map(fileTreeEntryRenderSignature)])
    .sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
  const gitStatusByPath = [...fileTreeState.gitStatusByPath.entries()]
    .map(([path, status]) => [normalizeFileTreePath(path), normalizeFileTreeGitStatus(status)])
    .sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
  return JSON.stringify({
    context: `${activeTabId || ""}:${activeTabGeneration}`,
    root: fileTreeState.root || "",
    displayCwd: fileTreeState.root || latestWorkspace?.displayCwd || activeTab()?.cwd || "",
    entriesByPath,
    expanded: [...fileTreeState.expanded].map(normalizeFileTreePath).sort(),
    loading: [...fileTreeState.loading].map(normalizeFileTreePath).sort(),
    selectedPath: normalizeFileTreePath(fileTreeState.selectedPath || ""),
    searchQuery: fileTreeState.searchQuery || fileTreeSearchQueryText(),
    searchEntries: fileTreeState.searchEntries.map(fileTreeEntryRenderSignature),
    searchLoading: fileTreeState.searchLoading,
    gitStatusRoot: fileTreeState.gitStatusRoot || "",
    gitStatusByPath,
  });
}

function renderFileTree() {
  if (deferUiRenderDuringPointerActivation("file-tree", renderFileTree)) return;
  const root = elements.fileTreeRoot;
  if (!root) return;
  const renderSignature = fileTreeRenderSignature();
  if (renderSignature === fileTreeLastRenderSignature) return;
  fileTreeLastRenderSignature = renderSignature;
  const continuityContextKey = `${activeTabId || ""}:${activeTabGeneration}:${fileTreeState.root || ""}`;
  const focusSnapshot = captureScopedControlContinuity(root, continuityContextKey, fileTreeControlKey);
  const restoreFocus = () => restoreScopedControlContinuity(root, continuityContextKey, focusSnapshot, (key) => [...root.querySelectorAll(".file-tree-item[data-path]")].find((node) => fileTreeControlKey(node) === key));
  root.replaceChildren();
  updateFileTreeSearchControls();
  if (elements.fileTreeCwd) elements.fileTreeCwd.textContent = fileTreeState.root || latestWorkspace?.displayCwd || activeTab()?.cwd || "";
  const searchQuery = fileTreeState.searchQuery || fileTreeSearchQueryText();
  root.classList.toggle("searching", !!searchQuery);
  if (searchQuery) {
    if (fileTreeState.searchLoading) {
      root.append(make("div", "file-tree-loading muted", `Searching for “${searchQuery}”…`));
      restoreFocus();
      return;
    }
    if (!fileTreeState.searchEntries.length) {
      root.append(make("div", "file-tree-empty muted", `No files or folders match “${searchQuery}”.`));
      restoreFocus();
      return;
    }
    const list = make("ul", "file-tree-list root search-results");
    list.setAttribute("role", "group");
    for (const entry of fileTreeState.searchEntries) appendFileSearchEntry(list, entry);
    root.append(list);
    syncFileTreeRovingTabindex();
    restoreFocus();
    return;
  }
  const entries = fileTreeState.entriesByPath.get(FILE_TREE_ROOT_PATH) || [];
  if (!entries.length) {
    root.append(make("div", "file-tree-empty muted", fileTreeState.loading.has(FILE_TREE_ROOT_PATH) ? "Loading files…" : "No files loaded."));
    restoreFocus();
    return;
  }
  const list = make("ul", "file-tree-list root");
  list.setAttribute("role", "group");
  for (const entry of entries) appendFileTreeEntry(list, entry, 0);
  root.append(list);
  syncFileTreeRovingTabindex();
  restoreFocus();
}

function visibleFileTreeItems() {
  return [...elements.fileTreeRoot?.querySelectorAll('[role="treeitem"]') || []];
}

function syncFileTreeRovingTabindex(preferredPath = fileTreeState.selectedPath) {
  const items = visibleFileTreeItems();
  const active = items.find((item) => normalizeFileTreePath(item.dataset.path) === normalizeFileTreePath(preferredPath)) || items[0];
  for (const item of items) item.tabIndex = item === active ? 0 : -1;
}

function selectFileTreePath(path, { focus = false } = {}) {
  fileTreeState.selectedPath = normalizeFileTreePath(path);
  renderFileTree();
  if (focus) {
    const selected = visibleFileTreeItems().find((item) => normalizeFileTreePath(item.dataset.path) === fileTreeState.selectedPath);
    selected?.focus({ preventScroll: true });
  }
}

function fileTreeOverflowButton(entry) {
  const button = make("button", "file-tree-overflow-button", "⋯");
  button.type = "button";
  button.setAttribute("aria-label", `Actions for ${entry.name || fileDisplayName(entry.path)}`);
  button.setAttribute("aria-haspopup", "menu");
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    showFileContextMenuForElement(button, entry);
  });
  return button;
}

function fileTreeExpander(expanded = false) {
  const arrow = make("span", "file-tree-expander", expanded ? "▾" : "▸");
  arrow.setAttribute("aria-hidden", "true");
  return arrow;
}

function appendFileSearchEntry(parent, entry) {
  const path = normalizeFileTreePath(entry.path);
  const isDirectory = entry.type === "directory" || entry.directory === true;
  const expanded = isDirectory && fileTreeState.expanded.has(path);
  const loading = isDirectory && fileTreeState.loading.has(path);
  const gitStatus = fileTreeGitStatusForEntry(entry);
  const gitStatusClasses = fileTreeGitStatusClasses(gitStatus);
  const gitIgnored = fileTreeEntryGitIgnored(entry);
  const item = make("li", `file-tree-node file-tree-search-node ${entry.type || "file"}${gitStatusClasses ? ` ${gitStatusClasses}` : ""}${gitIgnored ? " git-ignored" : ""}${expanded ? " expanded" : ""}${fileTreeState.selectedPath === path ? " selected" : ""}`);
  item.setAttribute("role", "none");
  const button = make("button", "file-tree-item file-tree-search-item");
  button.type = "button";
  button.dataset.path = path;
  button.dataset.type = entry.type || "file";
  button.style.setProperty("--file-tree-depth", "0");
  button.setAttribute("role", "treeitem");
  button.setAttribute("aria-selected", fileTreeState.selectedPath === path ? "true" : "false");
  if (isDirectory) {
    button.setAttribute("aria-expanded", expanded ? "true" : "false");
    button.setAttribute("aria-label", `${expanded ? "Collapse" : "Expand"} ${entry.name || fileDisplayName(path)}`);
  }
  button.title = [path || ".", fileTreeGitIgnoredTitle(gitIgnored), fileTreeGitStatusTitle(gitStatus), entry.error || ""].filter(Boolean).join("\n");
  const contextPath = fileParentPath(path) || ".";
  const label = make("span", "file-tree-search-label");
  label.append(
    make("span", "file-tree-name", entry.name || fileDisplayName(path)),
    make("span", "file-tree-search-path", contextPath),
  );
  button.append(
    isDirectory ? fileTreeExpander(expanded) : make("span", "file-tree-expander-spacer"),
    make("span", "file-tree-icon", loading ? "…" : fileEntryIcon(entry)),
    label,
  );
  const gitBadge = fileTreeGitStatusBadge(gitStatus);
  if (gitBadge) button.append(gitBadge);
  if (entry.type === "file") button.append(make("span", "file-tree-kind", entry.extension || "file"));
  else if (entry.type && entry.type !== "directory") button.append(make("span", "file-tree-kind", entry.type));
  if (entry.error) button.append(make("span", "file-tree-error", entry.error));
  button.addEventListener("click", () => {
    fileTreeState.selectedPath = path;
    if (entry.type === "file") openFileInViewer(path);
    else toggleFileTreeDirectory(path).catch((error) => addEvent(error.message || String(error), "error"));
  });
  button.addEventListener("contextmenu", (event) => showFileContextMenu(event, entry));
  bindFileTreeDragAndDrop(button, item, entry);
  item.append(button, fileTreeOverflowButton(entry));
  if (isDirectory && expanded) {
    const children = fileTreeState.entriesByPath.get(path) || [];
    const childList = make("ul", "file-tree-list");
    childList.setAttribute("role", "group");
    if (loading) childList.append(make("li", "file-tree-loading muted", "Loading…"));
    else if (!children.length) childList.append(make("li", "file-tree-empty muted", "Empty"));
    else for (const child of children) appendFileTreeEntry(childList, child, 1);
    item.append(childList);
  }
  parent.append(item);
}

async function revealFileTreeEntry(entry = {}, { expandTarget = true } = {}) {
  const targetPath = normalizeFileTreePath(entry.path || "");
  if (!targetPath && targetPath !== FILE_TREE_ROOT_PATH) return;
  const isDirectory = entry.type === "directory" || entry.directory === true;
  const parentPath = fileParentPath(targetPath);
  fileTreeState.selectedPath = targetPath;
  await loadFileTreeDirectory(FILE_TREE_ROOT_PATH);
  let currentPath = "";
  for (const part of parentPath.split("/").filter(Boolean)) {
    currentPath = currentPath ? `${currentPath}/${part}` : part;
    fileTreeState.expanded.add(currentPath);
    renderFileTree();
    await loadFileTreeDirectory(currentPath);
  }
  if (isDirectory && expandTarget) {
    fileTreeState.expanded.add(targetPath);
    await loadFileTreeDirectory(targetPath);
  }
  fileTreeState.selectedPath = targetPath;
  renderFileTree();
}

function appendFileTreeEntry(parent, entry, depth = 0) {
  const path = normalizeFileTreePath(entry.path);
  const isDirectory = entry.type === "directory" || entry.directory === true;
  const expanded = isDirectory && fileTreeState.expanded.has(path);
  const loading = isDirectory && fileTreeState.loading.has(path);
  const gitStatus = fileTreeGitStatusForEntry(entry);
  const gitStatusClasses = fileTreeGitStatusClasses(gitStatus);
  const gitIgnored = fileTreeEntryGitIgnored(entry);
  const item = make("li", `file-tree-node ${entry.type || "file"}${gitStatusClasses ? ` ${gitStatusClasses}` : ""}${gitIgnored ? " git-ignored" : ""}${expanded ? " expanded" : ""}${fileTreeState.selectedPath === path ? " selected" : ""}`);
  item.setAttribute("role", "none");
  const button = make("button", "file-tree-item");
  button.type = "button";
  button.dataset.path = path;
  button.dataset.type = entry.type || "file";
  button.style.setProperty("--file-tree-depth", String(depth));
  button.setAttribute("role", "treeitem");
  button.setAttribute("aria-selected", fileTreeState.selectedPath === path ? "true" : "false");
  if (isDirectory) {
    button.setAttribute("aria-expanded", expanded ? "true" : "false");
    button.setAttribute("aria-label", `${expanded ? "Collapse" : "Expand"} ${entry.name || fileDisplayName(path)}`);
  }
  button.title = [path || ".", fileTreeGitIgnoredTitle(gitIgnored), fileTreeGitStatusTitle(gitStatus), entry.error || ""].filter(Boolean).join("\n");
  button.append(
    isDirectory ? fileTreeExpander(expanded) : make("span", "file-tree-expander-spacer"),
    make("span", `file-tree-icon ${isDirectory && expanded ? "expanded" : ""}`, loading ? "…" : fileEntryIcon(entry)),
    make("span", "file-tree-name", entry.name || fileDisplayName(path)),
  );
  const gitBadge = fileTreeGitStatusBadge(gitStatus);
  if (gitBadge) button.append(gitBadge);
  if (entry.type === "file") button.append(make("span", "file-tree-kind", entry.extension || "file"));
  if (entry.error) button.append(make("span", "file-tree-error", entry.error));
  button.addEventListener("click", () => {
    fileTreeState.selectedPath = path;
    if (entry.type === "file") openFileInViewer(path);
    else toggleFileTreeDirectory(path).catch((error) => addEvent(error.message || String(error), "error"));
  });
  button.addEventListener("contextmenu", (event) => showFileContextMenu(event, entry));
  bindFileTreeDragAndDrop(button, item, entry);
  item.append(button, fileTreeOverflowButton(entry));
  if (isDirectory && expanded) {
    const children = fileTreeState.entriesByPath.get(path) || [];
    const childList = make("ul", "file-tree-list");
    childList.setAttribute("role", "group");
    if (loading) childList.append(make("li", "file-tree-loading muted", "Loading…"));
    else if (!children.length) childList.append(make("li", "file-tree-empty muted", "Empty"));
    else for (const child of children) appendFileTreeEntry(childList, child, depth + 1);
    item.append(childList);
  }
  parent.append(item);
}

async function loadFileTreeDirectory(path = FILE_TREE_ROOT_PATH, { force = false, renderResult = true } = {}) {
  const normalized = normalizeFileTreePath(path);
  if (!force && fileTreeState.entriesByPath.has(normalized)) return fileTreeState.entriesByPath.get(normalized);
  const tabContext = activeTabContext();
  if (!tabContext.tabId || fileTreeState.loading.has(normalized)) return [];
  const serial = ++fileTreeState.requestSerial;
  const hadCachedEntries = fileTreeState.entriesByPath.has(normalized);
  fileTreeState.loading.add(normalized);
  if (!hadCachedEntries) {
    setFileTreeStatus(normalized ? `Loading ${normalized}…` : "Loading workspace files…");
    renderFileTree();
  }
  try {
    const response = await api(fileApiPath("/api/files", normalized), { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext) || serial < fileTreeState.requestSerial) return [];
    const data = response.data || {};
    if (!normalized && data.root && data.root !== fileTreeState.root) {
      fileTreeState.root = data.root;
      fileTreeState.entriesByPath.clear();
      fileTreeState.expanded.clear();
    }
    const entries = Array.isArray(data.entries) ? data.entries : [];
    updateFileTreeGitStatus(data.gitStatus, entries);
    fileTreeState.entriesByPath.set(normalized, entries);
    if (!normalized || !hadCachedEntries) {
      setFileTreeStatus(fileTreeEntriesStatus(entries, { truncated: data.truncated, total: data.total || entries.length }));
    }
    return entries;
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      setFileTreeStatus(error.message || String(error), "error");
      addEvent(`file tree failed: ${error.message || String(error)}`, "error");
    }
    return [];
  } finally {
    fileTreeState.loading.delete(normalized);
    if (renderResult && isCurrentTabContext(tabContext)) renderFileTree();
  }
}

function focusVisibleFileTreeSelection(path = fileTreeState.selectedPath) {
  const normalized = normalizeFileTreePath(path);
  if (!normalized) return false;
  const selected = visibleFileTreeItems().find((item) => normalizeFileTreePath(item.dataset.path) === normalized);
  if (!selected) return false;
  selected.focus({ preventScroll: true });
  selected.scrollIntoView?.({ block: "nearest" });
  return true;
}

function clearFileTreeSearch({ focus = false } = {}) {
  clearTimeout(fileTreeSearchTimer);
  fileTreeSearchTimer = null;
  fileTreeSearchRequestSerial += 1;
  const serial = fileTreeSearchRequestSerial;
  const selectedPath = normalizeFileTreePath(fileTreeState.selectedPath || "");
  const selectedEntry = fileTreeState.searchEntries.find((entry) => normalizeFileTreePath(entry.path) === selectedPath) || fileEntryByPath(selectedPath);
  const selectedDirectoryExpanded = fileTreeState.expanded.has(selectedPath);
  if (elements.fileTreeSearchInput) elements.fileTreeSearchInput.value = "";
  updateFileTreeSearchControls();

  const commitClear = () => {
    if (serial !== fileTreeSearchRequestSerial || fileTreeSearchQueryText()) return;
    fileTreeState.searchQuery = "";
    fileTreeState.searchEntries = [];
    fileTreeState.searchLoading = false;
    fileTreeState.searchTruncated = false;
    fileTreeState.searchTotal = 0;
    const rootEntries = fileTreeState.entriesByPath.get(FILE_TREE_ROOT_PATH) || [];
    setFileTreeStatus(rootEntries.length ? fileTreeEntriesStatus(rootEntries) : "");
    renderFileTree();
    if (selectedPath && focusVisibleFileTreeSelection(selectedPath)) return;
    if (focus) elements.fileTreeSearchInput?.focus();
  };

  if (!selectedPath || !selectedEntry) {
    commitClear();
    return;
  }
  revealFileTreeEntry(selectedEntry, { expandTarget: selectedDirectoryExpanded }).then(commitClear).catch((error) => {
    addEvent(error.message || String(error), "error");
    commitClear();
  });
}

async function runFileTreeSearch({ background = false } = {}) {
  clearTimeout(fileTreeSearchTimer);
  fileTreeSearchTimer = null;
  const query = fileTreeSearchQueryText();
  fileTreeSearchRequestSerial += 1;
  const serial = fileTreeSearchRequestSerial;
  if (!query) {
    clearFileTreeSearch();
    return [];
  }
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return [];
  fileTreeState.searchQuery = query;
  if (!background) {
    fileTreeState.searchLoading = true;
    fileTreeState.searchEntries = [];
    fileTreeState.searchTruncated = false;
    fileTreeState.searchTotal = 0;
    setFileTreeStatus(`Searching for “${query}”…`);
    renderFileTree();
  }
  try {
    const response = await api(fileSearchApiPath(query), { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext) || serial !== fileTreeSearchRequestSerial) return [];
    const data = response.data || {};
    const entries = Array.isArray(data.entries) ? data.entries : [];
    if (data.root) fileTreeState.root = data.root;
    updateFileTreeGitStatus(data.gitStatus, entries);
    fileTreeState.searchQuery = data.query || query;
    fileTreeState.searchEntries = entries;
    fileTreeState.searchLoading = false;
    fileTreeState.searchTruncated = !!data.truncated;
    fileTreeState.searchTotal = Number(data.total || entries.length) || entries.length;
    setFileTreeStatus(fileTreeEntriesStatus(entries, { truncated: data.truncated, total: data.total || entries.length, searchQuery: fileTreeState.searchQuery }), entries.length ? "success" : "muted");
    return entries;
  } catch (error) {
    if (isCurrentTabContext(tabContext) && serial === fileTreeSearchRequestSerial) {
      if (!background) {
        fileTreeState.searchLoading = false;
        fileTreeState.searchEntries = [];
      }
      setFileTreeStatus(error.message || String(error), "error");
      addEvent(`file search failed: ${error.message || String(error)}`, "error");
    }
    return [];
  } finally {
    if (isCurrentTabContext(tabContext) && serial === fileTreeSearchRequestSerial) renderFileTree();
  }
}

function scheduleFileTreeSearch(delay = 180) {
  clearTimeout(fileTreeSearchTimer);
  const query = fileTreeSearchQueryText();
  updateFileTreeSearchControls();
  if (!query) {
    clearFileTreeSearch();
    return;
  }
  fileTreeSearchRequestSerial += 1;
  fileTreeState.searchQuery = query;
  fileTreeState.searchLoading = true;
  setFileTreeStatus(`Searching for “${query}”…`);
  renderFileTree();
  fileTreeSearchTimer = setTimeout(() => {
    runFileTreeSearch().catch((error) => addEvent(error.message || String(error), "error"));
  }, delay);
}

async function refreshFileTreeRoot(tabContext = activeTabContext()) {
  if (!tabContext.tabId || !elements.fileTreeRoot) return;
  if (!isCurrentTabContext(tabContext)) return;
  if (fileTreeSearchQueryText()) await runFileTreeSearch();
  else await loadFileTreeDirectory(FILE_TREE_ROOT_PATH, { force: true });
}

let fileTreeLiveRefreshInProgress = false;
let fileTreeLiveRefreshPendingContext = null;
let fileTreeLiveRefreshRetryTimer = null;

async function refreshLoadedFileTreeDirectories(tabContext = activeTabContext()) {
  const knownDirectories = new Set();
  const collectDirectories = (path) => {
    for (const entry of fileTreeState.entriesByPath.get(path) || []) {
      if (entry.type === "directory" || entry.directory === true) knownDirectories.add(normalizeFileTreePath(entry.path || ""));
    }
  };
  if (fileTreeState.loading.has(FILE_TREE_ROOT_PATH)) return true;
  await loadFileTreeDirectory(FILE_TREE_ROOT_PATH, { force: true, renderResult: false });
  if (!isCurrentTabContext(tabContext)) return false;
  collectDirectories(FILE_TREE_ROOT_PATH);
  const cachedDirectories = [...fileTreeState.entriesByPath.keys()]
    .filter((path) => path !== FILE_TREE_ROOT_PATH)
    .sort((a, b) => a.split("/").length - b.split("/").length || (a < b ? -1 : a > b ? 1 : 0));
  let skippedLoadingDirectory = false;
  for (const path of cachedDirectories) {
    if (!isCurrentTabContext(tabContext)) return false;
    if (!knownDirectories.has(path)) {
      clearFileTreeEntryCache(path);
      continue;
    }
    if (fileTreeState.loading.has(path)) {
      skippedLoadingDirectory = true;
      collectDirectories(path);
      continue;
    }
    await loadFileTreeDirectory(path, { force: true, renderResult: false });
    if (!isCurrentTabContext(tabContext)) return false;
    collectDirectories(path);
  }
  renderFileTree();
  return skippedLoadingDirectory;
}

async function refreshFileTreeLive(tabContext = activeTabContext()) {
  if (!tabContext.tabId || !elements.fileTreeRoot) return;
  if (!isCurrentTabContext(tabContext)) return;
  clearTimeout(fileTreeLiveRefreshRetryTimer);
  fileTreeLiveRefreshRetryTimer = null;
  if (fileTreeLiveRefreshInProgress) {
    fileTreeLiveRefreshPendingContext = tabContext;
    return;
  }
  fileTreeLiveRefreshInProgress = true;
  let retryContext = null;
  try {
    let refreshContext = tabContext;
    while (refreshContext && isCurrentTabContext(refreshContext)) {
      fileTreeLiveRefreshPendingContext = null;
      let skippedLoadingDirectory = false;
      if (fileTreeSearchQueryText()) await runFileTreeSearch({ background: true });
      else skippedLoadingDirectory = await refreshLoadedFileTreeDirectories(refreshContext);
      if (skippedLoadingDirectory && isCurrentTabContext(refreshContext)) retryContext = refreshContext;
      refreshContext = fileTreeLiveRefreshPendingContext;
    }
  } finally {
    fileTreeLiveRefreshInProgress = false;
    const pendingContext = fileTreeLiveRefreshPendingContext;
    fileTreeLiveRefreshPendingContext = null;
    const nextContext = pendingContext && isCurrentTabContext(pendingContext)
      ? pendingContext
      : retryContext && isCurrentTabContext(retryContext)
        ? retryContext
        : null;
    if (nextContext) {
      fileTreeLiveRefreshRetryTimer = setTimeout(() => {
        fileTreeLiveRefreshRetryTimer = null;
        refreshFileTreeLive(nextContext).catch((error) => addEvent(error.message || String(error), "error"));
      }, 50);
    }
  }
}

async function toggleFileTreeDirectory(path = "", { force = false } = {}) {
  const normalized = normalizeFileTreePath(path);
  if (!normalized && normalized !== FILE_TREE_ROOT_PATH) return;
  const currentlyExpanded = fileTreeState.expanded.has(normalized);
  if (currentlyExpanded && !force) {
    fileTreeState.expanded.delete(normalized);
    renderFileTree();
    return;
  }
  fileTreeState.expanded.add(normalized);
  renderFileTree();
  await loadFileTreeDirectory(normalized);
}

function closeFileContextMenu({ returnFocus = true } = {}) {
  const trigger = fileContextMenuState?.trigger;
  fileContextMenuState = null;
  if (elements.fileContextMenu) elements.fileContextMenu.hidden = true;
  if (returnFocus && trigger?.isConnected) queueMicrotask(() => trigger.focus({ preventScroll: true }));
}

function showFileContextMenu(event, entry) {
  if (!elements.fileContextMenu) return;
  event.preventDefault();
  event.stopPropagation();
  closeGitPanelContextMenu({ returnFocus: false });
  closeSidePanelContextMenu({ returnFocus: false });
  closeEventTreeContextMenu({ returnFocus: false });
  const path = normalizeFileTreePath(entry?.path || "");
  fileContextMenuState = { entry: { ...entry, path }, trigger: event.currentTarget || document.activeElement };
  const menu = elements.fileContextMenu;
  const webui = menu.querySelector('[data-file-menu-action="open-webui"]');
  if (webui) webui.textContent = entry?.type === "directory" ? "Open in WebUI" : "Open in WebUI";
  menu.hidden = false;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(event.clientX, Math.max(0, window.innerWidth - rect.width - 8));
  const top = Math.min(event.clientY, Math.max(0, window.innerHeight - rect.height - 8));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
  menu.querySelector('[role="menuitem"]')?.focus({ preventScroll: true });
}

function showFileContextMenuForElement(element, entry) {
  const rect = element.getBoundingClientRect();
  showFileContextMenu({
    preventDefault() {},
    stopPropagation() {},
    clientX: rect.right,
    clientY: rect.bottom,
    currentTarget: element,
  }, entry);
}

function handleFileTreeKeydown(event) {
  const current = event.target?.closest?.('[role="treeitem"]');
  if (!current || !elements.fileTreeRoot?.contains(current)) return;
  const items = visibleFileTreeItems();
  const index = items.indexOf(current);
  if (index < 0) return;
  const focusAt = (nextIndex) => {
    const next = items[Math.max(0, Math.min(items.length - 1, nextIndex))];
    if (!next) return;
    event.preventDefault();
    selectFileTreePath(next.dataset.path, { focus: true });
  };
  if (event.key === "ArrowDown") focusAt(index + 1);
  else if (event.key === "ArrowUp") focusAt(index - 1);
  else if (event.key === "Home") focusAt(0);
  else if (event.key === "End") focusAt(items.length - 1);
  else if (event.key === "ArrowRight" && current.dataset.type === "directory") {
    event.preventDefault();
    if (current.getAttribute("aria-expanded") !== "true") toggleFileTreeDirectory(current.dataset.path);
    else focusAt(index + 1);
  } else if (event.key === "ArrowLeft" && current.dataset.type === "directory" && current.getAttribute("aria-expanded") === "true") {
    event.preventDefault();
    toggleFileTreeDirectory(current.dataset.path);
  } else if (event.key === "Enter" && current.dataset.type === "directory") {
    event.preventDefault();
    toggleFileTreeDirectory(current.dataset.path);
  }
}

function currentFileViewerPath() {
  return normalizeFileTreePath(activeFileViewer?.path || elements.fileViewerOpenDefaultButton?.dataset.path || "");
}

async function openPathInDefaultEditor(path = currentFileViewerPath()) {
  const normalized = normalizeFileTreePath(path);
  if (!normalized) {
    addEvent("No file is currently open in the WebUI viewer.", "warn");
    return;
  }
  const tabContext = activeTabContext();
  try {
    const response = await api("/api/files/open-default", { method: "POST", body: { path: normalized }, tabId: tabContext.tabId });
    if (isCurrentTabContext(tabContext)) addEvent(`opened ${response.data?.path || normalized || "."} in the default editor`, "info");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
  }
}

function filePathWithinOrEqual(filePath = "", parentPath = "") {
  const path = normalizeFileTreePath(filePath);
  const parent = normalizeFileTreePath(parentPath);
  if (!parent) return path === parent;
  return path === parent || path.startsWith(`${parent}/`);
}

function remapFileTreePathAfterMove(filePath = "", sourcePath = "", destinationPath = "") {
  const path = normalizeFileTreePath(filePath);
  const source = normalizeFileTreePath(sourcePath);
  const destination = normalizeFileTreePath(destinationPath);
  if (!path || !source || !destination) return path;
  if (path === source) return destination;
  return path.startsWith(`${source}/`) ? `${destination}/${path.slice(source.length + 1)}` : path;
}

function fileExtensionForPath(filePath = "") {
  const name = fileDisplayName(filePath);
  const dot = name.lastIndexOf(".");
  return dot > 0 ? name.slice(dot).toLowerCase() : "";
}

function fileLanguageForPath(filePath = "") {
  const extension = fileExtensionForPath(filePath);
  return extension === ".md" || extension === ".markdown" ? "markdown" : "text";
}

function fileOperationTypeLabel(entry = {}) {
  if (entry.type === "directory" || entry.directory === true) return "directory";
  if (entry.type === "file" || entry.file === true) return "file";
  return "entry";
}

function fileTreeEntryIsMovable(entry = {}) {
  const path = normalizeFileTreePath(entry.path || "");
  return !!path && (entry.type === "file" || entry.file === true || entry.type === "directory" || entry.directory === true);
}

function fileTreeEntryIsDirectory(entry = {}) {
  return entry.type === "directory" || entry.directory === true;
}

function fileTreeDragSourceFromEvent(event) {
  const statePath = normalizeFileTreePath(fileTreeDragState?.sourcePath || "");
  return statePath ? { path: statePath, type: fileTreeDragState?.sourceType || "entry", entry: fileTreeDragState?.entry || null } : null;
}

function fileTreeEntryFromElement(element) {
  const path = normalizeFileTreePath(element?.dataset?.path || "");
  const type = element?.dataset?.type || "";
  return path || type ? { path, type, directory: type === "directory", file: type === "file" } : null;
}

function fileTreeDropTargetFromEvent(event) {
  const button = event?.target?.closest?.(".file-tree-item");
  if (!button || !elements.fileTreeRoot?.contains?.(button)) return null;
  const entry = fileTreeEntryFromElement(button);
  if (!entry || !fileTreeEntryIsDirectory(entry)) return null;
  return { entry, item: button.closest(".file-tree-node"), button };
}

function fileTreeCanDropOnDirectory(sourcePath = "", targetDirectoryPath = "", sourceEntry = fileTreeDragState?.entry) {
  const source = normalizeFileTreePath(sourcePath);
  const target = normalizeFileTreePath(targetDirectoryPath);
  if (!source) return false;
  if (fileParentPath(source) === target) return false;
  if (fileTreeEntryIsDirectory(sourceEntry || {}) && (target === source || target.startsWith(`${source}/`))) return false;
  return true;
}

function clearFileTreeDragVisuals() {
  for (const node of document.querySelectorAll(".file-tree-node.dragging, .file-tree-node.drop-target, .file-tree-node.drop-blocked")) {
    node.classList.remove("dragging", "drop-target", "drop-blocked");
  }
  elements.fileTreeRoot?.classList.remove("drag-root-drop", "drop-blocked");
}

function finishFileTreeDrag() {
  clearFileTreeDragVisuals();
  fileTreeDragState = null;
}

function beginFileTreeDrag(event, entry = {}, item) {
  if (!fileTreeEntryIsMovable(entry)) {
    event.preventDefault();
    return;
  }
  const sourcePath = normalizeFileTreePath(entry.path || "");
  closeFileContextMenu();
  fileTreeDragState = { sourcePath, sourceType: fileOperationTypeLabel(entry), entry: { ...entry, path: sourcePath } };
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData(FILE_TREE_DRAG_MIME, sourcePath);
  event.dataTransfer.setData("text/plain", sourcePath);
  item?.classList.add("dragging");
  setFileTreeStatus(`Drag ${sourcePath} onto a folder or empty file-tree space to move it.`);
}

function updateFileTreeDropTarget(event, entry = {}, item) {
  const source = fileTreeDragSourceFromEvent(event);
  if (!source || !fileTreeEntryIsDirectory(entry)) return false;
  const targetPath = normalizeFileTreePath(entry.path || "");
  const allowed = fileTreeCanDropOnDirectory(source.path, targetPath, source.entry);
  for (const node of document.querySelectorAll(".file-tree-node.drop-target, .file-tree-node.drop-blocked")) node.classList.remove("drop-target", "drop-blocked");
  elements.fileTreeRoot?.classList.remove("drag-root-drop", "drop-blocked");
  if (!allowed) {
    item?.classList.add("drop-blocked");
    event.dataTransfer.dropEffect = "none";
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  event.dataTransfer.dropEffect = "move";
  item?.classList.add("drop-target");
  if (fileTreeDragState) fileTreeDragState.targetPath = targetPath;
  return true;
}

function clearFileTreeDropTarget(event, item) {
  if (!item?.contains?.(event.relatedTarget)) item?.classList.remove("drop-target", "drop-blocked");
}

async function dropFileTreeEntry(event, entry = {}) {
  const source = fileTreeDragSourceFromEvent(event);
  if (!source || !fileTreeEntryIsDirectory(entry)) return;
  const targetPath = normalizeFileTreePath(entry.path || "");
  if (!fileTreeCanDropOnDirectory(source.path, targetPath, source.entry)) return;
  event.preventDefault();
  event.stopPropagation();
  finishFileTreeDrag();
  await moveFileTreeEntryToDestination(source.entry || { path: source.path, type: source.type }, targetPath, { viaDragDrop: true });
}

function bindFileTreeDragAndDrop(button, item, entry = {}) {
  if (!button || !item) return;
  const movable = fileTreeEntryIsMovable(entry);
  button.draggable = movable;
  button.classList.toggle("file-tree-draggable", movable);
  if (movable) {
    button.addEventListener("dragstart", (event) => beginFileTreeDrag(event, entry, item));
    button.addEventListener("dragend", finishFileTreeDrag);
  }
  if (fileTreeEntryIsDirectory(entry)) {
    for (const target of [button, item]) {
      target.addEventListener("dragenter", (event) => updateFileTreeDropTarget(event, entry, item));
      target.addEventListener("dragover", (event) => updateFileTreeDropTarget(event, entry, item));
      target.addEventListener("dragleave", (event) => clearFileTreeDropTarget(event, item));
      target.addEventListener("drop", (event) => dropFileTreeEntry(event, entry).catch((error) => addEvent(error.message || String(error), "error")));
    }
  }
}

function handleFileTreeRootDragOver(event) {
  const delegatedTarget = fileTreeDropTargetFromEvent(event);
  if (delegatedTarget) {
    updateFileTreeDropTarget(event, delegatedTarget.entry, delegatedTarget.item);
    return;
  }
  const source = fileTreeDragSourceFromEvent(event);
  if (!source) return;
  const allowed = fileTreeCanDropOnDirectory(source.path, FILE_TREE_ROOT_PATH, source.entry);
  elements.fileTreeRoot?.classList.toggle("drop-blocked", !allowed);
  if (!allowed) {
    event.dataTransfer.dropEffect = "none";
    return;
  }
  event.preventDefault();
  event.dataTransfer.dropEffect = "move";
  elements.fileTreeRoot?.classList.add("drag-root-drop");
}

function handleFileTreeRootDragLeave(event) {
  if (elements.fileTreeRoot?.contains?.(event.relatedTarget)) return;
  elements.fileTreeRoot?.classList.remove("drag-root-drop", "drop-blocked");
}

async function handleFileTreeRootDrop(event) {
  const delegatedTarget = fileTreeDropTargetFromEvent(event);
  if (delegatedTarget) {
    await dropFileTreeEntry(event, delegatedTarget.entry);
    return;
  }
  const source = fileTreeDragSourceFromEvent(event);
  if (!source || !fileTreeCanDropOnDirectory(source.path, FILE_TREE_ROOT_PATH, source.entry)) return;
  event.preventDefault();
  finishFileTreeDrag();
  await moveFileTreeEntryToDestination(source.entry || { path: source.path, type: source.type }, FILE_TREE_ROOT_PATH, { viaDragDrop: true });
}

function clearFileTreeEntryCache(filePath = "") {
  const normalized = normalizeFileTreePath(filePath);
  if (!normalized) {
    fileTreeState.entriesByPath.clear();
    fileTreeState.expanded.clear();
    fileTreeState.loading.clear();
    return;
  }
  for (const key of [...fileTreeState.entriesByPath.keys()]) {
    if (key === normalized || key.startsWith(`${normalized}/`)) fileTreeState.entriesByPath.delete(key);
  }
  for (const key of [...fileTreeState.expanded]) {
    if (key === normalized || key.startsWith(`${normalized}/`)) fileTreeState.expanded.delete(key);
  }
  for (const key of [...fileTreeState.loading]) {
    if (key === normalized || key.startsWith(`${normalized}/`)) fileTreeState.loading.delete(key);
  }
}

async function refreshFileTreeAfterOperation(paths = []) {
  if (fileTreeSearchQueryText()) {
    await runFileTreeSearch();
    return;
  }
  const uniquePaths = [...new Set(paths.map((item) => normalizeFileTreePath(item)))];
  if (!uniquePaths.length) {
    renderFileTree();
    return;
  }
  for (const path of uniquePaths) await loadFileTreeDirectory(path, { force: true });
  renderFileTree();
}

function updateActiveFileViewerAfterMove(sourcePath = "", destinationPath = "") {
  if (!activeFileViewer) return;
  const currentPath = normalizeFileTreePath(activeFileViewer.path || "");
  const nextPath = remapFileTreePathAfterMove(currentPath, sourcePath, destinationPath);
  if (!nextPath || nextPath === currentPath) return;
  const language = fileLanguageForPath(nextPath);
  activeFileViewer = {
    ...activeFileViewer,
    path: nextPath,
    name: fileDisplayName(nextPath),
    extension: fileExtensionForPath(nextPath),
    language,
    mode: activeFileViewer.mode === "preview" && language === "markdown" ? "preview" : "source",
    // The open-time diff snapshot belongs to the previous path.
    gitChanges: null,
  };
  if (fileViewerSelection) fileViewerSelection = { ...fileViewerSelection, path: nextPath, fileName: activeFileViewer.name };
  cacheActiveFileViewerForTab();
  updateFileViewerUi();
}

function closeActiveFileViewerIfDeleted(deletedPath = "") {
  if (!activeFileViewer || !filePathWithinOrEqual(activeFileViewer.path, deletedPath)) return false;
  closeFileViewer();
  return true;
}

async function deleteFileTreeEntry(entry = fileContextMenuState?.entry) {
  if (!entry) return;
  const sourcePath = normalizeFileTreePath(entry.path || "");
  if (!sourcePath) {
    addEvent("Workspace root cannot be deleted from the Files panel.", "warn");
    return;
  }
  const typeLabel = fileOperationTypeLabel(entry);
  const dirtyWarning = activeFileViewer?.dirty && filePathWithinOrEqual(activeFileViewer.path, sourcePath)
    ? "\n\nThe currently open file has unsaved edits that will be discarded from the viewer."
    : "";
  const recursiveWarning = typeLabel === "directory" ? "\n\nThis permanently deletes the directory and all of its contents." : "";
  if (!(await appConfirm({
    title: `Delete ${typeLabel}?`,
    summary: `${sourcePath}${recursiveWarning}${dirtyWarning}`,
    affected: typeLabel === "directory" ? "The directory and all files beneath it" : sourcePath,
    undoable: false,
    confirmLabel: `Delete ${typeLabel}`,
  }))) return;
  const tabContext = activeTabContext();
  setFileTreeStatus(`Deleting ${sourcePath}…`);
  try {
    const response = await api("/api/files", { method: "DELETE", body: { path: sourcePath, confirmed: true }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    const data = response.data || {};
    closeActiveFileViewerIfDeleted(sourcePath);
    clearFileTreeEntryCache(sourcePath);
    fileTreeState.selectedPath = "";
    await refreshFileTreeAfterOperation([data.parentPath ?? fileParentPath(sourcePath)]);
    setFileTreeStatus(`Deleted ${data.path || sourcePath}.`, "success");
    addEvent(`deleted ${data.path || sourcePath}`, "warn");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      setFileTreeStatus(error.message || String(error), "error");
      addEvent(`file delete failed: ${error.message || String(error)}`, "error");
    }
  }
}

async function moveFileTreeEntryToDestination(entry = {}, destinationPath = "", { viaDragDrop = false, confirmMove = false, offerMoveUndo = true, tabContext = activeTabContext() } = {}) {
  const sourcePath = normalizeFileTreePath(entry.path || "");
  const normalizedDestination = normalizeFileTreePath(destinationPath);
  if (!sourcePath) {
    addEvent("Workspace root cannot be moved from the Files panel.", "warn");
    return false;
  }
  if (!normalizedDestination && normalizedDestination !== FILE_TREE_ROOT_PATH) {
    addEvent("Destination path is required.", "warn");
    return false;
  }
  const typeLabel = fileOperationTypeLabel(entry);
  if (confirmMove && !(await appConfirmText(`Move ${typeLabel}?\n\nFrom: ${sourcePath}\nTo: ${normalizedDestination || "."}\n\nExisting destination paths are refused.`, { affected: sourcePath, undoable: true, confirmLabel: `Move ${typeLabel}` }))) return false;
  const isDirectory = fileTreeEntryIsDirectory(entry);
  const restoreSourceExpanded = isDirectory && fileTreeState.expanded.has(sourcePath) && !fileTreeSearchQueryText();
  const expandDestinationDirectory = viaDragDrop && !fileTreeSearchQueryText();
  setFileTreeStatus(`Moving ${sourcePath}…`);
  try {
    const response = await api("/api/files/move", { method: "POST", body: { path: sourcePath, toPath: normalizedDestination || ".", confirmed: true }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return true;
    const data = response.data || {};
    const nextPath = normalizeFileTreePath(data.destination || normalizedDestination);
    const sourceParent = data.parentPath ?? fileParentPath(sourcePath);
    const destinationParent = data.destinationParentPath ?? fileParentPath(nextPath);
    clearFileTreeEntryCache(sourcePath);
    clearFileTreeEntryCache(nextPath);
    if (restoreSourceExpanded && nextPath) fileTreeState.expanded.add(nextPath);
    if (expandDestinationDirectory) fileTreeState.expanded.add(normalizedDestination);
    fileTreeState.selectedPath = nextPath;
    updateActiveFileViewerAfterMove(sourcePath, nextPath);
    await refreshFileTreeAfterOperation([sourceParent, destinationParent]);
    if (restoreSourceExpanded && nextPath) await loadFileTreeDirectory(nextPath, { force: true });
    if (expandDestinationDirectory) await loadFileTreeDirectory(normalizedDestination, { force: true });
    renderFileTree();
    setFileTreeStatus(`Moved ${sourcePath} to ${nextPath}.`, "success");
    addEvent(`${viaDragDrop ? "drag-moved" : "moved"} ${sourcePath} to ${nextPath}`, "info");
    if (offerMoveUndo && nextPath && nextPath !== sourcePath) {
      offerUndo({
        message: `Moved ${sourcePath} to ${nextPath}.`,
        undo: async () => {
          const restored = await moveFileTreeEntryToDestination(
            { ...entry, path: nextPath },
            sourcePath,
            { offerMoveUndo: false, tabContext },
          );
          if (!restored) throw new Error(`Could not move ${nextPath} back to ${sourcePath}.`);
        },
        successMessage: `Moved ${nextPath} back to ${sourcePath}.`,
      });
    }
    return true;
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      setFileTreeStatus(error.message || String(error), "error");
      addEvent(`file move failed: ${error.message || String(error)}`, "error");
    }
    return false;
  }
}

// "New file… / New folder…" for the Files panel. `entry` is the folder (or a file, whose parent
// folder is used) the action was invoked on; the workspace root when invoked from the toolbar.
async function createFileTreeEntry(entry = null, kind = "file") {
  const entryPath = normalizeFileTreePath(entry?.path || "");
  const parentPath = !entryPath ? "" : entry?.type === "directory" ? entryPath : entryPath.split("/").slice(0, -1).join("/");
  const label = kind === "directory" ? "folder" : "file";
  const name = await appPromptText({
    title: `New ${label}`,
    summary: `Created inside ${parentPath || "the workspace root"}. Use "/" to create it deeper (existing folders only).`,
    placeholder: kind === "directory" ? "folder-name" : "notes.md",
    confirmLabel: "Create",
    validate: (value) => {
      const text = String(value || "").trim();
      if (!text) return "A name is required.";
      if (text === "." || text === ".." || text.includes("\0")) return "That name is not allowed.";
      if (text.startsWith("/") || text.startsWith("..")) return "Use a path relative to this folder.";
      return "";
    },
  });
  if (name === null) return;
  const relative = normalizeFileTreePath([parentPath, String(name).trim()].filter(Boolean).join("/"));
  const tabContext = activeTabContext();
  const response = await api("/api/files/create", { method: "POST", body: { path: relative, type: kind }, tabId: tabContext.tabId });
  if (!isCurrentTabContext(tabContext)) return;
  const created = response.data || {};
  addEvent(`Created ${label} ${created.path || relative}.`, "success");
  if (parentPath) fileTreeState.expanded.add(parentPath);
  await refreshFileTreeLive(tabContext).catch(() => {});
  if (kind === "file") await openFileInViewer(created.path || relative);
}

async function moveFileTreeEntry(entry = fileContextMenuState?.entry) {
  if (!entry) return;
  const sourcePath = normalizeFileTreePath(entry.path || "");
  if (!sourcePath) {
    addEvent("Workspace root cannot be moved from the Files panel.", "warn");
    return;
  }
  const typeLabel = fileOperationTypeLabel(entry);
  const baseName = sourcePath.split("/").pop() || sourcePath;
  const nameStart = sourcePath.length - baseName.length;
  const dotIndex = baseName.lastIndexOf(".");
  const destinationInput = await appPromptText({
    title: `Move or rename ${typeLabel}`,
    summary: `${sourcePath} — enter a new name or a destination path inside the workspace. An existing folder receives the ${typeLabel} as a child.`,
    defaultValue: sourcePath,
    confirmLabel: "Move",
    // Pre-select the file name (without extension) so a plain rename is one keystroke away.
    selectRange: [nameStart, entry.type === "directory" || dotIndex <= 0 ? sourcePath.length : nameStart + dotIndex],
    validate: (value) => (String(value || "").trim() ? "" : "Destination path is required."),
  });
  if (destinationInput === null) return;
  const destinationPath = String(destinationInput || "").trim();
  if (!destinationPath) {
    addEvent("Destination path is required.", "warn");
    return;
  }
  await moveFileTreeEntryToDestination(entry, destinationPath, { confirmMove: true });
}

// --- Durable UI layout settings -------------------------------------------
// Browser storage stays the immediate, offline-capable cache while the durable
// per-user layout lives in the WebUI settings file behind
// GET/PUT /api/interface-preferences. Local writes always apply first; server
// reconciliation is non-blocking, coalesced, and revision guarded.
const UI_LAYOUT_SCHEMA_VERSION = 3;
const UI_LAYOUT_ENDPOINT = "/api/interface-preferences";
const UI_LAYOUT_SAVE_DEBOUNCE_MS = 250;
const UI_LAYOUT_MAX_CONFLICT_RETRIES = 1;
const UI_LAYOUT_FIELDS = ["sidePanel", "composerActions", "controlVisibility", "footerScopedModelOrder", "terminalTabs", "fileViewerWidth"];
const UI_LAYOUT_SIDE_PANEL_FIELDS = ["placement", "sectionLayout", "collapsedSectionIds", "hiddenSectionIds", "collapsedPanels", "panelWidths"];
const REMOVED_SIDE_PANEL_SECTION_HEIGHT_STORAGE_KEY = "pi-webui-side-panel-section-heights-v1";
const UI_LAYOUT_COMPOSER_FIELDS = ["order", "grid"];
const UI_LAYOUT_TERMINAL_FIELDS = ["layout", "customGroups", "sidebarWidth"];
const UI_LAYOUT_PENDING_STORAGE_PREFIX = "pi-webui-ui-layout-pending-v4:";
const UI_LAYOUT_LEGACY_PENDING_STORAGE_PREFIX = "pi-webui-ui-layout-pending-v3:";
const UI_LAYOUT_PENDING_WRITER_ID = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
let durableLayoutPendingMutationSerial = 0;
const UI_LAYOUT_ID_MAX_LENGTH = 256;
const UI_LAYOUT_TITLE_MAX_LENGTH = 160;
const UI_LAYOUT_LIST_MAX_ITEMS = 128;
const UI_LAYOUT_GROUP_MAX_COUNT = 32;
const UI_LAYOUT_GRID_MAX_COLUMNS = 24;
const UI_LAYOUT_GRID_MAX_SLOTS = 4096;
const UI_LAYOUT_FILE_VIEWER_WIDTH_MAX_PX = 4096;
const UI_LAYOUT_UNSAFE_KEYS = new Set(["__proto__", "constructor", "prototype"]);
const UI_LAYOUT_CONTROL_CHARACTERS = /[\u0000-\u001f\u007f]/;

let durableLayoutRevision = null;
const durableLayoutGenerations = new Map();
const durableLayoutDirtyFields = new Map();
let durableLayoutSaveTimer = null;
let durableLayoutSaveInFlight = false;
let durableLayoutConflictAttempts = 0;
let durableLayoutWarned = false;
let durableLayoutReadEpoch = 0;
let durableLayoutAppliedReadEpoch = 0;
let durableLayoutWriteFenceReadEpoch = 0;

function readDurableLayoutCache(key) {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function writeDurableLayoutCache(key, value) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // Browser storage is only the local cache for the durable layout settings.
  }
}

function durableLayoutIdList(value) {
  if (!Array.isArray(value)) return null;
  const ids = [];
  const seen = new Set();
  for (const item of value) {
    if (typeof item !== "string") continue;
    const id = item.trim();
    if (!id || id.length > UI_LAYOUT_ID_MAX_LENGTH || UI_LAYOUT_CONTROL_CHARACTERS.test(id) || seen.has(id)) continue;
    seen.add(id);
    ids.push(id);
    if (ids.length >= UI_LAYOUT_LIST_MAX_ITEMS) break;
  }
  return ids;
}

function durableLayoutStoredIdList(key) {
  const raw = readDurableLayoutCache(key);
  if (raw === null) return null;
  try {
    return durableLayoutIdList(JSON.parse(raw));
  } catch {
    return null;
  }
}

function normalizeControlDeckPlacement(value) {
  return ["right", "left", "both"].includes(value) ? value : CONTROL_DECK_DEFAULT_PLACEMENT;
}

function defaultControlDeckLayout() {
  return {
    placement: CONTROL_DECK_DEFAULT_PLACEMENT,
    sectionLayout: { order: null, leftSectionIds: [] },
    collapsedSectionIds: null,
    hiddenSectionIds: null,
    collapsedPanels: { left: false, right: false },
    panelWidths: { left: SIDE_PANEL_WIDTH_DEFAULT_PX, right: SIDE_PANEL_WIDTH_DEFAULT_PX },
  };
}

function readStoredControlDeckLayout() {
  const fallback = defaultControlDeckLayout();
  try {
    const raw = localStorage.getItem(CONTROL_DECK_LAYOUT_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      return {
        ...fallback,
        ...parsed,
        placement: normalizeControlDeckPlacement(parsed?.placement),
        sectionLayout: parsed?.sectionLayout || fallback.sectionLayout,
        collapsedPanels: { ...fallback.collapsedPanels, ...(parsed?.collapsedPanels || {}) },
        panelWidths: { ...fallback.panelWidths, ...(parsed?.panelWidths || {}) },
      };
    }
  } catch { /* fall through to legacy cache */ }
  const order = durableLayoutStoredIdList(SIDE_PANEL_SECTION_ORDER_STORAGE_KEY);
  const collapsed = readStoredSidePanelCollapsed();
  const width = readStoredSidePanelWidth();
  const migrated = { ...fallback, sectionLayout: { order, leftSectionIds: [] } };
  if (typeof collapsed === "boolean") migrated.collapsedPanels.right = collapsed;
  if (width) migrated.panelWidths.right = width;
  return migrated;
}

let controlDeckLayout = readStoredControlDeckLayout();

function normalizedControlDeckLayout(next = {}) {
  return {
    ...defaultControlDeckLayout(),
    ...next,
    placement: normalizeControlDeckPlacement(next?.placement),
    sectionLayout: next?.sectionLayout || { order: null, leftSectionIds: [] },
    collapsedPanels: { left: false, right: false, ...(next?.collapsedPanels || {}) },
    panelWidths: { left: SIDE_PANEL_WIDTH_DEFAULT_PX, right: SIDE_PANEL_WIDTH_DEFAULT_PX, ...(next?.panelWidths || {}) },
  };
}

function cacheControlDeckLayout(next = controlDeckLayout, subfield = null) {
  const incoming = normalizedControlDeckLayout(next);
  const current = readStoredControlDeckLayout();
  const cached = subfield ? normalizedControlDeckLayout({ ...current, [subfield]: incoming[subfield] }) : incoming;
  writeDurableLayoutCache(CONTROL_DECK_LAYOUT_STORAGE_KEY, JSON.stringify(cached));
  controlDeckLayout = subfield ? normalizedControlDeckLayout({ ...incoming, [subfield]: cached[subfield] }) : cached;
  return controlDeckLayout;
}

function collectDurableSidePanelLayout() {
  const records = typeof controlDeckSectionRecords === "function" ? controlDeckSectionRecords() : [];
  const order = controlDeckLayout.sectionLayout?.order || records.map(({ id }) => id);
  const left = controlDeckLayout.sectionLayout?.leftSectionIds || [];
  return {
    placement: normalizeControlDeckPlacement(controlDeckLayout.placement),
    sectionLayout: { order, leftSectionIds: left.filter((id) => order.includes(id)) },
    collapsedSectionIds: durableLayoutStoredIdList(SIDE_PANEL_SECTION_STORAGE_KEY),
    hiddenSectionIds: durableLayoutStoredIdList(SIDE_PANEL_SECTION_VISIBILITY_STORAGE_KEY),
    collapsedPanels: controlDeckLayout.collapsedPanels,
    panelWidths: controlDeckLayout.panelWidths,
  };
}

function collectDurableComposerActionsLayout() {
  const stored = readStoredComposerActionLayout();
  let grid = null;
  if (stored && Number.isInteger(stored.columns) && stored.columns >= 1 && stored.columns <= UI_LAYOUT_GRID_MAX_COLUMNS) {
    const positions = {};
    const usedSlots = new Set();
    let count = 0;
    for (const [rawId, slot] of stored.positions) {
      const id = typeof rawId === "string" ? rawId.trim() : "";
      if (!id || id.length > UI_LAYOUT_ID_MAX_LENGTH || UI_LAYOUT_CONTROL_CHARACTERS.test(id) || UI_LAYOUT_UNSAFE_KEYS.has(id)) continue;
      if (!Number.isInteger(slot) || slot < 0 || slot >= UI_LAYOUT_GRID_MAX_SLOTS || usedSlots.has(slot)) continue;
      usedSlots.add(slot);
      positions[id] = slot;
      count += 1;
      if (count >= UI_LAYOUT_LIST_MAX_ITEMS) break;
    }
    grid = { version: 2, columns: stored.columns, positions };
  }
  // Composer order and sparse grid always travel together as one logical update.
  return { order: durableLayoutStoredIdList(COMPOSER_ACTION_ORDER_STORAGE_KEY), grid };
}

function collectDurableTerminalTabsLayout() {
  const rawLayout = readDurableLayoutCache(TERMINAL_TABS_LAYOUT_STORAGE_KEY);
  const rawGroups = readDurableLayoutCache(TERMINAL_CUSTOM_GROUPS_STORAGE_KEY);
  let customGroups = null;
  if (rawGroups !== null) {
    let parsed = null;
    try {
      parsed = JSON.parse(rawGroups);
    } catch {
      parsed = null;
    }
    const records = Array.isArray(parsed?.groups) ? parsed.groups : Array.isArray(parsed) ? parsed : [];
    const groups = [];
    const groupIds = new Set();
    const claimedTabIds = new Set();
    for (const record of records) {
      const id = String(record?.id || "").trim();
      if (!id || id.length > UI_LAYOUT_ID_MAX_LENGTH || UI_LAYOUT_CONTROL_CHARACTERS.test(id) || groupIds.has(id)) continue;
      const title = normalizeTerminalCustomGroupTitle(record?.title).slice(0, UI_LAYOUT_TITLE_MAX_LENGTH).trim();
      const tabIds = (durableLayoutIdList(normalizeTerminalCustomGroupTabIds(record?.tabIds)) || []).filter((tabId) => {
        if (claimedTabIds.has(tabId)) return false;
        claimedTabIds.add(tabId);
        return true;
      });
      if (!title || tabIds.length < 2) continue;
      groupIds.add(id);
      groups.push({ id, title, tabIds });
      if (groups.length >= UI_LAYOUT_GROUP_MAX_COUNT) break;
    }
    customGroups = { version: 1, groups };
  }
  return {
    layout: TERMINAL_TABS_LAYOUTS.has(rawLayout) ? rawLayout : null,
    customGroups,
    sidebarWidth: readStoredTerminalTabsSidebarWidth(),
  };
}

// --- Control visibility registry -------------------------------------------
// Stable preference keys are independent of DOM ids. Each entry maps to a
// static selector so user hiding composes with runtime capability gating via
// the dedicated .webui-user-hidden class (never touches the hidden attribute).
// Send is intentionally unregistered: it can never be hidden by preference.
const CONTROL_VISIBILITY_HIDDEN_IDS_STORAGE_KEY = "pi-webui-control-visibility-hidden-ids-v1";
const CONTROL_VISIBILITY_GROUP_LABELS = [
  ["workspace", "Workspace toolbar"],
  ["control-deck", "Control Deck"],
  ["composer", "Composer actions"],
  ["inputframe", "Input-frame controls"],
  ["tags", "Input-frame tags"],
];
const CONTROL_VISIBILITY_CATALOG = [
  { id: "workspace.save", group: "workspace", label: "Save workspace", selector: "#workspaceSaveButton" },
  { id: "workspace.command-palette", group: "workspace", label: "Command palette", selector: "#commandPaletteButton" },
  { id: "workspace.overview", group: "workspace", label: "Show workspace overview", selector: "#workspaceDashboardToggleButton" },
  { id: "workspace.close-all-tabs", group: "workspace", label: "Close all tabs", selector: "#closeAllTabsButton" },
  { id: "control-deck.sponsor", group: "control-deck", label: "Sponsor", selector: ".sponsor-link" },
  { id: "control-deck.open-issue", group: "control-deck", label: "Open Issue", selector: "#openIssueButton" },
  { id: "composer.new", group: "composer", label: "New", selector: '[data-composer-action-id="new"]' },
  { id: "composer.compact", group: "composer", label: "Compact", selector: '[data-composer-action-id="compact"]' },
  { id: "composer.guided-git", group: "composer", label: "Guided Git workflow", selector: '[data-composer-action-id="git"]' },
  { id: "composer.publish", group: "composer", label: "AUR/npm release dropdown", selector: '[data-composer-action-id="publish"]' },
  { id: "composer.tools-skills", group: "composer", label: "Tools/skills setup dropdown", selector: '[data-composer-action-id="native-command"]' },
  { id: "composer.common-options", group: "composer", label: "Common options", selector: '[data-composer-action-id="options"]' },
  { id: "composer.app-runner", group: "composer", label: "App runner", selector: '[data-composer-action-id="app-runner"]' },
  { id: "composer.steer", group: "composer", label: "Steer", selector: '[data-composer-action-id="steer"]' },
  { id: "composer.follow-up", group: "composer", label: "Follow-up", selector: '[data-composer-action-id="follow-up"]' },
  { id: "composer.btw", group: "composer", label: "/btw side question", selector: '[data-composer-action-id="btw"]' },
  { id: "input.workflow", group: "inputframe", label: "Workflow controls", selector: "#workflowModeControls" },
  { id: "input.attach-files", group: "inputframe", label: "Attach files", selector: "#attachButton" },
  { id: "tag.prompt-behavior", group: "tags", label: "Follow-up/Steer busy-prompt behavior tag", selector: "#busyPromptBehaviorTag" },
  { id: "tag.skills", group: "tags", label: "Session skill tags", selector: "#sessionSkillTags" },
  { id: "tag.agent-conversations", group: "tags", label: "Intercom agent-conversation tags", selector: "#intercomConversationTags" },
  { id: "tag.feature-category", group: "tags", label: "Feature-category tag", selector: "#featureCategoryTag" },
  { id: "tag.voice-mode", group: "tags", label: "Natural-conversation/voice tag", selector: "#conversationModeChip" },
  { id: "tag.workflow-mode", group: "tags", label: "Workflow-mode tag", selector: "#workflowModeChip" },
];
const CONTROL_VISIBILITY_REGISTRY = new Map(CONTROL_VISIBILITY_CATALOG.map((entry) => [entry.id, entry]));

function readStoredControlVisibilityHiddenIds() {
  const raw = readDurableLayoutCache(CONTROL_VISIBILITY_HIDDEN_IDS_STORAGE_KEY);
  if (raw === null) return null;
  try {
    return durableLayoutIdList(JSON.parse(raw));
  } catch {
    return null;
  }
}

function userControlHiddenIds() {
  const dirtyHiddenIds = durableLayoutDirtyFields.get("controlVisibility")?.value?.hiddenIds;
  if (dirtyHiddenIds === null || Array.isArray(dirtyHiddenIds)) return dirtyHiddenIds || [];
  return readStoredControlVisibilityHiddenIds() || [];
}

// Only the preference class is managed here. A runtime `hidden` attribute
// owned by capability/state gating always remains authoritative.
function applyControlVisibility(hiddenIdsOverride) {
  // An explicit override lets this tab keep showing its own pending mutation
  // while another same-origin tab's cache value is still unacknowledged.
  const hiddenSet = new Set(hiddenIdsOverride === undefined ? userControlHiddenIds() : hiddenIdsOverride || []);
  let composerChanged = false;
  for (const entry of CONTROL_VISIBILITY_CATALOG) {
    const shouldHide = hiddenSet.has(entry.id);
    for (const element of document.querySelectorAll(entry.selector)) {
      const wasHidden = element.classList.contains("webui-user-hidden");
      element.classList.toggle("webui-user-hidden", shouldHide);
      // Reflow on a real state change in either direction: un-hiding must
      // restore saved slots, and unchanged reapplies (storage events, snapshot
      // adoption) must not schedule spurious repacks.
      if (wasHidden !== shouldHide && entry.group === "composer") composerChanged = true;
    }
  }
  // Hiding composer actions leaves grid holes; repack/restore the saved layout.
  if (composerChanged) scheduleComposerActionSlotLayoutRestore();
  refreshControlVisibilitySetupDialog();
}

function persistControlVisibilityHiddenIds(hiddenIds) {
  writeDurableLayoutCache(CONTROL_VISIBILITY_HIDDEN_IDS_STORAGE_KEY, JSON.stringify(hiddenIds ?? null));
  markDurableUiLayoutDirty("controlVisibility");
  applyControlVisibility(hiddenIds);
}

function setControlVisibilityHidden(id, hidden) {
  if (!CONTROL_VISIBILITY_REGISTRY.has(id)) return;
  const current = userControlHiddenIds();
  const next = hidden ? [...new Set([...current, id])] : current.filter((entry) => entry !== id);
  persistControlVisibilityHiddenIds(next);
}

function showAllControls() {
  persistControlVisibilityHiddenIds([]);
}

function resetControlVisibilityDefaults() {
  persistControlVisibilityHiddenIds(null);
}

let visibilityContextMenuState = null;
let controlVisibilitySetupFocusReturn = null;

function setControlVisibilitySetupStatus(message = "") {
  if (elements.controlVisibilitySetupStatus) elements.controlVisibilitySetupStatus.textContent = message;
}

function renderControlVisibilitySetupDialog() {
  const body = elements.controlVisibilitySetupBody;
  if (!body) return;
  const groups = CONTROL_VISIBILITY_GROUP_LABELS.map(([groupId, groupLabel], groupIndex) => {
    const fieldset = make("fieldset", "control-visibility-setup-group");
    fieldset.append(make("legend", "control-visibility-setup-group-label", groupLabel));
    const grid = make("div", "control-visibility-setup-grid");
    for (const [entryIndex, entry] of CONTROL_VISIBILITY_CATALOG.filter((item) => item.group === groupId).entries()) {
      const label = make("label", "control-visibility-setup-toggle");
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.id = `controlVisibilitySetupToggle-${groupIndex}-${entryIndex}`;
      checkbox.dataset.visibilitySetupId = entry.id;
      checkbox.setAttribute("aria-label", `Show ${entry.label}`);
      label.htmlFor = checkbox.id;
      label.append(checkbox, make("span", "control-visibility-setup-toggle-label", entry.label));
      grid.append(label);
    }
    fieldset.append(grid);
    return fieldset;
  });
  body.replaceChildren(...groups);
}

function refreshControlVisibilitySetupDialog() {
  const dialog = elements.controlVisibilitySetupDialog;
  const body = elements.controlVisibilitySetupBody;
  if (!dialog?.open || !body) return;
  const hiddenSet = new Set(userControlHiddenIds());
  for (const checkbox of body.querySelectorAll("[data-visibility-setup-id]")) {
    checkbox.checked = !hiddenSet.has(checkbox.dataset.visibilitySetupId);
  }
  const visibleCount = CONTROL_VISIBILITY_CATALOG.filter((entry) => !hiddenSet.has(entry.id)).length;
  setControlVisibilitySetupStatus(`${visibleCount} of ${CONTROL_VISIBILITY_CATALOG.length} optional controls shown by preference.`);
}

function openControlVisibilitySetupDialog(trigger = null) {
  const dialog = elements.controlVisibilitySetupDialog;
  if (!dialog) return;
  controlVisibilitySetupFocusReturn = trigger instanceof HTMLElement ? trigger : elements.promptInput;
  if (!elements.controlVisibilitySetupBody?.childElementCount) renderControlVisibilitySetupDialog();
  if (!dialog.open) dialog.showModal();
  refreshControlVisibilitySetupDialog();
  queueMicrotask(() => elements.controlVisibilitySetupBody?.querySelector("input")?.focus({ preventScroll: true }));
}

function restoreControlVisibilitySetupFocus() {
  const trigger = controlVisibilitySetupFocusReturn;
  controlVisibilitySetupFocusReturn = null;
  const triggerSurvives = trigger
    && trigger.isConnected
    && !trigger.closest?.("[hidden], .webui-user-hidden")
    && typeof trigger.focus === "function";
  requestAnimationFrame(() => {
    if (triggerSurvives) trigger.focus({ preventScroll: true });
    else elements.promptInput?.focus({ preventScroll: true });
  });
}


function closeVisibilityContextMenu({ returnFocus = true } = {}) {
  const trigger = visibilityContextMenuState?.trigger;
  visibilityContextMenuState = null;
  if (elements.visibilityContextMenu) elements.visibilityContextMenu.hidden = true;
  if (!returnFocus) return;
  const triggerSurvives = trigger
    && trigger.isConnected
    && !trigger.hidden
    && !trigger.classList?.contains("webui-user-hidden")
    && typeof trigger.focus === "function";
  if (triggerSurvives) trigger.focus({ preventScroll: true });
  else elements.promptInput?.focus({ preventScroll: true });
}

function positionControlVisibilityMenu(clientX, clientY) {
  const menu = elements.visibilityContextMenu;
  menu.hidden = false;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(clientX, Math.max(8, window.innerWidth - rect.width - 8));
  const top = Math.min(clientY, Math.max(8, window.innerHeight - rect.height - 8));
  menu.style.left = `${Math.max(8, left)}px`;
  menu.style.top = `${Math.max(8, top)}px`;
}

function controlVisibilityMenuLabel(text) {
  const label = make("div", "control-visibility-menu-label", text);
  label.setAttribute("role", "presentation");
  label.setAttribute("aria-hidden", "true");
  return label;
}

function controlVisibilityMenuAction(action, text) {
  const button = make("button", "control-visibility-menu-item control-visibility-menu-action", text);
  button.type = "button";
  button.setAttribute("role", "menuitem");
  button.dataset.visibilityMenuAction = action;
  return button;
}

function prepareControlVisibilityMenu(trigger, entryId = null) {
  if (!elements.visibilityContextMenu) return null;
  closeFileContextMenu({ returnFocus: false });
  closeGitPanelContextMenu({ returnFocus: false });
  closeSidePanelContextMenu({ returnFocus: false });
  closeGitFooterContextMenu({ returnFocus: false });
  closeEventTreeContextMenu({ returnFocus: false });
  closeVisibilityContextMenu({ returnFocus: false });
  // Region hosts are plain non-focusable containers; storing one as the
  // trigger would let Escape focus fall through to <body>. Fall back to the
  // prompt unless the trigger can actually receive keyboard focus.
  const focusableTrigger = trigger
    && typeof trigger.focus === "function"
    && trigger.matches("button, a, input, select, textarea, [tabindex]")
    ? trigger
    : elements.promptInput;
  visibilityContextMenuState = {
    trigger: focusableTrigger,
    entryId,
    openedAt: performance.now(),
  };
  return elements.visibilityContextMenu;
}

// Right-clicking a visible registered control offers Hide <label> plus the
// recovery actions; empty marked regions open the grouped full catalog.
function showControlVisibilityDirectMenu(entry, focusTrigger, { clientX, clientY }) {
  const menu = prepareControlVisibilityMenu(focusTrigger, entry.id);
  if (!menu) return;
  const items = [
    controlVisibilityMenuLabel("Hide or restore controls"),
    controlVisibilityMenuAction("hide", `Hide ${entry.label}`),
    controlVisibilityMenuAction("open-setup", "Open setup"),
    controlVisibilityMenuAction("show-all", "Show all"),
    controlVisibilityMenuAction("reset-defaults", "Reset defaults"),
  ];
  menu.replaceChildren(...items);
  positionControlVisibilityMenu(clientX, clientY);
  menu.querySelector('[role="menuitem"]')?.focus({ preventScroll: true });
}

function showControlVisibilityRegionMenu(trigger, { clientX, clientY }) {
  const menu = prepareControlVisibilityMenu(trigger, null);
  if (!menu) return;
  const hiddenSet = new Set(userControlHiddenIds());
  const children = [controlVisibilityMenuLabel("Choose visible controls")];
  for (const [groupId, groupLabel] of CONTROL_VISIBILITY_GROUP_LABELS) {
    children.push(controlVisibilityMenuLabel(groupLabel));
    for (const entry of CONTROL_VISIBILITY_CATALOG.filter((item) => item.group === groupId)) {
      const button = make("button", "control-visibility-menu-item side-panel-context-menu-item", entry.label);
      button.type = "button";
      button.setAttribute("role", "menuitemcheckbox");
      button.setAttribute("aria-checked", hiddenSet.has(entry.id) ? "false" : "true");
      button.dataset.visibilityMenuToggle = entry.id;
      children.push(button);
    }
  }
  children.push(controlVisibilityMenuAction("open-setup", "Open setup"));
  children.push(controlVisibilityMenuAction("show-all", "Show all"));
  children.push(controlVisibilityMenuAction("reset-defaults", "Reset defaults"));
  menu.replaceChildren(...children);
  positionControlVisibilityMenu(clientX, clientY);
  menu.querySelector('[role="menuitemcheckbox"]')?.focus({ preventScroll: true });
}

// Registered visibility targets always win; unrelated editable/input/link
// contexts and existing specialized menus keep their native behavior.
function handleControlVisibilityContextMenu(event) {
  const target = event.target;
  if (!(target instanceof Element)) return;
  if (target.closest?.(".file-context-menu, dialog, .composer-publish-menu-panel")) return;
  const direct = target.closest?.("[data-visibility-key]");
  const entry = direct ? CONTROL_VISIBILITY_REGISTRY.get(direct.dataset.visibilityKey) : null;
  if (entry) {
    event.preventDefault();
    event.stopPropagation();
    const focusTrigger = target.closest?.("button, a, input, select, textarea, [tabindex]");
    showControlVisibilityDirectMenu(entry, focusTrigger, { clientX: event.clientX, clientY: event.clientY });
    return;
  }
  if (target.closest?.("button, input, textarea, select, [contenteditable='true'], a")) return;
  const region = target.closest?.("[data-visibility-region]");
  if (!region) return;
  event.preventDefault();
  event.stopPropagation();
  showControlVisibilityRegionMenu(region, { clientX: event.clientX, clientY: event.clientY });
}

function handleControlVisibilityKeydown(event) {
  if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return;
  const target = event.target instanceof Element ? event.target : document.activeElement;
  if (!(target instanceof Element)) return;
  if (target.closest?.(".file-context-menu, dialog, .composer-publish-menu-panel")) return;
  const direct = target.closest?.("[data-visibility-key]");
  const entry = direct ? CONTROL_VISIBILITY_REGISTRY.get(direct.dataset.visibilityKey) : null;
  // Send is permanently visible and never toggleable, so from the keyboard it
  // doubles as the always-reachable anchor for the grouped recovery menu when
  // every optional control is hidden. Pointer right-click on Send stays native.
  const sendAnchor = entry ? null : target.closest?.("#sendButton");
  const anchor = direct || sendAnchor || target.closest?.("[data-visibility-region]");
  if (!anchor) return;
  if (!entry && !sendAnchor && target.closest?.("button, input, textarea, select, [contenteditable='true'], a")) return;
  const rect = anchor.getBoundingClientRect();
  const position = { clientX: rect.left + Math.min(rect.width, 24), clientY: rect.bottom };
  event.preventDefault();
  event.stopPropagation();
  if (entry) {
    const focusTrigger = target.closest?.("button, a, input, select, textarea, [tabindex]");
    showControlVisibilityDirectMenu(entry, focusTrigger, position);
  } else showControlVisibilityRegionMenu(anchor, position);
}

function initializeControlVisibility() {
  applyControlVisibility();
  document.addEventListener("contextmenu", handleControlVisibilityContextMenu, { capture: true });
  document.addEventListener("keydown", handleControlVisibilityKeydown, { capture: true });
  document.addEventListener("pointerdown", (event) => {
    if (!elements.visibilityContextMenu || elements.visibilityContextMenu.hidden) return;
    if (!event.target?.closest?.(".control-visibility-context-menu")) closeVisibilityContextMenu({ returnFocus: false });
  }, { passive: true });
  window.addEventListener("resize", () => closeVisibilityContextMenu({ returnFocus: false }), { passive: true });
  document.addEventListener("scroll", () => {
    // Pointer-driven context-menu invocation can finish an automatic
    // scroll-into-view after the menu opens. Ignore that trailing event while
    // still dismissing the menu for subsequent user scrolling.
    if (!visibilityContextMenuState || performance.now() - visibilityContextMenuState.openedAt < 100) return;
    closeVisibilityContextMenu({ returnFocus: false });
  }, { capture: true, passive: true });
}

function collectDurableFileViewerWidth() {
  const width = readStoredFileViewerWidth();
  if (!Number.isFinite(width)) return null;
  const rounded = Math.round(width);
  return rounded >= FILE_VIEWER_WIDTH_MIN_PX && rounded <= UI_LAYOUT_FILE_VIEWER_WIDTH_MAX_PX ? rounded : null;
}

function collectDurableUiLayoutField(field) {
  switch (field) {
    case "sidePanel":
      return collectDurableSidePanelLayout();
    case "composerActions":
      return collectDurableComposerActionsLayout();
    case "controlVisibility":
      return { hiddenIds: readStoredControlVisibilityHiddenIds() };
    case "footerScopedModelOrder":
      return durableLayoutStoredIdList(FOOTER_SCOPED_MODEL_ORDER_STORAGE_KEY);
    case "terminalTabs":
      return collectDurableTerminalTabsLayout();
    case "fileViewerWidth":
      return collectDurableFileViewerWidth();
    default:
      return null;
  }
}

function durableUiLayoutSubFields(field) {
  if (field === "sidePanel") return UI_LAYOUT_SIDE_PANEL_FIELDS;
  if (field === "composerActions") return UI_LAYOUT_COMPOSER_FIELDS;
  if (field === "terminalTabs") return UI_LAYOUT_TERMINAL_FIELDS;
  return null;
}

function durableUiLayoutValuePresent(value) {
  return value !== null && value !== undefined;
}

function durableUiLayoutSubfieldValuePresent(field, subfield, value) {
  if (!durableUiLayoutValuePresent(value)) return false;
  if (field === "sidePanel" && subfield === "sectionLayout") return Array.isArray(value?.order) && Array.isArray(value?.leftSectionIds);
  if (field === "sidePanel" && subfield === "collapsedPanels") return typeof value?.left === "boolean" || typeof value?.right === "boolean";
  if (field === "sidePanel" && subfield === "panelWidths") return Number.isFinite(value?.left) || Number.isFinite(value?.right);
  return true;
}

function durableUiLayoutMutationValue(field, subfield = null) {
  const value = collectDurableUiLayoutField(field);
  return subfield ? value?.[subfield] ?? null : value;
}

function durableUiLayoutEntryPatch(field, entry) {
  if (!entry?.subfields?.size) return entry?.value ?? null;
  return Object.fromEntries([...entry.subfields].map((subfield) => [subfield, entry.value?.[subfield] ?? null]));
}

function durableUiLayoutPendingMutationRecords() {
  const records = [];
  try {
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (!key?.startsWith(UI_LAYOUT_PENDING_STORAGE_PREFIX) && !key?.startsWith(UI_LAYOUT_LEGACY_PENDING_STORAGE_PREFIX)) continue;
      let value;
      try {
        value = JSON.parse(localStorage.getItem(key) || "null");
      } catch {
        continue;
      }
      if (!value || ![3, 4].includes(value.version) || !UI_LAYOUT_FIELDS.includes(value.field)) continue;
      const allowedSubfields = durableUiLayoutSubFields(value.field);
      let subfield = typeof value.subfield === "string" ? value.subfield : null;
      let mutationValue = value.value;
      // v3 journals written before schema v2 used the four legacy side-panel
      // identities below. Translate at read time and retain the old immutable
      // key until the corresponding v2 mutation is acknowledged.
      if (value.field === "sidePanel" && subfield === "sectionOrder") {
        subfield = "sectionLayout";
        mutationValue = { order: durableLayoutIdList(value.value), leftSectionIds: [] };
      } else if (value.field === "sidePanel" && subfield === "collapsedSectionIds") {
        mutationValue = durableLayoutIdList(value.value);
      } else if (value.field === "sidePanel" && subfield === "hiddenSectionIds") {
        mutationValue = durableLayoutIdList(value.value);
      } else if (value.field === "sidePanel" && subfield === "collapsed") {
        subfield = "collapsedPanels";
        mutationValue = { right: typeof value.value === "boolean" ? value.value : null };
      }
      if (subfield && !allowedSubfields?.includes(subfield)) continue;
      if (allowedSubfields && value.field !== "composerActions" && !subfield) continue;
      records.push({
        key,
        field: value.field,
        subfield,
        value: mutationValue,
        updatedAt: Number(value.updatedAt) || 0,
      });
    }
  } catch {
    return [];
  }
  return records;
}

function writeDurableUiLayoutPendingMutation(field, subfield, value) {
  try {
    durableLayoutPendingMutationSerial += 1;
    const key = `${UI_LAYOUT_PENDING_STORAGE_PREFIX}${UI_LAYOUT_PENDING_WRITER_ID}:${Date.now().toString(36)}:${durableLayoutPendingMutationSerial.toString(36)}`;
    localStorage.setItem(key, JSON.stringify({
      version: 4,
      field,
      subfield,
      value,
      updatedAt: Date.now(),
    }));
    return key;
  } catch {
    return null;
  }
}

function removeDurableUiLayoutPendingMutation(key) {
  if (!key) return;
  try {
    localStorage.removeItem(key);
  } catch {
    // A later startup can retry an immutable mutation record that remains.
  }
}

function clearRemovedSidePanelSectionHeightState() {
  try {
    localStorage.removeItem(REMOVED_SIDE_PANEL_SECTION_HEIGHT_STORAGE_KEY);
  } catch {
    // Removed layout state may remain when browser storage is unavailable.
  }
  for (const record of durableUiLayoutPendingMutationRecords()) {
    if (record.field === "sidePanel" && record.subfield === "sectionHeights") {
      removeDurableUiLayoutPendingMutation(record.key);
    }
  }
}

function clearAcknowledgedDurableUiLayoutPendingMutations(snapshot) {
  for (const entry of snapshot.values()) {
    if (entry.subfieldMutationIds?.size) {
      for (const mutationId of entry.subfieldMutationIds.values()) removeDurableUiLayoutPendingMutation(mutationId);
    } else {
      removeDurableUiLayoutPendingMutation(entry.mutationId);
    }
  }
}

function restoreDurableUiLayoutPendingJournal() {
  const records = durableUiLayoutPendingMutationRecords();
  const candidates = new Map();
  for (const record of records) {
    const path = record.subfield ? `${record.field}.${record.subfield}` : record.field;
    const previous = candidates.get(path);
    if (!previous || record.updatedAt > previous.updatedAt || (record.updatedAt === previous.updatedAt && record.key > previous.key)) {
      candidates.set(path, record);
    }
  }
  // Mutation records are immutable. Once a newer record exists for the same
  // path, older records are safely superseded and can never be rewritten.
  for (const record of records) {
    const path = record.subfield ? `${record.field}.${record.subfield}` : record.field;
    if (candidates.get(path)?.key !== record.key) removeDurableUiLayoutPendingMutation(record.key);
  }

  for (const field of UI_LAYOUT_FIELDS) {
    const allowedSubfields = durableUiLayoutSubFields(field);
    const fieldCandidates = allowedSubfields && field !== "composerActions"
      ? allowedSubfields.map((subfield) => candidates.get(`${field}.${subfield}`)).filter(Boolean)
      : [candidates.get(field)].filter(Boolean);
    if (!fieldCandidates.length) continue;
    const patch = allowedSubfields && field !== "composerActions"
      ? Object.fromEntries(fieldCandidates.map((candidate) => [candidate.subfield, candidate.value]))
      : fieldCandidates[0].value;
    applyDurableUiLayoutField(field, patch);
    const generation = durableUiLayoutGeneration(field) + 1;
    const subfields = allowedSubfields && field !== "composerActions"
      ? new Set(fieldCandidates.map((candidate) => candidate.subfield))
      : null;
    const subfieldGenerations = subfields
      ? new Map([...subfields].map((subfield) => [subfield, generation]))
      : null;
    const subfieldMutationIds = subfields
      ? new Map(fieldCandidates.map((candidate) => [candidate.subfield, candidate.key]))
      : null;
    durableLayoutGenerations.set(field, generation);
    const restoredValue = collectDurableUiLayoutField(field);
    if (subfields) {
      for (const candidate of fieldCandidates) restoredValue[candidate.subfield] = candidate.value;
    }
    durableLayoutDirtyFields.set(field, {
      generation,
      value: restoredValue,
      subfields,
      subfieldGenerations,
      subfieldMutationIds,
      mutationId: subfields ? null : fieldCandidates[0].key,
    });
  }
  if (durableLayoutDirtyFields.size) scheduleDurableUiLayoutSave();
}

function applyDurableSidePanelLayout(value) {
  if (!value) return;
  const adoptedSubfields = [];
  if (value.placement) {
    controlDeckLayout.placement = normalizeControlDeckPlacement(value.placement);
    adoptedSubfields.push("placement");
  }
  if (value.sectionLayout) {
    controlDeckLayout.sectionLayout = value.sectionLayout;
    if (Array.isArray(value.sectionLayout.order)) writeDurableLayoutCache(SIDE_PANEL_SECTION_ORDER_STORAGE_KEY, JSON.stringify(value.sectionLayout.order));
    adoptedSubfields.push("sectionLayout");
  }
  if (Array.isArray(value.hiddenSectionIds)) {
    writeDurableLayoutCache(SIDE_PANEL_SECTION_VISIBILITY_STORAGE_KEY, JSON.stringify(value.hiddenSectionIds));
    restoreSidePanelSectionVisibility();
  }
  if (Array.isArray(value.collapsedSectionIds)) {
    writeDurableLayoutCache(SIDE_PANEL_SECTION_STORAGE_KEY, JSON.stringify(value.collapsedSectionIds));
    restoreSidePanelSectionState();
  }
  if (value.collapsedPanels && typeof value.collapsedPanels === "object") {
    controlDeckLayout.collapsedPanels = { ...controlDeckLayout.collapsedPanels, ...value.collapsedPanels };
    adoptedSubfields.push("collapsedPanels");
  }
  if (value.panelWidths && typeof value.panelWidths === "object") {
    controlDeckLayout.panelWidths = { ...controlDeckLayout.panelWidths, ...value.panelWidths };
    adoptedSubfields.push("panelWidths");
  }
  for (const subfield of adoptedSubfields) cacheControlDeckLayout(controlDeckLayout, subfield);
  restoreSidePanelSectionOrder();
  reconcileControlDeckHosts();
  restoreSidePanelState();
}

function applyDurableComposerActionsLayout(value) {
  if (!value) return;
  if (Array.isArray(value.order)) {
    writeDurableLayoutCache(COMPOSER_ACTION_ORDER_STORAGE_KEY, JSON.stringify(value.order));
    restoreComposerActionOrder();
  }
  if (value.grid && value.grid.version === 2) {
    // Keep the saved geometry as the canonical layout. Restore projects its
    // horizontal positions into the current responsive grid without rewriting
    // the source slots, so resizing back restores the exact original cells.
    writeDurableLayoutCache(COMPOSER_ACTION_LAYOUT_STORAGE_KEY, JSON.stringify(value.grid));
    restoreComposerActionSlotLayout();
  }
}

function applyDurableControlVisibility(value) {
  if (!value || typeof value !== "object") return;
  writeDurableLayoutCache(CONTROL_VISIBILITY_HIDDEN_IDS_STORAGE_KEY, JSON.stringify(value.hiddenIds ?? null));
  applyControlVisibility();
}

function applyDurableFooterScopedModelOrder(value) {
  if (!Array.isArray(value)) return;
  writeDurableLayoutCache(FOOTER_SCOPED_MODEL_ORDER_STORAGE_KEY, JSON.stringify(value));
  footerScopedModels = orderedFooterScopedModels();
  renderFooter();
}

function applyDurableTerminalTabsLayout(value) {
  if (!value) return;
  if (TERMINAL_TABS_LAYOUTS.has(value.layout)) {
    writeDurableLayoutCache(TERMINAL_TABS_LAYOUT_STORAGE_KEY, value.layout);
    setTerminalTabsLayout(value.layout, { persist: false });
  }
  if (Number.isFinite(value.sidebarWidth) && value.sidebarWidth >= TERMINAL_TABS_SIDEBAR_WIDTH_MIN_PX) {
    writeDurableLayoutCache(TERMINAL_TABS_SIDEBAR_WIDTH_STORAGE_KEY, String(Math.round(value.sidebarWidth)));
    restoreTerminalTabsSidebarWidthPreference();
  }
  if (value.customGroups && value.customGroups.version === 1) {
    writeDurableLayoutCache(TERMINAL_CUSTOM_GROUPS_STORAGE_KEY, JSON.stringify(value.customGroups));
    restoreTerminalCustomGroups();
    syncTerminalCustomGroupsWithTabs(tabs, { persist: false });
    renderTabs();
  }
}

function applyDurableFileViewerWidth(value) {
  if (!Number.isFinite(value)) return;
  const width = Math.round(value);
  if (width < FILE_VIEWER_WIDTH_MIN_PX) return;
  writeDurableLayoutCache(FILE_VIEWER_WIDTH_STORAGE_KEY, String(width));
  restoreFileViewerWidthPreference();
  if (activeFileViewer && !isSidePanelOverlayView()) applyFileViewerWidth(width);
}

function applyDurableUiLayoutField(field, value) {
  if (field === "sidePanel") applyDurableSidePanelLayout(value);
  else if (field === "composerActions") applyDurableComposerActionsLayout(value);
  else if (field === "controlVisibility") applyDurableControlVisibility(value);
  else if (field === "footerScopedModelOrder") applyDurableFooterScopedModelOrder(value);
  else if (field === "terminalTabs") applyDurableTerminalTabsLayout(value);
  else if (field === "fileViewerWidth") applyDurableFileViewerWidth(value);
}

function durableUiLayoutInteractionActive(field = null) {
  const activeByField = {
    sidePanel: Boolean(sidePanelSectionPointerDrag?.active || sidePanelResizeState),
    composerActions: Boolean(composerActionPointerDrag?.active),
    controlVisibility: false,
    footerScopedModelOrder: Boolean(footerScopedModelPointerDrag?.active),
    terminalTabs: Boolean(terminalTabDragId || terminalTabsResizeState),
    fileViewerWidth: Boolean(fileViewerResizeState),
  };
  return field ? activeByField[field] === true : Object.values(activeByField).some(Boolean);
}

function durableUiLayoutGeneration(field) {
  return durableLayoutGenerations.get(field) || 0;
}

function warnDurableUiLayoutOnce(message) {
  if (durableLayoutWarned) return;
  durableLayoutWarned = true;
  addEvent(message, "warn");
}

function scheduleDurableUiLayoutSave(delay = UI_LAYOUT_SAVE_DEBOUNCE_MS) {
  // One coalescing writer: repeated drag-over commits only reset this timer.
  if (durableLayoutSaveTimer !== null) clearTimeout(durableLayoutSaveTimer);
  durableLayoutSaveTimer = setTimeout(() => {
    durableLayoutSaveTimer = null;
    flushDurableUiLayoutSave();
  }, delay);
}

function markDurableUiLayoutDirty(field, subfield = null) {
  if (!UI_LAYOUT_FIELDS.includes(field)) return;
  const allowedSubfields = durableUiLayoutSubFields(field);
  if (subfield && !allowedSubfields?.includes(subfield)) return;
  const generation = durableUiLayoutGeneration(field) + 1;
  const previous = durableLayoutDirtyFields.get(field);
  const value = collectDurableUiLayoutField(field);
  let subfields = null;
  let subfieldGenerations = null;
  let subfieldMutationIds = null;
  let mutationId = null;
  if (allowedSubfields && field !== "composerActions") {
    subfields = new Set(previous?.subfields || []);
    subfieldGenerations = new Map(previous?.subfieldGenerations || []);
    subfieldMutationIds = new Map(previous?.subfieldMutationIds || []);
    const changedSubfields = subfield ? [subfield] : allowedSubfields;
    for (const key of changedSubfields) {
      const nextMutationId = writeDurableUiLayoutPendingMutation(field, key, value?.[key] ?? null);
      if (nextMutationId) {
        removeDurableUiLayoutPendingMutation(subfieldMutationIds.get(key));
        subfieldMutationIds.set(key, nextMutationId);
      }
      subfields.add(key);
      subfieldGenerations.set(key, generation);
    }
  } else {
    mutationId = writeDurableUiLayoutPendingMutation(field, null, value);
    if (mutationId) removeDurableUiLayoutPendingMutation(previous?.mutationId);
    else mutationId = previous?.mutationId || null;
  }
  durableLayoutGenerations.set(field, generation);
  durableLayoutDirtyFields.set(field, {
    generation,
    value,
    subfields,
    subfieldGenerations,
    subfieldMutationIds,
    mutationId,
  });
  durableLayoutConflictAttempts = 0;
  scheduleDurableUiLayoutSave();
}

function applyDurableUiLayoutSnapshot(data, { generations = null, readEpoch = 0 } = {}) {
  if (!data || typeof data !== "object") return false;
  if (readEpoch && readEpoch <= durableLayoutWriteFenceReadEpoch) return false;
  if (readEpoch && readEpoch < durableLayoutAppliedReadEpoch) return false;
  if (readEpoch) durableLayoutAppliedReadEpoch = readEpoch;
  if (typeof data.layoutRevision === "string" && data.layoutRevision) durableLayoutRevision = data.layoutRevision;
  const layout = data.layout && typeof data.layout === "object" ? data.layout : null;
  if (!layout || layout.version !== UI_LAYOUT_SCHEMA_VERSION) return Boolean(durableLayoutRevision);
  for (const field of UI_LAYOUT_FIELDS) {
    const requestedGeneration = generations ? generations.get(field) ?? 0 : durableUiLayoutGeneration(field);
    const generationChanged = durableUiLayoutGeneration(field) !== requestedGeneration;
    const dirtyEntry = durableLayoutDirtyFields.get(field);
    const serverValue = layout[field] ?? null;
    const localValue = collectDurableUiLayoutField(field);
    const subfields = durableUiLayoutSubFields(field);
    const dirtySubfields = dirtyEntry?.subfields;

      if (subfields && field !== "composerActions") {
      const applicable = {};
      let hasApplicable = false;
      for (const subfield of subfields) {
        const isDirty = dirtySubfields?.has(subfield) === true;
        const activelyManipulated = field === "sidePanel" && (
          (subfield === "sectionLayout" && Boolean(sidePanelSectionPointerDrag?.active))
          || (subfield === "panelWidths" && Boolean(sidePanelResizeState))
        );
        const remote = serverValue?.[subfield] ?? null;
        const local = localValue?.[subfield] ?? null;
        const remotePresent = durableUiLayoutSubfieldValuePresent(field, subfield, remote);
        if (!isDirty && !activelyManipulated && !generationChanged && remotePresent) {
          applicable[subfield] = remote;
          hasApplicable = true;
        }
        if (!isDirty && !remotePresent && durableUiLayoutValuePresent(local)) {
          markDurableUiLayoutDirty(field, subfield);
        }
      }
      if (hasApplicable) applyDurableUiLayoutField(field, applicable);
      continue;
    }

    if (!dirtyEntry && !generationChanged && !durableUiLayoutInteractionActive(field) && durableUiLayoutValuePresent(serverValue)) {
      applyDurableUiLayoutField(field, serverValue);
    }
    if (!dirtyEntry && !durableUiLayoutValuePresent(serverValue) && durableUiLayoutValuePresent(localValue)) {
      markDurableUiLayoutDirty(field);
    }
  }
  return true;
}

async function refreshDurableUiLayoutFromServer() {
  const generations = new Map(UI_LAYOUT_FIELDS.map((field) => [field, durableUiLayoutGeneration(field)]));
  const readEpoch = ++durableLayoutReadEpoch;
  try {
    const response = await api(UI_LAYOUT_ENDPOINT, { scoped: false });
    return applyDurableUiLayoutSnapshot(response.data, { generations, readEpoch });
  } catch {
    // Keep the local cache authoritative until the settings file is reachable.
    return false;
  }
}

async function flushDurableUiLayoutSave() {
  if (durableLayoutSaveInFlight || !durableLayoutDirtyFields.size) return;
  if ([...durableLayoutDirtyFields.keys()].some((field) => durableUiLayoutInteractionActive(field))) {
    scheduleDurableUiLayoutSave();
    return;
  }
  if (typeof navigator !== "undefined" && navigator.onLine === false) return;
  durableLayoutSaveInFlight = true;
  let snapshot = new Map();
  let retryImmediately = false;
  try {
    if (!durableLayoutRevision) await refreshDurableUiLayoutFromServer();
    if (!durableLayoutRevision || !durableLayoutDirtyFields.size) return;
    snapshot = new Map([...durableLayoutDirtyFields].map(([field, entry]) => [field, {
      ...entry,
      subfields: entry.subfields ? new Set(entry.subfields) : null,
      subfieldGenerations: entry.subfieldGenerations ? new Map(entry.subfieldGenerations) : null,
      subfieldMutationIds: entry.subfieldMutationIds ? new Map(entry.subfieldMutationIds) : null,
    }]));
    const patch = { version: UI_LAYOUT_SCHEMA_VERSION };
    for (const [field, entry] of snapshot) patch[field] = durableUiLayoutEntryPatch(field, entry);
      const mixedWidth = patch.sidePanel?.panelWidths?.right;
    const response = await api(UI_LAYOUT_ENDPOINT, {
      method: "PUT",
      scoped: false,
      body: {
        layout: patch,
        ...(Number.isFinite(mixedWidth) ? { sidePanelWidth: mixedWidth } : {}),
        expectedLayoutRevision: durableLayoutRevision,
      },
    });
    // A successful write is newer than every GET that began before this
    // acknowledgement, even if one of those reads completes afterward.
    durableLayoutWriteFenceReadEpoch = Math.max(durableLayoutWriteFenceReadEpoch, durableLayoutReadEpoch);
    if (typeof response.data?.layoutRevision === "string" && response.data.layoutRevision) durableLayoutRevision = response.data.layoutRevision;
    for (const [field, entry] of snapshot) {
      const current = durableLayoutDirtyFields.get(field);
      if (!current) continue;
      if (entry.subfields?.size) {
        for (const subfield of entry.subfields) {
          if (current.subfieldGenerations?.get(subfield) !== entry.subfieldGenerations?.get(subfield)) continue;
          if (current.subfieldMutationIds?.get(subfield) !== entry.subfieldMutationIds?.get(subfield)) continue;
          current.subfields.delete(subfield);
          current.subfieldGenerations.delete(subfield);
          current.subfieldMutationIds.delete(subfield);
        }
        if (!current.subfields.size) durableLayoutDirtyFields.delete(field);
        else current.value = collectDurableUiLayoutField(field);
      } else if (current.generation === entry.generation && current.mutationId === entry.mutationId) {
        durableLayoutDirtyFields.delete(field);
        if (field === "controlVisibility") {
          // Another tab may have overwritten the same-origin cache while this
          // mutation was pending; the acknowledged value is authoritative now.
          writeDurableLayoutCache(CONTROL_VISIBILITY_HIDDEN_IDS_STORAGE_KEY, JSON.stringify(entry.value?.hiddenIds ?? null));
          applyControlVisibility();
        }
      }
    }
    clearAcknowledgedDurableUiLayoutPendingMutations(snapshot);
    durableLayoutConflictAttempts = 0;
    durableLayoutWarned = false;
  } catch (error) {
    const status = Number(error?.statusCode) || 0;
    if (status === 409) {
      durableLayoutConflictAttempts += 1;
      await refreshDurableUiLayoutFromServer();
      if (durableLayoutConflictAttempts <= UI_LAYOUT_MAX_CONFLICT_RETRIES) retryImmediately = durableLayoutDirtyFields.size > 0;
      else warnDurableUiLayoutOnce("Durable layout changes stayed in this browser because the saved layout kept changing elsewhere.");
    } else if (status >= 400 && status < 500 && status !== 401 && status !== 408 && status !== 429) {
      // Keep the pending journal for recovery, but do not retry a rejected
      // payload until another user/lifecycle event supplies a new opportunity.
      warnDurableUiLayoutOnce(`Could not save the durable UI layout: ${error?.message || String(error)}`);
    }
    // Offline and server failures keep the newest dirty state for the next
    // mutation, online event, or foreground reconciliation.
  } finally {
    durableLayoutSaveInFlight = false;
  }
  const hasNewerMutation = [...durableLayoutDirtyFields].some(([field, entry]) => snapshot.get(field)?.generation !== entry.generation);
  if (retryImmediately || hasNewerMutation) scheduleDurableUiLayoutSave(retryImmediately ? 0 : UI_LAYOUT_SAVE_DEBOUNCE_MS);
}

function reconcileDurableUiLayout() {
  if (durableUiLayoutInteractionActive()) return;
  refreshDurableUiLayoutFromServer().then((ready) => {
    if (ready && durableLayoutDirtyFields.size) scheduleDurableUiLayoutSave(0);
  });
}

function readStoredSidePanelWidth() {
  try {
    const width = Number.parseFloat(localStorage.getItem(SIDE_PANEL_WIDTH_STORAGE_KEY) || "");
    return Number.isFinite(width) && width >= SIDE_PANEL_WIDTH_MIN_PX && width <= SIDE_PANEL_WIDTH_MAX_PX ? width : null;
  } catch {
    return null;
  }
}

function cacheSidePanelWidth(width) {
  try {
    localStorage.setItem(SIDE_PANEL_WIDTH_STORAGE_KEY, String(Math.round(width)));
  } catch {
    // Browser storage is only a local fallback for the user-scoped preference.
  }
}

function persistSidePanelWidth(width, side = "right") {
  const rounded = Math.round(width);
  sidePanelWidthPreferenceRevision += 1;
  if (side === "right") cacheSidePanelWidth(rounded);
  controlDeckLayout.panelWidths = { ...controlDeckLayout.panelWidths, [side]: rounded };
  cacheControlDeckLayout(controlDeckLayout, "panelWidths");
  markDurableUiLayoutDirty("sidePanel", "panelWidths");
}

function sidePanelMaxWidth(side = "right") {
  const layout = document.querySelector(".layout");
  const layoutRect = layout?.getBoundingClientRect?.();
  const layoutWidth = layoutRect?.width || window.innerWidth || SIDE_PANEL_WIDTH_DEFAULT_PX;
  const layoutStyle = layout ? getComputedStyle(layout) : null;
  const gap = Number.parseFloat(layoutStyle?.columnGap || layoutStyle?.gap || "0") || 0;
  const horizontalPadding = (Number.parseFloat(layoutStyle?.paddingLeft || "0") || 0) + (Number.parseFloat(layoutStyle?.paddingRight || "0") || 0);
  const contentWidth = Math.max(0, layoutWidth - horizontalPadding);
  const fileViewerVisible = !!activeFileViewer && elements.fileViewerPane && getComputedStyle(elements.fileViewerPane).display !== "none";
  const fileViewerWidth = fileViewerVisible ? Math.max(FILE_VIEWER_WIDTH_MIN_PX, elements.fileViewerPane.getBoundingClientRect().width) : 0;
  const splitOpen = document.body.classList.contains("terminal-split-open");
  const terminalRailWidth = isControlDeckSidebarPresentation() ? Math.max(TERMINAL_TABS_SIDEBAR_WIDTH_MIN_PX, currentTerminalTabsSidebarWidth()) : 0;
  const centralMinimum = 320 + (splitOpen ? 320 : 0) + fileViewerWidth + terminalRailWidth;
  const otherSide = side === "left" ? "right" : "left";
  const otherPanelVisible = effectiveControlDeckPresentation() === "both" && !controlDeckLayout.collapsedPanels?.[otherSide];
  const otherPanelWidth = otherPanelVisible ? Math.max(SIDE_PANEL_WIDTH_MIN_PX, currentSidePanelWidth(otherSide)) : 0;
  const otherColumnCount = 1 + (splitOpen ? 1 : 0) + (fileViewerVisible ? 1 : 0) + (otherPanelVisible ? 1 : 0);
  const available = contentWidth - otherPanelWidth - centralMinimum - (gap * otherColumnCount);
  return Math.max(SIDE_PANEL_WIDTH_MIN_PX, Math.min(Math.floor(contentWidth * 0.72), Math.floor(available)));
}

function clampSidePanelWidth(width, side = "right") {
  const number = Number(width);
  const max = sidePanelMaxWidth(side);
  const fallback = controlDeckLayout.panelWidths?.[side] || (side === "right" ? readStoredSidePanelWidth() : null) || SIDE_PANEL_WIDTH_DEFAULT_PX;
  return Math.max(SIDE_PANEL_WIDTH_MIN_PX, Math.min(max, Number.isFinite(number) ? number : fallback));
}

function currentSidePanelWidth(side = "right") {
  const shell = side === "left" ? elements.sidePanelLeft : elements.sidePanel;
  const width = shell?.getBoundingClientRect?.().width;
  return Number.isFinite(width) && width > 0 ? width : controlDeckLayout.panelWidths?.[side] || (side === "right" ? readStoredSidePanelWidth() : null) || SIDE_PANEL_WIDTH_DEFAULT_PX;
}

function controlDeckSideResizeAvailable(side = "right") {
  const presentation = effectiveControlDeckPresentation();
  if (presentation === "overlay" || presentation === "embedded" || controlDeckLayout.collapsedPanels?.[side]) return false;
  return side === "left"
    ? presentation === "left" || presentation === "both"
    : presentation === "right" || presentation === "both";
}

function updateSidePanelResizeHandle(width = currentSidePanelWidth("right"), side = "right") {
  const handle = side === "left" ? elements.sidePanelResizeHandleLeft : elements.sidePanelResizeHandle;
  if (!handle) return;
  handle.hidden = !controlDeckSideResizeAvailable(side);
  handle.setAttribute("aria-valuemin", String(SIDE_PANEL_WIDTH_MIN_PX));
  handle.setAttribute("aria-valuemax", String(sidePanelMaxWidth(side)));
  handle.setAttribute("aria-valuenow", String(Math.round(width)));
  handle.setAttribute("aria-valuetext", `${Math.round(width)} pixels wide`);
}

function applySidePanelWidth(width, { persist = false, side = "right" } = {}) {
  const clamped = clampSidePanelWidth(width, side);
  const variable = side === "left" ? "--side-panel-left-width" : "--side-panel-right-width";
  document.documentElement.style.setProperty(variable, `${Math.round(clamped)}px`);
  if (side === "right") document.documentElement.style.setProperty("--side-panel-width", `${Math.round(clamped)}px`);
  updateSidePanelResizeHandle(clamped, side);
  if (persist) persistSidePanelWidth(clamped, side);
  return clamped;
}

async function restoreSidePanelWidthPreference() {
  const localWidth = readStoredSidePanelWidth();
  if (localWidth) document.documentElement.style.setProperty("--side-panel-width", `${Math.round(localWidth)}px`);
  if (!isSidePanelOverlayView()) {
    applySidePanelWidth(controlDeckLayout.panelWidths?.left || SIDE_PANEL_WIDTH_DEFAULT_PX, { side: "left" });
    applySidePanelWidth(controlDeckLayout.panelWidths?.right || localWidth || SIDE_PANEL_WIDTH_DEFAULT_PX, { side: "right" });
  } else {
    updateSidePanelResizeHandle(currentSidePanelWidth("left"), "left");
    updateSidePanelResizeHandle(localWidth || currentSidePanelWidth("right"), "right");
  }

  const restoreRevision = sidePanelWidthPreferenceRevision;
  const layoutGenerations = new Map(UI_LAYOUT_FIELDS.map((field) => [field, durableUiLayoutGeneration(field)]));
  const readEpoch = ++durableLayoutReadEpoch;
  try {
    // One non-blocking unscoped read hydrates both the width preference and the
    // durable layout after the synchronous local-cache startup pass.
    const response = await api("/api/interface-preferences", { scoped: false });
    applyDurableUiLayoutSnapshot(response.data, { generations: layoutGenerations, readEpoch });
    if (restoreRevision !== sidePanelWidthPreferenceRevision) return;
    const userWidth = Number(response.data?.preferences?.sidePanelWidth);
    if (Number.isFinite(userWidth) && userWidth >= SIDE_PANEL_WIDTH_MIN_PX) {
      cacheSidePanelWidth(userWidth);
      document.documentElement.style.setProperty("--side-panel-width", `${Math.round(userWidth)}px`);
      if (!isSidePanelOverlayView()) applySidePanelWidth(userWidth);
      else updateSidePanelResizeHandle(userWidth);
    } else if (localWidth) {
      persistSidePanelWidth(localWidth);
    }
  } catch {
    // Keep the browser-local fallback when user settings cannot be loaded.
  }
}

function beginSidePanelResize(event, forcedSide = null) {
  const side = forcedSide || (event.currentTarget === elements.sidePanelResizeHandleLeft ? "left" : "right");
  if (!controlDeckSideResizeAvailable(side)) return;
  if (event.button !== undefined && event.button !== 0) return;
  event.preventDefault();
  const startWidth = currentSidePanelWidth(side);
  sidePanelResizeState = { side, pointerId: event.pointerId, startX: event.clientX, startWidth, width: startWidth };
  document.body.classList.add("side-panel-resizing");
  (side === "left" ? elements.sidePanelResizeHandleLeft : elements.sidePanelResizeHandle)?.setPointerCapture?.(event.pointerId);
  window.addEventListener("pointermove", updateSidePanelResize, { passive: false });
  window.addEventListener("pointerup", finishSidePanelResize, { passive: false });
  window.addEventListener("pointercancel", finishSidePanelResize, { passive: false });
}

function updateSidePanelResize(event) {
  const state = sidePanelResizeState;
  if (!state || (event.pointerId !== undefined && event.pointerId !== state.pointerId)) return;
  event.preventDefault();
  const delta = state.side === "left" ? event.clientX - state.startX : state.startX - event.clientX;
  state.width = applySidePanelWidth(state.startWidth + delta, { side: state.side });
}

function finishSidePanelResize(event) {
  const state = sidePanelResizeState;
  if (!state || (event.pointerId !== undefined && event.pointerId !== state.pointerId)) return;
  event.preventDefault?.();
  (state.side === "left" ? elements.sidePanelResizeHandleLeft : elements.sidePanelResizeHandle)?.releasePointerCapture?.(state.pointerId);
  window.removeEventListener("pointermove", updateSidePanelResize);
  window.removeEventListener("pointerup", finishSidePanelResize);
  window.removeEventListener("pointercancel", finishSidePanelResize);
  document.body.classList.remove("side-panel-resizing");
  applySidePanelWidth(state.width, { persist: true, side: state.side });
  sidePanelResizeState = null;
}

function handleSidePanelResizeKeydown(event) {
  const side = event.currentTarget === elements.sidePanelResizeHandleLeft ? "left" : "right";
  if (!controlDeckSideResizeAvailable(side)) return;
  const step = event.shiftKey ? 80 : 24;
  const current = currentSidePanelWidth(side);
  let next = current;
  if (event.key === "ArrowLeft") next = side === "left" ? current - step : current + step;
  else if (event.key === "ArrowRight") next = side === "left" ? current + step : current - step;
  else if (event.key === "Home") next = SIDE_PANEL_WIDTH_MIN_PX;
  else if (event.key === "End") next = sidePanelMaxWidth(side);
  else return;
  event.preventDefault();
  applySidePanelWidth(next, { persist: true, side });
}

function syncSidePanelWidthForViewport() {
  if (isSidePanelOverlayView()) {
    updateSidePanelResizeHandle(currentSidePanelWidth("left"), "left");
    updateSidePanelResizeHandle(currentSidePanelWidth("right"), "right");
    return;
  }
  // Keep viewport/layout reconciliation anchored to the durable preferences.
  // Reading rendered widths here can capture an in-progress CSS transition
  // during hard-reset startup and permanently freeze a panel below its saved width.
  applySidePanelWidth(controlDeckLayout.panelWidths?.left || currentSidePanelWidth("left"), { side: "left" });
  applySidePanelWidth(controlDeckLayout.panelWidths?.right || readStoredSidePanelWidth() || currentSidePanelWidth("right"), { side: "right" });
}

function readStoredFileViewerWidth() {
  try {
    const width = Number.parseFloat(localStorage.getItem(FILE_VIEWER_WIDTH_STORAGE_KEY) || "");
    return Number.isFinite(width) && width >= FILE_VIEWER_WIDTH_MIN_PX ? width : null;
  } catch {
    return null;
  }
}

function persistFileViewerWidth(width) {
  try {
    localStorage.setItem(FILE_VIEWER_WIDTH_STORAGE_KEY, String(Math.round(width)));
  } catch {
    // Ignore storage failures; resizing should still work for this page load.
  }
  markDurableUiLayoutDirty("fileViewerWidth");
}

function fileViewerMaxWidth() {
  const layout = document.querySelector(".layout");
  const layoutRect = layout?.getBoundingClientRect?.();
  const layoutWidth = layoutRect?.width || window.innerWidth || FILE_VIEWER_WIDTH_DEFAULT_PX;
  const layoutStyle = layout ? getComputedStyle(layout) : null;
  const gap = Number.parseFloat(layoutStyle?.columnGap || layoutStyle?.gap || "0") || 0;
  const sidePanelVisible = !document.body.classList.contains("side-panel-collapsed") && elements.sidePanel && getComputedStyle(elements.sidePanel).display !== "none";
  const sidePanelWidth = sidePanelVisible ? elements.sidePanel.getBoundingClientRect().width : 0;
  const splitOpen = document.body.classList.contains("terminal-split-open");
  const primaryMinWidth = splitOpen ? 560 : 320;
  const gapCount = splitOpen ? (sidePanelVisible ? 3 : 2) : (sidePanelVisible ? 2 : 1);
  const available = layoutWidth - sidePanelWidth - primaryMinWidth - (gap * gapCount);
  return Math.max(FILE_VIEWER_WIDTH_MIN_PX, Math.min(Math.floor(layoutWidth * 0.78), Math.floor(available)));
}

function clampFileViewerWidth(width) {
  const number = Number(width);
  const max = fileViewerMaxWidth();
  const fallback = readStoredFileViewerWidth() || FILE_VIEWER_WIDTH_DEFAULT_PX;
  return Math.max(FILE_VIEWER_WIDTH_MIN_PX, Math.min(max, Number.isFinite(number) ? number : fallback));
}

function currentFileViewerWidth() {
  const width = elements.fileViewerPane?.getBoundingClientRect?.().width;
  return Number.isFinite(width) && width > 0 ? width : readStoredFileViewerWidth() || FILE_VIEWER_WIDTH_DEFAULT_PX;
}

function updateFileViewerResizeHandle(width = currentFileViewerWidth()) {
  const handle = elements.fileViewerResizeHandle;
  if (!handle) return;
  const resizeAvailable = !!activeFileViewer && !isSidePanelOverlayView();
  handle.hidden = !resizeAvailable;
  handle.setAttribute("aria-valuemin", String(FILE_VIEWER_WIDTH_MIN_PX));
  handle.setAttribute("aria-valuemax", String(fileViewerMaxWidth()));
  handle.setAttribute("aria-valuenow", String(Math.round(width)));
  handle.setAttribute("aria-valuetext", `${Math.round(width)} pixels wide`);
}

function applyFileViewerWidth(width, { persist = false } = {}) {
  const clamped = clampFileViewerWidth(width);
  document.documentElement.style.setProperty("--file-viewer-width", `${Math.round(clamped)}px`);
  updateFileViewerResizeHandle(clamped);
  if (persist) persistFileViewerWidth(clamped);
  return clamped;
}

function restoreFileViewerWidthPreference() {
  const width = readStoredFileViewerWidth();
  if (width) document.documentElement.style.setProperty("--file-viewer-width", `${Math.round(width)}px`);
  updateFileViewerResizeHandle(width || FILE_VIEWER_WIDTH_DEFAULT_PX);
}

function beginFileViewerResize(event) {
  if (!activeFileViewer || isSidePanelOverlayView()) return;
  if (event.button !== undefined && event.button !== 0) return;
  event.preventDefault();
  const startWidth = currentFileViewerWidth();
  fileViewerResizeState = { pointerId: event.pointerId, startX: event.clientX, startWidth, width: startWidth };
  document.body.classList.add("file-viewer-resizing");
  elements.fileViewerResizeHandle?.setPointerCapture?.(event.pointerId);
  window.addEventListener("pointermove", updateFileViewerResize, { passive: false });
  window.addEventListener("pointerup", finishFileViewerResize, { passive: false });
  window.addEventListener("pointercancel", finishFileViewerResize, { passive: false });
}

function updateFileViewerResize(event) {
  const state = fileViewerResizeState;
  if (!state || (event.pointerId !== undefined && event.pointerId !== state.pointerId)) return;
  event.preventDefault();
  state.width = applyFileViewerWidth(state.startWidth + (state.startX - event.clientX));
}

function finishFileViewerResize(event) {
  const state = fileViewerResizeState;
  if (!state || (event.pointerId !== undefined && event.pointerId !== state.pointerId)) return;
  event.preventDefault?.();
  elements.fileViewerResizeHandle?.releasePointerCapture?.(state.pointerId);
  window.removeEventListener("pointermove", updateFileViewerResize);
  window.removeEventListener("pointerup", finishFileViewerResize);
  window.removeEventListener("pointercancel", finishFileViewerResize);
  document.body.classList.remove("file-viewer-resizing");
  applyFileViewerWidth(state.width, { persist: true });
  fileViewerResizeState = null;
}

function handleFileViewerResizeKeydown(event) {
  if (!activeFileViewer || isSidePanelOverlayView()) return;
  const step = event.shiftKey ? 80 : 24;
  const current = currentFileViewerWidth();
  let next = current;
  if (event.key === "ArrowLeft") next = current + step;
  else if (event.key === "ArrowRight") next = current - step;
  else if (event.key === "Home") next = FILE_VIEWER_WIDTH_MIN_PX;
  else if (event.key === "End") next = fileViewerMaxWidth();
  else return;
  event.preventDefault();
  applyFileViewerWidth(next, { persist: true });
}

function syncFileViewerWidthForViewport() {
  if (!activeFileViewer) {
    updateFileViewerResizeHandle();
    return;
  }
  if (isSidePanelOverlayView()) {
    updateFileViewerResizeHandle();
    return;
  }
  applyFileViewerWidth(currentFileViewerWidth());
}

function syncResizablePanelWidthsForViewport() {
  syncSidePanelWidthForViewport();
  syncFileViewerWidthForViewport();
  syncTerminalTabsSidebarWidthForViewport();
}

async function openFileTreeEntryInWebui(entry = fileContextMenuState?.entry) {
  if (!entry) return;
  const path = normalizeFileTreePath(entry.path || "");
  if (entry.type === "directory" || entry.directory === true) {
    if (fileTreeState.searchQuery || fileTreeSearchQueryText()) return revealFileTreeEntry(entry);
    fileTreeState.expanded.add(path);
    await loadFileTreeDirectory(path);
    return;
  }
  await openFileInViewer(path);
}

const FILE_VIEWER_IMAGE_MIME_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp", "image/avif"]);

function fileViewerImageDataUrl(data = {}) {
  const mimeType = String(data.mimeType || "").toLowerCase();
  const encoded = String(data.data || "");
  if (!FILE_VIEWER_IMAGE_MIME_TYPES.has(mimeType) || !encoded) return "";
  return `data:${mimeType};base64,${encoded}`;
}

// Changes mode only exists for Git-originated opens. Image previews are
// read-only, while text keeps the original Source/Markdown-Preview behavior.
function resolveFileViewerMode(viewer) {
  if (!viewer) return "source";
  const hasChanges = !!viewer.gitChanges;
  if (viewer.mode === "changes") return hasChanges ? "changes" : viewer.kind === "image" ? "image" : "source";
  if (viewer.kind === "image") return "image";
  if (viewer.sourceAvailable === false) return hasChanges ? "changes" : "source";
  return viewer.mode === "preview" && viewer.language === "markdown" ? "preview" : "source";
}

function setFileViewerMode(mode = "source") {
  if (!activeFileViewer) return;
  const previousMode = activeFileViewer.mode;
  activeFileViewer.mode = resolveFileViewerMode({ ...activeFileViewer, mode });
  if (activeFileViewer.mode === "changes" && previousMode !== "changes") clearFileViewerSelection();
  updateFileViewerUi();
  if (elements.fileViewerSearchBar && !elements.fileViewerSearchBar.hidden) {
    fileViewerSearchIndex = -1;
    runFileViewerSearch({ navigate: true });
  }
}

function setFileViewerDirty(dirty) {
  if (!activeFileViewer || activeFileViewer.readOnly) return;
  activeFileViewer.dirty = !!dirty;
  if (elements.fileViewerSaveButton) elements.fileViewerSaveButton.disabled = !activeFileViewer.dirty;
  if (activeFileViewer.dirty) setFileViewerStatus("Unsaved file edits.", "warn");
}

function updateFileViewerUi() {
  const open = !!activeFileViewer;
  document.body.classList.toggle("file-viewer-open", open);
  syncMobileShellInteractivity();
  if (elements.fileViewerPane) elements.fileViewerPane.hidden = !open;
  scheduleControlDeckPresentationReconciliation();
  updateFileViewerResizeHandle();
  if (!open) {
    closeFileViewerSearch({ restoreFocus: false });
    return;
  }
  if (!isSidePanelOverlayView()) applyFileViewerWidth(currentFileViewerWidth());
  const viewer = activeFileViewer;
  captureFileViewerEditorContinuity(viewer);
  const isMarkdown = viewer.language === "markdown";
  const isImage = viewer.kind === "image";
  const hasChanges = !!viewer.gitChanges;
  const sourceAvailable = viewer.sourceAvailable !== false;
  const mode = resolveFileViewerMode(viewer);
  viewer.mode = mode;
  if (elements.fileViewerTitle) elements.fileViewerTitle.textContent = viewer.name || fileDisplayName(viewer.path);
  if (elements.fileViewerMeta) {
    const lineCount = textLineCount(viewer.content || "");
    const sourceMeta = isImage
      ? [formatBytes(viewer.size), viewer.mimeType]
      : sourceAvailable ? [formatBytes(viewer.size), `${lineCount} ${lineCount === 1 ? "line" : "lines"}`] : ["source unavailable"];
    elements.fileViewerMeta.textContent = [viewer.path, ...sourceMeta].filter(Boolean).join(" · ");
  }
  if (elements.fileViewerChangesModeButton) {
    elements.fileViewerChangesModeButton.hidden = !hasChanges;
    elements.fileViewerChangesModeButton.disabled = !hasChanges;
    elements.fileViewerChangesModeButton.setAttribute("aria-pressed", mode === "changes" ? "true" : "false");
    elements.fileViewerChangesModeButton.classList.toggle("active", mode === "changes");
    elements.fileViewerChangesModeButton.title = hasChanges ? `${viewer.gitChanges.label || "Git"} changes for this file` : "";
  }
  if (elements.fileViewerSourceModeButton) {
    elements.fileViewerSourceModeButton.disabled = !sourceAvailable;
    elements.fileViewerSourceModeButton.setAttribute("aria-pressed", mode === "source" ? "true" : "false");
    elements.fileViewerSourceModeButton.classList.toggle("active", mode === "source");
  }
  if (elements.fileViewerPreviewModeButton) {
    elements.fileViewerPreviewModeButton.hidden = !isMarkdown && !isImage;
    elements.fileViewerPreviewModeButton.disabled = (!isMarkdown || !sourceAvailable) && !isImage;
    elements.fileViewerPreviewModeButton.setAttribute("aria-pressed", ["preview", "image"].includes(mode) ? "true" : "false");
    elements.fileViewerPreviewModeButton.classList.toggle("active", ["preview", "image"].includes(mode));
  }
  if (elements.fileViewerEditor) {
    elements.fileViewerEditor.hidden = mode !== "source";
    elements.fileViewerEditor.readOnly = viewer.readOnly === true;
    if (elements.fileViewerEditor.value !== viewer.content) elements.fileViewerEditor.value = viewer.content || "";
    elements.fileViewerEditor.dataset.fileViewerPath = viewer.path || "";
    if (mode === "source") restoreFileViewerEditorContinuity(viewer);
  }
  if (elements.fileViewerPreview) {
    elements.fileViewerPreview.hidden = mode !== "preview";
    if (mode === "preview") renderMarkdown(elements.fileViewerPreview, viewer.content || "");
    else elements.fileViewerPreview.replaceChildren();
  }
  if (elements.fileViewerImage) elements.fileViewerImage.hidden = mode !== "image";
  if (elements.fileViewerImageElement) {
    if (isImage) {
      if (elements.fileViewerImageElement.src !== viewer.imageUrl) elements.fileViewerImageElement.src = viewer.imageUrl;
      elements.fileViewerImageElement.alt = `Preview of ${viewer.name || fileDisplayName(viewer.path)}`;
    } else {
      elements.fileViewerImageElement.removeAttribute("src");
      elements.fileViewerImageElement.alt = "";
    }
  }
  if (elements.fileViewerChanges) {
    elements.fileViewerChanges.hidden = mode !== "changes";
    if (mode === "changes") renderFileViewerChanges(viewer.gitChanges);
    else elements.fileViewerChanges.replaceChildren();
  }
  if (elements.fileViewerSaveButton) elements.fileViewerSaveButton.disabled = viewer.readOnly === true || !viewer.dirty;
  if (elements.fileViewerOpenDefaultButton) {
    const viewerPath = normalizeFileTreePath(viewer.path || "");
    elements.fileViewerOpenDefaultButton.dataset.path = viewerPath;
    elements.fileViewerOpenDefaultButton.disabled = viewer.readOnly === true || !viewerPath;
  }
  if (isImage) {
    clearFileViewerSelection();
    closeFileViewerSearch({ restoreFocus: false });
  }
  renderFileViewerSelectionBar();
  if (elements.fileViewerSearchBar && !elements.fileViewerSearchBar.hidden) {
    fileViewerSearchIndex = -1;
    runFileViewerSearch({ navigate: false });
  }
}

const FILE_VIEWER_SEARCH_MATCH_LIMIT = 10_000;

function fileViewerSearchQueryText() {
  return String(elements.fileViewerSearchInput?.value || "");
}

function fileViewerSearchSurface() {
  const mode = resolveFileViewerMode(activeFileViewer);
  if (mode === "image") return null;
  if (mode === "preview") return elements.fileViewerPreview;
  if (mode === "changes") return elements.fileViewerChanges;
  return elements.fileViewerEditor;
}

function fileViewerSearchText() {
  const surface = fileViewerSearchSurface();
  if (surface === elements.fileViewerEditor) return String(surface?.value ?? activeFileViewer?.content ?? "");
  return String(surface?.textContent || "");
}

function collectFileViewerSearchMatches(query = fileViewerSearchQueryText()) {
  const haystack = fileViewerSearchText().toLowerCase();
  const needle = String(query || "").toLowerCase();
  if (!needle) return { matches: [], truncated: false };
  const matches = [];
  let offset = 0;
  while (matches.length < FILE_VIEWER_SEARCH_MATCH_LIMIT) {
    const index = haystack.indexOf(needle, offset);
    if (index < 0) return { matches, truncated: false };
    matches.push({ start: index, end: index + needle.length });
    offset = index + needle.length;
  }
  return { matches, truncated: haystack.indexOf(needle, offset) >= 0 };
}

function updateFileViewerSearchCount() {
  if (!elements.fileViewerSearchCount) return;
  const query = fileViewerSearchQueryText();
  if (!query) elements.fileViewerSearchCount.textContent = "";
  else if (!fileViewerSearchMatches.length) elements.fileViewerSearchCount.textContent = "0/0";
  else elements.fileViewerSearchCount.textContent = `${fileViewerSearchIndex + 1}/${fileViewerSearchMatches.length}${fileViewerSearchTruncated ? "+" : ""}`;
}

function textOffsetPosition(root, offset) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let remaining = Math.max(0, offset);
  let node = walker.nextNode();
  while (node) {
    const length = node.nodeValue?.length || 0;
    if (remaining <= length) return { node, offset: remaining };
    remaining -= length;
    node = walker.nextNode();
  }
  return null;
}

function textOffsetRange(root, match) {
  const start = textOffsetPosition(root, match.start);
  const end = textOffsetPosition(root, match.end);
  if (!start || !end) return null;
  const range = document.createRange();
  range.setStart(start.node, start.offset);
  range.setEnd(end.node, end.offset);
  return range;
}

function syncFileViewerSearchOverlayScroll() {
  const editor = elements.fileViewerEditor;
  const overlay = elements.fileViewerSearchOverlay;
  if (!editor || !overlay || overlay.hidden) return;
  overlay.scrollTop = editor.scrollTop;
  overlay.scrollLeft = editor.scrollLeft;
}

function clearFileViewerSearchHighlight() {
  globalThis.CSS?.highlights?.delete("file-viewer-search-match");
  globalThis.CSS?.highlights?.delete("file-viewer-search-current");
  for (const surface of [elements.fileViewerPreview, elements.fileViewerChanges]) {
    for (const node of surface?.querySelectorAll(".file-viewer-search-match-fallback, .file-viewer-search-current-fallback") || []) {
      node.classList.remove("file-viewer-search-match-fallback", "file-viewer-search-current-fallback");
    }
  }
  const overlay = elements.fileViewerSearchOverlay;
  if (overlay) {
    overlay.hidden = true;
    overlay.replaceChildren();
  }
  elements.fileViewerEditor?.closest(".file-viewer-content")?.classList.remove("search-highlights-source");
}

function renderFileViewerSourceSearchHighlights() {
  const editor = elements.fileViewerEditor;
  const overlay = elements.fileViewerSearchOverlay;
  if (!editor || !overlay || !fileViewerSearchMatches.length) return;
  const text = fileViewerSearchText();
  const fragment = document.createDocumentFragment();
  let offset = 0;
  fileViewerSearchMatches.forEach((match, index) => {
    if (match.start > offset) fragment.append(document.createTextNode(text.slice(offset, match.start)));
    const mark = make("mark", `file-viewer-search-match${index === fileViewerSearchIndex ? " current" : ""}`, text.slice(match.start, match.end));
    fragment.append(mark);
    offset = match.end;
  });
  if (offset < text.length) fragment.append(document.createTextNode(text.slice(offset)));
  overlay.replaceChildren(fragment);
  overlay.hidden = false;
  editor.closest(".file-viewer-content")?.classList.add("search-highlights-source");
  syncFileViewerSearchOverlayScroll();
}

function renderFileViewerSearchHighlights() {
  clearFileViewerSearchHighlight();
  const surface = fileViewerSearchSurface();
  if (!surface || !fileViewerSearchMatches.length) return;
  if (surface === elements.fileViewerEditor) {
    renderFileViewerSourceSearchHighlights();
    return;
  }
  const ranges = fileViewerSearchMatches.map((match) => textOffsetRange(surface, match)).filter(Boolean);
  const currentRange = textOffsetRange(surface, fileViewerSearchMatches[fileViewerSearchIndex]);
  const HighlightConstructor = globalThis.Highlight;
  if (globalThis.CSS?.highlights && typeof HighlightConstructor === "function") {
    if (ranges.length) globalThis.CSS.highlights.set("file-viewer-search-match", new HighlightConstructor(...ranges));
    if (currentRange) globalThis.CSS.highlights.set("file-viewer-search-current", new HighlightConstructor(currentRange));
    return;
  }
  for (const match of fileViewerSearchMatches) textOffsetPosition(surface, match.start)?.node.parentElement?.classList.add("file-viewer-search-match-fallback");
  textOffsetPosition(surface, fileViewerSearchMatches[fileViewerSearchIndex]?.start)?.node.parentElement?.classList.add("file-viewer-search-current-fallback");
}

function focusFileViewerSearchMatch() {
  const match = fileViewerSearchMatches[fileViewerSearchIndex];
  const surface = fileViewerSearchSurface();
  renderFileViewerSearchHighlights();
  if (!match || !surface) return;
  if (surface === elements.fileViewerEditor) {
    surface.setSelectionRange(match.start, match.end);
    const lineIndex = surface.value.slice(0, match.start).split("\n").length - 1;
    const computedStyle = getComputedStyle(surface);
    const parsedLineHeight = Number.parseFloat(computedStyle.lineHeight);
    const fontSize = Number.parseFloat(computedStyle.fontSize) || 14;
    const lineHeight = !parsedLineHeight ? fontSize * 1.45 : parsedLineHeight < 8 ? parsedLineHeight * fontSize : parsedLineHeight;
    surface.scrollTop = Math.max(0, (lineIndex * lineHeight) - (surface.clientHeight / 2));
    syncFileViewerSearchOverlayScroll();
  } else {
    textOffsetPosition(surface, match.start)?.node.parentElement?.scrollIntoView({ block: "center", behavior: "instant" });
  }
  elements.fileViewerSearchInput?.focus({ preventScroll: true });
  updateFileViewerSearchCount();
}

function runFileViewerSearch({ navigate = false } = {}) {
  const surface = fileViewerSearchSurface();
  if (surface?.id) elements.fileViewerSearchInput?.setAttribute("aria-controls", surface.id);
  const result = collectFileViewerSearchMatches();
  fileViewerSearchMatches = result.matches;
  fileViewerSearchTruncated = result.truncated;
  if (!fileViewerSearchMatches.length) fileViewerSearchIndex = -1;
  else if (fileViewerSearchIndex < 0 || fileViewerSearchIndex >= fileViewerSearchMatches.length) fileViewerSearchIndex = 0;
  updateFileViewerSearchCount();
  if (navigate) focusFileViewerSearchMatch();
  else renderFileViewerSearchHighlights();
}

function stepFileViewerSearch(step) {
  if (!fileViewerSearchMatches.length) runFileViewerSearch();
  if (!fileViewerSearchMatches.length) return;
  fileViewerSearchIndex = (fileViewerSearchIndex + step + fileViewerSearchMatches.length) % fileViewerSearchMatches.length;
  focusFileViewerSearchMatch();
}

function openFileViewerSearch() {
  if (!activeFileViewer || activeFileViewer.kind === "image" || !elements.fileViewerSearchBar) return;
  closeChatSearch();
  const editor = fileViewerSearchSurface() === elements.fileViewerEditor ? elements.fileViewerEditor : null;
  const selectedText = editor && editor.selectionEnd > editor.selectionStart
    ? editor.value.slice(editor.selectionStart, editor.selectionEnd)
    : "";
  if (selectedText && !selectedText.includes("\n") && selectedText.length <= 200 && !fileViewerSearchQueryText()) {
    elements.fileViewerSearchInput.value = selectedText;
  }
  elements.fileViewerSearchBar.hidden = false;
  fileViewerSearchIndex = -1;
  runFileViewerSearch({ navigate: !!fileViewerSearchQueryText() });
  elements.fileViewerSearchInput?.focus({ preventScroll: true });
  elements.fileViewerSearchInput?.select();
}

function closeFileViewerSearch({ restoreFocus = true } = {}) {
  if (!elements.fileViewerSearchBar || elements.fileViewerSearchBar.hidden) return;
  clearTimeout(fileViewerSearchTimer);
  fileViewerSearchTimer = null;
  clearFileViewerSearchHighlight();
  elements.fileViewerSearchBar.hidden = true;
  fileViewerSearchMatches = [];
  fileViewerSearchIndex = -1;
  fileViewerSearchTruncated = false;
  updateFileViewerSearchCount();
  if (!restoreFocus) return;
  const mode = resolveFileViewerMode(activeFileViewer);
  if (mode === "image") elements.fileViewerImage?.focus({ preventScroll: true });
  else if (mode === "preview") elements.fileViewerPreview?.focus({ preventScroll: true });
  else if (mode === "changes") elements.fileViewerChanges?.focus({ preventScroll: true });
  else elements.fileViewerEditor?.focus({ preventScroll: true });
}

function fileViewerChangesNotice(text, level = "") {
  return make("p", `file-viewer-changes-notice ${level}`.trim(), text);
}

function fileViewerChangesHeading(snapshot) {
  const heading = make("div", "git-diff-section-heading");
  heading.append(
    make("div", "git-diff-section-title", `${snapshot.label || "Git"} changes`),
    make("div", "git-diff-section-meta", snapshot.command || "git diff"),
  );
  return heading;
}

// git diff --cc emits combined "@@@" hunks that the two-column parser cannot
// represent, so those diffs fall back to readable raw text.
function gitFileDiffUsesCombinedSyntax(diffText = "") {
  return /^@@@+ /m.test(String(diffText || ""));
}

function renderFileViewerUntrackedChanges(snapshot) {
  const entry = normalizeGitUntrackedEntry({
    path: snapshot.path || "file",
    size: snapshot.size,
    binary: snapshot.binary,
    error: snapshot.contentError,
    ...(typeof snapshot.content === "string" ? { content: snapshot.content } : {}),
  });
  if (!entry) return fileViewerChangesNotice("Untracked file content is unavailable.", "error");
  if (entry.contentMissing) return fileViewerChangesNotice("Untracked file content is unavailable.", "error");
  if (entry.error || entry.binary) return renderGitUntrackedRawFile(entry);
  return renderGitDiffFile(gitUntrackedEntryToDiffFile(entry));
}

function renderFileViewerTrackedChanges(snapshot) {
  const diff = String(snapshot.diff || "");
  if (!diff.trim()) return fileViewerChangesNotice(`No ${String(snapshot.label || "Git").toLowerCase()} changes for this file.`);
  if (gitFileDiffUsesCombinedSyntax(diff)) return make("pre", "git-diff-raw", diff);
  const files = parseGitUnifiedDiff(diff);
  if (!files.length) return make("pre", "git-diff-raw", diff);
  const fragment = document.createDocumentFragment();
  for (const file of files) fragment.append(renderGitDiffFile(file));
  return fragment;
}

function renderFileViewerChangesTruncation(snapshot) {
  const notice = make("div", "git-diff-truncated-notice");
  notice.append(make("span", undefined, `Diff truncated at ${formatBytes(snapshot.capBytes || 0)} — showing the bounded snapshot. Run the full command in a terminal for the complete diff:`));
  notice.append(make("code", "git-tools-command", snapshot.command || "git diff"));
  return notice;
}

function renderFileViewerChanges(snapshot = activeFileViewer?.gitChanges) {
  const container = elements.fileViewerChanges;
  if (!container) return;
  if (!snapshot) {
    container.replaceChildren();
    return;
  }
  const wrapper = make("section", `git-diff-section file-viewer-changes-section ${snapshot.category || ""}`.trim());
  wrapper.append(fileViewerChangesHeading(snapshot));
  if (snapshot.loading) wrapper.append(fileViewerChangesNotice("Loading Git changes…"));
  else if (snapshot.error) wrapper.append(fileViewerChangesNotice(snapshot.error, "error"));
  else {
    wrapper.append(snapshot.category === "untracked" ? renderFileViewerUntrackedChanges(snapshot) : renderFileViewerTrackedChanges(snapshot));
    if (snapshot.truncated) wrapper.append(renderFileViewerChangesTruncation(snapshot));
  }
  container.replaceChildren(wrapper);
}

function clearFileViewerSelection() {
  fileViewerSelection = null;
  renderFileViewerSelectionBar();
}

function selectedTextFromEditor() {
  const editor = elements.fileViewerEditor;
  if (!editor || editor.hidden || !activeFileViewer) return null;
  const start = editor.selectionStart;
  const end = editor.selectionEnd;
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return null;
  return { start, end, text: editor.value.slice(start, end) };
}

function lineColumnForOffset(text, offset) {
  const prefix = String(text || "").slice(0, Math.max(0, offset));
  const lines = prefix.split("\n");
  return { line: lines.length, column: (lines.at(-1) || "").length + 1 };
}

function fileSelectionLineRange(text, start, end) {
  const startPos = lineColumnForOffset(text, start);
  const endPos = lineColumnForOffset(text, end);
  return { startLine: startPos.line, endLine: endPos.line, startColumn: startPos.column, endColumn: endPos.column };
}

function fileSelectionContext(text, start, end, radius = FILE_VIEWER_CONTEXT_RADIUS_LINES) {
  const value = String(text || "");
  const lines = value.split("\n");
  const range = fileSelectionLineRange(value, start, end);
  const fromLine = Math.max(1, range.startLine - radius);
  const toLine = Math.min(lines.length, range.endLine + radius);
  const contextLines = [];
  for (let line = fromLine; line <= toLine; line += 1) {
    contextLines.push(`${String(line).padStart(4, " ")}: ${lines[line - 1] || ""}`);
  }
  return { ...range, fromLine, toLine, context: contextLines.join("\n") };
}

function updateFileViewerSelectionFromEditor() {
  if (!activeFileViewer) return;
  const selected = selectedTextFromEditor();
  if (!selected || !selected.text.trim()) {
    clearFileViewerSelection();
    return;
  }
  const context = fileSelectionContext(elements.fileViewerEditor.value || "", selected.start, selected.end);
  fileViewerSelection = { ...context, ...selected, path: activeFileViewer.path, fileName: activeFileViewer.name };
  renderFileViewerSelectionBar();
}

function updateFileViewerSelectionFromPreview() {
  if (!activeFileViewer || elements.fileViewerPreview?.hidden) return;
  const selection = window.getSelection?.();
  const preview = elements.fileViewerPreview;
  if (!preview || !selection?.anchorNode || !selection?.focusNode || !preview.contains(selection.anchorNode) || !preview.contains(selection.focusNode)) return;
  const text = String(selection.toString?.() || "").trim();
  if (!text) {
    clearFileViewerSelection();
    return;
  }
  const content = activeFileViewer.content || "";
  const start = Math.max(0, content.indexOf(text));
  const end = start >= 0 ? start + text.length : start;
  const context = start >= 0
    ? fileSelectionContext(content, start, end)
    : { startLine: 1, endLine: textLineCount(content), startColumn: 1, endColumn: 1, fromLine: 1, toLine: textLineCount(content), context: content.slice(0, 4000) };
  fileViewerSelection = { ...context, start, end, text, path: activeFileViewer.path, fileName: activeFileViewer.name };
  renderFileViewerSelectionBar();
}

function renderFileViewerSelectionBar() {
  if (!elements.fileSelectionBar) return;
  const hasSelection = !!fileViewerSelection?.text;
  elements.fileSelectionBar.hidden = !hasSelection;
  if (!hasSelection) return;
  const lineLabel = fileViewerSelection.startLine === fileViewerSelection.endLine
    ? `line ${fileViewerSelection.startLine}`
    : `lines ${fileViewerSelection.startLine}-${fileViewerSelection.endLine}`;
  if (elements.fileSelectionSummary) elements.fileSelectionSummary.textContent = `${lineLabel} · ${fileViewerSelection.text.length} chars selected`;
}

function fileSelectionPrompt() {
  if (!activeFileViewer || !fileViewerSelection?.text) return "";
  const comment = (elements.fileSelectionCommentInput?.value || "").trim();
  const selection = fileViewerSelection;
  const range = selection.startLine === selection.endLine
    ? `line ${selection.startLine}, columns ${selection.startColumn}-${selection.endColumn}`
    : `lines ${selection.startLine}-${selection.endLine}`;
  return [
    `File selection from ${activeFileViewer.path} (${range}).`,
    comment ? `User comment: ${comment}` : "User comment: <none>",
    "",
    "Selected text:",
    "```",
    selection.text,
    "```",
    "",
    `Surrounding context (${selection.fromLine}-${selection.toLine}):`,
    "```",
    selection.context || selection.text,
    "```",
  ].join("\n");
}

async function sendFileSelectionToSession() {
  const prompt = fileSelectionPrompt();
  if (!prompt) return;
  if (elements.fileSelectionSendButton) elements.fileSelectionSendButton.disabled = true;
  try {
    await sendPrompt("prompt", prompt, { targetTabId: activeTabId, throwOnError: true });
    if (elements.fileSelectionCommentInput) elements.fileSelectionCommentInput.value = "";
    setFileViewerStatus("Selection sent to the current Pi session.", "success");
  } catch (error) {
    setFileViewerStatus(error.message || String(error), "error");
  } finally {
    if (elements.fileSelectionSendButton) elements.fileSelectionSendButton.disabled = false;
  }
}

function captureFileViewerEditorContinuity(viewer = activeFileViewer) {
  const editor = elements.fileViewerEditor;
  if (!viewer || !editor || editor.hidden || editor.dataset.fileViewerPath !== viewer.path) return;
  viewer.editorContinuity = {
    path: viewer.path,
    content: viewer.content,
    selectionStart: editor.selectionStart ?? editor.value.length,
    selectionEnd: editor.selectionEnd ?? editor.value.length,
    selectionDirection: editor.selectionDirection,
    scrollTop: editor.scrollTop,
    scrollLeft: editor.scrollLeft,
    focused: document.activeElement === editor,
  };
}

function restoreFileViewerEditorContinuity(viewer = activeFileViewer) {
  const editor = elements.fileViewerEditor;
  const state = viewer?.editorContinuity;
  if (!editor || !state || state.path !== viewer.path || state.content !== viewer.content || editor.dataset.fileViewerPath !== viewer.path) return;
  const length = editor.value.length;
  const start = Math.min(Math.max(0, state.selectionStart), length);
  const end = Math.min(Math.max(0, state.selectionEnd), length);
  try {
    editor.setSelectionRange(start, end, state.selectionDirection || "none");
  } catch {
    // A stale browser selection should not block the validated file restore.
  }
  editor.scrollTop = Math.min(Math.max(0, state.scrollTop || 0), Math.max(0, editor.scrollHeight - editor.clientHeight));
  editor.scrollLeft = Math.min(Math.max(0, state.scrollLeft || 0), Math.max(0, editor.scrollWidth - editor.clientWidth));
  if (state.focused && !isMeaningfulConnectedFocus(document.activeElement)) {
    editor.focus({ preventScroll: true });
  }
}

function cacheActiveFileViewerForTab(tabId = activeTabId) {
  if (!tabId) return;
  captureFileViewerEditorContinuity();
  if (activeFileViewer) fileViewersByTab.set(tabId, activeFileViewer);
  else fileViewersByTab.delete(tabId);
  if (fileViewerSelection) fileViewerSelectionsByTab.set(tabId, fileViewerSelection);
  else fileViewerSelectionsByTab.delete(tabId);
}

function resetFileViewerUi() {
  fileViewerOpenRequestSerial += 1;
  activeFileViewer = null;
  clearFileViewerSelection();
  document.body.classList.remove("file-viewer-open");
  syncMobileShellInteractivity();
  updateFileViewerResizeHandle();
  if (elements.fileViewerPane) elements.fileViewerPane.hidden = true;
  scheduleControlDeckPresentationReconciliation();
  if (elements.fileViewerOpenDefaultButton) elements.fileViewerOpenDefaultButton.dataset.path = "";
  if (elements.fileViewerEditor) {
    elements.fileViewerEditor.value = "";
    delete elements.fileViewerEditor.dataset.fileViewerPath;
    elements.fileViewerEditor.readOnly = false;
  }
  if (elements.fileViewerPreview) elements.fileViewerPreview.replaceChildren();
  if (elements.fileViewerImage) elements.fileViewerImage.hidden = true;
  if (elements.fileViewerImageElement) {
    elements.fileViewerImageElement.removeAttribute("src");
    elements.fileViewerImageElement.alt = "";
  }
  if (elements.fileViewerChanges) {
    elements.fileViewerChanges.hidden = true;
    elements.fileViewerChanges.replaceChildren();
  }
  setFileViewerStatus("");
}

function restoreFileViewerForActiveTab() {
  activeFileViewer = activeTabId ? fileViewersByTab.get(activeTabId) || null : null;
  fileViewerSelection = activeTabId ? fileViewerSelectionsByTab.get(activeTabId) || null : null;
  updateFileViewerUi();
  if (activeFileViewer?.dirty) setFileViewerStatus("Unsaved file edits.", "warn");
  else if (activeFileViewer) setFileViewerStatus("Restored for this terminal.", "success");
}

function closeFileViewer() {
  if (activeTabId) {
    fileViewersByTab.delete(activeTabId);
    fileViewerSelectionsByTab.delete(activeTabId);
  }
  resetFileViewerUi();
}

// Side-panel Git categories are UI labels; the read API uses its own allowlist.
const GIT_FILE_DIFF_CATEGORY_BY_PANEL = Object.freeze({
  staged: "staged",
  changes: "unstaged",
  conflicted: "conflicted",
  untracked: "untracked",
});

function gitFileDiffCategory(panelCategory = "") {
  return GIT_FILE_DIFF_CATEGORY_BY_PANEL[String(panelCategory || "").trim()] || "";
}

// The changes view is the bounded snapshot loaded when the file was opened;
// reopening the Git row refreshes it. Failures become a visible viewer state
// instead of a rejected open.
async function loadGitFileChangesSnapshot(repoRelPath, category, tabId) {
  const snapshot = { category, path: repoRelPath, label: "", command: "", diff: "", truncated: false, capBytes: 0, error: "" };
  try {
    const params = new URLSearchParams({ path: repoRelPath, category });
    const response = await api(`/api/git-file-diff?${params.toString()}`, { tabId });
    if (!response.ok) throw new Error(response.error || "Failed to load Git changes for this file");
    const data = response.data || {};
    return {
      ...snapshot,
      ...data,
      category,
      path: data.path || repoRelPath,
      diff: String(data.diff || ""),
      truncated: data.truncated === true,
      capBytes: Number(data.capBytes) || 0,
      contentError: data.error ? String(data.error) : "",
      error: "",
    };
  } catch (error) {
    return { ...snapshot, error: error.message || String(error) };
  }
}

function gitFileChangesPlaceholder(category, repoRelPath, requestSerial) {
  return { category, path: repoRelPath, label: "", command: "", diff: "", truncated: false, capBytes: 0, loading: true, requestSerial, error: "" };
}

async function applyGitFileChangesSnapshot(request, tabContext, viewerPath, requestSerial) {
  const snapshot = await request;
  const viewer = tabContext.tabId === activeTabId ? activeFileViewer : fileViewersByTab.get(tabContext.tabId);
  if (!viewer?.gitChanges?.loading || viewer.path !== viewerPath || viewer.gitChanges.requestSerial !== requestSerial) return;
  viewer.gitChanges = snapshot;
  if (viewer === activeFileViewer) updateFileViewerUi();
}

async function openFileInViewer(path = "", { gitCategory = "", gitPath = "" } = {}) {
  const normalized = normalizeFileTreePath(path);
  if (!normalized) return;
  if (activeFileViewer?.dirty && activeFileViewer.path !== normalized) {
    if (!(await confirmDiscardEdits({ what: "unsaved file edits", target: activeFileViewer.path }))) return;
  }
  const openRequestSerial = ++fileViewerOpenRequestSerial;
  const tabContext = activeTabContext();
  fileTreeState.selectedPath = normalized;
  renderFileTree();
  setFileViewerStatus(`Opening ${normalized}…`);
  const category = gitFileDiffCategory(gitCategory);
  const changesPath = normalizeFileTreePath(gitPath) || normalized;
  const changesRequestSerial = category ? ++fileViewerGitChangesRequestSerial : 0;
  const changesRequest = category ? loadGitFileChangesSnapshot(changesPath, category, tabContext.tabId) : null;
  try {
    const response = await api(fileApiPath("/api/files/content", normalized), { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext) || openRequestSerial !== fileViewerOpenRequestSerial) return;
    const data = response.data || {};
    const gitChanges = changesRequest ? gitFileChangesPlaceholder(category, changesPath, changesRequestSerial) : null;
    const kind = data.kind === "image" ? "image" : "text";
    const imageUrl = kind === "image" ? fileViewerImageDataUrl(data) : "";
    if (kind === "image" && !imageUrl) throw new Error("Image preview data is invalid or unsupported");
    activeFileViewer = {
      path: normalizeFileTreePath(data.path || normalized),
      name: data.name || fileDisplayName(normalized),
      content: kind === "text" ? String(data.content || "") : "",
      size: Number(data.size) || 0,
      mtimeMs: Number(data.mtimeMs) || 0,
      extension: data.extension || "",
      language: kind === "text" ? data.language || "text" : "image",
      kind,
      mimeType: kind === "image" ? String(data.mimeType || "") : "",
      imageUrl,
      mode: gitChanges ? "changes" : kind === "image" ? "image" : data.language === "markdown" ? "preview" : "source",
      dirty: false,
      readOnly: kind === "image",
      sourceAvailable: kind === "text",
      gitChanges,
    };
    if (elements.fileViewerEditor) elements.fileViewerEditor.value = activeFileViewer.content;
    clearFileViewerSelection();
    cacheActiveFileViewerForTab();
    updateFileViewerUi();
    setFileViewerStatus(kind === "image" ? "Image opened in WebUI (read-only)." : "Opened in WebUI.", "success");
    if (changesRequest) void applyGitFileChangesSnapshot(changesRequest, tabContext, activeFileViewer.path, changesRequestSerial);
  } catch (error) {
    const message = error.message || String(error);
    // A deleted tracked file has no live source but still has a diff worth showing.
    const gitChanges = changesRequest ? await changesRequest : null;
    if (!isCurrentTabContext(tabContext) || openRequestSerial !== fileViewerOpenRequestSerial) return;
    if (gitChanges && !gitChanges.error) {
      activeFileViewer = {
        path: normalized,
        name: fileDisplayName(normalized),
        content: "",
        size: 0,
        mtimeMs: 0,
        extension: fileExtensionForPath(normalized),
        language: fileLanguageForPath(normalized),
        mode: "changes",
        dirty: false,
        readOnly: true,
        sourceAvailable: false,
        gitChanges,
      };
      if (elements.fileViewerEditor) elements.fileViewerEditor.value = "";
      clearFileViewerSelection();
      cacheActiveFileViewerForTab();
      updateFileViewerUi();
      setFileViewerStatus("File content unavailable; showing Git changes (read-only).", "warn");
      return;
    }
    setFileViewerStatus(message, "error");
    addEvent(`file open failed: ${message}`, "error");
  }
}

async function openAurReviewReportInViewer(path = "", repoRoot = "") {
  const normalized = aurReviewSafePath(path);
  const expectedRepoRoot = String(repoRoot || "");
  if (!normalized || !expectedRepoRoot) return;
  const tabContext = activeTabContext();
  setFileViewerStatus(`Opening ${normalized}…`);
  try {
    const params = new URLSearchParams({ path: normalized, repoRoot: expectedRepoRoot });
    const response = await api(`/api/aur-review/report-content?${params.toString()}`, { tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    const data = response.data || {};
    activeFileViewer = {
      path: normalizeFileTreePath(data.path || normalized),
      name: data.name || fileDisplayName(normalized),
      content: String(data.content || ""),
      size: Number(data.size) || 0,
      mtimeMs: Number(data.mtimeMs) || 0,
      extension: data.extension || "",
      language: data.language || "text",
      mode: data.language === "markdown" ? "preview" : "source",
      dirty: false,
      readOnly: true,
    };
    if (elements.fileViewerEditor) elements.fileViewerEditor.value = activeFileViewer.content;
    clearFileViewerSelection();
    cacheActiveFileViewerForTab();
    updateFileViewerUi();
    setFileViewerStatus("Report opened in WebUI (read-only).", "success");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      setFileViewerStatus(error.message || String(error), "error");
      addEvent(`review report open failed: ${error.message || String(error)}`, "error");
    }
  }
}

async function saveActiveFileViewer() {
  if (!activeFileViewer || !elements.fileViewerEditor) return;
  if (activeFileViewer.readOnly) {
    setFileViewerStatus("This report is read-only.", "info");
    return;
  }
  const tabContext = activeTabContext();
  const content = elements.fileViewerEditor.value || "";
  if (elements.fileViewerSaveButton) elements.fileViewerSaveButton.disabled = true;
  setFileViewerStatus(`Saving ${activeFileViewer.path}…`);
  try {
    const response = await api("/api/files/content", { method: "POST", body: { path: activeFileViewer.path, content, mtimeMs: activeFileViewer.mtimeMs }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    const data = response.data || {};
    activeFileViewer = { ...activeFileViewer, ...data, path: normalizeFileTreePath(data.path || activeFileViewer.path), content, dirty: false };
    cacheActiveFileViewerForTab();
    updateFileViewerUi();
    await loadFileTreeDirectory(fileParentPath(activeFileViewer.path), { force: true });
    setFileViewerStatus("Saved.", "success");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) setFileViewerStatus(error.message || String(error), "error");
    if (activeFileViewer && elements.fileViewerSaveButton) elements.fileViewerSaveButton.disabled = false;
  }
}

function eventTargetsActiveTab(event) {
  return !event?.tabId || event.tabId === activeTabId;
}

function normalizeTabActivity(activity = {}) {
  const status = activity.status === "working" || activity.isWorking ? "working" : activity.status === "failed" ? "failed" : activity.status === "done" ? "done" : "idle";
  const completionSerial = Number(activity.completionSerial);
  return {
    ...activity,
    status,
    isWorking: status === "working",
    runStarted: activity.runStarted === true,
    completionSerial: Number.isFinite(completionSerial) ? completionSerial : 0,
  };
}

function normalizePendingExtensionUiRequestCount(value) {
  const count = Number(value);
  return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}

function tabPendingBlockerCount(tab) {
  return normalizePendingExtensionUiRequestCount(tab?.pendingExtensionUiRequestCount);
}

function setTabPendingBlockerCount(tabId, count) {
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  const previous = tabPendingBlockerCount(tab);
  const next = normalizePendingExtensionUiRequestCount(count);
  if (previous === next) return false;
  tab.pendingExtensionUiRequestCount = next;
  if (next === 0) clearBlockedTabNotificationKeys(tabId);
  return true;
}

function decrementTabPendingBlockerCount(tabId) {
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  return setTabPendingBlockerCount(tabId, Math.max(0, tabPendingBlockerCount(tab) - 1));
}

function tabActivityStateChanged(previous, next) {
  return !previous || previous.status !== next.status || previous.isWorking !== next.isWorking || previous.runStarted !== next.runStarted || previous.completionSerial !== next.completionSerial;
}

function setTabActivity(tabId, activity = {}) {
  if (!tabId) return null;
  const previous = tabActivities.get(tabId);
  const normalized = normalizeTabActivity(activity);
  if (promptRoutingTabs.has(tabId) && previous?.isWorking && !normalized.isWorking) return previous;
  tabActivities.set(tabId, normalized);
  if (!tabSeenCompletionSerials.has(tabId) || (previous && normalized.completionSerial < previous.completionSerial)) {
    tabSeenCompletionSerials.set(tabId, normalized.completionSerial);
  }
  return normalized;
}

function syncTabMetadata(nextTabs = []) {
  const liveIds = new Set();
  for (const tab of nextTabs) {
    if (!tab?.id) continue;
    liveIds.add(tab.id);
    setTabActivity(tab.id, tab.activity);
    if (Object.prototype.hasOwnProperty.call(tab, "appRunner")) setAppRunnerData(tab.id, { activeRun: tab.appRunner });
    if (Object.prototype.hasOwnProperty.call(tab, "conversationMode")) updateConversationModeForTab(tab.id, tab.conversationMode, { render: false });
    if (tab.sessionSummary) updateSessionSummaryForTab(tab.id, tab.sessionSummary);
  }
  for (const tabId of tabActivities.keys()) {
    if (!liveIds.has(tabId)) {
      tabActivities.delete(tabId);
      tabSeenCompletionSerials.delete(tabId);
      autoRetryingTabs.delete(tabId);
      suppressPendingAgentDoneNotificationsForTab(tabId, { markSeen: false });
      actionFeedbackByTab.delete(tabId);
      skillUsageByTab.delete(tabId);
      clearFeatureDecisionStateForTab(tabId);
      tabMessagesCache.delete(tabId);
      widgetsByTab.delete(tabId);
      appRunnerDataByTab.delete(tabId);
      conversationModeByTab.delete(tabId);
      workflowModeByTab.delete(tabId);
      workflowModeTogglePendingByTab.delete(tabId);
      workflowInspectorByTab.delete(tabId);
      workflowInspectorSelectionByTab.delete(tabId);
      workflowInspectorMinimizedByTab.delete(tabId);
      workflowSubprocessMinimizedByTab.delete(tabId);
      workflowOverlayMinimizedByTab.delete(tabId);
      compactThinkingDisclosureStateByTab.delete(tabId);
      remoteMicConsentTabs.delete(tabId);
      if (voiceConversationTabId === tabId) stopVoiceConversationLoop();
      clearGitWorkflowForTab(tabId);
      commandCatalogsByTab.delete(tabId);
      tabStateCache.delete(tabId);
      tabStatsCache.delete(tabId);
      tabWorkspaceCache.delete(tabId);
      sessionSummaryByTab.delete(tabId);
      if (sessionSummaryOverlayTabId === tabId) closeSessionSummaryOverlay({ restoreFocus: false });
      clearGitFooterPayloadState(tabId);
      gitFooterPayloadRequestSerialByTab.delete(tabId);
    }
  }
  for (const tabId of tabMessagesCache.keys()) {
    if (!liveIds.has(tabId)) tabMessagesCache.delete(tabId);
  }
  pruneSkillUsageForKnownTabs(liveIds);
}

function applyTabMetadata(tab) {
  if (!tab?.id) return false;
  const index = tabs.findIndex((item) => item.id === tab.id);
  if (index === -1) tabs.push(tab);
  else tabs[index] = { ...tabs[index], ...tab };
  if (tab.activity) setTabActivity(tab.id, tab.activity);
  if (Object.prototype.hasOwnProperty.call(tab, "conversationMode")) updateConversationModeForTab(tab.id, tab.conversationMode, { render: false });
  if (tab.sessionSummary) updateSessionSummaryForTab(tab.id, tab.sessionSummary);
  renderConversationModeControls();
  renderWorkflowModeControls();
  renderSessionSummaryControls();
  renderTabs();
  return true;
}

function applyResponseTab(response) {
  return applyTabMetadata(response?.tab || response?.data?.tab);
}

function syncResponseTabs(response) {
  const payload = response?.data || {};
  if (Array.isArray(payload.tabs)) {
    tabs = payload.tabs;
    syncTabMetadata(tabs);
  }
  const tab = response?.tab || payload.tab || null;
  if (tab) applyTabMetadata(tab);
  return tab;
}

async function switchToResponseTab(response) {
  const tab = syncResponseTabs(response);
  if (tab?.id) await switchTab(tab.id);
  return tab;
}

function activityForTab(tab) {
  if (!tab?.id) return normalizeTabActivity();
  return tabActivities.get(tab.id) || setTabActivity(tab.id, tab.activity) || normalizeTabActivity();
}

function tabIndicator(tab) {
  const activity = activityForTab(tab);
  const pendingBlockerCount = tabPendingBlockerCount(tab);
  if (tab?.running && pendingBlockerCount > 0) {
    return {
      state: "blocked",
      label: pendingBlockerCount === 1 ? "Blocked waiting for response" : `Blocked waiting on ${pendingBlockerCount} responses`,
      meta: pendingBlockerCount === 1 ? "blocked" : `blocked · ${pendingBlockerCount}`,
      glyph: "!",
    };
  }
  if (tab?.running && activity.isWorking) {
    return { state: "working", label: "Working", meta: "working", glyph: "●" };
  }
  const seenSerial = tabSeenCompletionSerials.get(tab?.id) ?? activity.completionSerial;
  if (tab?.running && activity.completionSerial > seenSerial) {
    return { state: "done", label: "Work done", meta: "done", glyph: "◆" };
  }
  return { state: "idle", label: tab?.running ? "Idle" : "Stopped", meta: tab?.running ? "idle" : "stopped", glyph: "○" };
}

function hasWorkingTab() {
  return tabs.some((tab) => ["working", "blocked"].includes(tabIndicator(tab).state) || tabAppRunnerRunningRun(tab));
}

function scheduleRefreshTabs(delay = 1500) {
  clearTimeout(refreshTabsTimer);
  refreshTabsTimer = setTimeout(() => {
    refreshTabsTimer = null;
    if (openTerminalTabGroupKey) {
      scheduleRefreshTabs(600);
      return;
    }
    refreshTabs().catch((error) => addEvent(error.message, "error"));
  }, delay);
}

function syncTabPolling() {
  if (hasWorkingTab()) {
    if (!refreshTabsTimer) scheduleRefreshTabs();
  } else {
    clearTimeout(refreshTabsTimer);
    refreshTabsTimer = null;
  }
}

function markTabWorkingLocally(tabId = activeTabId, { runStarted = false } = {}) {
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  suppressPendingAgentDoneNotificationsForTab(tabId);
  const previous = activityForTab(tab);
  const timestamp = new Date().toISOString();
  const next = normalizeTabActivity({
    ...previous,
    status: "working",
    isWorking: true,
    runStarted: previous.runStarted === true || runStarted === true,
    lastStartedAt: timestamp,
    lastChangedAt: timestamp,
  });
  tabActivities.set(tabId, next);
  if (tabActivityStateChanged(previous, next)) scheduleTabsRender();
  return true;
}

function markTabIdleLocally(tabId = activeTabId) {
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  const previous = activityForTab(tab);
  const next = normalizeTabActivity({ ...previous, status: "idle", isWorking: false, runStarted: false });
  tabActivities.set(tabId, next);
  if (tabActivityStateChanged(previous, next)) scheduleTabsRender();
  return true;
}

function markTabDoneLocally(tabId = activeTabId) {
  if (promptRoutingTabs.has(tabId)) return false;
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  const previous = activityForTab(tab);
  if (!previous.runStarted) return markTabIdleLocally(tabId);
  const next = normalizeTabActivity({
    ...previous,
    status: "done",
    isWorking: false,
    runStarted: false,
    completionSerial: (Number(previous.completionSerial) || 0) + 1,
    lastCompletedAt: new Date().toISOString(),
  });
  tabActivities.set(tabId, next);
  if (tabActivityStateChanged(previous, next)) scheduleTabsRender();
  return true;
}

function tabActivityRecentlyStarted(activity, nowMs = Date.now()) {
  const startedMs = Date.parse(activity?.lastStartedAt || activity?.lastChangedAt || "");
  return Number.isFinite(startedMs) && nowMs - startedMs < TAB_ACTIVITY_IDLE_RECONCILE_GRACE_MS;
}

function stateHasVisibleWork(state) {
  return !!state?.isStreaming || !!state?.isCompacting || Number(state?.pendingMessageCount || 0) > 0;
}

function syncActiveTabActivityFromState(state = currentState) {
  const tab = activeTab();
  if (!tab || !state || typeof state !== "object") return false;
  const activity = activityForTab(tab);
  if (tabPendingBlockerCount(tab) > 0) {
    if (!activity.isWorking) return markTabWorkingLocally(tab.id);
    return false;
  }
  if (stateHasVisibleWork(state)) {
    if (state.isStreaming) promptRoutingTabs.delete(tab.id);
    if (!activity.isWorking || (state.isStreaming && !activity.runStarted)) {
      return markTabWorkingLocally(tab.id, { runStarted: state.isStreaming === true });
    }
    return false;
  }
  if (activity.isWorking && !tabActivityRecentlyStarted(activity)) return markTabDoneLocally(tab.id);
  return false;
}

function markTabOutputSeen(tabId = activeTabId, { force = false } = {}) {
  if (!tabId) return false;
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return false;
  const activity = activityForTab(tab);
  if (activity.isWorking) return false;
  if (!force && tabId === activeTabId && !(autoFollowChat || isChatNearBottom())) return false;
  const completionSerial = activity.completionSerial || 0;
  const previousSerial = tabSeenCompletionSerials.get(tabId) ?? 0;
  if (previousSerial >= completionSerial) return false;
  tabSeenCompletionSerials.set(tabId, completionSerial);
  scheduleTabsRender();
  return true;
}

function ingestEventTabActivity(event) {
  if (!event?.tabId) return;
  const tab = tabs.find((item) => item.id === event.tabId);
  let changed = false;
  if (tab && event.tabTitle && tab.title !== event.tabTitle) {
    tab.title = event.tabTitle;
    changed = true;
  }
  if (Object.prototype.hasOwnProperty.call(event, "pendingExtensionUiRequestCount")) {
    changed = setTabPendingBlockerCount(event.tabId, event.pendingExtensionUiRequestCount) || changed;
  }
  if (event.tabActivity) {
    const previous = tabActivities.get(event.tabId);
    const next = setTabActivity(event.tabId, event.tabActivity);
    changed = tabActivityStateChanged(previous, next) || changed;
  }
  if (changed) scheduleTabsRender();
}

function eventHasTabActivityPayload(event) {
  return !!(
    event?.tabId &&
    (event.tabTitle || event.tabActivity || Object.prototype.hasOwnProperty.call(event, "pendingExtensionUiRequestCount"))
  );
}

function trackAutoRetryStateFromEvent(event) {
  const tabId = event?.tabId || activeTabId;
  if (!tabId) return;
  if (event.type === "auto_retry_start") {
    autoRetryingTabs.add(tabId);
    suppressPendingAgentDoneNotificationsForTab(tabId);
    markTabWorkingLocally(tabId);
  } else if (event.type === "auto_retry_end") {
    autoRetryingTabs.delete(tabId);
  }
}

function rememberActiveTab() {
  if (embeddedSplitMode) return;
  try {
    if (activeTabId) localStorage.setItem(TAB_STORAGE_KEY, activeTabId);
  } catch {
    // Ignore storage failures; tabs still work for this page load.
  }
}

function restoreStoredTabId() {
  try {
    return localStorage.getItem(TAB_STORAGE_KEY) || null;
  } catch {
    return null;
  }
}

function requestedTabIdFromUrl() {
  try {
    const params = new URLSearchParams(window.location.search);
    return params.get("tab") || params.get("tabId") || null;
  } catch {
    return null;
  }
}

function updateDocumentTitle() {
  const subagentView = activeSubagentTerminalView();
  if (subagentView) {
    document.title = `Pi Web UI · ${subagentTerminalViewTitle(subagentView)} · Subagent`;
    return;
  }
  const tab = activeTab();
  document.title = tab ? `Pi Web UI · ${tab.title}` : "Pi Web UI";
}

function saveActiveDraft() {
  if (activeTabId) tabDrafts.set(activeTabId, elements.promptInput.value || "");
  persistMobileContinuityState();
  persistDesktopDrafts();
}

function restoreActiveDraft() {
  resetPromptHistoryNavigation();
  elements.promptInput.value = activeTabId ? tabDrafts.get(activeTabId) || "" : "";
  resizePromptInput();
  renderCommandSuggestions();
  renderAttachmentTray();
}

function focusPromptInput({ defer = false } = {}) {
  const focus = () => {
    if (activeSubagentTerminalId || !elements.promptInput || elements.dialog.open || elements.issueWizardDialog?.open || elements.pathPickerDialog.open || elements.gitChangesDialog?.open || elements.commandPaletteDialog?.open || elements.editRetryDialog?.open || elements.nativeCommandDialog.open || elements.remoteQrDialog?.open || elements.appRunnerInfoDialog?.open || elements.gitFooterVisibilityDialog?.open || elements.statsOverlayDialog?.open || elements.promptListDialog?.open || elements.attachmentTextDialog?.open || elements.skillEditorDialog?.open || document.visibilityState === "hidden") return;
    try {
      elements.promptInput.focus({ preventScroll: true });
    } catch {
      elements.promptInput.focus();
    }
    syncMobileChatToBottomForInput();
    setTimeout(updateVisualViewportVars, 0);
  };
  if (defer) requestAnimationFrame(focus);
  else focus();
}

function clearRefreshTimers() {
  clearTimeout(refreshMessagesTimer);
  clearTimeout(refreshStateTimer);
  clearTimeout(refreshFooterTimer);
  refreshMessagesTimer = null;
  refreshStateTimer = null;
  refreshFooterTimer = null;
}

function cancelPendingDialogs() {
  const pending = activeDialog ? [activeDialog] : [];
  pending.push(...dialogQueue.splice(0));
  for (const request of pending) {
    if (!request?.id || !EXTENSION_UI_BLOCKING_METHODS.has(request.method)) continue;
    api("/api/extension-ui-response", {
      method: "POST",
      body: { type: "extension_ui_response", id: request.id, cancelled: true },
      tabId: request.tabId || activeTabId,
    }).catch((error) => console.warn("failed to cancel stale extension dialog", error));
  }
  activeDialog = null;
  activeDialogCancel = null;
  if (elements.dialog.open) elements.dialog.close();
}

function widgetCacheForTab(tabId = activeTabId, { create = true } = {}) {
  if (!tabId) return null;
  let cache = widgetsByTab.get(tabId);
  if (!cache && create) {
    cache = new Map();
    widgetsByTab.set(tabId, cache);
  }
  return cache || null;
}

function cacheWidgetsForTab(tabId = activeTabId) {
  if (!tabId) return;
  if (widgets.size === 0) {
    widgetsByTab.delete(tabId);
    return;
  }
  widgetsByTab.set(tabId, new Map(widgets));
}

function restoreWidgetsForActiveTab() {
  widgets.clear();
  const cache = widgetCacheForTab(activeTabId, { create: false });
  if (!cache) return;
  for (const [key, value] of cache) widgets.set(key, value);
}

function todoProgressSignatureFromLines(lines = []) {
  const parsed = parseTodoProgressWidget(lines);
  if (!parsed) return JSON.stringify(lines.map(stripAnsi));
  return JSON.stringify({ goal: parsed.goal, done: parsed.done, total: parsed.total, partial: parsed.partial, items: parsed.items, footer: parsed.footer });
}

function rememberTodoProgressGoalForTab(tabId, widgetKey, request) {
  if (widgetKey !== "todo-progress" || !tabId) return;
  if (!Array.isArray(request?.widgetLines)) {
    todoProgressGoalByTab.delete(tabId);
    todoProgressSignatureByTab.delete(tabId);
    return;
  }
  const parsed = parseTodoProgressWidget(request.widgetLines);
  if (parsed?.goal) todoProgressGoalByTab.set(tabId, parsed.goal);
  todoProgressSignatureByTab.set(tabId, todoProgressSignatureFromLines(request.widgetLines));
}

function widgetRequestEquivalent(a, b) {
  const aHasLines = Array.isArray(a?.widgetLines);
  const bHasLines = Array.isArray(b?.widgetLines);
  if (aHasLines !== bHasLines) return false;
  if (!aHasLines) return true;
  if (a.widgetLines.length !== b.widgetLines.length) return false;
  return a.widgetLines.every((line, index) => String(line) === String(b.widgetLines[index]));
}

function setWidgetForTab(tabId, widgetKey, request) {
  if (!widgetKey) return false;
  const targetTabId = tabId || activeTabId;
  const cache = widgetCacheForTab(targetTabId);
  const hasLines = Array.isArray(request?.widgetLines);
  const current = cache?.get(widgetKey) || (targetTabId === activeTabId ? widgets.get(widgetKey) : undefined);
  if (widgetRequestEquivalent(current, request)) return false;

  rememberTodoProgressGoalForTab(targetTabId, widgetKey, request);

  if (cache) {
    if (hasLines) cache.set(widgetKey, request);
    else cache.delete(widgetKey);
    if (cache.size === 0) widgetsByTab.delete(targetTabId);
  }

  if (targetTabId === activeTabId) {
    if (hasLines) widgets.set(widgetKey, request);
    else widgets.delete(widgetKey);
    // Native audio starting/stopping must immediately re-arbitrate which
    // voice loop (native vs. browser Web Speech) owns this conversation.
    if (widgetKey === "natural-conversation-audio") queueMicrotask(() => renderConversationModeControls());
  }

  return true;
}

function clearWidgetsForTab(tabId = activeTabId) {
  if (tabId) {
    widgetsByTab.delete(tabId);
    todoProgressGoalByTab.delete(tabId);
    todoProgressSignatureByTab.delete(tabId);
  }
  if (!tabId || tabId === activeTabId) widgets.clear();
  if (!tabId) {
    todoProgressGoalByTab.clear();
    todoProgressSignatureByTab.clear();
  }
}

function cachedStateForTabSwitch(tabId = activeTabId) {
  if (!tabId) return null;
  const cached = tabStateCache.get(tabId) || null;
  const activity = tabActivities.get(tabId);
  if (!activity) return cached;
  const isWorking = activity.isWorking === true;
  return {
    ...(cached || {}),
    isStreaming: isWorking,
    isCompacting: isWorking && cached?.isCompacting === true,
  };
}

function resetActiveTabUi() {
  clearRefreshTimers();
  eventSource?.close();
  eventSource = null;
  setControlsPendingModel("");
  setControlsPendingThinking("");
  currentState = cachedStateForTabSwitch(activeTabId);
  latestStats = activeTabId ? tabStatsCache.get(activeTabId) || null : null;
  latestStatsOverlayPayload = null;
  latestBtwWidgetPayload = null;
  btwWidgetComposerOpen = false;
  btwWidgetInputDraft = "";
  latestWorkspace = activeTabId ? tabWorkspaceCache.get(activeTabId) || null : null;
  latestMessages = [];
  latestMessagesSessionKey = "";
  resetFileViewerUi();
  resetFileTreeState();
  restoreFileViewerForActiveTab();
  clearRunIndicatorActivity({ render: false });
  if (currentState) syncRunIndicatorFromState(currentState);
  statusEntries.clear();
  restoreWidgetsForActiveTab();
  transientMessages = [];
  liveToolRuns.clear();
  liveToolCards.clear();
  const commandCatalog = commandCatalogsByTab.get(activeTabId);
  availableCommands = commandCatalog?.available || [];
  rawAvailableCommands = commandCatalog?.raw || [];
  resetOptionalFeatureAvailability();
  if (commandCatalog) updateOptionalFeatureAvailability();
  commandSuggestions = [];
  pathSuggestions = [];
  suggestionMode = "none";
  commandSuggestIndex = 0;
  resetStreamBubble();
  removeRunIndicatorBubble();
  hideCommandSuggestions();
  cancelPendingDialogs();
  if (elements.nativeCommandDialog.open) closeNativeCommandDialog();
  if (elements.gitFooterVisibilityDialog?.open) closeGitFooterVisibilityDialog();
  if (pathPickerState) closePathPicker(null);
  bindGitWorkflowToActiveTab();
  resetChatOutput();
  elements.stateDetails.replaceChildren();
  closeEventTreeContextMenu({ returnFocus: false });
  toolEventStartedAt.clear();
  elements.eventLog.replaceChildren();
  const queuedSnapshot = activeTabId ? latestQueuedMessagesByTab.get(activeTabId) : null;
  if (queuedSnapshot) renderQueue({ tabId: activeTabId, ...queuedSnapshot });
  else renderQueue({ tabId: activeTabId, steering: [], followUp: [] });
  elements.commandsBox.textContent = "Loading…";
  elements.commandsBox.classList.add("muted");
  renderAppRunnerControls();
  renderWidgets();
  renderGitWorkflow();
  // renderMessages() is transcript-only, so tab-level chrome is rendered here
  // explicitly whether or not a cached transcript was restored.
  restoreCachedMessagesForActiveTab();
  renderFooter();
  renderFeedbackTray();
  restoreComposerActionSlotLayout();
}

function tabGroupStatusRank(state) {
  const index = TAB_GROUP_STATUS_PRIORITY.indexOf(state);
  return index === -1 ? TAB_GROUP_STATUS_PRIORITY.indexOf("idle") : index;
}

function tabGroupIndicator(groupTabs) {
  let selected = null;
  let selectedRank = Number.POSITIVE_INFINITY;
  for (const tab of groupTabs) {
    const indicator = tabIndicator(tab);
    const rank = tabGroupStatusRank(indicator.state);
    if (rank < selectedRank) {
      selected = indicator;
      selectedRank = rank;
    }
  }
  return selected || { state: "idle", label: "Idle", meta: "idle", glyph: "○" };
}

function tabCwdGroupKey(tab) {
  const cwd = String(tab?.cwd || "");
  return cwd ? `cwd:${cwd}` : `tab:${tab?.id || "unknown"}`;
}

function tabCwdGroups() {
  syncTerminalCustomGroupsWithTabs(tabs);
  const groups = [];
  const byKey = new Map();
  const customByTab = terminalCustomGroupByTabId();
  const customGroups = new Map([...terminalCustomGroups.values()].map((group) => [group.id, {
    key: `custom:${group.id}`,
    custom: true,
    customGroupId: group.id,
    title: normalizeTerminalCustomGroupTitle(group.title),
    tabs: [],
    cwd: "",
  }]));

  for (const tab of tabs) {
    const customGroupId = customByTab.get(tab.id);
    if (customGroupId) customGroups.get(customGroupId)?.tabs.push(tab);
  }

  const emittedCustomGroups = new Set();
  for (const tab of tabs) {
    const customGroupId = customByTab.get(tab.id);
    if (customGroupId) {
      const customGroup = customGroups.get(customGroupId);
      if (customGroup && !emittedCustomGroups.has(customGroupId)) {
        groups.push(customGroup);
        emittedCustomGroups.add(customGroupId);
      }
      continue;
    }
    const key = tabCwdGroupKey(tab);
    let group = byKey.get(key);
    if (!group) {
      group = { key, custom: false, cwd: tab.cwd || "", tabs: [] };
      byKey.set(key, group);
      groups.push(group);
    }
    group.tabs.push(tab);
  }
  return groups;
}

function tabGroupTitle(cwd, fallback = "cwd") {
  const normalized = normalizeDisplayPath(cwd).replace(/\/+$/, "");
  const leaf = normalized.split("/").filter(Boolean).pop() || normalized || fallback;
  return leaf.length > 26 ? `…${leaf.slice(-25)}` : leaf;
}

function terminalDisplayGroupTitle(group, fallback = "group") {
  return group?.custom ? normalizeTerminalCustomGroupTitle(group.title, "Custom group") : tabGroupTitle(group?.cwd, fallback);
}

function terminalDisplayGroupDetail(group, fallback = "group") {
  if (!group?.custom) return normalizeDisplayPath(group?.cwd || fallback);
  const cwdLabels = [...new Set((group.tabs || []).map((tab) => normalizeDisplayPath(tab.cwd || "")).filter(Boolean))];
  if (!cwdLabels.length) return "custom group";
  if (cwdLabels.length === 1) return cwdLabels[0];
  return `${cwdLabels[0]} + ${cwdLabels.length - 1} cwd${cwdLabels.length === 2 ? "" : "s"}`;
}

function gitPanelSectionExpanded() {
  const section = elements.sidePanel?.querySelector('[data-side-panel-section="git"]');
  return Boolean(section && !section.hidden && !section.classList.contains("collapsed"));
}

function gitPanelTerminalGroups() {
  const cwdGroups = tabCwdGroups();
  const groups = [];
  for (const group of cwdGroups) {
    if (shouldRenderTerminalTabGroup(group, cwdGroups.length)) {
      groups.push({ ...group, title: terminalDisplayGroupTitle(group), detail: terminalDisplayGroupDetail(group) });
      continue;
    }
    for (const tab of group.tabs || []) {
      groups.push({
        key: `tab:${tab.id}`,
        custom: false,
        cwd: tab.cwd || "",
        tabs: [tab],
        title: tabGroupTitle(tab.cwd, "Working directory"),
        detail: normalizeDisplayPath(tab.cwd || ""),
      });
    }
  }
  return groups;
}

function gitPanelCandidates(groups = gitPanelTerminalGroups()) {
  const byCwd = new Map();
  for (const group of groups) {
    for (const tab of group.tabs || []) {
      const cwd = String(tab.cwd || "").trim();
      if (!cwd || byCwd.has(cwd)) continue;
      byCwd.set(cwd, {
        key: `cwd:${cwd}`,
        cwd,
        tabId: tab.id,
        tabTitle: tabGroupTitle(cwd, "Working directory"),
      });
    }
  }
  return [...byCwd.values()];
}

function gitPanelRepositoryCards(groups = gitPanelTerminalGroups()) {
  const byIdentity = new Map();
  for (const candidate of gitPanelCandidates(groups)) {
    const discovery = gitPanelState.discovery.get(candidate.key);
    const root = String(discovery?.root || "");
    const identity = root ? `root:${root}` : candidate.key;
    let card = byIdentity.get(identity);
    if (!card) {
      card = {
        key: identity,
        root,
        cwd: candidate.cwd,
        tabId: candidate.tabId,
        candidates: [],
        discovery,
      };
      byIdentity.set(identity, card);
    }
    card.candidates.push(candidate);
    if (!card.discovery && discovery) card.discovery = discovery;
  }
  return [...byIdentity.values()];
}

function gitPanelRootLabel(root, fallback = "Repository") {
  const normalized = normalizeDisplayPath(root || "").replace(/\/+$/, "");
  return normalized.split("/").filter(Boolean).pop() || normalized || fallback;
}

function gitPanelSnapshot(root) {
  return root ? gitPanelState.repositories.get(root) || null : null;
}

function gitPanelSnapshotFresh(snapshot) {
  return Boolean(snapshot?.data && Date.now() - Number(snapshot.loadedAt || 0) < GIT_PANEL_CACHE_MAX_AGE_MS);
}

async function discoverGitPanelCandidate(candidate, { force = false } = {}) {
  const current = gitPanelState.discovery.get(candidate.key);
  if (current?.loading || (!force && (current?.root || current?.resolved))) return;
  const requestSerial = ++gitPanelState.requestSerial;
  gitPanelState.discovery.set(candidate.key, { loading: true, resolved: false, requestSerial, root: "", error: "" });
  renderGitPanel();
  try {
    const response = await api("/api/git-root", { tabId: candidate.tabId });
    const latest = gitPanelState.discovery.get(candidate.key);
    if (latest?.requestSerial !== requestSerial) return;
    if (!response.ok || !response.data?.root) throw new Error(response.error || "Not a Git repository");
    gitPanelState.discovery.set(candidate.key, { loading: false, resolved: true, requestSerial, checkedAt: Date.now(), root: response.data.root, error: "" });
  } catch (error) {
    const latest = gitPanelState.discovery.get(candidate.key);
    if (latest?.requestSerial !== requestSerial) return;
    gitPanelState.discovery.set(candidate.key, { loading: false, resolved: true, requestSerial, checkedAt: Date.now(), root: "", error: error.message || String(error) });
  }
  renderGitPanel();
}

function ensureGitPanelRepositoriesDiscovered({ retryUnavailable = false } = {}) {
  if (!gitPanelSectionExpanded()) return;
  for (const candidate of gitPanelCandidates()) {
    const discovery = gitPanelState.discovery.get(candidate.key);
    if (!discovery || (!discovery.loading && !discovery.resolved)) {
      void discoverGitPanelCandidate(candidate);
    } else if (retryUnavailable && !discovery.loading && !discovery.root) {
      void discoverGitPanelCandidate(candidate, { force: true });
    }
  }
}

async function loadGitPanelRepository(card, { force = false } = {}) {
  if (!card?.root || !card.tabId) return;
  const existing = gitPanelSnapshot(card.root);
  if (!force && gitPanelSnapshotFresh(existing)) return;
  if (existing?.loading) {
    if (force && !existing.refreshPending) {
      gitPanelState.repositories.set(card.root, { ...existing, refreshPending: true });
    }
    return;
  }
  const requestSerial = ++gitPanelState.requestSerial;
  gitPanelState.repositories.set(card.root, { ...existing, loading: true, error: "", requestSerial, refreshPending: false });
  renderGitPanel();
  let refreshAgain = false;
  try {
    const response = await api("/api/git-panel", { tabId: card.tabId });
    const latest = gitPanelSnapshot(card.root);
    if (latest?.requestSerial !== requestSerial) return;
    refreshAgain = latest.refreshPending === true;
    if (!response.ok || !response.data?.root) throw new Error(response.error || "Failed to load Git repository");
    gitPanelState.repositories.set(card.root, {
      loading: false,
      error: "",
      requestSerial,
      loadedAt: Date.now(),
      refreshPending: false,
      data: response.data,
    });
  } catch (error) {
    const latest = gitPanelSnapshot(card.root);
    if (latest?.requestSerial !== requestSerial) return;
    refreshAgain = refreshAgain || latest.refreshPending === true;
    gitPanelState.repositories.set(card.root, {
      ...latest,
      loading: false,
      error: error.message || String(error),
      requestSerial,
      refreshPending: false,
    });
  }
  renderGitPanel();
  if (refreshAgain) queueMicrotask(() => loadGitPanelRepository(card, { force: true }));
}

function invalidateGitPanelRepository(root) {
  const repositoryRoot = String(root || "");
  const snapshot = gitPanelSnapshot(repositoryRoot);
  if (!snapshot) return;
  gitPanelState.repositories.set(repositoryRoot, {
    ...snapshot,
    error: "",
    loadedAt: 0,
    refreshPending: snapshot.loading === true,
  });
  if (!gitPanelSectionExpanded()) return;
  const card = gitPanelRepositoryCards().find((candidate) => candidate.root === repositoryRoot);
  if (card) void loadGitPanelRepository(card, { force: true });
}

function ensureGitPanelVisibleRepositoriesFresh(cards = gitPanelRepositoryCards()) {
  for (const card of cards) {
    const snapshot = gitPanelSnapshot(card.root);
    const expanded = gitPanelState.expandedCardKey === card.key;
    if (snapshot?.loading || snapshot?.error || (!snapshot?.data && !expanded) || gitPanelSnapshotFresh(snapshot)) continue;
    void loadGitPanelRepository(card);
  }
}

function toggleGitPanelRepository(card) {
  if (!card?.root) return;
  if (gitPanelState.expandedCardKey === card.key) {
    gitPanelState.expandedCardKey = "";
    renderGitPanel();
    return;
  }
  gitPanelState.expandedCardKey = card.key;
  renderGitPanel();
  const snapshot = gitPanelSnapshot(card.root);
  if (!gitPanelSnapshotFresh(snapshot)) void loadGitPanelRepository(card);
}

function gitPanelChangeCount(data) {
  return Array.isArray(data?.changes) ? data.changes.length : 0;
}

function gitPanelStatsText(entry = {}, category = "") {
  const prefix = category === "staged" ? "staged" : category === "changes" ? "unstaged" : "";
  const binary = prefix ? entry[`${prefix}Binary`] === true : entry.binary === true;
  if (binary) return "binary";
  const additions = Number(prefix ? entry[`${prefix}Additions`] : entry.additions || 0) || 0;
  const deletions = Number(prefix ? entry[`${prefix}Deletions`] : entry.deletions || 0) || 0;
  if (!additions && !deletions) return entry.untracked ? "new" : "";
  return `${additions ? `+${additions}` : "+0"} ${deletions ? `−${deletions}` : "−0"}`;
}

function gitPanelTree(entries = []) {
  const root = { name: "", path: "", folders: new Map(), files: [] };
  for (const entry of entries) {
    const parts = String(entry.path || "").split("/").filter(Boolean);
    if (!parts.length) continue;
    const fileName = parts.pop();
    let node = root;
    let currentPath = "";
    for (const part of parts) {
      currentPath = currentPath ? `${currentPath}/${part}` : part;
      if (!node.folders.has(part)) node.folders.set(part, { name: part, path: currentPath, folders: new Map(), files: [] });
      node = node.folders.get(part);
    }
    node.files.push({ ...entry, name: fileName });
  }
  return root;
}

function closeGitPanelContextMenu({ returnFocus = true } = {}) {
  const trigger = gitPanelContextMenuState?.trigger;
  gitPanelContextMenuState = null;
  if (elements.gitPanelContextMenu) elements.gitPanelContextMenu.hidden = true;
  if (returnFocus && trigger?.isConnected) queueMicrotask(() => trigger.focus({ preventScroll: true }));
}

function gitPanelContextMenuItems(context) {
  const { card, category = "", kind = "file", path = "" } = context || {};
  if (!card?.root) return [];
  if (kind === "repository") {
    const snapshot = gitPanelSnapshot(card.root);
    return [
      { label: "View Diff", run: () => openGitChangesDialog(card.tabId) },
      { label: snapshot?.loading ? "Refreshing…" : "Refresh", disabled: snapshot?.loading, run: () => loadGitPanelRepository(card, { force: true }) },
      { label: "Stage All", disabled: gitPanelActionBusy(card, "stage-all"), run: () => runGitPanelAction(card, "stage-all") },
      { label: "Unstage All", disabled: gitPanelActionBusy(card, "unstage-all"), run: () => runGitPanelAction(card, "unstage-all") },
    ];
  }
  const target = kind === "folder" ? "folder" : "file";
  const ignoreAction = target === "folder" ? "ignore-folder" : "ignore-file";
  const ignoreItem = { label: "Add to .gitignore", disabled: gitPanelActionBusy(card, ignoreAction, path), run: () => runGitPanelAction(card, ignoreAction, path) };
  if (category === "staged") {
    return [
      { label: `Unstage ${target}`, disabled: gitPanelActionBusy(card, "unstage", path), run: () => runGitPanelAction(card, "unstage", path) },
      ignoreItem,
    ];
  }
  const stageLabel = category === "conflicted" ? `Stage ${target} / mark resolved` : `Stage ${target}`;
  const items = [{ label: stageLabel, disabled: gitPanelActionBusy(card, "stage", path), run: () => runGitPanelAction(card, "stage", path) }, ignoreItem];
  if (kind === "file" && category === "changes") {
    items.push({ label: "Discard changes…", danger: true, disabled: gitPanelActionBusy(card, "discard", path), run: () => runGitPanelAction(card, "discard", path) });
  }
  if (kind === "file" && category === "untracked") {
    items.push({ label: "Delete file…", danger: true, disabled: gitPanelActionBusy(card, "delete", path), run: () => runGitPanelAction(card, "delete", path) });
  }
  return items;
}

function showGitPanelContextMenu(event, context) {
  if (!elements.gitPanelContextMenu) return;
  event.preventDefault();
  event.stopPropagation();
  closeFileContextMenu({ returnFocus: false });
  closeGitPanelContextMenu({ returnFocus: false });
  closeSidePanelContextMenu({ returnFocus: false });
  closeEventTreeContextMenu({ returnFocus: false });
  const menu = elements.gitPanelContextMenu;
  const items = gitPanelContextMenuItems(context);
  if (!items.length) return;
  const trigger = event.currentTarget || document.activeElement;
  gitPanelContextMenuState = { ...context, trigger };
  const labelText = context.kind === "repository" ? gitPanelRootLabel(context.card.root) : context.path;
  const label = make("div", "git-side-panel-context-label", labelText);
  const buttons = items.map((item) => {
    const button = make("button", item.danger ? "danger" : "", item.label);
    button.type = "button";
    button.setAttribute("role", "menuitem");
    button.disabled = Boolean(item.disabled);
    button.addEventListener("click", () => {
      closeGitPanelContextMenu();
      void item.run();
    });
    return button;
  });
  menu.replaceChildren(label, ...buttons);
  menu.hidden = false;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(event.clientX, Math.max(8, window.innerWidth - rect.width - 8));
  const top = Math.min(event.clientY, Math.max(8, window.innerHeight - rect.height - 8));
  menu.style.left = `${Math.max(8, left)}px`;
  menu.style.top = `${Math.max(8, top)}px`;
  menu.querySelector('[role="menuitem"]:not([disabled])')?.focus({ preventScroll: true });
}

// Touch- and keyboard-discoverable entry to the same actions as the right-click menu.
function gitPanelOverflowButton(context, label) {
  const button = make("button", "git-side-panel-overflow-button file-tree-overflow-button", "⋯");
  button.type = "button";
  button.setAttribute("aria-label", `Git actions for ${label}`);
  button.setAttribute("aria-haspopup", "menu");
  button.title = "Git actions";
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    const rect = button.getBoundingClientRect();
    showGitPanelContextMenu({
      preventDefault: () => event.preventDefault(),
      stopPropagation: () => event.stopPropagation(),
      clientX: rect.right,
      clientY: rect.bottom,
      currentTarget: button,
    }, context);
  });
  button.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") event.stopPropagation();
  });
  return button;
}

function bindGitPanelContextMenu(trigger, context) {
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.addEventListener("contextmenu", (event) => showGitPanelContextMenu(event, context));
  trigger.addEventListener("keydown", (event) => {
    if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return;
    const rect = trigger.getBoundingClientRect();
    showGitPanelContextMenu({
      preventDefault: () => event.preventDefault(),
      stopPropagation: () => event.stopPropagation(),
      clientX: rect.left + Math.min(rect.width, 24),
      clientY: rect.bottom,
      currentTarget: trigger,
    }, context);
  });
}

function gitPanelActionBusy(card, action, path = "") {
  return gitPanelState.busy.has(`${card.root}\u0000${action}\u0000${path}`);
}

async function runGitPanelAction(card, action, path = "") {
  const gitignoreAction = (kind) => ({
    url: "/api/git-changes/add-to-gitignore",
    body: { path, kind },
    done: (data) => `${data?.added
      ? `Added ${data?.entry || path} to .gitignore.`
      : `${data?.entry || path} is already in .gitignore.`} Tracked files stay tracked until removed from the index.`,
  });
  const config = {
    stage: { url: "/api/git-changes/stage-file", body: { path }, past: `Staged ${path}.` },
    unstage: { url: "/api/git-changes/unstage-file", body: { path }, past: `Unstaged ${path}.` },
    "stage-all": { url: "/api/git-changes/stage-all", body: {}, past: `Staged all changes in ${card.root}.` },
    "unstage-all": { url: "/api/git-changes/unstage-all", body: {}, past: `Unstaged all changes in ${card.root}.` },
    discard: {
      url: "/api/git-changes/discard-file",
      body: { path, confirmed: true },
      past: `Discarded tracked changes in ${path}.`,
      confirm: `Discard tracked working-tree changes in ${path}?\n\nRepository: ${card.root}\nCommand: git restore -- ${path}\n\nThis permanently reverts unstaged edits to this path.`,
      confirmLabel: "Discard changes",
    },
    delete: {
      url: "/api/git-changes/delete-untracked",
      body: { path, confirmed: true },
      past: `Deleted untracked file ${path}.`,
      confirm: `Delete untracked file ${path}?\n\nRepository: ${card.root}\n\nThis permanently removes the file from disk.`,
      confirmLabel: "Delete file",
    },
    "ignore-file": gitignoreAction("file"),
    "ignore-folder": gitignoreAction("folder"),
  }[action];
  if (!config || !card?.root || !card.tabId) return;
  if (config.confirm && !(await appConfirmText(config.confirm, { affected: path || card.root, confirmLabel: config.confirmLabel }))) return;
  const busyKey = `${card.root}\u0000${action}\u0000${path}`;
  if (gitPanelState.busy.has(busyKey)) return;
  gitPanelState.busy.add(busyKey);
  renderGitPanel();
  try {
    const response = await api(config.url, { method: "POST", body: config.body, tabId: card.tabId });
    if (!response.ok) throw new Error([response.error, response.hint].filter(Boolean).join("\n") || `Git ${action} failed`);
    addEvent(typeof config.done === "function" ? config.done(response.data) : config.past, "success");
    await loadGitPanelRepository(card, { force: true });
    requestGitFooterWebuiPayload({ tabId: card.tabId }, { force: true });
  } catch (error) {
    addEvent(error.message || String(error), "error");
    const snapshot = gitPanelSnapshot(card.root);
    gitPanelState.repositories.set(card.root, { ...snapshot, error: error.message || String(error), loading: false });
  } finally {
    gitPanelState.busy.delete(busyKey);
    renderGitPanel();
  }
}

function renderGitPanelFolder(node, card, category, depth = 0) {
  const details = make("details", "git-side-panel-folder");
  const folderKey = `${card.root}\u0000${category}\u0000${node.path}`;
  const defaultOpen = true;
  details.open = gitPanelState.openFolders.has(folderKey) ? gitPanelState.openFolders.get(folderKey) : defaultOpen;
  details.addEventListener("toggle", () => {
    if (details.open === defaultOpen) gitPanelState.openFolders.delete(folderKey);
    else gitPanelState.openFolders.set(folderKey, details.open);
  });
  const summary = make("summary", "git-side-panel-folder-summary");
  summary.dataset.gitPanelContinuityKey = `folder:${card.root}:${category}:${node.path}`;
  summary.title = `${node.path} · Right-click for Git actions`;
  const chevron = make("span", "git-side-panel-folder-chevron", "›");
  chevron.setAttribute("aria-hidden", "true");
  summary.append(chevron, make("span", "git-side-panel-folder-name", node.name));
  const folderEntries = [];
  const collect = (current) => {
    folderEntries.push(...current.files);
    for (const child of current.folders.values()) collect(child);
  };
  collect(node);
  summary.append(make("span", "git-side-panel-folder-count", String(folderEntries.length)));
  bindGitPanelContextMenu(summary, { card, category, kind: "folder", path: node.path });
  details.append(summary);
  const body = make("div", "git-side-panel-folder-body");
  for (const child of [...node.folders.values()].sort((a, b) => a.name.localeCompare(b.name))) body.append(renderGitPanelFolder(child, card, category, depth + 1));
  for (const file of [...node.files].sort((a, b) => a.name.localeCompare(b.name))) body.append(renderGitPanelFile(file, card, category));
  details.append(body);
  return details;
}

function renderGitPanelFile(entry, card, category) {
  const row = make("div", `git-side-panel-file ${category}`);
  row.dataset.gitPanelContinuityKey = `file:${card.root}:${category}:${entry.path}`;
  const fullPath = entry.oldPath ? `${entry.oldPath} → ${entry.path}` : entry.path;
  row.title = `${fullPath} · Open in WebUI · ⋯ or right-click for Git actions`;
  row.tabIndex = 0;
  row.setAttribute("role", "button");
  row.setAttribute("aria-label", `Open ${entry.name || entry.path} in WebUI, ${gitPanelStatsText(entry, category) || "no line statistics"}`);
  const open = () => openGitFileInViewer(entry.path, { root: card.root, candidates: card.candidates, category })
    .catch((error) => addEvent(error.message || String(error), "error"));
  row.addEventListener("click", open);
  row.addEventListener("keydown", (event) => {
    if (event.repeat || (event.key !== "Enter" && event.key !== " ")) return;
    event.preventDefault();
    open();
  });
  const status = make("span", "git-side-panel-file-status", entry.status?.trim() || (entry.untracked ? "?" : "•"));
  const name = make("span", "git-side-panel-file-name", entry.name || entry.path);
  const statsText = gitPanelStatsText(entry, category);
  const stats = make("span", "git-side-panel-file-stats", statsText);
  stats.hidden = !statsText;
  const context = { card, category, kind: "file", path: entry.path };
  bindGitPanelContextMenu(row, context);
  row.append(status, name, stats, gitPanelOverflowButton(context, entry.name || entry.path));
  return row;
}

function renderGitPanelTreeSection(label, category, entries, card) {
  if (!entries.length) return null;
  const section = make("section", `git-side-panel-tree-section ${category}`);
  const heading = make("div", "git-side-panel-tree-heading");
  heading.append(make("strong", undefined, label), make("span", undefined, String(entries.length)));
  section.append(heading);
  const tree = gitPanelTree(entries);
  const body = make("div", "git-side-panel-tree", undefined);
  body.setAttribute("aria-label", `${label} files`);
  for (const folder of [...tree.folders.values()].sort((a, b) => a.name.localeCompare(b.name))) body.append(renderGitPanelFolder(folder, card, category));
  for (const file of [...tree.files].sort((a, b) => a.name.localeCompare(b.name))) body.append(renderGitPanelFile(file, card, category));
  section.append(body);
  return section;
}

function renderGitPanelChanges(card, data) {
  const wrapper = make("div", "git-side-panel-changes");
  const changes = Array.isArray(data?.changes) ? data.changes : [];
  const categories = [
    ["Conflicts", "conflicted", changes.filter((entry) => entry.conflicted)],
    ["Staged", "staged", changes.filter((entry) => entry.staged && !entry.conflicted)],
    ["Changes", "changes", changes.filter((entry) => entry.unstaged && !entry.untracked && !entry.conflicted)],
    ["Untracked", "untracked", changes.filter((entry) => entry.untracked)],
  ];
  for (const [label, category, entries] of categories) {
    const section = renderGitPanelTreeSection(label, category, entries, card);
    if (section) wrapper.append(section);
  }
  if (!changes.length) wrapper.append(make("p", "git-side-panel-empty success", "Working tree clean."));
  return wrapper;
}

function gitPanelHistoryDate(value) {
  const date = new Date(value || "");
  return Number.isNaN(date.getTime()) ? String(value || "") : date.toLocaleString();
}

function gitPanelDataRenderSignature(data) {
  if (!data) return null;
  return {
    branch: data.branch || "",
    changes: Array.isArray(data.changes) ? data.changes : [],
    history: Array.isArray(data.history) ? data.history : [],
  };
}

function updateGitPanelRepositoryMeta(cards = gitPanelRepositoryCards()) {
  const sections = [...elements.gitPanelGroups?.querySelectorAll(".git-side-panel-repository[data-git-root]") || []];
  for (const card of cards) {
    const snapshot = gitPanelSnapshot(card.root);
    if (!snapshot?.data) continue;
    const section = sections.find((candidate) => candidate.dataset.gitRoot === card.root);
    const status = section?.querySelector(".git-side-panel-repository-updated");
    if (status) status.textContent = snapshot.loading ? "Refreshing…" : `Updated ${gitPanelHistoryDate(snapshot.data.generatedAt)}`;
  }
}

function renderGitPanelHistory(card, data) {
  const wrapper = make("div", "git-side-panel-history");
  const history = Array.isArray(data?.history) ? data.history : [];
  if (!history.length) {
    wrapper.append(make("p", "git-side-panel-empty", "No commits yet."));
    return wrapper;
  }
  for (const commit of history) {
    const button = make("button", "git-side-panel-commit");
    button.type = "button";
    button.dataset.gitPanelContinuityKey = `commit:${card.root}:${commit.hash}`;
    button.title = `View commit ${commit.hash}`;
    button.append(
      make("code", "git-side-panel-commit-hash", commit.shortHash || String(commit.hash || "").slice(0, 12)),
      make("span", "git-side-panel-commit-subject", commit.subject || "(no subject)"),
      make("span", "git-side-panel-commit-meta", [commit.author, gitPanelHistoryDate(commit.authoredAt)].filter(Boolean).join(" · ")),
    );
    button.addEventListener("click", () => openGitCommitDialog(card.tabId, commit));
    wrapper.append(button);
  }
  return wrapper;
}

function renderGitPanelRepositoryContent(card, snapshot) {
  const content = make("div", "git-side-panel-repository-content");
  if (snapshot?.error) content.append(make("p", "git-side-panel-error", snapshot.error));
  if (snapshot?.loading && !snapshot?.data) {
    content.append(make("p", "git-side-panel-empty", "Loading local Git status and history…"));
    return content;
  }
  const data = snapshot?.data;
  if (!data) {
    content.append(make("p", "git-side-panel-empty", "Expand this repository to load Git status."));
    return content;
  }
  const tabs = make("div", "git-side-panel-tabs");
  tabs.setAttribute("role", "tablist");
  tabs.setAttribute("aria-label", `${gitPanelRootLabel(card.root)} repository view`);
  const views = ["changes", "history"];
  const activeView = gitPanelState.activeViews.get(card.root) || "changes";
  for (const view of views) {
    const label = view === "changes" ? `Changes (${gitPanelChangeCount(data)})` : `History (${data.history?.length || 0})`;
    const button = make("button", "git-side-panel-tab", label);
    button.id = `git-side-panel-${view}-tab`;
    button.type = "button";
    button.dataset.gitPanelContinuityKey = `view:${card.root}:${view}`;
    button.setAttribute("role", "tab");
    button.setAttribute("aria-controls", `git-side-panel-${view}-panel`);
    button.setAttribute("aria-selected", activeView === view ? "true" : "false");
    button.tabIndex = activeView === view ? 0 : -1;
    button.addEventListener("click", () => {
      gitPanelState.activeViews.set(card.root, view);
      renderGitPanel();
    });
    tabs.append(button);
  }
  tabs.addEventListener("keydown", (event) => {
    const currentIndex = views.indexOf(gitPanelState.activeViews.get(card.root) || "changes");
    let nextIndex = -1;
    if (event.key === "ArrowRight") nextIndex = (currentIndex + 1) % views.length;
    else if (event.key === "ArrowLeft") nextIndex = (currentIndex - 1 + views.length) % views.length;
    else if (event.key === "Home") nextIndex = 0;
    else if (event.key === "End") nextIndex = views.length - 1;
    if (nextIndex < 0) return;
    event.preventDefault();
    const nextView = views[nextIndex];
    gitPanelState.activeViews.set(card.root, nextView);
    renderGitPanel();
    queueMicrotask(() => document.getElementById(`git-side-panel-${nextView}-tab`)?.focus({ preventScroll: true }));
  });
  const meta = make("div", "git-side-panel-repository-meta");
  meta.append(
    make("strong", undefined, data.branch || "detached"),
    make("span", "git-side-panel-repository-updated", snapshot.loading ? "Refreshing…" : `Updated ${gitPanelHistoryDate(data.generatedAt)}`),
  );
  const changesPanel = renderGitPanelChanges(card, data);
  changesPanel.id = "git-side-panel-changes-panel";
  changesPanel.setAttribute("role", "tabpanel");
  changesPanel.setAttribute("aria-labelledby", "git-side-panel-changes-tab");
  changesPanel.hidden = activeView !== "changes";
  const historyPanel = renderGitPanelHistory(card, data);
  historyPanel.id = "git-side-panel-history-panel";
  historyPanel.setAttribute("role", "tabpanel");
  historyPanel.setAttribute("aria-labelledby", "git-side-panel-history-tab");
  historyPanel.hidden = activeView !== "history";
  content.append(tabs, meta, changesPanel, historyPanel);
  return content;
}

function renderGitPanelRepositoryCard(card) {
  const discovery = card.discovery;
  if (!card.root) {
    const row = make("div", `git-side-panel-repository unavailable${discovery?.loading ? " loading" : ""}`);
    row.append(
      make("strong", undefined, gitPanelRootLabel(card.cwd, card.tabTitle)),
      make("span", "git-side-panel-repository-path", card.cwd),
      make("span", "git-side-panel-repository-state", discovery?.loading ? "Discovering repository…" : discovery?.error || "Waiting for repository discovery…"),
    );
    return row;
  }
  const snapshot = gitPanelSnapshot(card.root);
  const expanded = gitPanelState.expandedCardKey === card.key;
  const section = make("section", `git-side-panel-repository${expanded ? " expanded" : ""}`);
  section.dataset.gitRoot = card.root;
  const button = make("button", "git-side-panel-repository-toggle");
  button.type = "button";
  button.dataset.gitPanelContinuityKey = `repository:${card.root}`;
  button.setAttribute("aria-expanded", expanded ? "true" : "false");
  button.title = `${expanded ? "Collapse" : "Expand"} ${card.root} · ⋯ or right-click for repository actions`;
  const count = gitPanelChangeCount(snapshot?.data);
  button.append(
    make("span", "git-side-panel-repository-chevron", "›"),
    make("span", "git-side-panel-repository-copy", undefined),
    make("span", "git-side-panel-repository-count", String(count)),
  );
  const copy = button.querySelector(".git-side-panel-repository-copy");
  copy.append(make("strong", undefined, gitPanelRootLabel(card.root)), make("span", undefined, card.root));
  button.addEventListener("click", () => toggleGitPanelRepository(card));
  const repositoryContext = { card, kind: "repository", path: card.root };
  bindGitPanelContextMenu(button, repositoryContext);
  const header = make("div", "git-side-panel-repository-header");
  header.append(button, gitPanelOverflowButton(repositoryContext, gitPanelRootLabel(card.root)));
  section.append(header);
  if (expanded) section.append(renderGitPanelRepositoryContent(card, snapshot));
  return section;
}

function renderGitPanel() {
  if (!elements.gitPanelGroups || !gitPanelSectionExpanded()) return;
  if (deferUiRenderDuringPointerActivation("git-panel", renderGitPanel)) return;
  if (gitPanelContextMenuState && !elements.gitPanelContextMenu?.hidden) return;
  const groups = gitPanelTerminalGroups();
  const candidates = gitPanelCandidates(groups);
  const cards = gitPanelRepositoryCards(groups);
  const liveCandidateKeys = new Set(candidates.map((candidate) => candidate.key));
  const liveRoots = new Set(cards.map((card) => card.root).filter(Boolean));
  for (const key of [...gitPanelState.discovery.keys()]) if (!liveCandidateKeys.has(key)) gitPanelState.discovery.delete(key);
  for (const key of [...gitPanelState.activeViews.keys()]) if (!liveRoots.has(key)) gitPanelState.activeViews.delete(key);
  for (const key of [...gitPanelState.repositories.keys()]) if (!liveRoots.has(key)) gitPanelState.repositories.delete(key);
  for (const key of [...gitPanelState.openFolders.keys()]) if (!liveRoots.has(key.split("\u0000", 1)[0])) gitPanelState.openFolders.delete(key);
  const liveCardKeys = new Set(cards.filter((card) => card.root).map((card) => card.key));
  if (gitPanelState.expandedCardKey && !liveCardKeys.has(gitPanelState.expandedCardKey)) gitPanelState.expandedCardKey = "";
  closeGitPanelContextMenu({ returnFocus: false });
  const repositoryCount = cards.filter((card) => card.root).length;
  const discovering = [...gitPanelState.discovery.values()].some((entry) => entry.loading);
  const signature = JSON.stringify({
    expandedCardKey: gitPanelState.expandedCardKey,
    groups: groups.map((group) => [group.key, group.cwd, group.title, group.detail]),
    candidates: candidates.map((candidate) => {
      const discovery = gitPanelState.discovery.get(candidate.key);
      return [candidate.key, candidate.cwd, candidate.tabId, candidate.tabTitle, discovery?.root || "", !!discovery?.loading, discovery?.error || ""];
    }),
    cards: cards.map((card) => {
      const snapshot = gitPanelSnapshot(card.root);
      const data = snapshot?.data;
      return [card.key, card.root, card.cwd, card.tabId, snapshot?.error || "", !data && !!snapshot?.loading, gitPanelDataRenderSignature(data), gitPanelState.activeViews.get(card.root) || "changes"];
    }),
    repositoryCount,
    discovering,
  });
  if (signature === gitPanelRenderSignature && elements.gitPanelGroups.childElementCount === cards.length) {
    updateGitPanelRepositoryMeta(cards);
    ensureGitPanelRepositoriesDiscovered();
    ensureGitPanelVisibleRepositoriesFresh(cards);
    return;
  }
  const continuityContextKey = `${activeTabId || ""}:${activeTabGeneration}:git-panel`;
  const focusSnapshot = captureScopedControlContinuity(elements.gitPanelGroups, continuityContextKey, (node) => node?.dataset?.gitPanelContinuityKey || "");
  const scrollTop = elements.gitPanelGroups.scrollTop;
  const scrollLeft = elements.gitPanelGroups.scrollLeft;
  gitPanelRenderSignature = signature;
  elements.gitPanelGroups.replaceChildren(...cards.map(renderGitPanelRepositoryCard));
  restoreScopedControlContinuity(elements.gitPanelGroups, continuityContextKey, focusSnapshot, (key) => [...elements.gitPanelGroups.querySelectorAll("[data-git-panel-continuity-key]")]
    .find((node) => node.dataset.gitPanelContinuityKey === key));
  elements.gitPanelGroups.scrollTop = scrollTop;
  elements.gitPanelGroups.scrollLeft = scrollLeft;
  if (elements.gitPanelCountBadge) {
    elements.gitPanelCountBadge.textContent = String(repositoryCount);
    elements.gitPanelCountBadge.hidden = repositoryCount === 0;
  }
  if (elements.gitPanelStatus) {
    elements.gitPanelStatus.textContent = !groups.length
      ? "No terminal tabs are open."
      : discovering
        ? "Discovering repositories…"
        : `${repositoryCount} Git ${repositoryCount === 1 ? "repository" : "repositories"} · ⋯ or right-click for actions`;
  }
  ensureGitPanelRepositoriesDiscovered();
  ensureGitPanelVisibleRepositoriesFresh(cards);
}

function tabAppRunnerRun(tab) {
  if (!tab?.id) return null;
  const cached = appRunnerDataByTab.get(tab.id);
  if (cached && Object.prototype.hasOwnProperty.call(cached, "activeRun")) return cached.activeRun || null;
  if (Object.prototype.hasOwnProperty.call(tab, "appRunner")) return tab.appRunner || null;
  return null;
}

function tabAppRunnerRunningRun(tab) {
  const run = tabAppRunnerRun(tab);
  return appRunnerIsRunning(run) ? run : null;
}

function tabGroupAppRunnerRunningRun(groupTabs = []) {
  return groupTabs.map(tabAppRunnerRunningRun).find(Boolean) || null;
}

function terminalAppRunnerLabel(run) {
  const command = cleanStatusText(run?.displayCommand || run?.label || run?.command || "app runner");
  return command && command !== "app runner" ? `app runner: ${command}` : "app runner running";
}

function tabConversationMode(tab) {
  if (!tab?.id) return normalizeConversationModeState(tab?.conversationMode || {});
  return normalizeConversationModeState(conversationModeByTab.get(tab.id) || tab.conversationMode || {});
}

function tabConversationModeActive(tab) {
  return tabConversationMode(tab).enabled === true;
}

function tabWorkflowModeActive(tab) {
  return normalizeWorkflowModeState(workflowModeByTab.get(tab?.id) || {}).enabled === true;
}

function terminalTabWorkspaceName(tab) {
  return tabGroupTitle(tab?.cwd, "workspace");
}

function terminalTabMeta(tab, indicator) {
  const parts = [tab.running ? `${indicator.meta} · ${terminalTabWorkspaceName(tab)}` : "stopped"];
  if (tabAppRunnerRunningRun(tab)) parts.push("app runner");
  if (tabConversationModeActive(tab)) parts.push("voice");
  if (tabWorkflowModeActive(tab)) parts.push("workflow mode");
  const workflowCount = workflowRunningCountForTab(tab.id);
  if (workflowCount) parts.push(`${workflowCount} workflow${workflowCount === 1 ? "" : "s"}`);
  return parts.join(" · ");
}

function terminalTabGitTooltip(tab) {
  const workspace = normalizeGitWorkspaceInfo(tab?.gitWorkspace);
  if (!workspace) return "";
  const checkout = workspace.worktreePath ? (workspace.isMainWorktree ? "main worktree" : "worktree") : "";
  return [workspace.branch || "detached", checkout].filter(Boolean).join(" · ");
}

function terminalTabActiveTooltip(tab) {
  const active = [];
  const appRunnerRun = tabAppRunnerRunningRun(tab);
  if (appRunnerRun) active.push(terminalAppRunnerLabel(appRunnerRun));
  const conversationMode = tabConversationMode(tab);
  if (conversationMode.enabled) active.push(`voice: ${conversationMode.uiState || "listening"}`);
  const workflowCount = workflowRunningCountForTab(tab?.id);
  if (tabWorkflowModeActive(tab)) active.push(workflowCount ? `workflow: ${workflowCount} run${workflowCount === 1 ? "" : "s"}` : "workflow mode");
  else if (workflowCount) active.push(`workflow: ${workflowCount} run${workflowCount === 1 ? "" : "s"}`);
  return active.join(" · ");
}

function terminalTabPromptTooltip(tab) {
  const prompt = tab?.prompt;
  if (!prompt || typeof prompt !== "object" || Array.isArray(prompt) || Object.keys(prompt).length !== 2 || !Object.hasOwn(prompt, "kind") || !Object.hasOwn(prompt, "path") || prompt.kind !== "append-system") return "";
  const path = prompt.path;
  const absolute = typeof path === "string" && (path.startsWith("/") || /^[A-Za-z]:[\\/]/.test(path) || path.startsWith("\\\\"));
  if (!absolute || path.length > 4096 || /[\u0000-\u001f\u007f]/.test(path)) return "";
  return `Append-system prompt: ${path}`;
}

function terminalTabGroupRepresentedTab(groupTabs = []) {
  return groupTabs.find((tab) => typeof activeTabId !== "undefined" && tab?.id === activeTabId) || groupTabs[0] || null;
}

function terminalTabTooltip(tab) {
  const lines = [
    `${tab?.title || "Terminal tab"} · ${tabIndicator(tab).label}`,
    `Working folder: ${normalizeDisplayPath(tab?.cwd || "") || "Not set"}`,
  ];
  const git = terminalTabGitTooltip(tab);
  if (git) lines.push(`Git: ${git}`);
  const active = terminalTabActiveTooltip(tab);
  if (active) lines.push(`Active: ${active}`);
  const prompt = terminalTabPromptTooltip(tab);
  if (prompt) lines.push(prompt);
  lines.push("Click to switch · Drag to group");
  return lines.join("\n");
}

function terminalTabGroupStatusTooltip(groupTabs = []) {
  const counts = { blocked: 0, working: 0, done: 0, idle: 0, stopped: 0 };
  for (const tab of groupTabs) {
    const state = tab?.running ? tabIndicator(tab).state : "stopped";
    counts[state] = (counts[state] || 0) + 1;
  }
  return ["blocked", "working", "done", "idle", "stopped"]
    .filter((state) => counts[state])
    .map((state) => `${counts[state]} ${state}`)
    .join(" · ");
}

function terminalTabGroupWorkspaceTooltip(group) {
  const paths = [...new Set((group?.tabs || []).map((tab) => normalizeDisplayPath(tab?.cwd || "")).filter(Boolean))];
  if (!group?.custom || paths.length <= 1) return `Working folder: ${paths[0] || normalizeDisplayPath(group?.cwd || "") || "Not set"}`;
  const names = paths.map((path) => path.split("/").filter(Boolean).slice(-2).join("/") || path);
  const remainder = names.length - 2;
  return `Workspaces: ${names.slice(0, 2).join(", ")}${remainder > 0 ? ` +${remainder} more` : ""}`;
}

function terminalTabGroupActiveTooltip(groupTabs = []) {
  const appRunners = groupTabs.filter(tabAppRunnerRunningRun).length;
  const voices = groupTabs.filter(tabConversationModeActive).length;
  const workflowTabs = groupTabs.filter(tabWorkflowModeActive).length;
  const workflowRuns = groupTabs.reduce((total, tab) => total + workflowRunningCountForTab(tab?.id), 0);
  return [
    appRunners ? `${appRunners} app runner${appRunners === 1 ? "" : "s"}` : "",
    voices ? `${voices} voice` : "",
    workflowTabs ? `${workflowTabs} workflow tab${workflowTabs === 1 ? "" : "s"}` : "",
    workflowRuns ? `${workflowRuns} workflow run${workflowRuns === 1 ? "" : "s"}` : "",
  ].filter(Boolean).join(" · ");
}

function terminalTabGroupTooltip(group, groupTitle = terminalDisplayGroupTitle(group)) {
  const groupTabs = group?.tabs || [];
  const lines = [
    `${groupTitle} · ${groupTabs.length} tab${groupTabs.length === 1 ? "" : "s"}`,
    terminalTabGroupWorkspaceTooltip(group),
    `Status: ${terminalTabGroupStatusTooltip(groupTabs) || "No tabs"}`,
  ];
  const active = terminalTabGroupActiveTooltip(groupTabs);
  if (active) lines.push(`Active: ${active}`);
  const prompt = terminalTabPromptTooltip(terminalTabGroupRepresentedTab(groupTabs));
  if (prompt) lines.push(prompt);
  lines.push(isMobileView() ? "Tap to open group terminals" : "Click to switch · Drop tabs here to add");
  return lines.join("\n");
}

function appendTerminalTabContent(button, { title, indicator, meta, count = null, appRunnerRun = null, conversationModeActive = false, workflowModeActive = false, workflowCount = 0, subagent = false, dropdown = false }) {
  const titleRow = make("span", "terminal-tab-title-row");
  const indicatorDot = make("span", "terminal-tab-activity-indicator");
  indicatorDot.setAttribute("aria-hidden", "true");
  titleRow.append(indicatorDot, make("span", "terminal-tab-title", title));
  if (subagent) titleRow.append(make("span", "terminal-tab-subagent-indicator", "subagent"));
  if (appRunnerIsRunning(appRunnerRun)) titleRow.append(make("span", "terminal-tab-app-runner-indicator", "app"));
  if (conversationModeActive) titleRow.append(make("span", "terminal-tab-conversation-indicator", "voice"));
  if (workflowModeActive || workflowCount) titleRow.append(make("span", "terminal-tab-workflow-indicator", workflowCount ? `wf ${workflowCount}` : "wf"));
  if (count !== null) titleRow.append(make("span", "terminal-tab-group-count", String(count)));
  if (dropdown) {
    const disclosure = make("span", "terminal-tab-group-dropdown-indicator", "⌄");
    disclosure.setAttribute("aria-hidden", "true");
    titleRow.append(disclosure);
  }
  button.append(titleRow, make("span", "terminal-tab-meta", meta));
}

function createTerminalTabCwdAddMenu(tab) {
  const cwdTitle = tabGroupTitle(tab?.cwd, "working directory");
  const menu = make("div", "terminal-tab-cwd-add-menu");
  menu.setAttribute("role", "group");
  menu.setAttribute("aria-label", `Actions for ${cwdTitle}`);
  const add = make("button", "terminal-tab-group-add terminal-tab-cwd-add", "+ Tab");
  add.type = "button";
  add.draggable = false;
  const addTooltip = `Add tab in ${cwdTitle}`;
  applyStyledTooltip(add, addTooltip, { ariaLabel: addTooltip, targetKey: `terminal-tab:${tab.id}:add` });
  add.addEventListener("click", (event) => {
    event.stopPropagation();
    void createTerminalTab(tab.cwd || currentDirectoryForNewTab(), { triggerButton: add });
  });
  menu.append(add);
  return menu;
}

function renderTerminalTab(tab, { showCwdAdd = false } = {}) {
  const isActive = tab.id === activeTabId && !activeSubagentTerminalId;
  const indicator = tabIndicator(tab);
  const appRunnerRun = tabAppRunnerRunningRun(tab);
  const appRunnerLabel = appRunnerRun ? terminalAppRunnerLabel(appRunnerRun) : "";
  const conversationModeActive = tabConversationModeActive(tab);
  const conversationLabel = conversationModeActive ? `, natural conversation ${tabConversationMode(tab).uiState || "listening"}` : "";
  const workflowModeActive = tabWorkflowModeActive(tab);
  const workflowCount = workflowRunningCountForTab(tab.id);
  const wrapper = make("div", `terminal-tab${showCwdAdd ? " terminal-tab-cwd-add-host" : ""} activity-${indicator.state}${isActive ? " active" : ""}${tab.running ? "" : " stopped"}${appRunnerRun ? " app-runner-running" : ""}${conversationModeActive ? " conversation-mode-running" : ""}${workflowModeActive ? " workflow-mode-running" : ""}${workflowCount ? " workflow-run-running" : ""}`);
  wrapper.dataset.tabId = tab.id;
  bindTerminalTabDragAndDrop(wrapper, { sourceTabId: tab.id, target: { type: "tab", tabId: tab.id } });
  const button = make("button", "terminal-tab-button");
  button.type = "button";
  button.draggable = false;
  button.setAttribute("role", "tab");
  button.setAttribute("aria-selected", isActive ? "true" : "false");
  button.setAttribute("aria-label", `${tab.title}: ${indicator.label}${appRunnerLabel ? `, ${appRunnerLabel}` : ""}${conversationLabel}${workflowModeActive ? ", workflow mode active" : ""}${workflowCount ? `, ${workflowCount} workflow runs active` : ""}`);
  applyStyledTooltip(button, terminalTabTooltip(tab), { ariaLabel: false, align: "start", description: true, preserveInternalSpaces: true, variant: "workspace", targetKey: `terminal-tab:${tab.id}:switch` });
  appendTerminalTabContent(button, { title: tab.title, indicator, meta: terminalTabMeta(tab, indicator), appRunnerRun, conversationModeActive, workflowModeActive, workflowCount });
  button.addEventListener("click", () => switchTab(tab.id));
  wrapper.append(button, createTerminalTabActions(tab));
  if (showCwdAdd) wrapper.append(createTerminalTabCwdAddMenu(tab));

  if (tabs.length > 1) {
    const close = make("button", "terminal-tab-close", "×");
    close.type = "button";
    close.draggable = false;
    const closeTooltip = `Close ${tab.title}`;
    applyStyledTooltip(close, closeTooltip, { ariaLabel: closeTooltip, targetKey: `terminal-tab:${tab.id}:close` });
    close.addEventListener("click", (event) => {
      event.stopPropagation();
      closeTerminalTab(tab.id);
    });
    wrapper.append(close);
  }

  return wrapper;
}

function renderTerminalTabGroupItem(tab, group) {
  const isActive = tab.id === activeTabId && !activeSubagentTerminalId;
  const indicator = tabIndicator(tab);
  const appRunnerRun = tabAppRunnerRunningRun(tab);
  const appRunnerLabel = appRunnerRun ? terminalAppRunnerLabel(appRunnerRun) : "";
  const conversationModeActive = tabConversationModeActive(tab);
  const conversationLabel = conversationModeActive ? `, natural conversation ${tabConversationMode(tab).uiState || "listening"}` : "";
  const workflowModeActive = tabWorkflowModeActive(tab);
  const workflowCount = workflowRunningCountForTab(tab.id);
  const item = make("div", `terminal-tab-group-item activity-${indicator.state}${isActive ? " active" : ""}${tab.running ? "" : " stopped"}${appRunnerRun ? " app-runner-running" : ""}${conversationModeActive ? " conversation-mode-running" : ""}${workflowModeActive ? " workflow-mode-running" : ""}${workflowCount ? " workflow-run-running" : ""}`);
  item.dataset.tabId = tab.id;
  bindTerminalTabDragAndDrop(item, { sourceTabId: tab.id, target: group?.custom ? { type: "group", group } : { type: "tab", tabId: tab.id } });
  const button = make("button", "terminal-tab-button terminal-tab-group-item-button");
  button.type = "button";
  button.draggable = false;
  button.setAttribute("role", "tab");
  button.setAttribute("aria-selected", isActive ? "true" : "false");
  button.setAttribute("aria-label", `${tab.title}: ${indicator.label}${appRunnerLabel ? `, ${appRunnerLabel}` : ""}${conversationLabel}${workflowModeActive ? ", workflow mode active" : ""}${workflowCount ? `, ${workflowCount} workflow runs active` : ""}`);
  applyStyledTooltip(button, terminalTabTooltip(tab), { ariaLabel: false, align: "start", description: true, preserveInternalSpaces: true, variant: "workspace", targetKey: `terminal-tab:${tab.id}:switch` });
  appendTerminalTabContent(button, { title: tab.title, indicator, meta: terminalTabMeta(tab, indicator), appRunnerRun, conversationModeActive, workflowModeActive, workflowCount });
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    switchTab(tab.id);
  });
  item.append(button, createTerminalTabActions(tab));

  if (tabs.length > 1) {
    const close = make("button", "terminal-tab-close terminal-tab-group-item-close", "×");
    close.type = "button";
    close.draggable = false;
    const closeTooltip = `Close ${tab.title}`;
    applyStyledTooltip(close, closeTooltip, { ariaLabel: closeTooltip, targetKey: `terminal-tab:${tab.id}:close` });
    close.addEventListener("click", (event) => {
      event.stopPropagation();
      closeTerminalTab(tab.id);
    });
    item.append(close);
  }

  return item;
}

function shouldRenderTerminalTabGroup(group, groupCount) {
  if (group.custom) return group.tabs.length > 1;
  return groupCount > 1 && group.tabs.length > 1 && Boolean(group.cwd);
}

function renderTerminalTabGroup(group, groupCount = 1) {
  const groupTabs = group.tabs;
  const activeGroupTab = terminalTabGroupRepresentedTab(groupTabs);
  const isActive = !activeSubagentTerminalId && groupTabs.some((tab) => tab.id === activeTabId);
  const isStopped = groupTabs.every((tab) => !tab.running);
  const indicator = tabGroupIndicator(groupTabs);
  const appRunnerRun = tabGroupAppRunnerRunningRun(groupTabs);
  const appRunnerCount = groupTabs.filter(tabAppRunnerRunningRun).length;
  const appRunnerSummary = appRunnerCount > 1 ? `${appRunnerCount} app runners running` : appRunnerRun ? terminalAppRunnerLabel(appRunnerRun) : "";
  const groupAppRunnerMeta = appRunnerCount > 1 ? `${appRunnerCount} app runners` : appRunnerRun ? "app runner" : "";
  const workflowCount = groupTabs.reduce((total, tab) => total + workflowRunningCountForTab(tab.id), 0);
  const workflowModeActive = groupTabs.some(tabWorkflowModeActive);
  const groupTitle = terminalDisplayGroupTitle(group, activeGroupTab?.title || "group");
  const activeTitle = activeGroupTab?.title || groupTitle;
  const wrapper = make("div", `terminal-tab terminal-tab-group${group.custom ? " terminal-tab-custom-group" : ""} activity-${indicator.state}${isActive ? " active" : ""}${isStopped ? " stopped" : ""}${appRunnerRun ? " app-runner-running" : ""}${workflowModeActive ? " workflow-mode-running" : ""}${workflowCount ? " workflow-run-running" : ""}`);
  wrapper.dataset.groupKey = group.key;
  if (group.customGroupId) wrapper.dataset.customGroupId = group.customGroupId;
  bindTerminalTabDragAndDrop(wrapper, { sourceTabId: activeGroupTab?.id || "", target: { type: "group", group } });
  wrapper.addEventListener("pointerenter", (event) => {
    if (event.pointerType === "touch") return;
    setOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("pointerleave", (event) => {
    if (event.pointerType === "touch") return;
    clearOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("focusin", () => {
    if (!isMobileView()) setOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("focusout", () => {
    if (isMobileView()) return;
    setTimeout(() => {
      if (!wrapper.contains(document.activeElement)) clearOpenTerminalTabGroup(group.key);
    }, 0);
  });
  const button = make("button", "terminal-tab-button terminal-tab-group-button");
  button.type = "button";
  button.draggable = false;
  button.setAttribute("role", "tab");
  button.setAttribute("aria-selected", isActive ? "true" : "false");
  button.setAttribute("aria-haspopup", "true");
  button.setAttribute("aria-expanded", group.key === openTerminalTabGroupKey ? "true" : "false");
  button.setAttribute("aria-label", `${groupTitle} ${group.custom ? "custom" : "cwd"} group: ${groupTabs.length} tabs, ${indicator.label}${appRunnerSummary ? `, ${appRunnerSummary}` : ""}${workflowModeActive ? ", workflow mode active" : ""}${workflowCount ? `, ${workflowCount} workflow runs active` : ""}. Active ${activeTitle}. ${isMobileView() ? "Toggle group terminal list" : "Switch to the active group terminal"}`);
  applyStyledTooltip(button, terminalTabGroupTooltip(group, groupTitle), { ariaLabel: false, description: true, placement: "right", preserveInternalSpaces: true, variant: "workspace", targetKey: `terminal-group:${group.key}:switch` });
  appendTerminalTabContent(button, { title: activeTitle, indicator, meta: `${groupTitle} · ${indicator.meta}${groupAppRunnerMeta ? ` · ${groupAppRunnerMeta}` : ""}${workflowModeActive ? " · workflow mode" : ""}${workflowCount ? ` · ${workflowCount} workflows` : ""}`, appRunnerRun, count: groupTabs.length, workflowModeActive, workflowCount, dropdown: true });
  button.addEventListener("click", () => {
    if (isMobileView()) {
      toggleOpenTerminalTabGroup(group.key);
      return;
    }
    switchTab(activeGroupTab.id);
  });
  wrapper.append(button);

  if (groupCount > 1 || group.custom) {
    const close = make("button", "terminal-tab-close terminal-tab-group-close", "×");
    close.type = "button";
    close.draggable = false;
    const closeTooltip = `Close ${groupTitle} group`;
    applyStyledTooltip(close, closeTooltip, { ariaLabel: closeTooltip, targetKey: `terminal-group:${group.key}:close` });
    close.addEventListener("click", (event) => {
      event.stopPropagation();
      closeTerminalTabGroup(group);
    });
    wrapper.append(close);
  }

  const menu = make("div", "terminal-tab-group-menu");
  menu.id = `terminalTabGroupMenu${++terminalTabGroupMenuSerial}`;
  menu.setAttribute("role", "group");
  menu.setAttribute("aria-label", `${groupTitle} tabs`);
  button.setAttribute("aria-controls", menu.id);
  for (const tab of groupTabs) menu.append(renderTerminalTabGroupItem(tab, group));

  const add = make("button", "terminal-tab-group-add", "+ Tab");
  add.type = "button";
  add.draggable = false;
  const addTooltip = `Add tab in ${groupTitle}`;
  applyStyledTooltip(add, addTooltip, { ariaLabel: addTooltip, targetKey: `terminal-group:${group.key}:add` });
  add.addEventListener("click", (event) => {
    event.stopPropagation();
    createTerminalTab(activeGroupTab?.cwd || group.cwd || currentDirectoryForNewTab(), { triggerButton: add, customGroupId: group.customGroupId || null });
  });
  menu.append(add);
  wrapper.append(menu);
  return wrapper;
}

function updateTerminalTabGroupOpenState() {
  for (const group of elements.tabBar.querySelectorAll(".terminal-tab-group")) {
    const open = Boolean(openTerminalTabGroupKey && group.dataset.groupKey === openTerminalTabGroupKey);
    group.classList.toggle("menu-open", open);
    group.querySelector(".terminal-tab-group-button")?.setAttribute("aria-expanded", open ? "true" : "false");
  }
}

function setOpenTerminalTabGroup(groupKey) {
  if (!groupKey || openTerminalTabGroupKey === groupKey) return;
  openTerminalTabGroupKey = groupKey;
  updateTerminalTabGroupOpenState();
}

function toggleOpenTerminalTabGroup(groupKey) {
  if (!groupKey) return;
  if (openTerminalTabGroupKey === groupKey) clearOpenTerminalTabGroup(groupKey);
  else setOpenTerminalTabGroup(groupKey);
}

function clearOpenTerminalTabGroup(groupKey, { force = false } = {}) {
  if (!openTerminalTabGroupKey || (!force && openTerminalTabGroupKey !== groupKey)) return;
  openTerminalTabGroupKey = null;
  updateTerminalTabGroupOpenState();
  syncTabPolling();
}

function setNewTabMenuOpen(open) {
  if (open && followUpQueueOpen) setFollowUpQueueOpen(false);
  newTabMenuOpen = !!open;
  elements.newTabButton?.setAttribute("aria-expanded", newTabMenuOpen ? "true" : "false");
  elements.newTabButton?.classList.toggle("menu-open", newTabMenuOpen);
  elements.newTabMenu?.classList.toggle("open", newTabMenuOpen);
  if (!newTabMenuOpen) scheduleDeferredUiFlushAfterDropdownClose();
}

function initializeTerminalHeaderTooltips() {
  applyStyledTooltip(elements.newTabButton, "Start a separate isolated Pi terminal", { ariaLabel: "Start a separate isolated Pi terminal" });
  applyStyledTooltip(elements.closeAllTabsButton, "Close all terminal tabs", { ariaLabel: "Close all terminal tabs" });
}

function initializeControlSettingTooltips() {
  document.querySelectorAll("#sidePanelSectionControls .control-row-label[data-tooltip]").forEach((label) => {
    bindStyledTooltipEvents(label);
    label.addEventListener("click", (event) => {
      const modelLabel = label.contains(elements.modelControlLabel);
      const themeLabel = label.contains(elements.themeControlLabel);
      showFooterTooltip(label);
      if (!modelLabel && !themeLabel) return;
      if (event.target === elements.modelControlLabel || event.target === elements.themeControlLabel) return;
      event.preventDefault();
      if (modelLabel) toggleModelSearchInput();
      else toggleThemeSearchInput();
    });
    label.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      showFooterTooltip(label);
      if (label.contains(elements.modelControlLabel)) toggleModelSearchInput();
      else if (label.contains(elements.themeControlLabel)) toggleThemeSearchInput();
    });
  });
}

function openNewTabMenu() {
  setPublishMenuOpen(false);
  setNativeCommandMenuOpen(false);
  setAppRunnerMenuOpen(false);
  setOptionsMenuOpen(false);
  setNewTabMenuOpen(true);
}

function newTabMenuItems() {
  return [elements.newTabCurrentDirectoryButton, elements.newTabChooseDirectoryButton, elements.newTabWorktreeButton].filter(Boolean);
}

function focusNewTabMenuItem(direction = "first") {
  const items = newTabMenuItems();
  const item = direction === "last" ? items.at(-1) : items[0];
  item?.focus({ preventScroll: true });
}

function moveNewTabMenuFocus(delta) {
  const items = newTabMenuItems();
  if (!items.length) return;
  const currentIndex = Math.max(0, items.indexOf(document.activeElement));
  const nextIndex = (currentIndex + delta + items.length) % items.length;
  items[nextIndex].focus({ preventScroll: true });
}

function scheduleTabsRender() {
  if (tabsRenderFrame !== null) return;
  const flush = () => {
    tabsRenderFrame = null;
    renderTabs();
  };
  if (typeof requestAnimationFrame === "function") tabsRenderFrame = requestAnimationFrame(flush);
  else tabsRenderFrame = setTimeout(flush, 0);
}

function terminalTabControlKey(node) {
  if (node?.id && elements.newTabMenu?.contains(node)) return `terminal-new-tab:${node.id}`;
  const tabId = node?.closest?.("[data-tab-id]")?.dataset?.tabId;
  if (tabId) {
    if (node.classList.contains("terminal-tab-close")) return `terminal-tab:${tabId}:close`;
    if (node.classList.contains("terminal-tab-split-button")) return `terminal-tab:${tabId}:split`;
    if (node.classList.contains("terminal-tab-summary-button")) return `terminal-tab:${tabId}:summary`;
    if (node.classList.contains("terminal-tab-cwd-add")) return `terminal-tab:${tabId}:add`;
    if (node.classList.contains("terminal-tab-button")) return `terminal-tab:${tabId}:switch`;
  }
  const groupKey = node?.closest?.("[data-group-key]")?.dataset?.groupKey;
  if (!groupKey) return "";
  if (node.classList.contains("terminal-tab-group-close")) return `terminal-group:${groupKey}:close`;
  if (node.classList.contains("terminal-tab-group-add")) return `terminal-group:${groupKey}:add`;
  if (node.classList.contains("terminal-tab-group-button")) return `terminal-group:${groupKey}:switch`;
  return "";
}

function renderTabs() {
  if (deferUiRenderDuringPointerActivation("tabs", renderTabs)) return;
  const continuityContextKey = `${activeTabId || ""}:${activeTabGeneration}:${activeSubagentTerminalId || ""}`;
  const focusSnapshot = captureScopedControlContinuity(elements.tabBar, continuityContextKey, terminalTabControlKey);
  const tooltipSnapshot = captureTooltipContinuity(elements.tabBar);
  const activeSubagent = activeSubagentTerminalView();
  const active = activeSubagent || activeTab();
  const activeIndicator = activeSubagent ? { glyph: "◉", label: "Subagent view" } : active ? tabIndicator(active) : null;
  const activeTitle = activeSubagent ? subagentTerminalViewTitle(activeSubagent) : active?.title;
  const totalTabCount = tabs.length + subagentTerminalViews.size;
  elements.terminalTabsToggleButton.textContent = active ? `${activeIndicator.glyph} ${activeTitle}${totalTabCount > 1 ? ` · ${totalTabCount}` : ""}` : "Tabs";
  const toggleTooltip = active ? `Show terminal tabs · active: ${activeTitle} · ${activeIndicator.label}` : "Show terminal tabs";
  applyStyledTooltip(elements.terminalTabsToggleButton, toggleTooltip, { ariaLabel: toggleTooltip, targetKey: "terminal-tabs-toggle" });
  if (footerTooltipTarget && elements.tabBar.contains(footerTooltipTarget) && !tooltipSnapshot) hideFooterTooltip();
  elements.tabBar.replaceChildren();
  elements.tabBar.dataset.tabCount = String(totalTabCount);
  elements.tabBar.classList.toggle("terminal-tabs-dense", totalTabCount >= 10);
  const groups = tabCwdGroups();
  const subagentGroups = subagentTerminalViewGroups();
  const renderedGroupKeys = new Set([
    ...groups.filter((group) => shouldRenderTerminalTabGroup(group, groups.length)).map((group) => group.key),
    ...subagentGroups.filter((group) => group.views.length > 1).map((group) => group.key),
  ]);
  if (openTerminalTabGroupKey && !renderedGroupKeys.has(openTerminalTabGroupKey)) openTerminalTabGroupKey = null;
  for (const group of groups) {
    if (shouldRenderTerminalTabGroup(group, groups.length)) {
      elements.tabBar.append(renderTerminalTabGroup(group, groups.length));
    } else {
      const showCwdAdd = groups.length > 1 && group.tabs.length === 1 && Boolean(group.cwd);
      for (const tab of group.tabs) elements.tabBar.append(renderTerminalTab(tab, { showCwdAdd }));
    }
  }
  for (const group of subagentGroups) {
    if (group.views.length > 1) elements.tabBar.append(renderSubagentTerminalTabGroup(group));
    else elements.tabBar.append(renderSubagentTerminalTab(group.views[0]));
  }
  elements.tabBar.append(elements.newTabMenu);
  restoreScopedControlContinuity(elements.tabBar, continuityContextKey, focusSnapshot, (key) => [...elements.tabBar.querySelectorAll("button")].find((node) => terminalTabControlKey(node) === key));
  restoreTooltipContinuity(elements.tabBar, tooltipSnapshot);
  elements.closeAllTabsButton.disabled = tabs.length === 0;
  if (elements.workspaceSaveButton) {
    const canSave = tabs.length > 0;
    elements.workspaceSaveButton.disabled = !canSave;
    applyStyledTooltip(elements.workspaceSaveButton, canSave
      ? "Save workspace:\n• Captures all open tabs, sessions, order, custom groups, and the active tab."
      : "Save workspace is available after you open a tab.", { ariaLabel: canSave ? "Save workspace" : "Save workspace (no open tabs)", floating: false });
  }
  updateTerminalTabGroupOpenState();
  reconcileTerminalSplitState();
  setMobileTabsExpanded(mobileTabsExpanded);
  updateDocumentTitle();
  renderWorkspaceDashboard();
  renderContextMeter();
  renderGitPanel();
  if (elements.commandPaletteDialog?.open) renderCommandPalette({ preserveScroll: true });
  syncTabPolling();
  if (mobilePhoneExperienceInstalled && isMobileShellV2Active()) renderMobilePhoneExperience();
}

function prefetchInactiveTabCommandCatalogs() {
  for (const tab of tabs) {
    if (!tab?.id || tab.id === activeTabId || commandCatalogsByTab.has(tab.id) || commandCatalogRefreshesByTab.has(tab.id)) continue;
    const refresh = refreshCommands(activeTabContext(tab.id))
      .catch(() => {})
      .finally(() => {
        if (commandCatalogRefreshesByTab.get(tab.id) === refresh) commandCatalogRefreshesByTab.delete(tab.id);
      });
    commandCatalogRefreshesByTab.set(tab.id, refresh);
  }
}

function tabsSnapshotSignature(tabList = []) {
  try {
    return JSON.stringify(tabList);
  } catch {
    return "";
  }
}

function tabsRenderSnapshotSignature(tabList = []) {
  return tabsSnapshotSignature(tabList.map((tab) => {
    const activity = normalizeTabActivity(tab?.activity || {});
    const runner = tab?.appRunner || null;
    const conversation = normalizeConversationModeState(tab?.conversationMode || {});
    const summary = tab?.sessionSummary || null;
    const pendingExtensionUiRequestCount = normalizePendingExtensionUiRequestCount(tab?.pendingExtensionUiRequestCount);
    const seenCompletionSerial = tabSeenCompletionSerials.get(tab?.id) ?? activity.completionSerial;
    const activityState = tab?.running && pendingExtensionUiRequestCount > 0
      ? "blocked"
      : tab?.running && activity.isWorking
        ? "working"
        : tab?.running && activity.completionSerial > seenCompletionSerial
          ? "done"
          : tab?.running ? "idle" : "stopped";
    return {
      id: tab?.id || "",
      index: Number(tab?.index) || 0,
      title: tab?.title || "",
      titleSource: tab?.titleSource || "",
      running: tab?.running === true,
      cwd: tab?.cwd || "",
      gitWorkspace: tab?.gitWorkspace || null,
      pendingExtensionUiRequestCount,
      activityState,
      appRunner: runner ? {
        status: runner.status || "",
        stopping: runner.stopping === true,
        displayCommand: runner.displayCommand || runner.label || runner.command || "",
      } : null,
      conversationMode: {
        available: conversation.available,
        enabled: conversation.enabled,
        uiState: conversation.uiState,
        statusText: conversation.statusText,
      },
      sessionSummary: summary ? {
        status: summary.status || "",
        configured: summary.configured === true,
        enabled: summary.enabled === true,
        durable: summary.durable === true,
        hasSummary: Boolean(summary.summaryMarkdown),
        message: summary.message || "",
      } : null,
    };
  }));
}

async function refreshTabs({ selectStored = false } = {}) {
  const previousTabs = tabs;
  const previousTabsSignature = tabsSnapshotSignature(previousTabs);
  const previousTabsRenderSignature = tabsRenderSnapshotSignature(previousTabs);
  const previousActiveTabId = activeTabId;
  const response = await api("/api/tabs", { scoped: false });
  const nextTabs = response.data?.tabs || [];
  const tabsChanged = previousTabsSignature !== tabsSnapshotSignature(nextTabs);
  const tabsRenderChanged = previousTabsRenderSignature !== tabsRenderSnapshotSignature(nextTabs);
  if (tabsChanged) {
    tabs = nextTabs;
    syncTabMetadata(tabs);
    const liveParentTabIds = new Set(tabs.map((tab) => tab.id));
    for (const tabId of intercomConversationSummariesByTab.keys()) {
      if (!liveParentTabIds.has(tabId)) intercomConversationSummariesByTab.delete(tabId);
    }
    for (const view of [...subagentTerminalViews.values()]) {
      if (!liveParentTabIds.has(view.parentTabId)) removeSubagentTerminalViewsForParent(view.parentTabId);
    }
    syncBlockedTabNotificationsFromTabs(tabs, previousTabs);
    syncAgentDoneNotificationsFromTabs(tabs, previousTabs);
  }
  const requested = selectStored ? requestedTabIdFromUrl() : null;
  const stored = selectStored ? restoreStoredTabId() : null;
  if (!activeTabId || !tabs.some((tab) => tab.id === activeTabId)) {
    setActiveTabId((requested && tabs.some((tab) => tab.id === requested) ? requested : stored && tabs.some((tab) => tab.id === stored) ? stored : tabs[0]?.id) || null, { remember: true });
  }
  rememberServerStartCwd(tabs.find((tab) => tab.id === activeTabId)?.cwd || tabs[0]?.cwd);
  if (!tabs.length && previousTabs.length) {
    savedWorkspacesLoaded = false;
    savedWorkspacesError = "";
    setWorkspaceDashboardCollapsed(false, { persist: false });
  }
  renderSessionSkillTags(activeTabId);
  if (tabsRenderChanged || activeTabId !== previousActiveTabId || selectStored) renderTabs();
  else syncTabPolling();
  prefetchInactiveTabCommandCatalogs();
  return tabs;
}

async function switchTab(tabId) {
  if (!tabId || !tabs.some((tab) => tab.id === tabId)) return;
  if (tabId === activeTabId) {
    clearOpenTerminalTabGroup(null, { force: true });
    setMobileTabsExpanded(false);
    if (activeSubagentTerminalId) deactivateSubagentTerminalView({ focusParent: true });
    return;
  }
  if (themeCustomizerState?.saving) {
    setThemeCustomizerStatus("Wait for the theme save to finish before switching tabs.", "warn");
    return;
  }
  if (activeSubagentTerminalId) deactivateSubagentTerminalView({ render: false });
  if (themeCustomizerState) closeThemeCustomizer({ restore: true });
  clearOpenTerminalTabGroup(null, { force: true });
  setFollowUpQueueOpen(false);
  setFollowUpQueueStatus("");
  setMobileTabsExpanded(false);
  footerModelPickerOpen = false;
  footerThinkingPickerOpen = false;
  footerBranchPickerOpen = false;
  footerBranchPickerRequestSerial += 1;
  if (tabId === splitTabId) closeTerminalSplitView();
  saveActiveDraft();
  cacheMessagesForTab(activeTabId);
  cacheWidgetsForTab(activeTabId);
  cacheActiveFileViewerForTab(activeTabId);
  if (activeTabId && currentState) tabStateCache.set(activeTabId, currentState);
  if (activeTabId && latestStats) tabStatsCache.set(activeTabId, latestStats);
  if (activeTabId && latestWorkspace) tabWorkspaceCache.set(activeTabId, latestWorkspace);
  const tabContext = setActiveTabId(tabId, { remember: true });
  if (voiceConversation && voiceConversationTabId !== tabId) stopVoiceConversationLoop();
  resetActiveTabUi();
  renderTabs();
  restoreActiveDraft();
  focusPromptInput({ defer: true });
  connectEvents(tabContext);
  await refreshAll(tabContext);
  noteRecentFullRefresh();
  if (isCurrentTabContext(tabContext)) markTabOutputSeen();
  await refreshThemeCatalog(tabContext).catch((error) => addEvent(`Custom theme catalog refresh failed: ${error.message || String(error)}`, "warn"));
  if (!subagentLaunchSlotDraftIsDirty()) {
    loadSubagentLaunchSlotConfigWhenVisible({ tabId }).catch(() => {});
  } else {
    renderSubagentLaunchSlots();
  }
  refreshSamplingParametersForTabContext(tabContext);
}

function currentDirectoryForNewTab() {
  return latestWorkspace?.cwd || activeTab()?.cwd || "";
}

function terminalSplitTab() {
  return splitTabId ? tabs.find((tab) => tab.id === splitTabId) || null : null;
}

function terminalSplitFrameUrl(tabId) {
  const url = new URL("/", window.location.href);
  url.searchParams.set("embed", "split");
  url.searchParams.set("tab", tabId);
  return `${url.pathname}${url.search}`;
}

function updateTerminalSplitControls(canShowSplit, splitTab = terminalSplitTab()) {
  elements.tabBar?.querySelectorAll(".terminal-tab-split-button").forEach((button) => {
    const tabId = button.closest("[data-tab-id]")?.dataset?.tabId || "";
    const tab = tabs.find((candidate) => candidate.id === tabId);
    const isOpenSplit = canShowSplit && tabId === splitTab?.id;
    button.disabled = embeddedSplitMode || isSidePanelOverlayView() || !tab;
    button.setAttribute("aria-pressed", isOpenSplit ? "true" : "false");
    button.dataset.splitState = isOpenSplit ? "unsplit" : "split";
    const label = isOpenSplit
      ? `Close split view for ${tab?.title || "Pi terminal"}`
      : `Split ${tab?.title || "Pi terminal"} to the right`;
    applyStyledTooltip(button, label, { ariaLabel: label, targetKey: tabId ? `terminal-tab:${tabId}:split` : "" });
  });
}

function updateTerminalSplitUi() {
  const tab = terminalSplitTab();
  const overlayDrawerOpen = isControlDeckOverlayPresentation() && !document.body.classList.contains("side-panel-collapsed");
  const canShowSplit = !!tab && !embeddedSplitMode && !overlayDrawerOpen;
  document.body.classList.toggle("terminal-split-open", canShowSplit);
  if (elements.terminalSplitShell) elements.terminalSplitShell.hidden = !canShowSplit;
  scheduleControlDeckPresentationReconciliation();
  updateTerminalSplitControls(canShowSplit, tab);
  if (!canShowSplit) return;
  if (elements.terminalSplitTitle) elements.terminalSplitTitle.textContent = tab.title || "Split terminal";
  if (elements.terminalSplitMeta) elements.terminalSplitMeta.textContent = [tab.running ? `pid ${tab.pid || "starting"}` : "stopped", normalizeDisplayPath(tab.cwd || "")].filter(Boolean).join(" · ");
  if (elements.terminalSplitFrame && elements.terminalSplitFrame.dataset.tabId !== tab.id) {
    elements.terminalSplitFrame.dataset.tabId = tab.id;
    elements.terminalSplitFrame.src = terminalSplitFrameUrl(tab.id);
  }
}

function closeTerminalSplitView() {
  splitTabId = null;
  if (elements.terminalSplitFrame) {
    elements.terminalSplitFrame.removeAttribute("src");
    delete elements.terminalSplitFrame.dataset.tabId;
  }
  updateTerminalSplitUi();
}

function setTerminalSplitTab(tabId) {
  splitTabId = tabId || null;
  updateTerminalSplitUi();
}

function reconcileTerminalSplitState() {
  if (embeddedSplitMode) return;
  if (splitTabId && !tabs.some((tab) => tab.id === splitTabId)) {
    closeTerminalSplitView();
    return;
  }
  updateTerminalSplitUi();
}

async function splitTerminalTab(tabId, { triggerButton = null } = {}) {
  if (embeddedSplitMode) return;
  if (splitTabId === tabId) {
    closeTerminalSplitView();
    return;
  }
  const sourceTab = tabs.find((tab) => tab.id === tabId);
  if (!sourceTab) return;
  if (splitTabId) closeTerminalSplitView();
  let resolvedCwd = sourceTab.cwd || latestWorkspace?.cwd || currentDirectoryForNewTab();
  setMobileTabsExpanded(false);
  setNewTabMenuOpen(false);
  if (!resolvedCwd) {
    resolvedCwd = await pickCwd(sourceTab, "", { title: "Choose CWD for split terminal" });
    if (!resolvedCwd) return;
  }
  if (triggerButton) triggerButton.disabled = true;
  try {
    const response = await api("/api/tabs", { method: "POST", body: { cwd: resolvedCwd }, scoped: false });
    tabs = response.data?.tabs || tabs;
    syncTabMetadata(tabs);
    const tab = response.data?.tab;
    if (tab?.id) {
      setTerminalSplitTab(tab.id);
      renderTabs();
      addEvent(`split ${sourceTab.title || "terminal"} into independent ${tab.title}`, "info");
    }
  } catch (error) {
    addEvent(error.message, "error");
  } finally {
    if (triggerButton) triggerButton.disabled = false;
    updateTerminalSplitUi();
  }
}

async function createTerminalTab(cwd = currentDirectoryForNewTab(), { triggerButton = elements.newTabButton, customGroupId = null } = {}) {
  setMobileTabsExpanded(false);
  setNewTabMenuOpen(false);
  const resolvedCwd = cwd || currentDirectoryForNewTab();
  if (!resolvedCwd && tabs.length === 0) {
    await createTerminalTabFromChosenDirectory({ triggerButton });
    return;
  }
  const disabledButtons = new Set([elements.newTabButton, triggerButton].filter(Boolean));
  for (const button of disabledButtons) button.disabled = true;
  try {
    const response = await api("/api/tabs", { method: "POST", body: { cwd: resolvedCwd }, scoped: false });
    tabs = response.data?.tabs || tabs;
    syncTabMetadata(tabs);
    const tab = response.data?.tab;
    if (tab?.id && customGroupId && terminalCustomGroups.has(customGroupId)) addTabsToTerminalCustomGroup(customGroupId, [tab.id]);
    renderTabs();
    if (tab?.id) {
      await switchTab(tab.id);
      addEvent(`created isolated terminal ${tab.title}`, "info");
    }
  } catch (error) {
    addEvent(error.message, "error");
  } finally {
    for (const button of disabledButtons) button.disabled = false;
  }
}

async function createTerminalTabFromChosenDirectory({ triggerButton = elements.newTabChooseDirectoryButton } = {}) {
  const sourceTab = activeTab();
  const initialCwd = currentDirectoryForNewTab();
  setMobileTabsExpanded(false);
  setNewTabMenuOpen(false);
  const cwd = await pickCwd(sourceTab || { id: "new-tab", title: "new tab" }, initialCwd, { title: "Choose CWD for new tab" });
  if (!cwd) return;
  await createTerminalTab(cwd, { triggerButton });
}

async function createFirstTerminalTabFromChosenDirectory() {
  if (firstTerminalCwdPromptShown || tabs.length > 0) return;
  firstTerminalCwdPromptShown = true;
  const cwd = await pickCwd({ id: "first-terminal", title: "first terminal" }, "", { title: "Choose CWD for first terminal" });
  if (!cwd) {
    addEvent("choose a CWD to start the first terminal", "warn");
    return;
  }
  await createTerminalTab(cwd, { triggerButton: null });
}

function tabHasActiveAgent(tab) {
  const activity = activityForTab(tab);
  const indicator = tabIndicator(tab);
  return !!activity.isWorking || indicator.state === "working" || indicator.state === "blocked";
}

function activeTabHasConversationMessages(tab = activeTab()) {
  const tabId = tab?.id || activeTabId;
  if (!tabId) return false;
  if (tabId !== activeTabId && !latestMessagesSessionKey.startsWith(`${tabId}|`)) return false;
  return latestMessages.some((message) => ["user", "assistant"].includes(message?.role));
}

function shouldOpenCwdChangeInNewTab(tab) {
  return !!tab?.conversationStarted
    || activeTabHasConversationMessages(tab)
    || stateHasVisibleWork(currentState)
    || tabHasActiveAgent(tab);
}

async function confirmCloseTerminalTabs(targetTabs, label) {
  const count = targetTabs.length;
  const noun = count === 1 ? "tab" : "tabs";
  const activeAgentTabs = targetTabs.filter(tabHasActiveAgent);
  const tabList = targetTabs.map((tab) => `- ${tab.title}`).join("\n");
  const activeList = activeAgentTabs.map((tab) => `- ${tab.title} (${tabIndicator(tab).label})`).join("\n");
  const base = [
    `Close ${label || `${count} terminal ${noun}`}?`,
    "",
    `This terminates ${count === 1 ? "its isolated Pi process" : "their isolated Pi processes"}.`,
    count > 1 ? `\nTabs to close:\n${tabList}` : "",
  ].filter(Boolean).join("\n");
  const warning = activeAgentTabs.length
    ? `WARNING: ${activeAgentTabs.length} ${activeAgentTabs.length === 1 ? "tab has an agent" : "tabs have agents"} still running or waiting for input:\n${activeList}`
    : "No agent work is currently running in these tabs.";
  return appConfirm({
    title: `Close ${count === 1 ? "tab" : `${count} tabs`}?`,
    summary: `${base}\n\n${warning}`,
    affected: tabList || label || `${count} terminal ${noun}`,
    undoable: false,
    confirmLabel: activeAgentTabs.length ? "Close and stop work" : count === 1 ? "Close tab" : "Close tabs",
  });
}

async function reopenClosedTerminalTab(tabId) {
  const response = await api("/api/tabs/reopen", { method: "POST", body: { id: tabId }, scoped: false });
  await refreshTabs();
  const reopened = response.data?.tab?.id;
  if (reopened) await switchTab(reopened);
}

async function closeTerminalTabs(tabIds, { label = "selected terminal tabs", allowEmpty = false } = {}) {
  const targetIds = [...new Set(tabIds.filter(Boolean))];
  const targetTabs = targetIds.map((id) => tabs.find((item) => item.id === id)).filter(Boolean);
  if (!targetTabs.length) return;
  // Closing one idle tab is routine and reversible (its session stays resumable), so it closes at
  // once with an Undo instead of a confirmation. Anything with running work still asks first.
  const quickClose = targetTabs.length === 1 && !tabHasActiveAgent(targetTabs[0]) && !allowEmpty;
  if (!quickClose && !(await confirmCloseTerminalTabs(targetTabs, label))) return;

  const closedActiveTab = targetTabs.some((tab) => tab.id === activeTabId);
  const closedActiveCwd = closedActiveTab ? tabs.find((tab) => tab.id === activeTabId)?.cwd || "" : "";
  const fallbackTabId = tabs.find((item) => !targetIds.includes(item.id))?.id || null;
  for (const id of targetIds) closingTerminalTabIds.add(id);
  try {
    if (closedActiveTab) eventSource?.close();
    const response = await api("/api/tabs/close", { method: "POST", body: { ids: targetIds, allowEmpty }, scoped: false });
    const closedIds = response.data?.closedIds || targetIds;
    tabs = response.data?.tabs || tabs.filter((item) => !closedIds.includes(item.id));
    syncTabMetadata(tabs);
    for (const id of closedIds) {
      tabDrafts.delete(id);
      clearAttachments(id);
      clearGitWorkflowForTab(id);
      clearFeatureDecisionStateForTab(id);
      commandCatalogsByTab.delete(id);
      appRunnerDataByTab.delete(id);
      tabMessagesCache.delete(id);
      fileViewersByTab.delete(id);
      fileViewerSelectionsByTab.delete(id);
      btwWidgetDismissedIdsByTab.delete(id);
      removeSubagentTerminalViewsForParent(id);
    }
    syncTerminalCustomGroupsWithTabs(tabs);
    clearOpenTerminalTabGroup(null, { force: true });
    if (!tabs.length) setWorkspaceDashboardCollapsed(false, { persist: false });
    if (quickClose && closedIds.length === 1) {
      const closedTitle = targetTabs[0].title || "tab";
      offerUndo({
        message: `Closed ${closedTitle}.`,
        undo: () => reopenClosedTerminalTab(closedIds[0]),
        successMessage: `${closedTitle} reopened.`,
      });
    }

    const activeTabNeedsFallback = closedIds.includes(activeTabId) || !tabs.some((item) => item.id === activeTabId);
    if (activeTabNeedsFallback) {
      const sameCwdFallbackTabId = closedActiveCwd
        ? tabs.find((item) => !closedIds.includes(item.id) && item.cwd === closedActiveCwd)?.id || null
        : null;
      const tabContext = setActiveTabId((sameCwdFallbackTabId && tabs.some((item) => item.id === sameCwdFallbackTabId)
        ? sameCwdFallbackTabId
        : response.data?.activeTabId && tabs.some((item) => item.id === response.data.activeTabId)
          ? response.data.activeTabId
          : (fallbackTabId && tabs.some((item) => item.id === fallbackTabId) ? fallbackTabId : tabs[0]?.id)) || null, { remember: true });
      resetActiveTabUi();
      renderTabs();
      restoreActiveDraft();
      focusPromptInput({ defer: true });
      connectEvents(tabContext);
      if (activeTabId) {
        await refreshAll(tabContext);
        if (isCurrentTabContext(tabContext)) markTabOutputSeen();
      }
    } else {
      renderTabs();
    }
    addEvent(`closed ${closedIds.length || targetTabs.length} terminal ${closedIds.length === 1 ? "tab" : "tabs"}`, "info");
  } catch (error) {
    addEvent(error.message, "error");
  } finally {
    for (const id of targetIds) closingTerminalTabIds.delete(id);
  }
}

async function closeTerminalTab(tabId) {
  const tab = tabs.find((item) => item.id === tabId);
  if (!tab) return;
  await closeTerminalTabs([tabId], { label: tab.title });
}

async function closeTerminalTabGroup(group) {
  const title = terminalDisplayGroupTitle(group, group.tabs[0]?.title || "group");
  await closeTerminalTabs(group.tabs.map((tab) => tab.id), { label: `${title} group` });
}

async function closeAllTerminalTabs() {
  await closeTerminalTabs(tabs.map((tab) => tab.id), { label: "all terminal tabs", allowEmpty: true });
}

async function initializeTabs() {
  const loadedTabs = await refreshTabs({ selectStored: true });
  // Durable groups can arrive before the initial tab catalog. Rehydrate them
  // after tabs load so valid memberships are not filtered against an empty set.
  restoreTerminalCustomGroups();
  syncTerminalCustomGroupsWithTabs(tabs, { persist: false });
  restoreMobileContinuityState();
  restoreDesktopDrafts();
  resetActiveTabUi();
  renderTabs();
  restoreActiveDraft();
  if (!loadedTabs.length) {
    setWorkspaceDashboardCollapsed(false, { persist: false });
    const saved = await refreshSavedWorkspaces().catch((error) => {
      addEvent(`Could not list saved workspaces: ${error.message || String(error)}`, "error");
      return [];
    });
    if (!saved.length) await createFirstTerminalTabFromChosenDirectory();
    await refreshThemeCatalog(activeTabContext()).catch((error) => addEvent(`Custom theme catalog refresh failed: ${error.message || String(error)}`, "warn"));
    return;
  }
  focusPromptInput({ defer: true });
  const tabContext = activeTabContext();
  connectEvents(tabContext);
  if (activeTabId) {
    await refreshAll(tabContext);
    noteRecentFullRefresh();
    if (isCurrentTabContext(tabContext)) markTabOutputSeen();
    if (!subagentLaunchSlotDraftIsDirty() || subagentLaunchSlotConfigTabId !== activeTabId) {
      loadSubagentLaunchSlotConfigWhenVisible().catch(() => {});
    }
    refreshSamplingParametersForTabContext(tabContext);
    await refreshThemeCatalog(tabContext).catch((error) => addEvent(`Custom theme catalog refresh failed: ${error.message || String(error)}`, "warn"));
  }
}

function chatEventTargetForLine(line) {
  const toolCallId = line?.dataset.chatToolCallId || "";
  if (toolCallId) {
    const toolTarget = elements.chat.querySelector(`.message[data-tool-call-id="${CSS.escape(toolCallId)}"]`);
    if (toolTarget) return toolTarget;
  }

  const eventTimestamp = Number(line?.dataset.chatEventTimestamp);
  let closestTarget = null;
  let closestDistance = Number.POSITIVE_INFINITY;
  for (const candidate of elements.chat.querySelectorAll(".message[data-chat-timestamp]")) {
    const candidateTimestamp = Number(candidate.dataset.chatTimestamp);
    if (!Number.isFinite(eventTimestamp) || !Number.isFinite(candidateTimestamp)) continue;
    const distance = Math.abs(candidateTimestamp - eventTimestamp);
    if (distance <= closestDistance) {
      closestTarget = candidate;
      closestDistance = distance;
    }
  }
  return closestTarget || Array.from(elements.chat.querySelectorAll(".message:not(.runIndicator)")).at(-1) || null;
}

function highlightChatEventTarget(target) {
  clearTimeout(target._chatEventHighlightTimer);
  target.classList.remove("chat-event-target");
  void target.offsetWidth;
  target.classList.add("chat-event-target");
  target._chatEventHighlightTimer = setTimeout(() => target.classList.remove("chat-event-target"), 1600);
}

function jumpToChatEvent(line) {
  const revealTarget = () => {
    const target = chatEventTargetForLine(line);
    if (!target) return;
    autoFollowChat = false;
    lastChatProgrammaticScrollAt = performance.now();
    const centeredTop = chatScrollTopForNode(target) - Math.max(stickyUserPromptViewportGap(), (elements.chat.clientHeight - target.offsetHeight) / 2);
    setChatScrollTopInstant(Math.max(0, centeredTop));
    highlightChatEventTarget(target);
    updateJumpToLatestButton();
    updateStickyUserPromptButton();
  };

  if (isSidePanelOverlayView() && !document.body.classList.contains("side-panel-collapsed")) {
    setSidePanelCollapsed(true, { persist: false });
    requestAnimationFrame(revealTarget);
  } else {
    revealTarget();
  }
}

const TOOL_EVENT_TARGET_FIELDS = new Map([
  ["read", "path"],
  ["write", "path"],
  ["edit", "path"],
  ["grep", "path"],
  ["find", "path"],
  ["ls", "path"],
]);

function boundedToolEventTarget(event) {
  const toolName = String(event?.toolName || "").trim().toLowerCase();
  const field = TOOL_EVENT_TARGET_FIELDS.get(toolName);
  if (!field) return "";
  const args = event?.args ?? event?.arguments ?? event?.invocation?.args;
  const value = args && typeof args === "object" && !Array.isArray(args) ? args[field] : "";
  if (typeof value !== "string") return "";
  const singleLine = value.replace(/[\u0000-\u001f\u007f]+/g, " ").trim();
  return singleLine.length > 96 ? `${singleLine.slice(0, 93)}…` : singleLine;
}

function shortenedToolCallId(value) {
  const id = String(value || "").trim();
  if (!id) return "";
  return id.length <= 14 ? id : `${id.slice(0, 7)}…${id.slice(-5)}`;
}

function toolEventTimerKey(event) {
  const toolCallId = String(event?.toolCallId || "").trim();
  return toolCallId ? `${event?.tabId || activeTabId || "tab"}:${toolCallId}` : "";
}

function toolEventDurationMs(event, phase, occurredAt) {
  if (phase !== "finish") return null;
  const reportedDurationMs = Number(event?.durationMs);
  if (Number.isFinite(reportedDurationMs) && reportedDurationMs >= 0) return reportedDurationMs;
  const startedAt = toolEventStartedAt.get(toolEventTimerKey(event))?.startedAt;
  return Number.isFinite(startedAt) ? Math.max(0, occurredAt - startedAt) : null;
}

function formatToolEventDuration(durationMs) {
  if (!Number.isFinite(durationMs)) return "";
  if (durationMs < 1000) return `${Math.round(durationMs)} ms`;
  if (durationMs < 10_000) return `${(durationMs / 1000).toFixed(1)} s`;
  return `${Math.round(durationMs / 1000)} s`;
}

function toolLifecycleEventDetails(event, phase, occurredAt) {
  const status = phase === "start" ? "started" : event?.isError ? "failed" : "finished";
  const startRecord = phase === "finish" ? toolEventStartedAt.get(toolEventTimerKey(event)) : null;
  const target = boundedToolEventTarget(event) || startRecord?.target || "";
  const duration = formatToolEventDuration(toolEventDurationMs(event, phase, occurredAt));
  const callId = shortenedToolCallId(event?.toolCallId);
  return [
    target ? { label: "target", value: target } : null,
    { label: "status", value: status, tone: event?.isError ? "error" : phase === "finish" ? "success" : "info" },
    duration ? { label: "duration", value: duration } : null,
    callId ? { label: "call", value: callId } : null,
  ].filter(Boolean);
}

function toolLifecycleEventArguments(event, phase) {
  const occurredAt = Date.now();
  const timerKey = toolEventTimerKey(event);
  if (phase === "start" && timerKey) {
    toolEventStartedAt.set(timerKey, { startedAt: occurredAt, target: boundedToolEventTarget(event) });
    while (toolEventStartedAt.size > 240) toolEventStartedAt.delete(toolEventStartedAt.keys().next().value);
  }
  const toolName = runIndicatorToolName(event?.toolName || "tool");
  const status = phase === "start" ? "started" : event?.isError ? "failed" : "finished";
  const args = [`tool ${toolName} ${status}`, event?.isError ? "error" : "info", {
    toolCallId: event?.toolCallId,
    toolEventPhase: phase,
    details: toolLifecycleEventDetails(event, phase, occurredAt),
    occurredAt,
  }];
  if (phase === "finish" && timerKey) toolEventStartedAt.delete(timerKey);
  return args;
}

function normalizeEventDisplayMode(value) {
  return value === "compact" ? "compact" : "detailed";
}

function readStoredEventDisplayMode() {
  try {
    return normalizeEventDisplayMode(localStorage.getItem(EVENT_DISPLAY_MODE_STORAGE_KEY));
  } catch {
    return "detailed";
  }
}

function normalizeEventFilter(value) {
  return EVENT_FILTER_VALUES.has(value) ? value : "all";
}

function readStoredEventFilter() {
  try {
    return normalizeEventFilter(localStorage.getItem(EVENT_FILTER_STORAGE_KEY));
  } catch {
    return "all";
  }
}

function eventRowMatchesFilter(line, filter = eventFilter) {
  if (!line?.classList?.contains("event") || filter === "all") return true;
  if (filter === "errors") return line.dataset.eventLevel === "error";
  if (filter === "warnings") return line.dataset.eventLevel === "warn";
  if (filter === "tools") return ["start", "finish"].includes(line.dataset.eventToolPhase);
  if (filter === "tree") return line.dataset.eventTreeAvailable === "true";
  return true;
}

function applyEventFilter() {
  const rows = [...(elements.eventLog?.children || [])].filter((line) => line.classList?.contains("event"));
  let shown = 0;
  for (const line of rows) {
    const matches = eventRowMatchesFilter(line);
    line.hidden = !matches;
    if (matches) shown += 1;
  }
  const total = rows.length;
  if (elements.eventFilterStatus) {
    elements.eventFilterStatus.textContent = total === 0
      ? "No events yet"
      : eventFilter === "all"
        ? `${total} event${total === 1 ? "" : "s"}`
        : `${shown} of ${total}`;
  }
  if (elements.eventFilterEmpty) {
    elements.eventFilterEmpty.hidden = total === 0 || shown > 0;
    const label = elements.eventFilterSelect?.selectedOptions?.[0]?.textContent?.trim() || "this filter";
    elements.eventFilterEmpty.textContent = `No events match ${label.toLowerCase()}.`;
  }
}

function syncEventFilterUi() {
  if (elements.eventFilterSelect) elements.eventFilterSelect.value = eventFilter;
  applyEventFilter();
}

function setEventFilter(value, { persist = true } = {}) {
  eventFilter = normalizeEventFilter(value);
  syncEventFilterUi();
  if (!persist) return;
  try {
    localStorage.setItem(EVENT_FILTER_STORAGE_KEY, eventFilter);
  } catch {
    // The filter remains active for this page when storage is unavailable.
  }
}

function syncEventDisplayModeUi() {
  if (elements.eventLog) elements.eventLog.dataset.displayMode = eventDisplayMode;
  elements.eventDisplayDetailedAction?.setAttribute("aria-checked", String(eventDisplayMode === "detailed"));
  elements.eventDisplayCompactAction?.setAttribute("aria-checked", String(eventDisplayMode === "compact"));
}

function setEventDisplayMode(value, { persist = true } = {}) {
  eventDisplayMode = normalizeEventDisplayMode(value);
  syncEventDisplayModeUi();
  if (!persist) return;
  try {
    localStorage.setItem(EVENT_DISPLAY_MODE_STORAGE_KEY, eventDisplayMode);
  } catch {
    // Display mode remains active for this page when storage is unavailable.
  }
}

function addEvent(message, level = "info", { toolCallId = "", toolEventPhase = "", details = [], notify = true, occurredAt = Date.now(), aggregateKey = "", aggregateIncrement = 1, aggregateSingular = "", aggregatePlural = "" } = {}) {
  const stableAggregateKey = String(aggregateKey || "").trim();
  const priorAggregate = stableAggregateKey
    ? [...(elements.eventLog?.children || [])].find((candidate) => candidate.dataset.eventAggregateKey === stableAggregateKey)
    : null;
  const aggregateCount = stableAggregateKey
    ? Math.max(0, Number.parseInt(priorAggregate?.dataset.eventAggregateCount || "0", 10) || 0) + Math.max(1, Math.trunc(Number(aggregateIncrement) || 1))
    : 0;
  const eventMessage = stableAggregateKey && aggregateSingular
    ? `${message} ${aggregateCount} ${aggregateCount === 1 ? aggregateSingular : aggregatePlural || aggregateSingular}`
    : String(message || "");
  priorAggregate?.remove();
  const line = make("button", `event ${level}`.trim());
  line.type = "button";
  line.dataset.eventLevel = String(level || "info").trim().toLowerCase() || "info";
  line.dataset.chatEventTimestamp = String(occurredAt);
  if (stableAggregateKey) {
    line.dataset.eventAggregateKey = stableAggregateKey;
    line.dataset.eventAggregateCount = String(aggregateCount);
  }
  const stableToolCallId = String(toolCallId || "").trim();
  const toolLifecycle = ["start", "finish"].includes(toolEventPhase);
  const treeEligible = stableToolCallId && toolLifecycle;
  line.dataset.eventTreeAvailable = String(!!treeEligible);
  if (stableToolCallId) line.dataset.chatToolCallId = stableToolCallId;
  if (toolLifecycle) line.dataset.eventToolPhase = toolEventPhase;
  line.setAttribute("aria-keyshortcuts", "ContextMenu Shift+F10");
  const time = make("span", "event-time", `[${new Date(occurredAt).toLocaleTimeString()}]`);
  const summary = make("span", "event-summary", eventMessage);
  const main = make("span", "event-main");
  main.append(time, summary);
  line.append(main);
  if (Array.isArray(details) && details.length) {
    const meta = make("span", "event-details");
    for (const detail of details) {
      if (!detail?.label || !detail?.value) continue;
      const item = make("span", `event-detail${detail.tone ? ` ${detail.tone}` : ""}`);
      item.append(make("span", "event-detail-label", `${detail.label}:`), document.createTextNode(` ${detail.value}`));
      meta.append(item);
    }
    if (meta.childElementCount) line.append(meta);
  }
  const accessibleText = line.textContent.trim();
  line.title = `Jump to this event in the chat; open the context menu for display options${treeEligible ? " and Tree navigation" : ""}`;
  line.setAttribute("aria-label", `${accessibleText}. Jump to this event in the chat. Context menu: display options${treeEligible ? " and Tree navigation" : ""}.`);
  line.addEventListener("click", () => jumpToChatEvent(line));
  elements.eventLog.prepend(line);
  while (elements.eventLog.children.length > 120) elements.eventLog.lastElementChild?.remove();
  applyEventFilter();
  if (notify && (level === "error" || level === "warn")) {
    showNoticeToast(eventMessage, level);
    noteUnreadEvent();
  }
}

function closeEventTreeContextMenu({ returnFocus = true } = {}) {
  const trigger = eventTreeContextMenuState?.trigger;
  eventTreeContextMenuState = null;
  if (elements.eventTreeContextMenu) elements.eventTreeContextMenu.hidden = true;
  if (elements.eventTreeContextMenuAction) elements.eventTreeContextMenuAction.disabled = false;
  if (returnFocus && trigger?.isConnected) queueMicrotask(() => trigger.focus({ preventScroll: true }));
}

function setEventTreeContextMenuStatus(message = "", level = "info") {
  const status = elements.eventTreeContextMenuStatus;
  if (!status) return;
  status.textContent = message;
  status.hidden = !message;
  status.className = `event-tree-context-menu-status ${level}`;
}

function closeOtherContextMenusForEventTree() {
  closeFileContextMenu({ returnFocus: false });
  closeGitPanelContextMenu({ returnFocus: false });
  closeSidePanelContextMenu({ returnFocus: false });
  closeVisibilityContextMenu({ returnFocus: false });
  closeGitFooterContextMenu({ returnFocus: false });
  closeEventTreeContextMenu({ returnFocus: false });
}

function showEventTreeContextMenu(event, line = null) {
  const menu = elements.eventTreeContextMenu;
  if (!menu || (line && !elements.eventLog?.contains(line))) return;
  const toolCallId = String(line?.dataset.chatToolCallId || "").trim();
  const phase = line?.dataset.eventToolPhase || "";
  const treeEligible = !!toolCallId && ["start", "finish"].includes(phase);
  event.preventDefault();
  event.stopPropagation();
  closeOtherContextMenusForEventTree();
  eventTreeContextMenuState = {
    trigger: line,
    toolCallId,
    phase,
    tabContext: treeEligible ? activeTabContext() : null,
    busy: false,
    openedAt: performance.now(),
  };
  setEventTreeContextMenuStatus("");
  syncEventDisplayModeUi();
  if (elements.eventTreeContextMenuAction) elements.eventTreeContextMenuAction.hidden = !treeEligible;
  menu.hidden = false;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(Number(event.clientX) || 0, Math.max(8, window.innerWidth - rect.width - 8));
  const top = Math.min(Number(event.clientY) || 0, Math.max(8, window.innerHeight - rect.height - 8));
  menu.style.left = `${Math.max(8, left)}px`;
  menu.style.top = `${Math.max(8, top)}px`;
  const displayAction = eventDisplayMode === "compact" ? elements.eventDisplayCompactAction : elements.eventDisplayDetailedAction;
  displayAction?.focus({ preventScroll: true });
}

function eventTreeTargetEntryId(data, state) {
  const targets = Array.isArray(data?.eventTargets) ? data.eventTargets : [];
  const target = targets.find((item) => String(item?.toolCallId || "") === state.toolCallId);
  const entryId = state.phase === "start" ? target?.startEntryId : target?.finishEntryId || target?.startEntryId;
  if (typeof entryId !== "string" || !entryId.trim()) return "";
  const nodes = Array.isArray(data?.nodes) ? data.nodes : [];
  return nodes.some((node) => node?.id === entryId) ? entryId : "";
}

async function navigateEventTreeBoundary() {
  const state = eventTreeContextMenuState;
  const action = elements.eventTreeContextMenuAction;
  if (!state || state.busy || !action || !isCurrentTabContext(state.tabContext)) return;
  state.busy = true;
  action.disabled = true;
  setEventTreeContextMenuStatus("Resolving this tool boundary…");
  try {
    const tree = await api("/api/session-tree", { tabId: state.tabContext.tabId });
    if (eventTreeContextMenuState !== state || !isCurrentTabContext(state.tabContext)) return;
    const entryId = eventTreeTargetEntryId(tree.data, state);
    if (!entryId) {
      setEventTreeContextMenuStatus("This tool boundary is not available in the current persisted session tree.", "warn");
      addEvent("Tree navigation target is unavailable or stale; the session was not changed.", "warn");
      return;
    }
    setEventTreeContextMenuStatus("");
    const confirmed = await appConfirm({
      title: "Navigate to this tool boundary?",
      summary: "This changes the current session branch. Later entries stay in the tree, and no automatic branch summary is generated.",
      affected: "Use /tree to navigate back or choose another branch.",
      undoable: true,
      confirmLabel: "Navigate",
      danger: false,
    });
    if (eventTreeContextMenuState !== state || !isCurrentTabContext(state.tabContext)) return;
    if (!confirmed) {
      setEventTreeContextMenuStatus("Navigation cancelled; the session was not changed.");
      return;
    }
    setEventTreeContextMenuStatus("Navigating…");
    const result = await api("/api/tree-navigate", {
      method: "POST",
      body: { entryId, summarize: false },
      tabId: state.tabContext.tabId,
    });
    if (!isCurrentTabContext(state.tabContext)) return;
    applyResponseTab(result);
    addTransientMessage({ role: "native", title: "/tree", content: result.data?.message || "Navigated to the selected tool boundary.", level: "info" });
    if (eventTreeContextMenuState === state) closeEventTreeContextMenu();
    await refreshAll(state.tabContext);
  } catch (error) {
    if (eventTreeContextMenuState === state && isCurrentTabContext(state.tabContext)) {
      const message = error?.message || String(error);
      setEventTreeContextMenuStatus(`Navigation failed: ${message}`, "error");
      addEvent(`Tree navigation failed: ${message}`, "error");
    }
  } finally {
    if (eventTreeContextMenuState === state) {
      state.busy = false;
      action.disabled = false;
      action.focus({ preventScroll: true });
    }
  }
}

// --- Non-blocking warn/error notices -------------------------------------------------------
// The Events log lives in a collapsed Control Deck section, so on its own it makes failures look
// like "nothing happened". Warnings and errors additionally surface as a short-lived toast (max 3,
// deduplicated) with a shortcut to the Events log, and the Events header shows an unread count.
function noticeToastTimeout(level) {
  return NOTICE_TOAST_TIMEOUT_MS[level] || (level === "error" ? NOTICE_TOAST_TIMEOUT_MS.error : NOTICE_TOAST_TIMEOUT_MS.warn);
}

function removeNoticeToast(entry) {
  const index = noticeToasts.indexOf(entry);
  if (index >= 0) noticeToasts.splice(index, 1);
  clearTimeout(entry.timer);
  entry.node.remove();
}

function armNoticeToastTimer(entry) {
  clearTimeout(entry.timer);
  entry.timer = setTimeout(() => removeNoticeToast(entry), noticeToastTimeout(entry.level));
}

function showNoticeToast(message, level = "warn") {
  const stack = elements.noticeToastStack;
  const text = String(message || "").trim();
  if (!stack || !text) return null;
  const existing = noticeToasts.find((entry) => entry.level === level && entry.text === text);
  if (existing) {
    existing.count += 1;
    existing.countNode.textContent = `×${existing.count}`;
    existing.countNode.hidden = false;
    armNoticeToastTimer(existing);
    return existing;
  }
  const node = make("div", `notice-toast ${level}`);
  node.setAttribute("role", level === "error" ? "alert" : "status");
  const messageNode = make("span", "notice-toast-message", text);
  const countNode = make("span", "notice-toast-count", "");
  countNode.hidden = true;
  messageNode.append(countNode);
  const eventsButton = make("button", "notice-toast-events", "Events");
  eventsButton.type = "button";
  eventsButton.title = "Open the Events log in the Control Deck";
  const dismissButton = make("button", "notice-toast-dismiss", "×");
  dismissButton.type = "button";
  dismissButton.setAttribute("aria-label", "Dismiss notification");
  node.append(messageNode, eventsButton, dismissButton);
  const entry = { node, level, text, count: 1, countNode, timer: null };
  eventsButton.addEventListener("click", () => {
    removeNoticeToast(entry);
    revealEventsSection();
  });
  dismissButton.addEventListener("click", () => removeNoticeToast(entry));
  node.addEventListener("pointerenter", () => clearTimeout(entry.timer));
  node.addEventListener("pointerleave", () => armNoticeToastTimer(entry));
  noticeToasts.push(entry);
  stack.append(node);
  while (noticeToasts.length > NOTICE_TOAST_LIMIT) removeNoticeToast(noticeToasts[0]);
  armNoticeToastTimer(entry);
  return entry;
}

function eventsSectionRecord() {
  return sidePanelSectionRecords().find((record) => record.id === "events") || null;
}

function eventsSectionIsVisibleAndExpanded() {
  const record = eventsSectionRecord();
  if (!record || record.section.hidden || record.section.classList.contains("collapsed")) return false;
  return !document.body.classList.contains("side-panel-collapsed") || document.body.classList.contains("control-deck-left");
}

function renderEventsUnreadBadge() {
  const badge = elements.eventsUnreadBadge;
  if (!badge) return;
  badge.textContent = eventsUnreadCount > 99 ? "99+" : String(eventsUnreadCount);
  badge.hidden = eventsUnreadCount === 0;
  badge.setAttribute("aria-label", `${eventsUnreadCount} unread warning${eventsUnreadCount === 1 ? "" : "s"} or errors`);
}

function noteUnreadEvent() {
  if (eventsSectionIsVisibleAndExpanded()) return;
  eventsUnreadCount += 1;
  renderEventsUnreadBadge();
}

function clearUnreadEvents() {
  if (!eventsUnreadCount) return;
  eventsUnreadCount = 0;
  renderEventsUnreadBadge();
}

function revealSidePanelSectionById(id) {
  const record = sidePanelSectionRecords().find((entry) => entry.id === id);
  if (!record) return;
  if (record.section.hidden) setSidePanelSectionVisible(record, true);
  if (document.body.classList.contains("side-panel-collapsed") && !document.body.classList.contains("control-deck-left")) setSidePanelCollapsed(false, { focusPanel: true });
  if (record.section.classList.contains("collapsed")) setSidePanelSectionCollapsed(record, false);
  queueMicrotask(() => {
    record.section.scrollIntoView?.({ block: "nearest" });
    record.button?.focus?.({ preventScroll: true });
  });
}

function revealEventsSection() {
  const record = eventsSectionRecord();
  if (!record) return;
  if (record.section.hidden) setSidePanelSectionVisible(record, true);
  if (document.body.classList.contains("side-panel-collapsed") && !document.body.classList.contains("control-deck-left")) setSidePanelCollapsed(false);
  if (record.section.classList.contains("collapsed")) setSidePanelSectionCollapsed(record, false);
  clearUnreadEvents();
  queueMicrotask(() => record.section.scrollIntoView?.({ block: "nearest" }));
}

function browserNotificationSupported() {
  return "Notification" in window && window.isSecureContext;
}

function browserNotificationPermission() {
  if (!("Notification" in window)) return "unsupported";
  return Notification.permission || "default";
}

function blockedTabNotificationSupported() {
  return browserNotificationSupported();
}

function blockedTabNotificationPermission() {
  return browserNotificationPermission();
}

async function ensureBlockedTabNotificationPermission() {
  if (!blockedTabNotificationSupported()) return false;
  if (Notification.permission === "granted") return true;
  if (Notification.permission === "denied" || blockedTabNotificationPermissionRequested || typeof Notification.requestPermission !== "function") return false;

  blockedTabNotificationPermissionRequested = true;
  try {
    const permission = await Notification.requestPermission();
    if (permission === "granted") {
      addEvent("browser notifications enabled for blocked tabs", "info");
      return true;
    }
  } catch (error) {
    addEvent(`blocked-tab notification permission request failed: ${error.message}`, "warn");
  }
  return false;
}

async function ensureAgentDoneNotificationPermission() {
  if (!browserNotificationSupported()) return false;
  if (Notification.permission === "granted") return true;
  if (Notification.permission === "denied" || agentDoneNotificationPermissionRequested || typeof Notification.requestPermission !== "function") return false;

  agentDoneNotificationPermissionRequested = true;
  try {
    const permission = await Notification.requestPermission();
    if (permission === "granted") {
      addEvent("browser notifications enabled for completed agent work", "info");
      return true;
    }
  } catch (error) {
    addEvent(`agent-done notification permission request failed: ${error.message}`, "warn");
  }
  return false;
}

function noteBlockedTabNotificationFallback(reason) {
  if (blockedTabNotificationFallbackNoted) return;
  blockedTabNotificationFallbackNoted = true;
  addEvent(`browser notifications unavailable for blocked tabs: ${reason}`, "warn");
}

function blockedTabNotificationDetail({ method, count } = {}) {
  if (method) return `waiting for your ${method} response`;
  if (count > 1) return `waiting for ${count} responses`;
  return "waiting for your response";
}

function blockedTabNotificationKey(tabId, request) {
  return request?.id ? `${tabId}:${request.id}` : `${tabId}:blocked`;
}

function mobileNotificationTarget({ route = "activity", tabId, runId, blockerId } = {}) {
  return normalizeMobileNavigationTarget({ v: 1, route, tabId, runId, blockerId });
}

function clearBlockedTabNotificationKeys(tabId) {
  if (!tabId) return;
  const prefix = `${tabId}:`;
  blockedTabNotificationKeys = new Set([...blockedTabNotificationKeys].filter((key) => !key.startsWith(prefix)));
}

async function showBlockedTabBrowserNotification({ tabId, title, body, method, count, blockerId }) {
  if (!blockedTabNotificationSupported()) {
    noteBlockedTabNotificationFallback("requires HTTPS or localhost");
    return false;
  }
  if (!(await ensureBlockedTabNotificationPermission())) {
    const permission = blockedTabNotificationPermission();
    noteBlockedTabNotificationFallback(permission === "denied" ? "permission denied" : "permission not granted");
    return false;
  }

  const options = {
    body,
    tag: `${BLOCKED_TAB_NOTIFICATION_TAG_PREFIX}:${tabId}`,
    renotify: true,
    requireInteraction: true,
    icon: BLOCKED_TAB_NOTIFICATION_ICON,
    badge: BLOCKED_TAB_NOTIFICATION_ICON,
    data: { target: mobileNotificationTarget({ route: "activity", tabId, blockerId }) },
  };

  try {
    let registration = null;
    if ("serviceWorker" in navigator) {
      registration = await Promise.race([navigator.serviceWorker.ready, delay(1200).then(() => null)]).catch(() => null);
    }
    if (registration?.showNotification) {
      await registration.showNotification(title, options);
      return true;
    }

    const notification = new Notification(title, options);
    notification.onclick = () => {
      window.focus();
      const target = mobileNotificationTarget({ route: "activity", tabId, blockerId });
      if (target) receiveMobileNavigationTarget(target);
      notification.close();
    };
    return true;
  } catch (error) {
    noteBlockedTabNotificationFallback(error.message || "notification failed");
    return false;
  }
}

function notifyBlockedTab(tabOrId, { request = null, count } = {}) {
  const tabId = typeof tabOrId === "string" ? tabOrId : tabOrId?.id || request?.tabId || activeTabId;
  if (!tabId || request?.replayed) return;
  const tab = typeof tabOrId === "object" && tabOrId !== null ? tabOrId : tabs.find((item) => item.id === tabId);
  const key = blockedTabNotificationKey(tabId, request);
  if (blockedTabNotificationKeys.has(key)) return;
  blockedTabNotificationKeys.add(key);

  const pendingCount = normalizePendingExtensionUiRequestCount(count ?? request?.pendingExtensionUiRequestCount ?? tabPendingBlockerCount(tab));
  const method = request?.method && EXTENSION_UI_BLOCKING_METHODS.has(request.method) ? request.method : "";
  const tabTitle = tab?.title || request?.tabTitle || "terminal";
  const detail = blockedTabNotificationDetail({ method, count: pendingCount });
  const title = "Pi needs your response";
  const body = `${tabTitle} is blocked, ${detail}.`;
  addEvent(`${tabTitle} blocked: ${detail}`, "warn");
  showBlockedTabBrowserNotification({ tabId, title, body, method, count: pendingCount, blockerId: request?.id });
}

function noteAgentDoneNotificationFallback(reason) {
  if (agentDoneNotificationFallbackNoted) return;
  agentDoneNotificationFallbackNoted = true;
  addEvent(`browser notifications unavailable for completed agent work: ${reason}`, "warn");
}

async function showAgentDoneBrowserNotification({ tabId, title, body, runId }) {
  if (!agentDoneNotificationsEnabled) return false;
  if (!browserNotificationSupported()) {
    noteAgentDoneNotificationFallback("requires HTTPS or localhost");
    renderAgentDoneNotificationsToggle();
    return false;
  }
  if (!(await ensureAgentDoneNotificationPermission())) {
    const permission = browserNotificationPermission();
    noteAgentDoneNotificationFallback(permission === "denied" ? "permission denied" : "permission not granted");
    if (permission !== "granted") {
      agentDoneNotificationsEnabled = false;
      persistAgentDoneNotificationsEnabled(false);
    }
    renderAgentDoneNotificationsToggle();
    return false;
  }

  const options = {
    body,
    tag: `${AGENT_DONE_NOTIFICATION_TAG_PREFIX}:${tabId}`,
    renotify: true,
    requireInteraction: false,
    icon: BLOCKED_TAB_NOTIFICATION_ICON,
    badge: BLOCKED_TAB_NOTIFICATION_ICON,
    data: { target: mobileNotificationTarget({ route: "activity", tabId, runId }) },
  };

  try {
    let registration = null;
    if ("serviceWorker" in navigator) {
      registration = await Promise.race([navigator.serviceWorker.ready, delay(1200).then(() => null)]).catch(() => null);
    }
    if (registration?.showNotification) {
      await registration.showNotification(title, options);
      return true;
    }

    const notification = new Notification(title, options);
    notification.onclick = () => {
      window.focus();
      const target = mobileNotificationTarget({ route: "activity", tabId, runId });
      if (target) receiveMobileNavigationTarget(target);
      notification.close();
    };
    return true;
  } catch (error) {
    noteAgentDoneNotificationFallback(error.message || "notification failed");
    return false;
  }
}

function agentDoneNotificationKey(tabId, activity = {}) {
  const serial = Number(activity?.completionSerial);
  return `${tabId}:${Number.isFinite(serial) && serial > 0 ? serial : "done"}`;
}

function isAutoRetryingTab(tabId) {
  return !!tabId && autoRetryingTabs.has(tabId);
}

function clearPendingAgentDoneNotification(key, { markSeen = false } = {}) {
  const pending = pendingAgentDoneNotificationTimers.get(key);
  if (!pending) return false;
  clearTimeout(pending.timer);
  pendingAgentDoneNotificationTimers.delete(key);
  if (markSeen) agentDoneNotificationKeys.add(key);
  return true;
}

function suppressPendingAgentDoneNotificationsForTab(tabId, { markSeen = true } = {}) {
  if (!tabId) return;
  for (const [key, pending] of pendingAgentDoneNotificationTimers) {
    if (pending.tabId === tabId) clearPendingAgentDoneNotification(key, { markSeen });
  }
}

function queueAgentDoneBrowserNotification({ key, tabId, title, body, runId }) {
  clearPendingAgentDoneNotification(key);
  const timer = setTimeout(() => {
    pendingAgentDoneNotificationTimers.delete(key);
    const tab = tabs.find((item) => item.id === tabId);
    if (isAutoRetryingTab(tabId) || promptRoutingTabs.has(tabId) || activityForTab(tab).isWorking) return;
    showAgentDoneBrowserNotification({ tabId, title, body, runId });
  }, AGENT_DONE_NOTIFICATION_RETRY_GRACE_MS);
  pendingAgentDoneNotificationTimers.set(key, { tabId, timer });
}

function notifyAgentDone(tabOrId, { activity = null, tabTitle = "" } = {}) {
  if (!agentDoneNotificationsEnabled) return;
  const tabId = typeof tabOrId === "string" ? tabOrId : tabOrId?.id || activeTabId;
  if (!tabId) return;
  const tab = typeof tabOrId === "object" && tabOrId !== null ? tabOrId : tabs.find((item) => item.id === tabId);
  const normalizedActivity = normalizeTabActivity(activity || tab?.activity || activityForTab(tab));
  if (!normalizedActivity.completionSerial) return;
  const key = agentDoneNotificationKey(tabId, normalizedActivity);
  if (agentDoneNotificationKeys.has(key)) return;
  agentDoneNotificationKeys.add(key);
  if (isAutoRetryingTab(tabId)) return;

  const displayTitle = tabTitle || tab?.title || "terminal";
  const failed = normalizedActivity.status === "failed" || normalizedActivity.failed === true || tab?.failed === true;
  queueAgentDoneBrowserNotification({
    key,
    tabId,
    title: failed ? "Pi work failed" : "Pi finished work",
    body: failed ? `${displayTitle} failed. Open Activity to review.` : `${displayTitle} finished its agent run.`,
    runId: normalizedActivity.runId,
  });
}

function syncAgentDoneNotificationsFromTabs(nextTabs = [], previousTabs = []) {
  if (!agentDoneNotificationsEnabled || previousTabs.length === 0) return;
  const previousSerials = new Map(previousTabs.filter((tab) => tab?.id).map((tab) => [tab.id, normalizeTabActivity(tab.activity).completionSerial]));
  for (const tab of nextTabs) {
    if (!tab?.id || !previousSerials.has(tab.id)) continue;
    const activity = normalizeTabActivity(tab.activity);
    if (!activity.isWorking && activity.completionSerial > previousSerials.get(tab.id)) notifyAgentDone(tab, { activity: tab.failed === true ? { ...activity, failed: true } : activity });
  }
}

function syncBlockedTabNotificationsFromTabs(nextTabs = [], previousTabs = []) {
  if (previousTabs.length === 0) return;
  const previousCounts = new Map(previousTabs.filter((tab) => tab?.id).map((tab) => [tab.id, tabPendingBlockerCount(tab)]));
  const liveIds = new Set();
  for (const tab of nextTabs) {
    if (!tab?.id) continue;
    liveIds.add(tab.id);
    const previousCount = previousCounts.get(tab.id) || 0;
    const nextCount = tabPendingBlockerCount(tab);
    if (previousCount === 0 && nextCount > 0) notifyBlockedTab(tab, { count: nextCount });
    if (nextCount === 0) clearBlockedTabNotificationKeys(tab.id);
  }
  for (const tab of previousTabs) {
    if (tab?.id && !liveIds.has(tab.id)) clearBlockedTabNotificationKeys(tab.id);
  }
}

function formatDate(value) {
  if (!value) return "";
  const date = typeof value === "number" ? new Date(value) : new Date(String(value));
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleString();
}

// "3 min ago", "yesterday 14:05", "Aug 3, 09:12" — for lists where raw ISO stamps were shown.
function formatRelativeDate(value, now = Date.now()) {
  if (!value) return "";
  const date = typeof value === "number" ? new Date(value) : new Date(String(value));
  const time = date.getTime();
  if (Number.isNaN(time)) return String(value);
  const diff = Math.max(0, now - time);
  const minute = 60_000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (diff < minute) return "just now";
  if (diff < hour) return `${Math.round(diff / minute)} min ago`;
  if (diff < day && new Date(now).getDate() === date.getDate()) return `today ${date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`;
  if (diff < 2 * day) return `yesterday ${date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`;
  if (diff < 7 * day) return `${Math.round(diff / day)} days ago`;
  return date.toLocaleDateString([], { month: "short", day: "numeric", ...(new Date(now).getFullYear() === date.getFullYear() ? {} : { year: "numeric" }) });
}

function stripAnsi(text) {
  return String(text ?? "").replace(/(?:\x1B|\u241B)(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])/g, "");
}

const ANSI_16_COLORS = [
  "#000000",
  "#800000",
  "#008000",
  "#808000",
  "#000080",
  "#800080",
  "#008080",
  "#c0c0c0",
  "#808080",
  "#ff0000",
  "#00ff00",
  "#ffff00",
  "#0000ff",
  "#ff00ff",
  "#00ffff",
  "#ffffff",
];

function ansi256ToHex(index) {
  const n = Number(index);
  if (!Number.isInteger(n) || n < 0 || n > 255) return "";
  if (n < 16) return ANSI_16_COLORS[n];
  if (n < 232) {
    const cubeIndex = n - 16;
    const r = Math.floor(cubeIndex / 36);
    const g = Math.floor((cubeIndex % 36) / 6);
    const b = cubeIndex % 6;
    const toHex = (value) => (value === 0 ? 0 : 55 + value * 40).toString(16).padStart(2, "0");
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  }
  const gray = 8 + (n - 232) * 10;
  const grayHex = gray.toString(16).padStart(2, "0");
  return `#${grayHex}${grayHex}${grayHex}`;
}

function applyAnsiSgr(codes, state) {
  const values = codes.length ? codes : [0];
  for (let i = 0; i < values.length; i += 1) {
    const code = Number(values[i] || 0);
    if (code === 0) {
      state.color = "";
      state.backgroundColor = "";
      state.fontWeight = "";
      state.fontStyle = "";
      state.textDecoration = "";
    } else if (code === 1) {
      state.fontWeight = "700";
    } else if (code === 3) {
      state.fontStyle = "italic";
    } else if (code === 4) {
      state.textDecoration = "underline";
    } else if (code === 22) {
      state.fontWeight = "";
    } else if (code === 23) {
      state.fontStyle = "";
    } else if (code === 24) {
      state.textDecoration = "";
    } else if (code === 39) {
      state.color = "";
    } else if (code === 49) {
      state.backgroundColor = "";
    } else if (code >= 30 && code <= 37) {
      state.color = ANSI_16_COLORS[code - 30];
    } else if (code >= 90 && code <= 97) {
      state.color = ANSI_16_COLORS[code - 90 + 8];
    } else if (code >= 40 && code <= 47) {
      state.backgroundColor = ANSI_16_COLORS[code - 40];
    } else if (code >= 100 && code <= 107) {
      state.backgroundColor = ANSI_16_COLORS[code - 100 + 8];
    } else if ((code === 38 || code === 48) && Number(values[i + 1]) === 2) {
      const r = Number(values[i + 2]);
      const g = Number(values[i + 3]);
      const b = Number(values[i + 4]);
      if ([r, g, b].every((value) => Number.isInteger(value) && value >= 0 && value <= 255)) {
        state[code === 38 ? "color" : "backgroundColor"] = `rgb(${r}, ${g}, ${b})`;
      }
      i += 4;
    } else if ((code === 38 || code === 48) && Number(values[i + 1]) === 5) {
      const color = ansi256ToHex(values[i + 2]);
      if (color) state[code === 38 ? "color" : "backgroundColor"] = color;
      i += 2;
    }
  }
}

function appendAnsiSegment(parent, text, state) {
  const value = stripAnsi(text);
  if (!value) return;
  if (!state.color && !state.backgroundColor && !state.fontWeight && !state.fontStyle && !state.textDecoration) {
    parent.append(document.createTextNode(value));
    return;
  }
  const span = make("span", "ansi-segment");
  span.textContent = value;
  if (state.color) span.style.color = state.color;
  if (state.backgroundColor) span.style.backgroundColor = state.backgroundColor;
  if (state.fontWeight) span.style.fontWeight = state.fontWeight;
  if (state.fontStyle) span.style.fontStyle = state.fontStyle;
  if (state.textDecoration) span.style.textDecoration = state.textDecoration;
  parent.append(span);
}

function renderAnsiText(parent, text) {
  parent.replaceChildren();
  const raw = String(text ?? "");
  const pattern = /(?:\x1B|\u241B)\[([0-9;]*)m/g;
  const state = { color: "", backgroundColor: "", fontWeight: "", fontStyle: "", textDecoration: "" };
  let lastIndex = 0;
  let match;
  while ((match = pattern.exec(raw))) {
    appendAnsiSegment(parent, raw.slice(lastIndex, match.index), state);
    const codes = match[1].split(";").filter((part) => part !== "").map((part) => Number(part));
    applyAnsiSgr(codes, state);
    lastIndex = pattern.lastIndex;
  }
  appendAnsiSegment(parent, raw.slice(lastIndex), state);
}

function cleanStatusText(value) {
  return stripAnsi(value).replace(/\s+/g, " ").trim();
}

function modelLabel(model) {
  if (!model) return "none";
  return `${model.provider}/${model.id}`;
}

function shortSessionLabel(state) {
  const label = cleanStatusText(state?.sessionName || state?.sessionId || "session");
  return /^[0-9a-f]{8}-[0-9a-f-]{18,}$/i.test(label) ? label.slice(0, 8) : label;
}

function formatStatusEntry(key, value) {
  const cleanKey = cleanStatusText(key);
  const cleanValue = cleanStatusText(value);
  if (!cleanValue) return "";
  if ((cleanKey === "git-footer" || cleanKey === GIT_FOOTER_WEBUI_STATUS_KEY) && !isOptionalFeatureEnabled("gitFooterStatus")) return "";
  if (cleanKey === GIT_FOOTER_WEBUI_STATUS_KEY) return "";
  if (cleanKey === "plan-mode") return `Plan: ${cleanValue}`;
  if (cleanKey === "extension") return cleanValue;
  return `${cleanKey}: ${cleanValue}`;
}

function shortModelLabel(model) {
  if (!model) return "unknown";
  // Model id first: when a narrow footer chip truncates from the end, the useful part survives
  // ("qwen3.6-35b-a3b · lmstu…" instead of "(lmstu…").
  return `${model.id} · ${model.provider}`;
}

function footerThinkingLevelLabel(level) {
  return String(level || "unknown").trim() || "unknown";
}

function footerThinkingDisplay(state = currentState) {
  const current = footerThinkingLevelLabel(state?.thinkingLevel);
  const pending = state?.pendingThinkingLevel ? footerThinkingLevelLabel(state.pendingThinkingLevel) : "";
  return pending && pending !== current ? `${current} → ${pending} next` : current;
}

function footerModelLine(model = currentState?.model, thinkingLevel = currentState?.thinkingLevel) {
  const label = shortModelLabel(model);
  if (!model?.reasoning) return label;
  const thinking = thinkingLevel === "off" ? "thinking off" : thinkingLevel || "?";
  return `${label} • ${thinking}`;
}

function normalizeSelectedModel(model) {
  const provider = String(model?.provider || "").trim();
  const id = String(model?.id || model?.modelId || "").trim();
  if (!provider || !id) return null;
  const known = [...availableModels, ...footerScopedModels].find((item) => item?.provider === provider && item?.id === id);
  return { ...(known || {}), ...model, provider, id };
}

function applyOptimisticModelSelection(model, tabContext = activeTabContext()) {
  const nextModel = normalizeSelectedModel(model);
  if (!nextModel || !currentState || !isCurrentTabContext(tabContext)) return nextModel;
  const changed = modelStateKey(currentState.model) !== modelStateKey(nextModel);
  currentState = { ...currentState, model: nextModel };
  renderStatus();
  if (changed) requestGitFooterWebuiPayload(tabContext, { force: true });
  return nextModel;
}

function applyOptimisticThinkingSelection(data, tabContext = activeTabContext()) {
  const level = String(data?.level || data?.requestedLevel || "").trim();
  if (!level || !currentState || !isCurrentTabContext(tabContext)) return level;
  if (data?.pending) currentState = { ...currentState, pendingThinkingLevel: level };
  else currentState = { ...currentState, thinkingLevel: level, pendingThinkingLevel: undefined };
  renderStatus();
  if (!data?.pending) requestGitFooterWebuiPayload(tabContext, { force: true });
  return level;
}

function footerThinkingLevels() {
  const levels = Array.from(elements.thinkingSelect?.options || []).map((option) => option.value).filter(Boolean);
  return levels.length ? levels : ["off", "minimal", "low", "medium", "high", "xhigh", "max"];
}

// Which thinking levels the active model actually honors (mirrors the server-side rule used for
// launch slots): non-reasoning models only "off"; xhigh/max only when the model maps them.
function activeModelSupportedThinkingLevels(model = currentState?.model) {
  const catalogModel = model && Array.isArray(availableModels)
    ? availableModels.find((candidate) => candidate?.provider === model.provider && candidate?.id === model.id) || model
    : model;
  if (!catalogModel || typeof catalogModel.reasoning !== "boolean") return null; // unknown → don't restrict
  if (!catalogModel.reasoning) return ["off"];
  const mapping = catalogModel.thinkingLevelMap && typeof catalogModel.thinkingLevelMap === "object" ? catalogModel.thinkingLevelMap : {};
  return footerThinkingLevels().filter((level) => {
    if (mapping[level] === null) return false;
    if (["xhigh", "max"].includes(level)) return typeof mapping[level] === "string" || !Object.keys(mapping).length;
    return true;
  });
}

function thinkingLevelSupportedByActiveModel(level) {
  const supported = activeModelSupportedThinkingLevels();
  return !supported || supported.includes(level);
}

function syncThinkingSelectSupport() {
  const supported = activeModelSupportedThinkingLevels();
  for (const option of elements.thinkingSelect?.options || []) {
    const ok = !supported || supported.includes(option.value);
    option.disabled = !ok && option.value !== elements.thinkingSelect.value;
    const base = option.dataset.baseLabel || (option.dataset.baseLabel = option.textContent);
    option.textContent = ok ? base : `${base} (not supported by this model)`;
  }
}

function formatFooterTokenCount(value) {
  const n = Math.max(0, Number(value) || 0);
  if (n < 1000) return `${Math.round(n)}`;
  if (n < 10000) return `${(n / 1000).toFixed(1)}k`;
  if (n < 1000000) return `${Math.round(n / 1000)}k`;
  if (n < 10000000) return `${(n / 1000000).toFixed(1)}M`;
  return `${Math.round(n / 1000000)}M`;
}

function footerCostAuthLabel() {
  const provider = currentState?.model?.provider || "";
  return /codex|copilot|chatgpt/i.test(provider) ? "sub" : "api";
}

function contextWindowFromSources(...sources) {
  for (const source of sources) {
    const value = typeof source === "object" && source !== null ? source.contextWindow : source;
    const contextWindow = Number(value);
    if (Number.isFinite(contextWindow) && contextWindow > 0) return contextWindow;
  }
  return 0;
}

function contextUsageUnknownAfterCompaction(tabId = activeTabId) {
  return !!tabId && contextUsageUnknownAfterCompactionByTab.has(tabId);
}

function unknownFooterContextText(contextUsage = null) {
  const contextWindow = contextWindowFromSources(
    contextUsage,
    latestStats?.contextUsage,
    currentState?.contextUsage,
    currentState?.model?.contextWindow,
  );
  return contextWindow ? `?/${formatFooterTokenCount(contextWindow)}` : "?";
}

function contextUsageWithUnknownPercent(contextUsage = null) {
  return {
    ...(contextUsage || {}),
    percent: null,
    contextWindow: contextWindowFromSources(contextUsage, latestStats?.contextUsage, currentState?.contextUsage, currentState?.model?.contextWindow),
  };
}

function markContextUsageUnknownAfterCompaction(tabId = activeTabId) {
  if (!tabId) return;
  contextUsageUnknownAfterCompactionByTab.set(tabId, Date.now());
  if (tabId !== activeTabId) return;
  if (currentState) currentState = { ...currentState, contextUsage: contextUsageWithUnknownPercent(currentState.contextUsage) };
  if (latestStats) latestStats = { ...latestStats, contextUsage: contextUsageWithUnknownPercent(latestStats.contextUsage) };
}

function clearContextUsageUnknownAfterCompaction(tabId = activeTabId) {
  if (!tabId) return;
  contextUsageUnknownAfterCompactionByTab.delete(tabId);
}

function footerStatsTokensDisplay(stats = latestStats) {
  const tokens = stats?.tokens;
  if (!tokens) return "";
  return `↑${formatFooterTokenCount(tokens.input)} ↓${formatFooterTokenCount(tokens.output)}`;
}

function footerStatsCostDisplay(stats = latestStats) {
  if (!stats) return "";
  return `$${Number(stats.cost || 0).toFixed(3)} (${footerCostAuthLabel()})`;
}

function footerAutoCompactionEnabled(state = currentState) {
  return state?.autoCompactionEnabled !== false;
}

function footerContextDisplayWithAuto(value, state = currentState) {
  const text = cleanStatusText(value);
  if (!text) return "";
  const withoutAuto = text.replace(/\s*\(auto\)\s*$/i, "");
  return footerAutoCompactionEnabled(state) ? `${withoutAuto} (auto)` : withoutAuto;
}

function footerStatsContextDisplay(stats = latestStats) {
  const usage = stats?.contextUsage || currentState?.contextUsage;
  const contextWindow = contextWindowFromSources(usage, currentState?.model?.contextWindow);
  if (contextUsageUnknownAfterCompaction()) return footerContextDisplayWithAuto(unknownFooterContextText(usage));
  if (!contextWindow) return "";
  const rawPercent = Number(usage?.percent);
  const percent = Number.isFinite(rawPercent) ? `${rawPercent.toFixed(1)}%` : "?";
  return footerContextDisplayWithAuto(`${percent}/${formatFooterTokenCount(contextWindow)}`);
}

function footerAutoCompactionToggleAction(state = currentState) {
  return `Click to ${footerAutoCompactionEnabled(state) ? "disable" : "enable"} auto-compaction.`;
}

async function toggleFooterAutoCompaction(tabContext = activeTabContext()) {
  if (footerAutoCompactionToggleInFlight || !tabContext.tabId) return;
  const previousState = currentState;
  const enabled = !footerAutoCompactionEnabled(previousState);
  footerAutoCompactionToggleInFlight = true;
  if (isCurrentTabContext(tabContext) && currentState) {
    currentState = { ...currentState, autoCompactionEnabled: enabled };
    renderStatus();
  }
  try {
    await api("/api/auto-compaction", { method: "POST", body: { enabled }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    addEvent(`Auto-compaction ${enabled ? "enabled" : "disabled"}`, "info");
    try {
      await refreshState(tabContext);
    } catch (error) {
      if (isCurrentTabContext(tabContext)) addEvent(`Auto-compaction updated, but state refresh failed: ${error.message || String(error)}`, "warn");
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      if (previousState) currentState = previousState;
      addEvent(error.message || String(error), "error");
      renderStatus();
    }
  } finally {
    footerAutoCompactionToggleInFlight = false;
    if (isCurrentTabContext(tabContext)) renderStatus();
  }
}

function scheduleGitFooterPiCalibrationRefresh(tabContext, delays = [5000, 14000, 30000]) {
  for (const delayMs of delays) {
    setTimeout(() => {
      if (isCurrentTabContext(tabContext)) requestGitFooterWebuiPayload(tabContext, { force: true });
    }, delayMs);
  }
}


async function runGitFooterPiCalibration(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  if (gitFooterPiCalibrationInFlightByTab.has(tabContext.tabId)) return;
  if (currentState?.isStreaming || currentState?.isCompacting) {
    addEvent("PI calibration can run after the active agent work finishes.", "warn");
    return;
  }

  const commandName = resolveAvailableCommandName("calibrate", { rpcOnly: true });
  if (!commandName) {
    addEvent("PI calibration unavailable: /calibrate is not loaded in this Pi tab.", "warn");
    return;
  }

  gitFooterPiCalibrationInFlightByTab.add(tabContext.tabId);
  renderFooter();
  try {
    await sendPrompt("prompt", `/${commandName}`, { targetTabId: tabContext.tabId, throwOnError: true });
    scheduleGitFooterPiCalibrationRefresh(tabContext);
    if (!isCurrentTabContext(tabContext)) return;
    addEvent("PI calibration started in the background; refreshing the footer value after it records…", "info");
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
  } finally {
    gitFooterPiCalibrationInFlightByTab.delete(tabContext.tabId);
    if (isCurrentTabContext(tabContext)) renderFooter();
  }
}

function applyGitFooterPiCalibrationOptions(chip, options) {
  if (chip?.key !== "pi") return "";
  const tabContext = activeTabContext();
  const busy = !!tabContext.tabId && gitFooterPiCalibrationInFlightByTab.has(tabContext.tabId);
  options.onClick = () => {
    void runGitFooterPiCalibration();
  };
  if (busy) options.ariaBusy = true;
  return busy
    ? "Calibrating PI estimate in the background and refreshing this value…"
    : "Click to run /calibrate in the background and refresh this PI token count.";
}

function applyGitFooterContextToggleOptions(chip, options) {
  if (chip?.key !== "context") return "";
  options.onClick = () => toggleFooterAutoCompaction();
  options.ariaPressed = footerAutoCompactionEnabled();
  if (footerAutoCompactionToggleInFlight) options.ariaBusy = true;
  return footerAutoCompactionToggleInFlight ? "Updating auto-compaction…" : footerAutoCompactionToggleAction();
}

function fallbackFooterStats() {
  return [footerStatsTokensDisplay(), footerStatsCostDisplay(), footerStatsContextDisplay()].filter(Boolean);
}

function formatDuration(ms) {
  const totalSeconds = Math.max(0, Math.floor(Number(ms) / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  if (hours > 0) return `${hours}h${minutes > 0 ? `${minutes}m` : ""}`;
  if (minutes > 0) return `${minutes}m`;
  return `${totalSeconds}s`;
}

function normalizeDisplayPath(value) {
  return String(value || "").replace(/\\/g, "/");
}

function normalizeGitWorkspaceInfo(workspace) {
  if (!workspace || typeof workspace !== "object") return null;
  return {
    repoRoot: normalizeDisplayPath(workspace.repoRoot || ""),
    commonGitDir: normalizeDisplayPath(workspace.commonGitDir || ""),
    worktreePath: normalizeDisplayPath(workspace.worktreePath || workspace.path || ""),
    branch: cleanStatusText(workspace.branch || ""),
    worktreeCount: Number.isFinite(Number(workspace.worktreeCount)) ? Number(workspace.worktreeCount) : null,
    isMainWorktree: workspace.isMainWorktree === true,
  };
}

function gitWorkspaceBadgeLabel(workspace = normalizeGitWorkspaceInfo(activeTab()?.gitWorkspace)) {
  if (!workspace?.worktreePath) return "";
  const branch = workspace.branch || "detached";
  return workspace.isMainWorktree ? `main worktree · ${branch}` : `worktree · ${branch}`;
}

function textFromContent(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return JSON.stringify(content ?? "");
  return content
    .map((part) => {
      if (!part || typeof part !== "object") return String(part ?? "");
      if (typeof part.text === "string") return part.text;
      if (typeof part.thinking === "string") return part.thinking;
      if (part.type === "toolCall") return JSON.stringify(part.arguments || {});
      if (typeof part.content === "string") return part.content;
      return "";
    })
    .join("\n");
}

function cleanTooltipText(value, { preserveInternalSpaces = false } = {}) {
  const normalized = stripAnsi(value).replace(/\r\n?/g, "\n");
  const whitespaceNormalized = preserveInternalSpaces
    ? normalized.replace(/[^\S\n ]+/g, " ")
    : normalized.replace(/[^\S\n]+/g, " ");
  return whitespaceNormalized.replace(/\n{3,}/g, "\n\n").trim();
}

const TOOLTIP_HOVER_DELAY_MS = 500;

let footerTooltipNode = null;
let footerTooltipTarget = null;
let footerTooltipEventsBound = false;
let footerTooltipHoverTimer = null;
let footerTooltipPendingTarget = null;
let footerTooltipHoverDeadline = 0;

function ensureFooterTooltipNode() {
  if (!footerTooltipNode) {
    footerTooltipNode = make("div", "footer-floating-tooltip");
    footerTooltipNode.id = "footerFloatingTooltip";
    footerTooltipNode.setAttribute("role", "tooltip");
    footerTooltipNode.hidden = true;
    document.body.append(footerTooltipNode);
  }
  if (!footerTooltipEventsBound) {
    footerTooltipEventsBound = true;
    const update = () => positionFooterTooltip(footerTooltipTarget);
    window.addEventListener("resize", update, { passive: true });
    window.addEventListener("scroll", update, { passive: true, capture: true });
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && footerTooltipTarget) hideFooterTooltip(footerTooltipTarget);
    }, true);
  }
  return footerTooltipNode;
}

function positionFooterTooltip(target) {
  if (!target || !footerTooltipNode || footerTooltipNode.hidden) return;
  const gap = 8;
  const margin = 8;
  const rect = target.getBoundingClientRect();
  const maxWidth = Math.max(96, Math.min(384, window.innerWidth - margin * 2));
  footerTooltipNode.style.maxWidth = `${maxWidth}px`;

  const width = footerTooltipNode.offsetWidth;
  const height = footerTooltipNode.offsetHeight;
  const align = target.getAttribute("data-tooltip-align") || "center";
  const placement = target.getAttribute("data-tooltip-placement") || "top";
  let left;
  let top;
  if (placement === "right") {
    left = rect.right + gap;
    if (left + width > window.innerWidth - margin) left = rect.left - gap - width;
    top = rect.top;
  } else {
    left = rect.left + rect.width / 2 - width / 2;
    if (align === "start") left = rect.left;
    if (align === "end") left = rect.right - width;
    top = rect.top - gap - height;
    if (top < margin) top = rect.bottom + gap;
  }
  left = Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - margin - width));
  top = Math.min(Math.max(margin, top), window.innerHeight - margin - height);

  footerTooltipNode.style.left = `${Math.round(left)}px`;
  footerTooltipNode.style.top = `${Math.round(top)}px`;
}

function clearFooterTooltipHoverTimer(target) {
  if (target && footerTooltipPendingTarget && target !== footerTooltipPendingTarget) return;
  if (footerTooltipHoverTimer) clearTimeout(footerTooltipHoverTimer);
  footerTooltipHoverTimer = null;
  footerTooltipPendingTarget = null;
  footerTooltipHoverDeadline = 0;
}

function showFooterTooltip(target) {
  clearFooterTooltipHoverTimer();
  const text = target?.getAttribute("data-tooltip");
  if (!text) return;
  footerTooltipTarget = target;
  const tooltip = ensureFooterTooltipNode();
  const variant = target.getAttribute("data-tooltip-variant");
  if (variant) tooltip.dataset.variant = variant;
  else delete tooltip.dataset.variant;
  tooltip.textContent = text;
  tooltip.hidden = false;
  tooltip.classList.add("visible");
  positionFooterTooltip(target);
}

function scheduleFooterTooltip(target, delay = TOOLTIP_HOVER_DELAY_MS) {
  const text = target?.getAttribute("data-tooltip");
  if (!text) return;
  clearFooterTooltipHoverTimer();
  const boundedDelay = Math.max(0, Math.min(TOOLTIP_HOVER_DELAY_MS, Number(delay) || 0));
  footerTooltipPendingTarget = target;
  footerTooltipHoverDeadline = performance.now() + boundedDelay;
  footerTooltipHoverTimer = setTimeout(() => {
    const pendingTarget = footerTooltipPendingTarget;
    clearFooterTooltipHoverTimer();
    if (!pendingTarget?.isConnected || !pendingTarget.matches?.(":hover")) return;
    showFooterTooltip(pendingTarget);
  }, boundedDelay);
}

function hideFooterTooltip(target) {
  clearFooterTooltipHoverTimer(target);
  if (target && target !== footerTooltipTarget) return;
  footerTooltipTarget = null;
  if (!footerTooltipNode) return;
  footerTooltipNode.hidden = true;
  footerTooltipNode.classList.remove("visible");
  delete footerTooltipNode.dataset.variant;
}

function bindStyledTooltipEvents(node) {
  if (!node || node._styledTooltipBound) return;
  node._styledTooltipBound = true;
  node.addEventListener("pointerenter", (event) => {
    if (event.pointerType === "touch") return;
    scheduleFooterTooltip(node);
  });
  node.addEventListener("pointerleave", () => hideFooterTooltip(node));
  node.addEventListener("focus", () => {
    if (!node.matches(":focus-visible")) return;
    showFooterTooltip(node);
  });
  node.addEventListener("blur", () => hideFooterTooltip(node));
}

let styledTooltipDescriptionSerial = 0;

function applyStyledTooltip(node, tooltip, options = {}) {
  if (!node) return node;
  const text = cleanTooltipText(tooltip, { preserveInternalSpaces: options.preserveInternalSpaces === true });
  if (!text) return node;
  node.setAttribute("data-tooltip", text);
  node.removeAttribute("title");
  if (options.ariaLabel !== false) {
    const ariaLabel = typeof options.ariaLabel === "string" ? options.ariaLabel : text.replace(/\s+/g, " ");
    node.setAttribute("aria-label", ariaLabel);
  }
  if (options.description === true) {
    const description = make("span", "sr-only styled-tooltip-description", text);
    description.id = `styledTooltipDescription${++styledTooltipDescriptionSerial}`;
    node.append(description);
    const describedBy = [node.getAttribute("aria-describedby"), description.id].filter(Boolean).join(" ");
    node.setAttribute("aria-describedby", describedBy);
  }
  const targetKey = String(options.targetKey || (node.id ? `id:${node.id}` : "")).trim();
  if (targetKey) node.dataset.tooltipTargetKey = targetKey;
  else delete node.dataset.tooltipTargetKey;
  if (options.align) node.setAttribute("data-tooltip-align", options.align);
  if (options.placement) node.setAttribute("data-tooltip-placement", options.placement);
  if (options.variant) node.setAttribute("data-tooltip-variant", options.variant);
  if (options.floating !== false) bindStyledTooltipEvents(node);
  return node;
}

function applyFooterTooltip(node, tooltip, options = {}) {
  return applyStyledTooltip(node, tooltip, options);
}

function runFooterControlAction(action, event) {
  if (mobileFooterExpanded) setMobileFooterExpanded(false, { restoreFocus: false });
  return action(event);
}

function footerMetric(icon, label, value, tone = "", options = {}) {
  const isAction = typeof options.onClick === "function";
  const node = make(isAction ? "button" : "span", ["footer-metric", tone, isAction ? "footer-metric-action" : ""].filter(Boolean).join(" "));
  if (isAction) {
    node.type = "button";
    node.addEventListener("click", (event) => runFooterControlAction(options.onClick, event));
    if (options.ariaPressed !== undefined) node.setAttribute("aria-pressed", options.ariaPressed ? "true" : "false");
    if (options.ariaBusy) node.setAttribute("aria-busy", "true");
  }
  node.append(make("span", "footer-metric-icon", icon), make("span", "footer-metric-label", label), make("span", "footer-metric-value", value));
  return applyFooterTooltip(node, options.title || `${label}: ${value}`, { align: options.tooltipAlign, targetKey: options.targetKey });
}

function contextUsageActiveColor(percent) {
  const styles = getComputedStyle(document.documentElement);
  const cssVar = (name, fallback) => styles.getPropertyValue(name).trim() || fallback;
  const stops = [
    { at: 0, color: cssVar("--ctp-green", "#a6e3a1") },
    { at: 36, color: cssVar("--ctp-yellow", "#f9e2af") },
    { at: 62, color: cssVar("--ctp-blue", "#89b4fa") },
    { at: 100, color: cssVar("--ctp-red", "#f38ba8") },
  ];
  const value = Math.min(100, Math.max(0, Number(percent)));
  const right = stops.find((stop) => value <= stop.at) || stops.at(-1);
  const left = stops[Math.max(0, stops.indexOf(right) - 1)];
  const leftRgb = cssColorToRgb(left.color);
  const rightRgb = cssColorToRgb(right.color);
  if (!leftRgb || !rightRgb || left.at === right.at) {
    return { color: right.color, glow: right.color };
  }
  const mixed = mixRgb(leftRgb, rightRgb, (value - left.at) / (right.at - left.at));
  return { color: rgbColor(mixed), glow: rgbaColor(mixed, 0.42) };
}

function applyFooterContextUsage(node, contextUsage) {
  node.classList.add("footer-context-card");
  const percent = typeof contextUsage?.percent === "number" ? contextUsage.percent : Number.NaN;
  if (Number.isFinite(percent)) {
    const clampedPercent = Math.min(100, Math.max(0, percent));
    const activeColor = contextUsageActiveColor(clampedPercent);
    node.classList.add("has-context-usage");
    node.style.setProperty("--context-usage", `${clampedPercent.toFixed(1)}%`);
    node.style.setProperty("--context-active-color", activeColor.color);
    node.style.setProperty("--context-active-glow", activeColor.glow);
  }
  return node;
}

// Dedicated Usage visual apply path: sets available independent lane widths
// (top = primary/first window, bottom = secondary/second window) plus a
// max-window active foreground/glow reusing the Context color interpolation.
// Missing lanes remain empty; exact text and tooltip remain untouched.
function applyFooterUsageWindows(node, usageWindows) {
  node.classList.add("footer-usage-card");
  const primaryPercent = typeof usageWindows?.primaryPercent === "number" ? usageWindows.primaryPercent : Number.NaN;
  const secondaryPercent = typeof usageWindows?.secondaryPercent === "number" ? usageWindows.secondaryPercent : Number.NaN;
  if (Number.isFinite(primaryPercent) || Number.isFinite(secondaryPercent)) {
    const clampedPrimary = Number.isFinite(primaryPercent) ? Math.min(100, Math.max(0, primaryPercent)) : 0;
    const clampedSecondary = Number.isFinite(secondaryPercent) ? Math.min(100, Math.max(0, secondaryPercent)) : 0;
    const activeColor = contextUsageActiveColor(Math.max(clampedPrimary, clampedSecondary));
    node.classList.add("has-usage-windows");
    node.style.setProperty("--usage-primary", `${clampedPrimary.toFixed(1)}%`);
    node.style.setProperty("--usage-secondary", `${clampedSecondary.toFixed(1)}%`);
    node.style.setProperty("--usage-active-color", activeColor.color);
    node.style.setProperty("--usage-active-glow", activeColor.glow);
  }
  return node;
}

const FOOTER_MIDDLE_TRUNCATION_END_CHARS = 16;
const FOOTER_MIDDLE_TRUNCATION_MIN_START_CHARS = 6;

function splitMiddleTruncationText(value, endChars = FOOTER_MIDDLE_TRUNCATION_END_CHARS) {
  const characters = Array.from(String(value ?? ""));
  const minimumSuffixLength = Math.max(0, Math.min(Math.trunc(Number(endChars) || 0), characters.length));
  if (!minimumSuffixLength) return { start: characters.join(""), end: "" };
  let componentEnd = characters.length - 1;
  while (componentEnd >= 0 && (characters[componentEnd] === "/" || characters[componentEnd] === "\\")) componentEnd -= 1;
  let separatorIndex = -1;
  for (let index = componentEnd; index >= 0; index -= 1) {
    if (characters[index] === "/" || characters[index] === "\\") {
      separatorIndex = index;
      break;
    }
  }
  const componentSuffixLength = separatorIndex >= 0 ? characters.length - separatorIndex : 0;
  const suffixLength = Math.min(characters.length, Math.max(minimumSuffixLength, componentSuffixLength));
  if (!suffixLength || characters.length <= suffixLength + FOOTER_MIDDLE_TRUNCATION_MIN_START_CHARS) return { start: characters.join(""), end: "" };
  return { start: characters.slice(0, -suffixLength).join(""), end: characters.slice(-suffixLength).join("") };
}

function setMiddleTruncatedText(node, value, endChars = FOOTER_MIDDLE_TRUNCATION_END_CHARS) {
  const parts = splitMiddleTruncationText(value, endChars);
  if (!parts.end) {
    node.classList.remove("middle-truncate-value");
    node.textContent = parts.start;
    return node;
  }
  node.classList.add("middle-truncate-value");
  node.replaceChildren(
    make("span", "middle-truncate-start", parts.start),
    make("span", "middle-truncate-end", parts.end),
  );
  return node;
}

function footerMeta(label, value, className = "", options = {}) {
  const isAction = typeof options.onClick === "function";
  const node = make(isAction ? "button" : "span", ["footer-meta", className, isAction ? "footer-meta-action" : ""].filter(Boolean).join(" "));
  if (isAction) {
    node.type = "button";
    node.addEventListener("click", (event) => runFooterControlAction(options.onClick, event));
    if (options.ariaPressed !== undefined) node.setAttribute("aria-pressed", options.ariaPressed ? "true" : "false");
    if (options.ariaBusy) node.setAttribute("aria-busy", "true");
    if (options.disabled) {
      node.disabled = true;
      node.setAttribute("aria-disabled", "true");
    }
  }
  const valueNode = make("span", "footer-meta-value");
  if (options.middleTruncate) setMiddleTruncatedText(valueNode, value);
  else valueNode.textContent = String(value ?? "");
  node.append(make("span", "footer-meta-label", label), valueNode);
  return applyFooterTooltip(node, options.title || `${label}: ${value}`, { align: options.tooltipAlign });
}

