function gitFooterVisibilityLabel(key) {
  return GIT_FOOTER_VISIBILITY_LABELS[key] || String(key).split("-").map((part) => part ? `${part[0].toUpperCase()}${part.slice(1)}` : part).join(" ");
}

function gitFooterVisibilityHint(key) {
  return GIT_FOOTER_VISIBILITY_HINTS[key] || GIT_FOOTER_TOOLTIP_COPY[key] || `Controls the ${key} footer visibility key for the Web UI.`;
}

function gitFooterVisibilityCommandName() {
  return resolveAvailableCommandName("git-footer-visibility", { rpcOnly: true });
}

function gitFooterVisibilityCommandAvailable() {
  return !!gitFooterVisibilityCommandName();
}

function currentGitFooterVisibilityState() {
  return normalizeGitFooterWebuiVisibility(parseGitFooterWebuiPayload()?.visibility);
}

function setGitFooterVisibilityStatus(message = "", level = "muted") {
  if (!elements.gitFooterVisibilityStatus) return;
  elements.gitFooterVisibilityStatus.textContent = message;
  elements.gitFooterVisibilityStatus.className = `git-footer-visibility-status ${level || "muted"}`;
  elements.gitFooterVisibilityStatus.hidden = !message;
}

function setGitFooterVisibilityBusy(busy) {
  gitFooterVisibilityApplyInFlight = !!busy;
  const commandAvailable = gitFooterVisibilityCommandAvailable();
  for (const button of [elements.gitFooterVisibilityApplyButton, elements.gitFooterVisibilityResetButton]) {
    if (button) button.disabled = gitFooterVisibilityApplyInFlight || !commandAvailable;
  }
  const inputs = elements.gitFooterVisibilityBody?.querySelectorAll("input[data-git-footer-visibility-key]") || [];
  for (const input of inputs) input.disabled = gitFooterVisibilityApplyInFlight || !commandAvailable;
  for (const button of [elements.gitFooterVisibilitySelectAllButton, elements.gitFooterVisibilitySelectNoneButton]) {
    if (button) button.disabled = gitFooterVisibilityApplyInFlight || !commandAvailable;
  }
  if (elements.gitFooterVisibilityCloseButton) elements.gitFooterVisibilityCloseButton.disabled = gitFooterVisibilityApplyInFlight;
}

function renderGitFooterVisibilityToggle(key, visibility) {
  const label = make("label", "toggle-control git-footer-visibility-toggle");
  const input = make("input");
  input.type = "checkbox";
  input.checked = visibility[key] ?? true;
  input.dataset.gitFooterVisibilityKey = key;
  input.addEventListener("change", () => {
    gitFooterVisibilityDirty = true;
    setGitFooterVisibilityStatus("Unsaved WebUI footer visibility changes.", "warn");
  });
  const text = make("span", "git-footer-visibility-toggle-text");
  text.append(
    make("span", "toggle-control-label", gitFooterVisibilityLabel(key)),
    make("span", "toggle-control-hint", gitFooterVisibilityHint(key)),
    make("code", "git-footer-visibility-key", key),
  );
  label.append(input, text);
  return label;
}

function renderGitFooterVisibilityDialog() {
  if (!elements.gitFooterVisibilityBody) return;
  const visibility = currentGitFooterVisibilityState();
  elements.gitFooterVisibilityBody.replaceChildren();
  for (const group of GIT_FOOTER_VISIBILITY_GROUPS) {
    const section = make("section", "git-footer-visibility-group");
    const header = make("div", "git-footer-visibility-group-header");
    header.append(make("h3", "", group.label), make("p", "muted", group.description));
    const grid = make("div", "git-footer-visibility-grid");
    for (const key of group.keys) grid.append(renderGitFooterVisibilityToggle(key, visibility));
    section.append(header, grid);
    elements.gitFooterVisibilityBody.append(section);
  }
  setGitFooterVisibilityBusy(gitFooterVisibilityApplyInFlight);
  if (!gitFooterVisibilityDirty) {
    setGitFooterVisibilityStatus(
      gitFooterVisibilityCommandAvailable()
        ? "Changes are saved globally and reused by every Pi session. Reset WebUI removes the saved WebUI overrides."
        : commandUnavailableMessage("git-footer-visibility"),
      gitFooterVisibilityCommandAvailable() ? "muted" : "warn",
    );
  }
}

function readGitFooterVisibilitySelection() {
  const next = currentGitFooterVisibilityState();
  const inputs = elements.gitFooterVisibilityBody?.querySelectorAll("input[data-git-footer-visibility-key]") || [];
  for (const input of inputs) {
    const key = input.dataset.gitFooterVisibilityKey;
    if (key && key in next) next[key] = input.checked;
  }
  return next;
}

async function runGitFooterVisibilityCommand(action, keys = []) {
  const commandName = gitFooterVisibilityCommandName();
  if (!commandName) throw new Error(commandUnavailableMessage("git-footer-visibility"));
  const suffix = keys.length > 0 ? ` ${keys.join(" ")}` : "";
  await sendPrompt("prompt", `/${commandName} ${action} webui${suffix}`, { targetTabId: activeTabId, throwOnError: true });
}

async function applyGitFooterVisibilityDialog() {
  if (gitFooterVisibilityApplyInFlight) return;
  const current = currentGitFooterVisibilityState();
  const next = readGitFooterVisibilitySelection();
  const show = [];
  const hide = [];
  for (const key of GIT_FOOTER_VISIBILITY_DIALOG_KEYS) {
    if (next[key] === current[key]) continue;
    if (next[key]) show.push(key);
    else hide.push(key);
  }
  if (show.length === 0 && hide.length === 0) {
    gitFooterVisibilityDirty = false;
    setGitFooterVisibilityStatus("No footer visibility changes to apply.", "muted");
    return;
  }

  setGitFooterVisibilityBusy(true);
  setGitFooterVisibilityStatus("Applying WebUI footer visibility…", "muted");
  try {
    if (hide.length) await runGitFooterVisibilityCommand("hide", hide);
    if (show.length) await runGitFooterVisibilityCommand("show", show);
    gitFooterVisibilityDirty = false;
    setGitFooterVisibilityStatus(`Saved ${hide.length + show.length} global WebUI footer visibility change${hide.length + show.length === 1 ? "" : "s"}.`, "success");
    requestGitFooterWebuiPayload(activeTabContext(), { force: true, allowDuringRun: true });
    renderFooter();
  } catch (error) {
    setGitFooterVisibilityStatus(error.message || String(error), "error");
  } finally {
    setGitFooterVisibilityBusy(false);
  }
}

async function resetGitFooterVisibilityDialog() {
  if (gitFooterVisibilityApplyInFlight) return;
  setGitFooterVisibilityBusy(true);
  setGitFooterVisibilityStatus("Resetting WebUI footer visibility…", "muted");
  try {
    await runGitFooterVisibilityCommand("reset");
    gitFooterVisibilityDirty = false;
    setGitFooterVisibilityStatus("Removed the saved global WebUI footer visibility overrides.", "success");
    requestGitFooterWebuiPayload(activeTabContext(), { force: true, allowDuringRun: true });
  } catch (error) {
    setGitFooterVisibilityStatus(error.message || String(error), "error");
  } finally {
    setGitFooterVisibilityBusy(false);
  }
}

function setGitFooterVisibilitySelection(checked) {
  const inputs = elements.gitFooterVisibilityBody?.querySelectorAll("input[data-git-footer-visibility-key]") || [];
  for (const input of inputs) input.checked = !!checked;
  gitFooterVisibilityDirty = true;
  setGitFooterVisibilityStatus(checked ? "Selected all WebUI footer options." : "Deselected all WebUI footer options.", "warn");
}

function openGitFooterVisibilityDialog() {
  if (!elements.gitFooterVisibilityDialog) return;
  setOptionsMenuOpen(false);
  closeGitFooterContextMenu({ returnFocus: false });
  hideFooterTooltip();
  gitFooterVisibilityDirty = false;
  renderGitFooterVisibilityDialog();
  if (!elements.gitFooterVisibilityDialog.open) elements.gitFooterVisibilityDialog.showModal();
  queueMicrotask(() => elements.gitFooterVisibilityBody?.querySelector("input")?.focus());
}

function closeGitFooterVisibilityDialog() {
  gitFooterVisibilityDirty = false;
  gitFooterVisibilityApplyInFlight = false;
  if (elements.gitFooterVisibilityDialog?.open) elements.gitFooterVisibilityDialog.close();
}

function closeGitFooterContextMenu({ returnFocus = true } = {}) {
  const trigger = gitFooterContextMenuState?.trigger;
  gitFooterContextMenuState = null;
  if (elements.gitFooterContextMenu) elements.gitFooterContextMenu.hidden = true;
  if (returnFocus && trigger?.isConnected) queueMicrotask(() => trigger.focus?.({ preventScroll: true }));
}

function syncGitFooterAdvancedMenuItem(key = gitFooterContextMenuState?.key) {
  const advancedButton = elements.gitFooterContextMenu?.querySelector('[data-git-footer-menu-action="toggle-advanced"]');
  if (!advancedButton) return;
  advancedButton.hidden = key !== "model";
  advancedButton.textContent = footerScopedModelLayout === "advanced" ? "Toggle Simple" : "Toggle advanced";
  advancedButton.setAttribute("aria-checked", footerScopedModelLayout === "advanced" ? "true" : "false");
}

function showGitFooterContextMenu(event, chip, trigger) {
  const menu = elements.gitFooterContextMenu;
  const key = cleanStatusText(chip?.key);
  if (!menu || !key) return;
  event.preventDefault();
  event.stopPropagation();
  closeFileContextMenu({ returnFocus: false });
  closeGitPanelContextMenu({ returnFocus: false });
  closeSidePanelContextMenu({ returnFocus: false });
  closeGitFooterContextMenu({ returnFocus: false });
  closeEventTreeContextMenu({ returnFocus: false });
  hideFooterTooltip();

  const label = cleanStatusText(chip?.label) || gitFooterVisibilityLabel(key);
  gitFooterContextMenuState = { key, label, trigger };
  const disableButton = menu.querySelector('[data-git-footer-menu-action="disable"]');
  if (disableButton) disableButton.textContent = `Disable ${label} box`;
  syncGitFooterAdvancedMenuItem(key);
  menu.hidden = false;
  const rect = menu.getBoundingClientRect();
  const left = Math.min(event.clientX, Math.max(8, window.innerWidth - rect.width - 8));
  const top = Math.min(event.clientY, Math.max(8, window.innerHeight - rect.height - 8));
  menu.style.left = `${Math.max(8, left)}px`;
  menu.style.top = `${Math.max(8, top)}px`;
  menu.querySelector('[role="menuitem"]')?.focus({ preventScroll: true });
}

function bindGitFooterContextMenu(node, chip) {
  if (!node || !chip?.key) return node;
  node.setAttribute("aria-keyshortcuts", "ContextMenu Shift+F10");
  node.addEventListener("contextmenu", (event) => showGitFooterContextMenu(event, chip, node));
  node.addEventListener("keydown", (event) => {
    if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return;
    const rect = node.getBoundingClientRect();
    showGitFooterContextMenu({
      preventDefault: () => event.preventDefault(),
      stopPropagation: () => event.stopPropagation(),
      clientX: rect.left + Math.min(rect.width, 24),
      clientY: rect.bottom,
    }, chip, node);
  });
  return node;
}

async function disableGitFooterContextChip(key, label) {
  try {
    await runGitFooterVisibilityCommand("hide", [key]);
    addEvent(`Disabled the ${label || key} Git footer box.`, "success");
    requestGitFooterWebuiPayload(activeTabContext(), { force: true, allowDuringRun: true });
  } catch (error) {
    addEvent(error.message || String(error), "error");
  }
}

function cleanFooterPayloadText(value, fallback = "", maxLength = 240) {
  const text = cleanStatusText(value).slice(0, maxLength);
  return text || fallback;
}

function normalizeFooterPayloadChangedFile(value) {
  if (!value || typeof value !== "object") return null;
  const path = cleanFooterPayloadText(value.path, "", 1000);
  if (!path) return null;
  const kind = FOOTER_CHANGED_FILE_KINDS.has(value.kind) ? value.kind : "modified";
  const file = {
    kind,
    path,
    status: cleanFooterPayloadText(value.status, "", 12),
  };
  const oldPath = cleanFooterPayloadText(value.oldPath, "", 1000);
  if (oldPath) file.oldPath = oldPath;
  return file;
}

function normalizeGitFooterWebuiVisibility(value) {
  const visibility = { ...GIT_FOOTER_WEBUI_VISIBILITY_DEFAULTS };
  if (!value || typeof value !== "object") return visibility;
  for (const key of Object.keys(visibility)) {
    if (typeof value[key] === "boolean") visibility[key] = value[key];
  }
  return visibility;
}

function gitFooterPayloadVisible(payload, key) {
  if (!key) return true;
  if (typeof payload?.visibility?.[key] === "boolean") return payload.visibility[key];
  return GIT_FOOTER_WEBUI_VISIBILITY_DEFAULTS[key] ?? true;
}

function currentGitFooterPayloadVisible(key) {
  return gitFooterPayloadVisible(parseGitFooterWebuiPayload(), key);
}

function gitFooterPayloadVisibilityKey(payload) {
  const visibility = normalizeGitFooterWebuiVisibility(payload?.visibility);
  return Object.keys(visibility).sort().map((key) => `${key}:${visibility[key] ? 1 : 0}`).join("|");
}

function normalizeFooterPayloadChip(value, index) {
  if (!value || typeof value !== "object") return null;
  const key = cleanFooterPayloadText(value.key, `item-${index}`).replace(/[^a-z0-9_.:-]/gi, "-").slice(0, 64) || `item-${index}`;
  const label = cleanFooterPayloadText(value.label, key).slice(0, 32);
  const chip = {
    key,
    label,
    value: cleanFooterPayloadText(value.value, "—"),
    icon: cleanFooterPayloadText(value.icon, "•").slice(0, 8),
    tone: FOOTER_PAYLOAD_TONES.has(value.tone) ? value.tone : "",
    title: cleanFooterPayloadText(value.title, "", 4000),
  };
  if (FOOTER_PAYLOAD_ACTIONS.has(value.action)) chip.action = value.action;
  if (Array.isArray(value.files)) {
    const files = value.files.map(normalizeFooterPayloadChangedFile).filter(Boolean).slice(0, 80);
    if (files.length) {
      chip.files = files;
      const filesTotal = Number(value.filesTotal);
      if (value.filesTruncated === true && Number.isFinite(filesTotal) && filesTotal > files.length) {
        chip.filesTotal = filesTotal;
        chip.filesTruncated = true;
      }
    }
  }
  if (value.contextUsage && typeof value.contextUsage === "object") {
    const percent = typeof value.contextUsage.percent === "number" ? value.contextUsage.percent : Number.NaN;
    const contextWindow = Number(value.contextUsage.contextWindow);
    chip.contextUsage = {
      percent: Number.isFinite(percent) ? percent : null,
      contextWindow: Number.isFinite(contextWindow) ? contextWindow : 0,
    };
  }
  if (value.usageWindows && typeof value.usageWindows === "object") {
    const primaryPercent = typeof value.usageWindows.primaryPercent === "number" ? value.usageWindows.primaryPercent : Number.NaN;
    const secondaryPercent = typeof value.usageWindows.secondaryPercent === "number" ? value.usageWindows.secondaryPercent : Number.NaN;
    if (Number.isFinite(primaryPercent) || Number.isFinite(secondaryPercent)) {
      chip.usageWindows = {
        ...(Number.isFinite(primaryPercent) ? { primaryPercent } : {}),
        ...(Number.isFinite(secondaryPercent) ? { secondaryPercent } : {}),
      };
    }
  }
  return chip;
}

function normalizeFooterProviderUsageWindow(value) {
  if (!value || typeof value !== "object") return null;
  const label = cleanFooterPayloadText(value.label, "Usage window", 32);
  const usedPercent = Number(value.usedPercent);
  if (!Number.isFinite(usedPercent) || usedPercent < 0 || usedPercent > 100) return null;
  const window = { label, usedPercent };
  const windowMinutes = typeof value.windowMinutes === "number" ? value.windowMinutes : Number.NaN;
  if (Number.isFinite(windowMinutes) && windowMinutes > 0) window.windowMinutes = windowMinutes;
  const resetAt = typeof value.resetAt === "number" ? value.resetAt : Number.NaN;
  if (Number.isFinite(resetAt) && resetAt >= 0) window.resetAt = resetAt;
  const resetAfterSeconds = typeof value.resetAfterSeconds === "number" ? value.resetAfterSeconds : Number.NaN;
  if (Number.isFinite(resetAfterSeconds) && resetAfterSeconds >= 0) window.resetAfterSeconds = resetAfterSeconds;
  return window;
}

function normalizeFooterProviderUsage(value) {
  if (!value || typeof value !== "object") return null;
  if (value.provider !== "anthropic" && value.provider !== "openai-codex") return null;
  const capturedAt = typeof value.capturedAt === "number" ? value.capturedAt : Number.NaN;
  if (!Number.isFinite(capturedAt) || capturedAt <= 0) return null;
  const primary = normalizeFooterProviderUsageWindow(value.primary);
  const secondary = normalizeFooterProviderUsageWindow(value.secondary);
  if (!primary && !secondary) return null;
  const plan = cleanFooterPayloadText(value.plan, "", 80);
  return {
    provider: value.provider,
    capturedAt,
    ...(primary ? { primary } : {}),
    ...(secondary ? { secondary } : {}),
    ...(plan ? { plan } : {}),
  };
}

function currentGitFooterCacheCwd(tabId = activeTabId) {
  const tab = tabs.find((item) => item.id === tabId) || activeTab();
  return latestWorkspace?.cwd || tab?.cwd || "";
}

function parseGitFooterWebuiPayloadRaw(raw) {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.type !== GIT_FOOTER_WEBUI_PAYLOAD_TYPE || parsed.version !== GIT_FOOTER_WEBUI_PAYLOAD_VERSION) return null;
    const main = Array.isArray(parsed.main) ? parsed.main.map(normalizeFooterPayloadChip).filter(Boolean).slice(0, 8) : [];
    const meta = Array.isArray(parsed.meta) ? parsed.meta.map(normalizeFooterPayloadChip).filter(Boolean).slice(0, 10) : [];
    const visibility = normalizeGitFooterWebuiVisibility(parsed.visibility);
    const providerUsage = normalizeFooterProviderUsage(parsed.providerUsage);
    if (!main.length && !meta.length && !parsed.visibility && !providerUsage) return null;
    return { main, meta, visibility, ...(providerUsage ? { providerUsage } : {}) };
  } catch {
    return null;
  }
}

function parseRemoteWebuiControlsPayloadRaw(raw) {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.type !== REMOTE_WEBUI_CONTROLS_PAYLOAD_TYPE || parsed.version !== REMOTE_WEBUI_CONTROLS_PAYLOAD_VERSION) return null;
    if (parsed.featureId !== "remoteWebui") return null;
    const commands = parsed.commands && typeof parsed.commands === "object" ? parsed.commands : {};
    return {
      title: cleanFooterPayloadText(parsed.title, "Remote WebUI", 80),
      description: cleanFooterPayloadText(parsed.description, "Trusted-LAN browser access controlled by the Remote WebUI package.", 240),
      commands: {
        open: typeof commands.open === "string" ? commands.open : "/remote",
        close: typeof commands.close === "string" ? commands.close : "/remote close",
        refresh: typeof commands.refresh === "string" ? commands.refresh : "/remote refresh",
        status: typeof commands.status === "string" ? commands.status : "/remote status",
        authOn: typeof commands.authOn === "string" ? commands.authOn : "/remote auth on",
        authOff: typeof commands.authOff === "string" ? commands.authOff : "/remote auth off",
      },
    };
  } catch {
    return null;
  }
}

function remoteWebuiControlsPayload() {
  if (isOptionalFeatureDisabled("remoteWebui")) return null;
  return parseRemoteWebuiControlsPayloadRaw(statusEntries.get(REMOTE_WEBUI_CONTROLS_STATUS_KEY));
}

function remoteWebuiDefaultPortArg() {
  const port = Number.parseInt(String(latestNetwork?.port || DEFAULT_WEBUI_PORT), 10);
  return Number.isFinite(port) && port > 0 && port <= 65535 && String(port) !== DEFAULT_WEBUI_PORT ? ` --port ${port}` : "";
}

function remoteWebuiFallbackCommand(name, fallback) {
  const portArg = remoteWebuiDefaultPortArg();
  const commands = {
    open: `/remote${portArg}`,
    close: `/remote close${portArg}`,
    refresh: `/remote refresh${portArg}`,
    status: `/remote status${portArg}`,
    authOn: `/remote auth on${portArg}`,
    authOff: `/remote auth off${portArg}`,
  };
  return commands[name] || fallback;
}

function remoteWebuiCommand(name, fallback) {
  return remoteWebuiControlsPayload()?.commands?.[name] || remoteWebuiFallbackCommand(name, fallback);
}

function readCachedGitFooterWebuiPayloadRaw() {
  try {
    const cached = JSON.parse(localStorage.getItem(GIT_FOOTER_WEBUI_PAYLOAD_CACHE_KEY) || "null");
    if (!cached || typeof cached.raw !== "string") return null;
    const cachedCwd = typeof cached.cwd === "string" ? cached.cwd : "";
    const currentCwd = currentGitFooterCacheCwd();
    if (cachedCwd && currentCwd && cachedCwd !== currentCwd) return null;
    return cached.raw;
  } catch {
    return null;
  }
}

function cacheGitFooterWebuiPayload(raw, tabId = activeTabId) {
  if (!parseGitFooterWebuiPayloadRaw(raw)) return;
  try {
    localStorage.setItem(GIT_FOOTER_WEBUI_PAYLOAD_CACHE_KEY, JSON.stringify({
      raw,
      cwd: currentGitFooterCacheCwd(tabId),
      savedAt: Date.now(),
    }));
  } catch {
    // Cached footer payloads are best-effort; live extension payloads still work.
  }
}

function clearGitFooterWebuiPayloadCache() {
  try {
    localStorage.removeItem(GIT_FOOTER_WEBUI_PAYLOAD_CACHE_KEY);
  } catch {
    // Ignore storage failures; toggles should still work for this page load.
  }
}

function parseGitFooterWebuiPayload() {
  if (isOptionalFeatureDisabled("gitFooterStatus")) return null;

  const livePayload = parseGitFooterWebuiPayloadRaw(statusEntries.get(GIT_FOOTER_WEBUI_STATUS_KEY));
  if (livePayload) return livePayload;

  const commandsStillLoading = availableCommands.length === 0 && rawAvailableCommands.length === 0;
  const extensionDetected = hasAvailableCommand("git-footer-refresh") || optionalFeatureAvailability.gitFooterStatus;
  if (!commandsStillLoading && !extensionDetected) return null;
  return parseGitFooterWebuiPayloadRaw(readCachedGitFooterWebuiPayloadRaw());
}

function footerPayloadChipVisible(payload, chip, area = "main") {
  if (!chip?.key) return true;
  if (area === "meta" && chip.key === "context") return gitFooterPayloadVisible(payload, "context-meta");
  return gitFooterPayloadVisible(payload, chip.key);
}

function footerPayloadWithLiveModel(payload) {
  if (!payload) return payload;
  const visible = (key) => gitFooterPayloadVisible(payload, key);
  const mainSource = payload.main.filter((chip) => footerPayloadChipVisible(payload, chip, "main"));
  const metaSource = payload.meta.filter((chip) => footerPayloadChipVisible(payload, chip, "meta"));
  const model = currentState?.model ? shortModelLabel(currentState.model) : "";
  const effort = footerThinkingDisplay();
  const workspace = normalizeGitWorkspaceInfo(activeTab()?.gitWorkspace);
  const worktreeLabel = gitWorkspaceBadgeLabel(workspace);
  const hasThinkingChip = [...mainSource, ...metaSource].some((chip) => chip?.key === "thinking");
  const hasWorktreeChip = [...mainSource, ...metaSource].some((chip) => chip?.key === "worktree");
  const contextChip = (chip) => {
    const usageUnknown = contextUsageUnknownAfterCompaction();
    const value = usageUnknown ? footerContextDisplayWithAuto(unknownFooterContextText(chip?.contextUsage)) : footerContextDisplayWithAuto(chip?.value);
    const contextUsage = usageUnknown ? contextUsageWithUnknownPercent(chip?.contextUsage) : chip?.contextUsage;
    return { ...chip, value, title: `context: ${value}`, ...(contextUsage ? { contextUsage } : {}) };
  };
  const effortChip = (chip) => ({ ...chip, key: "thinking", label: "effort", value: effort, title: `effort: ${effort}`, tone: "mauve" });
  const worktreeChip = () => ({ key: "worktree", label: "worktree", value: worktreeLabel, icon: "🌳", tone: workspace?.isMainWorktree ? "teal" : "green", title: workspace?.worktreePath || "Git worktree" });
  const splitChip = (chip) => {
    if (chip?.key === "context") return [contextChip(chip)];
    if (chip?.key === "thinking") return visible("thinking") ? [effortChip(chip)] : [];
    if (chip?.key !== "model" || !model) return [chip];
    const modelChip = { ...chip, value: model, title: `model: ${model}` };
    return hasThinkingChip || !visible("thinking") ? [modelChip] : [modelChip, effortChip(chip)];
  };
  const meta = metaSource.flatMap(splitChip);
  if (visible("worktree") && worktreeLabel && !hasWorktreeChip) meta.splice(Math.min(meta.length, 2), 0, worktreeChip());
  return {
    main: mainSource.flatMap(splitChip),
    meta,
    visibility: payload.visibility,
  };
}

function footerMetaClassForPayload(chip) {
  const base = FOOTER_META_CLASS_BY_KEY.get(chip.key) || "footer-extension-meta";
  const toneClass = chip.tone ? ` tone-${chip.tone}` : "";
  return `${base}${toneClass}`.trim();
}

function isRedundantFooterTooltipTitle(sourceTitle, chip, value) {
  const normalized = cleanStatusText(sourceTitle).toLowerCase();
  if (!normalized) return true;
  const labels = [chip?.label, chip?.key].map((item) => cleanFooterPayloadText(item, "").toLowerCase()).filter(Boolean);
  return [`current: ${value}`, ...labels.map((label) => `${label}: ${value}`)].some((item) => normalized === cleanStatusText(item).toLowerCase());
}

function gitFooterPayloadTooltip(chip, options = {}) {
  const key = cleanFooterPayloadText(chip?.key, "");
  const value = cleanFooterPayloadText(chip?.value, "—");
  const sourceTitle = cleanFooterPayloadText(chip?.title, "", 4000);
  const action = cleanFooterPayloadText(options.action, "", 1000);
  const parts = [GIT_FOOTER_TOOLTIP_COPY[key] || "Extension-provided git-footer-status item.", `Current: ${value}`];
  if (sourceTitle && !isRedundantFooterTooltipTitle(sourceTitle, chip, value)) parts.push(sourceTitle);
  if (action) parts.push(action);
  return parts.join("\n");
}

function gitFooterTooltipAlign(chip) {
  if (["tokens", "cwd"].includes(chip?.key)) return "start";
  if (["model", "thinking"].includes(chip?.key)) return "end";
  return "center";
}

function footerTuiItem(value, className = "", options = {}) {
  const text = cleanStatusText(value);
  const isAction = typeof options.onClick === "function";
  const node = make(isAction ? "button" : "span", `footer-tui-item ${className}${isAction ? " footer-tui-action" : ""}`.trim());
  if (options.middleTruncate) setMiddleTruncatedText(node, text);
  else node.textContent = text;
  if (isAction) {
    node.type = "button";
    node.addEventListener("click", options.onClick);
  }
  if (options.title) node.title = options.title;
  return node;
}

function renderTuiFooterLine({ cwd, cwdTitle, message = "", stats = [], model = "" } = {}) {
  const tab = activeTab();
  const workspace = normalizeGitWorkspaceInfo(tab?.gitWorkspace);
  const worktreeLabel = gitWorkspaceBadgeLabel(workspace);
  const line = make("div", "footer-line footer-line-tui");
  line.append(footerTuiItem(cwd || "loading…", "footer-tui-cwd", tab ? {
    onClick: changeActiveTabCwd,
    title: cwdTitle || `Change cwd for ${tab.title}: ${cwd}`,
    middleTruncate: true,
  } : { title: cwdTitle, middleTruncate: true }));
  if (worktreeLabel) line.append(footerTuiItem(worktreeLabel, "footer-tui-worktree", { title: workspace?.worktreePath || worktreeLabel }));
  if (message) line.append(footerTuiItem(message, "footer-tui-status"));
  for (const stat of stats.filter(Boolean)) line.append(footerTuiItem(stat, "footer-tui-stat"));
  if (model) {
    line.append(make("span", "footer-tui-spacer"));
    line.append(footerTuiItem(model, "footer-tui-model", {
      onClick: () => setFooterModelPickerOpen(!footerModelPickerOpen),
      title: `Change scoped model: ${model}`,
    }));
  }
  return line;
}

function insertChangedFilePathReference(path) {
  const input = elements.promptInput;
  if (!input) return;
  const reference = formatPathReference(path);
  const start = input.selectionStart ?? input.value.length;
  const end = input.selectionEnd ?? start;
  const before = input.value.slice(0, start);
  const after = input.value.slice(end);
  const prefix = before && !/\s$/.test(before) ? " " : "";
  const suffix = after && !/^\s/.test(after) ? " " : "";
  input.value = `${before}${prefix}${reference}${suffix}${after}`;
  const cursor = before.length + prefix.length + reference.length + suffix.length;
  input.setSelectionRange(cursor, cursor);
  input.focus();
  resizePromptInput();
  addEvent(`Added ${reference} to the prompt`, "info");
}

function changedFileDisplayPath(file) {
  if (!file?.oldPath) return file?.path || "";
  return `${file.oldPath} → ${file.path}`;
}

function renderChangedFileButton(file) {
  const button = make("button", `footer-changed-file ${file.kind}`.trim());
  button.type = "button";
  button.title = `Add ${file.path} as an @ reference`;
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    insertChangedFilePathReference(file.path);
  });
  button.append(
    make("span", "footer-changed-file-status", file.status || ""),
    make("span", "footer-changed-file-path", changedFileDisplayPath(file)),
  );
  return button;
}

function renderChangedFilesGroup(kind, files) {
  if (!files.length) return null;
  const group = make("span", "footer-changed-files-group");
  group.append(make("span", "footer-changed-files-heading", `${FOOTER_CHANGED_FILE_KIND_LABELS[kind] || kind} (${files.length})`));
  const list = make("span", "footer-changed-files-list");
  list.append(...files.map(renderChangedFileButton));
  group.append(list);
  return group;
}

function applyFooterChangedFilesDropdown(node, chip, payload) {
  if (!gitFooterPayloadVisible(payload, "webui-changed-files-popover") || chip?.key !== "changes" || !Array.isArray(chip.files) || chip.files.length === 0) return node;
  node.classList.add("footer-changes-with-files");
  node.tabIndex = 0;
  node.removeAttribute("data-tooltip");
  node.setAttribute("aria-label", `changes: ${chip.value}. Hover or focus to choose changed files. Click a file to add it as an @ reference.`);

  const popover = make("span", "footer-changed-files-popover");
  popover.append(make("span", "footer-changed-files-title", chip.filesTruncated ? `Changed files (showing ${chip.files.length} of ${chip.filesTotal})` : "Changed files"));
  for (const kind of FOOTER_CHANGED_FILE_KIND_ORDER) {
    const group = renderChangedFilesGroup(kind, chip.files.filter((file) => file.kind === kind));
    if (group) popover.append(group);
  }
  if (chip.filesTruncated) popover.append(make("span", "footer-changed-files-truncated", `${chip.filesTotal - chip.files.length} more files not shown; open the Git Changes dialog for the full list.`));
  node.append(popover);
  return node;
}

function renderGitFooterPayloadMetric(chip, payload) {
  const options = { tooltipAlign: gitFooterTooltipAlign(chip), targetKey: `git-footer:metric:${chip.key}` };
  const piAction = gitFooterPayloadVisible(payload, "webui-pi-calibration") ? applyGitFooterPiCalibrationOptions(chip, options) : "";
  const contextAction = gitFooterPayloadVisible(payload, "webui-context-auto-compaction") ? applyGitFooterContextToggleOptions(chip, options) : "";
  const action = piAction || contextAction;
  options.title = gitFooterPayloadTooltip(chip, { action });
  const node = footerMetric(chip.icon || "•", chip.label, chip.value, chip.tone ? `tone-${chip.tone}` : "", options);
  if (chip.contextUsage) applyFooterContextUsage(node, chip.contextUsage);
  if (chip.usageWindows) applyFooterUsageWindows(node, chip.usageWindows);
  return bindGitFooterContextMenu(node, chip);
}

function gitFooterSyncCounts(value) {
  const text = String(value || "");
  const aheadMatch = text.match(/[↑⇡]\s*(\d+)/u);
  const behindMatch = text.match(/[↓⇣]\s*(\d+)/u);
  return {
    ahead: aheadMatch ? Number.parseInt(aheadMatch[1] || "0", 10) || 0 : 0,
    behind: behindMatch ? Number.parseInt(behindMatch[1] || "0", 10) || 0 : 0,
  };
}

function gitFooterSyncAction(chip) {
  if (chip?.key !== "sync") return "";
  const { ahead, behind } = gitFooterSyncCounts(chip.value);
  if (behind > 0 && ahead > 0) return "pull-push";
  if (behind > 0) return "pull";
  if (ahead > 0) return "push";
  return "";
}

function gitFooterCurrentBranch() {
  const gitChip = parseGitFooterWebuiPayload()?.meta?.find((chip) => chip.key === "git");
  const value = cleanFooterPayloadText(gitChip?.value, "").toLowerCase();
  return value && value !== "no repo" ? cleanFooterPayloadText(gitChip.value, "") : "";
}

function gitFailureDisplayText(response, fallback = "Git operation failed") {
  const errorText = String(response?.error || "").trim();
  const hintText = String(response?.hint || "").trim();
  const result = response?.data && typeof response.data === "object" ? { ...response.data } : null;
  if (result && errorText) {
    if (String(result.stderr || "").trim() === errorText) result.stderr = "";
    if (String(result.stdout || "").trim() === errorText) result.stdout = "";
  }
  const parts = [errorText || fallback, hintText, formatGitCommandResult(result)].map((part) => String(part || "").trim()).filter(Boolean);
  const seen = new Set();
  return parts.filter((part) => {
    const key = part.replace(/\r\n/g, "\n");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).join("\n\n");
}

function setGitPullErrorBusy(busy) {
  gitPullErrorContext = { ...gitPullErrorContext, busy: !!busy };
  for (const button of [elements.gitPullErrorMergeButton, elements.gitPullErrorRebaseButton, elements.gitPullErrorReviewButton, elements.gitPullErrorCloseButton]) {
    if (button) button.disabled = !!busy;
  }
  if (elements.gitPullErrorDialog) elements.gitPullErrorDialog.setAttribute("aria-busy", busy ? "true" : "false");
}

function closeGitPullErrorDialog() {
  if (gitPullErrorContext.busy) return;
  if (elements.gitPullErrorDialog?.open) elements.gitPullErrorDialog.close();
}

function openGitPullErrorDialog(message, { code = "", tabId = null, syncValue = "" } = {}) {
  const text = String(message || "git pull from origin failed").trim();
  const diverged = code === "DIVERGED";
  gitPullErrorText = text;
  gitPullErrorContext = {
    code,
    tabId: typeof tabId === "string" && tabId ? tabId : null,
    syncValue: String(syncValue || ""),
    busy: false,
    requestId: gitPullErrorContext.requestId + 1,
  };
  if (!elements.gitPullErrorDialog?.showModal || !elements.gitPullErrorOutput) {
    window.alert(`${diverged ? "Branches diverged" : "Git pull failed"}\n\n${text}`);
    return;
  }
  if (elements.gitPullErrorDialogTitle) elements.gitPullErrorDialogTitle.textContent = diverged ? "Branches diverged" : "Git pull failed";
  if (elements.gitPullErrorDialogDescription) {
    elements.gitPullErrorDialogDescription.textContent = diverged
      ? "Local and remote contain unique commits. This does not mean conflicts exist; conflicts are known only after a merge or rebase is attempted."
      : "The repository was not changed by the failed pull. Review or copy the complete error output below.";
  }
  elements.gitPullErrorOutput.textContent = text;
  if (elements.gitPullErrorRecovery) elements.gitPullErrorRecovery.hidden = !diverged;
  elements.gitPullErrorCloseButton?.classList.toggle("primary", !diverged);
  if (elements.gitPullErrorStatus) {
    elements.gitPullErrorStatus.textContent = diverged
      ? "Review the incoming changes, merge them, or rebase your local commits. No integration runs without confirmation."
      : "Select the output or use Copy error output.";
    elements.gitPullErrorStatus.classList.remove("error", "success");
  }
  setGitPullErrorBusy(false);
  if (!elements.gitPullErrorDialog.open) elements.gitPullErrorDialog.showModal();
  queueMicrotask(() => (diverged ? elements.gitPullErrorReviewButton : elements.gitPullErrorCopyButton)?.focus({ preventScroll: true }));
}

async function copyGitPullErrorOutput() {
  if (!gitPullErrorText) return;
  if (elements.gitPullErrorCopyButton) elements.gitPullErrorCopyButton.disabled = true;
  try {
    await copyText(gitPullErrorText);
    if (elements.gitPullErrorStatus) {
      elements.gitPullErrorStatus.textContent = "Error output copied to the clipboard.";
      elements.gitPullErrorStatus.classList.add("success");
      elements.gitPullErrorStatus.classList.remove("error");
    }
    addEvent("copied Git pull error output", "info");
  } catch (error) {
    const message = `Copy failed: ${error.message || String(error)}`;
    if (elements.gitPullErrorStatus) {
      elements.gitPullErrorStatus.textContent = message;
      elements.gitPullErrorStatus.classList.add("error");
      elements.gitPullErrorStatus.classList.remove("success");
    }
    addEvent(`Git pull error output copy failed: ${error.message || String(error)}`, "error");
  } finally {
    if (elements.gitPullErrorCopyButton) elements.gitPullErrorCopyButton.disabled = false;
  }
}

function reviewGitPullDivergence() {
  if (gitPullErrorContext.code !== "DIVERGED" || !gitPullErrorContext.tabId || gitPullErrorContext.busy) return;
  const tabId = gitPullErrorContext.tabId;
  closeGitPullErrorDialog();
  openGitChangesDialog(tabId);
}

async function integrateGitPullDivergence(mode) {
  if (!["merge", "rebase"].includes(mode) || gitPullErrorContext.code !== "DIVERGED" || !gitPullErrorContext.tabId || gitPullErrorContext.busy) return false;
  const { tabId, syncValue, requestId } = gitPullErrorContext;
  const targetTab = tabs.find((tab) => tab.id === tabId);
  const activeBranch = tabId === activeTabId ? gitFooterCurrentBranch() : "";
  const target = activeBranch || targetTab?.title || targetTab?.cwd || "the selected branch";
  const merge = mode === "merge";
  const confirmed = await appConfirmText([
    `${merge ? "Merge upstream changes into" : "Rebase local commits onto the upstream of"} ${target}?`,
    "",
    merge
      ? "This preserves both histories and may create a merge commit. Conflicts are possible but are not currently known."
      : "This replays local commits on top of upstream and rewrites their commit IDs. Conflicts are possible but are not currently known.",
  ].join("\n"), {
    affected: `Git history for ${target}`,
    confirmLabel: merge ? "Merge changes" : "Rebase commits",
    danger: !merge,
  });
  if (!confirmed || gitPullErrorContext.requestId !== requestId) return false;

  const tabContext = activeTabContext(tabId);
  let pushSyncValue = "";
  setGitPullErrorBusy(true);
  gitFooterSyncInFlightByTab.add(tabId);
  if (isCurrentTabContext(tabContext)) renderFooter();
  if (elements.gitPullErrorStatus) elements.gitPullErrorStatus.textContent = merge ? "Merging upstream changes…" : "Rebasing local commits…";
  try {
    const response = await api("/api/git-changes/integrate", { method: "POST", body: { mode, confirmed: true }, tabId });
    if (gitPullErrorContext.requestId !== requestId) return false;
    if (!response.ok) {
      const message = gitFailureDisplayText(response, `git ${mode} failed`);
      addEvent(message, "error");
      setGitPullErrorBusy(false);
      if (response.code === "CONFLICTS") {
        closeGitPullErrorDialog();
        openGitChangesDialog(tabId);
        return false;
      }
      openGitPullErrorDialog(message, { code: response.code || "", tabId, syncValue });
      return false;
    }
    setGitPullErrorBusy(false);
    closeGitPullErrorDialog();
    addEvent(`${merge ? "Merged" : "Rebased"} upstream changes.`, "success");
    requestGitFooterWebuiPayload(tabContext, { force: true });
    const freshAheadValue = response.data?.changes?.summary?.ahead;
    const freshAhead = Number(freshAheadValue);
    if (freshAheadValue !== undefined) {
      if (Number.isFinite(freshAhead) && freshAhead > 0) pushSyncValue = `⇡${freshAhead}`;
    } else if (gitFooterSyncCounts(syncValue).ahead > 0) {
      pushSyncValue = syncValue;
    }
  } catch (error) {
    if (gitPullErrorContext.requestId !== requestId) return false;
    const message = error.message || String(error);
    addEvent(message, "error");
    setGitPullErrorBusy(false);
    openGitPullErrorDialog(message, { tabId, syncValue });
    return false;
  } finally {
    gitFooterSyncInFlightByTab.delete(tabId);
    if (isCurrentTabContext(tabContext)) renderFooter();
  }
  if (pushSyncValue) await pushGitFooterSync(tabId, pushSyncValue);
  return true;
}

async function pullGitFooterSync(tabId = activeTabId, { syncValue = "" } = {}) {
  if (!tabId || gitFooterSyncInFlightByTab.has(tabId)) return false;
  const tabContext = activeTabContext(tabId);
  hideFooterTooltip();
  gitFooterSyncInFlightByTab.add(tabId);
  if (isCurrentTabContext(tabContext)) renderFooter();
  try {
    const response = await api("/api/git-changes/pull", { method: "POST", body: { remote: "origin" }, tabId });
    if (!response.ok) {
      const message = gitFailureDisplayText(response, "git pull from origin failed");
      addEvent(message, "error");
      openGitPullErrorDialog(message, { code: response.code || "", tabId, syncValue });
      return false;
    }
    addEvent("Pulled Git changes from origin.", "success");
    requestGitFooterWebuiPayload(tabContext, { force: true });
    return true;
  } catch (error) {
    const message = error.message || String(error);
    addEvent(message, "error");
    openGitPullErrorDialog(message, { code: error?.code || "", tabId, syncValue });
    return false;
  } finally {
    gitFooterSyncInFlightByTab.delete(tabId);
    if (isCurrentTabContext(tabContext)) renderFooter();
  }
}

async function pullThenPushGitFooterSync(tabId = activeTabId, syncValue = "") {
  const pulled = await pullGitFooterSync(tabId, { syncValue });
  if (!pulled) return;
  await pushGitFooterSync(tabId, syncValue);
}

async function pushGitFooterSync(tabId = activeTabId, syncValue = "") {
  if (!tabId || gitFooterSyncInFlightByTab.has(tabId)) return;
  const outgoing = gitFooterSyncCounts(syncValue).ahead;
  if (outgoing <= 0) return;
  let recoverWithPullFirst = false;
  const tabContext = activeTabContext(tabId);
  const tab = tabs.find((item) => item.id === tabId);
  const target = tab?.title || tab?.cwd || "this tab";
  hideFooterTooltip();
  const branch = gitFooterCurrentBranch();
  const protectedWarning = ["main", "master"].includes(branch)
    ? `\n\nWarning: ${branch} is usually a protected/shared branch. Consider pushing a feature branch and opening a PR instead.`
    : "";
  if (!(await appConfirmText(`Run git push for ${outgoing} outgoing commit${outgoing === 1 ? "" : "s"} in ${target}?${protectedWarning}`, { affected: `Remote Git branch ${branch || "current branch"}`, confirmLabel: "Push commits" }))) return;

  gitFooterSyncInFlightByTab.add(tabId);
  if (isCurrentTabContext(tabContext)) renderFooter();
  try {
    const response = await api("/api/git-workflow/push", { method: "POST", body: {}, tabId });
    if (!response.ok) {
      if (response.code === "NO_UPSTREAM") {
        const publish = await appConfirmText(`${response.error}\n\n${response.hint || ""}\n\nRun git push -u to publish ${branch || "the current branch"} and set its upstream?`, { affected: `Remote Git branch ${branch || "current branch"}`, confirmLabel: "Publish branch" });
        if (publish) {
          const upstreamResponse = await api("/api/git-workflow/push", { method: "POST", body: { setUpstream: true }, tabId });
          if (!upstreamResponse.ok) throw new Error([upstreamResponse.error, upstreamResponse.hint].filter(Boolean).join("\n"));
          addEvent(`Published ${upstreamResponse.data?.branch || "branch"} to ${upstreamResponse.data?.remote || "the remote"} and set its upstream.`, "success");
          requestGitFooterWebuiPayload(tabContext, { force: true });
          return;
        }
        throw new Error([response.error, response.hint].filter(Boolean).join("\n"));
      }
      if (response.code === "NON_FAST_FORWARD") {
        recoverWithPullFirst = true;
      } else {
        const detail = [response.error, response.hint, formatGitCommandResult(response.data)].filter(Boolean).join("\n\n").trim();
        throw new Error(detail || "git push failed");
      }
    } else {
      addEvent(`Pushed ${outgoing} outgoing commit${outgoing === 1 ? "" : "s"}.`, "success");
      requestGitFooterWebuiPayload(tabContext, { force: true });
    }
  } catch (error) {
    addEvent(error.message || String(error), "error");
  } finally {
    gitFooterSyncInFlightByTab.delete(tabId);
    if (isCurrentTabContext(tabContext)) renderFooter();
  }
  if (recoverWithPullFirst) {
    addEvent("Push found incoming commits. Starting pull-first recovery.", "info");
    await pullThenPushGitFooterSync(tabId, syncValue);
  }
}

function renderGitFooterPayloadMeta(chip, tab, payload) {
  const options = { targetKey: `git-footer:meta:${chip.key}` };
  const visible = (key) => gitFooterPayloadVisible(payload, key);
  let action = "";
  if (chip.key === "cwd" && tab && visible("webui-cwd-picker")) {
    options.onClick = changeActiveTabCwd;
    action = `Click to change the working directory for ${tab.title}.`;
  } else if (chip.key === "git" && cleanFooterPayloadText(chip.value, "").toLowerCase() === "no repo" && visible("webui-git-init")) {
    options.onClick = () => startGitInitWorkflow();
    action = "No Git repository detected. Click to initialize a repo, create README.md, add origin, and push main.";
  } else if (chip.key === "git" && visible("webui-branch-picker")) {
    options.onClick = () => setFooterBranchPickerOpen(!footerBranchPickerOpen);
    action = "Click to open, create, or switch branches. Worktree actions are the safe default for parallel work.";
  } else if (chip.key === "worktree" && visible("webui-branch-picker")) {
    options.onClick = () => setFooterBranchPickerOpen(!footerBranchPickerOpen);
    action = "Click to manage branch worktrees for this repository.";
  } else if (chip.key === "sync" && visible("webui-sync-push")) {
    const tabId = tab?.id || activeTabId;
    const syncAction = gitFooterSyncAction(chip);
    const inFlight = tabId ? gitFooterSyncInFlightByTab.has(tabId) : false;
    if (syncAction === "pull") {
      options.onClick = () => pullGitFooterSync(tabId);
      action = inFlight ? "Pulling from origin." : "Click to pull from origin with fast-forward only.";
    } else if (syncAction === "pull-push") {
      options.onClick = () => pullThenPushGitFooterSync(tabId, chip.value);
      action = inFlight ? "Pulling from origin before pushing local commits." : "Click to pull from origin with fast-forward only, then push if the pull succeeds.";
    } else if (syncAction === "push") {
      options.onClick = () => pushGitFooterSync(tabId, chip.value);
      action = inFlight ? "Pushing local commits to the configured remote." : "Click to push local commits to the configured remote.";
    }
    options.ariaBusy = inFlight;
    options.disabled = inFlight;
  } else if (chip.key === "changes" && visible("webui-changes-modal")) {
    options.onClick = () => openGitChangesDialog(tab?.id || activeTabId);
    action = "Click to view the current git diff.";
  } else if (chip.key === "git-state" && visible("webui-changes-modal")) {
    options.onClick = () => openGitChangesDialog(tab?.id || activeTabId);
    action = "Click to open the conflicts and operation panel with continue/abort actions.";
  } else if (chip.key === "git-extra" && visible("webui-git-tools-modal")) {
    const toolsSection = gitToolsSectionForExtraChip(chip.value);
    options.onClick = () => openGitToolsFromFooter(toolsSection);
    action = `Click to open git tools (${toolsSection} first): stash, worktrees, undo, submodules, tags, signing.`;
  } else if (chip.key === "model" && visible("webui-model-picker")) {
    options.onClick = () => setFooterModelPickerOpen(!footerModelPickerOpen);
    action = "Click to choose another model.";
  } else if (chip.key === "thinking" && visible("webui-thinking-picker")) {
    options.onClick = () => setFooterThinkingPickerOpen(!footerThinkingPickerOpen);
    action = "Click to change thinking effort.";
  }
  action = (visible("webui-context-auto-compaction") ? applyGitFooterContextToggleOptions(chip, options) : "") || action;
  options.title = gitFooterPayloadTooltip(chip, { action });
  options.tooltipAlign = gitFooterTooltipAlign(chip);
  options.middleTruncate = chip.key === "cwd";
  const node = footerMeta(chip.label, chip.value, footerMetaClassForPayload(chip), options);
  applyFooterChangedFilesDropdown(node, chip, payload);
  if (["git", "worktree"].includes(chip.key) && options.onClick && cleanFooterPayloadText(chip.value, "").toLowerCase() !== "no repo") {
    node.setAttribute("aria-haspopup", "listbox");
    node.setAttribute("aria-expanded", footerBranchPickerOpen ? "true" : "false");
  }
  if (chip.contextUsage) applyFooterContextUsage(node, chip.contextUsage);
  if (chip.usageWindows) applyFooterUsageWindows(node, chip.usageWindows);
  return bindGitFooterContextMenu(node, chip);
}

// Shape key for a footer chip with the frequently-changing fields removed, so
// live streaming metrics (token counts, tok/s, cost, context %) can be updated
// in place without tearing down the footer DOM (and any open dropdown inside it).
function gitFooterChipShapeKey(chip) {
  const shape = {};
  for (const [key, value] of Object.entries(chip || {})) {
    if (key === "value") continue;
    // Usage percentages/reset details make its title dynamic. The fast path
    // refreshes the complete tooltip and aria-label in place below.
    if (key === "title" && chip?.key === "usage") continue;
    if (key === "contextUsage") {
      shape.contextUsage = value ? true : false;
      continue;
    }
    if (key === "usageWindows") {
      shape.usageWindows = value ? true : false;
      continue;
    }
    shape[key] = value;
  }
  return JSON.stringify(shape);
}

function footerBranchPickerRenderKey() {
  // Branch data arrives asynchronously after the picker opens. Include its full
  // serializable state so the footer fast path cannot leave the initial loading
  // card mounted after fresher branch/worktree data has arrived.
  return footerBranchPickerOpen ? JSON.stringify(footerBranchPickerState) : "";
}

function footerModelPickerRenderKey() {
  if (!footerModelPickerOpen) return "";
  return `${footerScopedModelLayout}:${orderedFooterScopedModels().map(footerScopedModelKey).join(",")}`;
}

function gitFooterPickerStateKey(payload) {
  const tabContext = activeTabContext();
  const refreshInFlight = tabContext.tabId ? gitFooterPayloadRefreshInFlightByTab.has(tabContext.tabId) : false;
  const syncInFlight = tabContext.tabId ? gitFooterSyncInFlightByTab.has(tabContext.tabId) : false;
  const piCalibrationInFlight = tabContext.tabId ? gitFooterPiCalibrationInFlightByTab.has(tabContext.tabId) : false;
  const refreshAvailable = hasLoadedRpcCommand("git-footer-refresh");
  return `${footerModelPickerOpen ? 1 : 0}|${footerModelPickerRenderKey()}|${footerThinkingPickerOpen ? 1 : 0}|${footerBranchPickerOpen ? 1 : 0}|${footerBranchPickerRenderKey()}|${mobileFooterExpanded ? 1 : 0}|${refreshInFlight ? 1 : 0}|${syncInFlight ? 1 : 0}|${piCalibrationInFlight ? 1 : 0}|${refreshAvailable ? 1 : 0}|${gitFooterPayloadVisibilityKey(payload)}`;
}

function updateGitFooterChipNodeValue(node, chip, valueSelector) {
  if (!node) return;
  const valueNode = node.querySelector(valueSelector);
  const nextValue = String(chip.value ?? "");
  const middleTruncate = chip.key === "cwd";
  const middleTruncateActive = middleTruncate && !!splitMiddleTruncationText(nextValue).end;
  if (valueNode && (valueNode.textContent !== nextValue || valueNode.classList.contains("middle-truncate-value") !== middleTruncateActive)) {
    if (middleTruncate) setMiddleTruncatedText(valueNode, nextValue);
    else {
      valueNode.classList.remove("middle-truncate-value");
      valueNode.textContent = nextValue;
    }
  }
  const previousTooltip = node.getAttribute("data-tooltip");
  if (previousTooltip) {
    const nextTooltip = chip.key === "usage"
      ? gitFooterPayloadTooltip(chip)
      : previousTooltip.replace(/Current: [^\n]*/u, `Current: ${cleanFooterPayloadText(chip.value, "—")}`);
    if (nextTooltip !== previousTooltip) {
      node.setAttribute("data-tooltip", nextTooltip);
      node.setAttribute("aria-label", nextTooltip.replace(/\s+/g, " "));
      if (footerTooltipTarget === node && footerTooltipNode && !footerTooltipNode.hidden) {
        footerTooltipNode.textContent = nextTooltip;
        positionFooterTooltip(node);
      }
    }
  }
  if (chip.contextUsage) applyFooterContextUsage(node, chip.contextUsage);
  if (chip.usageWindows) applyFooterUsageWindows(node, chip.usageWindows);
}

let gitFooterRenderCache = null;

function invalidateGitFooterRenderCache() {
  gitFooterRenderCache = null;
}

function triggerGitFooterRefreshFromButton() {
  const tabContext = activeTabContext();
  if (!tabContext.tabId || gitFooterPayloadRefreshInFlightByTab.has(tabContext.tabId)) return;
  if (!resolveAvailableCommandName("git-footer-refresh", { rpcOnly: true })) {
    addEvent(optionalFeatureUnavailableMessage("gitFooterStatus"), "warn");
    return;
  }
  requestGitFooterWebuiPayload(tabContext, { force: true, silent: false, allowDuringRun: true });
}

function renderGitFooterRefreshButton() {
  const tabContext = activeTabContext();
  const inFlight = tabContext.tabId ? gitFooterPayloadRefreshInFlightByTab.has(tabContext.tabId) : false;
  const commandAvailable = !!resolveAvailableCommandName("git-footer-refresh", { rpcOnly: true });
  const button = make("button", "git-footer-refresh-button");
  button.type = "button";
  button.title = inFlight
    ? "Refreshing git footer status…"
    : commandAvailable
      ? "Refresh git footer status (/git-footer-refresh)"
      : optionalFeatureUnavailableMessage("gitFooterStatus");
  button.setAttribute("aria-label", inFlight ? "Refreshing git footer status" : "Refresh git footer status");
  if (!commandAvailable) button.setAttribute("aria-disabled", "true");
  if (inFlight) button.setAttribute("aria-busy", "true");
  button.disabled = inFlight || !tabContext.tabId;
  button.append(make("span", "git-footer-refresh-icon", "↻"));
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    triggerGitFooterRefreshFromButton();
  });
  return button;
}

function renderGitFooterPayload(payload) {
  const tab = activeTab();
  if (!gitFooterPayloadVisible(payload, "webui-details-button")) mobileFooterExpanded = false;
  if (!gitFooterPayloadVisible(payload, "webui-model-picker")) footerModelPickerOpen = false;
  if (!gitFooterPayloadVisible(payload, "webui-thinking-picker")) footerThinkingPickerOpen = false;
  if (!gitFooterPayloadVisible(payload, "webui-branch-picker")) footerBranchPickerOpen = false;
  const pickerKey = gitFooterPickerStateKey(payload);
  const mainKeys = payload.main.map(gitFooterChipShapeKey);
  const metaKeys = payload.meta.map(gitFooterChipShapeKey);

  // Fast path: only live metric values changed. Update text in place instead of
  // rebuilding the footer so buttons do not flicker and an open dropdown is not
  // destroyed/recreated/repositioned during streaming.
  const cache = gitFooterRenderCache;
  if (
    cache &&
    elements.statusBar.classList.contains("statusbar-git-footer") &&
    cache.pickerKey === pickerKey &&
    cache.mainKeys.length === mainKeys.length &&
    cache.metaKeys.length === metaKeys.length &&
    cache.mainKeys.every((key, index) => key === mainKeys[index]) &&
    cache.metaKeys.every((key, index) => key === metaKeys[index]) &&
    cache.mainNodes.every((node) => node.isConnected) &&
    cache.metaNodes.every((node) => node.isConnected)
  ) {
    payload.main.forEach((chip, index) => updateGitFooterChipNodeValue(cache.mainNodes[index], chip, ".footer-metric-value"));
    payload.meta.forEach((chip, index) => updateGitFooterChipNodeValue(cache.metaNodes[index], chip, ".footer-meta-value"));
    if (isFooterPickerOpen()) updateFooterModelPickerPosition();
    return;
  }

  closeGitFooterContextMenu({ returnFocus: false });
  elements.statusBar.replaceChildren();
  elements.statusBar.classList.remove("statusbar-tui-footer");
  elements.statusBar.classList.add("statusbar-git-footer");
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());

  const mainNodes = payload.main.map((chip) => renderGitFooterPayloadMetric(chip, payload));
  const row1 = make("div", "footer-line footer-line-main");
  row1.append(...mainNodes);

  const metaNodes = payload.meta.map((chip) => renderGitFooterPayloadMeta(chip, tab, payload));
  const row2 = make("div", "footer-line footer-line-meta");
  const row2Children = [...metaNodes];
  if (gitFooterPayloadVisible(payload, "webui-details-button")) {
    const footerToggle = make("button", "footer-details-toggle", mobileFooterExpanded ? "−" : "Details");
    footerToggle.type = "button";
    footerToggle.setAttribute("aria-label", mobileFooterExpanded ? "Minimize Git footer details" : "Show Git footer details");
    footerToggle.setAttribute("title", mobileFooterExpanded ? "Minimize Git footer details" : "Show Git footer details");
    footerToggle.setAttribute("aria-expanded", mobileFooterExpanded ? "true" : "false");
    footerToggle.addEventListener("click", () => setMobileFooterExpanded(!mobileFooterExpanded, { restoreFocus: true }));
    row2Children.push(footerToggle);
  }
  row2.append(...row2Children);

  const statusChildren = [row1, row2];
  if (gitFooterPayloadVisible(payload, "webui-refresh-button")) statusChildren.push(renderGitFooterRefreshButton());
  elements.statusBar.append(...statusChildren);
  if (footerModelPickerOpen && gitFooterPayloadVisible(payload, "webui-model-picker")) elements.statusBar.append(renderFooterModelPicker());
  if (footerThinkingPickerOpen && gitFooterPayloadVisible(payload, "webui-thinking-picker")) elements.statusBar.append(renderFooterThinkingPicker());
  if (footerBranchPickerOpen && gitFooterPayloadVisible(payload, "webui-branch-picker")) elements.statusBar.append(renderFooterBranchPicker());
  gitFooterRenderCache = { pickerKey, mainKeys, metaKeys, mainNodes, metaNodes };
  setMobileFooterExpanded(mobileFooterExpanded);
  updateFooterModelPickerPosition();
}

function cleanGitDiffPath(value = "") {
  let text = String(value || "").trim();
  if (!text || text === "/dev/null") return "";
  if ((text.startsWith("a/") || text.startsWith("b/")) && text.length > 2) text = text.slice(2);
  return text;
}

function gitDiffPathFromHeader(line) {
  const match = String(line || "").match(/^diff --git\s+(.+?)\s+(.+)$/);
  return cleanGitDiffPath(match?.[2] || match?.[1] || "");
}

function parseGitUnifiedDiff(diffText = "") {
  const normalized = String(diffText || "").replace(/\r\n?/g, "\n");
  const lines = normalized.split("\n");
  const files = [];
  let file = null;
  let hunk = null;
  let oldLineNumber = 0;
  let newLineNumber = 0;
  let deleteBuffer = [];
  let addBuffer = [];

  const flushChangeRows = () => {
    if (!hunk || (!deleteBuffer.length && !addBuffer.length)) return;
    if (file) {
      file.deletions += deleteBuffer.length;
      file.additions += addBuffer.length;
    }
    const rowCount = Math.max(deleteBuffer.length, addBuffer.length);
    for (let i = 0; i < rowCount; i++) {
      const left = deleteBuffer[i] || null;
      const right = addBuffer[i] || null;
      hunk.rows.push({
        type: left && right ? "changed" : left ? "removed" : "added",
        oldNumber: left?.number ?? "",
        newNumber: right?.number ?? "",
        left: left?.text ?? "",
        right: right?.text ?? "",
      });
    }
    deleteBuffer = [];
    addBuffer = [];
  };

  const finishFile = () => {
    flushChangeRows();
    if (!file) return;
    file.path = file.newPath || file.oldPath || file.headerPath || "diff";
    files.push(file);
    file = null;
    hunk = null;
  };

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] || "";
    if (index === lines.length - 1 && !line && normalized.endsWith("\n")) continue;

    if (line.startsWith("diff --git ")) {
      finishFile();
      file = { path: "", oldPath: "", newPath: "", headerPath: gitDiffPathFromHeader(line), headers: [line], hunks: [], additions: 0, deletions: 0 };
      continue;
    }

    if (!file) {
      if (!line.trim()) continue;
      file = { path: "diff", oldPath: "", newPath: "", headerPath: "diff", headers: [], hunks: [], additions: 0, deletions: 0 };
    }

    if (line.startsWith("@@ ")) {
      flushChangeRows();
      const match = line.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
      oldLineNumber = Number.parseInt(match?.[1] || "0", 10) || 0;
      newLineNumber = Number.parseInt(match?.[2] || "0", 10) || 0;
      hunk = { header: line, rows: [] };
      file.hunks.push(hunk);
      continue;
    }

    if (!hunk) {
      file.headers.push(line);
      if (line.startsWith("--- ")) file.oldPath = cleanGitDiffPath(line.slice(4));
      if (line.startsWith("+++ ")) file.newPath = cleanGitDiffPath(line.slice(4));
      continue;
    }

    if (line.startsWith("-")) {
      deleteBuffer.push({ number: oldLineNumber, text: line.slice(1) });
      oldLineNumber += 1;
      continue;
    }
    if (line.startsWith("+")) {
      addBuffer.push({ number: newLineNumber, text: line.slice(1) });
      newLineNumber += 1;
      continue;
    }

    flushChangeRows();
    if (line.startsWith(" ")) {
      const text = line.slice(1);
      hunk.rows.push({ type: "context", oldNumber: oldLineNumber, newNumber: newLineNumber, left: text, right: text });
      oldLineNumber += 1;
      newLineNumber += 1;
    } else if (line.startsWith("\\")) {
      hunk.rows.push({ type: "meta", oldNumber: "", newNumber: "", left: line, right: line });
    } else {
      hunk.rows.push({ type: "meta", oldNumber: "", newNumber: "", left: line, right: line });
    }
  }

  finishFile();
  return files;
}

function gitChangesChip(label, value, className = "") {
  const chip = make("div", `git-changes-chip ${className}`.trim());
  chip.append(make("span", "git-changes-chip-label", label), make("span", "git-changes-chip-value", String(value ?? "—")));
  return chip;
}

function renderGitChangesOverview(data) {
  const summary = data?.summary || {};
  const untrackedCount = Array.isArray(data?.untracked) ? data.untracked.length : Number(summary.untracked || 0);
  const ahead = Number(summary.ahead || 0) || 0;
  const behind = Number(summary.behind || 0) || 0;
  const overview = make("div", "git-changes-overview");
  overview.append(
    gitChangesChip("repo", data?.root || "—", "wide"),
    gitChangesChip("branch", data?.branch || "detached"),
    gitChangesChip("ahead", ahead > 0 ? `↑${ahead}` : 0, ahead > 0 ? "warning" : "muted"),
    gitChangesChip("remote", behind > 0 ? `↓${behind}` : 0, behind > 0 ? "danger" : "muted"),
    gitChangesChip("staged", summary.staged || 0, "success"),
    gitChangesChip("modified", summary.unstaged || 0, "warning"),
    gitChangesChip("untracked", untrackedCount, "muted"),
    gitChangesChip("conflicts", summary.conflicted || 0, (summary.conflicted || 0) > 0 ? "danger" : "muted"),
  );
  return overview;
}

function gitDiffDisplayLine(row, side) {
  const type = row.type || "context";
  if (side === "old") {
    const text = row.left ?? "";
    return row.oldNumber !== "" && (type === "removed" || type === "changed") ? `-${text}` : text;
  }
  const text = row.right ?? "";
  return row.newNumber !== "" && (type === "added" || type === "changed") ? `+${text}` : text;
}

function renderGitDiffRow(row) {
  const node = make("div", `git-diff-row ${row.type || "context"}`.trim());
  node.append(
    make("span", "git-diff-line-number old", row.oldNumber === "" ? "" : String(row.oldNumber)),
    make("code", "git-diff-line old", gitDiffDisplayLine(row, "old")),
    make("span", "git-diff-line-number new", row.newNumber === "" ? "" : String(row.newNumber)),
    make("code", "git-diff-line new", gitDiffDisplayLine(row, "new")),
  );
  return node;
}

function renderGitDiffGrid(file) {
  const grid = make("div", "git-diff-grid");
  const rowLimit = file.renderRowLimit ?? GIT_CHANGES_RENDER_ROW_LIMIT;
  let renderedRows = 0;
  let truncated = false;
  for (const hunk of file.hunks || []) {
    if (renderedRows >= rowLimit) {
      truncated = true;
      break;
    }
    grid.append(renderGitDiffRow({ type: "hunk", oldNumber: "", newNumber: "", left: hunk.header, right: hunk.header }));
    renderedRows += 1;
    for (const row of hunk.rows || []) {
      if (renderedRows >= rowLimit) {
        truncated = true;
        break;
      }
      grid.append(renderGitDiffRow(row));
      renderedRows += 1;
    }
    if (truncated) break;
  }
  if (truncated) {
    grid.append(renderGitDiffRow({ type: "meta", oldNumber: "", newNumber: "", left: `Diff preview truncated after ${rowLimit} rows.`, right: "Use git diff in the terminal for the full output." }));
  }
  return grid;
}

function gitFileActionButtons(actions) {
  if (!actions?.length) return null;
  const wrap = make("span", "git-file-actions");
  for (const action of actions) {
    const button = make("button", `git-file-action ${action.className || ""}`.trim(), action.label);
    button.type = "button";
    button.title = action.title || action.label;
    if (action.path) button.dataset.gitFileActionPath = action.path;
    if (action.path && gitChangesState.busyPath === action.path) {
      button.disabled = true;
      button.setAttribute("aria-busy", "true");
    }
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (button.disabled) return;
      action.onClick();
    });
    wrap.append(button);
  }
  return wrap;
}

function copyGitTextToClipboard(text, label = "text") {
  navigator.clipboard?.writeText(text)
    .then(() => addEvent(`Copied ${label}: ${text}`, "info"))
    .catch(() => addEvent(`Clipboard unavailable; copy the ${label} manually.`, "error"));
}

function copyGitPathToClipboard(path) {
  copyGitTextToClipboard(path, "path");
}

// Git paths are repo-root-relative; the file viewer resolves against a tab's
// cwd. Prefer the active tab when it contains the file, otherwise use another
// tab that exposes the repository path.
function gitFileViewerTarget(repoRelPath, root, candidates = []) {
  const path = normalizeFileTreePath(repoRelPath);
  const normalizedRoot = String(root || "").trim().replace(/\\/g, "/");
  const repoRoot = normalizedRoot === "/" ? "/" : normalizedRoot.replace(/\/+$/, "");
  if (!path || !repoRoot) return null;
  const absolute = `${repoRoot === "/" ? "/" : `${repoRoot}/`}${path}`;
  const current = activeTab();
  const ordered = [current ? { tabId: current.id, cwd: current.cwd } : null, ...candidates].filter(Boolean);
  const seen = new Set();
  for (const candidate of ordered) {
    const tabId = String(candidate?.tabId || candidate?.id || "");
    const normalizedCwd = String(candidate?.cwd || "").trim().replace(/\\/g, "/");
    const cwd = normalizedCwd === "/" ? "/" : normalizedCwd.replace(/\/+$/, "");
    if (!tabId || !cwd || seen.has(tabId)) continue;
    seen.add(tabId);
    const prefix = cwd === "/" ? "/" : `${cwd}/`;
    const caseInsensitive = /^[a-z]:\//i.test(absolute) && /^[a-z]:\//i.test(prefix);
    const comparableAbsolute = caseInsensitive ? absolute.toLowerCase() : absolute;
    const comparablePrefix = caseInsensitive ? prefix.toLowerCase() : prefix;
    if (!comparableAbsolute.startsWith(comparablePrefix)) continue;
    const viewerPath = absolute.slice(prefix.length);
    if (viewerPath) return { tabId, path: viewerPath };
  }
  return null;
}

async function openGitFileInViewer(repoRelPath, { root = "", candidates = [], closeChanges = false, category = "" } = {}) {
  const target = gitFileViewerTarget(repoRelPath, root, candidates);
  if (!target) {
    addEvent(`Cannot open ${repoRelPath}: it is outside the available tab working directories.`, "error");
    return;
  }
  if (closeChanges) closeGitChangesDialog();
  if (target.tabId !== activeTabId) await switchTab(target.tabId);
  if (target.tabId !== activeTabId) {
    addEvent(`Cannot open ${repoRelPath}: its terminal tab is no longer available.`, "error");
    return;
  }
  setSidePanelCollapsed(false);
  await openFileInViewer(target.path, { gitCategory: category, gitPath: normalizeFileTreePath(repoRelPath) });
}

async function openGitFileFromChanges(repoRelPath) {
  const tabId = gitChangesState.tabId || activeTabId;
  const tab = tabs.find((item) => item.id === tabId);
  await openGitFileInViewer(repoRelPath, {
    root: gitChangesState.data?.root || "",
    candidates: tab ? [{ tabId: tab.id, cwd: tab.cwd }] : [],
    closeChanges: true,
  });
}

function gitChangesCommonFileActions(path) {
  return [
    { label: "Open", title: "Open this file in the WebUI file viewer", onClick: () => openGitFileFromChanges(path) },
    { label: "Copy path", title: "Copy the repo-relative path", onClick: () => copyGitPathToClipboard(path) },
  ];
}

function gitChangesFileActionsFor(sectionKey, path) {
  if (!path || gitChangesState.loading || gitChangesState.pulling || gitChangesState.fetching) return [];
  if (sectionKey === "unstaged") {
    return [
      { label: "Stage", path, title: `git add -- ${path}`, onClick: () => runGitFileAction("stage", path) },
      ...gitChangesCommonFileActions(path),
      { label: "Discard", path, className: "danger", title: `git restore -- ${path} (destructive)`, onClick: () => runGitFileAction("discard", path) },
    ];
  }
  if (sectionKey === "staged") {
    return [
      { label: "Unstage", path, title: `git restore --staged -- ${path}`, onClick: () => runGitFileAction("unstage", path) },
      ...gitChangesCommonFileActions(path),
    ];
  }
  if (sectionKey === "incoming" || sectionKey === "commit") return [{ label: "Copy path", title: "Copy the repo-relative path", onClick: () => copyGitPathToClipboard(path) }];
  return [];
}

// Per-file fold state for the Git Changes dialog survives the full re-render that follows every
// stage/unstage/discard, so files the user collapsed stay collapsed.
const gitChangesCollapsedFiles = new Set();

function renderGitDiffFile(file, actions = []) {
  const details = make("details", `git-diff-file ${file.className || ""}`.trim());
  const fileKey = file.path || "diff";
  details.open = !gitChangesCollapsedFiles.has(fileKey);
  details.addEventListener("toggle", () => {
    if (details.open) gitChangesCollapsedFiles.delete(fileKey);
    else gitChangesCollapsedFiles.add(fileKey);
  });
  details.dataset.gitDiffFile = file.path || "diff";
  const summary = make("summary", "git-diff-file-summary");
  summary.append(
    make("span", "git-diff-file-name", file.path || "diff"),
    make("span", "git-diff-file-stats", file.statsText || `+${file.additions || 0} −${file.deletions || 0}`),
  );
  const actionButtons = gitFileActionButtons(actions);
  if (actionButtons) summary.append(actionButtons);
  details.append(summary);
  if (file.hunks?.length) {
    details.append(renderGitDiffGrid(file));
  } else {
    details.append(make("pre", "git-diff-raw", (file.headers || []).join("\n") || "No textual diff for this file."));
  }
  return details;
}

function renderGitDiffSection(section, files) {
  const key = String(section?.key || "diff").replace(/[^a-z0-9_-]/gi, "-");
  const wrapper = make("section", `git-diff-section git-diff-section-${key}`);
  const header = make("div", "git-diff-section-heading");
  header.append(
    make("div", "git-diff-section-title", section?.label || "Git diff"),
    make("div", "git-diff-section-meta", `${files.length} file${files.length === 1 ? "" : "s"} · ${section?.command || "git diff"}`),
  );
  wrapper.append(header);
  if (section?.truncated) {
    const notice = make("div", "git-diff-truncated-notice");
    const fullCommand = String(section?.command || "git diff").replace(/\s--unified=0\b/, "");
    notice.append(make("span", undefined, `Diff truncated at ${formatBytes(section.capBytes || 0)} — showing the tail. Use the per-file Open buttons for full contents, or run the full command in a terminal:`));
    notice.append(make("code", "git-tools-command", fullCommand));
    const copy = make("button", "git-file-action", "Copy command");
    copy.type = "button";
    copy.title = "Copy the full diff command";
    copy.addEventListener("click", () => copyGitTextToClipboard(fullCommand, "command"));
    notice.append(copy);
    wrapper.append(notice);
  }
  wrapper.append(...files.map((file) => renderGitDiffFile(file, gitChangesFileActionsFor(section?.key, file.path))));
  return wrapper;
}

function normalizeGitUntrackedEntry(value) {
  if (typeof value === "string") return { path: value, size: 0, binary: false, content: "", contentMissing: true };
  if (!value || typeof value !== "object") return null;
  const path = String(value.path || "").trim();
  if (!path) return null;
  const hasContent = Object.prototype.hasOwnProperty.call(value, "content");
  const binary = value.binary === true;
  const error = value.error ? String(value.error) : "";
  return {
    path,
    size: Number(value.size || 0) || 0,
    binary,
    content: hasContent && typeof value.content === "string" ? value.content : "",
    contentMissing: !hasContent && !binary && !error,
    error,
  };
}

function gitUntrackedEntries(untracked) {
  return Array.isArray(untracked) ? untracked.map(normalizeGitUntrackedEntry).filter(Boolean) : [];
}

function gitUntrackedContentLines(content = "") {
  const normalized = String(content || "").replace(/\r\n?/g, "\n");
  if (!normalized) return [];
  const withoutFinalNewline = normalized.endsWith("\n") ? normalized.slice(0, -1) : normalized;
  return withoutFinalNewline ? withoutFinalNewline.split("\n") : [""];
}

function gitUntrackedEntryToDiffFile(entry) {
  const lines = gitUntrackedContentLines(entry.content);
  return {
    path: entry.path,
    className: "git-untracked-full-file",
    additions: lines.length,
    deletions: 0,
    statsText: `${entry.binary ? "binary" : `+${lines.length}`} · ${formatBytes(entry.size)}`,
    renderRowLimit: Number.POSITIVE_INFINITY,
    headers: lines.length ? [] : ["Empty untracked file."],
    hunks: lines.length ? [{
      header: `@@ -0,0 +1,${lines.length} @@`,
      rows: lines.map((line, index) => ({ type: "added", oldNumber: "", newNumber: index + 1, left: "", right: line })),
    }] : [],
  };
}

function renderGitUntrackedRawFile(entry) {
  const details = make("details", "git-diff-file git-untracked-full-file");
  details.open = true;
  details.dataset.gitDiffFile = entry.path;
  const summary = make("summary", "git-diff-file-summary");
  summary.append(
    make("span", "git-diff-file-name", entry.path),
    make("span", "git-diff-file-stats", entry.error ? "unreadable" : `binary · ${formatBytes(entry.size)}`),
  );
  details.append(summary, make("pre", "git-diff-raw", entry.error || "Binary untracked file; text preview unavailable."));
  return details;
}

function renderGitUntrackedLoadingFile(entry) {
  const details = make("details", "git-diff-file git-untracked-full-file git-untracked-loading-file");
  details.open = true;
  details.dataset.gitDiffFile = entry.path;
  const summary = make("summary", "git-diff-file-summary");
  summary.append(make("span", "git-diff-file-name", entry.path), make("span", "git-diff-file-stats", "loading content"));
  details.append(summary, make("pre", "git-diff-raw", "Loading complete untracked file content…"));
  return details;
}

function renderGitUntrackedFile(entry) {
  const node = entry.contentMissing
    ? renderGitUntrackedLoadingFile(entry)
    : entry.error || entry.binary
      ? renderGitUntrackedRawFile(entry)
      : renderGitDiffFile(gitUntrackedEntryToDiffFile(entry));
  if (!gitChangesState.loading && !gitChangesState.pulling && !gitChangesState.fetching) {
    const summary = node.querySelector("summary");
    const actions = gitFileActionButtons([
      { label: "Stage", path: entry.path, title: `git add -- ${entry.path}`, onClick: () => runGitFileAction("stage", entry.path) },
      ...gitChangesCommonFileActions(entry.path),
      { label: "Delete", path: entry.path, className: "danger", title: "Delete this untracked file from disk (destructive)", onClick: () => runGitFileAction("delete-untracked", entry.path) },
    ]);
    if (summary && actions) summary.append(actions);
  }
  return node;
}

function replaceGitUntrackedEntry(entry, tabId = gitChangesState.tabId) {
  const data = gitChangesState.data;
  if (!data || tabId !== gitChangesState.tabId) return;
  const entries = gitUntrackedEntries(data.untracked);
  const nextEntries = entries.map((item) => item.path === entry.path ? normalizeGitUntrackedEntry(entry) : item);
  gitChangesState = { ...gitChangesState, data: { ...data, untracked: nextEntries } };
  renderGitChangesDialog();
}

async function loadMissingGitUntrackedContent(entry, tabId = gitChangesState.tabId) {
  const key = `${tabId || ""}\u0000${entry.path}`;
  if (!entry.contentMissing || gitChangesUntrackedContentRequests.has(key)) return;
  gitChangesUntrackedContentRequests.add(key);
  try {
    const response = await api(`/api/git-changes/untracked-file?path=${encodeURIComponent(entry.path)}`, { tabId });
    if (!response.ok) throw new Error(response.error || "Failed to load untracked file content");
    replaceGitUntrackedEntry(response.data, tabId);
  } catch (error) {
    replaceGitUntrackedEntry({ ...entry, contentMissing: false, error: error.message || String(error) }, tabId);
  } finally {
    gitChangesUntrackedContentRequests.delete(key);
  }
}

function renderGitUntrackedSection(untracked) {
  const entries = gitUntrackedEntries(untracked);
  const wrapper = make("section", "git-diff-section git-diff-section-untracked");
  const header = make("div", "git-diff-section-heading");
  header.append(
    make("div", "git-diff-section-title", "Untracked"),
    make("div", "git-diff-section-meta", `${entries.length} file${entries.length === 1 ? "" : "s"} · complete file contents`),
  );
  wrapper.append(header, ...entries.map(renderGitUntrackedFile));
  for (const entry of entries) {
    if (entry.contentMissing) queueMicrotask(() => loadMissingGitUntrackedContent(entry));
  }
  return wrapper;
}

function renderGitChangesFileList(parsedSections, untracked) {
  const items = [];
  for (const entry of parsedSections || []) {
    for (const file of entry.files || []) {
      items.push({ path: file.path || "diff", stats: file.statsText || `+${file.additions || 0} −${file.deletions || 0}`, section: entry.section?.label || "Diff" });
    }
  }
  for (const entry of untracked || []) {
    items.push({ path: entry.path, stats: entry.binary ? "binary" : "new", section: "Untracked" });
  }
  if (!items.length) return null;
  const list = make("nav", "git-changes-file-list");
  list.setAttribute("aria-label", "Changed files");
  list.append(make("span", "git-changes-file-list-label", `${items.length} file${items.length === 1 ? "" : "s"}`));
  for (const item of items) {
    const button = make("button", "git-changes-file-jump");
    button.type = "button";
    button.dataset.gitChangesJumpFile = item.path;
    button.title = `${item.section}: ${item.path}`;
    button.append(make("span", "git-changes-file-jump-name", item.path), make("span", "git-changes-file-jump-meta", `${item.section} · ${item.stats}`));
    list.append(button);
  }
  return list;
}

function renderGitCurrentFileHeader() {
  const header = make("button", "git-current-file-header");
  header.type = "button";
  header.title = "Collapse or expand the current file diff";
  header.append(make("span", "git-current-file-label", "Current file"), make("span", "git-current-file-name", "—"), make("span", "git-current-file-toggle", "Toggle"));
  return header;
}

function updateGitChangesCurrentFileHeader() {
  const body = elements.gitChangesBody;
  const header = body?.querySelector(".git-current-file-header");
  const name = header?.querySelector(".git-current-file-name");
  if (!body || !header || !name) return;
  const files = Array.from(body.querySelectorAll(".git-diff-file[data-git-diff-file]"));
  if (!files.length) {
    name.textContent = "—";
    return;
  }
  const bodyRect = body.getBoundingClientRect();
  const headerRect = header.getBoundingClientRect();
  const markerY = Math.min(bodyRect.bottom - 1, Math.max(bodyRect.top, headerRect.bottom + 8));
  let current = files[0];
  for (const file of files) {
    const rect = file.getBoundingClientRect();
    if (rect.top <= markerY && rect.bottom > markerY) {
      current = file;
      break;
    }
    if (rect.top <= markerY) current = file;
    else break;
  }
  const currentPath = current?.dataset.gitDiffFile || "—";
  name.textContent = currentPath;
  header.dataset.gitCurrentFile = currentPath;
  header.setAttribute("aria-expanded", String(current?.open !== false));
}

function gitChangesGeneratedLabel(data) {
  const timestamp = Date.parse(data?.generatedAt || "");
  if (!Number.isFinite(timestamp)) return "";
  return `Updated ${new Date(timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}`;
}

function gitPullOutputLines(result = {}) {
  return [result.stdout, result.stderr]
    .map((value) => stripAnsi(value || "").trim())
    .filter(Boolean)
    .join("\n")
    .split(/\r?\n/)
    .map((line) => line.trimEnd())
    .filter((line) => line.trim());
}

function parseGitPullSummaryLine(line) {
  const text = String(line || "").trim();
  if (!/\bfiles? changed\b|\binsertions?\(\+\)|\bdeletions?\(-\)/.test(text)) return null;
  const numberFrom = (regex) => {
    const match = text.match(regex);
    return match ? Number.parseInt(String(match[1] || "0").replace(/,/g, ""), 10) || 0 : 0;
  };
  return {
    summaryLine: text,
    totalFiles: numberFrom(/([\d,]+)\s+files? changed/),
    insertions: numberFrom(/([\d,]+)\s+insertions?\(\+\)/),
    deletions: numberFrom(/([\d,]+)\s+deletions?\(-\)/),
  };
}

function parseGitPullFileStatLine(line) {
  const match = String(line || "").match(/^(.+?)\s+\|\s+(.+)$/);
  if (!match) return null;
  const path = match[1].trim();
  const stats = match[2].trim();
  if (!path || !stats) return null;
  const tone = stats.includes("-") && !stats.includes("+") ? "danger" : stats.includes("+") ? "success" : "muted";
  return { path, stats, tone };
}

function normalizeGitPullResult(result = {}) {
  const outputLines = gitPullOutputLines(result);
  const changedFiles = [];
  const modeLines = [];
  let updateRange = "";
  let strategy = "";
  let summary = null;
  let alreadyUpToDate = false;

  for (const line of outputLines) {
    const text = line.trim();
    const rangeMatch = text.match(/^Updating\s+([0-9a-f]+)\.\.([0-9a-f]+)/i);
    if (!updateRange && rangeMatch) updateRange = `${rangeMatch[1]}…${rangeMatch[2]}`;
    if (!strategy && (/^Fast-forward$/i.test(text) || /^Merge made by\b/i.test(text))) strategy = text;
    if (/^Already up to date\.?$/i.test(text)) {
      alreadyUpToDate = true;
      strategy = text.replace(/\.?$/, ".");
    }
    const summaryLine = parseGitPullSummaryLine(text);
    if (summaryLine) summary = summaryLine;
    const stat = parseGitPullFileStatLine(text);
    if (stat) changedFiles.push(stat);
    if (/^(create|delete) mode\s+|^(rename|copy) (from|to)\s+/i.test(text)) modeLines.push(text);
  }

  return {
    command: result.command || "git pull --ff-only",
    outputLines,
    changedFiles,
    modeLines,
    updateRange,
    strategy,
    alreadyUpToDate,
    summaryLine: summary?.summaryLine || "",
    totalFiles: summary?.totalFiles || changedFiles.length || 0,
    insertions: summary?.insertions || 0,
    deletions: summary?.deletions || 0,
  };
}

function gitPullResultStatus(result) {
  if (!result) return "";
  if (result.alreadyUpToDate) return "Already up to date.";
  const totalFiles = Number(result.totalFiles || 0) || 0;
  const insertions = Number(result.insertions || 0) || 0;
  const deletions = Number(result.deletions || 0) || 0;
  if (totalFiles > 0) {
    const parts = [`${totalFiles.toLocaleString()} file${totalFiles === 1 ? "" : "s"} changed`];
    if (insertions > 0) parts.push(`+${insertions.toLocaleString()}`);
    if (deletions > 0) parts.push(`−${deletions.toLocaleString()}`);
    return `Pulled remote changes: ${parts.join(" · ")}.`;
  }
  if (result.summaryLine) return `Pulled remote changes: ${result.summaryLine}.`;
  if (result.strategy) return `Pulled remote changes (${result.strategy}).`;
  return "Pulled remote changes successfully.";
}

function renderGitPullResultPanel(result) {
  if (!result) return null;
  const panel = make("section", "git-pull-result-panel");
  const header = make("div", "git-pull-result-header");
  const copy = make("div", "git-pull-result-copy");
  copy.append(
    make("span", "git-pull-result-kicker", "Pull result"),
    make("strong", undefined, gitPullResultStatus(result)),
    make("span", "git-pull-result-meta", [result.updateRange, result.strategy, result.command].filter(Boolean).join(" · ")),
  );
  header.append(copy);
  panel.append(header);

  const metrics = make("div", "git-pull-result-metrics");
  metrics.append(
    gitChangesChip("changed", result.totalFiles || result.changedFiles.length || 0, (result.totalFiles || result.changedFiles.length) ? "warning" : "muted"),
    gitChangesChip("insertions", result.insertions > 0 ? `+${result.insertions.toLocaleString()}` : 0, result.insertions > 0 ? "success" : "muted"),
    gitChangesChip("deletions", result.deletions > 0 ? `−${result.deletions.toLocaleString()}` : 0, result.deletions > 0 ? "danger" : "muted"),
    gitChangesChip("mode ops", result.modeLines.length || 0, result.modeLines.length ? "warning" : "muted"),
  );
  panel.append(metrics);

  if (result.changedFiles.length) {
    const list = make("div", "git-pull-file-list");
    list.append(make("span", "git-pull-file-list-label", `${result.changedFiles.length} pulled file${result.changedFiles.length === 1 ? "" : "s"}`));
    for (const file of result.changedFiles.slice(0, GIT_PULL_RESULT_FILE_LIMIT)) {
      const row = make("div", `git-pull-file ${file.tone || ""}`.trim());
      row.append(make("span", "git-pull-file-path", file.path), make("span", "git-pull-file-stats", file.stats));
      list.append(row);
    }
    const remaining = result.changedFiles.length - GIT_PULL_RESULT_FILE_LIMIT;
    if (remaining > 0) list.append(make("div", "git-pull-result-more", `${remaining} more file${remaining === 1 ? "" : "s"}; expand command output for the full git stat.`));
    panel.append(list);
  }

  if (result.modeLines.length) {
    const details = make("details", "git-pull-output-details git-pull-mode-details");
    details.append(make("summary", undefined, `Mode changes (${result.modeLines.length})`), make("pre", undefined, result.modeLines.join("\n")));
    panel.append(details);
  }

  const details = make("details", "git-pull-output-details");
  details.append(make("summary", undefined, "Command output"), make("pre", undefined, result.outputLines.join("\n") || "No command output."));
  panel.append(details);
  return panel;
}

function renderGitChangesDialog() {
  if (!elements.gitChangesDialog || !elements.gitChangesBody) return;
  const { loading, pulling, fetching, error, message, pullResult, data, operation, mode, commit } = gitChangesState;
  const commitView = mode === "commit";
  const busyAction = pulling || fetching;
  const behind = Number(data?.remote?.behind ?? data?.summary?.behind ?? 0) || 0;
  const diverged = data?.remote?.diverged === true;
  const canPull = behind > 0 && data?.remote?.canPull !== false && !diverged;
  const hasOperation = !commitView && Boolean(operation?.operation);
  const remoteNotice = !commitView && !error && data?.remote?.error ? `Incoming diff unavailable: ${data.remote.error}` : "";
  if (elements.gitChangesTitle) elements.gitChangesTitle.textContent = commitView ? "Git Commit" : "Git Changes";
  if (elements.gitChangesSubtitle) {
    const commitData = data?.commit || commit;
    const base = commitView
      ? [commitData?.shortHash || String(commitData?.hash || "").slice(0, 12), commitData?.subject, data?.root].filter(Boolean).join(" · ") || "Commit diff"
      : data?.root ? `${data.branch || "detached"} · ${data.root}` : "Current tab git diff";
    elements.gitChangesSubtitle.textContent = !commitView && data?.remote?.upstream ? `${base} · upstream ${data.remote.upstream}` : base;
  }
  if (elements.gitChangesRefreshButton) {
    elements.gitChangesRefreshButton.disabled = loading || busyAction;
    elements.gitChangesRefreshButton.textContent = loading ? "Refreshing…" : commitView ? "Reload" : "Refresh";
  }
  if (elements.gitChangesFetchButton) {
    elements.gitChangesFetchButton.hidden = commitView;
    elements.gitChangesFetchButton.disabled = loading || busyAction || !data?.root;
    elements.gitChangesFetchButton.textContent = fetching ? "Fetching…" : "Fetch";
    elements.gitChangesFetchButton.title = "Run git fetch --prune to refresh remote tracking state";
  }
  if (elements.gitChangesPullButton) {
    elements.gitChangesPullButton.hidden = commitView;
    elements.gitChangesPullButton.disabled = loading || busyAction || !canPull;
    elements.gitChangesPullButton.textContent = pulling ? "Pulling…" : behind > 0 ? `Pull ↓${behind}` : "Pull";
    elements.gitChangesPullButton.title = canPull
      ? "Run git pull --ff-only for the current repository"
      : diverged
        ? "Local and remote branches have diverged; use the integrate actions below instead of one-click pull."
        : "No remote commits to pull";
  }
  if (elements.gitChangesStatus) {
    const statusText = error || (pulling ? "Pulling changes…" : fetching ? "Fetching from remote…" : loading ? `Loading ${commitView ? "commit" : "git"} diff…` : message || remoteNotice || (data ? gitChangesGeneratedLabel(data) : ""));
    elements.gitChangesStatus.className = `git-changes-status ${error || remoteNotice ? "error" : message ? "success" : "muted"}`;
    elements.gitChangesStatus.textContent = statusText;
    elements.gitChangesStatus.hidden = !elements.gitChangesStatus.textContent;
  }

  const body = elements.gitChangesBody;
  body.replaceChildren();
  if (loading && !data) {
    body.append(make("div", "git-changes-empty", "Loading git diff…"));
    return;
  }
  if (error && !data) {
    body.append(make("div", "git-changes-empty error", error));
    return;
  }
  if (!data) {
    body.append(make("div", "git-changes-empty", "No diff loaded yet. Open this from the CHANGES chip in the footer, or expand a repository in the Git panel."));
    return;
  }

  if (pullResult && !commitView) body.append(renderGitPullResultPanel(pullResult));
  if (hasOperation) {
    const panel = renderGitOperationPanel(operation);
    if (panel) body.append(panel);
  }
  if (!commitView) {
    body.append(renderGitChangesOverview(data));
    const fetchStateLines = gitChangesFetchStateLines();
    if (fetchStateLines.length) {
      const fetchNote = make("div", "git-tools-note git-fetch-state-note");
      for (const line of fetchStateLines) fetchNote.append(make("div", undefined, line));
      body.append(fetchNote);
    }
    if (diverged && !hasOperation) body.append(renderGitDivergedBar(data));
  }
  const parsedSections = (Array.isArray(data.sections) ? data.sections : [])
    .map((section) => ({ section, files: parseGitUnifiedDiff(section.diff || "") }))
    .filter((entry) => entry.files.length > 0);
  const untracked = gitUntrackedEntries(data.untracked);
  const hasVisibleFiles = parsedSections.length > 0 || untracked.length > 0;
  if (hasVisibleFiles) {
    const fileList = renderGitChangesFileList(parsedSections, untracked);
    if (fileList) body.append(fileList);
    body.append(renderGitCurrentFileHeader());
  }
  for (const entry of parsedSections) body.append(renderGitDiffSection(entry.section, entry.files));
  if (untracked.length) body.append(renderGitUntrackedSection(untracked));
  if (!hasVisibleFiles && !hasOperation) {
    const emptyMessage = behind > 0 ? "No textual incoming diff was available for the remote commits." : "Working tree is clean. No staged, unstaged, untracked, or incoming diff.";
    body.append(make("div", "git-changes-empty success", emptyMessage));
  }
  if (!commitView) body.append(renderGitToolsSection());
  if (hasVisibleFiles) requestAnimationFrame(updateGitChangesCurrentFileHeader);
}

async function loadGitChangesDialog(tabContext = activeTabContext()) {
  const requestSerial = ++gitChangesRequestSerial;
  gitChangesUntrackedContentRequests.clear();
  if (gitChangesState.tabId !== (tabContext.tabId || activeTabId)) gitChangesCollapsedFiles.clear();
  gitChangesState = { ...gitChangesState, loading: true, busyPath: "", error: "", errorCode: "", errorHint: "", message: "", pullResult: null, tabId: tabContext.tabId || activeTabId, mode: "changes", commit: null };
  renderGitChangesDialog();
  try {
    const [response, operationResponse] = await Promise.all([
      api("/api/git-changes", { tabId: tabContext.tabId }),
      api("/api/git-operation", { tabId: tabContext.tabId }).catch(() => null),
    ]);
    if (requestSerial !== gitChangesRequestSerial) return;
    if (!response.ok) throw new Error(response.error || "Failed to load git changes");
    gitChangesState = {
      ...gitChangesState,
      loading: false,
      pulling: false,
      fetching: false,
      error: "",
      errorCode: "",
      errorHint: "",
      message: "",
      pullResult: null,
      data: response.data || null,
      operation: operationResponse?.ok ? operationResponse.data : null,
      tabId: tabContext.tabId || activeTabId,
    };
  } catch (error) {
    if (requestSerial !== gitChangesRequestSerial) return;
    gitChangesState = { ...gitChangesState, loading: false, error: error.message || String(error) };
  }
  renderGitChangesDialog();
}

function openGitChangesDialog(requestedTabId = activeTabId) {
  if (!elements.gitChangesDialog) return;
  hideFooterTooltip();
  const tabId = typeof requestedTabId === "string" && requestedTabId ? requestedTabId : activeTabId;
  const tabContext = activeTabContext(tabId);
  if (gitToolsState.tabId !== tabId) resetGitToolsState(tabId);
  gitChangesState = {
    ...gitChangesState,
    loading: true,
    pulling: false,
    fetching: false,
    error: "",
    errorCode: "",
    errorHint: "",
    message: "",
    pullResult: null,
    data: gitChangesState.tabId === tabId ? gitChangesState.data : null,
    operation: gitChangesState.tabId === tabId ? gitChangesState.operation : null,
    lastFetch: gitChangesState.tabId === tabId ? gitChangesState.lastFetch : null,
    tabId,
    mode: "changes",
    commit: null,
  };
  renderGitChangesDialog();
  if (!elements.gitChangesDialog.open) elements.gitChangesDialog.showModal();
  loadGitChangesDialog(tabContext).catch((error) => addEvent(error.message || String(error), "error"));
}

async function loadGitCommitDialog(tabId, commit) {
  const requestSerial = ++gitChangesRequestSerial;
  const hash = String(commit?.hash || "");
  gitChangesState = { ...gitChangesState, loading: true, error: "", message: "", data: null, operation: null, tabId, mode: "commit", commit };
  renderGitChangesDialog();
  try {
    const response = await api(`/api/git-commit?hash=${encodeURIComponent(hash)}`, { tabId });
    if (requestSerial !== gitChangesRequestSerial) return;
    if (!response.ok) throw new Error(response.error || "Failed to load Git commit");
    gitChangesState = { ...gitChangesState, loading: false, error: "", data: response.data || null, tabId, mode: "commit", commit: response.data?.commit || commit };
  } catch (error) {
    if (requestSerial !== gitChangesRequestSerial) return;
    gitChangesState = { ...gitChangesState, loading: false, error: error.message || String(error), tabId, mode: "commit", commit };
  }
  renderGitChangesDialog();
}

function openGitCommitDialog(tabId, commit) {
  if (!elements.gitChangesDialog || !tabId || !commit?.hash) return;
  hideFooterTooltip();
  gitChangesState = { ...gitChangesState, loading: true, pulling: false, fetching: false, error: "", message: "", data: null, operation: null, tabId, mode: "commit", commit };
  renderGitChangesDialog();
  if (!elements.gitChangesDialog.open) elements.gitChangesDialog.showModal();
  loadGitCommitDialog(tabId, commit).catch((error) => addEvent(error.message || String(error), "error"));
}

function refreshGitChangesDialog() {
  const tabId = gitChangesState.tabId || activeTabId;
  if (gitChangesState.mode === "commit" && gitChangesState.commit?.hash) {
    loadGitCommitDialog(tabId, gitChangesState.commit).catch((error) => addEvent(error.message || String(error), "error"));
    return;
  }
  loadGitChangesDialog({ tabId }).catch((error) => addEvent(error.message || String(error), "error"));
}

async function pullGitChangesDialog() {
  const tabContext = { tabId: gitChangesState.tabId || activeTabId };
  const behind = Number(gitChangesState.data?.remote?.behind ?? gitChangesState.data?.summary?.behind ?? 0) || 0;
  if (behind <= 0 || gitChangesState.pulling || gitChangesState.loading || gitChangesState.fetching) return;
  if (gitChangesState.data?.remote?.diverged === true) return;
  const root = gitChangesState.data?.root || "the current repository";
  if (!(await appConfirmText(`Run git pull --ff-only in ${root}?`, { affected: root, confirmLabel: "Pull changes" }))) return;

  const requestSerial = ++gitChangesRequestSerial;
  gitChangesState = { ...gitChangesState, pulling: true, loading: false, error: "", errorCode: "", errorHint: "", message: "", pullResult: null, tabId: tabContext.tabId };
  renderGitChangesDialog();
  try {
    const response = await api("/api/git-changes/pull", { method: "POST", body: {}, tabId: tabContext.tabId });
    if (requestSerial !== gitChangesRequestSerial) return;
    if (!response.ok) {
      gitChangesState = { ...gitChangesState, errorCode: response.code || "" };
      const detail = [response.error, response.hint].filter(Boolean).join("\n").trim();
      throw new Error(detail || "Failed to pull git changes");
    }
    const pullResult = normalizeGitPullResult(response.data || {});
    gitChangesState = {
      ...gitChangesState,
      loading: false,
      pulling: false,
      error: "",
      errorCode: "",
      errorHint: "",
      message: gitPullResultStatus(pullResult),
      pullResult,
      data: response.data?.changes || gitChangesState.data,
      tabId: tabContext.tabId,
    };
    addEvent("Pulled remote git changes.", "success");
    requestGitFooterWebuiPayload(tabContext, { force: true });
  } catch (error) {
    if (requestSerial !== gitChangesRequestSerial) return;
    gitChangesState = { ...gitChangesState, pulling: false, error: error.message || String(error) };
    addEvent(error.message || String(error), "error");
  }
  renderGitChangesDialog();
}

function closeGitChangesDialog() {
  gitChangesRequestSerial += 1;
  gitChangesUntrackedContentRequests.clear();
  gitChangesState = { ...gitChangesState, loading: false, pulling: false, fetching: false };
  if (elements.gitChangesDialog?.open) elements.gitChangesDialog.close();
}

async function fetchGitChangesDialog() {
  const tabId = gitChangesState.tabId || activeTabId;
  if (gitChangesState.fetching || gitChangesState.loading || gitChangesState.pulling) return;
  const requestSerial = ++gitChangesRequestSerial;
  gitChangesState = { ...gitChangesState, fetching: true, error: "", errorCode: "", errorHint: "", message: "", pullResult: null };
  renderGitChangesDialog();
  try {
    const response = await api("/api/git-fetch", { method: "POST", body: {}, tabId });
    if (requestSerial !== gitChangesRequestSerial) return;
    if (!response.ok) {
      gitChangesState = { ...gitChangesState, errorCode: response.code || "" };
      throw new Error([response.error, response.hint].filter(Boolean).join("\n") || "git fetch failed");
    }
    const summaryLine = String(response.data?.summary || "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean).slice(-1)[0] || "";
    gitChangesState = {
      ...gitChangesState,
      fetching: false,
      data: response.data?.changes || gitChangesState.data,
      lastFetch: { at: Date.now(), summary: summaryLine, error: "" },
      message: summaryLine && !/^fetching/i.test(summaryLine) ? `Fetched (--prune). ${summaryLine}` : "Fetched remote state (git fetch --prune).",
    };
    addEvent("Fetched remote state (git fetch --prune).", "success");
    requestGitFooterWebuiPayload(activeTabContext(tabId), { force: true });
  } catch (error) {
    if (requestSerial !== gitChangesRequestSerial) return;
    gitChangesState = { ...gitChangesState, fetching: false, error: error.message || String(error), lastFetch: { at: Date.now(), summary: "", error: error.message || String(error) } };
  }
  renderGitChangesDialog();
}

// Fetch state lines shown inside the dialog: the extension's startup/tab fetch
// state (from the changes-chip tooltip payload) plus this dialog's last fetch.
function gitChangesFetchStateLines() {
  const lines = [];
  const chip = parseGitFooterWebuiPayload()?.meta?.find((item) => item.key === "changes");
  const extensionLine = String(chip?.title || "").split("\n").find((line) => /git fetch/i.test(line));
  if (extensionLine) lines.push(`Tab fetch state: ${extensionLine.trim()}`);
  const lastFetch = gitChangesState.lastFetch;
  if (lastFetch?.at) {
    const time = new Date(lastFetch.at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    lines.push(lastFetch.error ? `Last fetch from this dialog at ${time} failed: ${lastFetch.error}` : `Last fetch from this dialog at ${time}${lastFetch.summary ? ` — ${lastFetch.summary}` : " completed."}`);
  }
  return lines;
}

async function integrateGitChangesDialog(mode) {
  const tabId = gitChangesState.tabId || activeTabId;
  const data = gitChangesState.data;
  const upstream = data?.remote?.upstream || "@{upstream}";
  const command = mode === "merge" ? `git merge --no-edit ${upstream}` : `git rebase ${upstream}`;
  if (!(await appConfirmText([
    `${mode === "merge" ? "Merge" : "Rebase onto"} ${upstream} in ${data?.root || "the current repository"}?`,
    "",
    `Command: ${command}`,
    mode === "rebase" ? "Rebase rewrites local commits. Conflicts open the conflicts panel." : "Conflicts open the conflicts panel.",
    "For risky integration, prefer a separate worktree instead.",
  ].join("\n"), { affected: data?.root || "the current repository", confirmLabel: mode === "merge" ? "Merge" : "Rebase" }))) return;
  gitChangesState = { ...gitChangesState, pulling: true, error: "", errorCode: "", errorHint: "", message: "", pullResult: null };
  renderGitChangesDialog();
  try {
    const response = await api("/api/git-changes/integrate", { method: "POST", body: { mode, confirmed: true }, tabId });
    if (!response.ok) {
      const errText = [response.error, response.hint].filter(Boolean).join("\n") || `git ${mode} failed`;
      gitChangesState = { ...gitChangesState, pulling: false };
      await loadGitChangesDialog({ tabId });
      gitChangesState = { ...gitChangesState, error: errText, errorCode: response.code || "" };
      renderGitChangesDialog();
      return;
    }
    gitChangesState = { ...gitChangesState, pulling: false, message: `Integrated ${upstream} via ${mode}.`, data: response.data?.changes || gitChangesState.data };
    addEvent(`Integrated ${upstream} via ${mode}.`, "success");
    renderGitChangesDialog();
    requestGitFooterWebuiPayload(activeTabContext(tabId), { force: true });
  } catch (error) {
    gitChangesState = { ...gitChangesState, pulling: false, error: error.message || String(error) };
    renderGitChangesDialog();
  }
}

async function runGitFileAction(action, path) {
  const tabId = gitChangesState.tabId || activeTabId;
  const root = gitChangesState.data?.root || "the repository";
  const config = {
    stage: { url: "/api/git-changes/stage-file", body: { path }, label: `Staged ${path}.` },
    unstage: { url: "/api/git-changes/unstage-file", body: { path }, label: `Unstaged ${path}.` },
    discard: {
      url: "/api/git-changes/discard-file",
      body: { path, confirmed: true },
      label: `Discarded changes in ${path}.`,
      confirm: `Discard working tree changes in ${path}?\n\nRepository: ${root}\nCommand: git restore -- ${path}\n\nThis permanently reverts unstaged edits to this file.`,
    },
    "delete-untracked": {
      url: "/api/git-changes/delete-untracked",
      body: { path, confirmed: true },
      label: `Deleted untracked file ${path}.`,
      confirm: `Delete untracked file ${path}?\n\nRepository: ${root}\n\nThis permanently removes the file from disk.`,
    },
  }[action];
  if (!config) return;
  if (config.confirm && !(await appConfirmText(config.confirm, { affected: path, confirmLabel: action }))) return;
  if (gitChangesState.busyPath) return; // one file action at a time; ignore double clicks
  // Remember which control had focus so it can be restored after the dialog re-renders.
  const focusedActionLabel = document.activeElement?.classList?.contains("git-file-action") ? document.activeElement.textContent : "";
  const restoreFocus = () => {
    if (!focusedActionLabel) return;
    const candidates = [...(elements.gitChangesBody?.querySelectorAll(`.git-file-action[data-git-file-action-path="${CSS.escape(path)}"]`) || [])];
    const target = candidates.find((node) => node.textContent === focusedActionLabel) || candidates[0]
      || elements.gitChangesBody?.querySelector(".git-file-action") || elements.gitChangesDialog?.querySelector("button");
    target?.focus?.({ preventScroll: true });
  };
  gitChangesState = { ...gitChangesState, busyPath: path };
  renderGitChangesDialog();
  try {
    const response = await api(config.url, { method: "POST", body: config.body, tabId });
    if (!response.ok) throw new Error([response.error, response.hint].filter(Boolean).join("\n") || `git ${action} failed`);
    gitChangesState = { ...gitChangesState, busyPath: "", data: response.data?.changes || gitChangesState.data, message: config.label, error: "", errorCode: "", errorHint: "" };
    addEvent(config.label, "success");
    renderGitChangesDialog();
    restoreFocus();
    requestGitFooterWebuiPayload(activeTabContext(tabId), { force: true });
  } catch (error) {
    gitChangesState = { ...gitChangesState, busyPath: "", error: error.message || String(error) };
    renderGitChangesDialog();
    restoreFocus();
    addEvent(error.message || String(error), "error");
  }
}

const GIT_OPERATION_TITLES = {
  merge: "Merge in progress",
  rebase: "Rebase in progress",
  "cherry-pick": "Cherry-pick in progress",
  revert: "Revert in progress",
  bisect: "Bisect in progress",
};

function renderGitConflictPreview(preview) {
  if (!preview) return null;
  if (preview.kind === "binary") return make("pre", "git-conflict-preview muted", `Binary file (${formatBytes(preview.size || 0)}); resolve it with an external tool, then mark it resolved.`);
  if (preview.kind === "large") return make("pre", "git-conflict-preview muted", `File too large to preview (${formatBytes(preview.size || 0)}).`);
  if (preview.kind === "missing") return make("pre", "git-conflict-preview muted", "File is missing in the working tree (deleted on one side).");
  if (preview.kind === "error") return make("pre", "git-conflict-preview muted", preview.error || "Preview unavailable.");
  if (preview.kind !== "text") return null;
  if (!preview.hunks?.length) {
    return make("pre", "git-conflict-preview muted", preview.hasMarkers ? "Conflict markers present." : "No conflict markers found; the file may already be resolved — mark it resolved to stage it.");
  }
  const text = preview.hunks.map((hunk) => hunk.lines.join("\n") + (hunk.truncated ? "\n…" : "")).join("\n⋯\n");
  return make("pre", "git-conflict-preview", text);
}

async function runGitOperationRequest(url, body, successLabel) {
  const tabId = gitChangesState.tabId || activeTabId;
  gitToolsState.busy.add("operation");
  renderGitChangesDialog();
  try {
    const response = await api(url, { method: "POST", body, tabId });
    if (!response.ok) throw new Error([response.error, response.hint].filter(Boolean).join("\n") || "git operation failed");
    gitToolsState.busy.delete("operation");
    addEvent(`${successLabel}.`, "success");
    await loadGitChangesDialog({ tabId });
    gitChangesState = { ...gitChangesState, message: `${successLabel}.` };
    renderGitChangesDialog();
    requestGitFooterWebuiPayload(activeTabContext(tabId), { force: true });
  } catch (error) {
    gitToolsState.busy.delete("operation");
    gitChangesState = { ...gitChangesState, error: error.message || String(error) };
    renderGitChangesDialog();
  }
}

function renderGitOperationPanel(operation) {
  const kind = operation?.operation;
  if (!kind) return null;
  const busy = gitToolsState.busy.has("operation") || gitToolsState.busy.has("conflict-agent") || gitChangesState.loading || gitChangesState.pulling || gitChangesState.fetching;
  const conflicts = operation.conflicts || [];
  const panel = make("section", "git-operation-panel");
  const header = make("div", "git-operation-header");
  header.append(
    make("strong", "git-operation-title", GIT_OPERATION_TITLES[kind] || `${kind} in progress`),
    make("span", "git-operation-meta", `${conflicts.length} conflicted file${conflicts.length === 1 ? "" : "s"} · ${operation.root || ""}`),
  );
  panel.append(header);

  if (kind === "bisect") {
    if (operation.bisect?.log) panel.append(make("pre", "git-conflict-preview", operation.bisect.log));
    const row = make("div", "git-operation-actions");
    for (const verdict of ["good", "bad", "skip"]) {
      const button = make("button", "git-operation-button", `bisect ${verdict}`);
      button.type = "button";
      button.disabled = busy;
      button.title = `git bisect ${verdict}`;
      button.addEventListener("click", () => runGitOperationRequest("/api/git-operation/bisect", { verdict }, `Marked the current revision as ${verdict}`));
      row.append(button);
    }
    const reset = make("button", "git-operation-button danger", "Reset bisect");
    reset.type = "button";
    reset.disabled = busy;
    reset.title = "git bisect reset";
    reset.addEventListener("click", async () => {
      if (!(await appConfirmText(`Reset the bisect session in ${operation.root}?\n\nCommand: git bisect reset\nThis returns to the pre-bisect checkout.`, { affected: operation.root, confirmLabel: "Reset bisect" }))) return;
      runGitOperationRequest("/api/git-operation/bisect", { verdict: "reset", confirmed: true }, "Reset the bisect session");
    });
    row.append(reset);
    panel.append(row);
    return panel;
  }

  if (conflicts.length) {
    const list = make("div", "git-conflict-list");
    for (const conflict of conflicts) {
      const item = make("details", "git-conflict-file");
      item.open = conflicts.length <= 3;
      const summary = make("summary", "git-conflict-summary");
      summary.append(
        make("span", "git-conflict-status", conflict.status || "UU"),
        make("span", "git-conflict-path", conflict.path),
      );
      const actions = gitFileActionButtons([
        {
          label: "Mark resolved",
          title: `git add -- ${conflict.path}`,
          onClick: () => runGitOperationRequest("/api/git-operation/stage-file", { path: conflict.path }, `Marked ${conflict.path} as resolved`),
        },
      ]);
      if (actions) summary.append(actions);
      item.append(summary);
      const preview = renderGitConflictPreview(conflict.preview);
      if (preview) item.append(preview);
      list.append(item);
    }
    panel.append(list);
  } else {
    panel.append(make("div", "git-changes-empty success", "No unmerged paths remain. Continue to finish the operation."));
  }

  const row = make("div", "git-operation-actions");
  const refresh = make("button", "git-operation-button", "Refresh conflicts");
  refresh.type = "button";
  refresh.disabled = busy;
  refresh.addEventListener("click", refreshGitChangesDialog);
  row.append(refresh);

  if (conflicts.length) {
    const resolveWithAgent = make("button", "git-operation-button primary", "Resolve with agent");
    resolveWithAgent.type = "button";
    resolveWithAgent.disabled = busy;
    resolveWithAgent.title = `Open a new Pi tab in ${operation.root} and send it the ${kind} conflict context`;
    resolveWithAgent.addEventListener("click", async () => {
      const sourceTabId = gitChangesState.tabId || activeTabId;
      gitToolsState.busy.add("conflict-agent");
      renderGitChangesDialog();
      try {
        const response = await api("/api/git-operation/resolve-with-agent", { method: "POST", body: {}, tabId: sourceTabId });
        if (!response.ok) throw new Error(response.error || "Failed to open a conflict-resolution agent");
        closeGitChangesDialog();
        const targetTab = await switchToResponseTab(response);
        addEvent(`Opened ${targetTab?.title || "a new Pi tab"} and sent the ${kind} conflict context.`, "success");
      } catch (error) {
        gitChangesState = { ...gitChangesState, error: error.message || String(error) };
        renderGitChangesDialog();
      } finally {
        gitToolsState.busy.delete("conflict-agent");
        if (elements.gitChangesDialog?.open) renderGitChangesDialog();
      }
    });
    row.append(resolveWithAgent);
  }

  const cont = make("button", "git-operation-button primary", kind === "merge" ? "Continue (commit merge)" : "Continue");
  cont.type = "button";
  cont.disabled = busy || operation.canContinue !== true;
  cont.title = operation.canContinue ? operation.commands?.continue || "" : "Resolve and stage every conflicted file first.";
  cont.addEventListener("click", () => runGitOperationRequest("/api/git-operation/continue", {}, `Continued the ${kind}`));
  row.append(cont);

  if (operation.canSkip) {
    const skip = make("button", "git-operation-button", "Skip");
    skip.type = "button";
    skip.disabled = busy;
    skip.title = operation.commands?.skip || "";
    skip.addEventListener("click", async () => {
      if (!(await appConfirmText(`Skip the current ${kind} step?\n\nCommand: ${operation.commands?.skip || `git ${kind} --skip`}\nThe skipped commit is left out of the result.`, { affected: operation.root, confirmLabel: `Skip ${kind} step` }))) return;
      runGitOperationRequest("/api/git-operation/skip", {}, `Skipped the current ${kind} step`);
    });
    row.append(skip);
  }

  const abort = make("button", "git-operation-button danger", "Abort");
  abort.type = "button";
  abort.disabled = busy;
  abort.title = operation.commands?.abort || "";
  abort.addEventListener("click", async () => {
    const summary = operation.summary || {};
    if (!(await appConfirmText([
      `Abort the ${kind} in ${operation.root}?`,
      "",
      `Command: ${operation.commands?.abort || `git ${kind} --abort`}`,
      `Working tree: ${summary.staged || 0} staged · ${summary.unstaged || 0} unstaged · ${conflicts.length} conflicted`,
      "",
      "This discards the in-progress operation state and returns to the pre-operation HEAD.",
    ].join("\n"), { affected: operation.root, confirmLabel: `Abort ${kind}` }))) return;
    runGitOperationRequest("/api/git-operation/abort", { confirmed: true }, `Aborted the ${kind}`);
  });
  row.append(abort);
  panel.append(row);
  return panel;
}

function renderGitDivergedBar(data) {
  const remote = data?.remote || {};
  const bar = make("section", "git-diverged-bar");
  bar.append(make("strong", "git-diverged-title", `Diverged from ${remote.upstream || "upstream"}: ↑${remote.ahead || 0} local · ↓${remote.behind || 0} remote.`));
  bar.append(make("div", "git-tools-note", "One-click pull is disabled. Review the incoming diff below, then integrate explicitly — a separate worktree is the safest place for risky integration."));
  const row = make("div", "git-operation-actions");
  const busy = gitChangesState.loading || gitChangesState.pulling || gitChangesState.fetching;
  const addButton = (label, className, title, handler) => {
    const button = make("button", `git-operation-button ${className}`.trim(), label);
    button.type = "button";
    button.disabled = busy;
    button.title = title;
    button.addEventListener("click", handler);
    row.append(button);
  };
  addButton("Merge upstream…", "", `git merge --no-edit ${remote.upstream || "@{upstream}"}`, () => integrateGitChangesDialog("merge"));
  addButton("Rebase onto upstream…", "", `git rebase ${remote.upstream || "@{upstream}"}`, () => integrateGitChangesDialog("rebase"));
  addButton("Create integration worktree", "", "Open the branch picker to integrate in a separate worktree tab", () => {
    closeGitChangesDialog();
    openBranchWorktreePicker();
  });
  bar.append(row);
  return bar;
}

// ---- Git tools (stash, undo, worktrees, submodules, tags, signing) ----

const GIT_TOOLS_SECTIONS = [
  { key: "stash", title: "Stash", detail: "List, apply, pop, drop, or create stashes." },
  { key: "undo", title: "Undo & recovery", detail: "Undo the last unpushed commit, amend its message, review recent HEAD history." },
  { key: "worktrees", title: "Worktrees", detail: "Health, removal, and pruning of git worktrees." },
  { key: "submodules", title: "Submodules", detail: "Status and recursive update." },
  { key: "tags", title: "Tags", detail: "Recent tags and annotated tag creation." },
  { key: "signing", title: "Signing", detail: "Commit signing configuration and diagnostics." },
];

const GIT_TOOLS_ENDPOINTS = {
  stash: "/api/git-stash",
  undo: "/api/git-undo",
  worktrees: "/api/git-worktrees",
  submodules: "/api/git-submodules",
  tags: "/api/git-tags",
  signing: "/api/git-signing",
};

function resetGitToolsState(tabId) {
  gitToolsState = { tabId, openSections: new Set(), cache: {}, busy: new Set(), notice: {} };
}

async function loadGitToolsSection(key, { force = false } = {}) {
  const tabId = gitChangesState.tabId || activeTabId;
  if (!force && gitToolsState.cache[key]) return;
  if (gitToolsState.busy.has(`load:${key}`)) return;
  gitToolsState.busy.add(`load:${key}`);
  try {
    const response = await api(GIT_TOOLS_ENDPOINTS[key], { tabId });
    if (!response.ok) throw new Error(response.error || `Failed to load ${key}`);
    gitToolsState.cache[key] = response.data;
    if (key === "undo") {
      const reflog = await api("/api/git-reflog", { tabId }).catch(() => null);
      gitToolsState.cache.reflog = reflog?.ok ? reflog.data : null;
    }
    gitToolsState.notice[key] = "";
  } catch (error) {
    gitToolsState.notice[key] = error.message || String(error);
  } finally {
    gitToolsState.busy.delete(`load:${key}`);
    renderGitChangesDialog();
  }
}

async function runGitToolAction(sectionKey, { url, method = "POST", body, confirm, success, successMessage, refreshChanges = false }) {
  const tabId = gitChangesState.tabId || activeTabId;
  if (confirm && !(await appConfirmText(confirm, { affected: gitChangesState.data?.root || "the current repository", confirmLabel: success || "Continue" }))) return;
  gitToolsState.busy.add(sectionKey);
  renderGitChangesDialog();
  try {
    const response = await api(url, { method, body, tabId });
    if (!response.ok) throw new Error([response.error, response.hint].filter(Boolean).join("\n") || "git action failed");
    const finalMessage = (typeof successMessage === "function" ? successMessage(response) : "") || success;
    gitToolsState.notice[sectionKey] = "";
    gitToolsState.busy.delete(sectionKey);
    addEvent(finalMessage, "success");
    await loadGitToolsSection(sectionKey, { force: true });
    if (refreshChanges) await loadGitChangesDialog({ tabId });
    gitChangesState = { ...gitChangesState, message: finalMessage };
    renderGitChangesDialog();
    requestGitFooterWebuiPayload(activeTabContext(tabId), { force: true });
  } catch (error) {
    gitToolsState.busy.delete(sectionKey);
    gitToolsState.notice[sectionKey] = error.message || String(error);
    renderGitChangesDialog();
  }
}

function gitToolsButton(label, { className = "", disabled = false, title = "" } = {}, handler) {
  const button = make("button", `git-operation-button ${className}`.trim(), label);
  button.type = "button";
  button.disabled = disabled;
  if (title) button.title = title;
  button.addEventListener("click", handler);
  return button;
}

// Apply/pop/drop always show the stash's --stat preview in the confirmation,
// so no stash is modified sight-unseen.
async function confirmGitStashActionWithPreview(stash, question) {
  const tabId = gitChangesState.tabId || activeTabId;
  let statText = "";
  try {
    const preview = await api(`/api/git-stash/show?ref=${encodeURIComponent(stash.ref)}`, { tabId });
    statText = preview?.ok ? String(preview.data?.stat || "").trim() : "";
  } catch {
    // Preview is best-effort; the confirmation still shows the stash subject.
  }
  return appConfirmText([
    question,
    "",
    stash.subject || stash.ref,
    "",
    statText ? `Preview (git stash show --stat):\n${statText.slice(0, 2000)}` : "Preview unavailable.",
  ].join("\n"), { affected: stash.subject || stash.ref, confirmLabel: "Continue" });
}

function renderGitStashTools(body, data, busy) {
  const row = make("div", "git-operation-actions");
  row.append(
    gitToolsButton("Stash tracked changes", { disabled: busy, title: "git stash push" }, () =>
      runGitToolAction("stash", { url: "/api/git-stash/save", body: {}, success: "Stashed tracked changes.", refreshChanges: true })),
    gitToolsButton("Stash incl. untracked", { disabled: busy, title: "git stash push --include-untracked" }, () =>
      runGitToolAction("stash", { url: "/api/git-stash/save", body: { includeUntracked: true }, success: "Stashed tracked and untracked changes.", refreshChanges: true })),
  );
  body.append(row);
  const stashes = data.stashes || [];
  if (!stashes.length) {
    body.append(make("div", "git-changes-empty", "No stashes."));
    return body;
  }
  for (const stash of stashes) {
    const item = make("details", "git-tools-item");
    const summary = make("summary", "git-tools-item-summary");
    summary.append(make("span", "git-tools-item-ref", stash.ref), make("span", "git-tools-item-subject", stash.subject || ""));
    const actions = gitFileActionButtons([
      {
        label: "Apply",
        title: `git stash apply ${stash.ref}`,
        onClick: () => confirmGitStashActionWithPreview(stash, `Apply ${stash.ref} to the working tree?`).then((confirmed) => {
          if (confirmed) runGitToolAction("stash", { url: "/api/git-stash/apply", body: { ref: stash.ref }, success: `Applied ${stash.ref}.`, refreshChanges: true });
        }),
      },
      {
        label: "Pop",
        title: `git stash pop ${stash.ref}`,
        onClick: () => confirmGitStashActionWithPreview(stash, `Pop ${stash.ref}? This applies the stash and removes the entry on success.`).then((confirmed) => {
          if (confirmed) runGitToolAction("stash", { url: "/api/git-stash/pop", body: { ref: stash.ref }, success: `Popped ${stash.ref}.`, refreshChanges: true });
        }),
      },
      {
        label: "Drop",
        className: "danger",
        title: `git stash drop ${stash.ref}`,
        onClick: () => confirmGitStashActionWithPreview(stash, `Drop ${stash.ref}? This permanently deletes the stash entry.`).then((confirmed) => {
          if (confirmed) runGitToolAction("stash", { url: "/api/git-stash/drop", body: { ref: stash.ref, confirmed: true }, success: `Dropped ${stash.ref}.` });
        }),
      },
    ]);
    if (actions) summary.append(actions);
    item.append(summary);
    item.addEventListener("toggle", async () => {
      if (!item.open || item.dataset.previewLoaded) return;
      item.dataset.previewLoaded = "1";
      const placeholder = make("pre", "git-conflict-preview muted", "Loading stash preview…");
      item.append(placeholder);
      const preview = await api(`/api/git-stash/show?ref=${encodeURIComponent(stash.ref)}`, { tabId: gitChangesState.tabId || activeTabId }).catch(() => null);
      const text = preview?.ok ? [preview.data?.stat, preview.data?.patch].filter(Boolean).join("\n\n") : "Preview unavailable.";
      placeholder.textContent = text || "Empty stash preview.";
      placeholder.classList.toggle("muted", !preview?.ok);
    });
    body.append(item);
  }
  return body;
}

function renderGitUndoTools(body, data, busy) {
  const last = data.lastCommit;
  body.append(make("div", "git-tools-note", last ? `Last commit: ${last.hash} ${last.subject}` : "No commits yet."));
  const row = make("div", "git-operation-actions");
  row.append(gitToolsButton(
    "Undo last commit (keep changes)",
    { disabled: busy || !data.canUndoLastCommit, title: data.canUndoLastCommit ? "git reset --soft HEAD~1" : "Requires an unpushed commit with a parent and no operation in progress." },
    () => runGitToolAction("undo", {
      url: "/api/git-undo/last-commit",
      body: { confirmed: true },
      confirm: [
        `Undo the last commit in ${data.root}?`,
        "",
        `Commit: ${last?.hash || ""} ${last?.subject || ""}`,
        "Command: git reset --soft HEAD~1 (the commit's changes stay staged)",
        "Restore afterwards with: git reset --soft ORIG_HEAD",
      ].join("\n"),
      success: "Undid the last commit; its changes remain staged.",
      successMessage: (response) => {
        const undone = response.data?.undoneCommit;
        const restore = response.data?.restoreCommand || "git reset --soft ORIG_HEAD";
        return `Undid commit ${undone?.hash || ""} "${undone?.subject || ""}"; its changes remain staged. Restore with: ${restore}`;
      },
      refreshChanges: true,
    }),
  ));
  row.append(gitToolsButton(
    "Amend last commit message",
    { disabled: busy || !data.canAmendMessage, title: data.canAmendMessage ? "git commit --amend -m <message>" : "Requires an unpushed commit and an empty staging area." },
    async () => {
      const message = await appPromptText({ title: "Amend last commit message", summary: `git commit --amend -m <message> · current: ${last?.subject || ""}`, defaultValue: last?.subject || "", confirmLabel: "Amend", validate: (value) => (String(value || "").trim() ? "" : "A commit message is required.") });
      if (!message || !message.trim()) return;
      runGitToolAction("undo", {
        url: "/api/git-undo/amend-message",
        body: { confirmed: true, message: message.trim() },
        confirm: `Rewrite the last commit message?\n\nOld: ${last?.subject || ""}\nNew: ${message.trim()}`,
        success: "Amended the last commit message.",
        successMessage: (response) => {
          const previous = response.data?.previousCommit;
          const restore = response.data?.restoreCommand || "git reset --soft ORIG_HEAD";
          return `Amended the last commit message${previous?.hash ? ` (was ${previous.hash} "${previous.subject}")` : ""}. Restore with: ${restore}`;
        },
      });
    },
  ));
  body.append(row);
  const reflog = gitToolsState.cache.reflog;
  if (reflog?.entries?.length) {
    const details = make("details", "git-tools-item");
    details.append(make("summary", "git-tools-item-summary", `Recent HEAD history (${reflog.entries.length})`));
    details.append(make("pre", "git-conflict-preview", reflog.entries.map((entry) => `${entry.selector}\t${entry.hash}\t${entry.subject}`).join("\n")));
    body.append(details);
    body.append(make("div", "git-tools-note", "Recovery from here is read-only: copy a hash and use git reset/cherry-pick in a terminal."));
  }
  return body;
}

function renderGitWorktreeTools(body, data, busy) {
  const worktrees = data.worktrees || [];
  for (const worktree of worktrees) {
    const item = make("div", "git-tools-row");
    const health = [
      worktree.isMainWorktree ? "main" : "",
      worktree.current ? "current" : "",
      worktree.detached ? "detached" : "",
      worktree.locked ? `locked${worktree.lockedReason ? `: ${worktree.lockedReason}` : ""}` : "",
      worktree.prunable ? "prunable" : "",
    ].filter(Boolean).join(" · ");
    item.append(
      make("span", "git-tools-item-ref", worktree.branch || "detached"),
      make("span", "git-tools-item-subject", `${normalizeDisplayPath(worktree.path)}${health ? ` · ${health}` : ""}`),
    );
    if (!worktree.isMainWorktree && !worktree.current) {
      const actions = gitFileActionButtons([
        {
          label: "Remove",
          className: "danger",
          title: `git worktree remove ${worktree.path}`,
          onClick: () => runGitToolAction("worktrees", {
            method: "DELETE",
            url: "/api/git-worktrees",
            body: { path: worktree.path, confirmed: true },
            confirm: [
              `Remove worktree ${worktree.path}?`,
              "",
              `Branch: ${worktree.branch || "detached"}`,
              "This deletes the checkout directory. Dirty worktrees and worktrees with open tabs are refused.",
            ].join("\n"),
            success: `Removed worktree ${worktree.path}.`,
          }),
        },
      ]);
      if (actions) item.append(actions);
    }
    body.append(item);
  }
  const row = make("div", "git-operation-actions");
  row.append(gitToolsButton("Prune stale worktrees…", { disabled: busy, title: "git worktree prune (with dry-run preview)" }, async () => {
    const tabId = gitChangesState.tabId || activeTabId;
    try {
      const preview = await api("/api/git-worktrees/prune", { tabId });
      const previewData = preview?.data || preview || {};
      const output = String(previewData.output || "").trim();
      const prunable = previewData.prunable || [];
      if (!output && !prunable.length) {
        window.alert("No stale worktree records to prune.");
        return;
      }
      const lines = prunable.map((item) => `${item.path}${item.reason ? ` (${item.reason})` : ""}`).join("\n");
      runGitToolAction("worktrees", {
        url: "/api/git-worktrees/prune",
        body: { confirmed: true },
        confirm: `Prune stale worktree records?\n\nDry run:\n${output || lines || "(no output)"}\n\nThis removes administrative records for worktree directories that no longer exist.`,
        success: "Pruned stale worktree records.",
      });
    } catch (error) {
      gitToolsState.notice.worktrees = error.message || String(error);
      renderGitChangesDialog();
    }
  }));
  body.append(row);
  return body;
}

function renderGitSubmoduleTools(body, data, busy) {
  if (!data.hasSubmodules) {
    body.append(make("div", "git-changes-empty", "This repository has no submodules."));
    return body;
  }
  for (const submodule of data.submodules || []) {
    const item = make("div", "git-tools-row");
    item.append(
      make("span", "git-tools-item-ref", submodule.state),
      make("span", "git-tools-item-subject", `${submodule.path} · ${String(submodule.sha || "").slice(0, 10)}${submodule.describe ? ` · ${submodule.describe}` : ""}`),
    );
    const actions = gitFileActionButtons([
      {
        label: "Open tab",
        title: "Open a Web UI tab rooted at this submodule",
        onClick: () => {
          const root = String(data.root || "").replace(/\/+$/, "");
          closeGitChangesDialog();
          createTerminalTab(`${root}/${submodule.path}`).catch((error) => addEvent(error.message || String(error), "error"));
        },
      },
      { label: "Copy path", title: "Copy the submodule path", onClick: () => copyGitPathToClipboard(submodule.path) },
    ]);
    if (actions) item.append(actions);
    body.append(item);
  }
  const row = make("div", "git-operation-actions");
  row.append(gitToolsButton("Update / init recursively…", { disabled: busy, title: "git submodule update --init --recursive" }, () =>
    runGitToolAction("submodules", {
      url: "/api/git-submodules/update",
      body: { confirmed: true },
      confirm: "Run git submodule update --init --recursive?\n\nThis can check out new commits in every submodule and may take a while.",
      success: "Updated submodules recursively.",
      refreshChanges: true,
    })));
  body.append(row);
  return body;
}

function renderGitTagTools(body, data, busy) {
  const tags = data.tags || [];
  if (!tags.length) body.append(make("div", "git-changes-empty", "No tags."));
  for (const tag of tags.slice(0, 15)) {
    const item = make("div", "git-tools-row");
    item.append(
      make("span", "git-tools-item-ref", tag.name),
      make("span", "git-tools-item-subject", [tag.annotated ? "annotated" : "lightweight", tag.target ? `@ ${tag.target}` : "", tag.atHead ? "at HEAD" : "", tag.date || ""].filter(Boolean).join(" · ")),
    );
    body.append(item);
  }
  const row = make("div", "git-operation-actions");
  row.append(gitToolsButton("Create annotated tag…", { disabled: busy, title: "git tag -a <name> -m <message> (never pushed automatically)" }, async () => {
    const name = await appPromptText({ title: "Create annotated tag", summary: "git tag -a <name> -m <message> at HEAD. Tags are never pushed automatically.", placeholder: "v1.2.3", confirmLabel: "Next", validate: (value) => (String(value || "").trim() ? "" : "A tag name is required.") });
    if (!name || !name.trim()) return;
    const message = await appPromptText({ title: `Tag message for ${name.trim()}`, defaultValue: name.trim(), confirmLabel: "Create tag" });
    if (message === null) return;
    runGitToolAction("tags", {
      url: "/api/git-tags/create",
      body: { confirmed: true, name: name.trim(), message: (message || name).trim() },
      confirm: `Create annotated tag ${name.trim()} at HEAD?\n\nTags are not pushed automatically; push explicitly with: git push origin ${name.trim()}`,
      success: `Created tag ${name.trim()}.`,
    });
  }));
  body.append(row);
  return body;
}

function renderGitSigningTools(body, data) {
  body.append(make("div", "git-tools-note", `commit.gpgsign: ${data.commitSignRequired ? "true" : "false"} · gpg.format: ${data.gpgFormat} · user.signingkey: ${data.signingKey}`));
  if (data.lastCommit) body.append(make("div", "git-tools-note", `Last commit ${data.lastCommit.hash}: signature state ${data.lastCommit.signState}${data.lastCommit.signer ? ` (${data.lastCommit.signer})` : ""}`));
  body.append(make("div", `git-tools-note${data.mismatch ? " error" : ""}`, data.mismatch ? "Signing mismatch: signing is required but the last commit is not validly signed." : "No signing mismatch detected."));
  for (const suggestion of data.suggestions || []) {
    const item = make("div", "git-tools-row");
    item.append(make("span", "git-tools-item-subject", suggestion.label), make("code", "git-tools-command", suggestion.command));
    const actions = gitFileActionButtons([
      { label: "Copy", title: "Copy this command", onClick: () => navigator.clipboard?.writeText(suggestion.command).catch(() => {}) },
    ]);
    if (actions) item.append(actions);
    body.append(item);
  }
  body.append(make("div", "git-tools-note", "Commands are copyable only; config is never rewritten automatically."));
  return body;
}

function renderGitToolsSectionBody(key) {
  const body = make("div", "git-tools-body");
  const notice = gitToolsState.notice[key];
  if (notice) body.append(make("div", "git-changes-empty error", notice));
  const data = gitToolsState.cache[key];
  const busy = gitToolsState.busy.has(key) || gitToolsState.busy.has(`load:${key}`);
  if (!data) {
    if (!notice) body.append(make("div", "git-changes-empty", "Loading…"));
    return body;
  }
  switch (key) {
    case "stash":
      return renderGitStashTools(body, data, busy);
    case "undo":
      return renderGitUndoTools(body, data, busy);
    case "worktrees":
      return renderGitWorktreeTools(body, data, busy);
    case "submodules":
      return renderGitSubmoduleTools(body, data, busy);
    case "tags":
      return renderGitTagTools(body, data, busy);
    case "signing":
      return renderGitSigningTools(body, data);
    default:
      return body;
  }
}

function renderGitToolsSection() {
  const wrapper = make("section", "git-tools");
  wrapper.append(make("div", "git-diff-section-heading git-tools-heading", "Git tools"));
  for (const section of GIT_TOOLS_SECTIONS) {
    const details = make("details", "git-tools-section");
    details.dataset.gitTools = section.key;
    details.open = gitToolsState.openSections.has(section.key);
    const summary = make("summary", "git-tools-summary");
    summary.append(make("span", "git-tools-title", section.title), make("span", "git-tools-detail", section.detail));
    details.append(summary);
    if (details.open) details.append(renderGitToolsSectionBody(section.key));
    details.addEventListener("toggle", () => {
      if (details.open) {
        if (gitToolsState.openSections.has(section.key)) return;
        gitToolsState.openSections.add(section.key);
        loadGitToolsSection(section.key);
        renderGitChangesDialog();
      } else {
        gitToolsState.openSections.delete(section.key);
      }
    });
    wrapper.append(details);
  }
  return wrapper;
}

// Route the git+ chip to the tools section matching its leading indicator
// (📦 stash, 🧩 submodules, 🔓 signing, 🏷 tag, 🌳 worktrees).
function gitToolsSectionForExtraChip(value = "") {
  const text = String(value || "");
  if (text.includes("📦")) return "stash";
  if (text.includes("🧩")) return "submodules";
  if (text.includes("🔓")) return "signing";
  if (text.includes("🏷")) return "tags";
  if (text.includes("🌳")) return "worktrees";
  return "stash";
}

function openGitToolsFromFooter(section = "stash") {
  openGitChangesDialog();
  gitToolsState.openSections.add(section);
  loadGitToolsSection(section);
  renderGitChangesDialog();
}

function gitFooterFallbackMessage() {
  if (isOptionalFeatureDisabled("gitFooterStatus")) return "";
  const tabContext = activeTabContext();
  const commandsStillLoading = availableCommands.length === 0 && rawAvailableCommands.length === 0;
  const footerRefreshPending = tabContext.tabId ? gitFooterPayloadRefreshInFlightByTab.has(tabContext.tabId) : false;
  const payloadState = tabContext.tabId ? gitFooterPayloadStateByTab.get(tabContext.tabId) : null;
  const extensionDetected = hasAvailableCommand("git-footer-refresh") || optionalFeatureAvailability.gitFooterStatus;
  if (commandsStillLoading || footerRefreshPending || payloadState?.phase === "waiting") return "Loading git footer status…";
  if (payloadState?.phase === "failed") return payloadState.error || "Git footer status was not received — refresh to retry";
  if (payloadState?.phase === "idle") return "Git footer status unavailable — refresh to retry";
  if (extensionDetected) return "Loading git footer status…";
  return "Git footer status extension unavailable";
}

function renderMinimalFooter() {
  invalidateGitFooterRenderCache();
  const tab = activeTab();
  const workspaceLabel = latestWorkspace?.displayCwd || (tab?.cwd ? normalizeDisplayPath(tab.cwd) : "loading…");
  const modelLine = footerModelLine();
  const footerMessage = gitFooterFallbackMessage();

  elements.statusBar.replaceChildren();
  elements.statusBar.classList.remove("statusbar-git-footer");
  elements.statusBar.classList.add("statusbar-tui-footer");
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
  elements.statusBar.append(renderTuiFooterLine({
    cwd: workspaceLabel,
    cwdTitle: tab ? `Change cwd for ${tab.title}: ${workspaceLabel}` : undefined,
    message: footerMessage,
    stats: fallbackFooterStats(),
    model: modelLine,
  }));
  if (footerModelPickerOpen) elements.statusBar.append(renderFooterModelPicker());
  if (footerThinkingPickerOpen) elements.statusBar.append(renderFooterThinkingPicker());
  if (footerBranchPickerOpen) elements.statusBar.append(renderFooterBranchPicker());
  setMobileFooterExpanded(false);
  updateFooterModelPickerPosition();
}

function contextUsageSnapshot() {
  const usage = latestStats?.contextUsage || currentState?.contextUsage || null;
  const contextWindow = contextWindowFromSources(usage, currentState?.model?.contextWindow);
  if (!contextWindow) return null;
  const rawPercent = Number(usage?.percent);
  const unknown = contextUsageUnknownAfterCompaction() || !Number.isFinite(rawPercent);
  const rawTokens = Number(usage?.tokens);
  return {
    tokens: Number.isFinite(rawTokens) && rawTokens >= 0 ? rawTokens : null,
    contextWindow,
    percent: unknown ? null : Math.max(0, Math.min(100, rawPercent)),
    unknown,
    autoCompactionEnabled: footerAutoCompactionEnabled(),
  };
}

function contextUsageDisplay(snapshot = contextUsageSnapshot()) {
  if (!snapshot) return "Context unknown";
  const windowText = formatFooterTokenCount(snapshot.contextWindow);
  if (typeof snapshot.percent === "number") return `${snapshot.percent.toFixed(1)}% of ${windowText}`;
  return `?/${windowText}`;
}

function contextUsageDetail(snapshot = contextUsageSnapshot()) {
  if (!snapshot) return "Waiting for model context-window data.";
  const tokenText = snapshot.tokens === null ? "tokens unknown" : `${formatFooterTokenCount(snapshot.tokens)} tokens`;
  const autoText = snapshot.autoCompactionEnabled ? "auto-compaction on" : "auto-compaction off";
  return `${tokenText} · ${formatFooterTokenCount(snapshot.contextWindow)} window · ${autoText}`;
}

function appendContextMeterFill(meter, snapshot) {
  const fill = make("span", "context-meter-fill");
  const percent = typeof snapshot?.percent === "number" ? snapshot.percent : 0;
  fill.style.width = `${Math.max(0, Math.min(100, percent)).toFixed(1)}%`;
  if (typeof snapshot?.percent === "number") {
    const activeColor = contextUsageActiveColor(snapshot.percent);
    fill.style.setProperty("--context-active-color", activeColor.color);
    fill.style.setProperty("--context-active-glow", activeColor.glow);
  }
  meter.append(fill);
}

async function requestManualCompaction({ triggerButton = null } = {}) {
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  const buttons = [...new Set([elements.compactButton, triggerButton].filter(Boolean))];
  try {
    for (const button of buttons) {
      button.disabled = true;
      button.textContent = "Compacting…";
    }
    setRunIndicatorActivity("Requesting context compaction…");
    scrollChatToBottom({ force: true });
    markContextUsageUnknownAfterCompaction(tabContext.tabId);
    renderFooter();
    renderContextMeter();
    renderWorkspaceDashboard();
    addEvent("manual compaction requested");
    await api("/api/compact", { method: "POST", body: {}, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    scheduleRefreshState(120, tabContext);
    scheduleRefreshMessages(600, tabContext);
    scheduleRefreshFooter(600, tabContext);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      clearContextUsageUnknownAfterCompaction(tabContext.tabId);
      clearRunIndicatorActivity();
      renderFooter();
      renderContextMeter();
      renderWorkspaceDashboard();
      addEvent(error.message, "error");
    }
  } finally {
    if (isCurrentTabContext(tabContext)) {
      for (const button of buttons) {
        button.disabled = !!currentState?.isCompacting;
        button.textContent = button === elements.compactButton && currentState?.isCompacting ? "Compacting…" : button === elements.compactButton ? "Compact" : "Compact now";
      }
      renderContextMeter();
      renderWorkspaceDashboard();
    }
  }
}

let contextMeterSignature = null;

function renderContextMeter() {
  if (deferUiRenderDuringPointerActivation("context-meter", renderContextMeter)) return;
  const root = elements.contextMeterBar;
  if (!root) return;
  const tab = activeTab();
  const snapshot = contextUsageSnapshot();
  const visible = Boolean(tab && snapshot && typeof snapshot.percent === "number" && snapshot.percent > 50);
  const autoCompactionEnabled = footerAutoCompactionEnabled();
  const signature = JSON.stringify({
    tabId: tab?.id || "",
    visible,
    snapshot,
    isCompacting: !!currentState?.isCompacting,
    autoCompactionEnabled,
    autoCompactionToggleInFlight: footerAutoCompactionToggleInFlight,
    theme: [currentThemeName, effectiveScheme()],
  });
  if (signature === contextMeterSignature && root.hidden === !visible && (!visible || root.childElementCount > 0)) return;
  contextMeterSignature = signature;
  root.hidden = !visible;
  if (!visible) {
    root.replaceChildren();
    return;
  }
  const meter = make("div", `context-meter${snapshot?.unknown ? " unknown" : ""}`);
  appendContextMeterFill(meter, snapshot);

  const summary = make("div", "context-meter-summary");
  summary.append(
    make("strong", undefined, contextUsageDisplay(snapshot)),
    make("span", "muted", contextUsageDetail(snapshot)),
  );

  const actions = make("div", "context-meter-actions");
  const compact = make("button", "context-meter-compact", currentState?.isCompacting ? "Compacting…" : "Compact now");
  compact.type = "button";
  compact.disabled = !!currentState?.isCompacting;
  compact.title = "Manually compact this tab's conversation context";
  compact.addEventListener("click", () => requestManualCompaction({ triggerButton: compact }));
  const auto = make("button", "context-meter-auto", autoCompactionEnabled ? "Auto on" : "Auto off");
  auto.type = "button";
  auto.setAttribute("aria-pressed", autoCompactionEnabled ? "true" : "false");
  auto.disabled = footerAutoCompactionToggleInFlight;
  auto.title = footerAutoCompactionToggleInFlight ? "Updating auto-compaction…" : footerAutoCompactionToggleAction();
  auto.addEventListener("click", () => toggleFooterAutoCompaction());
  actions.append(compact, auto);

  root.replaceChildren(summary, meter, actions);
}

function compactDashboardText(value, maxLength = 34) {
  const text = String(value || "").trim();
  if (!text || text.length <= maxLength) return text;
  const available = Math.max(8, maxLength - 1);
  const headLength = Math.max(4, Math.ceil(available * 0.58));
  const tailLength = Math.max(4, available - headLength);
  return `${text.slice(0, headLength)}…${text.slice(-tailLength)}`;
}

function compactDashboardPath(value, maxLength = 52) {
  const text = normalizeDisplayPath(value || "").trim();
  if (!text || text.length <= maxLength) return text;
  const segments = text.split("/").filter(Boolean);
  if (segments.length >= 3) {
    const tail = `…/${segments.slice(-3).join("/")}`;
    if (tail.length <= maxLength) return tail;
  }
  return compactDashboardText(text, maxLength);
}

function contextDashboardTone(snapshot) {
  if (!snapshot) return "muted";
  if (typeof snapshot.percent !== "number") return "neutral";
  if (snapshot.percent >= 85) return "danger";
  if (snapshot.percent >= 70) return "warning";
  return "ok";
}

function dashboardSessionSummary() {
  const rawSession = currentState?.sessionName || currentState?.sessionId || "";
  const rawFile = currentState?.sessionFile || "in-memory";
  const sessionLabel = rawSession ? compactDashboardText(rawSession, 28) : "loading…";
  const fileLabel = rawFile === "in-memory" ? rawFile : compactDashboardPath(rawFile, 58);
  return {
    value: sessionLabel,
    detail: fileLabel,
    title: [rawSession || "Session loading…", rawFile].filter(Boolean).join("\n"),
  };
}

function dashboardMetric(label, value, detail = "", options = {}) {
  const tone = options.tone || "neutral";
  const item = make("div", `workspace-dashboard-metric tone-${tone}${options.meterSnapshot ? " with-meter" : ""}`);
  const valueText = value || "—";
  const title = options.title || [label, valueText, detail].filter(Boolean).join(" · ");
  item.title = title;
  item.setAttribute("aria-label", title);

  const icon = make("span", "workspace-dashboard-metric-icon", options.icon || "•");
  icon.setAttribute("aria-hidden", "true");
  const copy = make("span", "workspace-dashboard-metric-copy");
  copy.append(make("span", "workspace-dashboard-metric-label", label), make("strong", undefined, valueText));
  if (detail) copy.append(make("span", "workspace-dashboard-metric-detail", detail));
  item.append(icon, copy);

  if (options.meterSnapshot) {
    const meter = make("span", "workspace-dashboard-mini-meter");
    appendContextMeterFill(meter, options.meterSnapshot);
    item.append(meter);
  }
  return item;
}

function dashboardAction(label, handler, className = "") {
  const button = make("button", `workspace-dashboard-action ${className}`.trim(), label);
  button.type = "button";
  button.addEventListener("click", handler);
  return button;
}

let workspaceDashboardSignature = null;

function renderWorkspaceDashboard() {
  if (deferUiRenderDuringPointerActivation("workspace-dashboard", renderWorkspaceDashboard)) return;
  const root = elements.workspaceDashboard;
  if (!root) return;
  const tab = activeTab();
  const snapshot = contextUsageSnapshot();
  const workspaceLabel = latestWorkspace?.displayCwd || (tab?.cwd ? normalizeDisplayPath(tab.cwd) : "Choose or create a tab to start");
  const workspaceInfo = normalizeGitWorkspaceInfo(tab?.gitWorkspace);
  const worktreeLabel = gitWorkspaceBadgeLabel(workspaceInfo);
  const queueCount = Number(currentState?.pendingMessageCount || 0) || 0;
  const tabIndicatorState = tab ? tabIndicator(tab) : null;
  const sessionSummary = dashboardSessionSummary();
  const modelLabel = currentState?.model ? shortModelLabel(currentState.model) : "loading…";
  const queueDetail = queueCount === 0 ? "idle" : queueCount === 1 ? "pending message" : "pending messages";

  // Skip rebuilding the dashboard (and its buttons) when nothing it shows has
  // changed. Extension status pushes during streaming would otherwise rebuild
  // every workspace button on each token, causing flicker.
  const signature = JSON.stringify({
    title: tab?.title || "Pi Web UI",
    workspaceLabel,
    gitWorkspace: workspaceInfo ? {
      branch: workspaceInfo.branch,
      worktreePath: workspaceInfo.worktreePath,
      isMainWorktree: workspaceInfo.isMainWorktree,
      worktreeCount: workspaceInfo.worktreeCount,
    } : null,
    tabIndicatorState,
    tabsLength: tabs.length,
    queueCount,
    modelLabel,
    modelTitle: currentState?.model ? shortModelLabel(currentState.model) : "Model loading…",
    hasModel: !!currentState?.model,
    thinking: currentState?.thinkingLevel || "",
    context: { snapshot, display: contextUsageDisplay(snapshot), detail: contextUsageDetail(snapshot), tone: contextDashboardTone(snapshot) },
    theme: [currentThemeName, effectiveScheme()],
    session: sessionSummary,
    hasSession: !!(currentState?.sessionId || currentState?.sessionName),
    activeTabId,
    tabs: tabs.slice(0, 8).map((item) => ({ id: item.id, title: item.title, indicator: tabIndicator(item), active: item.id === activeTabId, cwd: item.cwd ? normalizeDisplayPath(item.cwd) : "" })),
    overflow: tabs.length > 8 ? tabs.length - 8 : 0,
    savedWorkspaces: !tabs.length ? savedWorkspaces.map((workspace) => ({ id: workspace.id, name: workspace.name, savedAt: workspace.savedAt, tabCount: workspace.tabCount, groupCount: workspace.groupCount, cwds: workspace.cwds })) : [],
    savedWorkspacesLoading,
    savedWorkspacesError,
  });
  if (signature === workspaceDashboardSignature && root.childElementCount > 0) return;
  workspaceDashboardSignature = signature;
  root.replaceChildren();

  const header = make("div", "workspace-dashboard-header");
  const title = make("div", "workspace-dashboard-title");
  const heading = make("h2", undefined, tab?.title || "Pi Web UI");
  heading.title = tab?.title || "Pi Web UI";
  const cwd = make("p", "workspace-dashboard-cwd muted", workspaceLabel);
  cwd.title = workspaceLabel;
  const meta = make("div", "workspace-dashboard-title-meta");
  if (tabIndicatorState) {
    const statusChip = make("span", `workspace-dashboard-chip activity-${tabIndicatorState.state}`);
    statusChip.title = tabIndicatorState.label;
    statusChip.append(make("span", "workspace-dashboard-chip-dot", tabIndicatorState.glyph), make("span", undefined, tabIndicatorState.label));
    meta.append(statusChip);
  }
  if (worktreeLabel) {
    const worktreeChip = make("button", "workspace-dashboard-chip worktree", worktreeLabel);
    worktreeChip.type = "button";
    worktreeChip.title = workspaceInfo?.worktreePath || worktreeLabel;
    worktreeChip.addEventListener("click", () => openBranchWorktreePicker());
    meta.append(worktreeChip);
  }
  meta.append(
    make("span", "workspace-dashboard-chip", `${tabs.length} tab${tabs.length === 1 ? "" : "s"}`),
    make("span", `workspace-dashboard-chip ${queueCount ? "attention" : ""}`.trim(), queueCount ? `${queueCount} queued` : "queue clear"),
  );
  const summary = make("div", "workspace-dashboard-summary-row");
  summary.append(make("span", "workspace-dashboard-kicker", "Workspace"), meta);
  const identity = make("div", "workspace-dashboard-identity");
  identity.append(heading, cwd);
  title.append(summary, identity);
  const actions = make("div", "workspace-dashboard-actions");
  actions.append(
    dashboardAction("Command palette", () => openCommandPalette(), "primary"),
    dashboardAction("New tab", () => createTerminalTab()),
  );
  if (tabs.length) {
    actions.append(
      dashboardAction("Load workspace", () => openWorkspaceLoadPicker(), "primary"),
      dashboardAction("Branch worktree", () => openBranchWorktreePicker(), "worktree"),
      dashboardAction("Resume", () => runNativeCommandMenu("/resume")),
      dashboardAction("Model", () => runNativeCommandMenu("/model")),
      dashboardAction("Settings", () => runNativeCommandMenu("/settings")),
    );
  }
  header.append(title, actions);

  const metrics = make("div", "workspace-dashboard-metrics");
  metrics.append(
    dashboardMetric("Model", modelLabel, currentState?.thinkingLevel ? `thinking ${currentState.thinkingLevel}` : "ready", {
      icon: "◌",
      tone: currentState?.model ? "neutral" : "muted",
      title: currentState?.model ? shortModelLabel(currentState.model) : "Model loading…",
    }),
    dashboardMetric("Context", contextUsageDisplay(snapshot), contextUsageDetail(snapshot), {
      icon: "◐",
      tone: contextDashboardTone(snapshot),
      meterSnapshot: snapshot,
    }),
    dashboardMetric("Session", sessionSummary.value, sessionSummary.detail, {
      icon: "#",
      tone: currentState?.sessionId || currentState?.sessionName ? "neutral" : "muted",
      title: sessionSummary.title,
    }),
    dashboardMetric("Queue", `${queueCount}`, queueDetail, {
      icon: queueCount ? "↳" : "✓",
      tone: queueCount ? "warning" : "ok",
    }),
  );

  const tabsPanel = make("div", "workspace-dashboard-tabs");
  const tabsHeader = make("div", "workspace-dashboard-tabs-header");
  tabsHeader.append(
    make("span", "workspace-dashboard-tabs-title", `Open tabs (${tabs.length})`),
    make("span", "workspace-dashboard-tabs-hint", tabs.length ? "Click a tab to switch" : "No tabs yet"),
  );
  tabsPanel.append(tabsHeader);
  const tabList = make("div", "workspace-dashboard-tab-list");
  for (const item of tabs.slice(0, 8)) {
    const indicator = tabIndicator(item);
    const button = make("button", `workspace-dashboard-tab activity-${indicator.state}${item.id === activeTabId ? " active" : ""}`);
    button.type = "button";
    button.title = `${item.title} · ${indicator.label}${item.cwd ? ` · ${normalizeDisplayPath(item.cwd)}` : ""}`;
    button.append(make("span", "workspace-dashboard-tab-dot", indicator.glyph), make("span", "workspace-dashboard-tab-label", item.title));
    button.addEventListener("click", () => switchTab(item.id));
    tabList.append(button);
  }
  if (!tabs.length) tabList.append(make("span", "workspace-dashboard-tab-empty", "Create a tab to start a workspace."));
  if (tabs.length > 8) tabList.append(make("span", "workspace-dashboard-tab-more", `+${tabs.length - 8} more`));
  tabsPanel.append(tabList);

  const savedWorkspacePanel = !tabs.length ? renderSavedWorkspacePicker() : null;
  root.append(header, metrics, tabsPanel);
  if (savedWorkspacePanel) root.append(savedWorkspacePanel);
}

function renderSavedWorkspacePicker() {
  if (!savedWorkspacesLoaded && !savedWorkspacesLoading && !savedWorkspacesError) {
    queueMicrotask(() => refreshSavedWorkspaces().catch((error) => addEvent(`Could not list saved workspaces: ${error.message || String(error)}`, "error")));
  }
  const panel = make("section", "workspace-saved-workspaces");
  panel.setAttribute("aria-label", "Saved workspaces");
  const heading = make("div", "workspace-saved-workspaces-heading");
  heading.append(
    make("span", "workspace-dashboard-kicker", "Saved workspaces"),
    make("span", "workspace-saved-workspaces-hint", "Load a complete saved tab constellation"),
  );
  panel.append(heading);
  if (savedWorkspacesLoading) {
    const status = make("p", "workspace-saved-workspaces-empty muted", "Loading saved workspaces…");
    status.setAttribute("role", "status");
    panel.append(status);
    return panel;
  }
  if (savedWorkspacesError) {
    const status = make("p", "workspace-saved-workspaces-empty error", `Could not load saved workspaces: ${savedWorkspacesError}`);
    status.setAttribute("role", "status");
    const retry = make("button", "workspace-saved-workspaces-retry", "Retry");
    retry.type = "button";
    retry.addEventListener("click", () => refreshSavedWorkspaces({ force: true }).catch((error) => addEvent(`Could not list saved workspaces: ${error.message || String(error)}`, "error")));
    panel.append(status, retry);
    return panel;
  }
  if (!savedWorkspaces.length) {
    panel.append(make("p", "workspace-saved-workspaces-empty muted", "No saved workspaces yet. Open tabs, then use Save workspace."));
    return panel;
  }
  const list = make("div", "workspace-saved-workspaces-list");
  for (const workspace of savedWorkspaces) {
    const row = make("article", "workspace-saved-workspace");
    const copy = make("div", "workspace-saved-workspace-copy");
    const title = make("strong", "workspace-saved-workspace-name", workspace.name);
    title.title = workspace.name;
    const detail = [
      formatDate(workspace.savedAt),
      `${workspace.tabCount || 0} tab${workspace.tabCount === 1 ? "" : "s"}`,
      workspace.groupCount ? `${workspace.groupCount} group${workspace.groupCount === 1 ? "" : "s"}` : "",
      Array.isArray(workspace.cwds) && workspace.cwds.length ? normalizeDisplayPath(workspace.cwds[0]) : "",
    ].filter(Boolean).join(" · ");
    copy.append(title, make("span", "workspace-saved-workspace-detail", detail));
    const actions = make("div", "workspace-saved-workspace-actions");
    const load = make("button", "workspace-saved-workspace-load primary", "Load");
    load.type = "button";
    load.setAttribute("aria-label", `Load workspace ${workspace.name}`);
    load.addEventListener("click", () => loadWebuiWorkspace(workspace.id, { triggerButton: load }));
    const remove = make("button", "workspace-saved-workspace-delete", "Delete");
    remove.type = "button";
    remove.setAttribute("aria-label", `Delete workspace ${workspace.name}`);
    remove.addEventListener("click", () => deleteWebuiWorkspace(workspace));
    actions.append(load, remove);
    row.append(copy, actions);
    list.append(row);
  }
  panel.append(list);
  return panel;
}

function setFooterModelPickerOpen(open, { restoreFocus = false } = {}) {
  const wasOpen = footerModelPickerOpen;
  footerModelPickerOpen = !!open;
  if (footerModelPickerOpen) {
    footerThinkingPickerOpen = false;
    footerBranchPickerOpen = false;
    footerBranchPickerRequestSerial += 1;
  }
  if (footerModelPickerOpen && isMobileView()) {
    mobileFooterExpanded = false;
    document.body.classList.remove("footer-details-expanded");
    setComposerActionsOpen(false);
    setMobileTabsExpanded(false);
  }
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
  renderFooter();
  updateFooterModelPickerPosition();
  if (footerModelPickerOpen && footerScopedModelLayout === "advanced") focusFooterModelPickerInitialOption();
  if (wasOpen && !footerModelPickerOpen) {
    scheduleDeferredUiFlushAfterDropdownClose();
    if (restoreFocus) focusFooterModelTrigger();
  }
}

function setFooterThinkingPickerOpen(open) {
  const wasOpen = footerThinkingPickerOpen;
  footerThinkingPickerOpen = !!open;
  if (footerThinkingPickerOpen) {
    footerModelPickerOpen = false;
    footerBranchPickerOpen = false;
    footerBranchPickerRequestSerial += 1;
  }
  if (footerThinkingPickerOpen && isMobileView()) {
    mobileFooterExpanded = false;
    document.body.classList.remove("footer-details-expanded");
    setComposerActionsOpen(false);
    setMobileTabsExpanded(false);
  }
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
  renderFooter();
  updateFooterModelPickerPosition();
  if (wasOpen && !footerThinkingPickerOpen) scheduleDeferredUiFlushAfterDropdownClose();
}

function footerGitBranchKey(item = {}) {
  // Remote-only rows stay distinct per exact remote ref so same-named branches
  // from different remotes never collapse into a single row.
  return item.remote ? `remote:${item.remoteRef}` : `local:${item.name}`;
}

function footerBranchOptionLabel(branch = {}) {
  return cleanStatusText(branch.displayName) || cleanStatusText(branch.name);
}

function normalizeFooterGitBranches(data = {}) {
  const current = cleanStatusText(data.current || data.currentBranch || "");
  const rawBranches = Array.isArray(data.branches) ? data.branches : [];
  const localNames = new Set(
    rawBranches
      .filter((item) => typeof item === "string" || item?.remote !== true)
      .map((item) => cleanStatusText(typeof item === "string" ? item : item?.name))
      .filter(Boolean),
  );
  const seen = new Set();
  const branches = [];
  for (const item of rawBranches) {
    const name = cleanStatusText(typeof item === "string" ? item : item?.name);
    if (!name) continue;
    const remoteRef = cleanFooterPayloadText(item?.remoteRef, "", 4000);
    const remote = item?.remote === true;
    // Never downgrade a remote record without an exact ref into a local row: the
    // browser must not infer a Git command from display text alone.
    if (remote && !remoteRef) continue;
    // A local branch always represents the local name; remote rows for that
    // same name stay hidden until they are materialized locally.
    if (remote && localNames.has(name)) continue;
    const branch = {
      name,
      remote,
      remoteRef: remote ? remoteRef : "",
      remoteName: remote ? cleanStatusText(item?.remoteName) : "",
      displayName: remote ? cleanFooterPayloadText(item?.displayName, remoteRef, 4000) : name,
      current: !remote && (Boolean(item?.current) || (!!current && name === current)),
      occupied: !remote && Boolean(item?.occupied),
      worktreePath: remote ? "" : cleanFooterPayloadText(item?.worktreePath, "", 4000),
      worktreeCurrent: !remote && Boolean(item?.worktreeCurrent),
      mainWorktree: !remote && Boolean(item?.mainWorktree),
    };
    const key = footerGitBranchKey(branch);
    if (seen.has(key)) continue;
    seen.add(key);
    branches.push({ key, ...branch });
  }
  const worktrees = (Array.isArray(data.worktrees) ? data.worktrees : [])
    .map((item) => ({
      path: cleanFooterPayloadText(item?.path, "", 4000),
      branch: cleanStatusText(item?.branch || ""),
      current: Boolean(item?.current),
      isMainWorktree: Boolean(item?.isMainWorktree),
      prunable: Boolean(item?.prunable),
      locked: Boolean(item?.locked),
    }))
    .filter((item) => item.path);
  const occupiedBranches = (Array.isArray(data.occupiedBranches) ? data.occupiedBranches : [])
    .map((item) => ({
      branch: cleanStatusText(item?.branch || ""),
      path: cleanFooterPayloadText(item?.path, "", 4000),
      current: Boolean(item?.current),
      isMainWorktree: Boolean(item?.isMainWorktree),
    }))
    .filter((item) => item.branch && item.path);
  return {
    root: cleanFooterPayloadText(data.root || data.currentWorktreePath, "", 4000),
    repoRoot: cleanFooterPayloadText(data.repoRoot || data.root, "", 4000),
    commonGitDir: cleanFooterPayloadText(data.commonGitDir, "", 4000),
    currentWorktreePath: cleanFooterPayloadText(data.currentWorktreePath || data.root, "", 4000),
    defaultWorktreesRoot: cleanFooterPayloadText(data.defaultWorktreesRoot, "", 4000),
    current,
    branches,
    worktrees,
    occupiedBranches,
  };
}

function applyOptimisticGitFooterBranch(branch, tabContext = activeTabContext()) {
  const nextBranch = cleanStatusText(branch);
  if (!nextBranch) return;
  const raw = statusEntries.get(GIT_FOOTER_WEBUI_STATUS_KEY) || readCachedGitFooterWebuiPayloadRaw();
  const payload = parseGitFooterWebuiPayloadRaw(raw);
  if (!payload) return;
  const nextPayload = {
    type: GIT_FOOTER_WEBUI_PAYLOAD_TYPE,
    version: GIT_FOOTER_WEBUI_PAYLOAD_VERSION,
    generatedAt: Date.now(),
    ...(payload.providerUsage ? { providerUsage: payload.providerUsage } : {}),
    main: payload.main,
    meta: payload.meta.map((chip) => chip.key === "git" ? { ...chip, value: nextBranch, title: `git branch: ${nextBranch}` } : chip),
    visibility: payload.visibility,
  };
  const nextRaw = JSON.stringify(nextPayload);
  statusEntries.set(GIT_FOOTER_WEBUI_STATUS_KEY, nextRaw);
  cacheGitFooterWebuiPayload(nextRaw, tabContext.tabId);
}

async function loadFooterBranchPicker(tabContext = activeTabContext()) {
  const requestSerial = ++footerBranchPickerRequestSerial;
  const tabId = tabContext.tabId || activeTabId;
  const preserveState = footerBranchPickerState.tabId === tabId ? footerBranchPickerState : {};
  footerBranchPickerState = {
    loading: true,
    error: "",
    branches: preserveState.branches || [],
    current: preserveState.current || "",
    root: preserveState.root || "",
    repoRoot: preserveState.repoRoot || "",
    commonGitDir: preserveState.commonGitDir || "",
    currentWorktreePath: preserveState.currentWorktreePath || "",
    defaultWorktreesRoot: preserveState.defaultWorktreesRoot || "",
    worktrees: preserveState.worktrees || [],
    occupiedBranches: preserveState.occupiedBranches || [],
    switching: "",
    switchingKey: "",
    tabId,
  };
  if (isCurrentTabContext(tabContext)) {
    renderFooter();
    updateFooterModelPickerPosition();
  }
  try {
    const response = await api("/api/git-branches", { tabId });
    if (requestSerial !== footerBranchPickerRequestSerial || !footerBranchPickerOpen || !isCurrentTabContext(tabContext)) return;
    if (!response.ok) throw new Error(response.error || "Failed to load git branches");
    footerBranchPickerState = { loading: false, error: "", switching: "", switchingKey: "", tabId, ...normalizeFooterGitBranches(response.data || {}) };
  } catch (error) {
    if (requestSerial !== footerBranchPickerRequestSerial || !footerBranchPickerOpen || !isCurrentTabContext(tabContext)) return;
    footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "", error: error.message || String(error) };
  }
  if (isCurrentTabContext(tabContext)) {
    renderFooter();
    updateFooterModelPickerPosition();
  }
}

function setFooterBranchPickerOpen(open) {
  const wasOpen = footerBranchPickerOpen;
  footerBranchPickerOpen = !!open;
  if (footerBranchPickerOpen) {
    footerModelPickerOpen = false;
    footerThinkingPickerOpen = false;
    if (isMobileView()) {
      mobileFooterExpanded = false;
      document.body.classList.remove("footer-details-expanded");
      setComposerActionsOpen(false);
      setMobileTabsExpanded(false);
    }
    loadFooterBranchPicker(activeTabContext()).catch((error) => addEvent(error.message || String(error), "error"));
  } else {
    footerBranchPickerRequestSerial += 1;
  }
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
  renderFooter();
  updateFooterModelPickerPosition();
  if (wasOpen && !footerBranchPickerOpen) scheduleDeferredUiFlushAfterDropdownClose();
}

function pathLooksInside(parentPath, childPath) {
  const normalizePath = (value) => String(value || "").replace(/\\+/g, "/").replace(/\/+$/, "");
  const parent = normalizePath(parentPath);
  const child = normalizePath(childPath);
  return !!parent && !!child && (child === parent || child.startsWith(`${parent}/`));
}

function footerBranchActiveAgentTabs(tabContext = activeTabContext()) {
  const active = activeTab();
  const activeCwd = latestWorkspace?.cwd || active?.cwd || "";
  const root = footerBranchPickerState.root || "";
  return tabs.filter((tab) => {
    const sameWorktree = root ? pathLooksInside(root, tab.cwd) : !!activeCwd && tab.cwd === activeCwd;
    if (!sameWorktree) return false;
    if (tab.id === tabContext.tabId) return currentState?.isStreaming || currentState?.isCompacting || tabHasActiveAgent(tab);
    return tabHasActiveAgent(tab);
  });
}

function footerBranchAgentWarningLines(tabContext = activeTabContext()) {
  const busyTabs = footerBranchActiveAgentTabs(tabContext);
  if (!busyTabs.length) return [];
  const list = busyTabs.slice(0, 4).map((tab) => `- ${tab.title || tab.id}`).join("\n");
  const extra = busyTabs.length > 4 ? `\n- … +${busyTabs.length - 4} more` : "";
  return [
    "",
    `WARNING: ${busyTabs.length === 1 ? "An agent is" : "Agents are"} still running or waiting for input in this Git working tree:`,
    `${list}${extra}`,
    "Switching branches can change files underneath the running agent.",
  ];
}

function footerBranchDirtySummaryLines() {
  const changesChip = parseGitFooterWebuiPayload()?.meta?.find((chip) => chip.key === "changes");
  const files = Array.isArray(changesChip?.files) ? changesChip.files : [];
  if (!files.length) return [];
  const counts = {};
  for (const file of files) counts[file.kind] = (counts[file.kind] || 0) + 1;
  const parts = FOOTER_CHANGED_FILE_KIND_ORDER
    .filter((kind) => counts[kind])
    .map((kind) => `${counts[kind]} ${FOOTER_CHANGED_FILE_KIND_LABELS[kind]?.toLowerCase() || kind}`);
  const total = changesChip?.filesTruncated && changesChip?.filesTotal ? changesChip.filesTotal : files.length;
  return [
    `Dirty working tree: ${total} changed file${total === 1 ? "" : "s"} (${parts.join(", ")}).`,
    "Switching branches carries these changes along; consider a worktree instead.",
  ];
}

async function confirmFooterGitBranchAction(branch, { create = false, requireConfirm = false, tabContext = activeTabContext(), remoteRef = "" } = {}) {
  const branchName = cleanStatusText(branch);
  const trackedRemoteRef = cleanStatusText(remoteRef);
  const warningLines = footerBranchAgentWarningLines(tabContext);
  const dirtyLines = footerBranchDirtySummaryLines();
  if (!requireConfirm && warningLines.length === 0 && dirtyLines.length === 0) return true;
  const action = trackedRemoteRef ? "Create local tracking branch and switch to it" : create ? "Create and switch to new git branch" : "Switch git branch";
  const message = [
    `${action}: ${branchName}?`,
    "",
    `Repository: ${footerBranchPickerState.root || currentGitFooterCacheCwd(tabContext.tabId) || "current tab"}`,
    ...(trackedRemoteRef ? [`Remote ref: ${trackedRemoteRef}`, `Command: git switch --track -c ${branchName} ${trackedRemoteRef}`] : []),
    ...dirtyLines,
    ...warningLines,
    "",
    "Continue?",
  ].join("\n");
  return appConfirmText(message, { affected: branchName || "the current branch", confirmLabel: trackedRemoteRef ? "Create tracking branch" : create ? "Create branch" : "Switch branch" });
}

async function confirmFooterGitWorktreeAction(branch, { path = "", create = false, requireConfirm = false, remoteRef = "" } = {}) {
  const branchName = cleanStatusText(branch);
  if (!requireConfirm) return true;
  const trackedRemoteRef = cleanStatusText(remoteRef);
  const targetPath = cleanFooterPayloadText(path, "", 4000);
  const message = [
    `${create ? "Create" : "Open"} branch worktree: ${branchName || targetPath}?`,
    "",
    `Repository: ${footerBranchPickerState.repoRoot || footerBranchPickerState.root || currentGitFooterCacheCwd() || "current tab"}`,
    ...(trackedRemoteRef ? [`Remote ref: ${trackedRemoteRef}`, `Creates local branch ${branchName} tracking ${trackedRemoteRef}.`] : []),
    targetPath ? `Worktree: ${targetPath}` : `Default location: ${footerBranchPickerState.defaultWorktreesRoot || "repo sibling .worktrees directory"}`,
    "",
    "This creates a separate checkout without changing this tab's branch.",
    "After creation, you can choose whether to open it in a separate Pi tab and switch to it.",
    "Ignored dependencies such as node_modules or .venv are not copied; bootstrap them manually if needed.",
    "",
    "Continue?",
  ].join("\n");
  return appConfirmText(message, { affected: targetPath || branchName, confirmLabel: create ? "Create worktree" : "Open worktree", danger: false });
}

function footerBranchCreateType(value = footerBranchCreateDraft.type) {
  return slugifyGitBranchPart(value);
}

function slugifyGitBranchName(value) {
  return cleanStatusText(value)
    .split("/")
    .map((part) => slugifyGitBranchPart(part))
    .filter(Boolean)
    .join("/");
}

function footerBranchCreateName() {
  const type = footerBranchCreateType();
  const rawName = cleanStatusText(footerBranchCreateDraft.name);
  if (!type || !rawName) return "";
  return slugifyGitBranchName(`${type}/${rawName}`);
}

function footerBranchCreatePreviewName() {
  const type = footerBranchCreateType() || "<type>";
  const rawName = cleanStatusText(footerBranchCreateDraft.name);
  const name = rawName ? slugifyGitBranchName(rawName) : "<branch-name>";
  return `${type}/${name}`;
}

function updateFooterBranchCreateDraft(patch = {}) {
  const has = (key) => Object.prototype.hasOwnProperty.call(patch, key);
  footerBranchCreateDraft = {
    type: has("type") ? footerBranchCreateType(patch.type) : footerBranchCreateType(),
    name: has("name") ? String(patch.name || "") : footerBranchCreateDraft.name,
  };
}

function quoteGitBranchForDisplay(branch) {
  return `'${String(branch || "").replace(/'/g, `'\\''`)}'`;
}

function gitSwitchCreateCommandDisplay(branch) {
  return `git switch -c ${quoteGitBranchForDisplay(branch)}`;
}

function slugifyWorktreePathPart(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "-")
    .replace(/[-.]{2,}/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 96) || "branch";
}

function footerBranchCreateWorktreePathPreview(branch = footerBranchCreateName(), state = footerBranchPickerState) {
  const root = state.defaultWorktreesRoot || "<repo>.worktrees";
  return `${root.replace(/\/+$/, "")}/${slugifyWorktreePathPart(branch || footerBranchCreatePreviewName())}`;
}

function gitWorktreeCreateCommandDisplay(branch, state = footerBranchPickerState, baseRef = "origin/main") {
  return `git worktree add -b ${quoteGitBranchForDisplay(branch)} ${quoteGitBranchForDisplay(footerBranchCreateWorktreePathPreview(branch, state))} ${quoteGitBranchForDisplay(baseRef)}`;
}

function gitWorktreeOpenCommandDisplay(path) {
  return `pi-webui --cwd ${quoteGitBranchForDisplay(path || "<worktree-path>")}`;
}

function footerBranchCreateTooltip(branchName = footerBranchCreateName(), state = footerBranchPickerState) {
  const command = gitWorktreeCreateCommandDisplay(branchName || footerBranchCreatePreviewName(), state);
  return [
    "Create branch worktree",
    "A branch worktree is a separate checkout for parallel changes.",
    "",
    `This will run roughly: ${command}`,
    "",
    "What happens:",
    "• asks whether to base the new branch on origin/main (default) or this workspace's current HEAD",
    "• creates the worktree, then asks whether to open and switch to it in a separate Pi tab",
    "• does not switch this tab's branch, commit, push, or delete anything",
    "",
    "Tip: ignored dependencies such as node_modules or .venv are not copied.",
  ].join("\n");
}

async function createFooterGitBranch(branch = footerBranchCreateName()) {
  const branchName = cleanStatusText(branch);
  if (!branchName) {
    addEvent("Enter a branch name before creating a new git branch.", "warn");
    return;
  }
  const tabContext = activeTabContext();
  if (!(await confirmFooterGitBranchAction(branchName, { create: true, requireConfirm: true, tabContext }))) return;
  await applyFooterGitBranch(branchName, { create: true, tabContext, skipConfirm: true });
}

async function openWorktreeResponseTab(response, { branchName = "", action = "open", announce = true } = {}) {
  if (!response.ok) throw new Error(response.error || `Failed to ${action} branch worktree`);
  const payload = response.data || {};
  if (Array.isArray(payload.tabs)) {
    tabs = payload.tabs;
    syncTabMetadata(tabs);
  }
  if (payload.tab) applyTabMetadata(payload.tab);
  footerBranchPickerOpen = false;
  footerBranchPickerRequestSerial += 1;
  footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "" };
  renderTabs();
  const targetTab = payload.tab;
  if (targetTab?.id) await switchTab(targetTab.id);
  const branch = cleanStatusText(payload.worktree?.branch || payload.branch || branchName || targetTab?.gitWorkspace?.branch || "");
  const where = payload.worktree?.path || payload.path || targetTab?.cwd || "worktree";
  const prefix = payload.created ? "Created" : payload.openedExisting || payload.openedExistingTab ? "Opened existing" : "Opened";
  if (announce) addEvent(`${prefix} branch worktree${branch ? ` ${branch}` : ""} at ${normalizeDisplayPath(where)}.`, "success");
  if (payload.session?.warning) addEvent(payload.session.warning, "warn");
  if (payload.dependencyHint) addEvent(payload.dependencyHint, "info");
  requestGitFooterWebuiPayload(activeTabContext(), { force: true });
}

async function confirmSwitchToCreatedFooterGitWorktree(payload = {}, branchName = "") {
  if (payload.created !== true) return false;
  const branch = cleanStatusText(payload.worktree?.branch || payload.branch || branchName);
  const worktreePath = cleanFooterPayloadText(payload.worktree?.path || payload.path, "", 4000);
  if (!worktreePath) return false;
  return appConfirm({
    title: "Switch to new worktree?",
    summary: `The${branch ? ` ${branch}` : ""} worktree was created. Open it in a separate Pi tab and switch to it now? The worktree remains available if you stay here.`,
    affected: normalizeDisplayPath(worktreePath),
    undoable: true,
    confirmLabel: "Switch to worktree",
    danger: false,
  });
}

async function createFooterGitBranchWorktree(branch = footerBranchCreateName(), { tabContext = activeTabContext(), skipConfirm = false, chooseBase = true, remoteRef = "", switchingLabel = "", switchingKey = "" } = {}) {
  const branchName = cleanStatusText(branch);
  if (!branchName) {
    addEvent("Enter a branch name before creating a branch worktree.", "warn");
    return;
  }
  const trackedRemoteRef = cleanFooterPayloadText(remoteRef, "", 4000);
  if (!skipConfirm && !(await confirmFooterGitWorktreeAction(branchName, { create: true, requireConfirm: true, remoteRef: trackedRemoteRef }))) return;
  const baseRef = trackedRemoteRef ? "" : chooseBase ? await chooseGitWorktreeBase(branchName) : "HEAD";
  if (baseRef === null) return;
  const tabId = tabContext.tabId || activeTabId;
  try {
    footerBranchPickerState = { ...footerBranchPickerState, loading: true, error: "", switching: switchingLabel || branchName, switchingKey, tabId };
    renderFooter();
    // Remote-only creation submits the exact advertised remote ref instead of a
    // base ref; the server re-verifies it and creates a local tracking branch.
    const response = trackedRemoteRef
      ? await api("/api/git-worktrees", { method: "POST", body: { branchName, remoteRef: trackedRemoteRef, sessionMode: "fork-current", openTab: false }, tabId })
      : await api("/api/git-worktrees", { method: "POST", body: { branchName, baseRef, sessionMode: "fork-current", openTab: false }, tabId });
    if (!response.ok) throw new Error(response.error || "Failed to create branch worktree");
    const payload = response.data || {};
    const worktreePath = cleanFooterPayloadText(payload.worktree?.path || payload.path, "", 4000);
    if (!worktreePath) throw new Error("Git worktree creation did not return a path");
    if (payload.created) {
      await openWorktreeResponseTab(response, { branchName, action: "create" });
      if (await confirmSwitchToCreatedFooterGitWorktree(payload, branchName)) {
        await openFooterGitWorktree(worktreePath, { branchName, tabContext, skipConfirm: true, announce: false });
      }
    } else {
      await openFooterGitWorktree(worktreePath, { branchName, tabContext, skipConfirm: true });
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "", error: error.message || String(error) };
      renderFooter();
      updateFooterModelPickerPosition();
    }
    addEvent(error.message || String(error), "error");
  }
}

async function openFooterGitWorktree(path, { branchName = "", tabContext = activeTabContext(), skipConfirm = false, switchingKey = "", announce = true } = {}) {
  const worktreePath = cleanFooterPayloadText(path, "", 4000);
  if (!worktreePath) return;
  if (!skipConfirm && !(await confirmFooterGitWorktreeAction(branchName, { path: worktreePath, requireConfirm: false }))) return;
  const tabId = tabContext.tabId || activeTabId;
  try {
    footerBranchPickerState = { ...footerBranchPickerState, loading: true, error: "", switching: branchName || worktreePath, switchingKey, tabId };
    renderFooter();
    const response = await api("/api/git-worktrees/open", { method: "POST", body: { path: worktreePath, sessionMode: "fork-current", openTab: true }, tabId });
    await openWorktreeResponseTab(response, { branchName, action: "open", announce });
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "", error: error.message || String(error) };
      renderFooter();
      updateFooterModelPickerPosition();
    }
    addEvent(error.message || String(error), "error");
  }
}

async function applyFooterGitBranch(branch, { create = false, tabContext = activeTabContext(), skipConfirm = false, remoteRef = "", switchingLabel = "", switchingKey = "" } = {}) {
  const branchName = cleanStatusText(branch);
  if (!branchName) return;
  const tabId = tabContext.tabId || activeTabId;
  const trackedRemoteRef = cleanFooterPayloadText(remoteRef, "", 4000);
  if (!skipConfirm && !(await confirmFooterGitBranchAction(branchName, { create, tabContext, remoteRef: trackedRemoteRef }))) return;
  try {
    footerBranchPickerState = { ...footerBranchPickerState, loading: true, error: "", switching: switchingLabel || branchName, switchingKey, tabId };
    renderFooter();
    // Remote-only switching sends the exact remote ref plus the intended local
    // branch; the server creates a tracking branch instead of detaching HEAD.
    const response = trackedRemoteRef
      ? await api("/api/git-branch", { method: "POST", body: { branch: branchName, create, remoteRef: trackedRemoteRef }, tabId })
      : await api("/api/git-branch", { method: "POST", body: { branch: branchName, create }, tabId });
    if (!isCurrentTabContext(tabContext)) return;
    if (!response.ok) throw new Error(response.error || (trackedRemoteRef ? `Failed to create local branch ${branchName} tracking ${trackedRemoteRef}` : `Failed to ${create ? "create and switch to" : "switch to"} ${branchName}`));
    const switchedBranch = cleanStatusText(response.data?.branch || branchName);
    footerBranchPickerOpen = false;
    footerBranchPickerRequestSerial += 1;
    footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "", current: switchedBranch };
    if (create) updateFooterBranchCreateDraft({ name: "" });
    applyOptimisticGitFooterBranch(switchedBranch, tabContext);
    addEvent(trackedRemoteRef ? `Created local branch ${switchedBranch} tracking ${trackedRemoteRef} and switched this checkout.` : response.data?.created ? `Created and switched to git branch ${switchedBranch}.` : response.data?.switched === false ? `Already on git branch ${switchedBranch}.` : `Switched git branch to ${switchedBranch}.`, "info");
    requestGitFooterWebuiPayload(tabContext, { force: true });
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      footerBranchPickerState = { ...footerBranchPickerState, loading: false, switching: "", switchingKey: "", error: error.message || String(error) };
      addEvent(error.message || String(error), "error");
    }
  } finally {
    if (isCurrentTabContext(tabContext)) {
      document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
      renderFooter();
      updateFooterModelPickerPosition();
    }
  }
}

function renderFooterBranchCreateForm(state = footerBranchPickerState) {
  const form = make("form", "footer-branch-create-form");
  form.setAttribute("aria-label", "Create branch worktree");

  const header = make("div", "footer-branch-create-header");
  header.append(make("strong", "footer-branch-create-title", "Create branch worktree"));

  const fields = make("div", "footer-branch-create-fields");
  const typeField = make("div", "footer-branch-create-type-field");
  const typeInput = make("input", "footer-branch-create-dropdown-inputfield");
  typeInput.id = "footerBranchCreateType";
  typeInput.type = "text";
  typeInput.value = footerBranchCreateType();
  typeInput.placeholder = "type";
  typeInput.setAttribute("aria-label", "Branch type suggestion or custom prefix");
  typeInput.setAttribute("aria-haspopup", "listbox");
  typeInput.autocomplete = "off";
  typeInput.autocapitalize = "none";
  typeInput.spellcheck = false;

  const typeSuggestions = make("div", "footer-branch-type-suggestions");
  typeSuggestions.setAttribute("role", "listbox");
  typeSuggestions.hidden = true;
  const renderTypeSuggestions = () => {
    const filter = slugifyGitBranchPart(typeInput.value);
    const matches = GIT_BRANCH_TYPE_SUGGESTIONS.filter((type) => !filter || type.includes(filter));
    const shown = matches.length ? matches : GIT_BRANCH_TYPE_SUGGESTIONS;
    typeSuggestions.replaceChildren(...shown.map((type) => {
      const button = make("button", `footer-branch-type-suggestion${footerBranchCreateType(typeInput.value) === type ? " active" : ""}`, type);
      button.type = "button";
      button.setAttribute("role", "option");
      button.setAttribute("aria-selected", footerBranchCreateType(typeInput.value) === type ? "true" : "false");
      button.addEventListener("pointerdown", (event) => event.preventDefault());
      button.addEventListener("click", () => {
        typeInput.value = type;
        updateFooterBranchCreateDraft({ type });
        updatePreview();
        typeSuggestions.hidden = true;
        nameInput.focus();
      });
      return button;
    }));
  };

  const slash = make("span", "footer-branch-create-slash", "/");

  const nameInput = make("input", "footer-branch-create-input-field");
  nameInput.id = "footerBranchCreateName";
  nameInput.type = "text";
  nameInput.value = footerBranchCreateDraft.name;
  nameInput.placeholder = "short-feature-name";
  nameInput.autocomplete = "off";
  nameInput.autocapitalize = "none";
  nameInput.spellcheck = false;
  nameInput.setAttribute("aria-label", "New branch name");

  const submitButton = make("button", "footer-branch-create-submit", state.switching ? "Opening…" : "Open worktree tab");
  submitButton.type = "submit";

  const preview = make("div", "footer-branch-create-preview");
  const updatePreview = () => {
    const branchName = footerBranchCreateName();
    preview.textContent = gitWorktreeCreateCommandDisplay(branchName || footerBranchCreatePreviewName(), state);
    const submitDisabled = Boolean(state.switching) || !branchName;
    submitButton.disabled = false;
    submitButton.classList.toggle("footer-branch-create-submit-disabled", submitDisabled);
    submitButton.setAttribute("aria-disabled", submitDisabled ? "true" : "false");
    submitButton.dataset.tooltip = footerBranchCreateTooltip(branchName);
    submitButton.setAttribute("aria-label", branchName ? `Create and open branch worktree ${branchName}` : "Create branch worktree: enter both a branch type and name first");
    submitButton.removeAttribute("title");
  };

  typeInput.addEventListener("focus", () => {
    renderTypeSuggestions();
    typeSuggestions.hidden = false;
  });
  typeInput.addEventListener("blur", () => {
    setTimeout(() => { typeSuggestions.hidden = true; }, 120);
  });
  typeInput.addEventListener("input", () => {
    updateFooterBranchCreateDraft({ type: typeInput.value });
    updatePreview();
    renderTypeSuggestions();
    typeSuggestions.hidden = false;
  });
  typeInput.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      typeSuggestions.hidden = true;
      return;
    }
    if (event.key !== "/" && event.key !== "Enter") return;
    event.preventDefault();
    typeSuggestions.hidden = true;
    nameInput.focus();
    nameInput.select();
  });
  nameInput.addEventListener("input", () => {
    updateFooterBranchCreateDraft({ name: nameInput.value });
    updatePreview();
  });
  nameInput.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    form.requestSubmit();
  });
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (state.switching) return;
    const branchName = footerBranchCreateName();
    createFooterGitBranchWorktree(branchName).catch((error) => addEvent(error.message || String(error), "error"));
  });

  updatePreview();
  renderTypeSuggestions();
  typeField.append(typeInput, typeSuggestions);
  fields.append(typeField, slash, nameInput, submitButton);
  form.append(header, fields, preview);
  return form;
}

function footerBranchWorktreePath(branch, state = footerBranchPickerState) {
  // Remote-only rows have no checkout yet and must never inherit the worktree
  // of an unrelated same-named local branch.
  if (branch?.remote) return "";
  const direct = cleanFooterPayloadText(branch?.worktreePath, "", 4000);
  if (direct) return direct;
  return cleanFooterPayloadText(state.occupiedBranches?.find((item) => item.branch === branch?.name)?.path, "", 4000);
}

function footerBranchOptionDetail(branch, state, { selected, worktreePath } = {}) {
  if (state.switchingKey ? state.switchingKey === branch.key : state.switching === footerBranchOptionLabel(branch)) return "opening…";
  if (selected) return branch.worktreeCurrent ? "current branch in this worktree" : "current branch";
  if (branch.remote) return `remote-only · creates local branch ${branch.name} tracking ${branch.remoteRef}`;
  if (worktreePath) return branch.mainWorktree ? "checked out in main worktree · open tab" : "checked out in another worktree · open tab";
  return "open branch in a new worktree tab";
}

function openFooterBranchOption(branch, state = footerBranchPickerState) {
  if (branch.remote) return createFooterGitBranchWorktree(branch.name, { skipConfirm: true, chooseBase: false, remoteRef: branch.remoteRef, switchingLabel: footerBranchOptionLabel(branch), switchingKey: branch.key });
  const worktreePath = footerBranchWorktreePath(branch, state);
  if (worktreePath && !branch.worktreeCurrent) return openFooterGitWorktree(worktreePath, { branchName: branch.name, skipConfirm: true, switchingKey: branch.key });
  return createFooterGitBranchWorktree(branch.name, { skipConfirm: true, chooseBase: false, switchingKey: branch.key });
}

function footerBranchSwitchAvailability(branch = {}, state = {}, worktreePath = "") {
  if (state.switching) {
    return {
      disabled: true,
      label: "Action running…",
      reason: `Cannot switch this checkout while the branch action for ${state.switching} is still running.`,
    };
  }
  if (state.loading) {
    return {
      disabled: true,
      label: "Refreshing…",
      reason: "Cannot switch this checkout until the latest branch and worktree information finishes loading.",
    };
  }
  if (worktreePath) {
    const location = branch.mainWorktree ? "the main worktree" : "another worktree";
    return {
      disabled: true,
      label: branch.mainWorktree ? "In main worktree" : "In another worktree",
      reason: `Cannot switch this checkout because ${branch.name} is already checked out in ${location} at ${worktreePath}. Open that worktree instead.`,
    };
  }
  return { disabled: false, label: "Switch here", reason: "" };
}

function renderFooterBranchOption(branch, state = footerBranchPickerState) {
  const selected = !branch.remote && (branch.current || (!!state.current && branch.name === state.current));
  const worktreePath = footerBranchWorktreePath(branch, state);
  const busy = state.loading || !!state.switching;
  const primaryDisabled = busy || selected;
  const row = make("div", `footer-branch-option-row${selected ? " active" : ""}${branch.remote ? " remote-only" : ""}${worktreePath && !branch.worktreeCurrent ? " worktree-occupied" : ""}`);
  row.setAttribute("role", "option");
  row.setAttribute("aria-selected", selected ? "true" : "false");

  const primary = make("button", "footer-model-option footer-branch-option footer-branch-primary-action");
  primary.type = "button";
  primary.disabled = primaryDisabled;
  primary.title = selected
    ? `Current branch: ${branch.name}`
    : branch.remote
      ? `Remote-only branch ${branch.remoteRef}: create local branch ${branch.name} tracking it and open a new Git worktree tab`
      : worktreePath ? `Open existing worktree: ${worktreePath}` : `Open ${branch.name} in a new Git worktree tab`;
  primary.append(
    make("span", "footer-model-option-main", footerBranchOptionLabel(branch)),
    make("span", "footer-model-option-name", footerBranchOptionDetail(branch, state, { selected, worktreePath })),
  );
  if (!primaryDisabled) primary.addEventListener("click", () => openFooterBranchOption(branch, state));
  row.append(primary);

  if (!selected) {
    const availability = footerBranchSwitchAvailability(branch, state, worktreePath);
    const advanced = make("button", "footer-branch-advanced-action", availability.label);
    advanced.type = "button";
    advanced.disabled = availability.disabled;
    advanced.title = availability.reason || (branch.remote
      ? `Advanced: git switch --track -c ${branch.name} ${branch.remoteRef} in this checkout`
      : `Advanced: git switch ${branch.name} in this checkout`);
    if (availability.reason) {
      advanced.dataset.disabledReason = availability.reason;
      advanced.setAttribute("aria-label", `${availability.label}. ${availability.reason}`);
    } else {
      advanced.addEventListener("click", () => branch.remote
        ? applyFooterGitBranch(branch.name, { remoteRef: branch.remoteRef, switchingLabel: footerBranchOptionLabel(branch), switchingKey: branch.key })
        : applyFooterGitBranch(branch.name, { switchingKey: branch.key }));
    }
    row.append(advanced);
  }
  return row;
}

async function removeFooterGitWorktree(worktree, tabContext = activeTabContext()) {
  const tabId = tabContext.tabId || activeTabId;
  if (!(await appConfirmText([
    `Remove worktree ${worktree.path}?`,
    "",
    `Branch: ${worktree.branch || "detached"}`,
    "Command: git worktree remove",
    "This deletes the checkout directory. Dirty worktrees and worktrees with open tabs are refused.",
  ].join("\n"), { affected: worktree.path, confirmLabel: "Remove worktree" }))) return;
  footerBranchPickerState = { ...footerBranchPickerState, loading: true, error: "" };
  renderFooter();
  try {
    const response = await api("/api/git-worktrees", { method: "DELETE", body: { path: worktree.path, confirmed: true }, tabId });
    if (!response.ok) throw new Error(response.error || "Failed to remove the worktree");
    addEvent(`Removed worktree ${worktree.path}.`, "success");
  } catch (error) {
    addEvent(error.message || String(error), "error");
  }
  await loadFooterBranchPicker(tabContext).catch(() => {});
}

async function pruneFooterGitWorktrees(tabContext = activeTabContext()) {
  const tabId = tabContext.tabId || activeTabId;
  try {
    const preview = await api("/api/git-worktrees/prune", { tabId });
    const previewData = preview?.data || {};
    const prunable = previewData.prunable || [];
    const output = String(previewData.output || "").trim();
    if (!prunable.length && !output) {
      addEvent("No stale worktree records to prune.", "info");
      return;
    }
    const lines = prunable.map((item) => `${item.path}${item.reason ? ` (${item.reason})` : ""}`).join("\n");
    if (!(await appConfirmText(`Prune stale worktree records?\n\nDry run:\n${output || lines || "(no output)"}\n\nThis removes administrative records for worktree directories that no longer exist.`, { affected: "Stale Git worktree administration records", confirmLabel: "Prune records" }))) return;
    const response = await api("/api/git-worktrees/prune", { method: "POST", body: { confirmed: true }, tabId });
    if (!response.ok) throw new Error(response.error || "Failed to prune worktrees");
    addEvent("Pruned stale worktree records.", "success");
  } catch (error) {
    addEvent(error.message || String(error), "error");
  }
  await loadFooterBranchPicker(tabContext).catch(() => {});
}

function renderFooterWorktreeList(state = footerBranchPickerState) {
  const allWorktrees = (state.worktrees || []).filter((item) => item.path);
  const worktrees = allWorktrees.filter((item) => !item.prunable);
  const prunableCount = allWorktrees.length - worktrees.length;
  if (worktrees.length <= 1 && prunableCount === 0) return null;
  const busy = state.loading || !!state.switching;
  const section = make("div", "footer-branch-worktree-section");
  section.append(make("div", "footer-branch-section-title", `Open worktrees (${worktrees.length})`));
  for (const worktree of worktrees.slice(0, 8)) {
    const selected = worktree.current || worktree.path === state.currentWorktreePath;
    const row = make("div", "footer-branch-option-row");
    const button = make("button", `footer-model-option footer-worktree-option${selected ? " active" : ""}`);
    button.type = "button";
    button.disabled = selected || busy;
    button.title = selected ? `Current worktree: ${worktree.path}` : `Open worktree: ${worktree.path}`;
    const health = [
      worktree.detached ? "detached" : "",
      worktree.locked ? `locked${worktree.lockedReason ? `: ${worktree.lockedReason}` : ""}` : "",
    ].filter(Boolean).join(" · ");
    button.append(
      make("span", "footer-model-option-main", worktree.branch || "detached"),
      make("span", "footer-model-option-name", `${selected ? "current" : "open"}${health ? ` · ${health}` : ""} · ${normalizeDisplayPath(worktree.path)}`),
    );
    if (!button.disabled) button.addEventListener("click", () => openFooterGitWorktree(worktree.path, { branchName: worktree.branch || "", skipConfirm: true }));
    row.append(button);
    if (!selected && !worktree.isMainWorktree) {
      const remove = make("button", "footer-branch-advanced-action footer-worktree-remove", "Remove");
      remove.type = "button";
      remove.disabled = busy || worktree.locked;
      remove.title = worktree.locked ? `Worktree is locked${worktree.lockedReason ? `: ${worktree.lockedReason}` : ""}` : `git worktree remove ${worktree.path}`;
      remove.addEventListener("click", () => removeFooterGitWorktree(worktree));
      row.append(remove);
    }
    section.append(row);
  }
  if (prunableCount > 0) {
    const prune = make("button", "footer-branch-advanced-action footer-worktree-prune", `Prune ${prunableCount} stale worktree record${prunableCount === 1 ? "" : "s"}…`);
    prune.type = "button";
    prune.disabled = busy;
    prune.title = "git worktree prune (with dry-run preview)";
    prune.addEventListener("click", () => pruneFooterGitWorktrees());
    section.append(prune);
  }
  return section;
}

function openBranchWorktreePicker() {
  setNewTabMenuOpen(false);
  setMobileTabsExpanded(false);
  setComposerActionsOpen(false);
  setFooterBranchPickerOpen(true);
}

function renderFooterBranchPicker() {
  const picker = make("div", "footer-model-picker footer-branch-picker");
  picker.setAttribute("role", "listbox");
  picker.setAttribute("aria-label", "Git branches and worktrees");
  const state = footerBranchPickerState;
  const current = state.current || "detached";
  picker.append(make("div", "footer-model-picker-title", "Git branches & worktrees"));
  picker.append(make("div", "footer-model-picker-source", `${state.loading ? "Refreshing" : "Current"}: ${state.switching || current}${state.currentWorktreePath ? ` · ${normalizeDisplayPath(state.currentWorktreePath)}` : state.root ? ` · ${state.root}` : ""}`));

  if (state.error) {
    const error = make("div", "footer-model-picker-empty error");
    error.append(make("strong", undefined, "Cannot load branches."), make("span", undefined, ` ${state.error}`));
    picker.append(error);
    return picker;
  }
  if (state.loading && state.branches.length === 0) {
    picker.append(make("div", "footer-model-picker-empty muted", "Loading local and fetched remote branches and worktrees… Worktree creation is available once branch data loads."), renderFooterBranchCreateForm(state));
    return picker;
  }

  const hasOtherBranches = state.branches.some((branch) => branch.remote || (!branch.current && branch.name !== state.current));
  if (!state.loading && !hasOtherBranches) {
    const empty = make("div", "footer-model-picker-empty muted");
    empty.append(make("strong", undefined, "No other local or fetched remote branches available."), make("span", undefined, " Fetch to list remote branches, or create a branch worktree from origin/main or the current workspace HEAD to continue."));
    picker.append(empty);
  }

  picker.append(renderFooterBranchCreateForm(state));
  const worktreeSection = renderFooterWorktreeList(state);
  if (worktreeSection) picker.append(worktreeSection);
  picker.append(make("div", "footer-branch-section-title", "Branches"));

  for (const branch of state.branches) picker.append(renderFooterBranchOption(branch, state));
  return picker;
}

function footerScopedModelKey(model) {
  return model?.provider && model?.id ? `${model.provider}/${model.id}` : "";
}

function normalizeFooterScopedModelLayout(value) {
  return value === "advanced" ? "advanced" : "flat";
}

function readStoredFooterScopedModelLayout() {
  try {
    return normalizeFooterScopedModelLayout(localStorage.getItem(FOOTER_SCOPED_MODEL_LAYOUT_STORAGE_KEY));
  } catch {
    return "flat";
  }
}

function setFooterScopedModelLayout(value, { persist = true } = {}) {
  const next = normalizeFooterScopedModelLayout(value);
  if (persist) {
    try {
      localStorage.setItem(FOOTER_SCOPED_MODEL_LAYOUT_STORAGE_KEY, next);
    } catch {}
  }
  const changed = next !== footerScopedModelLayout;
  footerScopedModelLayout = next;
  syncGitFooterAdvancedMenuItem();
  if (!changed || !footerModelPickerOpen) return;
  renderFooter();
  updateFooterModelPickerPosition();
  focusFooterModelPickerInitialOption();
}

function toggleFooterScopedModelLayout() {
  setFooterScopedModelLayout(footerScopedModelLayout === "advanced" ? "flat" : "advanced");
}

function compareFooterScopedModelProviders(a, b) {
  const baseOrder = String(a).localeCompare(String(b), undefined, { sensitivity: "base" });
  return baseOrder || String(a).localeCompare(String(b));
}

function footerScopedModelProviderGroups(models = orderedFooterScopedModels()) {
  const modelsByProvider = new Map();
  for (const model of models) {
    const provider = String(model?.provider || "");
    if (!modelsByProvider.has(provider)) modelsByProvider.set(provider, []);
    modelsByProvider.get(provider).push(model);
  }
  return [...modelsByProvider.entries()]
    .sort(([a], [b]) => compareFooterScopedModelProviders(a, b))
    .map(([provider, providerModels]) => ({ provider, models: providerModels }));
}

function readFooterScopedModelOrder() {
  try {
    const parsed = JSON.parse(localStorage.getItem(FOOTER_SCOPED_MODEL_ORDER_STORAGE_KEY) || "[]");
    return Array.isArray(parsed) ? parsed.filter((key) => typeof key === "string" && key.trim()) : [];
  } catch {
    return [];
  }
}

function writeFooterScopedModelOrder(order) {
  try {
    localStorage.setItem(FOOTER_SCOPED_MODEL_ORDER_STORAGE_KEY, JSON.stringify([...new Set(order.filter(Boolean))]));
  } catch {}
  markDurableUiLayoutDirty("footerScopedModelOrder");
}

function orderedFooterScopedModels() {
  const order = readFooterScopedModelOrder();
  if (!order.length) return footerScopedModels;
  const rank = new Map(order.map((key, index) => [key, index]));
  return [...footerScopedModels].sort((a, b) => {
    const aRank = rank.has(footerScopedModelKey(a)) ? rank.get(footerScopedModelKey(a)) : Number.MAX_SAFE_INTEGER;
    const bRank = rank.has(footerScopedModelKey(b)) ? rank.get(footerScopedModelKey(b)) : Number.MAX_SAFE_INTEGER;
    return aRank - bRank;
  });
}

function focusFooterScopedModelOrderButton(modelKey) {
  if (!modelKey) return;
  const movedButton = document.querySelector(`[data-footer-model-key="${CSS.escape(modelKey)}"]`);
  if (!movedButton) return;
  const advancedPicker = movedButton.closest(".footer-model-picker-advanced");
  if (advancedPicker) focusAdvancedFooterModelOption(advancedPicker, movedButton);
  else movedButton.focus();
}

function rebuildOpenFooterModelPicker() {
  const picker = elements.statusBar.querySelector(".footer-model-picker");
  if (!footerModelPickerOpen || !picker) {
    renderFooter();
    return;
  }
  picker.replaceWith(renderFooterModelPicker());
  updateFooterModelPickerPosition();
}

function commitFooterScopedModelOrder(order, { render = true, focusKey = "" } = {}) {
  writeFooterScopedModelOrder(order);
  footerScopedModels = orderedFooterScopedModels();
  if (render) rebuildOpenFooterModelPicker();
  focusFooterScopedModelOrderButton(focusKey);
}

function reorderFooterScopedModel(fromKey, toKey, { focus = true } = {}) {
  if (!fromKey || !toKey || fromKey === toKey) return false;
  const models = orderedFooterScopedModels();
  const fromIndex = models.findIndex((model) => footerScopedModelKey(model) === fromKey);
  const toIndex = models.findIndex((model) => footerScopedModelKey(model) === toKey);
  if (fromIndex < 0 || toIndex < 0) return false;
  const [moved] = models.splice(fromIndex, 1);
  models.splice(toIndex, 0, moved);
  commitFooterScopedModelOrder(models.map(footerScopedModelKey), { focusKey: focus ? fromKey : "" });
  return true;
}

function moveFooterScopedModelByOffset(modelKey, offset) {
  const models = orderedFooterScopedModels();
  const fromIndex = models.findIndex((model) => footerScopedModelKey(model) === modelKey);
  const toIndex = fromIndex + offset;
  if (fromIndex < 0 || toIndex < 0 || toIndex >= models.length) return false;
  const [moved] = models.splice(fromIndex, 1);
  models.splice(toIndex, 0, moved);
  commitFooterScopedModelOrder(models.map(footerScopedModelKey), { focusKey: modelKey });
  return true;
}

function footerScopedModelOrderWithProviderOrder(provider, providerOrder) {
  const models = orderedFooterScopedModels();
  const providerKeys = models
    .filter((model) => String(model?.provider || "") === provider)
    .map(footerScopedModelKey);
  const allowedKeys = new Set(providerKeys);
  const nextProviderKeys = [...new Set(providerOrder.filter((key) => allowedKeys.has(key)))];
  for (const key of providerKeys) {
    if (!nextProviderKeys.includes(key)) nextProviderKeys.push(key);
  }
  let providerIndex = 0;
  return models.map((model) => String(model?.provider || "") === provider
    ? nextProviderKeys[providerIndex++]
    : footerScopedModelKey(model));
}

function commitFooterScopedModelProviderOrder(provider, providerOrder, { render = true, focusKey = "" } = {}) {
  if (!provider || !providerOrder.length) return false;
  const currentOrder = orderedFooterScopedModels().map(footerScopedModelKey);
  const nextOrder = footerScopedModelOrderWithProviderOrder(provider, providerOrder);
  if (nextOrder.every((key, index) => key === currentOrder[index])) {
    focusFooterScopedModelOrderButton(focusKey);
    return false;
  }
  commitFooterScopedModelOrder(nextOrder, { render, focusKey });
  return true;
}

function moveFooterScopedModelWithinProviderByOffset(modelKey, offset) {
  const models = orderedFooterScopedModels();
  const model = models.find((candidate) => footerScopedModelKey(candidate) === modelKey);
  const provider = String(model?.provider || "");
  if (!provider) return false;
  const providerOrder = models
    .filter((candidate) => String(candidate?.provider || "") === provider)
    .map(footerScopedModelKey);
  const fromIndex = providerOrder.indexOf(modelKey);
  const toIndex = fromIndex + offset;
  if (fromIndex < 0 || toIndex < 0 || toIndex >= providerOrder.length) return false;
  const [moved] = providerOrder.splice(fromIndex, 1);
  providerOrder.splice(toIndex, 0, moved);
  return commitFooterScopedModelProviderOrder(provider, providerOrder, { focusKey: modelKey });
}

function footerScopedModelButtons() {
  return [...document.querySelectorAll(".footer-model-picker .footer-model-option[data-footer-model-key]")];
}

function footerScopedModelButtonFromPoint(clientX, clientY) {
  return document.elementFromPoint(clientX, clientY)?.closest?.(".footer-model-option[data-footer-model-key]") || null;
}

function clearFooterScopedModelDragMarkers() {
  for (const button of footerScopedModelButtons()) {
    button.classList.remove("drag-over", "drag-over-before", "drag-over-after");
  }
}

function commitVisibleFooterScopedModelOrder({ render = false, focusKey = "", provider = "" } = {}) {
  const order = footerScopedModelButtons()
    .filter((button) => !provider || button.dataset.footerProvider === provider)
    .map((button) => button.dataset.footerModelKey)
    .filter(Boolean);
  if (!order.length) return;
  if (provider) {
    commitFooterScopedModelProviderOrder(provider, order, { render, focusKey });
    return;
  }
  commitFooterScopedModelOrder(order, { render, focusKey });
}

function moveVisibleFooterScopedModel(fromKey, targetButton, clientY) {
  if (!fromKey || !targetButton) return false;
  const sourceButton = document.querySelector(`[data-footer-model-key="${CSS.escape(fromKey)}"]`);
  if (!sourceButton || sourceButton === targetButton) return false;
  const parent = sourceButton.parentElement;
  if (!parent || targetButton.parentElement !== parent) return false;
  const targetKey = targetButton.dataset.footerModelKey || "";
  const rect = targetButton.getBoundingClientRect();
  const insertBefore = clientY < rect.top + rect.height / 2;

  clearFooterScopedModelDragMarkers();
  targetButton.classList.add("drag-over", insertBefore ? "drag-over-before" : "drag-over-after");
  footerScopedModelLastDragOverKey = `${targetKey}:${insertBefore ? "before" : "after"}`;

  if (insertBefore) parent.insertBefore(sourceButton, targetButton);
  else parent.insertBefore(sourceButton, targetButton.nextSibling);
  commitVisibleFooterScopedModelOrder({ render: false, provider: parent.dataset.footerProvider || "" });
  return true;
}

function beginFooterScopedModelPointerDrag(event, modelKey) {
  if (event.button !== 0 || !modelKey) return;
  footerScopedModelPointerDrag = { modelKey, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, active: false };
  window.addEventListener("pointermove", updateFooterScopedModelPointerDrag, { capture: true });
  window.addEventListener("pointerup", endFooterScopedModelPointerDrag, { capture: true });
  window.addEventListener("pointercancel", endFooterScopedModelPointerDrag, { capture: true });
}

function updateFooterScopedModelPointerDrag(event) {
  const drag = footerScopedModelPointerDrag;
  if (!drag || drag.pointerId !== event.pointerId) return;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  if (!drag.active && distance < FOOTER_SCOPED_MODEL_POINTER_DRAG_THRESHOLD_PX) return;
  event.preventDefault();
  if (!drag.active) {
    drag.active = true;
    footerScopedModelDragKey = drag.modelKey;
    footerScopedModelLastDragOverKey = "";
    clearTimeout(pointerActivationTimeout);
    pointerActivationTimeout = null;
    activePointerActivation = null;
    deferredUiRenderCallbacks.delete("footer");
    const sourceButton = document.querySelector(`[data-footer-model-key="${CSS.escape(drag.modelKey)}"]`);
    if (sourceButton) sourceButton.classList.add("dragging");
  }
  const targetButton = footerScopedModelButtonFromPoint(event.clientX, event.clientY);
  if (!targetButton || targetButton.dataset.footerModelKey === drag.modelKey) return;
  const rect = targetButton.getBoundingClientRect();
  const markerKey = `${targetButton.dataset.footerModelKey}:${event.clientY < rect.top + rect.height / 2 ? "before" : "after"}`;
  if (markerKey === footerScopedModelLastDragOverKey) return;
  moveVisibleFooterScopedModel(drag.modelKey, targetButton, event.clientY);
}

function endFooterScopedModelPointerDrag(event) {
  const drag = footerScopedModelPointerDrag;
  if (!drag || drag.pointerId !== event.pointerId) return;
  window.removeEventListener("pointermove", updateFooterScopedModelPointerDrag, { capture: true });
  window.removeEventListener("pointerup", endFooterScopedModelPointerDrag, { capture: true });
  window.removeEventListener("pointercancel", endFooterScopedModelPointerDrag, { capture: true });
  const wasActive = drag.active;
  const sourceButton = document.querySelector(`[data-footer-model-key="${CSS.escape(drag.modelKey)}"]`);
  const provider = sourceButton?.dataset.footerProvider || "";
  footerScopedModelPointerDrag = null;
  footerScopedModelDragKey = "";
  footerScopedModelLastDragOverKey = "";
  clearFooterScopedModelDragMarkers();
  if (sourceButton) sourceButton.classList.remove("dragging");
  if (wasActive) {
    footerScopedModelSuppressClickUntil = Date.now() + 250;
    event.preventDefault();
    commitVisibleFooterScopedModelOrder({ render: false, focusKey: drag.modelKey, provider });
  }
}

async function applyFooterModel(model) {
  if (!model?.provider || !model?.id || footerModelApplyInFlight) return;
  const tabContext = activeTabContext();
  footerModelApplyInFlight = true;
  footerModelPickerOpen = false;
  document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
  renderFooter();
  try {
    const response = await api("/api/model", { method: "POST", body: { provider: model.provider, modelId: model.id }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    applyOptimisticModelSelection(response.data || model, tabContext);
    await refreshState(tabContext);
    await refreshModels(tabContext);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
  } finally {
    footerModelApplyInFlight = false;
    if (isCurrentTabContext(tabContext)) {
      document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
      renderFooter();
    }
  }
}

function focusFooterModelTrigger() {
  queueMicrotask(() => {
    const trigger = elements.statusBar.querySelector(".footer-model.footer-meta-action, .footer-tui-model");
    trigger?.focus({ preventScroll: true });
  });
}

function footerModelPickerInitialKey() {
  const models = orderedFooterScopedModels();
  const currentKey = footerScopedModelKey(currentState?.model);
  return models.some((model) => footerScopedModelKey(model) === currentKey) ? currentKey : footerScopedModelKey(models[0]);
}

function focusFooterModelPickerInitialOption({ retryAfterPointerRender = true } = {}) {
  const initialKey = footerModelPickerInitialKey();
  queueMicrotask(() => {
    if (!footerModelPickerOpen) return;
    const picker = elements.statusBar.querySelector(".footer-model-picker");
    if (!picker) {
      if (retryAfterPointerRender) setTimeout(() => focusFooterModelPickerInitialOption({ retryAfterPointerRender: false }), 0);
      return;
    }
    const escapedKey = initialKey ? CSS.escape(initialKey) : "";
    const target = (escapedKey && picker.querySelector(`[data-footer-model-key="${escapedKey}"]`))
      || picker.querySelector(".footer-model-option[data-footer-model-key]");
    if (!target) return;
    if (footerScopedModelLayout === "advanced") {
      for (const button of picker.querySelectorAll(".footer-model-option[data-footer-model-key]")) button.tabIndex = button === target ? 0 : -1;
    }
    target.focus({ preventScroll: true });
    target.scrollIntoView({ block: "nearest", inline: "nearest" });
  });
}

function syncAdvancedFooterModelRovingTabStop(picker = elements.statusBar.querySelector(".footer-model-picker-advanced")) {
  if (!picker) return;
  const options = [...picker.querySelectorAll(".footer-model-option[data-footer-model-key]")];
  const focused = picker.contains(document.activeElement) ? document.activeElement.closest?.(".footer-model-option[data-footer-model-key]") : null;
  const target = focused || options.find((option) => option.tabIndex === 0) || options[0];
  for (const option of options) option.tabIndex = option === target ? 0 : -1;
}

function focusAdvancedFooterModelOption(picker, button) {
  if (!picker || !button) return;
  for (const option of picker.querySelectorAll(".footer-model-option[data-footer-model-key]")) option.tabIndex = option === button ? 0 : -1;
  button.focus({ preventScroll: true });
  button.scrollIntoView({ block: "nearest", inline: "nearest" });
}

function advancedFooterModelColumnButtons(picker, providerIndex) {
  const column = picker.querySelector(`[data-footer-provider-index="${providerIndex}"]`);
  return column ? [...column.querySelectorAll(".footer-model-option[data-footer-model-key]")] : [];
}

function handleAdvancedFooterModelKeydown(event, model) {
  const picker = event.currentTarget.closest(".footer-model-picker-advanced");
  if (!picker) return;
  const providerIndex = Number(event.currentTarget.dataset.footerProviderIndex);
  const modelIndex = Number(event.currentTarget.dataset.footerModelIndex);
  const columns = [...picker.querySelectorAll(".footer-model-provider-column[data-footer-provider-index]")];
  let target = null;

  if (event.key === "Enter" || event.key === " ") {
    event.preventDefault();
    if (!event.repeat) void applyFooterModel(model);
    return;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    setFooterModelPickerOpen(false, { restoreFocus: true });
    return;
  }
  if (event.altKey && (event.key === "ArrowUp" || event.key === "ArrowDown")) {
    event.preventDefault();
    moveFooterScopedModelWithinProviderByOffset(footerScopedModelKey(model), event.key === "ArrowUp" ? -1 : 1);
    return;
  }
  if (event.key === "ArrowUp" || event.key === "ArrowDown" || event.key === "Home" || event.key === "End") {
    const buttons = advancedFooterModelColumnButtons(picker, providerIndex);
    const lastIndex = Math.max(0, buttons.length - 1);
    const targetIndex = event.key === "Home"
      ? 0
      : event.key === "End"
        ? lastIndex
        : Math.min(lastIndex, Math.max(0, modelIndex + (event.key === "ArrowUp" ? -1 : 1)));
    target = buttons[targetIndex] || event.currentTarget;
  } else if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
    const lastProviderIndex = Math.max(0, columns.length - 1);
    const targetProviderIndex = Math.min(lastProviderIndex, Math.max(0, providerIndex + (event.key === "ArrowLeft" ? -1 : 1)));
    const buttons = advancedFooterModelColumnButtons(picker, targetProviderIndex);
    target = buttons[Math.min(Math.max(0, modelIndex), Math.max(0, buttons.length - 1))] || event.currentTarget;
  } else {
    return;
  }

  event.preventDefault();
  focusAdvancedFooterModelOption(picker, target);
}

function renderFooterModelOption(model, { advanced = false, providerIndex = -1, modelIndex = -1, initialKey = "" } = {}) {
  const current = currentState?.model;
  const selected = current?.provider === model.provider && current?.id === model.id;
  const modelKey = footerScopedModelKey(model);
  const dragging = footerScopedModelDragKey === modelKey;
  const dragOver = footerScopedModelDragKey && footerScopedModelLastDragOverKey === modelKey;
  const button = make("button", `footer-model-option${selected ? " active" : ""}${dragging ? " dragging" : ""}${dragOver ? " drag-over" : ""}`);
  button.type = "button";
  button.draggable = false;
  button.dataset.footerModelKey = modelKey;
  button.setAttribute("role", "option");
  button.setAttribute("aria-selected", selected ? "true" : "false");
  button.title = `${model.provider}/${model.id}${model.name ? ` · ${model.name}` : ""}`;
  button.append(
    make("span", "footer-model-option-main", advanced ? model.id : `${model.provider}/${model.id}`),
    make("span", "footer-model-option-name", model.name || ""),
  );
  button.addEventListener("click", (event) => {
    if (Date.now() < footerScopedModelSuppressClickUntil) {
      event.preventDefault();
      return;
    }
    void applyFooterModel(model);
  });
  if (advanced) {
    button.dataset.footerProvider = model.provider;
    button.dataset.footerProviderIndex = String(providerIndex);
    button.dataset.footerModelIndex = String(modelIndex);
    button.tabIndex = modelKey === initialKey ? 0 : -1;
    button.addEventListener("keydown", (event) => handleAdvancedFooterModelKeydown(event, model));
  } else {
    button.addEventListener("keydown", (event) => {
      if (!event.altKey || (event.key !== "ArrowUp" && event.key !== "ArrowDown")) return;
      event.preventDefault();
      moveFooterScopedModelByOffset(modelKey, event.key === "ArrowUp" ? -1 : 1);
    });
  }
  button.addEventListener("pointerdown", (event) => beginFooterScopedModelPointerDrag(event, modelKey));
  return button;
}

function renderFooterModelPicker() {
  const advanced = footerScopedModelLayout === "advanced";
  const picker = make("div", `footer-model-picker${advanced ? " footer-model-picker-advanced" : ""}`);
  picker.setAttribute("role", "listbox");
  picker.setAttribute("aria-label", advanced ? "Scoped models by provider" : "Scoped models");
  picker.append(make("div", "footer-model-picker-title", advanced ? "Scoped models by provider" : "Scoped models"));
  const help = make("div", "footer-model-picker-source", advanced
    ? "Drag within provider · Alt+Up/Down reorders · Left/Right changes provider · Up/Down changes model · Home/End jumps within provider · Enter/Space selects · Escape closes"
    : "Drag models to reorder · Alt+Up/Down moves focused model");
  help.id = "footerModelPickerHelp";
  picker.setAttribute("aria-describedby", help.id);
  picker.append(help);
  if (footerScopedModels.length === 0) {
    const empty = make("div", "footer-model-picker-empty muted");
    empty.append(
      make("strong", undefined, "No scoped models available."),
      make("span", undefined, " If you changed /scoped-models in the terminal UI, choose its Save action so Web UI can read it from settings, or start Web UI with forwarded Pi args like -- --models model-a,model-b."),
    );
    picker.append(empty);
    return picker;
  }
  footerScopedModels = orderedFooterScopedModels();
  const initialKey = footerModelPickerInitialKey();
  if (!advanced) {
    for (const model of footerScopedModels) picker.append(renderFooterModelOption(model));
    return picker;
  }

  const columns = make("div", "footer-model-provider-columns");
  for (const [providerIndex, group] of footerScopedModelProviderGroups(footerScopedModels).entries()) {
    const heading = make("div", "footer-model-provider-title", group.provider);
    heading.id = `footerModelProvider${providerIndex}`;
    const column = make("div", "footer-model-provider-column");
    column.dataset.footerProvider = group.provider;
    column.dataset.footerProviderIndex = String(providerIndex);
    column.setAttribute("role", "group");
    column.setAttribute("aria-labelledby", heading.id);
    column.append(heading);
    for (const [modelIndex, model] of group.models.entries()) {
      column.append(renderFooterModelOption(model, { advanced: true, providerIndex, modelIndex, initialKey }));
    }
    columns.append(column);
  }
  picker.append(columns);
  return picker;
}

async function applyFooterThinking(level) {
  const nextLevel = String(level || "").trim();
  if (!nextLevel) return;
  const tabContext = activeTabContext();
  try {
    footerThinkingPickerOpen = false;
    const response = await api("/api/thinking", { method: "POST", body: { level: nextLevel }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    applyOptimisticThinkingSelection(response.data || { level: nextLevel }, tabContext);
    if (response.data?.pending) {
      addEvent(response.data.message || `Thinking effort ${response.data.level || nextLevel} will apply to the next prompt.`, "info");
    } else if (response.data?.level) {
      const requested = response.data.requestedLevel;
      const effective = response.data.level;
      if (requested && requested !== effective) addEvent(`Thinking effort set to ${effective}: the active model does not support ${requested}.`, "warn");
      else addEvent(`Thinking effort set to ${effective}.`, "info");
    }
    await refreshState(tabContext);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
  } finally {
    if (isCurrentTabContext(tabContext)) {
      document.body.classList.toggle("footer-model-picker-open", isFooterPickerOpen());
      renderFooter();
    }
  }
}

function renderFooterThinkingPicker() {
  const picker = make("div", "footer-model-picker footer-thinking-picker");
  picker.setAttribute("role", "listbox");
  picker.setAttribute("aria-label", "Thinking effort");
  picker.append(make("div", "footer-model-picker-title", "Thinking effort"));
  picker.append(make("div", "footer-model-picker-source", "Applies to this Pi tab."));
  const current = currentState?.pendingThinkingLevel || currentState?.thinkingLevel || "off";
  for (const level of footerThinkingLevels()) {
    const selected = current === level;
    const supported = thinkingLevelSupportedByActiveModel(level);
    const button = make("button", `footer-model-option${selected ? " active" : ""}${supported ? "" : " unsupported"}`);
    button.type = "button";
    button.setAttribute("role", "option");
    button.setAttribute("aria-selected", selected ? "true" : "false");
    button.title = supported ? `Set thinking effort to ${level}` : `${level} is not supported by the active model`;
    button.disabled = !supported && !selected;
    button.append(make("span", "footer-model-option-main", supported ? footerThinkingLevelLabel(level) : `${footerThinkingLevelLabel(level)} · not supported`));
    button.addEventListener("click", () => applyFooterThinking(level));
    picker.append(button);
  }
  return picker;
}

function pathPickerButton(label, title, onClick, className = "") {
  const button = make("button", className, label);
  button.type = "button";
  button.title = title || label;
  button.addEventListener("click", onClick);
  return button;
}

function setPathPickerError(message) {
  elements.pathPickerError.textContent = message || "";
  elements.pathPickerError.hidden = !message;
}

function pathPickerEnteredPath() {
  return elements.pathPickerPathInput.value.trim();
}

function updatePathPickerPathControls() {
  const loading = !!pathPickerState?.loading;
  elements.pathPickerPathInput.disabled = !pathPickerState || loading;
  elements.pathPickerPathButton.disabled = !pathPickerState || loading || !pathPickerEnteredPath();
}

async function openPathPickerEnteredPath() {
  const cwd = pathPickerEnteredPath();
  if (!cwd || pathPickerState?.loading) return;
  await loadPathPickerDirectory(cwd);
}

function pathPickerCreateName() {
  return elements.pathPickerCreateNameInput.value.trim();
}

function pathPickerCreateValidationError(name = pathPickerCreateName()) {
  if (!name) return "Enter a directory name.";
  if (name === "." || name === "..") return "Use a real directory name, not . or ..";
  if (name.includes("\u0000")) return "Directory names cannot contain null bytes.";
  if (/[\\/]/.test(name)) return "Create one directory at a time; do not include path separators.";
  return "";
}

function updateCreateDirectoryControls() {
  const busy = !!pathPickerState?.creatingDirectory;
  const loading = !!pathPickerState?.loading;
  const canEdit = !!pathPickerState?.cwd && pathPickerState.selectable !== false && !loading && !busy;
  const canCreate = canEdit && !!pathPickerCreateName();
  elements.pathPickerCreateNameInput.disabled = !canEdit;
  elements.pathPickerCreateButton.disabled = !canCreate;
  elements.pathPickerCreateButton.textContent = busy ? "Creating…" : "Create directory";
}

function pathPickerSearchQuery() {
  return elements.pathPickerSearchInput.value.trim().toLowerCase();
}

function updatePathPickerSearchControls() {
  const loading = !!pathPickerState?.loading;
  const canSearch = !!pathPickerState && (pathPickerState.selectable === false || !!pathPickerState.cwd);
  const hasQuery = !!pathPickerSearchQuery();
  elements.pathPickerSearchInput.disabled = loading || !canSearch;
  elements.pathPickerClearSearchButton.hidden = !hasQuery;
  elements.pathPickerClearSearchButton.disabled = loading || !hasQuery;
}

function pathPickerDirectoryMatchesSearch(directory, query) {
  if (!query) return true;
  const haystack = String(directory?.name || "").toLowerCase();
  return query.split(/\s+/).every((term) => haystack.includes(term));
}

function renderPathPickerDirectoryList() {
  if (!pathPickerState) return;
  const directories = Array.isArray(pathPickerState.directories) ? pathPickerState.directories : [];
  const query = pathPickerSearchQuery();
  const matches = directories.filter((directory) => pathPickerDirectoryMatchesSearch(directory, query));
  pathPickerState.filteredDirectories = matches;
  updatePathPickerSearchControls();
  elements.pathPickerList.replaceChildren();

  if (query) {
    elements.pathPickerSearchStatus.textContent = matches.length === directories.length
      ? `Showing all ${matches.length} director${matches.length === 1 ? "y" : "ies"}.`
      : `Showing ${matches.length} of ${directories.length} directories.`;
  } else {
    elements.pathPickerSearchStatus.textContent = "";
  }

  if (!matches.length) {
    elements.pathPickerList.append(make("div", "path-picker-empty muted", query ? `No directories match “${elements.pathPickerSearchInput.value.trim()}”.` : "No subdirectories."));
    return;
  }

  for (const directory of matches) {
    const label = /[\\/]$/.test(directory.name) ? directory.name : `${directory.name}/`;
    const button = pathPickerButton(label, directory.cwd, () => loadPathPickerDirectory(directory.cwd, { focusAfterLoad: true }), `path-picker-directory${directory.hidden ? " hidden-directory" : ""}`);
    button.setAttribute("role", "option");
    elements.pathPickerList.append(button);
  }
}

function clearPathPickerSearch({ focus = false } = {}) {
  elements.pathPickerSearchInput.value = "";
  renderPathPickerDirectoryList();
  if (focus) elements.pathPickerSearchInput.focus();
}

function normalizeFastPicks(value) {
  const items = Array.isArray(value) ? value : [];
  const seen = new Set();
  const picks = [];
  for (const item of items) {
    const cwd = typeof item === "string" ? item : String(item?.cwd || "");
    if (!cwd || seen.has(cwd)) continue;
    seen.add(cwd);
    picks.push({ cwd, displayCwd: String(item?.displayCwd || cwd) });
  }
  return picks.slice(0, 30);
}

function loadLegacyFastPicks() {
  try {
    return normalizeFastPicks(JSON.parse(localStorage.getItem(PATH_FAST_PICKS_STORAGE_KEY) || "[]"));
  } catch {
    return [];
  }
}

function clearLegacyFastPicks() {
  try {
    localStorage.removeItem(PATH_FAST_PICKS_STORAGE_KEY);
  } catch {
    // Ignore storage cleanup failures; server persistence is authoritative.
  }
}

function loadFastPicks() {
  return pathFastPicks;
}

async function fetchFastPicks() {
  const response = await api("/api/path-fast-picks", { scoped: false });
  return normalizeFastPicks(response.data?.picks || []);
}

async function saveFastPicks(picks) {
  pathFastPicks = normalizeFastPicks(picks);
  pathFastPicksReady = true;
  renderFastPicks();
  try {
    const response = await api("/api/path-fast-picks", { method: "POST", body: { picks: pathFastPicks }, scoped: false });
    pathFastPicks = normalizeFastPicks(response.data?.picks || pathFastPicks);
    clearLegacyFastPicks();
  } catch (error) {
    try {
      localStorage.setItem(PATH_FAST_PICKS_STORAGE_KEY, JSON.stringify(pathFastPicks));
    } catch {
      // Ignore fallback storage failure; the event log still reports the server-side error.
    }
    addEvent(`failed to persist path fast picks on server; saved in this browser only: ${error.message}`, "error");
  }
  renderFastPicks();
}

async function initializeFastPicks() {
  if (pathFastPicksLoadPromise) return pathFastPicksLoadPromise;
  pathFastPicksLoadPromise = (async () => {
    const legacy = loadLegacyFastPicks();
    try {
      const serverPicks = await fetchFastPicks();
      const merged = normalizeFastPicks([...serverPicks, ...legacy]);
      pathFastPicks = merged;
      pathFastPicksReady = true;
      if (legacy.length > 0 && JSON.stringify(merged) !== JSON.stringify(serverPicks)) await saveFastPicks(merged);
      else clearLegacyFastPicks();
    } catch (error) {
      pathFastPicks = legacy;
      pathFastPicksReady = true;
      if (legacy.length > 0) addEvent(`using browser-only path fast picks; server load failed: ${error.message}`, "warn");
      else addEvent(`failed to load path fast picks: ${error.message}`, "error");
    }
    renderFastPicks();
  })();
  return pathFastPicksLoadPromise;
}

function fastPickLabel(pick) {
  const cwd = String(pick.cwd || pick.displayCwd || "");
  const trimmed = cwd.replace(/\\/g, "/").replace(/\/+$/, "");
  if (!trimmed) return cwd || "directory";
  return trimmed.split("/").filter(Boolean).pop() || trimmed;
}

function currentFastPick() {
  if (!pathPickerState?.cwd || pathPickerState.selectable === false) return null;
  return { cwd: pathPickerState.cwd, displayCwd: elements.pathPickerCurrent.textContent || pathPickerState.cwd };
}

function updateAddFastPickButton() {
  if (!pathFastPicksReady) {
    elements.pathPickerAddFastPickButton.disabled = true;
    elements.pathPickerAddFastPickButton.textContent = "Loading pinned folders…";
    return;
  }
  const pick = currentFastPick();
  const exists = !!pick && loadFastPicks().some((item) => item.cwd === pick.cwd);
  elements.pathPickerAddFastPickButton.disabled = !pick || exists;
  elements.pathPickerAddFastPickButton.textContent = exists ? "Pinned" : "Pin this folder";
}

function renderFastPicks() {
  const picks = loadFastPicks();
  elements.pathPickerFastPicks.replaceChildren();
  if (!pathFastPicksReady) {
    elements.pathPickerFastPicks.append(make("div", "path-picker-fast-picks-empty muted", "Loading pinned folders…"));
    updateAddFastPickButton();
    return;
  }
  if (picks.length === 0) {
    elements.pathPickerFastPicks.append(make("div", "path-picker-fast-picks-empty muted", "No pinned folders yet. Pin the folders you switch to often."));
    updateAddFastPickButton();
    return;
  }

  for (const pick of picks) {
    const item = make("span", "path-picker-fast-pick");
    const jump = pathPickerButton(fastPickLabel(pick), pick.cwd, () => loadPathPickerDirectory(pick.cwd, { focusAfterLoad: true }), "path-picker-fast-pick-button");
    const remove = pathPickerButton("×", `Unpin ${pick.cwd}`, async () => {
      await saveFastPicks(loadFastPicks().filter((item) => item.cwd !== pick.cwd));
    }, "path-picker-fast-pick-remove");
    item.append(jump, remove);
    elements.pathPickerFastPicks.append(item);
  }
  updateAddFastPickButton();
}

async function addCurrentFastPick() {
  const pick = currentFastPick();
  if (!pick) return;
  const picks = loadFastPicks().filter((item) => item.cwd !== pick.cwd);
  picks.unshift(pick);
  await saveFastPicks(picks);
}

function renderPathPicker(data) {
  if (!pathPickerState) return;
  pathPickerState.cwd = data.cwd || "";
  pathPickerState.displayCwd = data.displayCwd || pathPickerState.cwd;
  pathPickerState.selectable = data.selectable !== false;
  pathPickerState.loading = false;
  pathPickerState.directories = Array.isArray(data.directories) ? data.directories : [];
  pathPickerState.filteredDirectories = pathPickerState.directories;
  elements.pathPickerCurrent.textContent = pathPickerState.displayCwd;
  elements.pathPickerCurrent.title = pathPickerState.cwd || pathPickerState.displayCwd;
  elements.pathPickerChooseButton.disabled = !pathPickerState.selectable || !pathPickerState.cwd;
  elements.pathPickerChooseButton.textContent = "Use this directory";
  elements.pathPickerPathInput.value = "";
  elements.pathPickerCreateNameInput.value = "";
  elements.pathPickerSearchInput.value = "";
  setPathPickerError(data.truncated ? "Showing the first 500 directories." : "");
  updatePathPickerPathControls();
  updateCreateDirectoryControls();
  renderFastPicks();

  elements.pathPickerRoots.replaceChildren();
  if (data.parent) {
    elements.pathPickerRoots.append(pathPickerButton("↑ Parent", data.parent, () => loadPathPickerDirectory(data.parent, { focusAfterLoad: true }), "path-picker-root-button"));
  }
  for (const root of data.roots || []) {
    elements.pathPickerRoots.append(pathPickerButton(root.label, root.cwd, () => loadPathPickerDirectory(root.cwd, { focusAfterLoad: true }), "path-picker-root-button"));
  }

  renderPathPickerDirectoryList();
}

async function loadPathPickerDirectory(cwd, { focusAfterLoad = false } = {}) {
  if (!pathPickerState) return;
  const requestId = ++pathPickerState.requestId;
  pathPickerState.loading = true;
  elements.pathPickerAddFastPickButton.disabled = true;
  elements.pathPickerChooseButton.disabled = true;
  elements.pathPickerCurrent.textContent = "Loading…";
  elements.pathPickerSearchStatus.textContent = "";
  updatePathPickerPathControls();
  updateCreateDirectoryControls();
  updatePathPickerSearchControls();
  setPathPickerError("");

  try {
    const query = cwd ? `?path=${encodeURIComponent(cwd)}` : "";
    const response = await api(`/api/directories${query}`);
    if (!pathPickerState || pathPickerState.requestId !== requestId) return;
    renderPathPicker(response.data || {});
    if (focusAfterLoad) elements.pathPickerSearchInput.focus({ preventScroll: true });
  } catch (error) {
    if (!pathPickerState || pathPickerState.requestId !== requestId) return;
    pathPickerState.loading = false;
    elements.pathPickerChooseButton.disabled = !pathPickerState.selectable || !pathPickerState.cwd;
    elements.pathPickerCurrent.textContent = pathPickerState.displayCwd || pathPickerState.cwd || "Unable to load directory";
    elements.pathPickerCurrent.title = pathPickerState.cwd || pathPickerState.displayCwd || "";
    setPathPickerError(error.message);
    updatePathPickerPathControls();
    updateCreateDirectoryControls();
    updatePathPickerSearchControls();
    updateAddFastPickButton();
  }
}

async function createPathPickerDirectory() {
  const state = pathPickerState;
  if (!state?.cwd || state.loading || state.creatingDirectory) return;
  const name = pathPickerCreateName();
  const validationError = pathPickerCreateValidationError(name);
  if (validationError) {
    setPathPickerError(validationError);
    elements.pathPickerCreateNameInput.focus();
    return;
  }

  const requestId = ++state.requestId;
  state.creatingDirectory = true;
  updateCreateDirectoryControls();
  setPathPickerError("");
  try {
    const response = await api("/api/directories", { method: "POST", body: { parent: state.cwd, name } });
    if (!pathPickerState || pathPickerState !== state || state.requestId !== requestId) return;
    renderPathPicker(response.data || {});
    elements.pathPickerChooseButton.focus({ preventScroll: true });
  } catch (error) {
    if (!pathPickerState || pathPickerState !== state || state.requestId !== requestId) return;
    setPathPickerError(error.message);
    elements.pathPickerCreateNameInput.focus();
  } finally {
    if (pathPickerState === state) {
      state.creatingDirectory = false;
      updateCreateDirectoryControls();
    }
  }
}

function closePathPicker(cwd) {
  const state = pathPickerState;
  if (!state) return;
  pathPickerState = null;
  if (elements.pathPickerDialog.open) elements.pathPickerDialog.close();
  state.resolve(cwd || null);
}

function pickCwd(tab, initialCwd, { title } = {}) {
  if (pathPickerState) {
    addEvent("working-directory picker is already open", "warn");
    elements.pathPickerDialog.focus();
    elements.pathPickerSearchInput.focus({ preventScroll: true });
    return Promise.resolve(null);
  }

  return new Promise((resolve) => {
    const pickerTab = tab || { id: "path-picker", title: "tab" };
    pathPickerState = { tabId: pickerTab.id, cwd: initialCwd, displayCwd: initialCwd, selectable: true, requestId: 0, loading: false, creatingDirectory: false, directories: [], filteredDirectories: [], resolve };
    elements.pathPickerTitle.textContent = title || `Choose CWD for ${pickerTab.title}`;
    elements.pathPickerCurrent.textContent = "Loading…";
    elements.pathPickerPathInput.value = "";
    elements.pathPickerCreateNameInput.value = "";
    elements.pathPickerSearchInput.value = "";
    elements.pathPickerSearchStatus.textContent = "";
    elements.pathPickerFastPicks.replaceChildren();
    elements.pathPickerRoots.replaceChildren();
    elements.pathPickerList.replaceChildren();
    setPathPickerError("");
    elements.pathPickerAddFastPickButton.disabled = true;
    elements.pathPickerChooseButton.disabled = true;
    updatePathPickerPathControls();
    updateCreateDirectoryControls();
    updatePathPickerSearchControls();
    initializeFastPicks().catch((error) => addEvent(`failed to initialize path fast picks: ${error.message}`, "error"));
    elements.pathPickerDialog.showModal();
    loadPathPickerDirectory(initialCwd);
  });
}

async function changeActiveTabCwd() {
  const tab = activeTab();
  if (!tab) return;
  const tabContext = activeTabContext(tab.id);

  const currentCwd = latestWorkspace?.cwd || tab.cwd || "";
  const cwd = await pickCwd(tab, currentCwd);
  if (!isCurrentTabContext(tabContext) || !cwd || cwd === currentCwd) return;

  if (shouldOpenCwdChangeInNewTab(tab)) {
    await createTerminalTab(cwd, { triggerButton: null });
    return;
  }

  if (!(await appConfirmText(`Restart ${tab.title} in:\n${cwd}\n\nCurrent in-flight work in this tab will be stopped. The conversation continues in the new directory.`, { affected: tab.title, confirmLabel: "Change working folder" }))) return;
  if (activeFileViewer?.dirty && !(await confirmDiscardEdits({ what: "unsaved file edits", target: activeFileViewer.path }))) return;

  saveActiveDraft();
  if (isCurrentTabContext(tabContext)) {
    addTransientMessage({
      role: "native",
      title: "Changing working folder…",
      content: `Restarting ${tab.title} in ${cwd}. This can take a few seconds.`,
      level: "info",
    });
  }
  let response;
  try {
    response = await api(`/api/tabs/${encodeURIComponent(tab.id)}`, { method: "PATCH", body: { cwd }, scoped: false });
  } catch (error) {
    const message = `Could not change ${tab.title} to ${cwd}. The existing working folder was kept.\n\n${error.message || String(error)}`;
    if (isCurrentTabContext(tabContext)) surfaceRuntimeDiagnostic("Working folder change failed", message);
    else addEvent(`working folder change failed for ${tab.title}: ${error.message || String(error)}`, "error");
    return;
  }

  tabs = response.data?.tabs || tabs;
  syncTabMetadata(tabs);
  const changedTabId = response.data?.tab?.id || tab.id;
  const changedCwd = response.data?.tab?.cwd || cwd;
  resetGitWorkflowForTab(changedTabId);
  clearGitFooterPayloadState(changedTabId);
  if (!isCurrentTabContext(tabContext)) {
    renderTabs();
    addEvent(response.data?.changed === false ? `cwd unchanged: ${changedCwd}` : `changed ${tab.title} cwd to ${changedCwd}`, "info");
    return;
  }

  if (response.data?.changed !== false) closeFileViewer();
  const nextContext = setActiveTabId(response.data?.tab?.id || activeTabId);
  resetActiveTabUi();
  renderTabs();
  restoreActiveDraft();
  connectEvents(nextContext);
  await refreshAll(nextContext);
  if (!isCurrentTabContext(nextContext)) return;
  const successMessage = response.data?.changed === false ? `cwd unchanged: ${changedCwd}` : `changed ${tab.title} cwd to ${changedCwd}`;
  addEvent(successMessage, "info");
  if (response.data?.changed !== false) addTransientMessage({ role: "native", title: "Working folder changed", content: `${tab.title} restarted in ${changedCwd}.`, level: "info" });
}

function footerControlKey(node) {
  if (node?.id) return `footer:id:${node.id}`;
  if (node?.dataset?.footerModelKey) return `footer:model:${node.dataset.footerModelKey}`;
  return "";
}

function renderFooter() {
  if (deferUiRenderDuringPointerActivation("footer", renderFooter)) return;
  const continuityContextKey = `${activeTabId || ""}:${activeTabGeneration}:${footerBranchPickerOpen ? footerBranchPickerState.tabId || activeTabId || "" : ""}`;
  const focusSnapshot = captureScopedControlContinuity(elements.statusBar, continuityContextKey, footerControlKey);
  const tooltipSnapshot = captureTooltipContinuity(elements.statusBar);
  const gitFooterPayload = parseGitFooterWebuiPayload();
  if (gitFooterPayload) renderGitFooterPayload(footerPayloadWithLiveModel(gitFooterPayload));
  else renderMinimalFooter();
  if (!tooltipSnapshot && footerTooltipTarget && !footerTooltipTarget.isConnected) hideFooterTooltip();
  restoreScopedControlContinuity(elements.statusBar, continuityContextKey, focusSnapshot, (key) => [...elements.statusBar.querySelectorAll("input, textarea, select, button")].find((node) => footerControlKey(node) === key));
  syncAdvancedFooterModelRovingTabStop();
  restoreTooltipContinuity(elements.statusBar, tooltipSnapshot);
}

function scheduleRefreshMessages(delay = 120, tabContext = activeTabContext()) {
  clearTimeout(refreshMessagesTimer);
  refreshMessagesTimer = setTimeout(() => {
    if (!isCurrentTabContext(tabContext)) return;
    refreshMessages(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
    });
  }, delay);
}

function scheduleRefreshState(delay = 120, tabContext = activeTabContext()) {
  clearTimeout(refreshStateTimer);
  refreshStateTimer = setTimeout(() => {
    if (!isCurrentTabContext(tabContext)) return;
    refreshState(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
    });
  }, delay);
}

function scheduleRefreshFooter(delay = 300, tabContext = activeTabContext()) {
  clearTimeout(refreshFooterTimer);
  refreshFooterTimer = setTimeout(() => {
    if (!isCurrentTabContext(tabContext)) return;
    refreshFooterData(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
    });
  }, delay);
}

function semanticReconcileContextKey(tabContext = {}) {
  return `${tabContext.tabId || ""}:${Number(tabContext.generation) || 0}`;
}

function mergeSemanticReconcileRequest(pendingByContext, dirty = {}, tabContext = {}) {
  const key = semanticReconcileContextKey(tabContext);
  let request = pendingByContext.get(key);
  if (!request) {
    request = { tabContext: { tabId: tabContext.tabId || null, generation: Number(tabContext.generation) || 0 }, dirty: {} };
  }
  let requested = false;
  for (const flag of SEMANTIC_RECONCILE_FLAGS) {
    if (!dirty[flag]) continue;
    request.dirty[flag] = true;
    requested = true;
  }
  if (requested) pendingByContext.set(key, request);
  return requested;
}

function takeSemanticReconcileRequests(pendingByContext) {
  const requests = Array.from(pendingByContext.values());
  pendingByContext.clear();
  return requests;
}

// Coalesced semantic reconciliation. Lifecycle boundaries declare which
// non-transcript surfaces became dirty; each tab generation retains its own
// request until the frame flush. Raw stream deltas never reach here.
function scheduleSemanticReconcile(dirty = {}, tabContext = activeTabContext()) {
  if (!mergeSemanticReconcileRequest(semanticReconcilePending, dirty, tabContext)) return;
  if (semanticReconcileFrame !== null) return;
  const flush = () => {
    semanticReconcileFrame = null;
    flushSemanticReconcile();
  };
  if (typeof requestAnimationFrame === "function") semanticReconcileFrame = requestAnimationFrame(flush);
  else semanticReconcileFrame = setTimeout(flush, 0);
}

function flushSemanticReconcile() {
  for (const { dirty, tabContext } of takeSemanticReconcileRequests(semanticReconcilePending)) {
    // Originating-tab settlement work is never reassigned. Workflow continuation
    // is tab-scoped and may run after the user has switched away.
    if (dirty.workflow) reconcileGitWorkflowContinuation(tabContext.tabId);
    if (dirty.usage) {
      scheduleRefreshCodexUsage(2200);
      scheduleRefreshClaudeUsage(2200);
    }

    // DOM and active-session fetches are valid only for the still-current tab
    // generation; resetActiveTabUi/refreshAll owns the newly active tab.
    if (!isCurrentTabContext(tabContext)) continue;
    if (dirty.messages) scheduleRefreshMessages(120, tabContext);
    if (dirty.state) scheduleRefreshState(120, tabContext);
    if (dirty.footerData) scheduleRefreshFooter(300, tabContext);
    if (dirty.footer) renderFooter();
    if (dirty.feedback) renderFeedbackTray();
    if (dirty.usage) {
      refreshCodexFastMode(tabContext).catch((error) => addEvent(`Codex Fast mode refresh failed: ${error.message || String(error)}`, "warn"));
    }
  }
}

// Continue a guided git workflow that was waiting on the agent turn. This is a
// settlement-boundary concern, not a streaming concern.
function reconcileGitWorkflowContinuation(workflowTabId = activeTabId) {
  const workflow = gitWorkflowForTab(workflowTabId, { create: false });
  if (!workflow?.active) return;
  if (workflow.step === "generating") {
    loadGitWorkflowMessage({ requireFresh: true, generationId: workflow.messageGenerationId, runId: workflow.runId, tabId: workflowTabId });
  } else if (workflow.step === "branchNaming") {
    loadGitWorkflowBranchName({ requireFresh: true, retries: 3, runId: workflow.runId, tabId: workflowTabId });
  } else if (workflow.step === "prGenerating") {
    loadGitWorkflowPr({ requireFresh: true, retries: 3, runId: workflow.runId, tabId: workflowTabId });
  } else if (workflow.step === "readmeGenerating") {
    prepareGitInitFiles({ afterReadmePrompt: true, runId: workflow.runId, tabId: workflowTabId });
  } else if (workflow.step === "gitignoreGenerating") {
    prepareGitInitFiles({ afterGitignorePrompt: true, runId: workflow.runId, tabId: workflowTabId });
  }
}

function formatCodexPlanType(value) {
  const text = String(value || "").trim();
  if (!text) return "unknown plan";
  const normalized = text.replace(/[\s_-]+/g, "").toLowerCase();
  if (normalized === "prolite") return "Usage";
  return text.replace(/[_-]+/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function formatCodexPercent(value) {
  const number = Number(value);
  return Number.isFinite(number) ? `${Math.max(0, Math.min(100, Math.round(number)))}%` : "—";
}

function codexWindowDurationMinutes(window) {
  const minutes = Number(window?.windowDurationMins);
  if (Number.isFinite(minutes) && minutes > 0) return minutes;
  const seconds = Number(window?.windowDurationSeconds);
  return Number.isFinite(seconds) && seconds > 0 ? seconds / 60 : null;
}

function formatCodexWindowDuration(window) {
  const minutes = codexWindowDurationMinutes(window);
  if (!minutes) return "window";
  if (minutes >= 280 && minutes <= 320) return "5h window";
  if (minutes >= 9500 && minutes <= 10550) return "weekly window";
  if (minutes >= 60 * 24) {
    const days = minutes / (60 * 24);
    return `${days >= 10 ? Math.round(days) : Number(days.toFixed(1))}d window`;
  }
  if (minutes >= 60) {
    const hours = minutes / 60;
    return `${Number.isInteger(hours) ? hours : Number(hours.toFixed(1))}h window`;
  }
  return `${Math.round(minutes)}m window`;
}

function formatDurationParts(milliseconds) {
  if (!Number.isFinite(Number(milliseconds))) return "now";
  const totalMinutes = Math.max(0, Math.ceil(Number(milliseconds) / 60000));
  if (totalMinutes <= 1) return "<1m";
  if (totalMinutes < 60) return `${totalMinutes}m`;
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours < 48) return minutes ? `${hours}h ${minutes}m` : `${hours}h`;
  const days = Math.floor(hours / 24);
  const remHours = hours % 24;
  return remHours ? `${days}d ${remHours}h` : `${days}d`;
}

function codexWindowResetDate(window) {
  const resetAt = window?.resetsAt ? new Date(window.resetsAt) : null;
  if (resetAt && Number.isFinite(resetAt.getTime())) return resetAt;
  const resetAfterSeconds = Number(window?.resetAfterSeconds);
  if (Number.isFinite(resetAfterSeconds) && resetAfterSeconds >= 0) return new Date(Date.now() + resetAfterSeconds * 1000);
  return null;
}

function formatCodexReset(window) {
  const resetDate = codexWindowResetDate(window);
  if (!resetDate) return "reset unknown";
  const diff = resetDate.getTime() - Date.now();
  if (diff <= 0) return "resetting now";
  return `resets in ${formatDurationParts(diff)}`;
}

function codexSnapshotName(snapshot) {
  return snapshot?.limitName || snapshot?.limitId || "codex";
}

function codexUsageBuckets(data) {
  const buckets = [];
  const selected = data?.selected || data?.rateLimits || null;
  const snapshots = Array.isArray(data?.snapshots) ? data.snapshots : selected ? [selected] : [];
  const selectedKey = selected?.limitId || selected?.limitName || "codex";
  const pushWindow = (snapshot, kind, window, { prefix } = {}) => {
    if (!window) return;
    const durationLabel = formatCodexWindowDuration(window);
    const baseLabel = kind === "secondary" && durationLabel === "window" ? "secondary window" : durationLabel;
    buckets.push({
      key: `${snapshot?.limitId || snapshot?.limitName || buckets.length}-${kind}`,
      label: prefix ? `${prefix} · ${baseLabel}` : baseLabel,
      window,
    });
  };

  if (selected) {
    pushWindow(selected, "primary", selected.primary);
    pushWindow(selected, "secondary", selected.secondary);
  }
  for (const snapshot of snapshots) {
    const key = snapshot?.limitId || snapshot?.limitName;
    if (!snapshot || snapshot === selected || key === selectedKey) continue;
    const name = codexSnapshotName(snapshot);
    pushWindow(snapshot, "primary", snapshot.primary, { prefix: name });
    pushWindow(snapshot, "secondary", snapshot.secondary, { prefix: name });
  }
  return buckets.slice(0, 6);
}

function codexUsageStructureSignature() {
  if (!latestCodexUsage) return JSON.stringify({ state: codexUsageLoading ? "loading" : codexUsageError ? "error" : "empty", error: codexUsageError?.message || String(codexUsageError || "") });
  return JSON.stringify({
    state: "data",
    plan: formatCodexPlanType(latestCodexUsage.planType),
    buckets: codexUsageBuckets(latestCodexUsage).map((bucket) => [bucket.key, bucket.label]),
    rateLimitReachedType: latestCodexUsage.rateLimitReachedType || "",
    error: codexUsageError?.message || String(codexUsageError || ""),
  });
}

function updateCodexUsageValues(box, buckets) {
  if (!latestCodexUsage || !box.querySelector(".codex-usage-summary")) return false;
  const fetched = box.querySelector(".codex-usage-fetched");
  if (fetched) fetched.textContent = latestCodexUsage.fetchedAt ? `updated ${formatDurationParts(Date.now() - new Date(latestCodexUsage.fetchedAt).getTime())} ago` : "updated now";
  const rendered = [...box.querySelectorAll(".codex-usage-bucket[data-codex-usage-key]")];
  if (rendered.length !== buckets.length) return false;
  for (const bucket of buckets) {
    const item = rendered.find((node) => node.dataset.codexUsageKey === bucket.key);
    if (!item) return false;
    const usedPercent = Number(bucket.window?.usedPercent);
    const fillPercent = Number.isFinite(usedPercent) ? Math.max(0, Math.min(100, usedPercent)) : 0;
    const percent = item.querySelector(".codex-usage-percent");
    const fill = item.querySelector(".codex-usage-meter-fill");
    const reset = item.querySelector(".codex-usage-reset");
    if (!percent || !fill || !reset) return false;
    percent.textContent = formatCodexPercent(usedPercent);
    fill.style.width = `${fillPercent}%`;
    reset.textContent = formatCodexReset(bucket.window);
  }
  return true;
}

function renderCodexUsage() {
  const box = elements.codexUsageBox;
  if (!box) return;
  if (elements.refreshCodexUsageButton) {
    elements.refreshCodexUsageButton.disabled = codexUsageLoading;
    elements.refreshCodexUsageButton.textContent = codexUsageLoading ? "Refreshing…" : "Refresh usage";
  }

  const buckets = codexUsageBuckets(latestCodexUsage);
  const structureSignature = codexUsageStructureSignature();
  if (structureSignature === codexUsageRenderSignature && updateCodexUsageValues(box, buckets)) {
    box.classList.toggle("muted", !latestCodexUsage);
    return;
  }
  codexUsageRenderSignature = structureSignature;
  box.replaceChildren();
  box.classList.toggle("muted", !latestCodexUsage);

  if (!latestCodexUsage && codexUsageLoading) {
    box.textContent = "Checking Codex usage…";
    return;
  }
  if (!latestCodexUsage && codexUsageError) {
    const title = make("div", "codex-usage-unavailable", "Usage unavailable");
    const detail = make("div", "codex-usage-detail", codexUsageError.message || String(codexUsageError));
    box.append(title, detail);
    return;
  }
  if (!latestCodexUsage) {
    box.textContent = "Codex usage has not loaded yet.";
    return;
  }

  const header = make("div", "codex-usage-summary");
  header.append(
    make("span", "codex-usage-plan", formatCodexPlanType(latestCodexUsage.planType)),
    make("span", "codex-usage-fetched", latestCodexUsage.fetchedAt ? `updated ${formatDurationParts(Date.now() - new Date(latestCodexUsage.fetchedAt).getTime())} ago` : "updated now"),
  );
  box.append(header);

  if (buckets.length === 0) {
    box.append(make("div", "codex-usage-detail", "No Codex rate-limit windows were returned."));
  } else {
    for (const bucket of buckets) {
      const usedPercent = Number(bucket.window?.usedPercent);
      const fillPercent = Number.isFinite(usedPercent) ? Math.max(0, Math.min(100, usedPercent)) : 0;
      const item = make("div", "codex-usage-bucket");
      item.dataset.codexUsageKey = bucket.key;
      const row = make("div", "codex-usage-row");
      row.append(
        make("span", "codex-usage-label", bucket.label),
        make("strong", "codex-usage-percent", formatCodexPercent(bucket.window?.usedPercent)),
      );
      const meter = make("div", "codex-usage-meter");
      const fill = make("span", "codex-usage-meter-fill");
      fill.style.width = `${fillPercent}%`;
      meter.append(fill);
      item.append(row, meter, make("div", "codex-usage-reset", formatCodexReset(bucket.window)));
      box.append(item);
    }
  }

  if (latestCodexUsage.rateLimitReachedType) {
    box.append(make("div", "codex-usage-warning", `Limit status: ${latestCodexUsage.rateLimitReachedType}`));
  }
  if (codexUsageError) {
    box.append(make("div", "codex-usage-detail", `Latest refresh failed: ${codexUsageError.message || codexUsageError}`));
  }
}

async function refreshCodexUsage({ forceAuthRefresh = false } = {}) {
  if (codexUsageLoading) return;
  codexUsageLoading = true;
  renderCodexUsage();
  try {
    const suffix = forceAuthRefresh ? "?refresh=1" : "";
    const response = await api(`/api/codex-usage${suffix}`, { scoped: false });
    latestCodexUsage = response.data || null;
    codexUsageError = null;
  } catch (error) {
    codexUsageError = error;
  } finally {
    codexUsageLoading = false;
    renderCodexUsage();
  }
}

// Codex subscription Fast mode is owned by the optional pi-extension-codex-fast-mode package. The
// browser only reads the sanitized tab-scoped server snapshot and asks the server to run the
// package-owned /fast-mode command; it never sees ChatGPT credentials or request payloads.
let codexFastModeState = { available: false, enabled: false, statusKnown: false, busy: false, model: null, modelEligible: false, unavailableReason: "", creditNotice: "" };
let codexFastModeLoaded = false;
let codexFastModeBusy = false;
let codexFastModeNotice = "";
let codexFastModeSelection = "normal";

function codexFastModeControlDisabled() {
  return !codexFastModeLoaded
    || !codexFastModeState.available
    || !isOptionalFeatureEnabled("codexFastMode")
    || codexFastModeBusy
    || codexFastModeState.busy === true;
}

function codexFastModeStatusText() {
  if (codexFastModeNotice) return codexFastModeNotice;
  if (!isOptionalFeatureEnabled("codexFastMode")) return optionalFeatureUnavailableMessage("codexFastMode");
  if (!codexFastModeLoaded) return "Checking…";
  if (!codexFastModeState.available) return codexFastModeState.unavailableReason || optionalFeatureUnavailableMessage("codexFastMode");
  if (!codexFastModeState.statusKnown) return "Status unknown · This tab";
  if (codexFastModeState.busy) return `${codexFastModeState.enabled ? "Fast" : "Normal"} · Busy`;
  if (codexFastModeState.enabled && codexFastModeState.model && !codexFastModeState.modelEligible) {
    return "Fast · Inactive for current model";
  }
  return `${codexFastModeState.enabled ? "Fast" : "Normal"} · This tab`;
}

function renderCodexFastModeControl({ syncSelection = true } = {}) {
  if (!elements.codexFastModeSelect || !elements.setCodexFastModeButton || !elements.codexFastModeStatus) return;
  if (syncSelection) {
    codexFastModeSelection = codexFastModeState.enabled ? "fast" : "normal";
    elements.codexFastModeSelect.value = codexFastModeSelection;
  }
  const controlDisabled = codexFastModeControlDisabled();
  elements.codexFastModeSelect.disabled = controlDisabled;
  elements.setCodexFastModeButton.disabled = controlDisabled
    || elements.codexFastModeSelect.value === (codexFastModeState.enabled ? "fast" : "normal");
  elements.setCodexFastModeButton.textContent = codexFastModeBusy ? "Applying…" : "Apply";
  elements.codexFastModeStatus.textContent = codexFastModeStatusText();
  const warn = !!codexFastModeNotice
    || (codexFastModeLoaded && !codexFastModeState.available)
    || codexFastModeState.busy === true
    || !isOptionalFeatureEnabled("codexFastMode");
  elements.codexFastModeStatus.classList.toggle("warning", warn);
}

function applyCodexFastModeData(data) {
  codexFastModeState = {
    available: data?.available === true,
    enabled: data?.enabled === true,
    statusKnown: data?.statusKnown === true,
    busy: data?.busy === true,
    model: data?.model || null,
    modelEligible: data?.modelEligible === true,
    unavailableReason: data?.unavailableReason || "",
    creditNotice: data?.creditNotice || "",
  };
  if (codexFastModeState.available) optionalFeatureAvailability.codexFastMode = true;
}

function codexFastModeConfirmedOff(data) {
  return data?.statusKnown === true && data?.enabled !== true;
}

function applyCodexFastModeStatus(statusText) {
  const status = String(statusText || "").trim().toLowerCase();
  if (status !== "on" && status !== "off") return false;
  codexFastModeState = {
    ...codexFastModeState,
    available: true,
    enabled: status === "on",
    statusKnown: true,
  };
  codexFastModeLoaded = true;
  codexFastModeNotice = "";
  renderCodexFastModeControl();
  if (status === "on" && !isOptionalFeatureEnabled("codexFastMode")) {
    const tabContext = activeTabContext();
    queueMicrotask(() => refreshCodexFastMode(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(`Disabled Codex Fast mode could not be disarmed: ${error.message || String(error)}`, "error");
    }));
  }
  return true;
}

async function refreshCodexFastMode(tabContext = activeTabContext()) {
  if (!elements.codexFastModeSelect || !tabContext.tabId) return codexFastModeState;
  const featureEnabled = isOptionalFeatureEnabled("codexFastMode");
  try {
    let response = await api("/api/codex-fast-mode", { tabId: tabContext.tabId });
    let data = response.data || {};
    // Browser disable is global while extension state is session/branch local. Keep querying even
    // when hidden and disarm a restored branch before it can silently remain on.
    if (!featureEnabled && data.available && !codexFastModeConfirmedOff(data)) {
      if (data.busy) throw new Error("this tab is busy; Fast mode will be disarmed when it becomes idle");
      response = await api("/api/codex-fast-mode", { method: "PUT", body: { enabled: false }, tabId: tabContext.tabId });
      data = response.data || {};
      if (!codexFastModeConfirmedOff(data)) throw new Error("the extension did not confirm Fast mode off");
    }
    if (!isCurrentTabContext(tabContext)) return codexFastModeState;
    applyCodexFastModeData(data);
    codexFastModeNotice = "";
  } catch (error) {
    if (!isCurrentTabContext(tabContext)) return codexFastModeState;
    codexFastModeState = { ...codexFastModeState, available: false, busy: false, unavailableReason: `Codex Fast mode unavailable: ${error.message || String(error)}.` };
    if (!featureEnabled) throw error;
  } finally {
    if (isCurrentTabContext(tabContext)) {
      codexFastModeLoaded = true;
      renderCodexFastModeControl();
    }
  }
  return codexFastModeState;
}

async function applyCodexFastMode() {
  if (!elements.codexFastModeSelect || codexFastModeBusy) return;
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  const enabled = elements.codexFastModeSelect.value === "fast";
  if (enabled === codexFastModeState.enabled) return;
  codexFastModeBusy = true;
  codexFastModeNotice = "";
  renderCodexFastModeControl({ syncSelection: false });
  try {
    const response = await api("/api/codex-fast-mode", { method: "PUT", body: { enabled }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    applyCodexFastModeData(response.data);
    addEvent(enabled
      ? "Codex Fast mode requested for this session. It asks supported Codex models for about 1.5x faster responses and may spend 2x credits on GPT-5.4 or 2.5x on GPT-5.5/5.6."
      : "Codex Fast mode turned off for this session; requests return to the standard tier.", "info");
  } catch (error) {
    if (!isCurrentTabContext(tabContext)) return;
    codexFastModeNotice = `Failed to change Codex Fast mode: ${error.message || String(error)}. You can retry.`;
    addEvent(codexFastModeNotice, "error");
  } finally {
    codexFastModeBusy = false;
    if (isCurrentTabContext(tabContext)) renderCodexFastModeControl();
  }
}

// Optional-features Disable is browser-global while Fast mode is tab/session scoped. Disarm every
// live tab first and abort the browser-side disable if any armed or unknown instance cannot confirm
// off. Future branch restores are handled by refreshCodexFastMode even while the control is hidden.
async function disableCodexFastModeIntegration() {
  const tabIds = [...new Set(tabs.filter((tab) => tab?.id && tab.running !== false).map((tab) => tab.id))];
  const snapshots = await Promise.all(tabIds.map(async (tabId) => {
    const response = await api("/api/codex-fast-mode", { tabId });
    return { tabId, data: response.data || {} };
  }));

  for (const { tabId, data } of snapshots) {
    if (!data.available) {
      if (data.statusKnown && data.enabled) throw new Error(`tab ${tabId} still reports Fast mode on but /fast-mode is unavailable`);
      continue;
    }
    if (data.busy && !codexFastModeConfirmedOff(data)) throw new Error(`tab ${tabId} is busy; wait for it to finish before disabling Codex Fast mode`);
  }

  for (const { tabId, data } of snapshots) {
    if (!data.available || codexFastModeConfirmedOff(data)) continue;
    const response = await api("/api/codex-fast-mode", { method: "PUT", body: { enabled: false }, tabId });
    if (!codexFastModeConfirmedOff(response.data)) throw new Error(`tab ${tabId} did not confirm Codex Fast mode off`);
    if (tabId === activeTabId) applyCodexFastModeData(response.data);
  }
}

function scheduleRefreshCodexUsage(delay = CODEX_USAGE_REFRESH_MS) {
  clearTimeout(refreshCodexUsageTimer);
  refreshCodexUsageTimer = setTimeout(() => {
    refreshCodexUsage().finally(() => scheduleRefreshCodexUsage());
  }, delay);
}

function initializeCodexUsage() {
  renderCodexUsage();
  refreshCodexUsage().finally(() => scheduleRefreshCodexUsage());
  clearInterval(codexUsageRenderTimer);
  codexUsageRenderTimer = setInterval(renderCodexUsage, CODEX_USAGE_RENDER_TICK_MS);
}

function claudeUsageWindowFromProvider(window, capturedAt) {
  if (!window) return null;
  const resetAt = Number(window.resetAt);
  const resetAfterSeconds = Number(window.resetAfterSeconds);
  const resetsAt = Number.isFinite(resetAt) && resetAt >= 0
    ? new Date(resetAt).toISOString()
    : Number.isFinite(resetAfterSeconds) && resetAfterSeconds >= 0
      ? new Date(capturedAt + resetAfterSeconds * 1000).toISOString()
      : undefined;
  return {
    label: window.label || "Usage window",
    usedPercent: window.usedPercent,
    ...(Number.isFinite(window.windowMinutes) ? { windowMinutes: window.windowMinutes } : {}),
    ...(resetsAt ? { resetsAt } : {}),
  };
}

function claudeUsageFromGitFooterPayload(payload = parseGitFooterWebuiPayload()) {
  const providerUsage = payload?.providerUsage;
  if (providerUsage?.provider !== "anthropic") return null;
  const capturedAt = Number(providerUsage.capturedAt);
  if (!Number.isFinite(capturedAt) || capturedAt <= 0) return null;
  const windows = [providerUsage.primary, providerUsage.secondary]
    .map((window) => claudeUsageWindowFromProvider(window, capturedAt))
    .filter(Boolean);
  if (windows.length === 0) return null;
  return {
    available: true,
    providerId: "claude-code",
    source: "git-footer-status-provider-headers",
    fetchedAt: new Date(capturedAt).toISOString(),
    summary: "Live Anthropic subscription usage from provider response headers.",
    windows,
    activityTitle: "",
    activity: [],
    notes: [],
  };
}

function syncClaudeUsageFromGitFooterPayload(payload = parseGitFooterWebuiPayload()) {
  const usage = claudeUsageFromGitFooterPayload(payload);
  if (!usage) return false;
  latestClaudeUsage = usage;
  claudeUsageError = null;
  renderClaudeUsage();
  return true;
}

function claudeUsageResetDate(window) {
  const resetAt = window?.resetsAt ? new Date(window.resetsAt) : null;
  if (resetAt && Number.isFinite(resetAt.getTime())) return resetAt;
  const resetAfterSeconds = Number(window?.resetAfterSeconds);
  if (Number.isFinite(resetAfterSeconds) && resetAfterSeconds >= 0) return new Date(Date.now() + resetAfterSeconds * 1000);
  return null;
}

function formatClaudeUsageReset(window) {
  const resetDate = claudeUsageResetDate(window);
  if (resetDate) {
    const diff = resetDate.getTime() - Date.now();
    if (diff <= 0) return "resetting now";
    return `resets in ${formatDurationParts(diff)}`;
  }
  return window?.resetText ? `resets ${window.resetText}` : "reset unknown";
}

function renderClaudeUsageWindow(box, window, key = "") {
  const usedPercent = Number(window?.usedPercent);
  const fillPercent = Number.isFinite(usedPercent) ? Math.max(0, Math.min(100, usedPercent)) : 0;
  const item = make("div", "claude-usage-bucket");
  if (key) item.dataset.claudeUsageKey = key;
  const row = make("div", "claude-usage-row");
  row.append(
    make("span", "claude-usage-label", window?.label || "Usage window"),
    make("strong", "claude-usage-percent", formatCodexPercent(usedPercent)),
  );
  const meter = make("div", "claude-usage-meter");
  const fill = make("span", "claude-usage-meter-fill");
  fill.style.width = `${fillPercent}%`;
  meter.append(fill);
  item.append(row, meter, make("div", "claude-usage-reset", formatClaudeUsageReset(window)));
  box.append(item);
}

function renderClaudeUsageActivity(box, activity) {
  if (!Array.isArray(activity) || activity.length === 0) return;
  const title = make("div", "claude-usage-activity-title", latestClaudeUsage?.activityTitle || "What's contributing to your limits usage?");
  box.append(title);
  for (const item of activity.slice(0, 2)) {
    const group = make("div", "claude-usage-activity-group");
    const row = make("div", "claude-usage-row");
    row.append(
      make("span", "claude-usage-label", item.label || "Activity"),
      make("span", "claude-usage-reset", `${Number(item.requests || 0)} requests · ${Number(item.sessions || 0)} sessions`),
    );
    group.append(row);
    for (const detail of (Array.isArray(item.details) ? item.details : []).slice(0, 4)) {
      group.append(make("div", "claude-usage-detail", detail?.text || String(detail || "")));
    }
    box.append(group);
  }
}

function claudeUsageStructureSignature() {
  if (!latestClaudeUsage) return JSON.stringify({ state: claudeUsageLoading ? "loading" : claudeUsageError ? "error" : "empty", error: claudeUsageError?.message || String(claudeUsageError || "") });
  const windows = Array.isArray(latestClaudeUsage.windows) ? latestClaudeUsage.windows : [];
  return JSON.stringify({
    state: "data",
    summary: latestClaudeUsage.summary || "",
    windows: windows.slice(0, 6).map((window, index) => [String(window?.id || index), window?.label || "Usage window"]),
    activityTitle: latestClaudeUsage.activityTitle || "",
    activity: latestClaudeUsage.activity || [],
    error: claudeUsageError?.message || String(claudeUsageError || ""),
  });
}

function updateClaudeUsageValues(box, windows) {
  if (!latestClaudeUsage || !box.querySelector(".claude-usage-summary")) return false;
  const fetched = box.querySelector(".claude-usage-fetched");
  if (fetched) fetched.textContent = latestClaudeUsage.fetchedAt ? `updated ${formatDurationParts(Date.now() - new Date(latestClaudeUsage.fetchedAt).getTime())} ago` : "updated now";
  const rendered = [...box.querySelectorAll(".claude-usage-bucket[data-claude-usage-key]")];
  if (rendered.length !== windows.length) return false;
  for (const [index, window] of windows.entries()) {
    const key = String(window?.id || index);
    const item = rendered.find((node) => node.dataset.claudeUsageKey === key);
    if (!item) return false;
    const usedPercent = Number(window?.usedPercent);
    const fillPercent = Number.isFinite(usedPercent) ? Math.max(0, Math.min(100, usedPercent)) : 0;
    const percent = item.querySelector(".claude-usage-percent");
    const fill = item.querySelector(".claude-usage-meter-fill");
    const reset = item.querySelector(".claude-usage-reset");
    if (!percent || !fill || !reset) return false;
    percent.textContent = formatCodexPercent(usedPercent);
    fill.style.width = `${fillPercent}%`;
    reset.textContent = formatClaudeUsageReset(window);
  }
  return true;
}

function renderClaudeUsage() {
  const box = elements.claudeUsageBox;
  if (!box) return;
  if (elements.refreshClaudeUsageButton) {
    elements.refreshClaudeUsageButton.disabled = claudeUsageLoading;
    elements.refreshClaudeUsageButton.textContent = claudeUsageLoading ? "Refreshing…" : "Refresh usage";
  }

  const windows = Array.isArray(latestClaudeUsage?.windows) ? latestClaudeUsage.windows.slice(0, 6) : [];
  const structureSignature = claudeUsageStructureSignature();
  if (structureSignature === claudeUsageRenderSignature && updateClaudeUsageValues(box, windows)) {
    box.classList.toggle("muted", !latestClaudeUsage);
    return;
  }
  claudeUsageRenderSignature = structureSignature;
  box.replaceChildren();
  box.classList.toggle("muted", !latestClaudeUsage);

  if (!latestClaudeUsage && claudeUsageLoading) {
    box.textContent = "Checking Claude usage…";
    return;
  }
  if (!latestClaudeUsage && claudeUsageError) {
    const title = make("div", "claude-usage-unavailable", "Usage unavailable");
    const detail = make("div", "claude-usage-detail", claudeUsageError.message || String(claudeUsageError));
    box.append(title, detail);
    return;
  }
  if (!latestClaudeUsage) {
    box.textContent = "Claude usage has not loaded yet.";
    return;
  }

  const header = make("div", "claude-usage-summary");
  header.append(
    make("span", "claude-usage-plan", "Claude Code"),
    make("span", "claude-usage-fetched", latestClaudeUsage.fetchedAt ? `updated ${formatDurationParts(Date.now() - new Date(latestClaudeUsage.fetchedAt).getTime())} ago` : "updated now"),
  );
  box.append(header);

  if (latestClaudeUsage.summary) box.append(make("div", "claude-usage-detail", latestClaudeUsage.summary));
  if (windows.length === 0) {
    box.append(make("div", "claude-usage-detail", "No Claude usage windows were returned."));
  } else {
    for (const [index, window] of windows.entries()) renderClaudeUsageWindow(box, window, String(window?.id || index));
  }

  renderClaudeUsageActivity(box, latestClaudeUsage.activity);
  if (claudeUsageError) {
    box.append(make("div", "claude-usage-detail", `Latest refresh failed: ${claudeUsageError.message || claudeUsageError}`));
  }
}

async function refreshClaudeUsage({ forceCli = false } = {}) {
  if (!forceCli && syncClaudeUsageFromGitFooterPayload()) return;
  if (claudeUsageLoading) return;
  claudeUsageLoading = true;
  renderClaudeUsage();
  try {
    const response = await api("/api/claude-usage", { scoped: false });
    if (!forceCli && syncClaudeUsageFromGitFooterPayload()) return;
    latestClaudeUsage = response.data || null;
    claudeUsageError = null;
  } catch (error) {
    if (!forceCli && syncClaudeUsageFromGitFooterPayload()) return;
    claudeUsageError = error;
  } finally {
    claudeUsageLoading = false;
    renderClaudeUsage();
  }
}

function scheduleRefreshClaudeUsage(delay = CLAUDE_USAGE_REFRESH_MS) {
  clearTimeout(refreshClaudeUsageTimer);
  refreshClaudeUsageTimer = setTimeout(() => {
    refreshClaudeUsage().finally(() => scheduleRefreshClaudeUsage());
  }, delay);
}

function initializeClaudeUsage() {
  renderClaudeUsage();
  refreshClaudeUsage().finally(() => scheduleRefreshClaudeUsage());
  clearInterval(claudeUsageRenderTimer);
  claudeUsageRenderTimer = setInterval(renderClaudeUsage, CLAUDE_USAGE_RENDER_TICK_MS);
}

const SUBAGENT_LAUNCHER_LABELS = Object.freeze({
  sdk: "SDK", "pi-rpc": "Pi RPC", "pi-json": "Pi JSON", "pi-print": "Pi print",
  interactive: "Pi session", tmux: "tmux", "pi-subagents": "pi-subagents",
  schedule: "scheduled", gate: "gate", workflow: "workflow", custom: "custom",
});
const SUBAGENT_LIFECYCLE_STATES = new Set(["queued", "running", "stale", "lost", "done", "failed", "cancelled"]);

function subagentLauncherLabel(value = "") {
  const launcher = String(value || "").trim();
  return SUBAGENT_LAUNCHER_LABELS[launcher] || launcher || "agent";
}

function subagentAgentStatus(run = {}, agent = null) {
  const status = String(agent?.status || run?.status || "running").toLowerCase();
  return SUBAGENT_LIFECYCLE_STATES.has(status) ? status : status === "pending" ? "queued" : "running";
}

function subagentIsWorkflowController(run = {}, agent = {}) {
  if (String(agent?.name || "").trim().toLowerCase() !== "workflow") return false;
  if (String(agent?.model || "").trim() || String(agent?.thinking || "").trim()) return false;
  const launcher = String(agent?.launcher || run?.launcher || "").trim();
  const legacyProvisional = run?.source === "foreground" && /(?:^|:)workflow$/i.test(String(agent?.id || ""));
  return launcher === "pi-subagents" || legacyProvisional;
}

function subagentWorkflowController(run = {}) {
  return (Array.isArray(run?.agents) ? run.agents : []).find((agent) => subagentIsWorkflowController(run, agent)) || null;
}

function subagentRunAgents(run = {}) {
  const controller = subagentWorkflowController(run);
  return (Array.isArray(run?.agents) ? run.agents : []).filter((agent) => agent !== controller);
}

function subagentRunAgentCounts(runs = []) {
  return (Array.isArray(runs) ? runs : []).reduce((counts, run) => {
    for (const agent of subagentRunAgents(run)) {
      counts.total += 1;
      const status = subagentAgentStatus(run, agent);
      if (status === "running") counts.running += 1;
      if (status === "stale") counts.stale += 1;
    }
    return counts;
  }, { total: 0, running: 0, stale: 0 });
}

function subagentRunPresentations(runs = []) {
  const presentations = [];
  let recoveredWorkflow = null;
  for (const run of Array.isArray(runs) ? runs : []) {
    const controller = subagentWorkflowController(run);
    const agents = subagentRunAgents(run).map((agent) => ({ run, agent }));
    if (controller) {
      const presentation = { run, controller, agents };
      presentations.push(presentation);
      const launcher = String(controller?.launcher || run?.launcher || "").trim();
      recoveredWorkflow = run?.source === "recovered" && launcher === "pi-subagents" ? presentation : null;
      continue;
    }
    const launcher = String(run?.launcher || "").trim();
    if (recoveredWorkflow && run?.source === "recovered" && launcher === "pi-subagents" && agents.length) {
      recoveredWorkflow.agents.push(...agents);
      continue;
    }
    recoveredWorkflow = null;
    presentations.push({ run, controller: null, agents });
  }
  return presentations;
}

function subagentWorkflowPresentationStatus(run = {}, agents = []) {
  const statuses = [subagentAgentStatus(run), ...(Array.isArray(agents) ? agents : []).map((entry) => subagentAgentStatus(entry.run, entry.agent))];
  return ["running", "queued", "stale", "lost", "failed", "cancelled", "done"].find((status) => statuses.includes(status)) || "running";
}

function subagentCapabilities(run = {}, agent = null) {
  const agentCapabilities = agent?.capabilities && typeof agent.capabilities === "object" ? agent.capabilities : null;
  const runCapabilities = run?.capabilities && typeof run.capabilities === "object" ? run.capabilities : null;
  return agentCapabilities || runCapabilities || null;
}

function subagentOverviewGroups(data = latestSubagents) {
  const serverNow = Number(data?.updatedAt);
  const now = Number.isFinite(serverNow) ? serverNow : Date.now();
  if (Number(data?.version) === 2 && Array.isArray(data?.groups)) {
    const legacyTabs = new Map((Array.isArray(data.tabs) ? data.tabs : []).map((tab) => [tab.tabId, tab]));
    return data.groups.map((group, index) => {
      const legacy = legacyTabs.get(group.tabId) || {};
      const gates = visibleSubagentGates({ ...legacy, gates: group.gates || legacy.gates || [] }, dismissedSubagentGateKeys, now);
      const runs = Array.isArray(group.runs) ? group.runs : [];
      const agentCounts = subagentRunAgentCounts(runs);
      return {
        ...legacy,
        ...group,
        groupId: group.id,
        groupKind: group.kind,
        tabId: group.tabId || activeTabId || "external",
        tabIndex: group.tabIndex || legacy.tabIndex || index + 1,
        tabTitle: group.title || legacy.tabTitle || (group.kind === "external" ? "External agents" : `Terminal ${index + 1}`),
        sessionName: group.cwdLabel || legacy.sessionName || "registered agents",
        available: true,
        gates,
        gateCount: gates.length,
        displayRuns: runs,
        agentCount: agentCounts.total,
        runningAgents: agentCounts.running,
        staleAgents: agentCounts.stale,
      };
    });
  }
  return (Array.isArray(data?.tabs) ? data.tabs : []).map((tab) => {
    const gates = visibleSubagentGates(tab, dismissedSubagentGateKeys, now);
    const displayRuns = ungatedSubagentRuns(tab);
    const agentCounts = subagentRunAgentCounts(displayRuns);
    return {
      ...tab,
      groupId: `tab:${tab.tabId}`,
      groupKind: "tab",
      gates,
      gateCount: gates.length,
      displayRuns,
      agentCount: agentCounts.total,
      runningAgents: agentCounts.running,
      staleAgents: agentCounts.stale,
    };
  });
}

function subagentTabsWithRunningAgents() {
  return subagentOverviewGroups()
    .filter((tab) => tab.displayRuns.length > 0 || Number(tab?.gateCount || 0) > 0)
    .sort((a, b) => Number(a.tabIndex || 0) - Number(b.tabIndex || 0) || String(a.tabTitle || "").localeCompare(String(b.tabTitle || "")));
}

function subagentSessionFileName(value) {
  return String(value || "").split(/[\\/]/).filter(Boolean).pop() || "";
}

function subagentTabMeta(tab) {
  const sessionName = String(tab?.sessionName || "").trim();
  const title = String(tab?.tabTitle || "").trim();
  if (sessionName && sessionName !== title) return sessionName;
  return subagentSessionFileName(tab?.sessionFile) || normalizeDisplayPath(tab?.cwd || "") || "session";
}

function subagentRunElapsed(run) {
  const startedAt = Number(run?.startedAt);
  return Number.isFinite(startedAt) ? formatDuration(Math.max(0, Date.now() - startedAt)) : "";
}

function subagentSourceLabel(source = "") {
  if (source === "recovered") return "recovered active child";
  return source === "foreground" || source === "workflow" ? source : "async";
}

function subagentRunSupportsInteraction(run = {}) {
  return run?.source !== "recovered" && run?.provisional !== true && run?.controllable !== false;
}

function subagentExecutionValues(agent = {}) {
  const thinking = String(agent?.thinking || "").trim();
  let model = String(agent?.model || "").trim();
  const suffixIndex = model.lastIndexOf(":");
  if (thinking && suffixIndex > model.indexOf("/") && model.slice(suffixIndex + 1).toLowerCase() === thinking.toLowerCase()) {
    model = model.slice(0, suffixIndex);
  }
  return [model || "unknown", thinking || "unknown"];
}

function subagentExecutionFacts(agent = {}) {
  const [model, thinking] = subagentExecutionValues(agent);
  return [`model ${model}`, `reasoning ${thinking}`];
}

function subagentGateAttemptViewFacts(attempt) {
  if (!attempt) return [];
  return [
    `gate attempt ${attempt.attempt || 1}/${attempt.maxAttempts || 1}`,
    attempt.phase ? `phase ${attempt.phase}` : "",
    attempt.failureKind ? `failure ${attempt.failureKind}` : "",
    attempt.error ? `gate error ${attempt.error}` : "",
  ].filter(Boolean);
}

function subagentRunIsRunning(run = {}, agent = null) {
  return ["queued", "running"].includes(subagentAgentStatus(run, agent));
}

function subagentRunIsTerminal(run = {}, agent = null) {
  return ["done", "failed", "cancelled"].includes(subagentAgentStatus(run, agent));
}

function subagentRunIsAttachedProjection(run = {}) {
  return run?.provider === "webui-registry"
    && run?.source === "explicit-attach"
    && ["stale", "lost"].includes(subagentAgentStatus(run));
}

function subagentRunCanOpen(run = {}, agent = null) {
  const capabilities = subagentCapabilities(run, agent);
  return capabilities ? capabilities.open === true : subagentRunSupportsInteraction(run);
}

function subagentRunCanRefresh(run = {}, agent = null) {
  const capabilities = subagentCapabilities(run, agent);
  return capabilities ? capabilities.refresh === true : subagentRunSupportsInteraction(run);
}

function subagentRunCanCancel(run = {}, agent = null) {
  const capabilities = subagentCapabilities(run, agent);
  return capabilities ? capabilities.cancel === true && subagentRunIsRunning(run, agent) : subagentRunSupportsInteraction(run) && run?.source !== "workflow" && subagentRunIsRunning(run, agent);
}

function subagentRunCanDismiss(run = {}) {
  if (subagentRunIsAttachedProjection(run)) return true;
  if (!subagentRunIsTerminal(run)) return false;
  if (run?.provider === "webui-registry") return true;
  const capabilities = subagentCapabilities(run);
  return capabilities ? capabilities.open === true && ["webui-helper", "pi-subagents"].includes(run.provider) : run?.source !== "workflow" && subagentRunSupportsInteraction(run);
}

function subagentRunStateLabel(run = {}, agent = null) {
  const status = subagentAgentStatus(run, agent);
  return status === "cancelled" ? "cancelled" : status;
}

function setSubagentCancelStatus(message = "", level = "muted") {
  if (!elements.subagentCancelStatus) return;
  elements.subagentCancelStatus.textContent = message;
  elements.subagentCancelStatus.className = `subagent-cancel-status ${message ? level : "muted"}`;
  elements.subagentCancelStatus.hidden = !message;
}

function setSubagentCancelSubmitting(submitting) {
  subagentCancelSubmitting = !!submitting;
  if (elements.subagentCancelSubmitButton) {
    elements.subagentCancelSubmitButton.disabled = subagentCancelSubmitting;
    elements.subagentCancelSubmitButton.textContent = subagentCancelSubmitting ? "Cancelling…" : "Cancel subagent";
  }
  if (elements.subagentCancelKeepRunningButton) elements.subagentCancelKeepRunningButton.disabled = subagentCancelSubmitting;
}

function subagentCancelTargetLabel(selection = subagentCancelSelection) {
  if (!selection) return "subagent run";
  return `run ${selection.runId}`;
}

function openSubagentCancelDialog(tab, run, agent = null) {
  if (!tab?.groupId || !run?.id || !subagentRunCanCancel(run, agent) || !elements.subagentCancelDialog) return;
  const agentCount = subagentRunAgents(run).length;
  subagentCancelSelection = {
    groupId: tab.groupId,
    tabId: tab.tabId,
    runId: run.id,
    agentId: agent?.instanceId || agent?.id || "",
    agentCount,
  };
  if (elements.subagentCancelDialogSubtitle) {
    const scope = agentCount > 1 ? ` and all ${agentCount} agents in it` : "";
    elements.subagentCancelDialogSubtitle.textContent = `Cancel ${subagentCancelTargetLabel()}${scope}? The entire run will be stopped and the parent agent will be notified.`;
  }
  if (elements.subagentCancelReason) elements.subagentCancelReason.value = "";
  if (elements.subagentCancelNote) elements.subagentCancelNote.value = "";
  setSubagentCancelStatus();
  setSubagentCancelSubmitting(false);
  if (!elements.subagentCancelDialog.open) elements.subagentCancelDialog.showModal();
  queueMicrotask(() => elements.subagentCancelReason?.focus());
}

function closeSubagentCancelDialog() {
  if (subagentCancelSubmitting) return;
  if (elements.subagentCancelDialog?.open) elements.subagentCancelDialog.close();
}

async function submitSubagentCancel() {
  const selection = subagentCancelSelection;
  if (!selection || subagentCancelSubmitting) return;
  const reason = String(elements.subagentCancelReason?.value || "").trim();
  const note = String(elements.subagentCancelNote?.value || "").trim();
  setSubagentCancelSubmitting(true);
  setSubagentCancelStatus("Cancelling subagent…");
  try {
    await api("/api/subagents/cancel", {
      method: "POST",
      scoped: false,
      body: {
        group: selection.groupId,
        runId: selection.runId,
        ...(selection.agentId ? { agentId: selection.agentId } : {}),
        ...(reason ? { reason } : {}),
        ...(note ? { note } : {}),
      },
    });
    if (elements.subagentCancelDialog?.open) elements.subagentCancelDialog.close();
    addEvent(`cancelled ${subagentCancelTargetLabel(selection)}; the parent agent was notified`, "info");
    await refreshSubagents();
    scheduleRefreshSubagents();
  } catch (error) {
    const message = `subagent cancel failed: ${error.message || String(error)}`;
    setSubagentCancelStatus(message, "error");
    addEvent(message, "error");
  } finally {
    setSubagentCancelSubmitting(false);
  }
}

async function dismissSubagentRun(tab, run) {
  if (!tab?.groupId || !run?.id || !subagentRunCanDismiss(run)) return;
  const attachedProjection = subagentRunIsAttachedProjection(run);
  try {
    await api("/api/subagents/dismiss", {
      method: "POST",
      scoped: false,
      body: { group: tab.groupId, runId: run.id },
    });
    addEvent(attachedProjection ? `detached persisted session projection ${run.id}` : `dismissed finished subagent run ${run.id}`, "info");
    await refreshSubagents();
    scheduleRefreshSubagents();
  } catch (error) {
    addEvent(`subagent dismiss failed: ${error.message || String(error)}`, "error");
  }
}

function finishedSubagentRunSelections(data = latestSubagents) {
  return subagentOverviewGroups(data).flatMap((tab) => tab.displayRuns
    .filter((run) => subagentRunIsTerminal(run) && subagentRunCanDismiss(run))
    .map((run) => ({ groupId: tab.groupId, runId: run.id }))
    .filter((selection) => selection.groupId && selection.runId));
}

async function clearFinishedSubagentRuns({ automatic = false } = {}) {
  if (subagentsClearingFinished || subagentsLoading) return;
  const selections = finishedSubagentRunSelections();
  if (!selections.length) return;
  clearTimeout(refreshSubagentsTimer);
  subagentsClearingFinished = true;
  renderSubagents();
  let dismissed = 0;
  const failures = [];
  try {
    for (const selection of selections) {
      try {
        await api("/api/subagents/dismiss", {
          method: "POST",
          scoped: false,
          body: { group: selection.groupId, runId: selection.runId },
        });
        dismissed += 1;
      } catch (error) {
        failures.push(error);
      }
    }
    await refreshSubagents();
  } finally {
    subagentsClearingFinished = false;
    renderSubagents();
    scheduleRefreshSubagents();
  }
  if (dismissed) {
    if (automatic) {
      addEvent("auto-cleared", "info", {
        aggregateKey: "subagent-auto-clear",
        aggregateIncrement: dismissed,
        aggregateSingular: "finished subagent run",
        aggregatePlural: "finished subagent runs",
      });
    } else {
      addEvent(`cleared ${dismissed} finished subagent ${dismissed === 1 ? "run" : "runs"}`, "info");
    }
  }
  if (failures.length) addEvent(`could not ${automatic ? "auto-clear" : "clear"} ${failures.length} finished subagent ${failures.length === 1 ? "run" : "runs"}`, "warn");
}

function subagentOverlayTranscriptMessages(data = subagentOverlayData) {
  const agent = data?.agent || subagentOverlaySelection?.agent || {};
  return (Array.isArray(agent.transcript) ? agent.transcript : [])
    .filter((message) => message && (message.role === "assistant" || message.role === "toolResult"));
}

function subagentOverlayToolArguments(value) {
  if (typeof value !== "string") return value;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" ? parsed : value;
  } catch {
    return value;
  }
}

function subagentOverlayTranscriptDisplayMessages(messages, { includeThinking = thinkingOutputVisible } = {}) {
  const toolResults = buildToolResultMap(messages);
  const pairedToolCallIds = buildAssistantToolCallIdSet(messages);
  const displayMessages = [];
  for (const message of messages) {
    if (message.role === "toolResult") {
      if (pairedToolCallIds.has(toolResultCallId(message))) continue;
      displayMessages.push(message);
      continue;
    }
    for (const displayMessage of assistantDisplayMessages(message)) {
      if (displayMessage.role === "thinking" && !includeThinking) continue;
      if (displayMessage.role === "toolCall" && displayMessage.toolCallId) {
        const result = toolResults.get(displayMessage.toolCallId) || null;
        displayMessages.push({
          ...displayMessage,
          role: "toolExecution",
          title: `tool: ${displayMessage.toolName || "unknown"}`,
          arguments: subagentOverlayToolArguments(displayMessage.arguments),
          result,
          isError: !!result?.isError,
        });
      } else {
        displayMessages.push(displayMessage);
      }
    }
  }
  return displayMessages;
}

function subagentOverlayTranscriptOutputLines(data = subagentOverlayData) {
  return subagentOverlayTranscriptDisplayMessages(subagentOverlayTranscriptMessages(data)).flatMap((message) => stripAnsi(
    messageCopyText(message),
  ).replace(/\r/g, "").split("\n"));
}

function subagentOverlayOutputLines(data = subagentOverlayData) {
  const agent = data?.agent || subagentOverlaySelection?.agent || {};
  const transcriptMessages = subagentOverlayTranscriptMessages(data);
  if (transcriptMessages.length) return subagentOverlayTranscriptOutputLines(data);
  const output = (Array.isArray(agent.recentOutput) ? agent.recentOutput : [])
    .flatMap((line) => stripAnsi(String(line ?? "")).replace(/\r/g, "").split("\n"));
  if (output.length) return output;
  const tools = (Array.isArray(agent.recentTools) ? agent.recentTools : [])
    .map((entry) => `✓ ${entry.tool || "tool"}${entry.args ? ` ${entry.args}` : ""}`);
  if (agent.currentTool) tools.push(`▶ ${agent.currentTool}${agent.currentToolArgs ? ` ${agent.currentToolArgs}` : ""}`);
  return tools;
}

function subagentOverlayOutputText(data = subagentOverlayData) {
  return subagentOverlayOutputLines(data).join("\n").trimEnd();
}

function subagentOverlayEmptyTranscriptText(messages) {
  const hasThinking = messages.some((message) => message.role === "assistant" && assistantDisplayMessages(message)
    .some((displayMessage) => displayMessage.role === "thinking"));
  return hasThinking && !thinkingOutputVisible
    ? "Thinking output is hidden. Enable thinking output to view the captured transcript."
    : "No visible output was captured.";
}

function subagentRunIndicatorActivity(agent = {}) {
  const currentTool = cleanStatusText(agent.currentTool || "");
  const currentToolArgs = cleanStatusText(agent.currentToolArgs || "");
  const activityState = cleanStatusText(agent.activityState || "");
  return currentTool
    ? `${currentTool}${currentToolArgs ? ` · ${currentToolArgs}` : ""}`
    : activityState || "Waiting for output or action…";
}

function updateSubagentRunIndicatorElapsed(parent, run) {
  const elapsedNode = parent?.querySelector?.(".subagent-run-indicator-elapsed");
  if (!elapsedNode) return false;
  const elapsed = subagentRunElapsed(run);
  const text = elapsed ? `· run time ${elapsed}` : "";
  if (elapsedNode.textContent !== text) elapsedNode.textContent = text;
  return true;
}

function appendSubagentRunIndicator(parent, { agent = {}, run } = {}) {
  const bubble = make("article", "message runIndicator run-indicator-message streaming subagent-run-indicator");
  bubble.setAttribute("role", "status");
  bubble.setAttribute("aria-live", "polite");
  bubble.setAttribute("aria-label", "Agent is running:");
  const body = make("div", "message-body");
  const row = make("div", "run-indicator-row");
  const pulse = make("span", "run-indicator-pulse");
  pulse.setAttribute("aria-hidden", "true");
  const headline = make("span", "run-indicator-text", "Agent is running:");
  const activity = make("span", "run-indicator-meta", subagentRunIndicatorActivity(agent));
  const elapsed = make("span", "run-indicator-meta subagent-run-indicator-elapsed");
  elapsed.setAttribute("aria-hidden", "true");
  row.append(pulse, headline, activity, elapsed);
  body.append(row);
  bubble.append(body);
  parent.append(bubble);
  updateSubagentRunIndicatorElapsed(parent, run);
}

function appendSubagentOverlayTranscript(parent, messages) {
  let rendered = 0;
  for (const displayMessage of subagentOverlayTranscriptDisplayMessages(messages)) {
    const { bubble } = createMessageBubble(displayMessage, { transient: true });
    bubble.classList.add("subagent-overlay-message");
    parent.append(bubble);
    rendered += 1;
  }
  return rendered;
}

function subagentOverlayStateFacts(data = subagentOverlayData) {
  const agent = data?.agent || subagentOverlaySelection?.agent || {};
  const run = subagentOverlaySelection?.run || {};
  return [
    subagentRunIsRunning(run, agent) ? agent.status || "running" : subagentRunStateLabel(run),
    data?.mode || run.mode,
    subagentSourceLabel(data?.source || run.source),
    agent.nested ? "nested" : "",
    ...subagentExecutionFacts(agent),
    ...subagentGateAttemptViewFacts(subagentOverlaySelection?.gateAttempt),
    agent.currentTool ? `tool ${agent.currentTool}` : "",
    Number.isFinite(agent.turnCount) ? `${agent.turnCount} turns` : "",
    Number.isFinite(agent.toolCount) ? `${agent.toolCount} tools` : "",
    Number.isFinite(agent.tokens) ? `${Number(agent.tokens).toLocaleString()} tokens` : "",
  ].filter(Boolean);
}

function subagentOverlayMeaningfulSignature() {
  return JSON.stringify({
    selection: subagentOverlaySelection ? {
      tabId: subagentOverlaySelection.tabId,
      runId: subagentOverlaySelection.runId,
      agentId: subagentOverlaySelection.agentId,
      finished: subagentOverlaySelection.finished === true,
    } : null,
    data: subagentOverlayData ? { ...subagentOverlayData, updatedAt: undefined } : null,
    error: subagentOverlayError,
  });
}

function renderSubagentOverlayErrorWidget() {
  const widget = make("section", "widget release-npm-widget app-runner-widget subagent-overlay-widget app-runner-log-widget");
  widget.setAttribute("aria-label", "Subagent output rendering error");
  const header = make("div", "release-npm-header");
  const titleWrap = make("div", "release-npm-title-wrap");
  titleWrap.append(make("strong", "release-npm-title", "Subagent output unavailable"));
  header.append(titleWrap);
  const body = make("div", "message-body");
  appendText(body, "The live subagent output could not be rendered. Close this panel and reopen it to retry.");
  const controls = make("div", "release-npm-controls subagent-overlay-output-controls");
  const actions = make("div", "app-runner-output-actions");
  actions.append(appRunnerActionButton("Close", closeSubagentOverlay, "subagent-overlay-close-action"));
  controls.append(actions);
  widget.append(header, body, controls);
  return widget;
}

function renderSubagentOverlayWidgetSafely() {
  try {
    return renderSubagentOverlayWidget();
  } catch {
    // Keep a faulty child transcript from preventing all other widgets from
    // rendering. The recoverable panel below replaces repeated event logging.
    return renderSubagentOverlayErrorWidget();
  }
}

function renderSubagentOverlayWidget() {
  const selection = subagentOverlaySelection;
  if (!selection || selection.tabId !== activeTabId) return null;
  const data = subagentOverlayData;
  const agent = data?.agent || selection.agent || {};
  const tab = tabs.find((item) => item.id === selection.tabId) || selection.tab;
  const running = !selection.finished && subagentRunIsRunning(selection.run, agent);
  const transcriptMessages = subagentOverlayTranscriptMessages(data);
  const hasStructuredTranscript = transcriptMessages.length > 0;
  const outputText = subagentOverlayOutputText(data);
  const fallbackText = outputText || agent.unavailableReason || (agent.unavailable ? "Output is unavailable for this registered agent." : running && agent.currentTool ? "" : running ? "Waiting for the first agent activity…" : "No recent output was captured.");
  const shownLineCount = outputText ? outputText.split("\n").length : fallbackText ? fallbackText.split("\n").length : 0;
  const widget = make("section", `widget release-npm-widget app-runner-widget subagent-overlay-widget${running ? " app-runner-live-widget" : " app-runner-log-widget"}`);
  widget.setAttribute("aria-label", `Live output for subagent ${agent.name || "subagent"}`);

  const header = make("div", "release-npm-header");
  const titleWrap = make("div", "release-npm-title-wrap");
  titleWrap.append(make("span", "release-npm-kicker", "subagent"), make("strong", "release-npm-title", agent.name || "subagent"));
  const meta = make("div", "release-npm-meta");
  for (const fact of subagentOverlayStateFacts(data)) meta.append(make("span", "release-npm-pill", fact));
  header.append(titleWrap, meta);

  const streamHeader = releaseNpmStreamHeader(running ? "Live agent output" : "Agent output", shownLineCount, { live: running });
  const output = make("div", "subagent-overlay-transcript");
  output.setAttribute("role", "log");
  output.setAttribute("aria-live", running ? "polite" : "off");
  const renderedTranscriptMessages = appendSubagentOverlayTranscript(output, transcriptMessages);
  const emptyTranscriptFallback = hasStructuredTranscript && renderedTranscriptMessages === 0
    ? subagentOverlayEmptyTranscriptText(transcriptMessages)
    : "";
  const visibleFallbackText = !hasStructuredTranscript ? fallbackText : emptyTranscriptFallback;
  if (visibleFallbackText) {
    const { bubble } = createMessageBubble({
      role: "assistant",
      title: "final output",
      timestamp: data?.updatedAt || Date.now(),
      content: visibleFallbackText,
    }, { streaming: running && !hasStructuredTranscript, transient: true });
    bubble.classList.add("subagent-overlay-message", "subagent-overlay-empty-fallback");
    output.append(bubble);
  }
  if (running) appendSubagentRunIndicator(output, { agent, run: selection.run });

  const controls = make("div", "release-npm-controls subagent-overlay-output-controls");
  const actions = make("div", "app-runner-output-actions");
  const copyButton = appRunnerActionButton("Copy output", copySubagentOverlayOutput, "subagent-overlay-copy-action");
  copyButton.disabled = !outputText;
  const refreshButton = appRunnerActionButton(subagentOverlayLoading ? "Refreshing…" : "Refresh", () => {
    refreshSubagentOverlay().finally(() => scheduleSubagentOverlayRefresh());
  }, "subagent-overlay-refresh-action");
  refreshButton.disabled = subagentOverlayLoading || selection.finished;
  if (subagentRunCanCancel(selection.run, agent)) {
    actions.append(appRunnerActionButton("Cancel…", () => openSubagentCancelDialog(selection.tab, selection.run, agent), "subagent-overlay-cancel-action danger"));
  }
  actions.append(copyButton);
  if (subagentRunCanRefresh(selection.run, agent)) actions.append(refreshButton);
  actions.append(appRunnerActionButton("Close", closeSubagentOverlay, "subagent-overlay-close-action"));
  const details = [
    `${selection.tab?.tabTitle || tab?.title || `Terminal ${selection.tabIndex || "?"}`} · run ${selection.runId}`,
    agent.currentPath ? `path: ${agent.currentPath}` : "",
    agent.activityState ? `activity: ${agent.activityState}` : "",
    agent.error ? `status warning: ${agent.error}` : "",
    subagentOverlayError,
  ].filter(Boolean);
  controls.append(actions, make("span", `app-runner-output-meta${subagentOverlayError ? " warning" : ""}`, details.join(" · ")));
  const outputDetails = renderReleaseNpmOutputDetails(`subagent:${selection.tabId}:${selection.agentId}`, streamHeader, output, controls);
  const scrollKey = `subagent-overlay:${selection.tabId}:${selection.runId}:${selection.agentId}`;
  bindScopedScrollContinuity(output, scrollKey);
  widget.append(header, outputDetails);
  restoreScopedScrollContinuity(output, scrollKey);
  return widget;
}

function scheduleSubagentOverlayRefresh(delay = SUBAGENT_OVERLAY_REFRESH_MS) {
  clearTimeout(subagentOverlayRefreshTimer);
  const agent = subagentOverlayData?.agent || subagentOverlaySelection?.agent || null;
  if (!subagentOverlaySelection || subagentOverlaySelection.finished || !subagentRunIsRunning(subagentOverlaySelection.run, agent)) return;
  subagentOverlayRefreshTimer = setTimeout(() => {
    refreshSubagentOverlay().finally(() => scheduleSubagentOverlayRefresh());
  }, delay);
}

async function refreshSubagentOverlay() {
  const selection = subagentOverlaySelection;
  if (!selection || subagentOverlayLoading) return;
  const requestSerial = ++subagentOverlayRequestSerial;
  const previousSignature = subagentOverlayMeaningfulSignature();
  subagentOverlayLoading = true;
  try {
    const query = new URLSearchParams({ group: selection.groupId, run: selection.runId, agent: selection.agentId });
    const response = await api(`/api/subagents/output?${query}`, { scoped: false });
    if (requestSerial !== subagentOverlayRequestSerial || subagentOverlaySelection !== selection) return;
    subagentOverlayData = response.data || null;
    subagentOverlayError = "";
  } catch (error) {
    if (requestSerial !== subagentOverlayRequestSerial || subagentOverlaySelection !== selection) return;
    if (error?.statusCode === 404) selection.finished = true;
    subagentOverlayError = error?.statusCode === 404
      ? "This subagent has finished or is no longer tracked. Showing the last captured output."
      : `Subagent output refresh failed: ${error.message || String(error)}`;
  } finally {
    if (requestSerial === subagentOverlayRequestSerial && subagentOverlaySelection === selection) {
      subagentOverlayLoading = false;
      if (selection.tabId === activeTabId && previousSignature !== subagentOverlayMeaningfulSignature()) renderWidgets();
    }
  }
}

async function openSubagentOverlay(tab, run, agent) {
  if (!tab?.groupId || !run?.id || !agent?.id || !subagentRunCanOpen(run, agent)) return;
  if (activeSubagentTerminalId) deactivateSubagentTerminalView({ render: false });
  try {
    if (activeTabId !== tab.tabId) await switchTab(tab.tabId);
    subagentOverlaySelection = {
      groupId: tab.groupId,
      tabId: tab.tabId,
      tabIndex: tab.tabIndex,
      tab,
      run,
      agent,
      runId: run.id,
      agentId: agent.id,
      gateAttempt: run.gateAttempt || null,
      finished: false,
    };
    subagentOverlayData = null;
    subagentOverlayError = "";
    subagentOverlayRequestSerial += 1;
    renderWidgets();
    await refreshSubagentOverlay();
    scheduleSubagentOverlayRefresh();
  } catch (error) {
    addEvent(`could not open subagent output: ${error.message || String(error)}`, "error");
  }
}

function closeSubagentOverlay() {
  clearTimeout(subagentOverlayRefreshTimer);
  subagentOverlayRefreshTimer = null;
  subagentOverlayRequestSerial += 1;
  subagentOverlaySelection = null;
  subagentOverlayData = null;
  subagentOverlayError = "";
  subagentOverlayLoading = false;
  renderWidgets();
}

async function copySubagentOverlayOutput() {
  const text = subagentOverlayOutputText();
  if (!text) {
    addEvent("subagent output is empty", "warn");
    return;
  }
  try {
    await copyText(text);
    addEvent("copied subagent output", "info");
  } catch (error) {
    addEvent(`subagent output copy failed: ${error.message || String(error)}`, "warn");
  }
}

function subagentTerminalViewId(tab, run, agent) {
  return JSON.stringify([tab?.tabId || "", run?.id || "", agent?.id || ""]);
}

function activeSubagentTerminalView() {
  return activeSubagentTerminalId ? subagentTerminalViews.get(activeSubagentTerminalId) || null : null;
}

function subagentTerminalViewTitle(view) {
  return String(view?.data?.agent?.name || view?.agent?.name || "subagent").trim() || "subagent";
}

function subagentTerminalViewIsRunning(view) {
  const agent = view?.data?.agent || view?.agent || null;
  return view?.finished !== true && subagentRunIsRunning(view?.run, agent);
}

function subagentTerminalViewMeaningfulSignature(view) {
  const data = view?.data ? { ...view.data, updatedAt: undefined } : null;
  return JSON.stringify({ data, error: view?.error || "", finished: view?.finished === true });
}

function updateSubagentTerminalRefreshState(view, { running = subagentTerminalViewIsRunning(view) } = {}) {
  if (!view || view.id !== activeSubagentTerminalId) return;
  const status = [
    view.loading ? "Refreshing…" : running ? "Live view · refreshes automatically" : view.finished ? "View retained after the child stopped being tracked" : "View retained after the run finished",
    view.error,
  ].filter(Boolean).join(" · ");
  elements.subagentTerminalStatus.setAttribute("aria-live", view.error ? "polite" : "off");
  elements.subagentTerminalStatus.textContent = status;
  elements.subagentTerminalStatus.classList.toggle("warning", !!view.error);
  elements.subagentTerminalRefreshButton.hidden = !subagentRunCanRefresh(view.run, view.data?.agent || view.agent);
  elements.subagentTerminalRefreshButton.disabled = view.loading || view.finished === true;
  elements.subagentTerminalRefreshButton.textContent = view.loading ? "Refreshing…" : "Refresh";
}

function subagentTerminalTelemetryNumber(value) {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
}

function formatSubagentTerminalTelemetryTokens(value) {
  const tokens = subagentTerminalTelemetryNumber(value);
  return tokens === null ? "—" : formatFooterTokenCount(tokens);
}

function formatSubagentTerminalTelemetryText(value) {
  return typeof value === "string" && value.trim() ? value.trim() : "unknown";
}

function renderSubagentTerminalCards(agent) {
  const telemetry = agent?.telemetry && typeof agent.telemetry === "object" && !Array.isArray(agent.telemetry)
    ? agent.telemetry
    : {};
  const contextTokens = formatSubagentTerminalTelemetryTokens(telemetry.contextTokens);
  const contextWindow = subagentTerminalTelemetryNumber(telemetry.contextWindow);

  if (elements.subagentTerminalCardPi) elements.subagentTerminalCardPi.textContent = formatSubagentTerminalTelemetryTokens(telemetry.promptInjectionTokens);
  if (elements.subagentTerminalCardSpeed) {
    const speed = subagentTerminalTelemetryNumber(telemetry.tokenSpeed);
    elements.subagentTerminalCardSpeed.textContent = speed === null ? "—" : `${formatFooterTokenCount(speed)} tok/s`;
  }
  if (elements.subagentTerminalCardContext) elements.subagentTerminalCardContext.textContent = `${contextTokens} / ${contextWindow === null ? "unknown" : formatFooterTokenCount(contextWindow)}`;
  if (elements.subagentTerminalCardModel) elements.subagentTerminalCardModel.textContent = formatSubagentTerminalTelemetryText(telemetry.model);
  if (elements.subagentTerminalCardEffort) elements.subagentTerminalCardEffort.textContent = formatSubagentTerminalTelemetryText(telemetry.effort);
  if (elements.subagentTerminalCardTokens) {
    elements.subagentTerminalCardTokens.textContent = `↑${formatSubagentTerminalTelemetryTokens(telemetry.inputTokens)} · ↓${formatSubagentTerminalTelemetryTokens(telemetry.outputTokens)}`;
  }
}

function renderSubagentTerminalView() {
  const view = activeSubagentTerminalView();
  const active = !!view;
  document.body.classList.toggle("subagent-terminal-active", active);
  if (!elements.subagentTerminalView) return;
  elements.subagentTerminalView.hidden = !active;
  if (!view) return;

  const agent = view.data?.agent || view.agent || {};
  const running = subagentTerminalViewIsRunning(view);
  const transcriptMessages = subagentOverlayTranscriptMessages({ agent });
  const hasStructuredTranscript = transcriptMessages.length > 0;
  const outputText = subagentOverlayOutputText({ agent });
  const fallbackText = outputText || agent.unavailableReason || (agent.unavailable ? "Output is unavailable for this registered agent." : running && agent.currentTool ? "" : running ? "Waiting for the first agent activity…" : "No recent output was captured.");
  const parent = tabs.find((tab) => tab.id === view.parentTabId);
  const elapsed = subagentRunElapsed(view.run);
  const facts = [
    view.finished ? "finished" : running ? `running${elapsed ? ` ${elapsed}` : ""}` : subagentRunStateLabel(view.run),
    view.run?.mode,
    subagentSourceLabel(view.data?.source || view.run?.source),
    agent.nested ? "nested" : "",
    ...subagentExecutionFacts(agent),
    ...subagentGateAttemptViewFacts(view.gateAttempt),
    agent.currentTool ? `tool ${agent.currentTool}` : "",
  ].filter(Boolean);

  const transcript = elements.subagentTerminalTranscript;
  const scrollKey = `subagent-terminal:${view.id}`;
  if (transcript.dataset.continuityScrollKey === scrollKey) rememberScopedScrollContinuity(transcript, scrollKey);
  else if (!scopedScrollContinuityByKey.has(scrollKey)) scopedScrollContinuityByKey.set(scrollKey, { mode: "follow-end", scrollTop: 0, scrollLeft: 0 });
  elements.subagentTerminalTitle.textContent = subagentTerminalViewTitle(view);
  elements.subagentTerminalMeta.textContent = `${facts.join(" · ")} · parent ${parent?.title || view.parentTitle || "terminal"} · run ${view.runId}`;
  renderSubagentTerminalCards(agent);
  transcript.replaceChildren();
  transcript.setAttribute("aria-live", running ? "polite" : "off");
  const rendered = appendSubagentOverlayTranscript(transcript, transcriptMessages);
  const emptyTranscriptFallback = hasStructuredTranscript && rendered === 0 ? subagentOverlayEmptyTranscriptText(transcriptMessages) : "";
  const visibleFallbackText = !hasStructuredTranscript ? fallbackText : emptyTranscriptFallback;
  if (visibleFallbackText) {
    const { bubble } = createMessageBubble({
      role: "assistant",
      title: "subagent output",
      timestamp: view.data?.updatedAt || Date.now(),
      content: visibleFallbackText,
    }, { streaming: running && !hasStructuredTranscript, transient: true });
    bubble.classList.add("subagent-overlay-message", "subagent-overlay-empty-fallback");
    transcript.append(bubble);
  }
  if (running) appendSubagentRunIndicator(elements.subagentTerminalTranscript, { agent, run: view.run });

  updateSubagentTerminalRefreshState(view, { running });
  elements.subagentTerminalCopyButton.hidden = !outputText;
  elements.subagentTerminalCopyButton.disabled = !outputText;
  if (elements.subagentTerminalCancelButton) {
    const cancellable = subagentRunCanCancel(view.run, agent);
    elements.subagentTerminalCancelButton.hidden = !cancellable;
    elements.subagentTerminalCancelButton.disabled = !cancellable;
  }
  bindScopedScrollContinuity(transcript, scrollKey);
  restoreScopedScrollContinuity(transcript, scrollKey);
}

function scheduleSubagentTerminalRefresh(delay = SUBAGENT_OVERLAY_REFRESH_MS) {
  clearTimeout(subagentTerminalRefreshTimer);
  const view = activeSubagentTerminalView();
  if (!view || view.finished || !subagentTerminalViewIsRunning(view)) return;
  subagentTerminalRefreshTimer = setTimeout(() => {
    refreshSubagentTerminalView(view.id).finally(() => scheduleSubagentTerminalRefresh());
  }, delay);
}

async function refreshSubagentTerminalView(viewId = activeSubagentTerminalId, { showLoading = false } = {}) {
  const view = viewId ? subagentTerminalViews.get(viewId) : null;
  if (!view || view.loading || view.finished) return;
  const requestSerial = (view.requestSerial || 0) + 1;
  const previousSignature = subagentTerminalViewMeaningfulSignature(view);
  view.requestSerial = requestSerial;
  view.loading = true;
  if (showLoading) updateSubagentTerminalRefreshState(view);
  try {
    const query = new URLSearchParams({ group: view.groupId, run: view.runId, agent: view.agentId });
    const response = await api(`/api/subagents/output?${query}`, { scoped: false });
    if (view.requestSerial !== requestSerial || !subagentTerminalViews.has(view.id)) return;
    view.data = response.data || null;
    view.error = "";
  } catch (error) {
    if (view.requestSerial !== requestSerial || !subagentTerminalViews.has(view.id)) return;
    if (error?.statusCode === 404) view.finished = true;
    view.error = error?.statusCode === 404
      ? "This subagent has finished or is no longer tracked. Showing the last captured output."
      : `Subagent output refresh failed: ${error.message || String(error)}`;
  } finally {
    if (view.requestSerial === requestSerial && subagentTerminalViews.has(view.id)) {
      view.loading = false;
      const meaningfulChange = previousSignature !== subagentTerminalViewMeaningfulSignature(view);
      if (view.id === activeSubagentTerminalId) {
        if (meaningfulChange) {
          renderSubagentTerminalView();
          renderTabs();
        } else {
          if (showLoading) updateSubagentTerminalRefreshState(view);
          updateSubagentRunIndicatorElapsed(elements.subagentTerminalTranscript, view.run);
        }
      }
    }
  }
}

function deactivateSubagentTerminalView({ render = true, focusParent = false } = {}) {
  clearTimeout(subagentTerminalRefreshTimer);
  subagentTerminalRefreshTimer = null;
  activeSubagentTerminalId = null;
  renderSubagentTerminalView();
  if (render) renderTabs();
  updateDocumentTitle();
  if (focusParent) focusPromptInput({ defer: true });
}

async function activateSubagentTerminalView(viewId) {
  const view = subagentTerminalViews.get(viewId);
  if (!view) return;
  clearOpenTerminalTabGroup(null, { force: true });
  setMobileTabsExpanded(false);
  if (activeTabId !== view.parentTabId) await switchTab(view.parentTabId);
  closeSubagentOverlay();
  activeSubagentTerminalId = view.id;
  renderSubagentTerminalView();
  renderTabs();
  updateDocumentTitle();
  if (isSidePanelOverlayView()) setSidePanelCollapsed(true, { persist: false });
  await refreshSubagentTerminalView(view.id);
  scheduleSubagentTerminalRefresh();
}

function ensureSubagentTerminalView(tab, run, agent) {
  if (!tab?.groupId || !tab?.tabId || !run?.id || !agent?.id || !subagentRunCanOpen(run, agent)) return null;
  const id = subagentTerminalViewId(tab, run, agent);
  const existing = subagentTerminalViews.get(id);
  if (existing) {
    existing.groupId = tab.groupId;
    existing.tab = tab;
    existing.run = run;
    existing.agent = agent;
    existing.parentTitle = tab.tabTitle;
    if (run.gateAttempt) existing.gateAttempt = run.gateAttempt;
    return existing;
  }
  const view = {
    id,
    groupId: tab.groupId,
    parentTabId: tab.tabId,
    parentTitle: tab.tabTitle,
    tabIndex: tab.tabIndex,
    tab,
    run,
    agent,
    runId: run.id,
    agentId: agent.id,
    gateAttempt: run.gateAttempt || null,
    data: null,
    error: "",
    loading: false,
    finished: false,
    requestSerial: 0,
    openedAt: Date.now(),
  };
  subagentTerminalViews.set(id, view);
  return view;
}

async function openSubagentTerminal(tab, run, agent) {
  if (!subagentRunCanOpen(run, agent)) return;
  const view = ensureSubagentTerminalView(tab, run, agent);
  if (!view) return;
  try {
    await activateSubagentTerminalView(view.id);
  } catch (error) {
    addEvent(`could not open subagent terminal: ${error.message || String(error)}`, "error");
  }
}

function closeSubagentTerminalTab(viewId) {
  const view = subagentTerminalViews.get(viewId);
  if (!view) return;
  view.requestSerial += 1;
  subagentTerminalViews.delete(viewId);
  if (activeSubagentTerminalId === viewId) deactivateSubagentTerminalView({ render: false, focusParent: true });
  renderTabs();
  addEvent(`closed subagent view for ${subagentTerminalViewTitle(view)}; the child run was not stopped`, "info");
}

function closeSubagentTerminalGroup(group) {
  const groupViews = Array.isArray(group?.views) ? group.views : [];
  if (!groupViews.length) return;
  const viewIds = new Set(groupViews.map((view) => view.id));
  for (const view of groupViews) {
    view.requestSerial += 1;
    subagentTerminalViews.delete(view.id);
  }
  if (viewIds.has(activeSubagentTerminalId)) deactivateSubagentTerminalView({ render: false, focusParent: true });
  renderTabs();
  addEvent(`closed ${groupViews.length} subagent views for ${group.parentTitle || "workspace"}; the child runs were not stopped`, "info");
}

async function copySubagentTerminalOutput() {
  const view = activeSubagentTerminalView();
  const text = view ? subagentOverlayOutputText(view.data || { agent: view.agent }) : "";
  if (!text) {
    addEvent("subagent output is empty", "warn");
    return;
  }
  try {
    await copyText(text);
    addEvent("copied subagent output", "info");
  } catch (error) {
    addEvent(`subagent output copy failed: ${error.message || String(error)}`, "warn");
  }
}

function removeSubagentTerminalViewsForParent(parentTabId) {
  for (const key of subagentTerminalRestoredParentTabs) {
    if (key.startsWith(`${parentTabId}\u0000`)) subagentTerminalRestoredParentTabs.delete(key);
  }
  for (const [viewId, view] of subagentTerminalViews) {
    if (view.parentTabId !== parentTabId) continue;
    view.requestSerial += 1;
    subagentTerminalViews.delete(viewId);
    if (activeSubagentTerminalId === viewId) deactivateSubagentTerminalView({ render: false });
  }
}

function syncSubagentTerminalViewsFromOverview() {
  let changed = false;
  const overviewTabs = subagentOverviewGroups();
  for (const view of [...subagentTerminalViews.values()]) {
    const tab = overviewTabs.find((candidate) => candidate.groupId === view.groupId);
    const run = (Array.isArray(tab?.runs) ? tab.runs : []).find((candidate) => candidate.id === view.runId);
    if (run && !subagentRunCanOpen(run, (Array.isArray(run.agents) ? run.agents : []).find((candidate) => candidate.id === view.agentId))) {
      view.requestSerial += 1;
      subagentTerminalViews.delete(view.id);
      if (activeSubagentTerminalId === view.id) activeSubagentTerminalId = null;
      changed = true;
      continue;
    }
    const agent = (Array.isArray(run?.agents) ? run.agents : []).find((candidate) => candidate.id === view.agentId);
    if (tab) {
      view.tab = tab;
      view.parentTitle = tab.tabTitle;
      changed = true;
    }
    if (run) {
      view.run = run;
      changed = true;
    }
    if (agent) {
      view.agent = agent;
      if (view.data?.agent) view.data = { ...view.data, agent: { ...view.data.agent, ...agent } };
      changed = true;
    }
  }
  const selection = subagentOverlaySelection;
  if (selection) {
    const tab = overviewTabs.find((candidate) => candidate.groupId === selection.groupId);
    const run = (Array.isArray(tab?.runs) ? tab.runs : []).find((candidate) => candidate.id === selection.runId);
    if (run && !subagentRunCanOpen(run, (Array.isArray(run.agents) ? run.agents : []).find((candidate) => candidate.id === selection.agentId))) {
      clearTimeout(subagentOverlayRefreshTimer);
      subagentOverlayRefreshTimer = null;
      subagentOverlayRequestSerial += 1;
      subagentOverlaySelection = null;
      subagentOverlayData = null;
      subagentOverlayError = "";
      subagentOverlayLoading = false;
      changed = true;
    } else {
      const agent = (Array.isArray(run?.agents) ? run.agents : []).find((candidate) => candidate.id === selection.agentId);
      if (tab) selection.tab = tab;
      if (run) {
        selection.run = run;
        changed = true;
      }
      if (agent) {
        selection.agent = agent;
        if (subagentOverlayData?.agent) subagentOverlayData = { ...subagentOverlayData, agent: { ...subagentOverlayData.agent, ...agent } };
        changed = true;
      }
    }
  }
  return changed;
}

function materializeRetainedSubagentTerminalViews() {
  if (subagentOpenMode !== "tab") return false;
  let materialized = false;
  for (const tab of subagentOverviewGroups()) {
    if (tab?.available !== true || !tab?.tabId) continue;
    const restoreKey = `${tab.tabId}\u0000${tab.sessionFile || ""}`;
    if (subagentTerminalRestoredParentTabs.has(restoreKey)) continue;
    subagentTerminalRestoredParentTabs.add(restoreKey);
    for (const run of tab.displayRuns) {
      if (["queued", "running", "stale"].includes(subagentAgentStatus(run)) || run?.source === "workflow") continue;
      for (const agent of subagentRunAgents(run)) {
        const id = subagentTerminalViewId(tab, run, agent);
        if (subagentTerminalViews.has(id)) continue;
        if (ensureSubagentTerminalView(tab, run, agent)) materialized = true;
      }
    }
  }
  return materialized;
}

function subagentTerminalViewGroups() {
  const groups = [];
  const byParent = new Map();
  const views = [...subagentTerminalViews.values()].sort((a, b) => a.openedAt - b.openedAt || String(a.id).localeCompare(String(b.id)));
  for (const view of views) {
    const parentTabId = view.parentTabId || view.id;
    let group = byParent.get(parentTabId);
    if (!group) {
      group = {
        key: `subagents:${parentTabId}`,
        parentTabId,
        parentTitle: view.parentTitle || "workspace",
        views: [],
      };
      byParent.set(parentTabId, group);
      groups.push(group);
    }
    group.parentTitle = view.parentTitle || group.parentTitle;
    group.views.push(view);
  }
  return groups;
}

function renderSubagentTerminalTab(view, { groupItem = false } = {}) {
  const active = view.id === activeSubagentTerminalId;
  const running = subagentTerminalViewIsRunning(view);
  const stateClass = running ? "activity-working" : view.error && !view.data ? "stopped" : "activity-done";
  const wrapper = make("div", `${groupItem ? "terminal-tab-group-item" : "terminal-tab"} terminal-tab-subagent ${stateClass}${active ? " active" : ""}`);
  wrapper.dataset.subagentViewId = view.id;
  const button = make("button", `terminal-tab-button${groupItem ? " terminal-tab-group-item-button" : ""}`);
  button.type = "button";
  button.setAttribute("role", "tab");
  button.setAttribute("aria-selected", active ? "true" : "false");
  button.setAttribute("aria-label", `${subagentTerminalViewTitle(view)} subagent view, parent ${view.parentTitle || "terminal"}`);
  appendTerminalTabContent(button, {
    title: subagentTerminalViewTitle(view),
    indicator: { state: running ? "working" : "done" },
    meta: ["Subagent", subagentSourceLabel(view.data?.source || view.run?.source), ...subagentExecutionFacts(view.data?.agent || view.agent), view.parentTitle || "parent terminal"].join(" · "),
    subagent: true,
  });
  button.addEventListener("click", (event) => {
    if (groupItem) event.stopPropagation();
    activateSubagentTerminalView(view.id);
  });
  const close = make("button", `terminal-tab-close${groupItem ? " terminal-tab-group-item-close" : ""}`, "×");
  close.type = "button";
  applyStyledTooltip(close, `Close ${subagentTerminalViewTitle(view)} view without stopping the subagent`, { ariaLabel: `Close ${subagentTerminalViewTitle(view)} subagent view` });
  close.addEventListener("click", (event) => {
    event.stopPropagation();
    closeSubagentTerminalTab(view.id);
  });
  wrapper.append(button, close);
  return wrapper;
}

function renderSubagentTerminalTabGroup(group) {
  const groupViews = group.views;
  const activeView = groupViews.find((view) => view.id === activeSubagentTerminalId) || groupViews.at(-1);
  const active = groupViews.some((view) => view.id === activeSubagentTerminalId);
  const runningCount = groupViews.filter(subagentTerminalViewIsRunning).length;
  const stateClass = runningCount ? "activity-working" : "activity-done";
  const groupTitle = group.parentTitle || "workspace";
  const wrapper = make("div", `terminal-tab terminal-tab-group terminal-tab-subagent terminal-tab-subagent-group ${stateClass}${active ? " active" : ""}`);
  wrapper.dataset.groupKey = group.key;
  wrapper.addEventListener("pointerenter", (event) => {
    if (event.pointerType === "touch") return;
    setOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("pointerleave", (event) => {
    if (event.pointerType === "touch") return;
    clearOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("focusin", () => {
    if (!isMobileView()) setOpenTerminalTabGroup(group.key);
  });
  wrapper.addEventListener("focusout", () => {
    if (isMobileView()) return;
    setTimeout(() => {
      if (!wrapper.contains(document.activeElement)) clearOpenTerminalTabGroup(group.key);
    }, 0);
  });

  const button = make("button", "terminal-tab-button terminal-tab-group-button");
  button.type = "button";
  button.setAttribute("role", "tab");
  button.setAttribute("aria-selected", active ? "true" : "false");
  button.setAttribute("aria-haspopup", "true");
  button.setAttribute("aria-expanded", group.key === openTerminalTabGroupKey ? "true" : "false");
  button.setAttribute("aria-label", `${groupTitle} workspace subagents: ${groupViews.length} views, ${runningCount} running. Active ${subagentTerminalViewTitle(activeView)}. ${isMobileView() ? "Toggle subagent view list" : "Switch to the active subagent view"}`);
  applyStyledTooltip(button, `${groupTitle} · ${groupViews.length} subagent views\n${runningCount ? `${runningCount} running` : "All finished"}\nActive: ${subagentTerminalViewTitle(activeView)}`, { ariaLabel: false, description: true, placement: "right", variant: "workspace" });
  appendTerminalTabContent(button, {
    title: groupTitle,
    indicator: { state: runningCount ? "working" : "done" },
    meta: `${groupViews.length} subagents · ${runningCount ? `${runningCount} running` : "finished"}`,
    count: groupViews.length,
    subagent: true,
    dropdown: true,
  });
  button.addEventListener("click", () => {
    if (isMobileView()) {
      toggleOpenTerminalTabGroup(group.key);
      return;
    }
    activateSubagentTerminalView(activeView.id);
  });
  wrapper.append(button);

  const close = make("button", "terminal-tab-close terminal-tab-group-close", "×");
  close.type = "button";
  applyStyledTooltip(close, `Close all ${groupViews.length} ${groupTitle} subagent views without stopping them`, { ariaLabel: `Close ${groupTitle} subagent view group` });
  close.addEventListener("click", (event) => {
    event.stopPropagation();
    closeSubagentTerminalGroup(group);
  });
  wrapper.append(close);

  const menu = make("div", "terminal-tab-group-menu");
  menu.id = `terminalTabGroupMenu${++terminalTabGroupMenuSerial}`;
  menu.setAttribute("role", "group");
  menu.setAttribute("aria-label", `${groupTitle} subagent views`);
  button.setAttribute("aria-controls", menu.id);
  for (const view of groupViews) menu.append(renderSubagentTerminalTab(view, { groupItem: true }));
  wrapper.append(menu);
  return wrapper;
}

function openSubagentOutput(tab, run, agent) {
  if (!subagentRunCanOpen(run, agent)) return;
  return subagentOpenMode === "tab" ? openSubagentTerminal(tab, run, agent) : openSubagentOverlay(tab, run, agent);
}

function subagentWorkflowRunKey(tab, run) {
  return `${tab?.groupId || tab?.tabId || ""}:${run?.id || ""}`;
}

function renderSubagentWorkflow(tab, run, controller, agents) {
  const status = subagentWorkflowPresentationStatus(run, agents);
  const key = subagentWorkflowRunKey(tab, run);
  const details = make("details", `subagent-workflow state-${status}`);
  details.open = !collapsedSubagentWorkflowRunKeys.has(key);
  details.addEventListener("toggle", () => {
    if (details.open) collapsedSubagentWorkflowRunKeys.delete(key);
    else collapsedSubagentWorkflowRunKeys.add(key);
  });

  const summary = make("summary", "subagent-workflow-header");
  summary.dataset.subagentContinuityKey = `workflow:${tab?.tabId || ""}:${run?.id || ""}`;
  summary.setAttribute("aria-label", `Workflow ${status}, ${agents.length} ${agents.length === 1 ? "agent" : "agents"}`);
  const dot = make("span", `subagent-state-dot ${status}`);
  dot.setAttribute("aria-hidden", "true");
  const identity = make("span", "subagent-agent-identity");
  identity.append(
    make("strong", "subagent-workflow-name", "Workflow"),
    make("span", "subagent-source-badge", subagentLauncherLabel(controller?.launcher || run?.launcher)),
    make("span", "subagent-agent-inline-meta", `· ${status} · ${agents.length} ${agents.length === 1 ? "agent" : "agents"}`),
  );
  summary.append(dot, identity);

  const children = make("div", "subagent-workflow-agents");
  for (const entry of agents) children.append(renderSubagentAgent(tab, entry.run, entry.agent));
  if (!children.childElementCount) children.append(make("div", "subagents-empty", "Waiting for workflow agents…"));
  details.append(summary, children);
  return details;
}

function renderSubagentAgent(tab, run, agent) {
  const status = subagentAgentStatus(run, agent);
  const running = ["queued", "running"].includes(status);
  const interactive = subagentRunCanOpen(run, agent);
  const name = agent?.name || "subagent";
  const [model, thinking] = subagentExecutionValues(agent);
  const launcher = subagentLauncherLabel(agent?.launcher || run?.launcher);
  const row = make(interactive ? "button" : "div", `subagent-agent-row state-${status}${agent?.nested ? " nested" : ""}${running ? " running" : " finished"}${interactive ? "" : " metadata-only"}`);
  if (interactive) row.type = "button";
  row.dataset.subagentContinuityKey = `agent:${tab?.tabId || ""}:${run?.id || ""}:${agent?.id || ""}`;
  const dot = make("span", `subagent-state-dot ${status}`);
  dot.setAttribute("aria-hidden", "true");
  const identity = make("span", "subagent-agent-identity");
  identity.append(
    make("strong", "subagent-agent-name", name),
    make("span", "subagent-source-badge", launcher),
    make("span", "subagent-agent-inline-meta", `· ${status} · ${model} · ${thinking}`),
  );
  row.append(dot, identity);
  if (interactive) {
    const open = make("span", "subagent-agent-open", "›");
    open.setAttribute("aria-hidden", "true");
    row.append(open);
    const destination = subagentOpenMode === "tab" ? "subagent tab" : "output overlay";
    row.title = `${name} · ${launcher} · ${status} · ${model} · ${thinking} · open ${destination}`;
    row.setAttribute("aria-label", `Open ${destination} for ${name}, launched by ${launcher}, ${status}, model ${model}, reasoning ${thinking}, in ${tab?.tabTitle || `Terminal ${tab?.tabIndex || "?"}`}`);
    row.addEventListener("click", () => openSubagentOutput(tab, run, agent));
  } else {
    row.title = `${name} · ${launcher} · ${status} · output is unavailable from this provider`;
    row.setAttribute("aria-label", `${name}, launched by ${launcher}, ${status}; output and controls are unavailable from this provider`);
  }
  return row;
}

function renderSubagentRun(tab, run, workflowAgents = null) {
  const running = subagentRunIsRunning(run);
  const card = make("section", `subagent-run ${running ? "running" : run?.status || "done"}`);
  const controller = subagentWorkflowController(run);
  const agents = subagentRunAgents(run)
    .slice()
    .sort((a, b) => Number(a.index || 0) - Number(b.index || 0) || String(a.name || "").localeCompare(String(b.name || "")));
  const presentedAgents = controller && Array.isArray(workflowAgents) ? workflowAgents : agents.map((agent) => ({ run, agent }));
  card.setAttribute("aria-label", `${controller ? "Workflow" : "Subagent"} run with ${presentedAgents.length} ${presentedAgents.length === 1 ? "agent" : "agents"}`);
  const list = make("div", "subagent-run-agents");
  if (controller) list.append(renderSubagentWorkflow(tab, run, controller, presentedAgents));
  else for (const agent of agents) list.append(renderSubagentAgent(tab, run, agent));
  if (!list.childElementCount) list.append(make("div", "subagents-empty", "No agents were captured."));
  card.append(list);

  const actions = make("div", "subagent-run-actions");
  if (subagentRunCanCancel(run)) {
    const cancel = make("button", "subagent-run-cancel", "■");
    cancel.type = "button";
    cancel.dataset.subagentContinuityKey = `run:${tab?.tabId || ""}:${run?.id || ""}:cancel`;
    applyStyledTooltip(cancel, "Cancel entire subagent run…", { ariaLabel: "Cancel entire subagent run" });
    cancel.addEventListener("click", () => openSubagentCancelDialog(tab, run));
    actions.append(cancel);
  } else if (subagentRunCanDismiss(run)) {
    const dismiss = make("button", "subagent-run-dismiss", "×");
    dismiss.type = "button";
    dismiss.dataset.subagentContinuityKey = `run:${tab?.tabId || ""}:${run?.id || ""}:dismiss`;
    const dismissLabel = subagentRunIsAttachedProjection(run) ? "Detach persisted session from WebUI" : "Dismiss finished run";
    applyStyledTooltip(dismiss, dismissLabel, { ariaLabel: dismissLabel });
    dismiss.addEventListener("click", () => dismissSubagentRun(tab, run));
    actions.append(dismiss);
  }
  if (actions.childElementCount) card.append(actions);
  return card;
}

function subagentGateStatusLabel(status) {
  return status === "satisfied" ? "satisfied" : status === "running" ? "running" : status === "cancelled" ? "cancelled" : "failed";
}

function subagentGateAttemptTarget(tab, attempt) {
  if (!tab?.groupId || !attempt?.runId) return null;
  const run = (Array.isArray(tab.displayRuns) ? tab.displayRuns : []).find((candidate) => candidate?.id === attempt.runId);
  if (!run) return null;
  const agents = Array.isArray(run.agents) ? run.agents : [];
  let agent = agents.find((candidate) => candidate?.id === attempt.instanceId || candidate?.instanceId === attempt.instanceId || candidate?.name === attempt.agent);
  if (!agent && agents.length === 1) [agent] = agents;
  return agent?.id && subagentRunCanOpen(run, agent) ? { run, agent } : null;
}

function subagentGateAttemptExecutionValues(attempt = {}) {
  let model = String(attempt?.model || "").trim();
  let thinking = String(attempt?.thinking || "").trim().toLowerCase();
  const suffixIndex = model.lastIndexOf(":");
  const suffix = suffixIndex > model.indexOf("/") ? model.slice(suffixIndex + 1).toLowerCase() : "";
  if (!thinking && SETTINGS_THINKING_OPTIONS.includes(suffix)) thinking = suffix;
  if (thinking && suffix === thinking) model = model.slice(0, suffixIndex);
  const provider = String(attempt?.provider || "").trim().toLowerCase();
  if (provider && model && !model.toLowerCase().startsWith(`${provider}/`)) model = `${provider}/${model}`;
  return [model || provider || "unknown", thinking || "unknown"];
}

function openSubagentGateAttemptOutput(tab, target, attempt) {
  return openSubagentOutput(tab, { ...target.run, gateAttempt: attempt }, target.agent);
}

function renderSubagentGateAttempt(tab, attempt) {
  const target = subagentGateAttemptTarget(tab, attempt);
  const row = make(target ? "button" : "div", `subagent-gate-attempt ${attempt?.status || "failed"}${target ? " openable" : ""}`);
  const title = attempt?.label || attempt?.agent || "subagent";
  if (target) {
    row.type = "button";
    row.dataset.subagentContinuityKey = `gate:${tab?.tabId || ""}:${attempt?.runId || ""}:${target.agent?.id || ""}`;
    const destination = subagentOpenMode === "tab" ? "subagent tab" : "output overlay";
    row.title = `${title} · open ${destination}`;
    row.setAttribute("aria-label", `Open ${destination} for ${title}, ${attempt?.status || "unknown"}, ${attempt?.retrySafety || "may-write"}`);
    row.addEventListener("click", () => openSubagentGateAttemptOutput(tab, target, attempt));
  }
  const marker = make("span", "subagent-gate-attempt-marker");
  marker.setAttribute("aria-hidden", "true");
  const identity = make("span", "subagent-gate-attempt-identity");
  const [model, thinking] = subagentGateAttemptExecutionValues(attempt);
  identity.append(
    make("strong", "subagent-gate-attempt-name", title),
    make("span", "subagent-gate-attempt-meta", `· ${attempt?.status || "unknown"} · ${model} · ${thinking} · ${attempt?.retrySafety || "may-write"}`),
  );
  const open = target ? make("span", "subagent-gate-attempt-open", "›") : null;
  open?.setAttribute("aria-hidden", "true");
  row.append(marker, identity, ...(open ? [open] : []));
  return row;
}

function renderSubagentGate(tab, gate) {
  const status = subagentGateStatusLabel(gate?.status);
  const card = make("section", `subagent-gate-card ${status}`);
  const header = make("div", "subagent-gate-header");
  const title = make("div", "subagent-gate-title");
  title.append(
    make("strong", undefined, "Retry gate"),
    make("span", undefined, `${gate?.qualifyingSuccesses || 0}/${gate?.requiredSuccesses || 1} · ${status}${gate?.requireDistinctProviders ? " · distinct providers" : ""}`),
  );
  const actions = make("div", "subagent-gate-actions");
  if (subagentGateIsTerminal(gate)) {
    const close = make("button", "subagent-gate-close", "×");
    close.type = "button";
    applyStyledTooltip(close, "Hide finished retry gate", { ariaLabel: "Hide finished retry gate" });
    close.addEventListener("click", (event) => {
      const key = subagentGateKey(tab?.tabId, gate?.id);
      if (key) dismissedSubagentGateKeys.add(key);
      renderSubagents();
      if (event.detail === 0) {
        const focusTarget = elements.subagentsBox?.querySelector(".subagent-gate-close") || document.querySelector("#sidePanelSectionToggleSubagents");
        focusTarget?.focus({ preventScroll: true });
      }
    });
    actions.append(close);
  }
  header.append(title, actions);
  card.append(header);
  const attempts = make("div", "subagent-gate-attempts");
  for (const attempt of Array.isArray(gate?.attempts) ? gate.attempts : []) attempts.append(renderSubagentGateAttempt(tab, attempt));
  if (!attempts.childElementCount) attempts.append(make("div", "subagents-empty", "Waiting for the first attempt…"));
  card.append(attempts);
  return card;
}

function renderSubagentTabGroup(tab) {
  const isExternal = tab.groupKind === "external";
  const group = make("section", `subagent-tab-group${isExternal ? " external" : ""}${tab.tabId === activeTabId && !isExternal ? " active" : ""}`);
  const header = make(isExternal ? "div" : "button", "subagent-tab-header");
  if (!isExternal) header.type = "button";
  header.dataset.subagentContinuityKey = `tab:${tab?.tabId || ""}`;
  if (!isExternal) header.setAttribute("aria-label", `Open ${tab.tabTitle || `Terminal ${tab.tabIndex || ""}`}`);
  const title = make("span", "subagent-tab-title");
  title.append(
    make("strong", undefined, tab.tabTitle || `Terminal ${tab.tabIndex || "?"}`),
    make("span", "subagent-tab-session", isExternal ? "Registered outside open WebUI tabs" : `Terminal ${tab.tabIndex || "?"} · ${subagentTabMeta(tab)}`),
  );
  const runs = (Array.isArray(tab.displayRuns) ? tab.displayRuns : ungatedSubagentRuns(tab))
    .slice()
    .sort((a, b) => Number(a.startedAt || 0) - Number(b.startedAt || 0) || String(a.id || "").localeCompare(String(b.id || "")));
  const agentCounts = subagentRunAgentCounts(runs);
  const runningAgents = agentCounts.running;
  const staleAgents = agentCounts.stale;
  const retainedRuns = runs.filter((run) => !["queued", "running", "stale"].includes(subagentAgentStatus(run))).length;
  const countLabel = [
    `${agentCounts.total} total`,
    runningAgents ? `${runningAgents} running` : "",
    staleAgents ? `${staleAgents} stale` : "",
    retainedRuns ? `${retainedRuns} retained` : "",
    Number(tab.gateCount || 0) ? `${tab.gateCount} gates` : "",
  ].filter(Boolean).join(" · ");
  header.append(title, make("span", "subagent-tab-count", countLabel));
  if (!isExternal) header.addEventListener("click", () => switchTab(tab.tabId));
  group.append(header);

  const list = make("div", "subagent-agent-list");
  for (const presentation of subagentRunPresentations(runs)) list.append(renderSubagentRun(tab, presentation.run, presentation.agents));
  for (const gate of (Array.isArray(tab.gates) ? tab.gates : []).slice().sort((a, b) => Number(a.startedAt || 0) - Number(b.startedAt || 0))) {
    list.append(renderSubagentGate(tab, gate));
  }
  group.append(list);
  return group;
}

function subagentPanelControlKey(node) {
  return node?.dataset?.subagentContinuityKey || "";
}

function renderSubagents() {
  if (deferUiRenderDuringPointerActivation("subagents", renderSubagents)) return;
  const box = elements.subagentsBox;
  if (!box) return;
  const continuityContextKey = `${activeTabId || ""}:${activeTabGeneration}`;
  const focusSnapshot = captureScopedControlContinuity(box, continuityContextKey, subagentPanelControlKey);
  const restoreFocus = () => restoreScopedControlContinuity(box, continuityContextKey, focusSnapshot, (key) => [...box.querySelectorAll("[data-subagent-continuity-key]")].find((node) => subagentPanelControlKey(node) === key));
  const activeTabs = subagentTabsWithRunningAgents();
  const finishedRuns = finishedSubagentRunSelections();
  const totalAgents = activeTabs.reduce((count, tab) => count + Number(tab.agentCount || 0), 0);
  const runningAgents = activeTabs.reduce((count, tab) => count + Number(tab.runningAgents || 0), 0);
  const staleAgents = activeTabs.reduce((count, tab) => count + Number(tab.staleAgents || 0), 0);
  const totalRuns = activeTabs.reduce((count, tab) => count + tab.displayRuns.length, 0);
  const runningRuns = activeTabs.reduce((count, tab) => count + tab.displayRuns.filter((run) => run?.status === "running").length, 0);
  const retainedRuns = Math.max(0, totalRuns - runningRuns);
  const totalGates = activeTabs.reduce((count, tab) => count + Number(tab.gateCount || 0), 0);
  const hasItems = activeTabs.length > 0;
  if (elements.subagentCountBadge) {
    elements.subagentCountBadge.textContent = String(totalAgents);
    elements.subagentCountBadge.hidden = totalAgents === 0;
  }
  if (elements.subagentsAutoClearButton) {
    elements.subagentsAutoClearButton.setAttribute("aria-pressed", subagentAutoClearEnabled ? "true" : "false");
    elements.subagentsAutoClearButton.classList.toggle("selected", subagentAutoClearEnabled);
    elements.subagentsAutoClearButton.title = subagentAutoClearEnabled
      ? "Auto-Clear is on: finished subagent runs are removed automatically"
      : "Auto-Clear is off: keep finished subagent runs until they are cleared manually";
  }
  if (elements.subagentsClearFinishedButton) {
    elements.subagentsClearFinishedButton.disabled = subagentsLoading || subagentsClearingFinished || finishedRuns.length === 0;
    elements.subagentsClearFinishedButton.textContent = subagentsClearingFinished ? "Clearing…" : "Clear finished";
    elements.subagentsClearFinishedButton.title = finishedRuns.length
      ? `Clear ${finishedRuns.length} finished subagent ${finishedRuns.length === 1 ? "run" : "runs"}`
      : "No finished subagent runs to clear";
  }
  if (elements.subagentsStatus) {
    elements.subagentsStatus.textContent = hasItems
      ? [`${totalAgents} total`, `${runningAgents} running`, staleAgents ? `${staleAgents} stale` : "", Number(latestSubagents?.fleet?.omitted || 0) ? `${latestSubagents.fleet.omitted} active ${latestSubagents.fleet.omitted === 1 ? "child" : "children"} omitted upstream` : "", retainedRuns ? `${retainedRuns} retained ${retainedRuns === 1 ? "run" : "runs"}` : "", totalGates ? `${totalGates} retry ${totalGates === 1 ? "gate" : "gates"}` : "", `across ${activeTabs.length} ${activeTabs.length === 1 ? "group" : "groups"}`].filter(Boolean).join(" · ")
      : subagentsLoading && !latestSubagents
        ? "Checking subagents and retry gates…"
        : "No running subagents, retained runs, or retry gates.";
  }

  box.replaceChildren();
  box.classList.toggle("muted", !hasItems);
  box.classList.toggle("has-items", hasItems);
  if (!hasItems) {
    box.append(make("div", "subagents-empty", subagentsError ? `Subagent status unavailable: ${subagentsError.message || subagentsError}` : "Managed and registered Pi agent runs will appear here, grouped by terminal or under External agents."));
    restoreFocus();
    return;
  }
  for (const tab of activeTabs) box.append(renderSubagentTabGroup(tab));
  if (subagentsError) box.append(make("div", "subagents-stale muted", `Latest refresh failed: ${subagentsError.message || subagentsError}`));
  restoreFocus();
}

async function refreshSubagents() {
  if (subagentsRefreshPromise) {
    subagentsRefreshQueued = true;
    return subagentsRefreshPromise;
  }
  let refreshed = false;
  let subagentViewsChanged = false;
  let materializedTerminalViews = false;
  subagentsLoading = true;
  renderSubagents();
  let settleRefresh;
  let rejectRefresh;
  const refreshPromise = new Promise((resolve, reject) => {
    settleRefresh = resolve;
    rejectRefresh = reject;
  });
  subagentsRefreshPromise = refreshPromise;
  (async () => {
    try {
      do {
        subagentsRefreshQueued = false;
        try {
          const response = await api("/api/subagents", { scoped: false });
          latestSubagents = response.data || null;
          pruneDismissedSubagentGateKeys(latestSubagents?.tabs, dismissedSubagentGateKeys);
          subagentViewsChanged = syncSubagentTerminalViewsFromOverview() || subagentViewsChanged;
          materializedTerminalViews = materializeRetainedSubagentTerminalViews() || materializedTerminalViews;
          subagentsError = null;
          refreshed = true;
        } catch (error) {
          subagentsError = error;
        }
      } while (subagentsRefreshQueued);
    } finally {
      if (subagentsRefreshPromise === refreshPromise) subagentsRefreshPromise = null;
      subagentsLoading = false;
      renderSubagents();
      if (subagentOverlaySelection?.tabId === activeTabId) renderWidgets();
      if (activeSubagentTerminalId) {
        renderSubagentTerminalView();
        scheduleSubagentTerminalRefresh();
      }
      if (subagentViewsChanged || materializedTerminalViews) renderTabs();
    }
  })().then(settleRefresh, rejectRefresh);
  await refreshPromise;
  if (refreshed && subagentAutoClearEnabled && finishedSubagentRunSelections().length) {
    await clearFinishedSubagentRuns({ automatic: true });
  }
}

function scheduleRefreshSubagents(delay) {
  clearTimeout(refreshSubagentsTimer);
  const totalAgents = Number(latestSubagents?.runningAgents || 0);
  const hasRunningGate = (Array.isArray(latestSubagents?.tabs) ? latestSubagents.tabs : []).some((tab) => (Array.isArray(tab?.gates) ? tab.gates : []).some((gate) => gate?.status === "running"));
  const nextDelay = delay ?? (document.visibilityState === "hidden" ? SUBAGENTS_HIDDEN_REFRESH_MS : totalAgents > 0 || hasRunningGate ? SUBAGENTS_ACTIVE_REFRESH_MS : SUBAGENTS_IDLE_REFRESH_MS);
  refreshSubagentsTimer = setTimeout(() => {
    refreshSubagents().finally(() => scheduleRefreshSubagents());
  }, nextDelay);
}

function initializeSubagents() {
  renderSubagents();
  refreshSubagents().finally(() => scheduleRefreshSubagents());
}

function subagentLaunchSlotLimits() {
  return {
    slotsPerRole: Number(subagentLaunchSlotConfig?.limits?.slotsPerRole) || 8,
    totalSlots: Number(subagentLaunchSlotConfig?.limits?.totalSlots) || 32,
  };
}

function subagentLaunchSlotDraftRoles() {
  return subagentLaunchSlotDraft || subagentLaunchSlotConfig?.roles || {};
}

function subagentLaunchSlotDraftIsDirty() {
  return !!subagentLaunchSlotConfig && !!subagentLaunchSlotDraft
    && !launchSlotRolesEqual(subagentLaunchSlotDraft, subagentLaunchSlotConfig.roles || {});
}

function subagentLaunchSlotModelKey(model) {
  return model?.provider && model?.id ? `${model.provider}/${model.id}` : "";
}

function subagentLaunchSlotModelsByKey() {
  return new Map((Array.isArray(subagentLaunchSlotConfig?.models) ? subagentLaunchSlotConfig.models : [])
    .map((model) => [subagentLaunchSlotModelKey(model), model])
    .filter(([key]) => key));
}

function subagentLaunchSlotThinkingForModel(model) {
  const levels = subagentLaunchSlotConfig?.modelThinkingLevels?.[model];
  return Array.isArray(levels) ? levels : [];
}

function subagentLaunchSlotTotal(roles = subagentLaunchSlotDraftRoles()) {
  return Object.values(roles).reduce((total, slots) => total + (Array.isArray(slots) ? slots.length : 0), 0);
}

function newSubagentLaunchSlotId(roles) {
  const used = new Set(Object.values(roles).flatMap((slots) => (Array.isArray(slots) ? slots : []).map((slot) => slot?.id)));
  for (let attempt = 0; attempt < 12; attempt++) {
    const token = globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    const id = `slot-${token}`;
    if (!used.has(id)) return id;
  }
  return "";
}

function setSubagentLaunchSlotAnnouncement(message = "") {
  if (elements.subagentLaunchSlotsAnnouncer) elements.subagentLaunchSlotsAnnouncer.textContent = message;
}

function focusSubagentLaunchSlotControl() {
  const target = subagentLaunchSlotFocusTarget;
  subagentLaunchSlotFocusTarget = null;
  if (!target || !elements.subagentLaunchSlotRoles) return;
  requestAnimationFrame(() => {
    const control = [...elements.subagentLaunchSlotRoles.querySelectorAll("select[data-launch-slot-role]")]
      .find((candidate) => candidate.dataset.launchSlotRole === target.roleId
        && candidate.dataset.launchSlotId === target.slotId
        && candidate.dataset.launchSlotControl === target.control);
    control?.focus();
  });
}

function subagentLaunchSlotOption(value, text, { disabled = false } = {}) {
  const option = document.createElement("option");
  option.value = value || "";
  option.textContent = text;
  option.disabled = disabled;
  return option;
}

function renderSubagentLaunchSlotCard(role, slots) {
  const limits = subagentLaunchSlotLimits();
  const modelsByKey = subagentLaunchSlotModelsByKey();
  const roleId = String(role?.id || "");
  const card = make("section", "subagent-launch-slot-role");
  card.setAttribute("aria-labelledby", `subagent-launch-slot-role-${roleId}`);
  if (role?.purpose) card.title = role.purpose;
  const header = make("header", "subagent-launch-slot-role-header");
  const heading = make("h4", "subagent-launch-slot-role-heading", role?.title || roleId);
  heading.id = `subagent-launch-slot-role-${roleId}`;
  header.append(heading, make("span", "subagent-launch-slot-count", `${slots.length}/${limits.slotsPerRole}`));
  card.append(header);

  const list = make("div", "subagent-launch-slot-list");
  for (const [index, slot] of slots.entries()) {
    const ordinal = index + 1;
    const slotLabel = `${role?.title || roleId} slot ${ordinal}`;
    const row = make("section", "subagent-launch-slot-row");
    row.setAttribute("aria-label", slotLabel);
    if (slots.length > 1) {
      const rowHeader = make("strong", "subagent-launch-slot-row-header", `Slot ${ordinal}`);
      row.append(rowHeader);
    }

    const controls = make("div", "subagent-launch-slot-controls");
    const modelField = make("label", "subagent-launch-slot-field");
    const modelId = `subagent-launch-slot-model-${roleId}-${slot.id}`;
    modelField.append(make("span", undefined, "Model"));
    const modelSelect = document.createElement("select");
    modelSelect.id = modelId;
    modelSelect.dataset.launchSlotRole = roleId;
    modelSelect.dataset.launchSlotId = slot.id;
    modelSelect.dataset.launchSlotControl = "model";
    modelSelect.setAttribute("aria-label", `Model for ${slotLabel}`);
    modelSelect.append(subagentLaunchSlotOption("", "Default / inherit"));
    for (const [modelKey, model] of modelsByKey) {
      modelSelect.append(subagentLaunchSlotOption(modelKey, model?.name ? `${modelKey} · ${model.name}` : modelKey));
    }
    if (slot.model && !modelsByKey.has(slot.model)) {
      modelSelect.append(subagentLaunchSlotOption(slot.model, `Unavailable: ${slot.model}`, { disabled: true }));
    }
    modelSelect.value = slot.model || "";
    modelSelect.disabled = subagentLaunchSlotLoading || subagentLaunchSlotSaving;
    modelSelect.addEventListener("change", () => {
      const model = modelSelect.value || null;
      const thinking = model && subagentLaunchSlotThinkingForModel(model).includes(slot.thinking) ? slot.thinking : null;
      subagentLaunchSlotDraft = updateLaunchSlot(subagentLaunchSlotDraftRoles(), roleId, slot.id, { model, thinking });
      subagentLaunchSlotError = "";
      subagentLaunchSlotFocusTarget = { roleId, slotId: slot.id, control: "model" };
      renderSubagentLaunchSlots();
    });
    modelField.append(modelSelect);

    const thinkingField = make("label", "subagent-launch-slot-field");
    const thinkingId = `subagent-launch-slot-thinking-${roleId}-${slot.id}`;
    thinkingField.append(make("span", undefined, "Thinking"));
    const thinkingSelect = document.createElement("select");
    thinkingSelect.id = thinkingId;
    thinkingSelect.dataset.launchSlotRole = roleId;
    thinkingSelect.dataset.launchSlotId = slot.id;
    thinkingSelect.dataset.launchSlotControl = "thinking";
    thinkingSelect.setAttribute("aria-label", `Thinking for ${slotLabel}`);
    thinkingSelect.append(subagentLaunchSlotOption("", "Default / inherit"));
    const supportedThinking = slot.model ? subagentLaunchSlotThinkingForModel(slot.model) : [];
    for (const thinking of supportedThinking) thinkingSelect.append(subagentLaunchSlotOption(thinking, thinking));
    if (slot.thinking && !supportedThinking.includes(slot.thinking)) {
      thinkingSelect.append(subagentLaunchSlotOption(slot.thinking, `Unavailable: ${slot.thinking}`, { disabled: true }));
    }
    thinkingSelect.value = slot.thinking || "";
    thinkingSelect.disabled = !slot.model || subagentLaunchSlotLoading || subagentLaunchSlotSaving || !modelsByKey.has(slot.model);
    thinkingSelect.addEventListener("change", () => {
      subagentLaunchSlotDraft = updateLaunchSlot(subagentLaunchSlotDraftRoles(), roleId, slot.id, { thinking: thinkingSelect.value || null });
      subagentLaunchSlotError = "";
      subagentLaunchSlotFocusTarget = { roleId, slotId: slot.id, control: "thinking" };
      renderSubagentLaunchSlots();
    });
    thinkingField.append(thinkingSelect);
    controls.append(modelField, thinkingField);
    row.append(controls);
    if (slot.id !== `${roleId}:base`) {
      const remove = make("button", "subagent-launch-slot-remove", "Remove");
      remove.type = "button";
      remove.disabled = subagentLaunchSlotLoading || subagentLaunchSlotSaving;
      remove.setAttribute("aria-label", `Remove ${slotLabel}`);
      remove.addEventListener("click", () => {
        const removed = removeLaunchSlot(subagentLaunchSlotDraftRoles(), roleId, slot.id);
        if (!removed) return;
        subagentLaunchSlotDraft = removed.roles;
        subagentLaunchSlotError = "";
        subagentLaunchSlotFocusTarget = removed.focusSlotId ? { roleId, slotId: removed.focusSlotId, control: "model" } : null;
        setSubagentLaunchSlotAnnouncement(`Removed ${slotLabel}.`);
        renderSubagentLaunchSlots();
      });
      row.append(remove);
    }
    list.append(row);
  }
  card.append(list);

  const add = make("button", "subagent-launch-slot-add", "Add slot");
  add.type = "button";
  const source = slots[slots.length - 1];
  const atRoleLimit = slots.length >= limits.slotsPerRole || subagentLaunchSlotTotal() >= limits.totalSlots;
  add.disabled = atRoleLimit || subagentLaunchSlotLoading || subagentLaunchSlotSaving;
  add.setAttribute("aria-label", `Add same ${role?.title || roleId} type from slot ${slots.length}`);
  add.addEventListener("click", () => {
    const slotId = newSubagentLaunchSlotId(subagentLaunchSlotDraftRoles());
    if (!slotId) {
      setSubagentLaunchSlotAnnouncement(`Could not generate a unique ${role?.title || roleId} slot identifier. Try again.`);
      return;
    }
    const added = addLaunchSlot(subagentLaunchSlotDraftRoles(), roleId, source?.id, {
      ...limits,
      createId: () => slotId,
    });
    if (!added) {
      setSubagentLaunchSlotAnnouncement(`Cannot add another ${role?.title || roleId} slot because the configured limit was reached.`);
      return;
    }
    subagentLaunchSlotDraft = added.roles;
    subagentLaunchSlotError = "";
    subagentLaunchSlotFocusTarget = { roleId, slotId: added.slot.id, control: "model" };
    setSubagentLaunchSlotAnnouncement(`Added ${role?.title || roleId} slot ${slots.length + 1}.`);
    renderSubagentLaunchSlots();
  });
  card.append(add);
  return card;
}

function renderSubagentLaunchSlots() {
  if (!elements.subagentLaunchSlotRoles) return;
  const config = subagentLaunchSlotConfig;
  const dirty = subagentLaunchSlotDraftIsDirty();
  const activeConfigTab = !!subagentLaunchSlotConfigTabId && subagentLaunchSlotConfigTabId === activeTabId;
  const saveState = subagentLaunchSlotSaveState({
    hasConfig: !!config,
    hasDraft: !!subagentLaunchSlotDraft,
    dirty,
    loading: subagentLaunchSlotLoading,
    saving: subagentLaunchSlotSaving,
    activeConfigTab,
  });
  if (elements.subagentLaunchSlotsSummaryStatus) {
    const roleCount = Array.isArray(config?.roleMetadata) ? config.roleMetadata.length : 8;
    elements.subagentLaunchSlotsSummaryStatus.textContent = subagentLaunchSlotError
      ? "Needs attention"
      : subagentLaunchSlotLoading
        ? "Loading launch presets…"
        : dirty
          ? "Unsaved changes"
          : subagentLaunchSlotReloadRequired && activeConfigTab
            ? "Saved · reload this tab"
            : config
              ? `${roleCount} roles · ${subagentLaunchSlotScope === "project" ? "project scope" : "user defaults"}`
              : "Select a running Pi tab";
  }
  if (elements.subagentLaunchSlots && (subagentLaunchSlotError || (subagentLaunchSlotReloadRequired && activeConfigTab))) {
    elements.subagentLaunchSlots.open = true;
  }
  if (elements.subagentLaunchSlotScope) {
    elements.subagentLaunchSlotScope.value = subagentLaunchSlotScope;
    elements.subagentLaunchSlotScope.disabled = subagentLaunchSlotLoading || subagentLaunchSlotSaving;
  }
  if (elements.subagentLaunchSlotsRefresh) elements.subagentLaunchSlotsRefresh.disabled = subagentLaunchSlotLoading || subagentLaunchSlotSaving;
  if (elements.subagentLaunchSlotScopeStatus) {
    elements.subagentLaunchSlotScopeStatus.textContent = config
      ? subagentLaunchSlotScope === "project"
        ? config.inherited
          ? `This project (${config.projectLabel || "current project"}) inherits your user defaults.`
          : `This project (${config.projectLabel || "current project"}) has its own launch-slot defaults.`
        : "User defaults apply to new projects unless that project has its own defaults."
      : "Select a running Pi tab to load its available models.";
  }
  if (elements.subagentLaunchSlotsInherit) {
    elements.subagentLaunchSlotsInherit.hidden = !(config && subagentLaunchSlotScope === "project" && !config.inherited);
    elements.subagentLaunchSlotsInherit.disabled = subagentLaunchSlotLoading || subagentLaunchSlotSaving || !activeConfigTab;
  }
  if (elements.subagentLaunchSlotsStatus) {
    const message = subagentLaunchSlotError || (subagentLaunchSlotLoading
      ? "Loading agent models…"
      : config
        ? !activeConfigTab
          ? "This unsaved draft belongs to a different tab. Switch back to save or reload it."
          : subagentLaunchSlotScope === "project" && config.inherited
            ? "This project currently inherits user-default launch slots."
            : "Model assignments are saved separately from the live monitor."
        : "Agent model configuration is unavailable.");
    elements.subagentLaunchSlotsStatus.textContent = message;
    elements.subagentLaunchSlotsStatus.classList.toggle("error", !!subagentLaunchSlotError);
  }
  if (elements.subagentLaunchSlotsSave) {
    elements.subagentLaunchSlotsSave.disabled = saveState.disabled;
    elements.subagentLaunchSlotsSave.textContent = subagentLaunchSlotSaving ? "Saving…" : "Save agent models";
  }
  if (elements.subagentLaunchSlotsDirty) {
    elements.subagentLaunchSlotsDirty.textContent = dirty
      ? `Unsaved changes · ${saveState.reason}`
      : saveState.reason;
  }
  if (elements.subagentLaunchSlotsReloadActions) {
    elements.subagentLaunchSlotsReloadActions.hidden = !(subagentLaunchSlotReloadRequired && activeConfigTab);
  }
  if (elements.subagentLaunchSlotsReload) elements.subagentLaunchSlotsReload.disabled = subagentLaunchSlotSaving || subagentLaunchSlotLoading;
  if (elements.subagentLaunchSlotsLater) elements.subagentLaunchSlotsLater.disabled = subagentLaunchSlotSaving || subagentLaunchSlotLoading;

  elements.subagentLaunchSlotRoles.setAttribute("aria-busy", subagentLaunchSlotLoading ? "true" : "false");
  elements.subagentLaunchSlotRoles.replaceChildren();
  if (!config) {
    elements.subagentLaunchSlotRoles.append(make("p", "subagent-launch-slot-empty", subagentLaunchSlotLoading ? "Loading launch-slot defaults…" : "No agent-model configuration is loaded."));
    return;
  }
  const roles = subagentLaunchSlotDraftRoles();
  for (const role of Array.isArray(config.roleMetadata) ? config.roleMetadata : []) {
    const slots = Array.isArray(roles[role.id]) ? roles[role.id] : [];
    if (slots.length) elements.subagentLaunchSlotRoles.append(renderSubagentLaunchSlotCard(role, slots));
  }
  focusSubagentLaunchSlotControl();
}

async function loadSubagentLaunchSlotConfig({ tabId = activeTabId, scope = subagentLaunchSlotScope } = {}) {
  if (!tabId) {
    renderSubagentLaunchSlots();
    return;
  }
  const requestSerial = ++subagentLaunchSlotRequestSerial;
  subagentLaunchSlotLoading = true;
  subagentLaunchSlotError = "";
  renderSubagentLaunchSlots();
  try {
    const query = new URLSearchParams({ tab: tabId, scope });
    const response = await api(`/api/subagents/config?${query}`, { scoped: false });
    if (requestSerial !== subagentLaunchSlotRequestSerial || tabId !== activeTabId || scope !== subagentLaunchSlotScope) return;
    subagentLaunchSlotConfig = response.data || null;
    subagentLaunchSlotConfigTabId = tabId;
    subagentLaunchSlotDraft = cloneLaunchSlotRoles(response.data?.roles || {});
    subagentLaunchSlotReloadRequired = subagentLaunchSlotReloadTabs.has(tabId);
  } catch (error) {
    if (requestSerial !== subagentLaunchSlotRequestSerial) return;
    subagentLaunchSlotError = `Could not load agent models: ${error.message || String(error)}`;
  } finally {
    if (requestSerial === subagentLaunchSlotRequestSerial) {
      subagentLaunchSlotLoading = false;
      renderSubagentLaunchSlots();
    }
  }
}

async function confirmDiscardSubagentLaunchSlotDraft(action) {
  if (!subagentLaunchSlotDraftIsDirty()) return true;
  return appConfirm({
    title: "Discard unsaved agent models?",
    summary: `${action} replaces the current launch-slot draft with saved settings.`,
    affected: "Unsaved model and thinking assignments in this browser tab",
    undoable: false,
    confirmLabel: "Discard changes",
  });
}

async function selectSubagentLaunchSlotScope(scope) {
  const nextScope = scope === "project" ? "project" : "user";
  if (nextScope === subagentLaunchSlotScope) return;
  if (!(await confirmDiscardSubagentLaunchSlotDraft("Changing scope"))) {
    renderSubagentLaunchSlots();
    return;
  }
  subagentLaunchSlotScope = nextScope;
  subagentLaunchSlotReloadRequired = false;
  await loadSubagentLaunchSlotConfig();
}

async function reloadSubagentLaunchSlotConfig() {
  if (!(await confirmDiscardSubagentLaunchSlotDraft("Reloading configuration"))) return;
  subagentLaunchSlotReloadRequired = false;
  await loadSubagentLaunchSlotConfig();
}

function applySavedSubagentLaunchSlotConfig(data) {
  subagentLaunchSlotConfig = data || null;
  subagentLaunchSlotConfigTabId = activeTabId;
  subagentLaunchSlotDraft = cloneLaunchSlotRoles(data?.roles || {});
  if (data?.changed === true && data?.reloadRequired === true && activeTabId) {
    subagentLaunchSlotReloadTabs.add(activeTabId);
  }
  subagentLaunchSlotReloadRequired = subagentLaunchSlotReloadTabs.has(activeTabId);
}

async function saveSubagentLaunchSlotConfig({ inherit = false } = {}) {
  if (!subagentLaunchSlotConfig || !subagentLaunchSlotConfigTabId || subagentLaunchSlotConfigTabId !== activeTabId) {
    subagentLaunchSlotError = "Return to the tab that owns this launch-slot draft before saving.";
    renderSubagentLaunchSlots();
    return;
  }
  subagentLaunchSlotSaving = true;
  subagentLaunchSlotError = "";
  renderSubagentLaunchSlots();
  try {
    const body = {
      tab: activeTabId,
      scope: subagentLaunchSlotScope,
      revision: subagentLaunchSlotConfig.revision,
    };
    if (inherit) body.inherit = true;
    else body.roles = cloneLaunchSlotRoles(subagentLaunchSlotDraftRoles());
    const response = await api("/api/subagents/config", { method: "POST", body, scoped: false });
    applySavedSubagentLaunchSlotConfig(response.data);
    setSubagentLaunchSlotAnnouncement(inherit ? "This project now uses user-default agent models." : "Agent models saved.");
  } catch (error) {
    const conflict = error?.statusCode === 409;
    subagentLaunchSlotError = `${conflict ? "Conflict: reload configuration before saving." : "Could not save agent models:"} ${conflict ? "" : error.message || String(error)}`.trim();
  } finally {
    subagentLaunchSlotSaving = false;
    renderSubagentLaunchSlots();
  }
}

async function resetSubagentLaunchSlotProjectScope() {
  if (subagentLaunchSlotScope !== "project" || !subagentLaunchSlotConfig || subagentLaunchSlotConfig.inherited) return;
  if (!(await confirmDiscardSubagentLaunchSlotDraft("Using user defaults"))) return;
  await saveSubagentLaunchSlotConfig({ inherit: true });
}

async function reloadActiveTabForSubagentLaunchSlots() {
  if (!subagentLaunchSlotReloadRequired || subagentLaunchSlotConfigTabId !== activeTabId) return;
  subagentLaunchSlotSaving = true;
  subagentLaunchSlotError = "";
  renderSubagentLaunchSlots();
  try {
    await sendPrompt("prompt", "/reload", { targetTabId: activeTabId, throwOnError: true });
    subagentLaunchSlotReloadTabs.delete(activeTabId);
    subagentLaunchSlotReloadRequired = false;
    setSubagentLaunchSlotAnnouncement("Active tab reloaded. Agent model guidance now applies to future launches.");
    await loadSubagentLaunchSlotConfig();
  } catch (error) {
    subagentLaunchSlotError = `Could not reload the active tab: ${error.message || String(error)}`;
  } finally {
    subagentLaunchSlotSaving = false;
    renderSubagentLaunchSlots();
  }
}

// The launch-slot editor lives in a collapsed <details> inside the (usually collapsed) Subagents
// section, yet its config payload is one of the largest boot requests (~290 KB uncompressed).
// Load it lazily: only when the editor is actually visible, otherwise on first reveal.
let subagentLaunchSlotConfigDeferred = false;

function subagentLaunchSlotsVisible() {
  const details = elements.subagentLaunchSlots;
  if (!details || !details.open) return false;
  const section = details.closest?.("[data-side-panel-section]");
  return !section || (!section.hidden && !section.classList.contains("collapsed"));
}

function loadSubagentLaunchSlotConfigWhenVisible(options = {}) {
  if (subagentLaunchSlotsVisible()) {
    subagentLaunchSlotConfigDeferred = false;
    return loadSubagentLaunchSlotConfig(options);
  }
  subagentLaunchSlotConfigDeferred = true;
  renderSubagentLaunchSlots();
  return Promise.resolve();
}

function revealSubagentLaunchSlotConfigIfDeferred() {
  if (!subagentLaunchSlotConfigDeferred || !subagentLaunchSlotsVisible()) return;
  subagentLaunchSlotConfigDeferred = false;
  loadSubagentLaunchSlotConfig().catch(() => {});
}

function initializeSubagentLaunchSlots() {
  renderSubagentLaunchSlots();
  if (activeTabId) loadSubagentLaunchSlotConfigWhenVisible().catch(() => {});
  elements.subagentLaunchSlots?.addEventListener("toggle", () => revealSubagentLaunchSlotConfigIfDeferred());
}

function samplingParametersPath(tabId) {
  return `/api/tabs/${encodeURIComponent(tabId)}/sampling-parameters`;
}

const samplingParameterControlElements = new Map();
let samplingParameterTooltipDismissalInstalled = false;

function samplingParameterTooltipBoundary(row) {
  const viewportHeight = globalThis.innerHeight || document.documentElement?.clientHeight || 0;
  const clippingRects = [row?.closest?.(".side-panel-section-content"), row?.closest?.(".side-panel-body")]
    .map((node) => node?.getBoundingClientRect?.())
    .filter(Boolean);
  return {
    top: Math.max(8, ...clippingRects.map((rect) => rect.top)),
    bottom: Math.min(viewportHeight - 8, ...clippingRects.map((rect) => rect.bottom)),
  };
}

function updateSamplingParameterTooltipPlacement(row, tooltip) {
  if (!row?.classList.contains("unsupported") || tooltip?.hidden || !row.getBoundingClientRect || !tooltip.getBoundingClientRect) return;
  tooltip.classList.remove("sampling-tooltip-below");
  tooltip.style?.removeProperty("--sampling-tooltip-max-height");
  const rowRect = row.getBoundingClientRect();
  const naturalHeight = Math.max(tooltip.scrollHeight || 0, tooltip.getBoundingClientRect().height || 0);
  const boundary = samplingParameterTooltipBoundary(row);
  const spaceAbove = Math.max(0, rowRect.top - boundary.top - 6);
  const spaceBelow = Math.max(0, boundary.bottom - rowRect.bottom - 6);
  const placeBelow = spaceAbove < naturalHeight && spaceBelow > spaceAbove;
  const availableHeight = placeBelow ? spaceBelow : spaceAbove;
  tooltip.classList.toggle("sampling-tooltip-below", placeBelow);
  tooltip.style?.setProperty("--sampling-tooltip-max-height", `${Math.floor(availableHeight)}px`);
}

function resetSamplingParameterTooltip(row, tooltip) {
  row?.classList.remove("sampling-tooltip-dismissed");
  updateSamplingParameterTooltipPlacement(row, tooltip);
}

function dismissSamplingParameterTooltip(row, event) {
  if (!row?.classList.contains("unsupported") || row.classList.contains("sampling-tooltip-dismissed")) return false;
  row.classList.add("sampling-tooltip-dismissed");
  event?.preventDefault?.();
  event?.stopPropagation?.();
  return true;
}

function initializeSamplingParameterTooltipDismissal() {
  if (samplingParameterTooltipDismissalInstalled || typeof document.addEventListener !== "function") return;
  samplingParameterTooltipDismissalInstalled = true;
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || event.target?.closest?.(".sampling-parameter-control.unsupported")) return;
    const hovered = document.querySelector?.(".sampling-parameter-control.unsupported:hover:not(.sampling-tooltip-dismissed)");
    if (hovered) dismissSamplingParameterTooltip(hovered, event);
  });
}

function cloneSamplingControlDraft(draft) {
  return draft ? JSON.parse(JSON.stringify(draft)) : null;
}

function samplingParametersBaseDraft(tabId = activeTabId) {
  if (!tabId || samplingParametersStateTabId !== tabId || !samplingParametersState) return null;
  return createSamplingControlDraft(samplingParametersState.session || {}, {
    defaults: samplingParametersState.defaults || {},
  });
}

function samplingParametersDraft(tabId = activeTabId) {
  return tabId ? samplingParametersDrafts.get(tabId) ?? null : null;
}

function setSamplingParametersDraft(draft, tabId = activeTabId) {
  if (!tabId) return;
  if (draft === null) samplingParametersDrafts.delete(tabId);
  else samplingParametersDrafts.set(tabId, cloneSamplingControlDraft(draft));
}

function samplingParametersEditableDraft(tabId = activeTabId) {
  return samplingParametersDraft(tabId) || samplingParametersBaseDraft(tabId);
}

// Drafts are keyed by Pi tab so background refreshes and tab switches cannot
// overwrite or expose another session's unsaved controls.
function samplingParametersDraftIsDirty(tabId = activeTabId) {
  const draft = samplingParametersDraft(tabId);
  if (!draft) return false;
  const baseline = samplingParametersBaseDraft(tabId);
  return !baseline || !samplingControlDraftEquals(draft, baseline);
}

function samplingParametersSectionRecord() {
  return sidePanelSectionRecords().find(({ id }) => id === "sampling") || null;
}

function samplingParametersSectionActive() {
  const record = samplingParametersSectionRecord();
  return !!record && !record.section.hidden && !record.section.classList.contains("collapsed");
}

function samplingParametersSupportText() {
  const state = samplingParametersStateTabId === activeTabId ? samplingParametersState : null;
  const support = state?.support;
  if (!support) return samplingParametersLoading ? "Loading sampling support…" : "Select a running Pi tab to load sampling parameters.";
  const modelLabel = support.model?.provider && support.model?.id ? `(${support.model.provider}) ${support.model.id}` : "unknown model";
  const apiLabel = support.api || "unknown API";
  if (support.supported) return `${modelLabel} · ${apiLabel} · ${support.message || "Sampling parameters apply to subsequent provider requests."}`;
  const compatible = Array.isArray(support.compatibleApis) && support.compatibleApis.length
    ? ` Sampling-capable APIs: ${support.compatibleApis.join(", ")}.`
    : "";
  return `${modelLabel} · ${apiLabel} · ${support.message || "Sampling parameters are stored but not applied."}${compatible}`;
}

// Success and error text describes one tab's last action, so it is suppressed as soon
// as another tab becomes active instead of leaking into the new tab's status line.
function samplingParametersFeedbackIsCurrent() {
  return samplingParametersFeedbackTabId === activeTabId;
}

function setSamplingParametersFeedback({ error = "", notice = "" } = {}) {
  samplingParametersError = error;
  samplingParametersNotice = notice;
  samplingParametersFeedbackTabId = error || notice ? activeTabId : null;
}

function samplingParametersStatusText({ dirty, unsupported, validation, loadedForActiveTab }) {
  const feedbackCurrent = samplingParametersFeedbackIsCurrent();
  if (samplingParametersError && feedbackCurrent) return samplingParametersError;
  if (samplingParametersBusy) return "Applying sampling parameters…";
  if (samplingParametersLoading) return "Loading session sampling parameters…";
  if (!activeTabId) return "Select a running Pi tab to edit sampling parameters.";
  if (samplingParametersNotice && feedbackCurrent) return samplingParametersNotice;
  if (!loadedForActiveTab) return "Sampling parameters are not loaded for this tab.";
  if (!validation.valid) return Object.values(validation.errors)[0] || "Correct invalid sampling values before applying.";
  if (unsupported) return "This model has no verified sampling parameters, so applying them is disabled.";
  if (dirty) return "Unsaved controls · Apply stores enabled values for this session only.";
  return "Saved for this Pi session · unchecked parameters inherit model defaults.";
}

function samplingParameterCapabilities(state) {
  return Object.fromEntries(SAMPLING_PARAMETER_CATALOG.map(({ key }) => [
    key,
    samplingParameterCapability(state?.support?.parameters, key),
  ]));
}

function samplingParameterDomId(key, suffix) {
  return `samplingParameter${key.split("_").map((part) => part[0].toUpperCase() + part.slice(1)).join("")}${suffix}`;
}

function samplingParameterDisplayValue(parameters, key) {
  if (!parameters || typeof parameters !== "object" || !Object.hasOwn(parameters, key)) return "Inherited";
  const value = parameters[key];
  return typeof value === "number" && Number.isFinite(value) ? String(value) : "Invalid or unsupported value";
}

function updateSamplingParameterControl(key, mutate) {
  const baseline = samplingParametersEditableDraft();
  if (!baseline || samplingParametersStateTabId !== activeTabId) return;
  const next = cloneSamplingControlDraft(baseline);
  mutate(next.controls[key]);
  setSamplingParametersDraft(next);
  setSamplingParametersFeedback();
  renderSamplingParameters();
}

function initializeSamplingParameterControls() {
  if (!elements.samplingParametersControls || samplingParameterControlElements.size) return;
  initializeSamplingParameterTooltipDismissal();
  const groups = new Map();
  for (const [name, label] of [["core", "OpenAI-compatible controls"], ["server-extension", "Server extensions"]]) {
    const section = document.createElement("section");
    section.className = "sampling-parameter-group";
    section.dataset.samplingParameterGroup = name;
    const heading = document.createElement("h3");
    heading.textContent = label;
    section.append(heading);
    elements.samplingParametersControls.append(section);
    groups.set(name, section);
  }

  for (const definition of SAMPLING_PARAMETER_CATALOG) {
    const row = document.createElement("div");
    row.className = "sampling-parameter-control";
    row.dataset.samplingParameter = definition.key;
    row.setAttribute("role", "group");

    const enableId = samplingParameterDomId(definition.key, "Enabled");
    const valueId = samplingParameterDomId(definition.key, "Value");
    const rangeId = samplingParameterDomId(definition.key, "Range");
    const descriptionId = samplingParameterDomId(definition.key, "Description");
    const errorId = samplingParameterDomId(definition.key, "Error");
    const tooltipId = samplingParameterDomId(definition.key, "UnsupportedReason");
    row.setAttribute("aria-labelledby", `${enableId}Label`);

    const header = document.createElement("div");
    header.className = "sampling-parameter-control-header";
    const enable = document.createElement("input");
    enable.id = enableId;
    enable.type = "checkbox";
    const label = document.createElement("label");
    label.id = `${enableId}Label`;
    label.htmlFor = enableId;
    label.textContent = definition.label;
    const scope = document.createElement("span");
    scope.className = "sampling-parameter-scope";
    scope.textContent = definition.scopeLabel;
    header.append(enable, label, scope);

    const description = document.createElement("p");
    description.id = descriptionId;
    description.className = "sampling-parameter-description";
    description.textContent = definition.description;

    const editor = document.createElement("div");
    editor.className = "sampling-parameter-editor";
    const number = document.createElement("input");
    number.id = valueId;
    number.className = "sampling-parameter-number";
    number.type = "number";
    number.inputMode = definition.kind === "integer" ? "numeric" : "decimal";
    number.step = String(definition.step);
    if (definition.min !== undefined && !definition.minExclusive) number.min = String(definition.min);
    if (definition.max !== undefined) number.max = String(definition.max);
    number.setAttribute("aria-label", `${definition.label} exact value`);
    number.setAttribute("aria-describedby", `${descriptionId} ${errorId}`);
    const range = document.createElement("input");
    range.id = rangeId;
    range.className = "sampling-parameter-range";
    range.type = "range";
    range.min = String(definition.slider.min);
    range.max = String(definition.slider.max);
    range.step = String(definition.slider.step);
    range.setAttribute("aria-label", `${definition.label} common-range slider`);
    range.setAttribute("aria-describedby", descriptionId);
    editor.append(number, range);

    const context = document.createElement("dl");
    context.className = "sampling-parameter-context";
    const defaultTerm = document.createElement("dt");
    defaultTerm.textContent = "Model default";
    const defaultValue = document.createElement("dd");
    const effectiveTerm = document.createElement("dt");
    effectiveTerm.textContent = "Effective";
    const effectiveValue = document.createElement("dd");
    context.append(defaultTerm, defaultValue, effectiveTerm, effectiveValue);

    const error = document.createElement("p");
    error.id = errorId;
    error.className = "sampling-parameter-error";
    error.setAttribute("aria-live", "polite");

    const tooltip = document.createElement("p");
    tooltip.id = tooltipId;
    tooltip.className = "sampling-parameter-unsupported-tooltip";
    tooltip.setAttribute("role", "tooltip");

    enable.addEventListener("change", () => updateSamplingParameterControl(definition.key, (control) => {
      control.enabled = enable.checked;
    }));
    number.addEventListener("input", () => updateSamplingParameterControl(definition.key, (control) => {
      control.value = number.value;
    }));
    range.addEventListener("input", () => updateSamplingParameterControl(definition.key, (control) => {
      control.value = range.value;
    }));
    row.addEventListener("keydown", (event) => {
      if (event.key === "Escape") dismissSamplingParameterTooltip(row, event);
    });
    row.addEventListener("pointerenter", () => resetSamplingParameterTooltip(row, tooltip));
    row.addEventListener("focusin", () => resetSamplingParameterTooltip(row, tooltip));
    row.addEventListener("focusout", (event) => {
      if (!row.contains?.(event.relatedTarget) && !row.matches?.(":hover")) row.classList.remove("sampling-tooltip-dismissed");
    });

    row.append(header, description, editor, context, error, tooltip);
    groups.get(definition.group)?.append(row);
    samplingParameterControlElements.set(definition.key, { row, enable, number, range, defaultValue, effectiveValue, error, tooltip });
  }
}

function renderSamplingParameters() {
  initializeSamplingParameterControls();
  const loadedForActiveTab = !!samplingParametersState && samplingParametersStateTabId === activeTabId;
  const activeState = loadedForActiveTab ? samplingParametersState : null;
  const editableDraft = samplingParametersEditableDraft()
    || createSamplingControlDraft({}, { defaults: activeState?.defaults || {} });
  const validation = validateSamplingControlDraft(editableDraft);
  const dirty = samplingParametersDraftIsDirty();
  const capabilities = samplingParameterCapabilities(activeState);
  const unsupported = !Object.values(capabilities).some(({ supported }) => supported);
  const feedbackError = !!samplingParametersError && samplingParametersFeedbackIsCurrent();
  const showError = feedbackError || !validation.valid;
  const defaults = splitSamplingParameters(activeState?.defaults || {}).known;
  const effective = splitSamplingParameters(activeState?.effective || {}).known;
  const controlsDisabled = samplingParametersBusy || samplingParametersLoading || !activeTabId || !loadedForActiveTab;

  for (const definition of SAMPLING_PARAMETER_CATALOG) {
    const refs = samplingParameterControlElements.get(definition.key);
    if (!refs) continue;
    const control = editableDraft.controls[definition.key];
    const capability = capabilities[definition.key];
    const parameterUnsupported = !capability.supported;
    const error = validation.errors[definition.key] || "";
    const valueText = typeof control.value === "number" || typeof control.value === "string" ? String(control.value) : "";
    const tooltipId = samplingParameterDomId(definition.key, "UnsupportedReason");
    refs.enable.checked = control.enabled;
    refs.enable.disabled = controlsDisabled || parameterUnsupported;
    refs.number.disabled = controlsDisabled || parameterUnsupported || !control.enabled;
    refs.range.disabled = controlsDisabled || parameterUnsupported || !control.enabled;
    if (refs.number.value !== valueText) refs.number.value = valueText;
    refs.range.value = String(samplingParameterSliderValue(definition.key, control.value));
    refs.number.setAttribute("aria-invalid", error ? "true" : "false");
    refs.row.classList.toggle("enabled", control.enabled);
    refs.row.classList.toggle("invalid", !!error);
    refs.row.classList.toggle("unsupported", parameterUnsupported);
    refs.row.tabIndex = parameterUnsupported ? 0 : -1;
    if (parameterUnsupported) {
      refs.row.setAttribute("aria-disabled", "true");
      refs.row.setAttribute("aria-describedby", tooltipId);
      refs.enable.setAttribute("aria-describedby", tooltipId);
    } else {
      refs.row.removeAttribute("aria-disabled");
      refs.row.removeAttribute("aria-describedby");
      refs.enable.removeAttribute("aria-describedby");
      refs.row.classList.remove("sampling-tooltip-dismissed");
    }
    refs.defaultValue.textContent = samplingParameterDisplayValue(defaults, definition.key);
    refs.effectiveValue.textContent = samplingParameterDisplayValue(effective, definition.key);
    refs.error.textContent = error;
    refs.error.hidden = !error;
    refs.tooltip.hidden = !parameterUnsupported;
    refs.tooltip.textContent = parameterUnsupported ? capability.reason : "";
  }

  if (elements.samplingParametersSupport) {
    elements.samplingParametersSupport.textContent = samplingParametersSupportText();
    elements.samplingParametersSupport.classList.toggle("warning", unsupported);
  }
  if (elements.samplingParametersPreserved) {
    elements.samplingParametersPreserved.textContent = loadedForActiveTab
      ? summarizePreservedSamplingParameters(editableDraft.preservedUnknown).text
      : samplingParametersLoading ? "Loading additional parameter state…" : "Additional parameter state is not loaded for this tab.";
  }
  if (elements.applySamplingParametersButton) {
    elements.applySamplingParametersButton.disabled = samplingParametersBusy
      || samplingParametersLoading
      || !activeTabId
      || !loadedForActiveTab
      || unsupported
      || !validation.valid;
    elements.applySamplingParametersButton.textContent = samplingParametersBusy ? "Applying…" : "Apply";
  }
  if (elements.resetSamplingParametersButton) {
    elements.resetSamplingParametersButton.disabled = samplingParametersBusy
      || samplingParametersLoading
      || !activeTabId
      || !loadedForActiveTab;
  }
  if (elements.reloadSamplingParametersButton) {
    elements.reloadSamplingParametersButton.disabled = samplingParametersBusy || samplingParametersLoading || !activeTabId;
  }
  if (elements.samplingParametersStatus) {
    elements.samplingParametersStatus.textContent = samplingParametersStatusText({ dirty, unsupported, validation, loadedForActiveTab });
    elements.samplingParametersStatus.classList.toggle("error", showError);
    elements.samplingParametersStatus.classList.toggle("warning", !showError && unsupported);
  }
}

function applySamplingParametersResponse(data, tabId) {
  const existingDraft = samplingParametersDraft(tabId);
  samplingParametersState = data || null;
  samplingParametersStateTabId = tabId;
  if (existingDraft) {
    const loadedDraft = samplingParametersBaseDraft(tabId);
    existingDraft.preservedUnknown = cloneSamplingControlDraft(loadedDraft)?.preservedUnknown || {};
    setSamplingParametersDraft(existingDraft, tabId);
  }
  if (!samplingParametersDraftIsDirty(tabId)) setSamplingParametersDraft(null, tabId);
}

async function loadSamplingParameters({ tabId = activeTabId, force = false } = {}) {
  if (!tabId) {
    samplingParametersState = null;
    samplingParametersStateTabId = null;
    renderSamplingParameters();
    return;
  }
  // Structured drafts are stored separately from loaded state, so a background
  // refresh can update support/default/hidden-key context without discarding edits.
  if (force) setSamplingParametersDraft(null, tabId);
  const requestSerial = ++samplingParametersRequestSerial;
  samplingParametersLoading = true;
  setSamplingParametersFeedback();
  renderSamplingParameters();
  try {
    const response = await api(samplingParametersPath(tabId), { scoped: false });
    if (requestSerial !== samplingParametersRequestSerial || tabId !== activeTabId) return;
    applySamplingParametersResponse(response.data, tabId);
  } catch (error) {
    if (requestSerial !== samplingParametersRequestSerial || tabId !== activeTabId) return;
    setSamplingParametersFeedback({ error: `Could not load sampling parameters: ${error.message || String(error)}` });
  } finally {
    if (requestSerial === samplingParametersRequestSerial) {
      samplingParametersLoading = false;
      renderSamplingParameters();
    }
  }
}

// Background refresh for tab and model changes. It stays quiet until the section has
// been opened once, so collapsed panels never pay for helper round-trips.
function refreshSamplingParametersForTabContext(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  if (!samplingParametersState && !samplingParametersSectionActive()) return;
  return loadSamplingParameters({ tabId: tabContext.tabId }).catch(() => {});
}

async function writeSamplingParameters(samplingParams, { successNotice }) {
  const tabId = activeTabId;
  if (!tabId) return;
  const requestSerial = ++samplingParametersRequestSerial;
  samplingParametersBusy = true;
  setSamplingParametersFeedback();
  renderSamplingParameters();
  try {
    const response = await api(samplingParametersPath(tabId), { method: "PUT", body: samplingParams, scoped: false });
    setSamplingParametersDraft(null, tabId);
    if (requestSerial !== samplingParametersRequestSerial || tabId !== activeTabId) return;
    applySamplingParametersResponse(response.data, tabId);
    setSamplingParametersFeedback({ notice: successNotice });
  } catch (error) {
    if (requestSerial !== samplingParametersRequestSerial || tabId !== activeTabId) return;
    setSamplingParametersFeedback({ error: `Could not save sampling parameters: ${error.message || String(error)}` });
  } finally {
    // Writes are serialized by the busy guard. A tab/model refresh may supersede
    // the response serial, but it must never strand the section in a busy state.
    samplingParametersBusy = false;
    renderSamplingParameters();
  }
}

async function applySamplingParameters() {
  if (!activeTabId || samplingParametersBusy) return;
  if (!samplingParametersState || samplingParametersStateTabId !== activeTabId) {
    setSamplingParametersFeedback({ error: "Wait for this tab's sampling parameters to load before applying changes." });
    renderSamplingParameters();
    return;
  }
  const capabilities = samplingParameterCapabilities(samplingParametersState);
  if (!Object.values(capabilities).some(({ supported }) => supported)) {
    setSamplingParametersFeedback({ error: "This model has no verified sampling parameters, so nothing was sent." });
    renderSamplingParameters();
    return;
  }
  const draft = samplingParametersEditableDraft();
  const validation = validateSamplingControlDraft(draft);
  if (!validation.valid) {
    setSamplingParametersFeedback({ error: Object.values(validation.errors)[0] || "Correct invalid sampling values before applying." });
    renderSamplingParameters();
    return;
  }
  const samplingParams = buildSamplingParametersFromDraft(draft);
  await writeSamplingParameters(samplingParams, {
    successNotice: Object.keys(samplingParams).length
      ? "Applied to this Pi session · affects subsequent provider requests."
      : "Session override cleared · model defaults apply.",
  });
}

async function resetSamplingParameters() {
  if (!activeTabId || samplingParametersBusy) return;
  if (!samplingParametersState || samplingParametersStateTabId !== activeTabId) {
    setSamplingParametersFeedback({ error: "Wait for this tab's sampling parameters to load before resetting them." });
    renderSamplingParameters();
    return;
  }
  await writeSamplingParameters({}, { successNotice: "Session override cleared · model defaults apply." });
}

// Lazy loader for surfaces that reveal the section (side-panel expand/visibility,
// mobile canonical mount) after the initial page load.
function ensureSamplingParametersLoaded() {
  if (!activeTabId || samplingParametersLoading || samplingParametersBusy) return;
  if (samplingParametersState && samplingParametersStateTabId === activeTabId) return;
  loadSamplingParameters().catch(() => {});
}

function initializeSamplingParameters() {
  initializeSamplingParameterControls();
  renderSamplingParameters();
  if (samplingParametersSectionActive()) ensureSamplingParametersLoaded();
}

function sessionCopyButton(label, value) {
  const button = make("button", "session-copy-button", "Copy");
  button.type = "button";
  button.title = `Copy ${label.toLowerCase()}`;
  button.setAttribute("aria-label", button.title);
  button.addEventListener("click", async () => {
    const original = button.textContent;
    try {
      await copyText(value);
      button.textContent = "Copied";
      button.classList.add("copied");
    } catch {
      button.textContent = "Failed";
    }
    setTimeout(() => {
      if (!button.isConnected) return;
      button.textContent = original;
      button.classList.remove("copied");
    }, 1400);
  });
  return button;
}

function sessionDetailField(label, value, { secondary = "", copyValue = "", mono = false, truncate = false, wide = false } = {}) {
  const field = make("div", `session-detail-field${wide ? " wide" : ""}`);
  const labelNode = make("span", "session-detail-label", label);
  const valueRow = make("div", "session-detail-value-row");
  const valueCopy = make("div", `session-detail-value${mono ? " mono" : ""}${truncate ? " truncate" : ""}`);
  const primary = make("span", "session-detail-primary", value);
  primary.title = copyValue || value;
  valueCopy.append(primary);
  if (secondary) {
    const secondaryNode = make("span", "session-detail-secondary", secondary);
    secondaryNode.title = copyValue || secondary;
    valueCopy.append(secondaryNode);
  }
  valueRow.append(valueCopy);
  if (copyValue) valueRow.append(sessionCopyButton(label, copyValue));
  field.append(labelNode, valueRow);
  return field;
}

function splitSessionFilePath(sessionFile) {
  const value = String(sessionFile || "");
  const separator = Math.max(value.lastIndexOf("/"), value.lastIndexOf("\\"));
  if (separator < 0) return { name: value || "in-memory", directory: "" };
  const directory = value.slice(0, separator).replace(/^\/home\/[^/]+(?=\/|$)/, "~");
  return { name: value.slice(separator + 1) || value, directory };
}

function renderStatus() {
  if (deferUiRenderDuringPointerActivation("status", renderStatus)) return;
  const state = currentState;
  updateComposerModeButtons();
  const statusKey = state?.isCompacting ? "compacting" : state?.isStreaming ? "running" : "idle";
  const statusLabel = statusKey[0].toUpperCase() + statusKey.slice(1);

  elements.stateDetails.replaceChildren();
  const pendingThinkingLevel = state?.pendingThinkingLevel || null;
  const shownThinkingLevel = pendingThinkingLevel || state?.thinkingLevel;
  const thinkingDetail = pendingThinkingLevel && pendingThinkingLevel !== state?.thinkingLevel
    ? `${state?.thinkingLevel || "unknown"} → ${pendingThinkingLevel} next prompt`
    : state?.thinkingLevel || "unknown";
  const overview = make("div", "session-overview");
  const statusCard = make("div", `session-status-card ${statusKey}`);
  const statusDot = make("span", "session-status-dot");
  statusDot.setAttribute("aria-hidden", "true");
  const statusCopy = make("span", "session-overview-copy");
  statusCopy.append(make("span", "session-overview-label", "Status"), make("strong", undefined, statusLabel));
  statusCard.append(statusDot, statusCopy);
  const messagesCard = make("div", "session-metric-card");
  messagesCard.append(make("span", "session-overview-label", "Messages"), make("strong", undefined, String(state?.messageCount ?? "?")));
  const queueCard = make("div", "session-metric-card");
  queueCard.append(make("span", "session-overview-label", "Queue"), make("strong", undefined, String(state?.pendingMessageCount ?? 0)));
  overview.append(statusCard, messagesCard, queueCard);

  const sessionId = state?.sessionId || "unknown";
  const sessionName = state?.sessionName && state.sessionName !== sessionId ? state.sessionName : "";
  const sessionFile = state?.sessionFile || "";
  const fileParts = splitSessionFilePath(sessionFile);
  const infoGrid = make("div", "session-info-grid");
  infoGrid.append(
    sessionDetailField("Model", modelLabel(state?.model), { wide: true, truncate: true }),
    sessionDetailField("Thinking", thinkingDetail, { truncate: true }),
    sessionDetailField("Auto compact", footerAutoCompactionEnabled(state) ? "On" : "Off"),
    sessionDetailField("Session ID", sessionName || sessionId, {
      secondary: sessionName ? sessionId : "",
      copyValue: sessionId !== "unknown" ? sessionId : "",
      mono: !sessionName,
      wide: true,
    }),
    sessionDetailField("Session file", fileParts.name, {
      secondary: fileParts.directory,
      copyValue: sessionFile,
      mono: true,
      truncate: true,
      wide: true,
    }),
  );
  elements.stateDetails.append(overview, infoGrid);

  if (controlsPendingThinkingValue && shownThinkingLevel === controlsPendingThinkingValue) setControlsPendingThinking("");
  if (shownThinkingLevel && !controlsPendingThinkingValue) elements.thinkingSelect.value = shownThinkingLevel;
  syncThinkingSelectSupport();
  elements.compactButton.disabled = !!state?.isCompacting;
  elements.compactButton.textContent = state?.isCompacting ? "Compacting…" : "Compact";
  syncModelSelectToState();
  renderFooter();
  renderContextMeter();
  renderWorkspaceDashboard();
  renderFeedbackTray();
}

function normalizeDialogText(text, { preserveAnsi = false } = {}) {
  const normalized = String(text ?? "").replace(/\r\n?/g, "\n");
  return preserveAnsi ? normalized : stripAnsi(normalized);
}

function normalizeDialogPrompt(request) {
  const rawTitle = normalizeDialogText(request.title || "Pi request", { preserveAnsi: true });
  const rawMessage = normalizeDialogText(request.message || request.placeholder || "", { preserveAnsi: true });

  if (rawTitle.includes("\n")) {
    const lines = rawTitle.split("\n");
    const titleIndex = lines.findIndex((line) => stripAnsi(line).trim());
    if (titleIndex !== -1) {
      const titleBody = lines.slice(titleIndex + 1).join("\n").replace(/^\n+/, "").trimEnd();
      const message = [titleBody, rawMessage.trimEnd()].filter((part) => stripAnsi(part).trim()).join("\n\n");
      return {
        title: stripAnsi(lines[titleIndex]).trim(),
        message,
        plainMessage: stripAnsi(message),
      };
    }
  }

  const message = rawMessage.trimEnd();
  return {
    title: stripAnsi(rawTitle).trim() || "Pi request",
    message,
    plainMessage: stripAnsi(message),
  };
}

function isGuardrailDialogPrompt(prompt) {
  const plainTitle = stripAnsi(prompt.title || "");
  const plainMessage = prompt.plainMessage ?? stripAnsi(prompt.message || "");
  return /(?:dangerous|high-risk|protected).*(?:command|file)|safety rule|execute anyway\?/i.test(`${plainTitle}\n${plainMessage}`);
}

function releaseDialogPromptParts(prompt) {
  const combined = [prompt.title, prompt.message].filter((part) => stripAnsi(part).trim()).join("\n").trimEnd();
  const lines = combined.split("\n");
  const questionIndex = lines.findIndex((line) => /^(Publish eligible packages now\?|Publish to AUR\?|Publish newly created\/converged AUR package\?)$/i.test(stripAnsi(line).trim()));
  const question = questionIndex === -1 ? "Publish eligible packages now?" : stripAnsi(lines[questionIndex]).trim();
  const isNpmReleasePrompt = /Release preflight summary:/i.test(combined) && /Publish eligible packages now\?/i.test(combined);
  const isAurReleasePrompt = /AUR release summary:/i.test(combined) && questionIndex !== -1;
  if (!isNpmReleasePrompt && !isAurReleasePrompt) return null;

  const summaryLines = questionIndex === -1 ? lines : [...lines.slice(0, questionIndex), ...lines.slice(questionIndex + 1)];
  const message = summaryLines.join("\n").replace(/\n+$/, "");
  return {
    title: question,
    message,
    plainMessage: stripAnsi(message),
    featureId: isAurReleasePrompt ? "releaseAur" : "releaseNpm",
  };
}

function releaseDialogLineClass(plainLine, section) {
  const text = plainLine.trim();
  if (!text) return "release-dialog-spacer";
  if (/^(Release preflight summary|AUR release summary|Version changes|Bump summary|Will publish|Will skip|Blocked|Other|Publish targets after confirmation|Missing local package dirs):$/i.test(text)) {
    return "release-dialog-heading";
  }
  if (/^none$/i.test(text)) return "release-dialog-muted";
  if (/->\s*error\b|\bfailed\b|\bmissing\b|\berrors?:\s*[1-9]/i.test(text) || /^blocked$/i.test(section)) return "release-dialog-danger";
  if (/publish-(?:first|update)|would bump up|first release/i.test(text) || /^(will publish|publish targets after confirmation)$/i.test(section)) return "release-dialog-success";
  if (/\bskip(?:ped)?\b|\bunchanged\b|would reduce down|already published/i.test(text) || /^will skip$/i.test(section)) return "release-dialog-warning";
  return "";
}

// Enter inside a native input dialog must never fall through to the browser's
// implicit `method="dialog"` submission. "ignore" leaves IME composition alone,
// "suppress" only blocks the implicit close, and "submit" sends one response.
function dialogInputEnterIntent(event) {
  if (!event || event.key !== "Enter") return "ignore";
  if (event.isComposing || event.keyCode === 229) return "ignore";
  if (event.repeat) return "suppress";
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return "suppress";
  return "submit";
}

const QUESTIONNAIRE_TITLE_PATTERN = /^Question\s+([1-9]\d*)\s+of\s+([1-9]\d*):\s+\S.*$/;
const QUESTIONNAIRE_ROW_PATTERN = /^(\d{2})\.\s(.*)$/;
const QUESTIONNAIRE_STATE_PATTERN = /^(\[ \]|\[x\]|\[selected\])\s(.*)$/;
const QUESTIONNAIRE_MAX_QUESTIONS = 20;
const QUESTIONNAIRE_MAX_OPTIONS = 50;

function isQuestionnaireChangeOtherAction(value) {
  const prefix = "Change Other… (currently ";
  if (!value.startsWith(prefix) || !value.endsWith(")")) return false;
  const encoded = value.slice(prefix.length, -1);
  try {
    const other = JSON.parse(encoded);
    return typeof other === "string" && JSON.stringify(other) === encoded;
  } catch {
    return false;
  }
}

// Bounded, presentation-only grammar for the native questionnaire runtime's
// action strings. Anything outside this list stays a generic option.
function questionnaireContinueCount(text) {
  const match = String(text || "").match(/^Continue with (0|[1-9]\d*) selection\(s\)$/);
  if (!match) return null;
  const count = Number(match[1]);
  return Number.isSafeInteger(count) && count <= QUESTIONNAIRE_MAX_OPTIONS + 1 ? count : null;
}

function questionnaireActionKind(text) {
  const value = String(text || "");
  if (value === "Cancel questionnaire") return "cancel";
  if (value === "Ask Pi to clarify…") return "clarify";
  if (value === "Remove Other answer") return "remove-other";
  if (value === "Other… (enter a custom answer)" || value === "Add Other…") return "other";
  if (isQuestionnaireChangeOtherAction(value)) return "other";
  if (questionnaireContinueCount(value) !== null) return "continue";
  return null;
}

// Parses one native option string for presentation only; the caller always
// transports the untouched original string back to the extension.
function parseQuestionnaireOption(text) {
  const value = String(text || "");
  const action = questionnaireActionKind(value);
  if (action) return { kind: "action", action, value };

  const row = value.match(QUESTIONNAIRE_ROW_PATTERN);
  if (!row) return null;
  const number = row[1];
  const state = row[2].match(QUESTIONNAIRE_STATE_PATTERN);
  const marker = state ? (state[1] === "[ ]" ? "unselected" : "selected") : "none";
  const body = state ? state[2] : row[2];
  if (!body.trim()) return null;

  const separator = body.indexOf(" — ");
  const label = separator === -1 ? body : body.slice(0, separator);
  const description = separator === -1 ? "" : body.slice(separator + 3);
  if (!label.trim()) return null;
  return { kind: "option", marker, number, label, description, value };
}

function questionnaireActionSequenceMatches(mode, actionRows) {
  const values = actionRows.map((row) => row.value);
  if (mode === "single") {
    const expected = values[0] === "Other… (enter a custom answer)"
      ? ["Other… (enter a custom answer)", "Ask Pi to clarify…", "Cancel questionnaire"]
      : ["Ask Pi to clarify…", "Cancel questionnaire"];
    return values.length === expected.length && values.every((value, index) => value === expected[index]);
  }

  let index = 0;
  if (values[index] === "Add Other…") {
    index += 1;
  } else if (isQuestionnaireChangeOtherAction(values[index] || "")) {
    index += 1;
    if (values[index] !== "Remove Other answer") return false;
    index += 1;
  }
  if (values[index] !== "Ask Pi to clarify…") return false;
  index += 1;
  if (questionnaireContinueCount(values[index]) === null) return false;
  index += 1;
  return values[index] === "Cancel questionnaire" && index === values.length - 1;
}

// Detection requires the complete runtime title, contiguous numbered rows, one
// consistent state-marker mode, and the exact ordered action tail. This keeps
// lookalike extension selects on the generic renderer.
function questionnaireSelectParts(prompt, options) {
  if (!Array.isArray(options) || options.length < 3 || options.length > QUESTIONNAIRE_MAX_OPTIONS + 5) return null;
  const title = stripAnsi(prompt?.title || "").trim();
  const titleMatch = title.match(QUESTIONNAIRE_TITLE_PATTERN);
  if (!titleMatch) return null;
  const current = Number(titleMatch[1]);
  const total = Number(titleMatch[2]);
  if (current > total || total > QUESTIONNAIRE_MAX_QUESTIONS) return null;

  const rows = [];
  for (const option of options) {
    const parsed = parseQuestionnaireOption(String(option));
    if (!parsed) return null;
    rows.push(parsed);
  }

  const firstAction = rows.findIndex((row) => row.kind === "action");
  if (firstAction < 1 || firstAction > QUESTIONNAIRE_MAX_OPTIONS) return null;
  const optionRows = rows.slice(0, firstAction);
  const actionRows = rows.slice(firstAction);
  if (actionRows.some((row) => row.kind !== "action")) return null;
  if (!optionRows.every((row, index) => row.kind === "option" && row.number === String(index + 1).padStart(2, "0"))) return null;

  const single = optionRows.every((row) => row.marker === "none");
  const multi = optionRows.every((row) => row.marker !== "none");
  if (!single && !multi) return null;
  const mode = multi ? "multi" : "single";
  if (!questionnaireActionSequenceMatches(mode, actionRows)) return null;
  return { rows, mode };
}

function renderQuestionnaireOptionButton(row, mode) {
  const classNames = ["questionnaire-option", `questionnaire-option-${mode}`];
  if (row.marker === "selected") classNames.push("is-selected");
  const button = make("button", classNames.join(" "));
  button.type = "button";
  // The visible text is split into semantic parts, so the accessible name keeps
  // the exact native string that click transport sends back.
  button.setAttribute("aria-label", row.value);
  if (row.marker !== "none") button.setAttribute("aria-pressed", String(row.marker === "selected"));

  button.append(make("span", "questionnaire-option-number", row.number));
  if (row.marker !== "none") {
    const state = make("span", "questionnaire-option-state", row.marker === "selected" ? "✓" : "");
    state.setAttribute("aria-hidden", "true");
    button.append(state);
  }
  const text = make("span", "questionnaire-option-text");
  text.append(make("span", "questionnaire-option-label", row.label));
  if (row.description) text.append(make("span", "questionnaire-option-description", row.description));
  button.append(text);
  return button;
}

function renderQuestionnaireActionButton(row) {
  const classNames = ["questionnaire-action", `questionnaire-action-${row.action}`];
  if (row.action === "continue") classNames.push("primary");
  const button = make("button", classNames.join(" "), row.value);
  button.type = "button";
  return button;
}

function renderReleaseDialogMessage(parent, text) {
  parent.replaceChildren();
  let section = "";
  for (const line of String(text || "").split("\n")) {
    const plainLine = stripAnsi(line);
    const heading = plainLine.trim().match(/^(Release preflight summary|Version changes|Bump summary|Will publish|Will skip|Blocked|Other|Publish targets after confirmation|Missing local package dirs):$/i);
    const rowClass = ["release-dialog-line", releaseDialogLineClass(plainLine, section)].filter(Boolean).join(" ");
    const row = make("span", rowClass);
    renderAnsiText(row, line || " ");
    parent.append(row);
    if (heading) section = heading[1].toLowerCase();
  }
}

function textLines(raw) {
  const value = String(raw || "");
  const lines = [];
  let start = 0;
  for (let index = 0; index < value.length; index += 1) {
    if (value[index] !== "\n") continue;
    const end = index > start && value[index - 1] === "\r" ? index - 1 : index;
    lines.push(value.slice(start, end));
    start = index + 1;
  }
  if (start <= value.length) lines.push(value.slice(start));
  return lines;
}

function stripTodoProgressLines(text, { streaming = false } = {}) {
  // Checklist text is transport for the todo-progress extension, not final
  // assistant output. Keep filtering it when the widget UI is user-disabled;
  // disabling the renderer does not unload the extension or its prompt policy.
  if (!isOptionalFeatureDetected("todoProgressWidget")) return String(text || "");
  let inFence = false;
  const kept = [];
  const raw = String(text || "");
  const hasTrailingNewline = /\r?\n$/.test(raw);
  const lines = textLines(raw);

  lines.forEach((line, index) => {
    const isUnfinishedTail = streaming && !hasTrailingNewline && index === lines.length - 1;
    if (/^\s*```/.test(line)) {
      inFence = !inFence;
      kept.push(line);
      return;
    }
    if (!inFence && TODO_PROGRESS_LINE_REGEX.test(line)) return;
    if (!inFence && isUnfinishedTail && TODO_PROGRESS_PARTIAL_LINE_REGEX.test(line)) return;
    kept.push(line);
  });

  return kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function parseTodoProgressItemLine(line) {
  const match = String(line || "").match(/^\s*(?:(?:[-*]|\d+[.)])\s*)?\[( |x|X|-)\]\s+(.+)$/);
  if (!match) return null;
  const mark = match[1].toLowerCase();
  return { status: mark === "x" ? "done" : mark === "-" ? "partial" : "todo", text: match[2].trim() };
}

function todoProgressStatusLabel(status) {
  if (status === "done") return "[x]";
  if (status === "partial") return "[-]";
  return "[ ]";
}

function liveTodoProgressWidgetLinesFromText(text, tabId = activeTabId) {
  if (!isOptionalFeatureEnabled("todoProgressWidget")) return null;
  const raw = String(text || "");
  if (!raw.trim()) return null;

  let inFence = false;
  let goal = "";
  let current = [];
  const blocks = [];
  const flush = () => {
    if (current.length) blocks.push(current);
    current = [];
  };

  for (const line of textLines(raw)) {
    if (/^\s*```/.test(line)) {
      inFence = !inFence;
      flush();
      continue;
    }
    if (inFence) continue;

    const clean = stripAnsi(line).trim();
    const goalMatch = clean.match(/^Goal\s*[:：]\s*(.+)$/i);
    if (goalMatch?.[1]?.trim()) goal = goalMatch[1].trim();

    const item = parseTodoProgressItemLine(clean);
    if (item) {
      current.push(item);
      continue;
    }
    flush();
  }
  flush();

  const items = blocks.at(-1) || [];
  if (!items.length) return null;

  if (goal && tabId) todoProgressGoalByTab.set(tabId, goal);
  const displayGoal = goal || (tabId ? todoProgressGoalByTab.get(tabId) : "") || "";
  const done = items.filter((item) => item.status === "done").length;
  const partial = items.filter((item) => item.status === "partial").length;
  const lines = [];
  if (displayGoal) lines.push(`Goal: ${displayGoal}`);
  lines.push(`Todo ${done}/${items.length} done${partial ? `, ${partial} partial` : ""}`);
  for (const item of items) lines.push(`${todoProgressStatusLabel(item.status)} ${item.text}`);
  return lines;
}

// Coalesce widget rebuilds to one per animation frame. Todo-progress records
// are now derived only at authoritative message reconciliation, but several
// semantic boundaries can land in the same frame, so the widget area must
// still never be torn down/rebuilt more than once per frame.
function scheduleLiveWidgetRender() {
  if (liveWidgetRenderFrame !== null) return;
  const flush = () => {
    liveWidgetRenderFrame = null;
    renderWidgets();
  };
  if (typeof requestAnimationFrame === "function") liveWidgetRenderFrame = requestAnimationFrame(flush);
  else liveWidgetRenderFrame = setTimeout(flush, 0);
}

// Authoritative source for the todo-progress record: the settled assistant
// text that message reconciliation just fetched. Raw stream tokens never
// reach this path, so widget records change at most once per reconciliation
// and only when the parsed checklist value actually differs.
function authoritativeTodoProgressSourceText(messages = latestMessages) {
  for (let index = (messages?.length || 0) - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role !== "assistant") continue;
    const text = textFromContent(message.content);
    if (String(text || "").trim()) return text;
  }
  return "";
}

function reconcileTodoProgressFromMessages(messages = latestMessages, tabId = activeTabId) {
  if (!tabId) return false;
  const text = authoritativeTodoProgressSourceText(messages);
  if (!text) return false;
  return syncLiveTodoProgressWidgetFromText(text, tabId);
}

function syncLiveTodoProgressWidgetFromText(text, tabId = activeTabId) {
  const lines = liveTodoProgressWidgetLinesFromText(text, tabId);
  if (!lines) return false;
  const signature = todoProgressSignatureFromLines(lines);
  if (tabId && todoProgressSignatureByTab.get(tabId) === signature) return false;
  // liveTodoProgressWidgetLinesFromText already short-circuits unless the
  // feature is enabled, so detection is settled here. Do NOT run
  // updateOptionalFeatureAvailability() from this path: it triggers git-footer
  // payload reconciliation and a full optional-feature control rebuild.
  // Availability is reconciled on command/state refreshes and RPC widget
  // updates instead, keeping streaming output decoupled from chrome UI.
  const changed = setWidgetForTab(tabId, "todo-progress", { method: "setWidget", widgetKey: "todo-progress", widgetLines: lines, tabId, live: true });
  if (changed && tabId === activeTabId) scheduleLiveWidgetRender();
  return changed;
}

function parseTodoProgressWidget(lines) {
  const cleanLines = lines.map(stripAnsi).map((line) => line.trim()).filter(Boolean);
  const goalLine = cleanLines.find((line) => /^Goal\s*[:：]/i.test(line));
  const goal = goalLine ? goalLine.replace(/^Goal\s*[:：]\s*/i, "").trim() : "";
  const headerIndex = cleanLines.findIndex((line) => /^Todo\s+\d+\/\d+\s+done/i.test(line));
  if (headerIndex === -1) return null;

  const header = cleanLines[headerIndex];
  const match = header.match(/^Todo\s+(\d+)\/(\d+)\s+done(?:,\s+(\d+)\s+partial)?/i);
  if (!match) return null;

  const items = [];
  let footer = "";
  for (const line of cleanLines.slice(headerIndex + 1)) {
    const item = parseTodoProgressItemLine(line);
    if (item) {
      items.push(item);
    } else if (/^Scroll\s+/i.test(line)) {
      footer = line;
    }
  }

  return {
    goal,
    done: Number.parseInt(match[1], 10) || 0,
    total: Number.parseInt(match[2], 10) || items.length,
    partial: Number.parseInt(match[3] || "0", 10) || 0,
    items,
    footer,
  };
}

function renderTodoProgressWidget(_key, lines) {
  const todo = parseTodoProgressWidget(lines);
  if (!todo) return null;

  const tabId = activeTabId || "default";
  const node = make("details", "widget todo-widget");
  node.open = todoProgressWidgetExpandedByTab.get(tabId) === true;
  node.setAttribute("aria-label", "Todo progress");
  node.addEventListener("toggle", () => {
    todoProgressWidgetExpandedByTab.set(tabId, node.open);
  });

  const percent = todo.total > 0 ? Math.max(0, Math.min(100, (todo.done / todo.total) * 100)) : 0;
  const summary = make("summary", "todo-widget-summary");
  const header = make("div", "todo-widget-header");
  header.append(
    make("span", "todo-widget-toggle", "›"),
    make("span", "todo-widget-title", "Todo progress"),
    make("span", "todo-widget-count", `${todo.done}/${todo.total}`),
    make("span", "todo-widget-meta", todo.partial ? `${todo.partial} partial` : "active"),
  );

  const progress = make("div", "todo-widget-progress");
  const fill = make("span", "todo-widget-progress-fill");
  fill.style.width = `${percent}%`;
  progress.append(fill);
  if (todo.goal) summary.append(make("div", "todo-widget-goal", `Goal: ${todo.goal}`));
  summary.append(header, progress);

  const body = make("div", "todo-widget-body");
  const list = make("ol", "todo-widget-list");
  for (const item of todo.items) {
    const row = make("li", `todo-widget-item ${item.status}`);
    row.append(
      make("span", "todo-widget-marker", item.status === "done" ? "✓" : item.status === "partial" ? "–" : ""),
      make("span", "todo-widget-text", item.text),
    );
    list.append(row);
  }
  if (todo.items.length) body.append(list);
  if (todo.footer) body.append(make("div", "todo-widget-footer", todo.footer));

  node.append(summary);
  if (body.children.length) node.append(body);
  return node;
}

function getWidgetLines(key) {
  const value = widgets.get(key);
  return Array.isArray(value?.widgetLines) ? value.widgetLines : [];
}

function releaseNpmFooterDetails(lines) {
  const primary = cleanStatusText(lines[0] || "").replace(/^release-(?:npm|aur):\s*/i, "");
  const parts = primary.split(/\s+·\s+/).map((part) => part.trim()).filter(Boolean);
  return {
    phase: parts[0] || "release workflow",
    mode: parts[1] || "",
    elapsed: parts[2] || "",
    controls: lines.slice(1).map(cleanStatusText).filter(Boolean).join(" · "),
  };
}

function releaseNpmLineTone(line) {
  const clean = stripAnsi(line).trim();
  if (/^\$\s+/.test(clean)) return "command";
  if (/^==>/.test(clean)) return "target";
  if (/^(PASS|✓|Published)\b/i.test(clean)) return "pass";
  if (/^(FAIL|ERROR|ERR|✗)\b/i.test(clean)) return "fail";
  if (/^(WARN|warning)\b/i.test(clean)) return "warn";
  if (/^(INFO|npm notice|notice)\b/i.test(clean)) return "info";
  if (/^RELEASE_NPM_EVENT\b/.test(clean)) return "event";
  if (/^\[[0-9:]+\]\s+\[[^\]]+\]\s+\$/.test(clean)) return "command";
  if (/\b(STDERR|failed|error|exited with code)\b/i.test(clean)) return "fail";
  if (/\b(completed|succeeded|agent completed|tool completed)\b/i.test(clean)) return "pass";
  if (/\b(started|running|auto retry|compaction)\b/i.test(clean)) return "info";
  return "";
}

function appendReleaseNpmTerminalLine(parent, line) {
  const tone = releaseNpmLineTone(line);
  const row = make("div", `release-npm-line${tone ? ` ${tone}` : ""}`);
  if (String(line ?? "") === "") row.textContent = "\u00a0";
  else renderAnsiText(row, line);
  parent.append(row);
}

async function sendReleaseNpmCommand(command) {
  const tabContext = activeTabContext();
  const resolvedCommand = resolveRpcSlashCommandMessage(command);
  try {
    await api("/api/prompt", { method: "POST", body: { message: resolvedCommand }, tabId: tabContext.tabId });
    if (!isCurrentTabContext(tabContext)) return;
    addEvent(`${command} sent`, "info");
    scheduleRefreshState(120, tabContext);
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      addEvent(error.message, "error");
      addTransientMessage({ role: "error", title: command, content: error.message, level: "error" });
    }
  }
}

function releaseNpmActionButton(label, command, className = "") {
  const button = make("button", `release-npm-action ${className}`.trim(), label);
  button.type = "button";
  button.addEventListener("click", () => sendReleaseNpmCommand(command));
  return button;
}

function releaseNpmStreamHeader(label, lineCount, { live = false } = {}) {
  const header = make("div", "release-npm-stream-header");
  const safeLineCount = Math.max(0, Number(lineCount) || 0);
  header.append(
    make("span", `release-npm-stream-dot${live ? " live" : ""}`),
    make("span", "release-npm-stream-title", label),
    make("span", "release-npm-stream-count", `${safeLineCount} line${safeLineCount === 1 ? "" : "s"}`),
  );
  return header;
}

function renderReleaseNpmOutputDetails(key, streamHeader, terminal, controls = null) {
  const tabId = activeTabId || "default";
  const stateKey = `${tabId}:${key}`;
  const node = make("details", "release-npm-output-details");
  node.open = releaseNpmOutputExpandedByTab.get(stateKey) !== false;
  node.addEventListener("toggle", () => {
    releaseNpmOutputExpandedByTab.set(stateKey, node.open);
    if (node.open && terminal.dataset.preserveScrollOnToggle !== "true") {
      requestAnimationFrame(() => { terminal.scrollTop = terminal.scrollHeight; });
    }
  });

  const summary = make("summary", "release-npm-output-summary");
  summary.title = "Expand or collapse command output in the Web UI";
  const toggle = make("span", "release-npm-output-toggle", "›");
  toggle.setAttribute("aria-hidden", "true");
  summary.append(toggle, streamHeader);
  node.append(summary, terminal);
  if (controls) node.append(controls);
  return node;
}

function renderReleaseNpmOutputWidget() {
  if (!isOptionalFeatureEnabled("releaseNpm")) return null;
  const outputLines = getWidgetLines("release-npm:output");
  const footerLines = getWidgetLines("release-npm:footer");
  if (outputLines.length === 0 && footerLines.length === 0) return null;

  const details = releaseNpmFooterDetails(footerLines);
  const node = make("section", "widget release-npm-widget release-npm-live-widget");
  node.setAttribute("aria-label", "npm release output");

  const header = make("div", "release-npm-header");
  const titleWrap = make("div", "release-npm-title-wrap");
  titleWrap.append(make("span", "release-npm-kicker", "npm release"), make("strong", "release-npm-title", details.phase));

  const meta = make("div", "release-npm-meta");
  if (details.mode) meta.append(make("span", "release-npm-pill", details.mode));
  if (details.elapsed) meta.append(make("span", "release-npm-pill elapsed", details.elapsed));

  const actions = make("div", "release-npm-actions");
  actions.append(
    releaseNpmActionButton("Toggle output", "/release-toggle"),
    releaseNpmActionButton("Abort", "/release-abort", "danger"),
  );
  header.append(titleWrap, meta, actions);

  const streamLines = outputLines.length ? outputLines : ["Waiting for release output..."];
  const streamHeader = releaseNpmStreamHeader("Live output stream", outputLines.length, { live: true });
  const terminal = make("div", "release-npm-terminal");
  terminal.setAttribute("role", "log");
  terminal.setAttribute("aria-live", "polite");
  for (const line of streamLines) {
    appendReleaseNpmTerminalLine(terminal, line);
  }

  const controls = make("div", "release-npm-controls", details.controls || "Controls: /release-toggle expands/collapses · /release-abort stops subprocess");
  const outputDetails = renderReleaseNpmOutputDetails("release-npm:output", streamHeader, terminal, controls);
  node.append(header, outputDetails);
  requestAnimationFrame(() => { if (outputDetails.open) terminal.scrollTop = terminal.scrollHeight; });
  return node;
}

