function nativeResourceSourceLabel(resource) {
  const info = resource?.sourceInfo || {};
  return [info.source, info.scope, info.origin].filter(Boolean).join(" · ") || resource?.location || "loaded resource";
}

function nativeToolOriginTag(resource) {
  return resource?.sourceInfo?.source === "builtin"
    ? { label: "Pi Native", className: "native-selector-badge-pi-native" }
    : { label: "External", className: "native-selector-badge-external" };
}

function nativeResourceCounts(resources) {
  const disabled = resources.filter((resource) => resource.enabled === false).length;
  return { total: resources.length, disabled, enabled: resources.length - disabled };
}

function nativeResourceFilterMatches(resource, filter) {
  if (filter === "enabled") return resource.enabled !== false;
  if (filter === "disabled") return resource.enabled === false;
  return true;
}

function renderNativeResourceToggles(resources, { savingName, filter = "all", onToggle, getResourceTag } = {}) {
  const filteredResources = resources.filter((resource) => nativeResourceFilterMatches(resource, filter));
  const counts = nativeResourceCounts(resources);
  const items = filteredResources.map((resource) => {
    const resourceTag = getResourceTag?.(resource);
    return {
      id: resource.name,
      label: resource.name,
      description: resource.description || "No description provided.",
      meta: nativeResourceSourceLabel(resource),
      badge: resource.enabled === false ? "disabled" : "enabled",
      badgeClass: resource.enabled === false ? "disabled native-selector-badge-disabled" : "enabled native-selector-badge-enabled",
      pressed: resource.enabled !== false,
      tags: resourceTag ? [resourceTag] : [],
      disabled: Boolean(savingName),
      resource,
    };
  });
  const filterLabel = filter === "enabled" ? "enabled" : filter === "disabled" ? "disabled" : "all";
  renderNativeSelectorItems(items, {
    emptyText: `No ${filterLabel} entries match this filter.`,
    onSelect: (item) => onToggle?.(item.resource),
  });
  elements.nativeCommandBody.prepend(make("div", "native-resource-summary muted", `${counts.total} total · ${counts.enabled} enabled · ${counts.disabled} disabled · showing ${filterLabel}`));
}

function renderNativeResourceFilterActions(filter, setFilter, render, extraActions = []) {
  elements.nativeCommandActions.replaceChildren();
  for (const option of [
    { value: "all", label: "All" },
    { value: "enabled", label: "Enabled" },
    { value: "disabled", label: "Disabled" },
  ]) {
    addNativeCommandAction(option.label, () => {
      setFilter(option.value);
      render();
    }, filter === option.value ? "primary" : undefined);
  }
  for (const action of extraActions) {
    const button = addNativeCommandAction(action.label, action.handler);
    button.disabled = !!action.disabled;
  }
  addNativeCommandAction("Cancel", closeNativeCommandDialog);
}

function nativeResourceScopeControl(scope, { configured = false, saving = false, onChange } = {}) {
  const hints = {
    session: "Applies immediately and persists only on the current session branch.",
    global: configured
      ? "Saved as the default for future sessions. Existing session-specific choices are unchanged."
      : "No global default is saved yet. The current session is shown as the starting point.",
    model: configured
      ? "Saved for this exact model. Sessions without their own choice apply it whenever this model is selected."
      : "No default is saved for this exact model yet. The inherited selection is shown as the starting point.",
  };
  const badges = {
    session: { label: "This session", tone: "now" },
    global: { label: "Global", tone: "startup" },
    model: { label: "Exact model", tone: "startup" },
  };
  const control = nativeSettingSelect("Apply changes to", scope, [
    { value: "session", label: "Session only" },
    { value: "global", label: "Global default" },
    { value: "model", label: "Model default" },
  ], hints[scope] || hints.session, badges[scope] || badges.session);
  control.field.classList.add("native-resource-scope");
  control.select.disabled = !!saving;
  control.select.addEventListener("change", () => onChange?.(control.select.value));
  return control.field;
}

function nativeResourceModelControl(models, modelIndex, { saving = false, onChange } = {}) {
  const options = models.map((model, index) => ({
    value: String(index),
    label: `${model.provider}/${model.id}${model.name && model.name !== model.id ? ` — ${model.name}` : ""}`,
  }));
  const control = nativeSettingSelect("Model default for", String(modelIndex), options, "Chooses which exact model profile to edit. The active session model is not changed.", { label: "Exact model", tone: "startup" });
  control.field.classList.add("native-resource-model");
  control.select.disabled = !!saving;
  control.select.addEventListener("change", () => onChange?.(Number(control.select.value)));
  return control.field;
}

async function loadNativeResourceModels() {
  const response = await nativeCommandApi("/api/models");
  return (Array.isArray(response.data?.models) ? response.data.models : [])
    .filter((model) => model?.provider && model?.id)
    .sort((left, right) => `${left.provider}/${left.id}`.localeCompare(`${right.provider}/${right.id}`));
}

async function openNativeToolsSelector() {
  openNativeCommandDialog({ title: "Tools Setup", message: "Enable or disable tool access for this session, or save a global or exact-model default.", searchPlaceholder: "Filter tools…" });
  let tools = [];
  let savingName = "";
  let filter = "all";
  let scope = "session";
  let configured = false;
  let models = [];
  let modelIndex = 0;

  const modelQuery = () => scope === "model" && models[modelIndex]
    ? `&provider=${encodeURIComponent(models[modelIndex].provider)}&modelId=${encodeURIComponent(models[modelIndex].id)}`
    : "";

  const load = async () => {
    renderNativeLoading(`Loading ${scope === "global" ? "global tool defaults" : scope === "model" ? "model tool defaults" : "session tools"}…`);
    try {
      const response = await nativeCommandApi(`/api/tools?scope=${encodeURIComponent(scope)}${modelQuery()}`);
      tools = Array.isArray(response.data?.tools) ? response.data.tools : [];
      configured = response.data?.configured === true;
      if (scope === "model" && Array.isArray(response.data?.models)) models = response.data.models;
      render();
    } catch (error) {
      setNativeCommandError(error.message || String(error));
      elements.nativeCommandBody.replaceChildren();
    }
  };

  const applyModelScope = async () => {
    if (!models.length) {
      try {
        models = await loadNativeResourceModels();
      } catch (error) {
        setNativeCommandError(error.message || String(error));
        return false;
      }
    }
    if (!models.length) {
      setNativeCommandError("No authenticated Pi models are available for a model default.");
      return false;
    }
    modelIndex = Math.min(Math.max(modelIndex, 0), models.length - 1);
    return true;
  };

  const inheritSelection = async () => {
    if (savingName) return;
    savingName = "inherit";
    setNativeCommandError("");
    render();
    try {
      const body = { scope, inherit: true };
      if (scope === "model" && models[modelIndex]) {
        body.provider = models[modelIndex].provider;
        body.modelId = models[modelIndex].id;
      }
      const response = await nativeCommandApi("/api/tools", { method: "POST", body });
      tools = Array.isArray(response.data?.tools) ? response.data.tools : [];
      configured = response.data?.configured === true;
      const content = scope === "model"
        ? `Tool default for ${body.provider}/${body.modelId} cleared. It now inherits the global or Pi runtime default.`
        : scope === "global"
          ? "Global tool default cleared. Unpinned active tools now follow the Pi runtime default; pinned tools are unchanged."
          : "Tools for this session now follow the inherited model, global, or Pi runtime defaults.";
      addTransientMessage({ role: "native", title: "/tools", content, level: "info" });
    } catch (error) {
      setNativeCommandError(error.message || String(error));
    } finally {
      savingName = "";
      render();
    }
  };

  const render = () => {
    renderNativeResourceToggles(tools, {
      savingName,
      filter,
      getResourceTag: nativeToolOriginTag,
      onToggle: async (tool) => {
        if (!tool || savingName) return;
        const enabledTools = new Set(tools.filter((item) => item.enabled !== false).map((item) => item.name));
        if (tool.enabled === false) enabledTools.add(tool.name);
        else enabledTools.delete(tool.name);
        savingName = tool.name;
        setNativeCommandError("");
        render();
        try {
          const body = { enabledTools: [...enabledTools], scope };
          if (scope === "model" && models[modelIndex]) {
            body.provider = models[modelIndex].provider;
            body.modelId = models[modelIndex].id;
          }
          const response = await nativeCommandApi("/api/tools", { method: "POST", body });
          tools = Array.isArray(response.data?.tools) ? response.data.tools : [];
          configured = response.data?.configured === true;
          const enabled = enabledTools.has(tool.name);
          const content = scope === "model"
            ? `Model default for tool ${tool.name} ${enabled ? "enabled" : "disabled"} (${body.provider}/${body.modelId}). Unpinned active tools update immediately when this model is active; pinned tools are unchanged.`
            : scope === "global"
              ? `Global default for tool ${tool.name} ${enabled ? "enabled" : "disabled"}. Unpinned active tools update immediately; pinned tools are unchanged.`
              : `Tool ${tool.name} ${enabled ? "enabled" : "disabled"} for this session.`;
          addTransientMessage({ role: "native", title: "/tools", content, level: "info" });
        } catch (error) {
          setNativeCommandError(error.message || String(error));
        } finally {
          savingName = "";
          render();
        }
      },
    });
    if (scope === "model" && models.length) {
      elements.nativeCommandBody.prepend(nativeResourceModelControl(models, modelIndex, {
        saving: !!savingName,
        onChange: async (nextIndex) => {
          if (nextIndex === modelIndex || savingName || !models[nextIndex]) return;
          modelIndex = nextIndex;
          await load();
        },
      }));
    }
    elements.nativeCommandBody.prepend(nativeResourceScopeControl(scope, {
      configured,
      saving: !!savingName,
      onChange: async (nextScope) => {
        if (nextScope === scope || savingName) return;
        if (nextScope === "model" && !(await applyModelScope())) {
          render();
          return;
        }
        scope = nextScope;
        await load();
      },
    }));
    renderNativeResourceFilterActions(filter, (value) => { filter = value; }, render, [
      { label: "Use inherited defaults", handler: inheritSelection, disabled: !!savingName },
    ]);
  };

  elements.nativeCommandSearch.oninput = render;
  await load();
}

async function openNativeSkillsSelector() {
  openNativeCommandDialog({ title: "Skills Setup", message: "Enable or disable skill invocation for this session, or save a global or exact-model default.", searchPlaceholder: "Filter skills…" });
  let skills = [];
  let savingName = "";
  let filter = "all";
  let scope = "session";
  let configured = false;
  let models = [];
  let modelIndex = 0;

  const modelQuery = () => scope === "model" && models[modelIndex]
    ? `&provider=${encodeURIComponent(models[modelIndex].provider)}&modelId=${encodeURIComponent(models[modelIndex].id)}`
    : "";

  const load = async () => {
    renderNativeLoading(`Loading ${scope === "global" ? "global skill defaults" : scope === "model" ? "model skill defaults" : "session skills"}…`);
    try {
      const response = await nativeCommandApi(`/api/skills?scope=${encodeURIComponent(scope)}${modelQuery()}`);
      skills = Array.isArray(response.data?.skills) ? response.data.skills : [];
      configured = response.data?.configured === true;
      if (scope === "model" && Array.isArray(response.data?.models)) models = response.data.models;
      render();
    } catch (error) {
      setNativeCommandError(error.message || String(error));
      elements.nativeCommandBody.replaceChildren();
    }
  };

  const applyModelScope = async () => {
    if (!models.length) {
      try {
        models = await loadNativeResourceModels();
      } catch (error) {
        setNativeCommandError(error.message || String(error));
        return false;
      }
    }
    if (!models.length) {
      setNativeCommandError("No authenticated Pi models are available for a model default.");
      return false;
    }
    modelIndex = Math.min(Math.max(modelIndex, 0), models.length - 1);
    return true;
  };

  const inheritSelection = async () => {
    if (savingName) return;
    savingName = "inherit";
    setNativeCommandError("");
    render();
    try {
      const body = { scope, inherit: true };
      if (scope === "model" && models[modelIndex]) {
        body.provider = models[modelIndex].provider;
        body.modelId = models[modelIndex].id;
      }
      const response = await nativeCommandApi("/api/skills", { method: "POST", body });
      skills = Array.isArray(response.data?.skills) ? response.data.skills : [];
      configured = response.data?.configured === true;
      const content = scope === "model"
        ? `Skill default for ${body.provider}/${body.modelId} cleared. It now inherits the global or Pi runtime default.`
        : scope === "global"
          ? "Global skill default cleared. Unpinned active skills now follow the Pi runtime default; pinned skills are unchanged."
          : "Skills for this session now follow the inherited model, global, or Pi runtime defaults.";
      addTransientMessage({ role: "native", title: "/skills", content, level: "info" });
      if (scope === "session") refreshCommands(activeTabContext()).catch((error) => addEvent(error.message || String(error), "error"));
    } catch (error) {
      setNativeCommandError(error.message || String(error));
    } finally {
      savingName = "";
      render();
    }
  };

  const render = () => {
    renderNativeResourceToggles(skills, {
      savingName,
      filter,
      onToggle: async (skill) => {
        if (!skill || savingName) return;
        const enabledSkills = new Set(skills.filter((item) => item.enabled !== false).map((item) => item.name));
        if (skill.enabled === false) enabledSkills.add(skill.name);
        else enabledSkills.delete(skill.name);
        savingName = skill.name;
        setNativeCommandError("");
        render();
        try {
          const body = { enabledSkills: [...enabledSkills], scope };
          if (scope === "model" && models[modelIndex]) {
            body.provider = models[modelIndex].provider;
            body.modelId = models[modelIndex].id;
          }
          const response = await nativeCommandApi("/api/skills", { method: "POST", body });
          skills = Array.isArray(response.data?.skills) ? response.data.skills : [];
          configured = response.data?.configured === true;
          const enabled = enabledSkills.has(skill.name);
          const content = scope === "model"
            ? `Model default for skill ${skill.name} ${enabled ? "enabled" : "disabled"} (${body.provider}/${body.modelId}). Unpinned active skills update immediately when this model is active; pinned skills are unchanged.`
            : scope === "global"
              ? `Global default for skill ${skill.name} ${enabled ? "enabled" : "disabled"}. Unpinned active skills update immediately; pinned skills are unchanged.`
              : `Skill ${skill.name} ${enabled ? "enabled" : "disabled"} for this session.`;
          addTransientMessage({ role: "native", title: "/skills", content, level: "info" });
          if (scope === "session") refreshCommands(activeTabContext()).catch((error) => addEvent(error.message || String(error), "error"));
        } catch (error) {
          setNativeCommandError(error.message || String(error));
        } finally {
          savingName = "";
          render();
        }
      },
    });
    if (scope === "model" && models.length) {
      elements.nativeCommandBody.prepend(nativeResourceModelControl(models, modelIndex, {
        saving: !!savingName,
        onChange: async (nextIndex) => {
          if (nextIndex === modelIndex || savingName || !models[nextIndex]) return;
          modelIndex = nextIndex;
          await load();
        },
      }));
    }
    elements.nativeCommandBody.prepend(nativeResourceScopeControl(scope, {
      configured,
      saving: !!savingName,
      onChange: async (nextScope) => {
        if (nextScope === scope || savingName) return;
        if (nextScope === "model" && !(await applyModelScope())) {
          render();
          return;
        }
        scope = nextScope;
        await load();
      },
    }));
    renderNativeResourceFilterActions(filter, (value) => { filter = value; }, render, [
      { label: "Use inherited defaults", handler: inheritSelection, disabled: !!savingName },
    ]);
  };

  elements.nativeCommandSearch.oninput = render;
  await load();
}

async function openNativeAuthSelector(mode) {
  const command = mode === "logout" ? "/logout" : "/login";
  openNativeCommandDialog({
    title: command,
    message: mode === "logout" ? "Remove stored provider credentials from auth.json." : "Provider login still requires the Pi TUI.",
    searchPlaceholder: "Filter providers…",
  });
  renderNativeLoading("Loading provider auth status…");
  try {
    const response = await nativeCommandApi("/api/auth-providers");
    const providers = mode === "logout" ? response.data?.logoutProviders || [] : response.data?.loginProviders || [];
    const guidance = String(response.data?.guidance || "").trim();
    const items = providers.map((provider) => ({
      id: provider.id,
      label: provider.name || provider.id,
      description: provider.authType === "oauth" ? "OAuth / subscription" : "API key",
      meta: provider.status?.configured
        ? `configured via ${provider.status.source || "stored"}`
        : "not configured in auth.json",
      badge: provider.status?.configured ? "configured" : "",
      provider,
    }));
    if (!items.length) {
      elements.nativeCommandBody.replaceChildren(make("p", "native-command-note", mode === "logout"
        ? "No stored credentials to remove. /logout only removes credentials saved by /login."
        : "No providers are currently available."));
      if (guidance) elements.nativeCommandBody.append(make("p", "native-command-note muted", guidance));
      return;
    }
    const render = () => renderNativeSelectorItems(items, {
      emptyText: "No providers match this filter.",
      onSelect: async (item) => {
        if (mode === "login") {
          setNativeCommandError(`Run /login in the Pi TUI for ${item.label}. Browser login is not implemented yet.`);
          return;
        }
        if (!(await appConfirmText(`Remove stored credentials for ${item.label}?`, { affected: `${item.label} stored credentials`, confirmLabel: "Remove credentials" }))) return;
        setNativeCommandError("");
        try {
          const result = await nativeCommandApi("/api/auth-logout", {
            method: "POST",
            body: { provider: item.provider.id, confirmed: true },
          });
          addTransientMessage({ role: "native", title: "/logout", content: result.data?.message || "Provider credentials removed.", level: "info" });
          closeNativeCommandDialog();
          scheduleRefreshState(120);
        } catch (error) {
          setNativeCommandError(error.message || String(error));
        }
      },
    });
    elements.nativeCommandSearch.oninput = render;
    render();
  } catch (error) {
    setNativeCommandError(error.message || String(error));
    elements.nativeCommandBody.replaceChildren();
  }
}

async function handleNativeSlashSelectorCommand(message, { usesPromptInput = false } = {}) {
  const summaryMatch = String(message || "").trim().match(/^\/summary(?:\s+(refresh))?$/i);
  const name = summaryMatch ? "summary" : slashCommandName(message);
  if (!NATIVE_SELECTOR_COMMANDS.has(name)) return false;
  const featureId = optionalFeatureIdForCommand(name);
  if ((name === "workflow-setup" || name === "summary" || name === "summary-setup") && !hasLoadedRpcCommand(name)) {
    const tabContext = activeTabContext();
    addEvent(commandUnavailableMessage(name), "warn");
    refreshCommands(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
    });
    return true;
  }
  if (featureId && !isOptionalFeatureEnabled(featureId)) {
    const tabContext = activeTabContext();
    addEvent(commandUnavailableMessage(name), "warn");
    refreshCommands(tabContext).catch((error) => {
      if (isCurrentTabContext(tabContext)) addEvent(error.message || String(error), "error");
    });
    return true;
  }
  setComposerActionsOpen(false);
  hideCommandSuggestions();
  if (usesPromptInput) {
    elements.promptInput.value = "";
    resizePromptInput();
  }
  switch (name) {
    case "model":
      await openNativeModelSelector();
      return true;
    case "settings":
      await openNativeSettingsDialog();
      return true;
    case "summary":
      await openSessionSummaryForTab(activeTabId, { refresh: summaryMatch?.[1]?.toLowerCase() === "refresh" });
      return true;
    case "summary-setup":
      await openNativeSessionSummarySetupDialog();
      return true;
    case "workflow-setup":
      await openNativeWorkflowSetupDialog();
      return true;
    case "safety-guard-setup":
      await openNativeSafetyGuardSetupDialog();
      return true;
    case "git-workflow-setup":
      await openNativeGitWorkflowSetupDialog();
      return true;
    case "theme":
      openNativeThemeSelector();
      return true;
    case "fork":
      await openNativeForkSelector();
      return true;
    case "clone":
      openNativeCloneDialog();
      return true;
    case "name":
      openNativeNameDialog();
      return true;
    case "resume":
      await openNativeResumeSelector();
      return true;
    case "tree":
      await openNativeTreeSelector();
      return true;
    case "scoped-models":
      openNativeScopedModelsInfo();
      return true;
    case "tools":
      await openNativeToolsSelector();
      return true;
    case "skills":
      await openNativeSkillsSelector();
      return true;
    case "login":
    case "logout":
      await openNativeAuthSelector(name);
      return true;
    default:
      return false;
  }
}

function shouldSendPromptFromEnter(event) {
  if (event.key !== "Enter" || event.shiftKey || event.isComposing) return false;
  if (event.ctrlKey || event.metaKey) return true;
  return !isMobileView();
}

function insertNumpadDecimal(event) {
  const isNumpadDecimal = event.code === "NumpadDecimal"
    || event.keyCode === 110
    || (event.location === 3 && [".", ",", "Decimal", "Delete"].includes(event.key));
  if (event.defaultPrevented || !isNumpadDecimal || event.ctrlKey || event.metaKey || event.altKey || event.shiftKey || event.isComposing) return false;
  const input = event.currentTarget;
  if (!input || input.disabled || input.readOnly || typeof input.setRangeText !== "function") return false;
  const start = input.selectionStart ?? input.value.length;
  const end = input.selectionEnd ?? start;
  event.preventDefault();
  input.setRangeText(".", start, end, "end");
  input.dispatchEvent(new InputEvent("input", { bubbles: true, data: ".", inputType: "insertText" }));
  return true;
}

// Transcript-only. Message rendering may reconcile transcript state and the
// transcript DOM, but never footer/feedback/widget chrome: those surfaces are
// owned by the coalesced semantic reconciler.
function renderMessages(messages) {
  latestMessages = messages || [];
  reconcileOptimisticUserPrompts(latestMessages);
  cleanupLiveToolRunsForMessages(latestMessages);
  syncLastUserPromptFromMessages(latestMessages);
  syncPromptHistoryFromMessages(latestMessages);
  trackSkillsFromMessages(latestMessages, activeTabId);
  renderAllMessages();
}

function cancelStreamBubbleHide() {
  clearTimeout(streamBubbleHideTimer);
  streamBubbleHideTimer = null;
}

function compactOutputActive() {
  return outputModeAcknowledged && activeOutputMode === "compact-v1";
}

function outputModeAcknowledgement(event) {
  const outputMode = event?.outputMode;
  if (outputMode?.protocolVersion !== 1 || !["normal", "compact-v1"].includes(outputMode.activeMode)) return null;
  return outputMode;
}

function removeCompactLiveBubble(bubble) {
  const messageKey = bubble?.dataset?.transcriptMessageKey || bubble?.dataset?.itemKey || "compact-live";
  removeLiveTranscriptBubble(bubble, messageKey);
}

function clearCompactToolShells() {
  for (const shell of compactToolShells.values()) removeCompactLiveBubble(shell?.bubble);
  compactToolShells.clear();
}

function resetCompactLiveOutput({ remove = true } = {}) {
  compactLiveScheduler.cancel();
  compactLiveState = createFastOutputLiveState();
  clearCompactThinkingDisclosureState("live");
  if (remove) {
    removeCompactLiveBubble(compactTextBubble);
    removeCompactLiveBubble(compactThinkingBubble);
    clearCompactToolShells();
  } else {
    compactToolShells.clear();
  }
  compactTextBubble = null;
  compactTextNode = null;
  compactThinkingBubble = null;
  compactThinkingNode = null;
}

function ensureCompactTextBubble() {
  if (compactTextBubble?.parentElement === elements.chat && compactTextNode) return;
  const created = appendMessage({ role: "assistant", title: "final output", timestamp: Date.now(), content: "" }, { streaming: true, itemKey: "live:compact-output" });
  compactTextBubble = created.bubble;
  compactTextBubble.classList.add("compact-live-output");
  compactTextNode = make("div", "compact-live-text");
  created.body.append(compactTextNode);
  transcriptRenderer.ownSurface(compactTextNode, { messageKey: "live:compact-output", kind: "compact-output", segment: "0" });
  renderRunIndicator({ scroll: false });
}

function ensureCompactThinkingBubble() {
  if (!thinkingOutputVisible) return false;
  if (compactThinkingBubble?.parentElement === elements.chat && compactThinkingNode) return true;
  const created = appendMessage({ role: "thinking", title: "thinking (live)", timestamp: Date.now(), content: "", compactThinkingAggregate: true, compactThinkingKey: "live", compactThinkingDefaultExpanded: true }, { streaming: true, itemKey: "live:compact-thinking" });
  compactThinkingBubble = created.bubble;
  compactThinkingBubble.classList.add("compact-live-output");
  compactThinkingNode = make("div", "markdown-body thinking-text compact-live-thinking");
  created.body.append(compactThinkingNode);
  transcriptRenderer.ownSurface(compactThinkingNode, { messageKey: "live:compact-thinking", kind: "assistant-thinking", segment: "0" });
  renderRunIndicator({ scroll: false });
  return true;
}

function compactToolShellId(event) {
  const direct = String(event?.toolCallId || event?.id || "").trim();
  return direct || `compact-tool-${compactToolShells.size + 1}`;
}

function renderCompactToolShell(event, { complete = false } = {}) {
  const id = compactToolShellId(event);
  let shell = compactToolShells.get(id);
  if (!shell) {
    clearCompactToolShells();
    const bubble = make("article", "message toolExecution compact-tool-shell streaming");
    const header = make("div", "message-header");
    const role = make("span", "message-role");
    const timestamp = make("span", "muted", formatDate(Date.now()));
    const body = make("div", "message-body");
    const status = make("div", "compact-tool-status");
    header.append(role, timestamp);
    body.append(status);
    bubble.append(header, body);
    bubble.dataset.toolCallId = id;
    transcriptRenderer.ownMessage(bubble, { key: `live:compact-tool:${id}`, role: "toolExecution" });
    transcriptRenderer.ownSurface(body, { messageKey: `live:compact-tool:${id}`, kind: "tool-execution", segment: "0" });
    transcriptRenderer.ownSurface(status, { messageKey: `live:compact-tool:${id}`, kind: "tool-execution", segment: "status" });
    appendChatMessageBubble(bubble, { liveTail: true });
    shell = { bubble, role, status };
    compactToolShells.set(id, shell);
  }
  const name = String(event?.toolName || event?.name || "tool");
  shell.role.textContent = `tool: ${name}`;
  transcriptRenderer.updateTextSurface({
    key: `compact-tool:${id}`,
    surface: shell.status,
    messageKey: `live:compact-tool:${id}`,
    kind: "tool-execution",
    text: complete
      ? event?.isError ? "failed" : "done"
      : "running",
  });
  shell.bubble.classList.toggle("tool-error", !!event?.isError);
  shell.bubble.classList.toggle("tool-running", !complete);
  shell.bubble.classList.toggle("tool-success", complete && !event?.isError);
  return shell;
}

function flushCompactLiveOutput() {
  if (compactLiveState.text) {
    ensureCompactTextBubble();
    if (compactTextNode?.textContent !== compactLiveState.text) {
      const selectionSnapshot = captureChatTextSelection(compactTextNode);
      transcriptRenderer.updateTextSurface({
        key: "compact-output",
        surface: compactTextNode,
        messageKey: "live:compact-output",
        kind: "compact-output",
        text: compactLiveState.text,
      });
      restoreChatTextSelection(selectionSnapshot);
    }
  } else {
    removeCompactLiveBubble(compactTextBubble);
    compactTextBubble = null;
    compactTextNode = null;
  }
  if (compactLiveState.thinking && ensureCompactThinkingBubble()) {
    if (compactThinkingNode?._rawThinkingText !== compactLiveState.thinking) renderThinkingMarkdown(compactThinkingNode, compactLiveState.thinking);
  } else if (!compactLiveState.thinking) {
    removeCompactLiveBubble(compactThinkingBubble);
    compactThinkingBubble = null;
    compactThinkingNode = null;
  }
  scheduleChatFollowScroll();
}

function finishCompactLiveOutput(tabContext = activeTabContext()) {
  compactLiveScheduler.flushNow();
  scheduleRefreshMessages(0, tabContext);
}

function handleCompactMessageUpdate(event) {
  const reduced = reduceFastOutputLiveEvent(compactLiveState, event);
  if (!shouldConsumeFastOutputLiveEvent(reduced)) return false;
  if (!reduced.changed) return true;
  compactLiveState = reduced.state;
  clearCompactToolShells();
  return true;
}

function acceptOutputModeAcknowledgement(event) {
  const acknowledgement = outputModeAcknowledgement(event);
  if (acknowledgement) {
    activeOutputMode = acknowledgement.activeMode;
    outputModeAcknowledged = true;
    if (!currentState?.isStreaming) renderAllMessages({ preserveScroll: true, forceRebuild: true });
    return true;
  }
  activeOutputMode = "normal";
  outputModeAcknowledged = false;
  if (!eventSourceOutputModeFallbackAttempted) {
    eventSourceOutputModeFallbackAttempted = true;
    queueMicrotask(() => connectEvents(activeTabContext(), { requestedMode: "normal", fallbackAttempted: true }));
  }
  return false;
}

function transitionNormalLiveOutputToCompact() {
  flushNormalStreamRenders("output-mode-transition");
  compactLiveState = seedFastOutputLiveState({ text: streamRawText, thinking: streamThinkingRawText });
  setStreamRawText("");
  setStreamThinkingRawText("");
  removeStreamBubble();
  removeStreamingThinkingBubble();
  flushCompactLiveOutput();
}

function transitionCompactLiveOutputToNormal(tabContext = activeTabContext()) {
  finishCompactLiveOutput(tabContext);
  const live = fastOutputLiveTextAndThinking(compactLiveState);
  resetCompactLiveOutput();
  setStreamRawText(live.text);
  setStreamThinkingRawText(live.thinking);
  if (live.thinking) setStreamingThinkingText(live.thinking);
  if (live.text) renderStreamingAssistantText();
}

function applyOutputModeControl(event, tabContext = activeTabContext()) {
  if (event?.protocolVersion !== 1 || !["normal", "compact-v1"].includes(event.activeMode)) return false;
  flushNormalStreamRenders("output-mode-change");
  fallbackStreamDerivedOutput("output-mode-change");
  const previousMode = activeOutputMode;
  if (previousMode === "normal" && event.activeMode === "compact-v1") {
    transitionNormalLiveOutputToCompact();
  } else if (previousMode === "compact-v1" && event.activeMode === "normal") {
    transitionCompactLiveOutputToNormal(tabContext);
  } else if (previousMode === "compact-v1") {
    finishCompactLiveOutput(tabContext);
    resetCompactLiveOutput();
  } else if (event.activeMode === "normal") {
    resetCompactLiveOutput();
  }
  activeOutputMode = event.activeMode;
  outputModeAcknowledged = true;
  if (!currentState?.isStreaming) renderAllMessages({ preserveScroll: true, forceRebuild: true });
  addEvent(`live output mode changed to ${event.activeMode}`, "info");
  return true;
}

function removeStreamBubble() {
  cancelStreamBubbleHide();
  removeLiveTranscriptBubble(streamBubble, "assistant");
  streamBubble = null;
  streamText = null;
  streamBubbleVisibleSince = 0;
  renderRunIndicator({ scroll: false });
}

function ensureStreamDerivedOutputState() {
  const todoProgressDetected = isOptionalFeatureDetected("todoProgressWidget");
  if (!streamDerivedOutputState) {
    streamDerivedOutputState = createStreamDerivedOutputState({
      todoProgressDetected,
      shadow: !!streamIsolationDebugLedger,
    });
  } else {
    streamDerivedOutputState.setTodoProgressDetected(todoProgressDetected);
  }
  return streamDerivedOutputState;
}

function recordStreamDerivedOutputDiagnostic(diagnostic, ms = 0) {
  if (!streamIsolationDebugLedger || (!diagnostic.scannedCodeUnits && !diagnostic.fallbackReason && !diagnostic.shadowMismatch)) return;
  const bytes = diagnostic.scannedCodeUnits * 2;
  recordStreamProfileDiagnostic({ type: "derive", ms, bytes });
  if (diagnostic.fallbackReason) recordStreamProfileDiagnostic({ type: "derive-fallback", reason: diagnostic.fallbackReason, bytes });
  if (diagnostic.shadowMismatch) recordStreamProfileDiagnostic({ type: "derive-shadow-mismatch", reason: diagnostic.fallbackReason || "shadow-mismatch" });
}

function captureStreamDerivedOutputProfile(startedAt) {
  recordStreamDerivedOutputDiagnostic(
    ensureStreamDerivedOutputState().takeDiagnostics(),
    streamIsolationDebugLedger ? performance.now() - startedAt : 0,
  );
}

function resetStreamDerivedOutputState(reason = "reset") {
  if (!streamDerivedOutputState) return;
  streamDerivedOutputState.reset({
    todoProgressDetected: isOptionalFeatureDetected("todoProgressWidget"),
    reason,
  });
  recordStreamDerivedOutputDiagnostic(streamDerivedOutputState.takeDiagnostics());
}

function fallbackStreamDerivedOutput(reason) {
  if (!streamRawText || !streamDerivedOutputState) return;
  const profileStart = streamIsolationDebugLedger ? performance.now() : 0;
  ensureStreamDerivedOutputState().replace(streamRawText, { reason, force: true });
  captureStreamDerivedOutputProfile(profileStart);
}

function setStreamRawText(text, { reason = "snapshot" } = {}) {
  const nextText = String(text || "");
  if (nextText === streamRawText) return false;
  const profileStart = streamIsolationDebugLedger ? performance.now() : 0;
  streamRawText = nextText;
  ensureStreamDerivedOutputState().replace(nextText, { reason });
  captureStreamDerivedOutputProfile(profileStart);
  return true;
}

function appendStreamRawText(delta) {
  const text = String(delta || "");
  if (!text) return false;
  const profileStart = streamIsolationDebugLedger ? performance.now() : 0;
  streamRawText += text;
  ensureStreamDerivedOutputState().append(text);
  captureStreamDerivedOutputProfile(profileStart);
  return true;
}

function streamingAssistantTextFallback(event) {
  // Fallback for legacy/summary events that do not carry a delta. The hot
  // text_delta path appends update.delta and avoids this accumulated-message scan.
  return assistantTextFromMessage(assistantStreamingMessage(event), { streaming: true });
}

function syncStreamRawTextFromUpdate(event, update) {
  if (update.type === "text_delta") {
    const delta = update.delta ?? update.text ?? update.content ?? "";
    if (appendStreamRawText(delta)) return true;
  }
  if (typeof update.content === "string") return setStreamRawText(update.content);
  if (typeof update.text === "string") return setStreamRawText(update.text);
  const partialText = streamingAssistantTextFallback(event);
  return typeof partialText === "string" ? setStreamRawText(partialText) : false;
}

function streamDerivedText() {
  const state = ensureStreamDerivedOutputState();
  if (state.value().rawText !== streamRawText) {
    const profileStart = streamIsolationDebugLedger ? performance.now() : 0;
    state.replace(streamRawText, { reason: "state-divergence" });
    captureStreamDerivedOutputProfile(profileStart);
  }
  return state.value();
}

function streamRenderableAssistantText() {
  return streamDerivedText().finalText;
}

function authoritativeAssistantTextForAdoption(message) {
  if (message?.role !== "assistant") return null;
  const finalParts = assistantDisplayMessages(message).filter((part) => part?.role === "assistant");
  // A live bubble can only be adopted without a structural map when the
  // authoritative message has exactly one final-output surface. Multi-part
  // settlement remains an explicit invalidation/mapping follow-up.
  if (finalParts.length !== 1) return null;
  return stripTodoProgressLines(textFromContent(finalParts[0].content), { streaming: false });
}

function adoptLiveAssistantBubble(messages) {
  const compactCandidate = compactTextBubble?.isConnected && compactTextBubble.parentElement === elements.chat && compactTextNode
    ? {
        bubble: compactTextBubble,
        surface: compactTextNode,
        text: stripTodoProgressLines(compactLiveState.text, { streaming: true }),
        kind: "compact",
      }
    : null;
  const normalCandidate = streamBubble?.isConnected && streamBubble.parentElement === elements.chat && streamText
    ? { bubble: streamBubble, surface: streamText, text: streamRenderableAssistantText(), kind: "normal" }
    : null;
  const candidate = compactCandidate?.text ? compactCandidate : normalCandidate?.text ? normalCandidate : null;
  if (!candidate) return "";
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const authoritativeText = authoritativeAssistantTextForAdoption(messages[index]);
    if (authoritativeText !== candidate.text) continue;
    const key = `m:${index}`;
    candidate.bubble.dataset.itemKey = key;
    transcriptRenderer.ownMessage(candidate.bubble, { key, role: "assistant" });
    transcriptRenderer.ownSurface(candidate.surface, { messageKey: key, kind: "assistant-final", segment: "0" });
    pendingTranscriptAdoptions.set(key, candidate.bubble);
    return candidate.kind;
  }
  return "";
}

function finalizeAdoptedAssistantBubble(bubble, message, key) {
  const compactSurface = bubble?.querySelector?.(".compact-live-text");
  if (!compactSurface) return;
  const authoritativeText = authoritativeAssistantTextForAdoption(message);
  if (authoritativeText === null) return;
  bubble.classList.remove("compact-live-output");
  compactSurface.classList.remove("compact-live-text");
  compactSurface.classList.add("markdown-body", "compact-transcript-text");
  transcriptRenderer.reconcileMarkdownSurface({
    key: `compact-settlement:${key}`,
    surface: compactSurface,
    messageKey: key,
    kind: "assistant-final",
    text: authoritativeText,
    stableBoundary: (value) => value.length,
    renderInto: renderMarkdownInto,
  });
}

function scheduleStreamBubbleHide() {
  if (!streamBubble) return;
  const visibleForMs = streamBubbleVisibleSince ? performance.now() - streamBubbleVisibleSince : STREAM_OUTPUT_MIN_VISIBLE_MS;
  const delayMs = Math.max(STREAM_OUTPUT_HIDE_DELAY_MS, STREAM_OUTPUT_MIN_VISIBLE_MS - visibleForMs);
  clearTimeout(streamBubbleHideTimer);
  streamBubbleHideTimer = setTimeout(() => {
    streamBubbleHideTimer = null;
    if (streamRenderableAssistantText() || !streamBubble) return;
    removeStreamBubble();
  }, delayMs);
}

function syncStreamingThinkingFormat({ complete = false } = {}) {
  const parsed = streamDerivedText().thinkingFormat;
  if (!parsed?.hasThinkingFormat) return null;
  const thinking = visibleThinkingText(parsed.thinkingText);
  if (thinking) setStreamingThinkingText(thinking, { complete: complete || parsed.complete });
  if (parsed.complete && streamThinkingBubble) streamThinkingBubble.classList.add("complete");
  return parsed;
}

function renderStreamingAssistantText({ complete = false } = {}) {
  const thinkingFormat = syncStreamingThinkingFormat({ complete });
  const finalText = thinkingFormat?.hasThinkingFormat ? streamDerivedText().finalText : streamRenderableAssistantText();
  if (finalText) {
    ensureStreamBubble();
    renderStreamingMarkdown(streamText, finalText, { complete });
  } else {
    scheduleStreamBubbleHide();
  }
}

function suppressStreamingAssistantTextBeforeToolCall() {
  flushNormalStreamRenders("tool-call-boundary");
  setStreamRawText("");
  removeStreamBubble();
}

function resetStreamingToolCallState({ remove = true } = {}) {
  if (remove) streamToolCallBubble?.remove();
  streamToolCallBubble = null;
  streamToolCallText = null;
  streamToolCallRawArguments = "";
  streamToolCallName = "";
  streamToolCallId = "";
  streamToolCallContentIndex = null;
  streamToolCallComplete = false;
}

function streamingToolCallTitle() {
  const name = streamToolCallName || "tool";
  return `tool call: ${name}${streamToolCallComplete ? " (ready)" : " (building)"}`;
}

function streamingToolCallMessage() {
  return {
    role: "toolCall",
    title: streamingToolCallTitle(),
    timestamp: Date.now(),
    toolName: streamToolCallName || "tool",
    toolCallId: streamToolCallId,
    rawArguments: streamToolCallRawArguments,
    content: streamToolCallRawArguments,
  };
}

function renderStreamingToolCallCard({ scroll = false } = {}) {
  const message = streamingToolCallMessage();
  const displayText = streamToolCallRawArguments || (streamToolCallComplete ? "{}" : "(waiting for argument stream…)");
  if (!streamToolCallBubble?.parentElement || !streamToolCallText) {
    const created = appendMessage(message, { streaming: true, itemKey: `live:tool-call:${streamToolCallId || "pending"}` });
    streamToolCallBubble = created.bubble;
    streamToolCallText = created.body.querySelector(".tool-call-arguments") || created.body.querySelector(".code-block");
    transcriptRenderer.ownSurface(streamToolCallText, { messageKey: streamToolCallBubble.dataset.transcriptMessageKey, kind: "tool-execution", segment: "0" });
  }
  streamToolCallBubble._copyMessage = message;
  const role = streamToolCallBubble.querySelector(":scope > .message-header .message-role");
  if (role && role.textContent !== message.title) role.textContent = message.title;
  if (streamToolCallText && streamToolCallText.textContent !== displayText) {
    transcriptRenderer.updateTextSurface({
      key: `tool-call:${streamToolCallId || "pending"}`,
      surface: streamToolCallText,
      messageKey: streamToolCallBubble.dataset.transcriptMessageKey,
      kind: "tool-execution",
      text: displayText,
    });
  }
  renderRunIndicator({ scroll: false });
  if (scroll) scrollChatToBottom();
}

function removeStreamingToolCallCard() {
  resetStreamingToolCallState({ remove: true });
  renderRunIndicator({ scroll: false });
}

function ensureStreamBubble() {
  cancelStreamBubbleHide();
  if (streamBubble?.parentElement === elements.chat) return;
  const created = appendMessage({ role: "assistant", title: "final output", timestamp: Date.now(), content: "" }, { streaming: true, itemKey: "live:assistant" });
  streamBubble = created.bubble;
  streamText = make("div", "markdown-body streaming-markdown");
  created.body.append(streamText);
  transcriptRenderer.ownSurface(streamText, { messageKey: "live:assistant", kind: "assistant-final", segment: "0" });
  streamBubbleVisibleSince = performance.now();
  renderRunIndicator({ scroll: false });
  scrollChatToBottom();
}

function ensureStreamingThinkingBubble() {
  if (!thinkingOutputVisible) return false;
  if (streamThinkingBubble?.parentElement === elements.chat) return true;
  const created = appendMessage({ role: "thinking", title: "thinking", timestamp: Date.now(), content: "" }, { streaming: true, itemKey: "live:thinking" });
  streamThinkingBubble = created.bubble;
  streamThinking = make("div", "markdown-body thinking-text");
  created.body.append(streamThinking);
  transcriptRenderer.ownSurface(streamThinking, { messageKey: "live:thinking", kind: "assistant-thinking", segment: "0" });
  renderRunIndicator({ scroll: false });
  scrollChatToBottom();
  return true;
}

function showStreamingThinking(initialText = "") {
  if (!ensureStreamingThinkingBubble()) return;
  if (initialText && !streamThinking.textContent) renderThinkingMarkdown(streamThinking, initialText);
}

function resetStreamBubble({ preserveCompact = false } = {}) {
  cancelNormalStreamRenders();
  resetCompactLiveOutput({ remove: !preserveCompact });
  cancelStreamBubbleHide();
  streamBubble = null;
  streamText = null;
  streamRawText = "";
  streamThinkingRawText = "";
  resetStreamDerivedOutputState("reset");
  streamBubbleVisibleSince = 0;
  streamToolCallSeen = false;
  streamToolCalls.reset();
  resetStreamingToolCallState({ remove: true });
  streamThinkingBubble = null;
  streamThinking = null;
  streamMessageActive = false;
  streamProviderErrorText = "";
}

function compactLiveStreamRenderActive() {
  const messageOutputActive = streamMessageActive && Boolean(
    compactTextBubble
    || compactThinkingBubble
    || compactLiveState.text
    || compactLiveState.thinking
    || compactLiveState.toolCall?.arguments,
  );
  return compactOutputActive() && currentState?.isStreaming === true && Boolean(compactToolShells.size || messageOutputActive);
}

function liveStreamRenderActive() {
  return streamMessageActive && currentState?.isStreaming === true && Boolean(streamBubble || streamThinkingBubble || streamToolCallBubble || streamRawText || streamToolCallRawArguments);
}

function restoreCompactLiveOutputAfterChatRebuild() {
  compactTextBubble = null;
  compactTextNode = null;
  compactThinkingBubble = null;
  compactThinkingNode = null;
  if (streamMessageActive) flushCompactLiveOutput();
  for (const shell of compactToolShells.values()) appendChatMessageBubble(shell.bubble, { liveTail: true });
  renderRunIndicator({ scroll: false });
}

/**
 * Reconcile live stream surfaces after an authoritative transcript render.
 * Transcript resets intentionally keep mounted live-tail bubbles, so reuse
 * those nodes and only rebuild a surface when it was actually detached.
 */
function restoreStreamRenderAfterChatRebuild() {
  const thinkingText = streamThinking?._rawThinkingText || streamThinking?.textContent || "";
  const thinkingComplete = streamThinkingBubble?.classList.contains("complete") === true;
  const toolCallWasVisible = !!(streamToolCallBubble?.parentElement === elements.chat || streamToolCallRawArguments || streamToolCallName);
  const streamOutputMounted = !!(streamBubble?.parentElement === elements.chat && streamText?.isConnected && streamBubble.contains(streamText));
  const thinkingOutputMounted = !!(streamThinkingBubble?.parentElement === elements.chat && streamThinking?.isConnected && streamThinkingBubble.contains(streamThinking));
  const toolCallOutputMounted = !!(streamToolCallBubble?.parentElement === elements.chat && streamToolCallText?.isConnected && streamToolCallBubble.contains(streamToolCallText));
  if (!streamOutputMounted) {
    removeLiveTranscriptBubble(streamBubble, "assistant-rebuild");
    streamBubble = null;
    streamText = null;
    streamBubbleVisibleSince = 0;
  }
  if (!thinkingOutputMounted) {
    removeLiveTranscriptBubble(streamThinkingBubble, "thinking-rebuild");
    streamThinkingBubble = null;
    streamThinking = null;
  }
  if (!toolCallOutputMounted) {
    removeLiveTranscriptBubble(streamToolCallBubble, "tool-call-rebuild");
    streamToolCallBubble = null;
    streamToolCallText = null;
  }
  if (thinkingText && setStreamingThinkingText(thinkingText) && thinkingComplete) {
    streamThinkingBubble?.classList.add("complete");
  }
  if (toolCallWasVisible) renderStreamingToolCallCard();
  if (streamRenderableAssistantText()) renderStreamingAssistantText();
}

function thinkingDeltaText(update) {
  return visibleThinkingText(update.delta || update.thinking || update.content || "");
}

function assistantStreamingMessage(event) {
  if (event?.message?.role === "assistant") return event.message;
  const partial = event?.assistantMessageEvent?.partial;
  return partial?.role === "assistant" ? partial : null;
}

function updateStreamingToolCallFromState(call) {
  if (!call?.visible) return;
  if (call.contentIndex !== streamToolCallContentIndex || call.id !== streamToolCallId) {
    resetStreamingToolCallState({ remove: true });
  }
  streamToolCallContentIndex = call.contentIndex;
  streamToolCallName = call.name;
  streamToolCallId = call.id;
  streamToolCallComplete = call.complete;
  streamToolCallRawArguments = call.rawArguments;
  if (call.truncated) streamToolCallRawArguments += "\n[Live arguments truncated; see the completed tool card.]";
  renderStreamingToolCallCard();
}

function assistantTextFromMessage(message, { streaming = false } = {}) {
  void streaming;
  const content = message?.content;
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return null;
  const parts = [];
  for (let index = 0; index < content.length; index += 1) {
    const part = content[index];
    const text = assistantTextPartText(part) || (part && typeof part === "object" && typeof part.text === "string" ? part.text : part !== undefined && part !== null && typeof part !== "object" ? String(part) : "");
    if (text && !assistantHasToolCallAfter(content, index)) parts.push(text);
  }
  return parts.length ? parts.join("\n\n") : "";
}

function assistantThinkingTextFromMessage(message, { streaming = false } = {}) {
  const content = message?.content;
  if (typeof content === "string") {
    const parsed = splitThinkingFormatText(content, { streaming });
    return parsed?.hasThinkingFormat ? visibleThinkingText(parsed.thinkingText) : null;
  }
  if (!Array.isArray(content)) return null;
  const parts = [];
  for (const part of content) {
    if (part && typeof part === "object" && (part.type === "thinking" || typeof part.thinking === "string")) {
      const thinking = visibleThinkingText(assistantThinkingText(part));
      if (thinking.trim()) parts.push(thinking);
      continue;
    }
    const text = assistantTextPartText(part) || (part && typeof part === "object" && typeof part.text === "string" ? part.text : part !== undefined && part !== null && typeof part !== "object" ? String(part) : "");
    const parsed = splitThinkingFormatText(text, { streaming });
    const thinking = parsed?.hasThinkingFormat ? visibleThinkingText(parsed.thinkingText) : "";
    if (thinking.trim()) parts.push(thinking);
  }
  return parts.length ? parts.join("\n\n") : "";
}

function setStreamingThinkingText(text, { complete = false } = {}) {
  const thinking = visibleThinkingText(text);
  if (!thinkingOutputVisible) return false;
  if (!thinking) {
    removeLiveTranscriptBubble(streamThinkingBubble, "thinking-correction");
    streamThinkingBubble = null;
    streamThinking = null;
    return true;
  }
  showStreamingThinking("");
  if (streamThinking) renderThinkingMarkdown(streamThinking, thinking, { complete });
  return true;
}

function streamingThinkingTextFallback(event) {
  return assistantThinkingTextFromMessage(assistantStreamingMessage(event), { streaming: true });
}

function setStreamThinkingRawText(text, { reconcile = false } = {}) {
  const snapshot = visibleThinkingText(text);
  const thinking = reconcile
    ? reconcileTranscriptThinkingSnapshot(streamThinkingRawText, snapshot)
    : snapshot;
  if (thinking === streamThinkingRawText) return false;
  streamThinkingRawText = thinking;
  return true;
}

function appendStreamThinkingText(delta) {
  const thinking = visibleThinkingText(delta);
  if (!thinking) return false;
  streamThinkingRawText += thinking;
  return true;
}

function syncStreamingThinkingFromUpdate(event, update, { placeholder = "", render = true } = {}) {
  if (!thinkingOutputVisible) return true;
  const delta = thinkingDeltaText(update);
  if (update.type === "thinking_delta" && delta) {
    appendStreamThinkingText(delta);
    return render ? setStreamingThinkingText(streamThinkingRawText || placeholder) : true;
  }
  if (update.type === "thinking_start") {
    if (delta) setStreamThinkingRawText(delta);
    if (!streamThinkingRawText) return false;
    return render ? setStreamingThinkingText(streamThinkingRawText || placeholder) : true;
  }
  if (update.type === "thinking_end") {
    const snapshot = typeof update.content === "string" ? update.content
      : typeof update.thinking === "string" ? update.thinking : streamingThinkingTextFallback(event);
    if (snapshot !== null) setStreamThinkingRawText(snapshot, { reconcile: true });
    return render ? setStreamingThinkingText(streamThinkingRawText, { complete: true }) : true;
  }
  const fallback = streamingThinkingTextFallback(event);
  if (fallback === null) return false;
  setStreamThinkingRawText(fallback);
  return render ? setStreamingThinkingText(streamThinkingRawText || placeholder) : true;
}

function assistantStreamErrorMessage(event, update = event?.assistantMessageEvent || {}) {
  return String(
    update.error?.errorMessage ||
    update.errorMessage ||
    update.partial?.errorMessage ||
    event?.message?.errorMessage ||
    update.reason ||
    "assistant error"
  ).trim();
}

function handleMessageUpdate(event) {
  if (compactOutputActive() && handleCompactMessageUpdate(event)) return;
  const update = event.assistantMessageEvent || {};
  if (update.type === "thinking_start" || update.type === "thinking_delta") {
    syncStreamingThinkingFromUpdate(event, update, { render: false });
    if (thinkingOutputVisible && streamThinkingRawText) thinkingStreamRenderScheduler.request({ complete: false });
  } else if (update.type === "thinking_end") {
    syncStreamingThinkingFromUpdate(event, update, { render: false });
    if (thinkingOutputVisible) {
      thinkingStreamRenderScheduler.request({ complete: true });
      thinkingStreamRenderScheduler.flushNow("thinking_end");
    }
  } else if (update.type === "text_delta" || update.type === "text_end") {
    syncStreamRawTextFromUpdate(event, update);
    if (update.type === "text_end") fallbackStreamDerivedOutput("settlement:text_end");
    assistantStreamRenderScheduler.request({ complete: update.type === "text_end" });
    if (update.type === "text_end") assistantStreamRenderScheduler.flushNow("text_end");
  } else if (update.type === "error") {
    streamProviderErrorText = assistantStreamErrorMessage(event, update);
    appendMessage({ role: "error", title: "assistant error", timestamp: Date.now(), content: streamProviderErrorText, level: "error" }, { streaming: true });
    renderRunIndicator({ scroll: false });
  }
}

function modelStateKey(model) {
  return model ? `${model.provider || ""}/${model.id || ""}` : "";
}

function gitFooterRelevantStateChanged(previousState, nextState) {
  if (!previousState || !nextState) return false;
  return previousState.thinkingLevel !== nextState.thinkingLevel || modelStateKey(previousState.model) !== modelStateKey(nextState.model);
}

async function refreshState(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const response = await api("/api/state", { tabId: tabContext.tabId });
  if (!isCurrentTabContext(tabContext)) return;
  const previousState = currentState;
  currentState = response.data || null;
  if (currentState) tabStateCache.set(tabContext.tabId, currentState);
  else tabStateCache.delete(tabContext.tabId);
  if (latestMessages.length) {
    latestMessagesSessionKey = resolveMessagesSessionKey(tabContext.tabId);
    cacheMessagesForTab(tabContext.tabId, latestMessages, latestMessagesSessionKey);
  }
  const shouldRefreshGitFooter = gitFooterRelevantStateChanged(previousState, currentState);
  syncActiveTabActivityFromState(currentState);
  syncRunIndicatorFromState(currentState);
  renderStatus();
  if (mobilePhoneExperienceInstalled && isMobileShellV2Active()) renderMobilePhoneExperience();
  requestGitFooterWebuiPayload(tabContext, { force: shouldRefreshGitFooter });
  // Sampling support and effective values depend on the active model, so refresh
  // them whenever the session reports a different model.
  if (modelStateKey(previousState?.model) !== modelStateKey(currentState?.model)) {
    refreshSamplingParametersForTabContext(tabContext);
  }
}

async function refreshStats(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const response = await api("/api/stats", { tabId: tabContext.tabId });
  if (!isCurrentTabContext(tabContext)) return;
  latestStats = response.data || null;
  if (latestStats) tabStatsCache.set(tabContext.tabId, latestStats);
  else tabStatsCache.delete(tabContext.tabId);
  renderFooter();
  renderContextMeter();
  renderWorkspaceDashboard();
}

async function refreshWorkspace(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  let nextWorkspace = null;
  try {
    const response = await api("/api/workspace", { tabId: tabContext.tabId });
    nextWorkspace = response.data || null;
  } catch (error) {
    if (!isCurrentTabContext(tabContext)) return;
    // Older webui server processes do not have /api/workspace. Fall back to /api/health,
    // which has exposed cwd from the beginning, so the footer still shows the real path.
    const health = await api("/api/health", { tabId: tabContext.tabId });
    nextWorkspace = health.cwd
      ? {
          cwd: health.cwd,
          displayCwd: normalizeDisplayPath(health.cwd),
          uptimeMs: latestWorkspace?.uptimeMs || 0,
        }
      : null;
  }
  if (!isCurrentTabContext(tabContext)) return;
  latestWorkspace = nextWorkspace;
  if (latestWorkspace) tabWorkspaceCache.set(tabContext.tabId, latestWorkspace);
  else tabWorkspaceCache.delete(tabContext.tabId);
  rememberServerStartCwd(nextWorkspace?.cwd);
  renderFooter();
  renderWorkspaceDashboard();
}

function renderNetworkStatus() {
  const network = latestNetwork;
  const open = !!network?.open;
  const opening = !!network?.opening;
  const closing = !!network?.closing;
  const rebinding = opening || closing;
  const localUrl = network?.localUrl || `${window.location.origin}/`;
  const networkUrls = Array.isArray(network?.networkUrls) ? network.networkUrls : [];
  syncRemoteWebuiControlVisibility();
  elements.networkStatus.className = `network-status ${opening ? "opening" : closing ? "closing" : open ? "open" : "closed"}`;
  elements.networkStatus.title = closing
    ? "Closing network access and returning to local-only"
    : open
      ? `Reachable on local network${networkUrls.length ? `:\n${networkUrls.join("\n")}` : " (no LAN address detected)"}`
      : "Only reachable from this machine";

  const heading = make(
    "div",
    "network-status-heading",
    opening ? "Opening to local network…" : closing ? "Closing network access…" : open ? "Open to local network" : "Closed · local only",
  );
  const detail = make(
    "div",
    "network-status-detail",
    closing
      ? "Rebinding to local-only access. Network clients will disconnect."
      : open
        ? "Use one of these URLs from a trusted device:"
        : "Only this machine can connect until you open the network listener.",
  );
  const list = make("div", "network-url-list");

  const addUrl = (label, url) => {
    const href = safeHttpUrl(url);
    if (!href) return;
    const row = make("div", "network-status-url-row");
    const labelNode = make("span", "network-status-url-label", label);
    const link = make("a", "network-status-url", url);
    link.href = href;
    link.target = "_blank";
    link.rel = "noreferrer";
    row.append(labelNode, link);
    list.append(row);
  };

  addUrl("Local", localUrl);
  if (open) {
    for (const url of networkUrls) addUrl("LAN", url);
    if (networkUrls.length === 0) list.append(make("div", "network-status-empty", "No LAN address detected."));
  }

  const auth = network?.auth || {};
  const authText = auth.enabled
    ? auth.pin
      ? `Remote PIN auth on · PIN ${auth.pin}`
      : "Remote PIN auth on"
    : "Remote PIN auth off";
  const authDetail = make("div", "network-status-detail", authText);

  elements.networkStatus.replaceChildren(heading, detail, list, authDetail);
  const remoteAuthRow = elements.remoteAuthToggle?.closest(".remote-auth-control-row");
  if (remoteAuthRow) remoteAuthRow.hidden = false;
  elements.remoteAuthToggle.checked = !!auth.enabled;
  elements.remoteAuthToggle.disabled = rebinding;
  elements.remoteAuthStatus.textContent = auth.enabled
    ? auth.pin
      ? `PIN ${auth.pin}`
      : "On"
    : "Off";
  elements.openNetworkButton.disabled = rebinding;
  elements.openNetworkButton.textContent = opening ? "Opening…" : closing ? "Closing…" : open ? "Close remote access" : "Open for remote access";
  if (elements.remoteAccessIndicator) {
    elements.remoteAccessIndicator.hidden = !open;
    elements.remoteAccessIndicator.textContent = open ? "Remote access open" : "";
    elements.remoteAccessIndicator.title = open
      ? `Network listener exposed${networkUrls.length ? ` at ${networkUrls.join(", ")}` : ""} · ${auth.enabled ? "PIN auth on" : "PIN auth off"}`
      : "";
  }
  document.body.classList.toggle("remote-access-open", open);
  if (elements.showRemoteQrButton) {
    elements.showRemoteQrButton.hidden = !open;
    elements.showRemoteQrButton.disabled = rebinding || !open;
    elements.showRemoteQrButton.textContent = "Open QR-Code";
  }
}

async function refreshNetworkStatus() {
  const hadNetworkStatus = networkStatusLoaded;
  const wasOpen = !!latestNetwork?.open;
  try {
    const response = await api("/api/network", { scoped: false });
    latestNetwork = response.data || null;
  } catch {
    const health = await api("/api/health", { scoped: false });
    latestNetwork = health.network || { open: false, opening: false, localUrl: window.location.origin };
  }
  renderNetworkStatus();
  networkStatusLoaded = true;

  const open = !!latestNetwork?.open;
  if (!open) {
    remoteQrAutoPopupShown = false;
    return;
  }

  if (!hadNetworkStatus) {
    remoteQrAutoPopupShown = true;
    return;
  }

  if (!wasOpen && !remoteQrAutoPopupShown && isLocalWebuiBrowserOrigin()) {
    showRemoteWebuiQrPopupFromNetwork({ auto: true }).catch((error) => addEvent(error.message || String(error), "warn"));
  }
}

async function runRemoteWebuiCommand(command) {
  const commandName = String(command || "").replace(/^\//, "").split(/\s+/, 1)[0] || "remote";
  if (!isOptionalFeatureEnabled("remoteWebui") || !hasAvailableCommand(commandName)) {
    const message = commandUnavailableMessage(commandName);
    addEvent(message, "warn");
    refreshCommands(activeTabContext()).catch((error) => addEvent(error.message || String(error), "error"));
    return false;
  }
  await runNativeCommandMenu(command);
  return true;
}

async function toggleRemoteAuth() {
  const enable = !latestNetwork?.auth?.enabled;
  elements.remoteAuthToggle.disabled = true;
  try {
    await runRemoteWebuiCommand(remoteWebuiCommand(enable ? "authOn" : "authOff", enable ? "/remote auth on" : "/remote auth off"));
    await delay(250);
    await refreshNetworkStatus();
  } catch (error) {
    addEvent(error.message || String(error), "error");
  } finally {
    renderNetworkStatus();
  }
}

async function refreshFooterData(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  await Promise.allSettled([refreshStats(tabContext), refreshWorkspace(tabContext)]);
}

// Session key of the last applied transcript fetch; deltas are only
// attempted while the tab+session is unchanged.
function resolveMessagesSessionKey(tabId = activeTabId) {
  if (!tabId) return "";
  const stateSessionId = tabId === activeTabId ? currentState?.sessionId : null;
  if (stateSessionId) return `${tabId}|${stateSessionId}`;
  if (latestMessagesSessionKey.startsWith(`${tabId}|`)) return latestMessagesSessionKey;
  const cached = tabMessagesCache.get(tabId);
  if (cached?.sessionKey?.startsWith(`${tabId}|`)) return cached.sessionKey;
  return `${tabId}|`;
}

function cacheMessagesForTab(tabId = activeTabId, messages = latestMessages, sessionKey = latestMessagesSessionKey) {
  if (!tabId || !Array.isArray(messages)) return;
  const stateSessionKey = tabId === activeTabId && currentState?.sessionId ? `${tabId}|${currentState.sessionId}` : "";
  const resolvedSessionKey = stateSessionKey || (sessionKey?.startsWith(`${tabId}|`) ? sessionKey : resolveMessagesSessionKey(tabId));
  tabMessagesCache.set(tabId, { messages, sessionKey: resolvedSessionKey });
}

function restoreCachedMessagesForActiveTab() {
  if (!activeTabId) return false;
  const cached = tabMessagesCache.get(activeTabId);
  if (!cached || !Array.isArray(cached.messages)) return false;
  latestMessages = cached.messages;
  latestMessagesSessionKey = cached.sessionKey || resolveMessagesSessionKey(activeTabId);
  renderMessages(latestMessages);
  if (autoFollowChat) setChatScrollTopInstant(elements.chat.scrollHeight);
  return true;
}

function messagesLookEqual(a, b) {
  return !!a && !!b && a.role === b.role && String(a.timestamp || "") === String(b.timestamp || "")
    && contentSignature(a.content) === contentSignature(b.content);
}

/**
 * Merge a /api/messages?since= delta into the previous transcript. Returns
 * null whenever the delta cannot be applied safely — history shrank
 * (compaction), counts are inconsistent, or the one-message overlap no
 * longer matches (fork/resume/retroactive edit) — in which case the caller
 * falls back to a full fetch. Merged arrays keep previous message object
 * identities, which keeps the WeakMap signature cache hot.
 */
function mergeMessagesDelta(previous, data) {
  if (!data || !Array.isArray(data.messages)) return null;
  const since = Number(data.since);
  const totalCount = Number(data.totalCount);
  if (!Number.isInteger(since) || !Number.isInteger(totalCount)) return null;
  if (since > previous.length || totalCount < previous.length) return null;
  if (totalCount !== since + data.messages.length) return null;
  if (since < previous.length && !messagesLookEqual(previous[since], data.messages[0])) return null;
  return previous.slice(0, since).concat(data.messages);
}

function mainOutputLoadingRequestIsCurrent(request) {
  return !!request?.tabContext && isCurrentTabContext(request.tabContext);
}

function currentMainOutputLoadingRequest() {
  return [...mainOutputLoadingRequests].filter(mainOutputLoadingRequestIsCurrent).at(-1) || null;
}

function renderMainOutputLoading({ reveal = false } = {}) {
  const request = currentMainOutputLoadingRequest();
  const active = !!request;
  elements.chat?.setAttribute("aria-busy", active ? "true" : "false");
  if (elements.mainOutputLoadingLabel) elements.mainOutputLoadingLabel.textContent = request?.label || "Loading your conversation…";
  clearTimeout(mainOutputLoadingRevealTimer);
  mainOutputLoadingRevealTimer = null;
  if (!elements.mainOutputLoading) return;
  if (!active) {
    elements.mainOutputLoading.hidden = true;
    return;
  }
  if (reveal || !elements.mainOutputLoading.hidden) {
    elements.mainOutputLoading.hidden = false;
    return;
  }
  mainOutputLoadingRevealTimer = setTimeout(() => {
    mainOutputLoadingRevealTimer = null;
    if (currentMainOutputLoadingRequest()) elements.mainOutputLoading.hidden = false;
  }, MAIN_OUTPUT_LOADING_REVEAL_DELAY_MS);
}

function beginMainOutputLoading(tabContext, label) {
  const request = { tabContext: { ...tabContext }, label };
  mainOutputLoadingRequests.add(request);
  renderMainOutputLoading();
  return request;
}

function updateMainOutputLoading(request, label) {
  if (!mainOutputLoadingRequests.has(request)) return;
  request.label = label;
  if (request === currentMainOutputLoadingRequest() && elements.mainOutputLoadingLabel) elements.mainOutputLoadingLabel.textContent = label;
}

function finishMainOutputLoading(request) {
  mainOutputLoadingRequests.delete(request);
  renderMainOutputLoading();
}

async function refreshMessages(tabContext = activeTabContext(), { authoritative = false } = {}) {
  if (!tabContext.tabId) return;
  const previousMessages = latestMessages;
  const sessionKey = resolveMessagesSessionKey(tabContext.tabId);
  const loadDelta = !authoritative && previousMessages.length > 1 && sessionKey === latestMessagesSessionKey;
  const loadingRequest = beginMainOutputLoading(tabContext, loadDelta ? "Checking for new messages…" : "Loading conversation history…");
  try {
    let nextMessages = null;
    if (loadDelta) {
      // Delta fetch with a one-message overlap: the last known message is
      // re-requested so retroactive changes are detected via mergeMessagesDelta.
      const response = await api(`/api/messages?since=${previousMessages.length - 1}`, { tabId: tabContext.tabId });
      if (!isCurrentTabContext(tabContext)) return;
      nextMessages = mergeMessagesDelta(previousMessages, response.data);
    }
    if (!nextMessages) {
      updateMainOutputLoading(loadingRequest, "Loading conversation history…");
      const response = await api("/api/messages", { tabId: tabContext.tabId });
      if (!isCurrentTabContext(tabContext)) return;
      nextMessages = response.data?.messages || [];
    }
    updateMainOutputLoading(loadingRequest, "Preparing your conversation…");
    latestMessages = nextMessages;
    latestMessagesSessionKey = sessionKey;
    cacheMessagesForTab(tabContext.tabId, latestMessages, latestMessagesSessionKey);
    const selectionSnapshot = captureChatTextSelection();
    const preserveCompactStream = compactLiveStreamRenderActive();
    const preserveNormalStream = !preserveCompactStream && liveStreamRenderActive();
    if (!preserveCompactStream && !preserveNormalStream) {
      const adoptedOutput = adoptLiveAssistantBubble(latestMessages);
      resetStreamBubble({ preserveCompact: adoptedOutput === "compact" });
    }
    renderMessages(latestMessages);
    if (preserveCompactStream) restoreCompactLiveOutputAfterChatRebuild();
    else if (preserveNormalStream) restoreStreamRenderAfterChatRebuild();
    restoreChatTextSelection(selectionSnapshot);
    markTabOutputSeen();
    // Authoritative content just landed: derive the todo-progress record once
    // here instead of from raw token cadence, and let the coalesced semantic
    // reconciler own the footer/widget chrome that message data can change.
    // syncLiveTodoProgressWidgetFromText owns the frame-coalesced widget render
    // and only fires when the parsed checklist value actually changed.
    reconcileTodoProgressFromMessages(latestMessages, tabContext.tabId);
    scheduleSemanticReconcile({ footer: true }, tabContext);
  } finally {
    finishMainOutputLoading(loadingRequest);
  }
}

async function refreshModels(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const response = await api("/api/models", { tabId: tabContext.tabId });
  const models = response.data?.models || [];
  let scopedModels = [];
  let scopedModelPatterns = [];
  let scopedModelSource = "none";
  let scopedModelError = null;
  try {
    const scopedResponse = await api("/api/scoped-models", { tabId: tabContext.tabId });
    scopedModels = scopedResponse.data?.models || [];
    scopedModelPatterns = scopedResponse.data?.patterns || [];
    scopedModelSource = scopedResponse.data?.source || "none";
  } catch (error) {
    scopedModelError = error;
  }
  if (!isCurrentTabContext(tabContext)) return;
  availableModels = models;
  footerScopedModels = scopedModels;
  footerScopedModels = orderedFooterScopedModels();
  footerScopedModelPatterns = scopedModelPatterns;
  footerScopedModelSource = scopedModelSource;
  if (scopedModelError) addEvent(`failed to load scoped models: ${scopedModelError.message}`, "warn");
  populateModelSelect(models, elements.modelSearchInput?.value || "");
  syncModelSelectToState();
  renderFooter();
  renderFeedbackTray();
  if (elements.commandPaletteDialog?.open) renderCommandPalette({ preserveScroll: true });
}

function modelSelectOptionText(model) {
  return `${model.provider}/${model.id}${model.name ? ` · ${model.name}` : ""}`;
}

function modelSelectValue(model) {
  return JSON.stringify({ provider: model.provider, modelId: model.id });
}

function modelSearchDisplayParts(model) {
  const id = `${model.provider}/${model.id}`;
  const name = String(model.name || "").trim();
  if (!name) return { primary: id, secondary: "" };
  const match = name.match(/^(.*?)(\s+\([^)]+\))$/);
  return { primary: (match?.[1] || name).trim(), secondary: `${id}${match?.[2] || ""}` };
}

let modelSearchResultsSignature = null;

function renderModelSearchResults(models = []) {
  if (!elements.modelSearchResults) return;
  // Skip redundant rebuilds (e.g. extension status pushes during streaming that
  // funnel through renderStatus -> syncModelSelectToState) so the Controls-panel
  // model list does not flicker or drop an in-progress interaction.
  const signature = JSON.stringify({
    hidden: !!elements.modelSearchInput?.hidden,
    selected: elements.modelSelect?.value || "",
    models: models.map((model) => `${modelSelectValue(model)}\u0000${modelSelectOptionText(model)}`),
  });
  if (signature === modelSearchResultsSignature) return;
  modelSearchResultsSignature = signature;
  elements.modelSearchResults.replaceChildren();
  if (elements.modelSearchInput?.hidden) return;
  if (!models.length) {
    elements.modelSearchResults.append(make("div", "model-search-empty", "No models match the search"));
    elements.modelSearchResults.hidden = false;
    return;
  }
  for (const model of models) {
    const value = modelSelectValue(model);
    const selected = elements.modelSelect?.value === value;
    const button = make("button", `model-search-result${selected ? " active" : ""}`);
    button.type = "button";
    button.setAttribute("role", "option");
    button.setAttribute("aria-selected", String(selected));
    button.title = modelSelectOptionText(model);
    const display = modelSearchDisplayParts(model);
    button.append(
      make("span", "model-search-result-main", display.primary),
      make("span", "model-search-result-name", display.secondary),
    );
    button.addEventListener("click", () => {
      if (elements.modelSelect) elements.modelSelect.value = value;
      setControlsPendingModel(value);
      renderModelSearchResults(models);
    });
    button.addEventListener("dblclick", () => elements.setModelButton?.click());
    elements.modelSearchResults.append(button);
  }
  elements.modelSearchResults.hidden = false;
}

function populateModelSelect(models = availableModels, query = "") {
  if (!elements.modelSelect) return;
  const previousValue = elements.modelSelect.value;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  const matchingModels = models.filter((model) => !normalizedQuery || modelSelectOptionText(model).toLowerCase().includes(normalizedQuery));
  const optionsSignature = JSON.stringify(matchingModels.map((model) => [modelSelectValue(model), modelSelectOptionText(model)]));
  if (elements.modelSelect.dataset.optionsSignature !== optionsSignature) {
    elements.modelSelect.dataset.optionsSignature = optionsSignature;
    elements.modelSelect.replaceChildren();
    for (const model of matchingModels) {
      const option = document.createElement("option");
      option.value = modelSelectValue(model);
      option.textContent = modelSelectOptionText(model);
      elements.modelSelect.append(option);
    }
    if (!matchingModels.length) {
      const option = document.createElement("option");
      option.value = "";
      option.textContent = "No models match the search";
      option.disabled = true;
      elements.modelSelect.append(option);
    }
  }
  if (previousValue && [...elements.modelSelect.options].some((option) => option.value === previousValue)) elements.modelSelect.value = previousValue;
  renderModelSearchResults(matchingModels);
}

function showModelSearchInput({ focus = true } = {}) {
  if (!elements.modelSearchInput) return;
  elements.modelSearchInput.hidden = false;
  elements.modelSearchResults.hidden = false;
  elements.modelSelect.classList.add("model-select-expanded");
  populateModelSelect(availableModels, elements.modelSearchInput.value);
  if (focus) {
    requestAnimationFrame(() => {
      elements.modelSearchInput.focus();
      elements.modelSearchInput.select();
    });
  }
}

function hideModelSearchInput() {
  if (!elements.modelSearchInput) return;
  elements.modelSearchInput.hidden = true;
  elements.modelSearchInput.value = "";
  if (elements.modelSearchResults) {
    elements.modelSearchResults.hidden = true;
    elements.modelSearchResults.replaceChildren();
  }
  elements.modelSelect?.classList.remove("model-select-expanded");
  populateModelSelect(availableModels, "");
  syncModelSelectToState();
  scheduleDeferredUiFlushAfterDropdownClose();
}

function setControlsPendingModel(value) {
  controlsPendingModelValue = value || "";
  elements.setModelButton?.classList.toggle("pending", Boolean(controlsPendingModelValue));
  if (elements.setModelButton) elements.setModelButton.title = controlsPendingModelValue ? "Apply the selected model (not applied yet)" : "Apply selected model";
}

function setControlsPendingThinking(value) {
  controlsPendingThinkingValue = value || "";
  elements.setThinkingButton?.classList.toggle("pending", Boolean(controlsPendingThinkingValue));
  if (elements.setThinkingButton) elements.setThinkingButton.title = controlsPendingThinkingValue ? "Apply the selected thinking effort (not applied yet)" : "Apply selected thinking effort";
}

function syncModelSelectToState() {
  if (!currentState?.model || !elements.modelSelect.options.length) return;
  const value = JSON.stringify({ provider: currentState.model.provider, modelId: currentState.model.id });
  if (controlsPendingModelValue && controlsPendingModelValue === value) setControlsPendingModel("");
  if (controlsPendingModelValue) return; // keep the user's unapplied choice visible
  for (const option of elements.modelSelect.options) {
    if (option.value === value) {
      elements.modelSelect.value = value;
      renderModelSearchResults(availableModels.filter((model) => !elements.modelSearchInput?.value.trim() || modelSelectOptionText(model).toLowerCase().includes(elements.modelSearchInput.value.trim().toLowerCase())));
      break;
    }
  }
}

function normalizedCommandIdentity(command) {
  return [commandBaseName(command.name), command.description, command.source, command.enabled ? "enabled" : "disabled"].join("\u0000");
}

function combineIdenticalDuplicateCommands(commands) {
  const duplicateGroups = new Map();
  for (const command of commands) {
    if (commandBaseName(command.name) === command.name) continue;
    const key = normalizedCommandIdentity(command);
    if (!duplicateGroups.has(key)) duplicateGroups.set(key, []);
    duplicateGroups.get(key).push(command);
  }
  const combinedKeys = new Set([...duplicateGroups.entries()].filter(([, group]) => group.length > 1).map(([key]) => key));
  const emittedKeys = new Set();
  const emittedNames = new Set();
  const result = [];

  for (const command of commands) {
    const key = normalizedCommandIdentity(command);
    if (!combinedKeys.has(key)) {
      if (emittedNames.has(command.name)) continue;
      emittedNames.add(command.name);
      result.push(command);
      continue;
    }

    if (emittedKeys.has(key)) continue;
    emittedKeys.add(key);
    const group = duplicateGroups.get(key);
    const baseName = commandBaseName(command.name);
    const displayName = emittedNames.has(baseName) ? command.name : baseName;
    emittedNames.add(displayName);
    result.push({
      ...command,
      name: displayName,
      invokeName: command.name,
      duplicateNames: group.map((item) => item.name),
      duplicateCount: group.length,
      location: command.location || `${group.length} identical loaded commands`,
    });
  }

  return result;
}

function normalizeCommands(commands, { dedupe = true } = {}) {
  const normalized = (commands || [])
    .map((command) => {
      const name = String(command.name || "").trim();
      return {
        name,
        invokeName: name,
        description: String(command.description || "").trim(),
        source: String(command.source || "command").trim(),
        location: String(command.location || "").trim(),
        enabled: command.enabled !== false,
      };
    })
    .filter((command) => command.name);

  return (dedupe ? combineIdenticalDuplicateCommands(normalized) : normalized)
    .sort((a, b) => a.name.localeCompare(b.name));
}

function commandSourceLabel(command) {
  return [command.source, command.location].filter(Boolean).join(" · ") || "command";
}

function normalizePathSuggestions(suggestions) {
  const seen = new Set();
  return (suggestions || [])
    .map((suggestion) => {
      const path = String(suggestion.path || "").trim();
      return {
        path,
        label: String(suggestion.label || path).trim(),
        description: String(suggestion.description || path).trim(),
        type: suggestion.type === "directory" || path.endsWith("/") ? "directory" : "file",
      };
    })
    .filter((suggestion) => {
      if (!suggestion.path || seen.has(suggestion.path)) return false;
      seen.add(suggestion.path);
      return true;
    });
}

function normalizeBangSuggestions(suggestions) {
  const seen = new Set();
  return (suggestions || [])
    .map((suggestion) => {
      const insertText = String(suggestion.insertText || suggestion.value || "").trim().replace(/^!+/, "");
      const label = String(suggestion.label || `!${insertText}`).trim();
      return {
        insertText,
        label,
        description: String(suggestion.description || "shell command").trim(),
        kind: String(suggestion.kind || "command").trim(),
      };
    })
    .filter((suggestion) => {
      if (!suggestion.insertText || seen.has(suggestion.insertText)) return false;
      seen.add(suggestion.insertText);
      return true;
    });
}

function getCommandTrigger() {
  const input = elements.promptInput;
  const cursor = input.selectionStart ?? input.value.length;
  const selectionEnd = input.selectionEnd ?? cursor;
  if (cursor !== selectionEnd) return null;

  const beforeCursor = input.value.slice(0, cursor);
  const match = beforeCursor.match(/(^|[\s(])\/([^\s]*)$/);
  if (!match) return null;

  const query = match[2] || "";
  // "/etc/hosts" or "/tmp/x.txt" mid-sentence is a path, not a slash command.
  if (query.includes("/")) return null;
  return {
    start: cursor - query.length - 1,
    end: cursor,
    query,
  };
}

function getPathTrigger() {
  const input = elements.promptInput;
  const cursor = input.selectionStart ?? input.value.length;
  const selectionEnd = input.selectionEnd ?? cursor;
  if (cursor !== selectionEnd) return null;

  const beforeCursor = input.value.slice(0, cursor);
  const quotedMatch = beforeCursor.match(/(^|[\s(])@"([^"]*)$/);
  if (quotedMatch) {
    const query = quotedMatch[2] || "";
    return { start: cursor - query.length - 2, end: cursor, query, quoted: true };
  }

  const match = beforeCursor.match(/(^|[\s(])@([^\s"']*)$/);
  if (!match) return null;
  const query = match[2] || "";
  return { start: cursor - query.length - 1, end: cursor, query, quoted: false };
}

function getBangTrigger() {
  const input = elements.promptInput;
  const cursor = input.selectionStart ?? input.value.length;
  const selectionEnd = input.selectionEnd ?? cursor;
  if (cursor !== selectionEnd) return null;

  const beforeCursor = input.value.slice(0, cursor);
  const match = beforeCursor.match(/^\s*(!!?)([^\n]*)$/);
  if (!match) return null;
  const afterBang = match[2] || "";
  const leadingSpaceLength = afterBang.match(/^\s*/)?.[0]?.length || 0;
  const query = afterBang.slice(leadingSpaceLength);
  return { start: cursor - query.length, end: cursor, query, bangPrefix: match[1] };
}

function scoreCommandSuggestion(command, query) {
  if (!query) return 0;
  const q = query.toLowerCase();
  const names = [command.name, command.invokeName, ...(command.duplicateNames || [])]
    .filter(Boolean)
    .map((name) => name.toLowerCase());
  const description = command.description.toLowerCase();
  if (names.some((name) => name === q)) return 0;
  if (names.some((name) => name.startsWith(q))) return 1;
  if (names.some((name) => name.includes(q))) return 2;
  if (description.includes(q)) return 3;
  return Number.POSITIVE_INFINITY;
}

function getCommandMatches(query) {
  return visibleCommands()
    .map((command) => ({ command, score: scoreCommandSuggestion(command, query) }))
    .filter((item) => Number.isFinite(item.score))
    .sort((a, b) => a.score - b.score || a.command.name.localeCompare(b.command.name))
    .slice(0, clampAutocompleteMaxVisible(autocompleteMaxVisible))
    .map((item) => item.command);
}

function commandSearchQuery() {
  return String(elements.commandSearchInput?.value || "").trim().replace(/^\/+/, "").toLowerCase();
}

function commandMatchesSearch(command, query) {
  if (!query) return true;
  return [command.name, command.invokeName, ...(command.duplicateNames || []), command.description, command.source, command.location]
    .filter(Boolean)
    .join(" ")
    .toLowerCase()
    .includes(query);
}

function activeSuggestionCount() {
  if (suggestionMode === "path") return pathSuggestions.length;
  if (suggestionMode === "bang") return bangSuggestions.length;
  return commandSuggestions.length;
}

function abortPathSuggestionRequest() {
  pathSuggestAbortController?.abort();
  pathSuggestAbortController = null;
}

function cancelPathSuggestionRequest() {
  pathSuggestRequestSerial++;
  pathSuggestActiveQuery = null;
  abortPathSuggestionRequest();
}

function abortBangSuggestionRequest() {
  bangSuggestAbortController?.abort();
  bangSuggestAbortController = null;
}

function cancelBangSuggestionRequest() {
  bangSuggestRequestSerial++;
  bangSuggestActiveQuery = null;
  abortBangSuggestionRequest();
}

function showCommandSuggestionList() {
  elements.commandSuggest.hidden = false;
  elements.promptInput?.setAttribute("aria-expanded", "true");
  const hasChoices = elements.commandSuggest.querySelector(".command-suggest-item") !== null;
  let hint = elements.commandSuggest.querySelector(".command-suggest-hint");
  if (hasChoices && !hint) {
    hint = make("div", "command-suggest-hint", "↑↓ navigate · Enter or Tab accept · Esc close");
    hint.setAttribute("aria-hidden", "true");
    elements.commandSuggest.append(hint);
  } else if (!hasChoices && hint) {
    hint.remove();
  }
}

function hideCommandSuggestions() {
  cancelPathSuggestionRequest();
  cancelBangSuggestionRequest();
  elements.commandSuggest.hidden = true;
  elements.promptInput?.setAttribute("aria-expanded", "false");
  elements.promptInput?.removeAttribute("aria-activedescendant");
  elements.commandSuggest.removeAttribute("aria-busy");
  elements.commandSuggest.replaceChildren();
  commandSuggestions = [];
  pathSuggestions = [];
  bangSuggestions = [];
  suggestionMode = "none";
  commandSuggestIndex = 0;
  scheduleDeferredUiFlushAfterDropdownClose();
}

function setActiveCommandSuggestion(index) {
  const count = activeSuggestionCount();
  if (!count) return;
  commandSuggestIndex = (index + count) % count;
  const items = [...elements.commandSuggest.querySelectorAll(".command-suggest-item")];
  for (const [itemIndex, item] of items.entries()) {
    const active = itemIndex === commandSuggestIndex;
    item.classList.toggle("active", active);
    item.setAttribute("aria-selected", active ? "true" : "false");
    if (active) {
      elements.promptInput?.setAttribute("aria-activedescendant", item.id);
      item.scrollIntoView({ block: "nearest" });
    }
  }
}

function pointerPositionFromEvent(event) {
  if (!Number.isFinite(event.clientX) || !Number.isFinite(event.clientY)) return null;
  return { x: event.clientX, y: event.clientY };
}

function rememberPointerPosition(event) {
  lastPointerPosition = pointerPositionFromEvent(event);
}

function commandSuggestionPointerActuallyMoved(event) {
  const movementX = Number.isFinite(event.movementX) ? event.movementX : 0;
  const movementY = Number.isFinite(event.movementY) ? event.movementY : 0;
  if (movementX !== 0 || movementY !== 0) return true;

  const position = pointerPositionFromEvent(event);
  return Boolean(
    position &&
      lastPointerPosition &&
      (position.x !== lastPointerPosition.x || position.y !== lastPointerPosition.y),
  );
}

function setActiveCommandSuggestionFromPointerMove(index, event) {
  if (!commandSuggestionPointerActuallyMoved(event)) return;
  setActiveCommandSuggestion(index);
}

function renderCommandSuggestionItems(trigger, { keepIndex = false } = {}) {
  suggestionMode = "command";
  pathSuggestions = [];
  bangSuggestions = [];
  commandSuggestions = getCommandMatches(trigger.query);
  elements.commandSuggest.replaceChildren();

  if (commandSuggestions.length === 0) {
    elements.commandSuggest.append(make("div", "command-suggest-empty", `No command matches /${trigger.query}`));
    showCommandSuggestionList();
    return;
  }

  for (const [index, command] of commandSuggestions.entries()) {
    const item = make("button", "command-suggest-item");
    item.type = "button";
    item.id = `composer-suggestion-command-${encodeURIComponent(command.name).replace(/%/g, "-")}`;
    item.setAttribute("role", "option");
    item.addEventListener("mousedown", (event) => event.preventDefault());
    item.addEventListener("pointermove", (event) => setActiveCommandSuggestionFromPointerMove(index, event));
    item.addEventListener("click", () => insertCommandSuggestion(index));

    item.append(
      make("span", "command-suggest-name", `/${command.name}`),
      make("span", "command-suggest-desc", command.description || "No description"),
      make("span", "command-suggest-source", commandSourceLabel(command)),
    );
    elements.commandSuggest.append(item);
  }

  showCommandSuggestionList();
  elements.promptInput?.setAttribute("aria-expanded", "true");
  setActiveCommandSuggestion(keepIndex ? commandSuggestIndex : 0);
}

function pathSuggestionIsDirectory(suggestion) {
  return suggestion.type === "directory" || suggestion.path.endsWith("/");
}

function formatPathReference(pathText, forceQuoted = false) {
  const normalized = String(pathText || "").replace(/\\/g, "/");
  if (!forceQuoted && !/[\s"']/.test(normalized)) return `@${normalized}`;
  return `@"${normalized.replace(/(["\\])/g, "\\$1")}"`;
}

function renderPathSuggestionItems(trigger, { keepIndex = false } = {}) {
  suggestionMode = "path";
  commandSuggestions = [];
  bangSuggestions = [];
  elements.commandSuggest.replaceChildren();

  if (pathSuggestions.length === 0) {
    elements.commandSuggest.append(make("div", "command-suggest-empty", `No path matches @${trigger.query}`));
    showCommandSuggestionList();
    return;
  }

  for (const [index, suggestion] of pathSuggestions.entries()) {
    const isDirectory = pathSuggestionIsDirectory(suggestion);
    const item = make("button", `command-suggest-item path-suggest-item ${isDirectory ? "directory" : "file"}`);
    item.type = "button";
    item.id = `composer-suggestion-path-${index}-${encodeURIComponent(suggestion.path).replace(/%/g, "-")}`;
    item.setAttribute("role", "option");
    item.addEventListener("mousedown", (event) => event.preventDefault());
    item.addEventListener("pointermove", (event) => setActiveCommandSuggestionFromPointerMove(index, event));
    item.addEventListener("click", () => insertPathSuggestion(index));

    item.append(
      make("span", "command-suggest-name path-suggest-name", `@${suggestion.path}`),
      make("span", "command-suggest-desc", suggestion.description || suggestion.path),
      make("span", "command-suggest-source", isDirectory ? "directory" : "file"),
    );
    elements.commandSuggest.append(item);
  }

  showCommandSuggestionList();
  setActiveCommandSuggestion(keepIndex ? commandSuggestIndex : 0);
}

async function renderPathSuggestions(trigger, { keepIndex = false } = {}) {
  cancelBangSuggestionRequest();
  if (suggestionMode === "path" && pathSuggestActiveQuery === trigger.query && !elements.commandSuggest.hidden) {
    if (keepIndex && activeSuggestionCount() > 0) setActiveCommandSuggestion(commandSuggestIndex);
    return;
  }

  const keepExistingPathMenu = suggestionMode === "path" && !elements.commandSuggest.hidden && elements.commandSuggest.childElementCount > 0;
  abortPathSuggestionRequest();
  const requestSerial = ++pathSuggestRequestSerial;
  const controller = new AbortController();
  pathSuggestActiveQuery = trigger.query;
  pathSuggestAbortController = controller;
  suggestionMode = "path";
  commandSuggestions = [];
  if (!keepExistingPathMenu) {
    pathSuggestions = [];
    elements.commandSuggest.replaceChildren(make("div", "command-suggest-empty", "Finding paths…"));
  }
  showCommandSuggestionList();
  elements.commandSuggest.setAttribute("aria-busy", "true");

  try {
    // Debounce keystrokes: one directory scan per pause instead of one per character.
    await new Promise((resolve) => setTimeout(resolve, PATH_SUGGEST_DEBOUNCE_MS));
    if (requestSerial !== pathSuggestRequestSerial || controller.signal.aborted) return;
    const response = await api(`/api/path-suggestions?query=${encodeURIComponent(trigger.query)}`, { signal: controller.signal });
    if (requestSerial !== pathSuggestRequestSerial || document.activeElement !== elements.promptInput) return;
    pathSuggestions = normalizePathSuggestions(response.data?.suggestions || []);
    renderPathSuggestionItems(trigger, { keepIndex });
  } catch (error) {
    if (error?.name === "AbortError" || requestSerial !== pathSuggestRequestSerial) return;
    pathSuggestions = [];
    elements.commandSuggest.replaceChildren(make("div", "command-suggest-empty", `Path suggestions unavailable: ${error.message}`));
    showCommandSuggestionList();
  } finally {
    if (requestSerial === pathSuggestRequestSerial) {
      pathSuggestAbortController = null;
      elements.commandSuggest.removeAttribute("aria-busy");
    }
  }
}

function renderBangSuggestionItems(trigger, { keepIndex = false } = {}) {
  suggestionMode = "bang";
  commandSuggestions = [];
  pathSuggestions = [];
  elements.commandSuggest.replaceChildren();

  if (bangSuggestions.length === 0) {
    elements.commandSuggest.append(make("div", "command-suggest-empty", `No shell command matches !${trigger.query}`));
    showCommandSuggestionList();
    return;
  }

  for (const [index, suggestion] of bangSuggestions.entries()) {
    const item = make("button", "command-suggest-item bang-suggest-item");
    item.type = "button";
    item.id = `composer-suggestion-bang-${index}-${encodeURIComponent(suggestion.insertText).replace(/%/g, "-")}`;
    item.setAttribute("role", "option");
    item.addEventListener("mousedown", (event) => event.preventDefault());
    item.addEventListener("pointermove", (event) => setActiveCommandSuggestionFromPointerMove(index, event));
    item.addEventListener("click", () => insertBangSuggestion(index));

    item.append(
      make("span", "command-suggest-name bang-suggest-name", suggestion.label || `!${suggestion.insertText}`),
      make("span", "command-suggest-desc", suggestion.description || "shell command"),
      make("span", "command-suggest-source", suggestion.kind || "command"),
    );
    elements.commandSuggest.append(item);
  }

  showCommandSuggestionList();
  setActiveCommandSuggestion(keepIndex ? commandSuggestIndex : 0);
}

async function renderBangSuggestions(trigger, { keepIndex = false } = {}) {
  cancelPathSuggestionRequest();
  const activeQuery = `${trigger.bangPrefix}\0${trigger.query}`;
  if (suggestionMode === "bang" && bangSuggestActiveQuery === activeQuery && !elements.commandSuggest.hidden) {
    if (keepIndex && activeSuggestionCount() > 0) setActiveCommandSuggestion(commandSuggestIndex);
    return;
  }

  const keepExistingBangMenu = suggestionMode === "bang" && !elements.commandSuggest.hidden && elements.commandSuggest.childElementCount > 0;
  abortBangSuggestionRequest();
  const requestSerial = ++bangSuggestRequestSerial;
  const controller = new AbortController();
  bangSuggestActiveQuery = activeQuery;
  bangSuggestAbortController = controller;
  suggestionMode = "bang";
  commandSuggestions = [];
  pathSuggestions = [];
  if (!keepExistingBangMenu) {
    bangSuggestions = [];
    elements.commandSuggest.replaceChildren(make("div", "command-suggest-empty", "Finding shell commands…"));
  }
  showCommandSuggestionList();
  elements.commandSuggest.setAttribute("aria-busy", "true");

  try {
    const response = await api(`/api/bang-suggestions?query=${encodeURIComponent(trigger.query)}`, { signal: controller.signal });
    if (requestSerial !== bangSuggestRequestSerial || document.activeElement !== elements.promptInput) return;
    bangSuggestions = normalizeBangSuggestions(response.data?.suggestions || []);
    renderBangSuggestionItems(trigger, { keepIndex });
  } catch (error) {
    if (error?.name === "AbortError" || requestSerial !== bangSuggestRequestSerial) return;
    bangSuggestions = [];
    elements.commandSuggest.replaceChildren(make("div", "command-suggest-empty", `Shell command suggestions unavailable: ${error.message}`));
    showCommandSuggestionList();
  } finally {
    if (requestSerial === bangSuggestRequestSerial) {
      bangSuggestAbortController = null;
      elements.commandSuggest.removeAttribute("aria-busy");
    }
  }
}

function renderCommandSuggestions({ keepIndex = false } = {}) {
  if (document.activeElement !== elements.promptInput) {
    hideCommandSuggestions();
    return;
  }

  const bangTrigger = getBangTrigger();
  if (bangTrigger) {
    if (isOptionalFeatureEnabled("bangCommandAutocomplete")) renderBangSuggestions(bangTrigger, { keepIndex });
    else hideCommandSuggestions();
    return;
  }

  const pathTrigger = getPathTrigger();
  if (pathTrigger) {
    renderPathSuggestions(pathTrigger, { keepIndex });
    return;
  }

  cancelPathSuggestionRequest();
  cancelBangSuggestionRequest();
  const trigger = getCommandTrigger();
  if (!trigger || availableCommands.length === 0) {
    hideCommandSuggestions();
    return;
  }

  renderCommandSuggestionItems(trigger, { keepIndex });
}

function insertCommandSuggestion(index = commandSuggestIndex) {
  if (suggestionMode === "path") return insertPathSuggestion(index);
  if (suggestionMode === "bang") return insertBangSuggestion(index);
  const command = commandSuggestions[index];
  const trigger = getCommandTrigger();
  if (!command || !trigger) return false;

  const input = elements.promptInput;
  const value = input.value;
  let tokenEnd = trigger.end;
  while (tokenEnd < value.length && !/\s/.test(value[tokenEnd])) tokenEnd++;

  const commandText = `/${command.name}`;
  const suffix = value.slice(tokenEnd);
  const separator = suffix && /^\s/.test(suffix) ? "" : " ";
  input.value = `${value.slice(0, trigger.start)}${commandText}${separator}${suffix}`;

  const whitespaceOffset = separator ? 1 : suffix && /^\s/.test(suffix) ? 1 : 0;
  const cursor = trigger.start + commandText.length + whitespaceOffset;
  input.setSelectionRange(cursor, cursor);
  input.focus();
  hideCommandSuggestions();
  return true;
}

function insertBangSuggestion(index = commandSuggestIndex) {
  const suggestion = bangSuggestions[index];
  const trigger = getBangTrigger();
  if (!suggestion || !trigger) return false;

  const input = elements.promptInput;
  const value = input.value;
  const suffix = value.slice(trigger.end);
  const commandText = suggestion.insertText.replace(/^!+/, "");
  const separator = suggestion.kind === "line" || (suffix && /^\s/.test(suffix)) ? "" : " ";
  input.value = `${value.slice(0, trigger.start)}${commandText}${separator}${suffix}`;

  const cursor = trigger.start + commandText.length + separator.length;
  input.setSelectionRange(cursor, cursor);
  input.focus();
  resizePromptInput();
  hideCommandSuggestions();
  return true;
}

function insertPathSuggestion(index = commandSuggestIndex) {
  const suggestion = pathSuggestions[index];
  const trigger = getPathTrigger();
  if (!suggestion || !trigger) return false;

  const input = elements.promptInput;
  const value = input.value;
  let tokenEnd = trigger.end;
  if (trigger.quoted) {
    while (tokenEnd < value.length && value[tokenEnd] !== '"') tokenEnd++;
    if (value[tokenEnd] === '"') tokenEnd++;
  } else {
    while (tokenEnd < value.length && !/\s/.test(value[tokenEnd])) tokenEnd++;
  }

  const isDirectory = pathSuggestionIsDirectory(suggestion);
  const reference = formatPathReference(suggestion.path, trigger.quoted);
  const suffix = value.slice(tokenEnd);
  const separator = isDirectory || (suffix && /^\s/.test(suffix)) ? "" : " ";
  input.value = `${value.slice(0, trigger.start)}${reference}${separator}${suffix}`;

  const cursorOffset = isDirectory && reference.endsWith('"') ? reference.length - 1 : reference.length + separator.length;
  const cursor = trigger.start + cursorOffset;
  input.setSelectionRange(cursor, cursor);
  input.focus();
  resizePromptInput();
  if (isDirectory) renderCommandSuggestions();
  else hideCommandSuggestions();
  return true;
}

function renderCommands() {
  elements.commandsBox.replaceChildren();
  if (!availableCommands.length) {
    elements.commandsBox.textContent = "No RPC-visible commands.";
    elements.commandsBox.classList.add("muted");
    hideCommandSuggestions();
    return;
  }
  const commandsToShow = visibleCommands();
  if (!commandsToShow.length) {
    elements.commandsBox.textContent = "No enabled commands visible. Re-enable optional features to show their commands.";
    elements.commandsBox.classList.add("muted");
    hideCommandSuggestions();
    return;
  }
  const searchQuery = commandSearchQuery();
  const filteredCommands = commandsToShow.filter((command) => commandMatchesSearch(command, searchQuery));
  if (!filteredCommands.length) {
    elements.commandsBox.textContent = `No commands match “${elements.commandSearchInput?.value.trim() || searchQuery}”.`;
    elements.commandsBox.classList.add("muted");
    renderCommandSuggestions();
    return;
  }
  elements.commandsBox.classList.remove("muted");
  for (const command of filteredCommands.slice(0, 80)) {
    const item = make("button", "command-item");
    item.type = "button";
    item.title = `Send /${command.name}`;
    item.setAttribute("aria-label", `Send /${command.name}${command.description ? `: ${command.description}` : ""}`);
    item.addEventListener("click", () => sendPrompt("prompt", `/${command.name}`));

    const code = make("code", undefined, `/${command.name}`);
    item.append(code);
    if (command.description) item.append(document.createTextNode(` — ${command.description}`));
    elements.commandsBox.append(item);
  }
  renderCommandSuggestions();
}

async function refreshCommands(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  const response = await api("/api/commands", { tabId: tabContext.tabId });
  if (!tabs.some((tab) => tab.id === tabContext.tabId)) return;
  const catalog = {
    raw: normalizeCommands(response.data?.commands || [], { dedupe: false }),
    available: normalizeCommands(response.data?.commands || []),
  };
  // Keep results for their originating tab even when the active tab changed
  // while this request was in flight. Guided Git must never borrow another
  // tab's extension availability or duplicate-command alias.
  const previousCatalog = commandCatalogsByTab.get(tabContext.tabId);
  commandCatalogsByTab.set(tabContext.tabId, catalog);
  if (tabsSnapshotSignature(previousCatalog) !== tabsSnapshotSignature(catalog)) scheduleTabsRender();
  if (!isCurrentTabContext(tabContext)) return;
  rawAvailableCommands = catalog.raw;
  availableCommands = catalog.available;
  updateOptionalFeatureAvailability();
  renderSessionSummaryControls();
  renderCommands();
  if (elements.commandPaletteDialog?.open) renderCommandPalette({ preserveScroll: true });
}

function paletteText(value) {
  return String(value || "").toLowerCase();
}

function paletteItemMatches(item, query) {
  const text = [item.label, item.description, item.kind, item.keywords].map(paletteText).join(" ");
  return query.split(/\s+/).filter(Boolean).every((token) => text.includes(token));
}

function commandPaletteCoreItems() {
  const items = [
    { kind: "Action", label: "New tab", description: "Start an isolated Pi terminal in the current directory", keywords: "workspace session", run: () => createTerminalTab() },
    { kind: "Action", label: "Choose directory for new tab", description: "Pick a cwd before starting a tab", keywords: "cwd folder workspace", run: () => createTerminalTabFromChosenDirectory({ triggerButton: elements.commandPaletteButton }) },
    { kind: "Git", label: "Branch worktree", description: "Create or open a Git worktree tab for parallel branch work", keywords: "git branch worktree parallel checkout", run: () => openBranchWorktreePicker() },
    { kind: "Action", label: "New session", description: "Start a fresh session in the active tab", keywords: "/new clear", run: () => elements.newSessionButton.click() },
    { kind: "Action", label: "Compact context", description: contextUsageDetail(), keywords: "/compact context window tokens", run: () => requestManualCompaction() },
    { kind: "Action", label: footerAutoCompactionEnabled() ? "Disable auto-compaction" : "Enable auto-compaction", description: footerAutoCompactionToggleAction(), keywords: "context automatic", run: () => toggleFooterAutoCompaction() },
    { kind: "Action", label: workspaceDashboardCollapsed ? "Show workspace dashboard" : "Hide workspace dashboard", description: "Toggle the launch/workspace overview", keywords: "home overview", run: () => setWorkspaceDashboardCollapsed(!workspaceDashboardCollapsed) },
    { kind: "Action", label: document.body.classList.contains("side-panel-collapsed") ? "Show side panel" : "Hide side panel", description: "Toggle the Control Deck", keywords: "controls settings", run: () => setSidePanelCollapsed(!document.body.classList.contains("side-panel-collapsed"), { focusPanel: true }) },
    { kind: "Action", label: "Change working directory", description: "Restart active tab in another cwd", keywords: "cwd folder workspace", run: () => changeActiveTabCwd() },
    { kind: "Action", label: "Search transcript", description: "Open transcript search", keywords: "find", run: () => openChatSearch() },
    { kind: "Pi", label: "/model", description: "Select the active model", keywords: "provider llm", run: () => runNativeCommandMenu("/model") },
    { kind: "Pi", label: "/resume", description: "Resume a previous session", keywords: "sessions history", run: () => runNativeCommandMenu("/resume") },
    { kind: "Pi", label: "/fork", description: "Fork from a previous user message", keywords: "branch edit retry", run: () => runNativeCommandMenu("/fork") },
    { kind: "Pi", label: "/tree", description: "Navigate the session tree", keywords: "branch history", run: () => runNativeCommandMenu("/tree") },
    { kind: "Pi", label: "/settings", description: "Open settings", keywords: "configuration", run: () => runNativeCommandMenu("/settings") },
    { kind: "Pi", label: "/scoped-models", description: "Manage model cycling scope", keywords: "models cycle ctrl p", run: () => runNativeCommandMenu("/scoped-models") },
    { kind: "Pi", label: "/tools", description: "Manage active tools", keywords: "capabilities", run: () => runNativeCommandMenu("/tools") },
    { kind: "Pi", label: "/skills", description: "Manage active skills", keywords: "system prompt", run: () => runNativeCommandMenu("/skills") },
    { kind: "Pi", label: "/append-system", description: "Choose the APPEND_SYSTEM.md append prompt", keywords: "append system prompt settings global", run: () => openNativeAppendSystemSelector() },
    { kind: "Pi", label: "/theme", description: "Choose the Web UI theme", keywords: "dark light colors appearance", run: () => openNativeThemeSelector() },
    { kind: "Git", label: "Guided Git workflow", description: "Stage, commit, push, or open a pull request step by step", keywords: "git commit push pr publish", run: () => launchGuidedGitWorkflow() },
    { kind: "Git", label: "Git changes", description: "Review and stage local changes with diffs", keywords: "git diff stage unstage discard status", run: () => openGitChangesDialog() },
    { kind: "Action", label: "Files panel", description: "Open the Files section of the Control Deck", keywords: "tree browse project explorer", run: () => revealSidePanelSectionById("files") },
    { kind: "Action", label: "Git panel", description: "Open the Git section of the Control Deck", keywords: "repository status history", run: () => revealSidePanelSectionById("git") },
    { kind: "Action", label: "Events log", description: "Open the Events section of the Control Deck", keywords: "errors warnings log diagnostics", run: () => revealEventsSection() },
    { kind: "Action", label: thinkingOutputVisible ? "Hide thinking output" : "Show thinking output", description: "Toggle thinking cards in the transcript (Ctrl/Cmd+T in the composer)", keywords: "reasoning thinking toggle", run: () => setThinkingOutputVisible(!thinkingOutputVisible, { announce: true }) },
    { kind: "Action", label: toolOutputGloballyExpanded ? "Collapse tool output" : "Expand tool output", description: "Toggle tool result cards (Ctrl/Cmd+O in the composer)", keywords: "tools results collapse expand", run: () => setToolOutputGloballyExpanded(!toolOutputGloballyExpanded, { announce: true }) },
    { kind: "Action", label: "Show all controls", description: "Restore every hidden button and input tag", keywords: "visibility hidden restore controls buttons", run: () => showAllControls() },
    { kind: "Action", label: "Reset control visibility", description: "Return hidden/visible controls to the defaults", keywords: "visibility defaults controls buttons", run: () => resetControlVisibilityDefaults() },
  ];
  if (tabs.length) {
    items.push({ kind: "Workspace", label: "Workspace: Save", description: "Capture all open tabs, sessions, groups, and the active tab", keywords: "workspace snapshot save sessions groups", run: () => saveWebuiWorkspace({ triggerButton: elements.commandPaletteButton }) });
  }
  items.push({ kind: "Workspace", label: "Workspace: Load…", description: tabs.length ? "Choose a saved workspace and decide whether to save current tabs" : "Show saved workspaces to restore", keywords: "workspace restore saved sessions groups", run: () => openWorkspaceLoadPicker({ triggerButton: elements.commandPaletteButton }) });
  if (isOptionalFeatureEnabled("statsCommand")) items.push({ kind: "Pi", label: "/stats-webui", description: "Open usage dashboard", keywords: "tokens cost budget", run: () => openStatsOverlay({ refresh: true }) });
  return items;
}

function commandPaletteTabItems() {
  return tabs.map((tab) => {
    const indicator = tabIndicator(tab);
    return {
      kind: "Tab",
      label: tab.id === activeTabId ? `Current tab: ${tab.title}` : `Switch to tab: ${tab.title}`,
      description: `${indicator.label} · ${normalizeDisplayPath(tab.cwd || "")}`,
      keywords: `${tab.id} ${tab.cwd || ""}`,
      run: () => switchTab(tab.id),
    };
  });
}

function commandPaletteModelItems() {
  return availableModels.map((model) => ({
    kind: "Model",
    label: `${model.provider}/${model.id}`,
    description: model.name || (model.contextWindow ? `context ${formatFooterTokenCount(model.contextWindow)}` : "Set active model"),
    keywords: `${model.provider} ${model.id} ${model.name || ""}`,
    run: async () => {
      const tabContext = activeTabContext();
      const response = await api("/api/model", { method: "POST", body: { provider: model.provider, modelId: model.id }, tabId: tabContext.tabId });
      if (!isCurrentTabContext(tabContext)) return;
      applyOptimisticModelSelection(response.data || model, tabContext);
      await refreshState(tabContext);
      await refreshModels(tabContext);
    },
  }));
}

function commandPaletteSlashItems() {
  return visibleCommands().slice(0, 140).map((command) => ({
    kind: command.source || "Command",
    label: `/${command.name}`,
    description: command.description || "Run slash command",
    keywords: `${command.location || ""} ${command.path || ""}`,
    run: () => sendPrompt("prompt", `/${command.name}`),
  }));
}

function buildCommandPaletteItems() {
  return [
    ...commandPaletteCoreItems(),
    ...commandPaletteTabItems(),
    ...commandPaletteModelItems(),
    ...commandPaletteSlashItems(),
  ];
}

// Ranking: label prefix > label word-start > label contains > description/keywords only.
// Ties keep catalog order (actions, tabs, models, commands), so results stay predictable.
function paletteItemScore(item, query) {
  const label = paletteText(item.label);
  const tokens = query.split(/\s+/).filter(Boolean);
  let score = 0;
  for (const token of tokens) {
    if (label.startsWith(token)) score += 40;
    else if (label.replace(/^\//, "").startsWith(token)) score += 36;
    else if (new RegExp(`(^|[\\s/_-])${token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`).test(label)) score += 24;
    else if (label.includes(token)) score += 12;
    else score += 1;
  }
  return score;
}

function filteredCommandPaletteItems() {
  const query = paletteText(elements.commandPaletteInput?.value || "").trim();
  const items = buildCommandPaletteItems();
  if (!query) return items.slice(0, 80);
  return items
    .map((item, index) => ({ item, index, score: paletteItemMatches(item, query) ? paletteItemScore(item, query) : -1 }))
    .filter((entry) => entry.score >= 0)
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, 80)
    .map((entry) => entry.item);
}

function setCommandPaletteIndex(index) {
  const count = commandPaletteItems.length;
  commandPaletteIndex = count ? (index + count) % count : 0;
  renderCommandPaletteList();
}

function renderCommandPaletteList({ preserveScroll = false } = {}) {
  const list = elements.commandPaletteList;
  if (!list) return;
  const scrollTop = preserveScroll ? list.scrollTop : 0;
  list.replaceChildren();
  if (!commandPaletteItems.length) {
    list.append(make("div", "command-palette-empty muted", "No matching actions."));
    elements.commandPaletteInput?.removeAttribute("aria-activedescendant");
    if (preserveScroll) list.scrollTop = scrollTop;
    return;
  }
  commandPaletteItems.forEach((item, index) => {
    const button = make("button", `command-palette-item${index === commandPaletteIndex ? " active" : ""}`);
    button.type = "button";
    button.id = `command-palette-option-${encodeURIComponent(`${item.kind}-${item.label}`).replace(/%/g, "-")}`;
    button.setAttribute("role", "option");
    button.setAttribute("aria-selected", index === commandPaletteIndex ? "true" : "false");
    button.addEventListener("click", () => executeCommandPaletteItem(item));
    button.append(
      make("span", "command-palette-item-kind", item.kind || "Action"),
      make("span", "command-palette-item-label", item.label || "Untitled action"),
      make("span", "command-palette-item-description", item.description || ""),
    );
    list.append(button);
  });
  const active = list.children[commandPaletteIndex];
  if (active?.id) elements.commandPaletteInput?.setAttribute("aria-activedescendant", active.id);
  if (preserveScroll) {
    list.scrollTop = scrollTop;
    return;
  }
  active?.scrollIntoView({ block: "nearest" });
}

function renderCommandPalette({ preserveScroll = false } = {}) {
  commandPaletteItems = filteredCommandPaletteItems();
  if (commandPaletteIndex >= commandPaletteItems.length) commandPaletteIndex = 0;
  renderCommandPaletteList({ preserveScroll });
}

function openCommandPalette(initialQuery = "") {
  setComposerActionsOpen(false);
  setPublishMenuOpen(false);
  setNativeCommandMenuOpen(false);
  setAppRunnerMenuOpen(false);
  setOptionsMenuOpen(false);
  if (elements.commandPaletteInput) elements.commandPaletteInput.value = initialQuery;
  commandPaletteIndex = 0;
  renderCommandPalette();
  if (!elements.commandPaletteDialog.open) elements.commandPaletteDialog.showModal();
  queueMicrotask(() => {
    elements.commandPaletteInput?.focus();
    elements.commandPaletteInput?.select();
  });
}

function closeCommandPalette() {
  if (elements.commandPaletteDialog?.open) elements.commandPaletteDialog.close();
}

async function executeCommandPaletteItem(item = commandPaletteItems[commandPaletteIndex]) {
  if (!item) return;
  closeCommandPalette();
  try {
    await item.run?.();
  } catch (error) {
    addEvent(error.message || String(error), "error");
  }
}

function supplementalRefreshRequests(tabContext) {
  return [
    refreshModels(tabContext),
    refreshCommands(tabContext),
    refreshNaturalConversationMode(tabContext),
    refreshCodexFastMode(tabContext),
    refreshStats(tabContext),
    refreshWorkspace(tabContext),
    refreshFileTreeRoot(tabContext),
    refreshAppRunners(tabContext),
    refreshNativeSettings(tabContext),
    refreshNetworkStatus(),
    refreshWebuiVersion(),
  ];
}

function reportRefreshFailures(results, prefix = "") {
  for (const result of results) {
    if (result.status !== "rejected") continue;
    addEvent(`${prefix}${result.reason?.message || String(result.reason)}`, "error");
  }
}

async function refreshAll(tabContext = activeTabContext()) {
  if (!tabContext.tabId) return;
  noteRecentFullRefresh();
  const results = await Promise.allSettled([
    refreshState(tabContext),
    refreshMessages(tabContext),
    refreshIntercomConversationSummaries(tabContext),
    ...supplementalRefreshRequests(tabContext),
  ]);
  if (!isCurrentTabContext(tabContext)) return;
  reportRefreshFailures(results);
  resumeGitWorkflowForActiveTab(tabContext);
}

function scheduleForegroundSupplementalRefresh(tabContext) {
  foregroundSupplementalRefreshCancel?.();
  const run = async () => {
    foregroundSupplementalRefreshCancel = null;
    if (document.visibilityState === "hidden" || !isCurrentTabContext(tabContext)) return;
    const results = await Promise.allSettled(supplementalRefreshRequests(tabContext));
    if (!isCurrentTabContext(tabContext)) return;
    reportRefreshFailures(results, "foreground refresh failed: ");
    resumeGitWorkflowForActiveTab(tabContext);
  };
  if (typeof globalThis.requestIdleCallback === "function") {
    const handle = globalThis.requestIdleCallback(run, { timeout: 1_200 });
    foregroundSupplementalRefreshCancel = () => globalThis.cancelIdleCallback?.(handle);
  } else {
    const handle = setTimeout(run, 250);
    foregroundSupplementalRefreshCancel = () => clearTimeout(handle);
  }
}

function ensureActiveEventStream(tabContext = activeTabContext()) {
  if (!tabContext.tabId || !isCurrentTabContext(tabContext)) return;
  if (!eventSource || eventSource.readyState === EventSource.CLOSED) connectEvents(tabContext);
}

async function reconcileForegroundState(reason = "resume") {
  if (document.visibilityState === "hidden") return;

  const wasAway = mobileConnectionState === "away";
  const transcriptCatchUpRequired = foregroundTranscriptCatchUpRequired;
  mobileConnectionState = navigator.onLine === false ? "offline" : "reconnecting";
  mobileConnectionLabel = mobileConnectionState === "offline" ? "Paused/offline" : "Reconnecting";
  recordMobileDiagnostic("foreground reconcile", reason);
  renderMobilePhoneExperience();
  const tabResult = await Promise.allSettled([refreshTabs()]);
  const tabContext = activeTabContext();

  const results = [...tabResult];
  if (tabContext.tabId && transcriptCatchUpRequired) {
    const criticalResults = await Promise.allSettled([
      refreshState(tabContext),
      refreshMessages(tabContext, { authoritative: true }),
    ]);
    results.push(...criticalResults);
    if (isCurrentTabContext(tabContext)) {
      if (foregroundTranscriptSuppressedEvents > 0) {
        recordMobileDiagnostic("foreground output coalesced", `${foregroundTranscriptSuppressedEvents} raw transcript updates replaced by one authoritative snapshot`);
      }
      backgroundReconnectSnapshotFresh = ![...tabResult, ...criticalResults].some((result) => result.status === "rejected");
      foregroundTranscriptCatchUpRequired = false;
      foregroundTranscriptSuppressedEvents = 0;
      ensureActiveEventStream(tabContext);
      scheduleForegroundSupplementalRefresh(tabContext);
    }
  } else if (tabContext.tabId) {
    ensureActiveEventStream(tabContext);
    results.push(...(await Promise.allSettled([refreshAll(tabContext)])));
  }
  if (!isCurrentTabContext(tabContext)) return;

  const failed = results.some((result) => result.status === "rejected");
  for (const result of results) {
    if (result.status === "rejected") addEvent(`foreground refresh failed after ${reason}: ${result.reason?.message || String(result.reason)}`, "error");
  }
  if (failed || backendOffline || navigator.onLine === false) {
    mobileConnectionState = "offline";
    mobileConnectionLabel = "Paused/offline";
  } else {
    mobileConnectionState = "online";
    mobileConnectionLabel = wasAway ? "Continued while away · reconciled" : "Online · reconciled";
    clearTimeout(mobileConnectionLabelResetTimer);
    mobileConnectionLabelResetTimer = setTimeout(() => {
      if (mobileConnectionState !== "online") return;
      mobileConnectionLabel = "Online";
      renderMobilePhoneExperience();
    }, 45_000);
    await applyPendingMobileNavigationTarget();
  }
  renderMobilePhoneExperience();
}

// A tab activation/boot just ran the full refresh; the immediately following "event stream
// reconnect" and "page show" signals would otherwise repeat every catalog fetch a second time.
let recentFullRefreshFreshUntil = 0;

function noteRecentFullRefresh() {
  recentFullRefreshFreshUntil = performance.now() + 3_000;
}

function scheduleForegroundReconcile(reason = "resume", delay = FOREGROUND_RECONCILE_DELAY_MS) {
  if ((reason === "event stream reconnect" || reason === "page show") && performance.now() < recentFullRefreshFreshUntil && !foregroundTranscriptCatchUpRequired) return;
  clearTimeout(foregroundReconcileTimer);
  foregroundReconcileTimer = setTimeout(() => {
    foregroundReconcileTimer = null;
    reconcileForegroundState(reason).catch((error) => addEvent(`foreground refresh failed after ${reason}: ${error.message || String(error)}`, "error"));
  }, delay);
}

async function openToNetwork() {
  const open = !!latestNetwork?.open;
  if (!open) {
    const localUrl = latestNetwork?.localUrl || `${window.location.origin}/`;
    let interfaceName = "all network interfaces";
    let port = DEFAULT_WEBUI_PORT;
    try {
      const parsed = new URL(localUrl);
      port = parsed.port || (parsed.protocol === "https:" ? "443" : "80");
    } catch {
      // Keep explicit fallback values in the confirmation.
    }
    const confirmed = await appConfirm({
      title: "Open for remote access?",
      summary: "This changes Pi Web UI from local-only to reachable by devices on your network.",
      affected: `${interfaceName}, port ${port}, ${latestNetwork?.auth?.enabled ? "PIN authentication enabled" : "PIN authentication disabled"}`,
      undoable: true,
      confirmLabel: "Open remote access",
    });
    if (!confirmed) return;
  }
  elements.openNetworkButton.disabled = true;
  elements.openNetworkButton.textContent = open ? "Closing…" : "Opening…";
  try {
    await runRemoteWebuiCommand(remoteWebuiCommand(open ? "close" : "open", open ? "/remote close" : "/remote"));
    await delay(350);
    await refreshNetworkStatus();
    if (!open && latestNetwork?.open) {
      offerUndo({
        message: "Remote access is open.",
        undo: async () => {
          await runRemoteWebuiCommand(remoteWebuiCommand("close", "/remote close"));
          await delay(350);
          await refreshNetworkStatus();
          renderNetworkStatus();
        },
        successMessage: "Remote access closed; Pi Web UI is local-only again.",
      });
    }
  } catch (error) {
    addEvent(error.message || String(error), "error");
  } finally {
    renderNetworkStatus();
  }
}

async function closeNetworkAccess() {
  if (!latestNetwork?.open) return;
  await openToNetwork();
}

function setServerActionStatus(message = "", level = "info") {
  const status = elements.serverActionStatus;
  if (!status) return;
  status.textContent = message;
  status.hidden = !message;
  status.className = `server-action-status ${level} ${message ? "" : "muted"}`.trim();
}

function updateServerActionButton() {
  const action = elements.serverActionSelect?.value || "";
  const button = elements.runServerActionButton;
  if (!button) return;
  button.disabled = !action;
  button.textContent = action === "restart" ? "Restart" : action === "update" || action === "update-webui" ? "Update" : action === "stop" ? "Stop" : "Run";
  button.classList.toggle("danger", action === "stop");
  if (action === "restart") setServerActionStatus("Ready to restart the Web UI server.", "info");
  else if (action === "update") setServerActionStatus("Ready to preview the verified PATH Pi update.", "info");
  else if (action === "update-webui") setServerActionStatus("Ready to preview eligible Web UI installations separately from Pi.", "info");
  else if (action === "stop") setServerActionStatus("Ready to stop the Web UI server.", "info");
  else setServerActionStatus();
}

function setServerActionBusy(label) {
  if (elements.serverActionSelect) elements.serverActionSelect.disabled = true;
  if (elements.runServerActionButton) {
    elements.runServerActionButton.disabled = true;
    elements.runServerActionButton.textContent = label;
  }
}

function resetServerActionControls() {
  if (elements.serverActionSelect) {
    elements.serverActionSelect.disabled = false;
    elements.serverActionSelect.value = "";
  }
  updateServerActionButton();
}

async function waitForServerRestart(previousBootIdentity = serverBootIdentity) {
  const deadline = Date.now() + 90_000;
  let attempt = 0;
  while (Date.now() < deadline) {
    attempt += 1;
    await delay(attempt === 1 ? 900 : 500);
    const remainingSeconds = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
    const message = `Restarting… waiting for changed server identity (${remainingSeconds}s remaining)`;
    setServerActionStatus(message, "warn");
    setServerRestartOverlay(true, message);
    try {
      const health = await api("/api/health", { scoped: false });
      if (!health.bootIdentity || health.bootIdentity === previousBootIdentity) continue;
      serverBootIdentity = health.bootIdentity;
      setBackendOffline(false);
      await initializeTabs();
      setServerRestartOverlay(false);
      setServerActionStatus("Server restarted and reconnected.", "success");
      addEvent("Pi Web UI server restarted with a changed boot identity", "warn");
      return true;
    } catch (error) {
      setBackendOffline(true, error);
    }
  }
  return false;
}

async function restartServer() {
  if (!(await appConfirm({
    title: "Restart Pi Web UI server?",
    summary: "Browser clients disconnect briefly while the server restarts.",
    affected: "All connected browser clients and Pi tabs managed by this Web UI",
    undoable: false,
    confirmLabel: "Restart server",
  }))) return;

  setServerActionBusy("Restarting…");
  setServerActionStatus("Restart requested. Waiting for the server to come back…", "warn");
  setServerRestartOverlay(true, "Restart requested. Waiting for the server to come back…");
  try {
    await api("/api/restart", { method: "POST", scoped: false });
    addEvent("Pi Web UI server restart requested", "warn");
  } catch (error) {
    if (!error?.backendOffline) {
      const missingRestartEndpoint = error.statusCode === 404 || /not found/i.test(error.message || "");
      const message = missingRestartEndpoint
        ? "Restart is not available in the currently running server. Stop/start manually once to load the new backend."
        : error.message || String(error);
      addEvent(message, "error");
      setServerRestartOverlay(false);
      resetServerActionControls();
      setServerActionStatus(message, "error");
      return;
    }
    addEvent("Pi Web UI server connection dropped during restart request", "warn");
  }

  setBackendOffline(true, new Error("restart requested from side panel"));
  const restarted = await waitForServerRestart(serverBootIdentity);
  if (elements.serverActionSelect) {
    elements.serverActionSelect.disabled = false;
    elements.serverActionSelect.value = "";
  }
  updateServerActionButton();
  if (restarted) {
    setServerActionStatus("Server restarted and reconnected.", "success");
  } else {
    setServerRestartOverlay(false);
    setBackendOffline(true, new Error("restart reconnect timed out"));
    setServerActionStatus("Restart requested, but the server did not reconnect automatically.", "error");
    addEvent("Pi Web UI server did not come back online after restart request", "error");
  }
}

async function stopServer() {
  if (!(await appConfirm({
    title: "Stop Pi Web UI server?",
    summary: "The Web UI becomes unavailable until the server is started again.",
    affected: "All connected browser clients and Pi tabs managed by this Web UI",
    undoable: false,
    confirmLabel: "Stop server",
  }))) return;

  setServerActionBusy("Stopping…");
  setServerActionStatus("Stop requested. The Web UI will disconnect.", "warn");
  try {
    await api("/api/shutdown", { method: "POST", scoped: false });
    addEvent("Pi Web UI server stop requested", "warn");
    setBackendOffline(true, new Error("stop requested from side panel"));
  } catch (error) {
    if (error?.backendOffline) {
      addEvent("Pi Web UI server appears to be offline after stop request", "warn");
      setBackendOffline(true, error);
      return;
    }
    addEvent(error.message || String(error), "error");
    resetServerActionControls();
    setServerActionStatus(error.message || String(error), "error");
  }
}

async function runSelectedServerAction() {
  const action = elements.serverActionSelect?.value || "";
  if (action === "restart") await restartServer();
  else if (action === "update" || action === "update-webui") {
    const target = action === "update" ? "pi" : "webui";
    if (componentUpdateButtonState(target).disabled) {
      setServerActionStatus(componentUpdateStatusText(target).text || "Update status is not safe to start. Check the version tag for details.", "warn");
      return;
    }
    await startComponentUpdate(target);
  }
  else if (action === "stop") await stopServer();
}

function appShortcutModelLabel(model) {
  return model ? `${model.provider}/${model.id}` : "unknown model";
}

async function cycleModelFromShortcut(direction = "forward") {
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  try {
    const response = await api("/api/model-cycle", { method: "POST", body: { direction }, tabId: tabContext.tabId });
    applyResponseTab(response);
    const model = response.data?.model;
    const scope = response.data?.scoped ? `scoped (${response.data.scopeSource})` : "all models";
    if (isCurrentTabContext(tabContext)) {
      applyOptimisticModelSelection(model, tabContext);
      addTransientMessage({ role: "native", title: "model cycle", content: `Model set to ${appShortcutModelLabel(model)} via ${direction} cycle over ${scope}.`, level: "info" });
      await Promise.allSettled([refreshState(tabContext), refreshModels(tabContext), refreshStats(tabContext)]);
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      addEvent(error.message, "error");
      addTransientMessage({ role: "error", title: "model cycle", content: error.message, level: "error" });
    }
  }
}

async function cycleThinkingFromShortcut() {
  const tabContext = activeTabContext();
  if (!tabContext.tabId) return;
  try {
    const response = await api("/api/thinking-cycle", { method: "POST", body: {}, tabId: tabContext.tabId });
    if (isCurrentTabContext(tabContext)) {
      applyOptimisticThinkingSelection(response.data, tabContext);
      addTransientMessage({ role: "native", title: "thinking", content: response.data?.level ? `Thinking level: ${response.data.level}` : "Thinking level did not change.", level: "info" });
      if (response.data?.level) requestGitFooterWebuiPayload(tabContext, { force: true });
      await Promise.allSettled([refreshState(tabContext), refreshStats(tabContext)]);
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      addEvent(error.message, "error");
      addTransientMessage({ role: "error", title: "thinking", content: error.message, level: "error" });
    }
  }
}

function clearPromptFromShortcut() {
  const input = elements.promptInput;
  if (document.activeElement !== input) return false;
  if (input.selectionStart !== input.selectionEnd) return false;
  if (!input.value) return false;
  const previous = input.value;
  // Go through the editing command so the browser's own Ctrl+Z can bring the text back.
  let cleared = false;
  try {
    input.select();
    cleared = document.execCommand("delete");
  } catch {
    cleared = false;
  }
  if (!cleared || input.value) input.value = "";
  resizePromptInput();
  renderCommandSuggestions();
  addEvent("prompt cleared", "info");
  offerUndo({
    message: "Prompt cleared (Ctrl/Cmd+C with nothing selected).",
    undo: () => {
      input.value = previous;
      resizePromptInput();
      renderCommandSuggestions();
      input.focus({ preventScroll: true });
      input.setSelectionRange(previous.length, previous.length);
    },
    successMessage: "Prompt restored.",
    timeoutMs: 8000,
  });
  return true;
}

function parseUserBashInput(message) {
  const text = String(message || "").trim();
  if (!text.startsWith("!") || text === "!" || text === "!!") return null;
  const excludeFromContext = text.startsWith("!!");
  const command = text.slice(excludeFromContext ? 2 : 1).trim();
  if (!command) return null;
  return { command, excludeFromContext };
}

function userBashOutputSummary(result = {}, excludeFromContext = false) {
  const output = String(result.output || "").trimEnd();
  const status = result.cancelled ? "cancelled" : result.exitCode === 0 ? "exit 0" : result.exitCode === undefined || result.exitCode === null ? "finished" : `exit ${result.exitCode}`;
  const context = excludeFromContext ? "excluded from LLM context" : "included in the next LLM context";
  const lines = [`# ${status}; ${context}`];
  if (output) lines.push("", output);
  if (result.truncated && result.fullOutputPath) lines.push("", `Full output: ${result.fullOutputPath}`);
  return lines.join("\n");
}

function clearComposerAfterUserBash({ usesPromptInput, targetTabId, tabContext }) {
  if (!usesPromptInput) return;
  clearAttachments(targetTabId);
  if (isCurrentTabContext(tabContext)) {
    elements.promptInput.value = "";
    resizePromptInput();
  } else {
    tabDrafts.set(targetTabId, "");
  }
}

function enqueueUserBashCommand(parsed, { usesPromptInput = false, targetTabId = activeTabId } = {}) {
  if (!targetTabId || !parsed?.command) return;
  const tabContext = activeTabContext(targetTabId);
  clearComposerAfterUserBash({ usesPromptInput, targetTabId, tabContext });
  const queue = userBashQueueForTab(targetTabId);
  queue.push({ command: parsed.command, excludeFromContext: parsed.excludeFromContext === true, enqueuedAt: Date.now() });
  const waiting = queue.length;
  if (isCurrentTabContext(tabContext)) {
    addTransientMessage({
      role: "bashExecution",
      title: parsed.excludeFromContext ? "bash (!! queued)" : "bash (! queued)",
      command: parsed.command,
      output: `Queued behind the active bash command. Position: ${waiting}.\n\nOutput will be ${parsed.excludeFromContext ? "excluded from" : "included in the next"} LLM context when it runs.`,
      excludeFromContext: parsed.excludeFromContext === true,
      level: "info",
    });
    addEvent(`bash queued (${waiting} waiting): ${parsed.command}`, "info");
    setRunIndicatorActivity(`Bash queued (${waiting} waiting)…`);
    updateComposerModeButtons();
  }
}

function dequeueNextUserBashCommand(targetTabId) {
  return userBashQueueForTab(targetTabId).shift() || null;
}

async function runUserBashCommand(parsed, { usesPromptInput = false, targetTabId = activeTabId, queued = false } = {}) {
  if (!targetTabId || !parsed?.command) return;
  const tabContext = activeTabContext(targetTabId);
  const { command, excludeFromContext } = parsed;
  resumeChatAutoFollow();
  setComposerActionsOpen(false);
  hideCommandSuggestions();
  userBashByTab.set(targetTabId, { command, excludeFromContext, startedAt: Date.now() });
  markTabWorkingLocally(targetTabId);
  if (isCurrentTabContext(tabContext)) {
    const waiting = queuedUserBashCount(targetTabId);
    setRunIndicatorActivity(`Running bash: ${command}${waiting ? ` (${waiting} queued)` : ""}`);
    addTransientMessage({
      role: "bashExecution",
      title: excludeFromContext ? "bash (!!)" : "bash (!)" ,
      command,
      output: `${queued ? "Dequeued and running.\n\n" : ""}${excludeFromContext ? "Output will be excluded from LLM context." : "Output will be included in the next LLM context."}\n\nRunning…`,
      excludeFromContext,
      level: "info",
    });
  }
  clearComposerAfterUserBash({ usesPromptInput, targetTabId, tabContext });

  try {
    const response = await api("/api/bash", { method: "POST", body: { command, excludeFromContext }, tabId: targetTabId });
    const result = response.data || {};
    applyResponseTab(response);
    if (isCurrentTabContext(tabContext)) {
      for (const warning of response.warnings || []) {
        if (warning) addEvent(String(warning), "warn");
      }
      addTransientMessage({
        role: "bashExecution",
        title: excludeFromContext ? "bash (!! complete)" : "bash (! complete)",
        command,
        output: userBashOutputSummary(result, excludeFromContext),
        exitCode: result.exitCode,
        cancelled: result.cancelled === true,
        truncated: result.truncated === true,
        fullOutputPath: result.fullOutputPath,
        excludeFromContext,
        level: result.cancelled ? "warn" : result.exitCode ? "error" : "info",
      });
      addEvent(`bash ${result.cancelled ? "cancelled" : "finished"}: ${command}`, result.cancelled || result.exitCode ? "warn" : "info");
      scheduleRefreshMessages(250, tabContext);
      scheduleRefreshState(250, tabContext);
    } else {
      scheduleRefreshTabs(300);
    }
  } catch (error) {
    if (isCurrentTabContext(tabContext)) {
      addEvent(error.message, "error");
      addTransientMessage({ role: "error", title: excludeFromContext ? "!! bash failed" : "! bash failed", content: error.message, level: "error" });
    }
  } finally {
    userBashByTab.delete(targetTabId);
    const nextQueued = dequeueNextUserBashCommand(targetTabId);
    if (isCurrentTabContext(tabContext)) {
      if (nextQueued) {
        setRunIndicatorActivity(`Starting queued bash (${queuedUserBashCount(targetTabId)} waiting)…`);
      } else if (!currentState?.isStreaming && !currentState?.isCompacting) {
        markTabIdleLocally(targetTabId);
        clearRunIndicatorActivity();
      } else {
        syncRunIndicatorFromState(currentState);
      }
      updateComposerModeButtons();
    }
    if (nextQueued) void runUserBashCommand(nextQueued, { usesPromptInput: false, targetTabId, queued: true });
  }
}

async function sendUserBashCommand(parsed, { usesPromptInput = false, targetTabId = activeTabId } = {}) {
  if (!targetTabId || !parsed?.command) return;
  if (isUserBashActive(targetTabId) || queuedUserBashCount(targetTabId) > 0) {
    enqueueUserBashCommand(parsed, { usesPromptInput, targetTabId });
    return;
  }
  await runUserBashCommand(parsed, { usesPromptInput, targetTabId });
}

function clearPromptInputForRouting({ usesPromptInput, targetTabId, tabContext }) {
  if (!usesPromptInput) return;
  tabDrafts.set(targetTabId, "");
  if (!isCurrentTabContext(tabContext)) return;
  elements.promptInput.value = "";
  resizePromptInput();
  hideCommandSuggestions();
}

function restorePromptInputAfterRoutingError(message, { usesPromptInput, targetTabId, tabContext }) {
  if (!usesPromptInput) return;
  if (isCurrentTabContext(tabContext)) {
    if (elements.promptInput.value) return;
    elements.promptInput.value = message;
    resizePromptInput();
    tabDrafts.set(targetTabId, message);
    return;
  }
  if (!tabDrafts.get(targetTabId)) tabDrafts.set(targetTabId, message);
}

function createBrowserPromptRequestId() {
  const generated = globalThis.crypto?.randomUUID?.();
  if (generated) return generated;
  const bytes = new Uint8Array(16);
  globalThis.crypto?.getRandomValues?.(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function createBrowserGuidedGitLaunchId() {
  const generated = globalThis.crypto?.randomUUID?.();
  if (generated) return generated;
  const bytes = new Uint8Array(16);
  globalThis.crypto?.getRandomValues?.(bytes);
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

async function retryMobileFailedSend() {
  const pending = mobileFailedSend;
  if (!pending || pending.retrying) return;
  pending.retrying = true;
  renderMobileFailedSendRecovery();
  recordMobileDiagnostic("manual send retry", pending.kind);
  try {
    const path = pending.kind === "steer" ? "/api/steer" : pending.kind === "follow-up" ? "/api/follow-up" : "/api/prompt";
    const response = await api(path, { method: "POST", body: pending.body, tabId: pending.tabId });
    applyResponseTab(response);
    if (pending.tabId === activeTabId && elements.promptInput.value.trim() === pending.inputMessage.trim()) {
      elements.promptInput.value = "";
      tabDrafts.set(pending.tabId, "");
      resizePromptInput();
    }
    clearAttachments(pending.tabId);
    mobileFailedSend = null;
    renderMobileFailedSendRecovery();
    persistMobileContinuityState();
    addEvent("failed send retried manually with the original request identity", "info");
    scheduleForegroundReconcile("manual failed-send retry", 0);
  } catch (error) {
    pending.retrying = false;
    renderMobileFailedSendRecovery();
    addEvent(`manual retry was not confirmed: ${error.message || String(error)}`, "error");
  }
}

function discardMobileFailedSend() {
  if (!mobileFailedSend) return;
  mobileFailedSend = null;
  renderMobileFailedSendRecovery();
  persistMobileContinuityState();
  addEvent("discarded failed-send recovery; the composer draft remains available", "warn");
  recordMobileDiagnostic("failed send discarded");
}

async function sendPrompt(kind = "prompt", explicitMessage, { targetTabId = activeTabId, throwOnError = false, streamingBehavior } = {}) {
  const usesPromptInput = explicitMessage === undefined;
  const rawMessage = usesPromptInput ? elements.promptInput.value : explicitMessage;
  const inputMessage = String(rawMessage || "");
  const originalMessage = inputMessage.trim();
  if (!targetTabId) return;
  if (voiceConversationActiveFor(targetTabId)) voiceConversation.handleUserActivity();
  const tabContext = activeTabContext(targetTabId);
  const attachments = usesPromptInput ? [...attachmentsForTab(targetTabId)] : [];
  const unavailableAttachments = attachments.filter((attachment) => attachment.requiresReselect);
  if (unavailableAttachments.length) {
    addEvent(`${unavailableAttachments.length} restored attachment${unavailableAttachments.length === 1 ? " requires" : "s require"} reselection before sending.`, "warn");
    if (isMobileShellV2Active()) mobileOpenSurface("actionSheet", "context");
    return;
  }
  if (!originalMessage && attachments.length === 0) return;
  if (kind === "prompt" && attachments.length === 0 && await handleNativeSlashSelectorCommand(originalMessage, { usesPromptInput })) return;
  const userBash = kind === "prompt" && attachments.length === 0 ? parseUserBashInput(originalMessage) : null;
  if (userBash) {
    await sendUserBashCommand(userBash, { usesPromptInput, targetTabId });
    return;
  }

  const guidedGitExtensionLaunch = kind === "prompt"
    && attachments.length === 0
    && guidedGitWorkflowCommandForTabCatalog(commandCatalogForTab(targetTabId), originalMessage);
  let guidedGitPermitGranted = false;
  let guidedGitLaunchId = "";
  if (guidedGitExtensionLaunch) {
    if (!guidedGitLaunchAdmitted(targetTabId)) return;
    guidedGitLaunchId = createBrowserGuidedGitLaunchId();
    if (!guidedGitLaunchPermits.grant(targetTabId, guidedGitLaunchId)) {
      addEvent("Guided Git activation is already pending for this tab.", "warn");
      return;
    }
    guidedGitPermitGranted = true;
  }

  const targetState = targetTabId === activeTabId ? currentState : tabStateCache.get(targetTabId);
  const targetWasStreaming = !!targetState?.isStreaming;
  const targetWasCompacting = !!targetState?.isCompacting;
  const targetWasBusy = targetWasStreaming || targetWasCompacting;
  const busyBehavior = normalizeBusyPromptBehavior(busyPromptBehavior);
  const startsRun = kind === "prompt" && !targetWasBusy;
  let optimisticPromptId = "";
  clearPromptInputForRouting({ usesPromptInput, targetTabId, tabContext });
  resumeChatAutoFollow();
  updateJumpToLatestButton();
  setComposerActionsOpen(false);
  if (startsRun) {
    promptRoutingTabs.add(targetTabId);
    markTabWorkingLocally(targetTabId);
    if (isCurrentTabContext(tabContext)) {
      optimisticPromptId = appendOptimisticUserPrompt(originalMessage, attachments.length);
      setRunIndicatorActivity(attachments.length ? "Preparing attachments for routing…" : "Routing prompt to the selected agent…");
    }
  }

  let message = originalMessage;
  let dispatchedRequest = null;
  try {
    const prepared = attachments.length ? await prepareAttachmentsForPrompt(attachments, targetTabId) : { images: [], uploadedFiles: [], inlineImageIds: new Set() };
    message = composeMessageWithAttachments(originalMessage, prepared.uploadedFiles, prepared.inlineImageIds);
    // Dispatch against the captured target tab, never the tab that happened
    // to become active while attachments/requests were resolving.
    if (kind === "prompt" && attachments.length === 0) message = resolveRpcSlashCommandMessage(message, { tabId: targetTabId });
    const bodyBase = { message };
    // The ID is generated once per browser dispatch and scoped by the server to
    // targetTabId. This implementation intentionally never retries an
    // ambiguous mutation automatically.
    if (kind === "prompt") bodyBase.requestId = createBrowserPromptRequestId();
    if (guidedGitLaunchId) bodyBase.guidedGitLaunchId = guidedGitLaunchId;
    if (prepared.images.length) bodyBase.images = prepared.images;
    if (!message.startsWith("/")) {
      rememberPromptHistory(message, { tabId: targetTabId });
      if (kind === "prompt") rememberLastUserPrompt(message, { tabId: targetTabId });
    }
    if (startsRun && isCurrentTabContext(tabContext)) setRunIndicatorActivity("Routing complete; starting agent…");

    let response;
    if (kind === "steer") {
      response = await api("/api/steer", { method: "POST", body: bodyBase, tabId: targetTabId });
    } else if (kind === "follow-up") {
      response = await api("/api/follow-up", { method: "POST", body: bodyBase, tabId: targetTabId });
    } else {
      const body = { ...bodyBase };
      if (targetWasBusy) body.streamingBehavior = streamingBehavior || busyBehavior;
      dispatchedRequest = { kind, body, tabId: targetTabId, inputMessage };
      response = await api("/api/prompt", { method: "POST", body, tabId: targetTabId });
    }
    applyResponseTab(response);
    // A successful RPC response ends prompt-routing ownership even when an
    // extension command handled the input without starting an agent turn.
    // Canonical streaming state keeps real agent runs active after this handoff.
    if (startsRun) promptRoutingTabs.delete(targetTabId);
    if (response?.command === "native_slash_command" && /^\/new(?:\s|$)/.test(message)) forgetLastUserPrompt(targetTabId);
    const targetStillActive = isCurrentTabContext(tabContext);
    if (startsRun && response?.command === "native_slash_command") {
      discardOptimisticUserPrompt(optimisticPromptId);
      markTabIdleLocally(targetTabId);
      if (targetStillActive) clearRunIndicatorActivity();
    } else if (targetStillActive && response?.data?.queuedFor === "compaction") {
      setRunIndicatorActivity("Prompt queued; Pi will resume automatically after compaction…");
      addEvent("prompt queued until compaction finishes");
    } else if (targetStillActive && kind === "steer" && currentState?.isStreaming) {
      setRunIndicatorActivity("Steering sent; waiting for the next output or action…");
    } else if (targetStillActive && kind === "follow-up" && currentState?.isStreaming) {
      setRunIndicatorActivity("Follow-up queued; current agent run is still active…");
    }
    if (targetStillActive && response?.command === "native_slash_command") {
      applyNativeSlashCommandEffects(response, message, tabContext);
    }
    if (usesPromptInput) clearAttachments(targetTabId);
    persistMobileContinuityState();
    if (targetStillActive) {
      hideCommandSuggestions();
      if (response?.command !== "native_slash_command") scheduleRefreshState(120, tabContext);
    } else if (response?.command !== "native_slash_command") {
      scheduleRefreshTabs(300);
    }
  } catch (error) {
    if (guidedGitPermitGranted) guidedGitLaunchPermits.clearTab(targetTabId);
    restorePromptInputAfterRoutingError(inputMessage, { usesPromptInput, targetTabId, tabContext });
    if (dispatchedRequest?.kind === "prompt" && dispatchedRequest.body?.requestId && error?.backendOffline === true && isMobileShellV2Active()) {
      mobileFailedSend = { ...dispatchedRequest, retrying: false };
      renderMobileFailedSendRecovery();
      recordMobileDiagnostic("send not confirmed", kind);
      persistMobileContinuityState();
    }
    if (startsRun) {
      promptRoutingTabs.delete(targetTabId);
      discardOptimisticUserPrompt(optimisticPromptId, { render: false });
      markTabIdleLocally(targetTabId);
      if (isCurrentTabContext(tabContext)) clearRunIndicatorActivity();
    }
    if (isCurrentTabContext(tabContext)) {
      addEvent(error.message, "error");
      addTransientMessage({ role: "error", title: message.startsWith("/") ? message.split(/\s+/, 1)[0] : "error", content: error.message, level: "error" });
    }
    if (throwOnError) throw error;
  }
}

function hasQueuedDialogRequest(id) {
  if (!id) return false;
  const key = String(id);
  return String(activeDialog?.id || "") === key || dialogQueue.some((request) => String(request?.id || "") === key);
}

function removeQueuedDialogRequests(ids = []) {
  const idSet = new Set(ids.map((id) => String(id)).filter(Boolean));
  if (idSet.size === 0) return false;
  for (let i = dialogQueue.length - 1; i >= 0; i -= 1) {
    if (idSet.has(String(dialogQueue[i]?.id || ""))) dialogQueue.splice(i, 1);
  }
  if (activeDialog && idSet.has(String(activeDialog.id || ""))) {
    if (elements.dialog.open) elements.dialog.close();
    activeDialog = null;
    activeDialogCancel = null;
    showNextDialog();
    return true;
  }
  return false;
}

function handleExtensionUiRequest(request) {
  if (handleGuidedGitActivationRequest(request)) return;
  request.tabId ||= activeTabId;
  switch (request.method) {
    case "notify": {
      const level = request.notifyType === "error" ? "error" : request.notifyType === "warning" ? "warn" : "info";
      const message = request.message || "notification";
      addEvent(message, level);
      addTransientMessage({ role: "extension", title: "extension output", content: message, level });
      return;
    }
    case "setStatus": {
      const statusKey = request.statusKey || "extension";
      if (statusKey === FEATURE_DECISION_OUTPUT_STATUS_KEY) {
        handleFeatureDecisionOutputStatus(request.statusText, request.tabId || activeTabId);
        return;
      }
      if (statusKey === FEATURE_CATEGORY_STATUS_KEY) {
        handleFeatureCategoryStatus(request.statusText, request.tabId || activeTabId);
        return;
      }
      if (request.statusText) {
        statusEntries.set(statusKey, request.statusText);
        if (statusKey === GIT_FOOTER_WEBUI_STATUS_KEY) {
          const footerPayload = parseGitFooterWebuiPayloadRaw(request.statusText);
          const validPayload = !!footerPayload;
          cacheGitFooterWebuiPayload(request.statusText, request.tabId);
          settleGitFooterPayload(
            request.tabId || activeTabId,
            validPayload ? "ready" : "failed",
            validPayload ? "" : "Git footer returned invalid status data — refresh to retry",
          );
          if (footerPayload) syncClaudeUsageFromGitFooterPayload(footerPayload);
        }
      } else {
        statusEntries.delete(statusKey);
        if (statusKey === GIT_FOOTER_WEBUI_STATUS_KEY) settleGitFooterPayload(request.tabId || activeTabId, "idle");
      }
      if (statusKey === STATS_WEBUI_STATUS_KEY) handleStatsWebuiStatus(request.statusText);
      if (statusKey === BTW_WEBUI_STATUS_KEY) handleBtwWebuiStatus(request.statusText);
      if (statusKey === NATURAL_CONVERSATION_STATUS_KEY) handleNaturalConversationStatus(request.statusText, request.tabId || activeTabId);
      if (statusKey === CODEX_FAST_MODE_STATUS_KEY && (request.tabId || activeTabId) === activeTabId) applyCodexFastModeStatus(request.statusText);
      if (statusKey === WORKFLOW_MODE_STATUS_KEY) handleWorkflowModeStatus(request.statusText, request.tabId || activeTabId);
      if (statusKey === "pi-remote-webui") handleRemoteWebuiStatus(request.statusText);
      updateOptionalFeatureAvailability();
      if (statusKey === GIT_FOOTER_WEBUI_STATUS_KEY) {
        if (currentState?.isStreaming || runIndicatorLocallyActive) return;
        if (deferUiRenderDuringInteractiveSurface("footer", renderFooter)) return;
        renderFooter();
        return;
      }
      renderStatus();
      return;
    }
    case "setWidget": {
      const widgetKey = request.widgetKey || request.id;
      const requestTabId = request.tabId || activeTabId;
      if (widgetKey === SUBAGENT_ASYNC_WIDGET_KEY) {
        const changed = setWidgetForTab(requestTabId, widgetKey, { ...request, widgetLines: undefined });
        if (changed && requestTabId === activeTabId) renderWidgets();
        return;
      }
      if (widgetKey === WORKFLOW_MODE_RPC_WIDGET_KEY) {
        const modeState = workflowModeStateFromRpcPayload(request.widgetLines);
        if (modeState) updateWorkflowModeForTab(requestTabId, modeState, { render: requestTabId === activeTabId });
        updateOptionalFeatureAvailability();
        return;
      }
      if (widgetKey === WORKFLOW_INSPECTOR_WIDGET_KEY) {
        const inspector = parseWorkflowInspectorPayload(request.widgetLines);
        if (inspector) updateWorkflowInspectorForTab(requestTabId, inspector);
        if (!setWidgetForTab(requestTabId, widgetKey, request)) return;
        updateOptionalFeatureAvailability();
        renderTabs();
        renderWidgets();
        return;
      }
      if (widgetKey === AUR_REVIEW_RPC_WIDGET_KEY) {
        const payload = parseAurReviewPayload(request.widgetLines);
        if (payload) reconcileGuidedGitReviewPayload(requestTabId, payload);
        else if (!Array.isArray(request.widgetLines)) reconcileGuidedGitReviewWidgetRemoval(requestTabId);
        if (!setWidgetForTab(requestTabId, widgetKey, request)) return;
        updateOptionalFeatureAvailability();
        renderTabs();
        renderWidgets();
        return;
      }
      if (widgetKey === "pi-remote-webui") {
        setWidgetForTab(requestTabId, widgetKey, { ...request, widgetLines: undefined });
        if (Array.isArray(request.widgetLines)) {
          mirrorRemoteWebuiWidgetToTranscript(widgetKey, request.widgetLines, request);
          showRemoteWebuiQrPopup(widgetKey, request.widgetLines, request);
        } else {
          closeRemoteWebuiQrPopup();
        }
      } else {
        if (!setWidgetForTab(requestTabId, widgetKey, request)) return;
      }
      updateOptionalFeatureAvailability();
      renderWidgets();
      return;
    }
    case "setTitle":
      if (request.title) document.title = request.title;
      return;
    case "set_editor_text":
      elements.promptInput.value = request.text || "";
      resizePromptInput();
      elements.promptInput.focus();
      renderCommandSuggestions();
      return;
    case "select":
    case "confirm":
    case "input":
    case "editor":
      if (isRemoteWebuiQrPopupLoading()) closeRemoteWebuiQrPopup();
      if (hasQueuedDialogRequest(request.id)) return;
      if (request.pendingExtensionUiRequestCount === undefined) {
        const tab = tabs.find((item) => item.id === request.tabId);
        if (setTabPendingBlockerCount(request.tabId, Math.max(1, tabPendingBlockerCount(tab) + 1))) renderTabs();
      }
      if (!request.replayed) notifyBlockedTab(request.tabId, { request, count: request.pendingExtensionUiRequestCount });
      if (request.replayed) addEvent(`recovered pending ${request.method} request`, "warn");
      setRunIndicatorActivity(`Waiting for your ${request.method} response…`);
      dialogQueue.push(request);
      showNextDialog();
      return;
    default:
      addEvent(`Unsupported extension UI request: ${request.method}`, "warn");
  }
}

async function sendDialogResponse(payload) {
  const { tabId = activeTabId, ...body } = payload;
  const tabContext = activeTabContext(tabId);
  const responseId = String(body.id || "");
  try {
    const response = await api("/api/extension-ui-response", { method: "POST", body, tabId });
    if (!applyResponseTab(response) && decrementTabPendingBlockerCount(tabId)) renderTabs();
  } catch (error) {
    if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
  } finally {
    if (!isCurrentTabContext(tabContext)) return;
    if (responseId && activeDialog && String(activeDialog.id || "") !== responseId) return;
    if (elements.dialog.open) elements.dialog.close();
    activeDialog = null;
    activeDialogCancel = null;
    if (runIndicatorIsActive()) {
      setRunIndicatorActivity("Continuing after your response…");
      // Extension commands can continue background work after Pi has already
      // returned to an idle canonical state. Reconcile promptly so this local
      // handoff label cannot survive the workflow that requested the dialog.
      scheduleRefreshState(120, tabContext);
    }
    showNextDialog();
  }
}

function cancelActiveExtensionDialog(event) {
  if (!activeDialog || typeof activeDialogCancel !== "function") return false;
  event?.preventDefault?.();
  return activeDialogCancel();
}

function createDialogResponder(sendResponse) {
  let responseSent = false;
  return (response, onAccept) => {
    if (responseSent) return false;
    responseSent = true;
    onAccept?.();
    sendResponse(response);
    return true;
  };
}

function addDialogButton(label, handler, className) {
  const button = make("button", className, label);
  button.type = "button";
  button.addEventListener("click", handler);
  elements.dialogActions.append(button);
  return button;
}

const WORKFLOW_SCRIPT_TOKEN_PATTERN = /\/\/.*$|\/\*.*?\*\/|`(?:\\.|[^`])*`|"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|\b(?:abstract|any|as|asserts|async|await|boolean|break|case|catch|class|const|continue|declare|default|delete|do|else|enum|export|extends|false|finally|for|from|function|get|if|implements|import|in|instanceof|interface|is|keyof|let|namespace|never|new|null|number|of|private|protected|public|readonly|return|satisfies|set|static|string|super|switch|symbol|this|throw|true|try|type|typeof|undefined|unknown|using|var|void|while|yield)\b|\b\d+(?:\.\d+)?\b/g;

function isWorkflowScriptPreviewRequest(request, prompt) {
  const title = String(prompt?.title || "");
  return request?.method === "editor"
    && title.startsWith("Raw workflow script")
    && /\binspection only;\s*edits are ignored\b/i.test(title);
}

function workflowScriptTokenClass(token) {
  if (/^\/\//.test(token) || /^\/\*/.test(token)) return "comment";
  if (/^[`"']/.test(token)) return "string";
  if (/^\d/.test(token)) return "number";
  return "keyword";
}

function appendWorkflowScriptTokens(parent, line) {
  let start = 0;
  WORKFLOW_SCRIPT_TOKEN_PATTERN.lastIndex = 0;
  for (let match = WORKFLOW_SCRIPT_TOKEN_PATTERN.exec(line); match; match = WORKFLOW_SCRIPT_TOKEN_PATTERN.exec(line)) {
    if (match.index > start) parent.append(document.createTextNode(line.slice(start, match.index)));
    parent.append(make("span", `workflow-script-token workflow-script-token-${workflowScriptTokenClass(match[0])}`, match[0]));
    start = match.index + match[0].length;
  }
  if (start < line.length) parent.append(document.createTextNode(line.slice(start)));
}

function renderWorkflowScriptPreview(request, respondToDialog) {
  const source = request.prefill ?? "";
  const sourceLines = source.split("\n");
  const searchableLines = sourceLines.map((line) => line.toLocaleLowerCase());
  const preview = make("section", "workflow-script-preview");
  preview.setAttribute("aria-label", "Read-only TypeScript workflow script");

  const metadata = make("div", "workflow-script-meta");
  metadata.append(
    make("span", "workflow-script-language", "TypeScript · read-only"),
    make("span", "workflow-script-source-stats", `${sourceLines.length.toLocaleString()} ${sourceLines.length === 1 ? "line" : "lines"} · ${source.length.toLocaleString()} characters`),
  );

  const toolbar = make("div", "workflow-script-toolbar");
  const search = make("input", "workflow-script-search");
  search.type = "search";
  search.placeholder = "Search source";
  search.setAttribute("aria-label", "Search workflow source");

  const previous = make("button", "workflow-script-search-button", "Previous match");
  previous.type = "button";
  previous.title = "Previous search match";
  previous.setAttribute("aria-label", "Previous search match");
  previous.disabled = true;

  const next = make("button", "workflow-script-search-button", "Next match");
  next.type = "button";
  next.title = "Next search match";
  next.setAttribute("aria-label", "Next search match");
  next.disabled = true;

  const wrap = make("button", "workflow-script-wrap-button", "Wrap lines");
  wrap.type = "button";
  wrap.title = "Wrap long lines";
  wrap.setAttribute("aria-label", "Wrap long lines");
  wrap.setAttribute("aria-pressed", "false");

  const copy = make("button", "workflow-script-copy-button", "Copy source");
  copy.type = "button";
  copy.title = "Copy workflow source";
  copy.setAttribute("aria-label", "Copy workflow source");

  const searchStatus = make("span", "workflow-script-search-status", "Search source.");
  searchStatus.setAttribute("role", "status");
  searchStatus.setAttribute("aria-live", "polite");
  const copyStatus = make("span", "workflow-script-copy-status");
  copyStatus.setAttribute("role", "status");
  copyStatus.setAttribute("aria-live", "polite");
  toolbar.append(search, previous, next, wrap, copy, searchStatus, copyStatus);

  const codeViewer = make("div", "workflow-script-code");
  codeViewer.id = "workflowScriptViewer";
  codeViewer.tabIndex = 0;
  codeViewer.setAttribute("role", "region");
  codeViewer.setAttribute("aria-label", "Read-only workflow source with line numbers");
  search.setAttribute("aria-controls", codeViewer.id);

  const lineRows = sourceLines.map((line, index) => {
    const row = make("div", "workflow-script-line");
    row.dataset.line = String(index + 1);
    const number = make("span", "workflow-script-line-number", String(index + 1));
    number.setAttribute("aria-hidden", "true");
    const text = make("code", "workflow-script-line-text");
    appendWorkflowScriptTokens(text, line);
    row.append(number, text);
    codeViewer.append(row);
    return row;
  });

  let matchingLineIndexes = [];
  let activeMatchIndex = -1;
  const setActiveMatch = (index, { scroll = true } = {}) => {
    if (matchingLineIndexes.length === 0) return;
    activeMatchIndex = (index + matchingLineIndexes.length) % matchingLineIndexes.length;
    const activeLine = matchingLineIndexes[activeMatchIndex];
    lineRows.forEach((row, lineIndex) => {
      const active = lineIndex === activeLine;
      row.classList.toggle("is-active-match", active);
      if (active) row.setAttribute("aria-current", "true");
      else row.removeAttribute("aria-current");
    });
    searchStatus.textContent = `${activeMatchIndex + 1} of ${matchingLineIndexes.length} matching ${matchingLineIndexes.length === 1 ? "line" : "lines"}.`;
    if (scroll) lineRows[activeLine].scrollIntoView({ block: "center" });
  };
  const updateMatches = () => {
    const query = search.value.toLocaleLowerCase();
    matchingLineIndexes = [];
    if (query) {
      searchableLines.forEach((line, index) => {
        if (line.includes(query)) matchingLineIndexes.push(index);
      });
    }
    const matchingLineSet = new Set(matchingLineIndexes);
    lineRows.forEach((row, index) => {
      const matched = matchingLineSet.has(index);
      row.classList.toggle("is-search-match", matched);
      row.classList.remove("is-active-match");
      row.removeAttribute("aria-current");
    });
    activeMatchIndex = -1;
    previous.disabled = matchingLineIndexes.length === 0;
    next.disabled = matchingLineIndexes.length === 0;
    if (matchingLineIndexes.length > 0) setActiveMatch(0);
    else searchStatus.textContent = query ? "No matching lines." : "Search source.";
  };

  search.addEventListener("input", updateMatches);
  search.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    if (matchingLineIndexes.length === 0) return;
    setActiveMatch(activeMatchIndex + (event.shiftKey ? -1 : 1));
  });
  previous.addEventListener("click", () => setActiveMatch(activeMatchIndex - 1));
  next.addEventListener("click", () => setActiveMatch(activeMatchIndex + 1));
  wrap.addEventListener("click", () => {
    const wrapped = codeViewer.classList.toggle("is-wrapped");
    wrap.textContent = wrapped ? "Unwrap lines" : "Wrap lines";
    wrap.title = wrapped ? "Do not wrap long lines" : "Wrap long lines";
    wrap.setAttribute("aria-label", wrap.title);
    wrap.setAttribute("aria-pressed", String(wrapped));
  });
  copy.addEventListener("click", async () => {
    copy.disabled = true;
    try {
      await copyText(source);
      copy.textContent = "Copied";
      copyStatus.textContent = "Workflow source copied.";
    } catch (error) {
      copy.textContent = "Copy failed";
      copyStatus.textContent = "Could not copy workflow source.";
    } finally {
      window.setTimeout(() => {
        if (!copy.isConnected) return;
        copy.textContent = "Copy source";
        copy.disabled = false;
      }, 1600);
    }
  });

  preview.append(metadata, toolbar, codeViewer);
  elements.dialogBody.append(preview);
  addDialogButton("Cancel workflow", () => respondToDialog({ cancelled: true }));
  addDialogButton("Back to approval", () => respondToDialog({ value: request.prefill }), "primary");
  setTimeout(() => codeViewer.focus(), 0);
}

function showNextDialog() {
  if (activeDialog || dialogQueue.length === 0) return;
  activeDialog = dialogQueue.shift();
  activeDialogCancel = null;
  const request = activeDialog;

  const prompt = normalizeDialogPrompt(request);
  const detectedReleasePrompt = request.method === "select" ? releaseDialogPromptParts(prompt) : null;
  const releasePrompt = detectedReleasePrompt && isOptionalFeatureEnabled(detectedReleasePrompt.featureId) ? detectedReleasePrompt : null;
  const displayPrompt = releasePrompt || prompt;
  const isGuardrailDialog = isGuardrailDialogPrompt(displayPrompt);
  const isReleaseDialog = !!releasePrompt;
  const isWorkflowScriptPreview = isWorkflowScriptPreviewRequest(request, prompt);
  const questionnaire = request.method === "select" && !isReleaseDialog ? questionnaireSelectParts(prompt, request.options) : null;
  elements.dialog.classList.toggle("guardrail-dialog", isGuardrailDialog);
  elements.dialog.classList.toggle("release-dialog", isReleaseDialog);
  elements.dialog.classList.toggle("workflow-script-dialog", isWorkflowScriptPreview);
  elements.dialog.classList.toggle("questionnaire-dialog", !!questionnaire);
  elements.dialogTitle.textContent = displayPrompt.title;
  if (isReleaseDialog) renderReleaseDialogMessage(elements.dialogMessage, displayPrompt.message);
  else renderAnsiText(elements.dialogMessage, displayPrompt.message);
  elements.dialogMessage.hidden = !displayPrompt.plainMessage;
  elements.dialogBody.replaceChildren();
  elements.dialogActions.replaceChildren();

  const respondToDialog = createDialogResponder((response) => {
    sendDialogResponse({ type: "extension_ui_response", id: request.id, tabId: request.tabId, ...response });
  });
  const cancel = () => respondToDialog({ cancelled: true });
  activeDialogCancel = cancel;

  if (questionnaire) {
    const options = make("div", "dialog-options questionnaire-options");
    const respondToQuestionnaire = (response) => respondToDialog(response, () => {
      options.querySelectorAll("button").forEach((button) => { button.disabled = true; });
      elements.dialogActions.querySelectorAll("button").forEach((button) => { button.disabled = true; });
    });
    activeDialogCancel = () => respondToQuestionnaire({ cancelled: true });
    (request.options || []).forEach((option, index) => {
      const optionLabel = String(option);
      const row = questionnaire.rows[index];
      const button = row.kind === "action"
        ? renderQuestionnaireActionButton(row)
        : renderQuestionnaireOptionButton(row, questionnaire.mode);
      // Presentation is derived, but the response always carries the exact
      // native option string the questionnaire runtime produced.
      button.addEventListener("click", () => respondToQuestionnaire({ value: optionLabel }));
      options.append(button);
    });
    elements.dialogBody.append(options);
    addDialogButton("Cancel", () => respondToQuestionnaire({ cancelled: true }), "questionnaire-dialog-cancel");
  } else if (request.method === "select") {
    const options = make("div", "dialog-options");
    for (const option of request.options || []) {
      const optionLabel = String(option);
      const button = make("button", undefined, optionLabel);
      button.type = "button";
      if (isGuardrailDialog && /^Block$/i.test(optionLabel)) button.classList.add("guardrail-safe-action");
      if (isGuardrailDialog && /^Allow/i.test(optionLabel)) button.classList.add("guardrail-allow-action");
      if (isReleaseDialog && /^(?:Yes|All eligible packages\b|Publish selected packages \([1-9]\d*\))/.test(optionLabel)) button.classList.add("primary", "release-publish-action");
      if (isReleaseDialog && /^Publish selected packages$/i.test(optionLabel)) button.classList.add("release-publish-disabled-action");
      if (isReleaseDialog && /^\[x\]/.test(optionLabel)) button.classList.add("release-target-option", "release-target-selected");
      if (isReleaseDialog && /^\[ \]/.test(optionLabel)) button.classList.add("release-target-option");
      if (isReleaseDialog && /^(?:No|Cancel)$/i.test(optionLabel)) button.classList.add("release-cancel-action");
      button.addEventListener("click", () => respondToDialog({ value: optionLabel }));
      options.append(button);
    }
    elements.dialogBody.append(options);
    addDialogButton("Cancel", cancel);
  } else if (request.method === "confirm") {
    addDialogButton("Cancel", cancel);
    addDialogButton("No", () => respondToDialog({ confirmed: false }));
    addDialogButton("Yes", () => respondToDialog({ confirmed: true }), "primary");
  } else if (request.method === "input") {
    const input = make("input", "dialog-input");
    input.value = request.prefill || "";
    input.placeholder = request.placeholder || "";
    elements.dialogBody.append(input);
    // The dialog form uses method="dialog", so an unhandled Enter would close it
    // implicitly without ever sending a response and leave the extension blocked.
    // Keyboard, click, and cancel paths therefore share one guarded one-shot closure.
    const respondToInput = (response) => respondToDialog(response, () => {
      input.disabled = true;
      elements.dialogActions.querySelectorAll("button").forEach((button) => { button.disabled = true; });
    });
    const submitInput = () => respondToInput({ value: input.value });
    activeDialogCancel = () => respondToInput({ cancelled: true });
    input.addEventListener("keydown", (event) => {
      const intent = dialogInputEnterIntent(event);
      if (intent === "ignore") return;
      event.preventDefault();
      event.stopPropagation();
      if (intent === "submit") submitInput();
    });
    addDialogButton("Cancel", () => respondToInput({ cancelled: true }));
    addDialogButton("Submit", submitInput, "primary");
    setTimeout(() => input.focus(), 0);
  } else if (isWorkflowScriptPreview) {
    renderWorkflowScriptPreview(request, respondToDialog);
  } else if (request.method === "editor") {
    const textarea = make("textarea", "dialog-editor");
    textarea.value = request.prefill || "";
    elements.dialogBody.append(textarea);
    addDialogButton("Cancel", cancel);
    addDialogButton("Submit", () => respondToDialog({ value: textarea.value }), "primary");
    setTimeout(() => textarea.focus(), 0);
  }

  elements.dialog.showModal();
}

elements.dialog.addEventListener("cancel", cancelActiveExtensionDialog);

function supervisorEventEnvelope(event, fallbackTabId = activeTabId) {
  if (!event || typeof event !== "object") return null;
  const fields = ["supervisorScopeId", "supervisorEpoch", "supervisorSeq"];
  const present = fields.map((field) => Object.prototype.hasOwnProperty.call(event, field));
  if (!present.some(Boolean)) return null;
  const scopeId = String(event.supervisorScopeId || "").trim();
  const epoch = String(event.supervisorEpoch || "").trim();
  const tabId = String(event.tabId || fallbackTabId || "").trim();
  const sequenceText = present[2] ? String(event.supervisorSeq ?? "").trim() : null;
  const sequenceValid = sequenceText === null || /^(?:0|[1-9]\d*)$/.test(sequenceText);
  return {
    valid: present[0] && present[1] && scopeId.length > 0 && epoch.length > 0 && tabId.length > 0 && sequenceValid,
    scopeId,
    epoch,
    tabId,
    sequence: sequenceText === null || !sequenceValid ? null : BigInt(sequenceText),
  };
}

function supervisorCursorKey(envelope) {
  return JSON.stringify([envelope.scopeId, envelope.tabId]);
}

function acceptSupervisorEvent(event, fallbackTabId = activeTabId) {
  const envelope = supervisorEventEnvelope(event, fallbackTabId);
  if (!envelope) return true;
  if (!envelope.valid) {
    const warningKey = String(event?.type || "unknown");
    if (!supervisorEnvelopeWarnings.has(warningKey)) {
      supervisorEnvelopeWarnings.add(warningKey);
      addEvent(`ignored malformed supervisor event (${warningKey})`, "warn");
    }
    return false;
  }

  const key = supervisorCursorKey(envelope);
  const cursor = supervisorEventCursors.get(key);
  if (!cursor) {
    supervisorEventCursors.set(key, { epoch: envelope.epoch, sequence: envelope.sequence });
    return true;
  }

  if (cursor.epoch !== envelope.epoch) {
    const retired = supervisorRetiredEpochs.get(key) || new Set();
    if (retired.has(envelope.epoch)) return false;
    retired.add(cursor.epoch);
    supervisorRetiredEpochs.set(key, retired);
    supervisorEventCursors.set(key, { epoch: envelope.epoch, sequence: envelope.sequence });
    return true;
  }

  if (envelope.sequence === null) return true;
  if (cursor.sequence !== null && envelope.sequence <= cursor.sequence) return false;
  cursor.sequence = envelope.sequence;
  return true;
}

function supervisorContinuityKey(event, fallbackTabId = activeTabId) {
  const envelope = supervisorEventEnvelope(event, fallbackTabId);
  return envelope?.valid ? `${supervisorCursorKey(envelope)}|${envelope.epoch}` : "";
}

function scheduleSupervisorContinuityRefresh(event, { gap = false } = {}) {
  const tabContext = activeTabContext(event?.tabId || activeTabId);
  const key = supervisorContinuityKey(event, tabContext.tabId);
  if (!key || !tabContext.tabId || !isCurrentTabContext(tabContext) || closingTerminalTabIds.has(tabContext.tabId)) return;

  if (gap && !supervisorGapWarnings.has(key)) {
    supervisorGapWarnings.add(key);
    addEvent("Buffered live output may be incomplete; refreshing tabs, state, and transcript from Pi.", "info");
  }
  if (supervisorContinuityRefreshes.has(key)) return;

  const timer = setTimeout(async () => {
    try {
      if (closingTerminalTabIds.has(tabContext.tabId)) return;
      const results = await Promise.allSettled([refreshTabs()]);
      if (isCurrentTabContext(tabContext) && !closingTerminalTabIds.has(tabContext.tabId)) {
        results.push(...(await Promise.allSettled([
          refreshState(tabContext),
          refreshMessages(tabContext, { authoritative: true }),
        ])));
      }
      if (!isCurrentTabContext(tabContext) || closingTerminalTabIds.has(tabContext.tabId)) return;
      for (const result of results) {
        if (result.status === "rejected") addEvent(`continuity refresh failed: ${result.reason?.message || String(result.reason)}`, "error");
      }
    } finally {
      supervisorContinuityRefreshes.delete(key);
    }
  }, 25);
  supervisorContinuityRefreshes.set(key, timer);
}

function handleInactiveTabEvent(event) {
  if (handleGuidedGitActivationRequest(event)) return;
  if (event.type === "extension_ui_request" && EXTENSION_UI_BLOCKING_METHODS.has(event.method)) {
    if (!event.replayed) notifyBlockedTab(event.tabId, { request: event, count: event.pendingExtensionUiRequestCount });
    renderTabs();
  } else if (event.type === "extension_ui_request" && event.method === "setStatus" && event.statusKey === WORKFLOW_MODE_STATUS_KEY) {
    handleWorkflowModeStatus(event.statusText, event.tabId);
    renderTabs();
  } else if (event.type === "extension_ui_request" && event.method === "setWidget" && (event.widgetKey || event.id) === WORKFLOW_MODE_RPC_WIDGET_KEY) {
    const modeState = workflowModeStateFromRpcPayload(event.widgetLines);
    if (modeState) updateWorkflowModeForTab(event.tabId, modeState, { render: false });
    renderTabs();
  } else if (event.type === "extension_ui_request" && event.method === "setWidget" && (event.widgetKey || event.id) === WORKFLOW_INSPECTOR_WIDGET_KEY) {
    const inspector = parseWorkflowInspectorPayload(event.widgetLines);
    if (inspector) updateWorkflowInspectorForTab(event.tabId, inspector);
    setWidgetForTab(event.tabId, WORKFLOW_INSPECTOR_WIDGET_KEY, event);
    renderTabs();
  } else if (event.type === "extension_ui_request" && event.method === "setWidget" && (event.widgetKey || event.id) === AUR_REVIEW_RPC_WIDGET_KEY) {
    const payload = parseAurReviewPayload(event.widgetLines);
    if (payload) reconcileGuidedGitReviewPayload(event.tabId, payload);
    else if (!Array.isArray(event.widgetLines)) reconcileGuidedGitReviewWidgetRemoval(event.tabId);
    setWidgetForTab(event.tabId, AUR_REVIEW_RPC_WIDGET_KEY, event);
    updateOptionalFeatureAvailability();
    renderTabs();
  } else if (event.type === "agent_settled") {
    notifyAgentDone(event.tabId, { activity: event.tabActivity, tabTitle: event.tabTitle });
  }
}

const TRANSCRIPT_STREAM_BARRIER_EVENT_TYPES = new Set([
  "agent_start",
  "message_start",
  "message_end",
  "tool_execution_start",
  "tool_execution_end",
  "agent_end",
  "agent_settled",
  "auto_retry_start",
  "auto_retry_end",
  "compaction_start",
  "compaction_end",
  "webui_output_mode",
  "pi_process_exit",
  "pi_process_error",
]);

function beginForegroundTranscriptCatchUp() {
  foregroundTranscriptCatchUpRequired = true;
  backgroundReconnectSnapshotFresh = false;
  flushNormalStreamRenders("visibility-hidden");
  streamOutputController.cancel();
  if (!eventSource) return;
  eventStreamPausedForBackground = true;
  const source = eventSource;
  eventSource = null;
  source.close();
}

function dispatchTranscriptStreamEvent(event) {
  const classification = classifyTranscriptStreamEvent(event);
  if (classification && (document.visibilityState === "hidden" || foregroundTranscriptCatchUpRequired)) {
    foregroundTranscriptCatchUpRequired = true;
    foregroundTranscriptSuppressedEvents += 1;
    streamOutputController.cancel();
    return true;
  }
  return streamOutputController.dispatch(event, {
    owner: transcriptStreamOwner(event?.tabId || activeTabId),
  });
}

function flushTranscriptStreamBarrier(event) {
  if (!TRANSCRIPT_STREAM_BARRIER_EVENT_TYPES.has(event?.type)) return;
  streamOutputController.barrier(event.type);
  if (["message_end", "agent_end", "agent_settled", "compaction_end", "pi_process_exit", "pi_process_error"].includes(event.type)) {
    fallbackStreamDerivedOutput(`settlement:${event.type}`);
  }
  flushNormalStreamRenders(event.type);
  reconcileUnknownTranscriptEvidenceAtBarrier(event);
  if (event.type === "pi_process_exit" || event.type === "pi_process_error") streamOutputController.cancel();
}

function handleEvent(event) {
  if (dispatchTranscriptStreamEvent(event)) return;
  flushTranscriptStreamBarrier(event);
  if (event?.type === "webui_session_summary") {
    handleSessionSummaryEvent(event);
    return;
  }
  if (event?.type === "webui_optional_feature_migration") {
    applyOptionalFeatureMigrationSnapshot(event.snapshot);
    return;
  }
  if (["webui_optional_feature_restart_completed", "webui_optional_feature_restart_deferred"].includes(event?.type)) {
    optionalFeatureRestartNotice = {
      tabId: event.tabId || activeTabId,
      tabTitle: event.tabTitle || "terminal",
      autoRestarted: event.autoRestarted === true,
      restartDeferred: event.restartDeferred === true,
      reason: event.reason || "",
    };
    addEvent(event.autoRestarted ? "restarted tab to load new optional features" : "optional feature restart deferred because the tab is busy", event.restartDeferred ? "warn" : "info");
    renderOptionalFeatureMigrationSurface();
    return;
  }
  if (eventHasTabActivityPayload(event)) ingestEventTabActivity(event);
  if (event?.type === "auto_retry_start" || event?.type === "auto_retry_end") trackAutoRetryStateFromEvent(event);
  // Advance the fallback tool-boundary epoch before inactive-tab routing.
  // Inactive tool boundaries are still tracked, so their agent_start must own
  // the same run identity semantics as the foreground tab.
  if (event?.type === "agent_start") beginToolBoundaryRun(event);
  if (eventMayAffectSkillUsage(event)) trackSkillsFromEvent(event);
  if (handleGitWorkflowFallbackLifecycleEvent(event)) return;
  if (!eventTargetsActiveTab(event)) {
    handleInactiveTabEvent(event);
    return;
  }
  const tabContext = activeTabContext(event.tabId || activeTabId);
  if (["webui_connected", "agent_end", "message_end", "tool_execution_end"].includes(event.type)) scheduleIntercomConversationRefresh(tabContext);
  switch (event.type) {
    case "webui_connected": {
      const connectedTabId = event.tabId || activeTabId;
      const resumedWithFreshSnapshot = eventStreamPausedForBackground && backgroundReconnectSnapshotFresh;
      eventStreamPausedForBackground = false;
      backgroundReconnectSnapshotFresh = false;
      if (resumedWithFreshSnapshot) foregroundReconnectSnapshotFreshUntil = performance.now() + 2_000;
      clearFeatureDecisionStateForTab(connectedTabId, { render: true });
      acceptOutputModeAcknowledgement(event);
      setWebuiVersion(event.version);
      setPiVersion(event.piVersion);
      setWebuiDevServer(isWebuiDevMetadata(event));
      if (Object.prototype.hasOwnProperty.call(event, "activeRun")) {
        setAppRunnerData(event.tabId || activeTabId, { cwd: event.cwd, activeRun: event.activeRun });
        renderAppRunnerControls();
        renderWidgets();
      }
      addEvent(`connected to ${event.tabTitle || "terminal"} for ${event.cwd}`);
      if (event.supervisorReplayGap === true && !resumedWithFreshSnapshot) scheduleSupervisorContinuityRefresh(event, { gap: true });
      if (!resumedWithFreshSnapshot) scheduleForegroundReconcile("event stream reconnect", 0);
      break;
    }
    case "webui_supervisor_reconnected":
      addEvent("reconnected to the running Pi session");
      if (performance.now() > foregroundReconnectSnapshotFreshUntil) scheduleSupervisorContinuityRefresh(event);
      break;
    case "webui_supervisor_replay_gap":
      if (performance.now() > foregroundReconnectSnapshotFreshUntil) scheduleSupervisorContinuityRefresh(event, { gap: true });
      break;
    case "webui_output_mode":
      applyOutputModeControl(event, tabContext);
      break;
    case "webui_tab_renamed":
      applyTabMetadata(event.tab || { id: event.tabId, title: event.tabTitle, activity: event.tabActivity });
      addEvent(`${event.previousTabTitle || "terminal"} renamed to ${event.tabTitle || "terminal"}`);
      break;
    case "webui_recovery_opened":
      addEvent(`opened ${event.recoveryTabTitle || "recovery plan"}`);
      refreshTabs()
        .then(() => switchTab(event.recoveryTabId))
        .catch((error) => addEvent(error.message, "error"));
      break;
    case "pi_process_start":
      addEvent(`started pi rpc pid ${event.pid}`);
      refreshTabs().catch((error) => addEvent(error.message, "error"));
      break;
    case "webui_tab_restarting":
      addEvent(`restarting ${event.tabTitle || "terminal"} in ${event.cwd}`);
      break;
    case "webui_tab_reloading":
      addEvent(`reloading ${event.tabTitle || "terminal"} native Pi resources`);
      addTransientMessage({ role: "native", title: "/reload", content: `Reloading ${event.tabTitle || "terminal"} native Pi resources…`, level: "info" });
      break;
    case "webui_tab_reloaded":
      addEvent(`${event.tabTitle || "terminal"} reloaded`);
      addTransientMessage({ role: "native", title: "/reload", content: `${event.tabTitle || "terminal"} reloaded. Keybindings, extensions, skills, prompts, and themes were refreshed by restarting the RPC tab${event.sessionFile ? ` and resuming ${event.sessionFile}` : ""}.`, level: "info" });
      clearContextUsageUnknownAfterCompaction(event.tabId || activeTabId);
      statusEntries.clear();
      clearWidgetsForTab(event.tabId || activeTabId);
      latestBtwWidgetPayload = null;
      btwWidgetDismissedIdsByTab.delete(event.tabId || activeTabId);
      btwWidgetComposerOpen = false;
      btwWidgetInputDraft = "";
      resetOptionalFeatureAvailability();
      renderStatus();
      renderWidgets();
      refreshTabs().catch((error) => addEvent(error.message, "error"));
      setTimeout(() => {
        if (!isCurrentTabContext(tabContext)) return;
        refreshAll(tabContext).catch((error) => {
          if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
        });
      }, 500);
      break;
    case "webui_extension_ui_cancelled":
      removeQueuedDialogRequests(event.ids || []);
      addEvent(`cancelled ${event.ids?.length || 0} pending extension UI request(s)`, "warn");
      break;
    case "webui_extension_ui_resolved": {
      const closedActiveDialog = removeQueuedDialogRequests([event.id]);
      if (closedActiveDialog) {
        addEvent("extension UI request resolved");
        if (runIndicatorIsActive() && !activeDialog) setRunIndicatorActivity("Continuing after extension UI response…");
      }
      break;
    }
    case "webui_app_runner_update": {
      const runTabId = event.tabId || activeTabId;
      const previousRun = appRunnerDataByTab.get(runTabId)?.activeRun || null;
      setAppRunnerData(runTabId, { cwd: event.cwd, activeRun: event.activeRun });
      renderAppRunnerControls();
      // A chatty dev server sends several updates per second; append only the new lines to the
      // existing widget instead of rebuilding every widget and the tab strip each time.
      if (!patchAppRunnerWidgetInPlace(runTabId, previousRun, event.activeRun)) renderWidgets();
      const runningChanged = Boolean(previousRun && appRunnerIsRunning(previousRun)) !== Boolean(event.activeRun && appRunnerIsRunning(event.activeRun));
      if (!previousRun !== !event.activeRun || runningChanged || previousRun?.id !== event.activeRun?.id) renderTabs();
      break;
    }
    case "webui_git_changed":
      invalidateGitPanelRepository(event.root);
      break;
    case "webui_workspace_files_changed":
      if (event.tabId && event.tabId !== activeTabId) break;
      refreshFileTreeLive(tabContext).catch((error) => addEvent(error.message || String(error), "error"));
      break;
    case "webui_cwd_changed":
      addEvent(`${event.tabTitle || "terminal"} cwd changed to ${event.cwd}`);
      setAppRunnerData(event.tabId || activeTabId, { cwd: event.cwd, activeRun: null, runners: [] });
      closeFileViewer();
      resetFileTreeState();
      renderAppRunnerControls();
      renderWidgets();
      renderTabs();
      refreshTabs().catch((error) => addEvent(error.message, "error"));
      refreshFileTreeRoot(tabContext).catch((error) => addEvent(error.message, "error"));
      refreshAppRunners(tabContext).catch((error) => addEvent(error.message, "error"));
      scheduleRefreshFooter();
      break;
    case "webui_network_rebinding": {
      const closing = !!event.closing;
      const opening = event.opening === undefined ? !closing : !!event.opening;
      addEvent(
        closing
          ? `webui network listener closing to ${event.host}:${event.port}; event stream will reconnect or disconnect`
          : `webui network listener rebinding on ${event.host}:${event.port}; event stream will reconnect`,
        "warn",
      );
      latestNetwork = { ...(latestNetwork || {}), opening, closing };
      renderNetworkStatus();
      break;
    }
    case "webui_remote_auth_changed":
      latestNetwork = { ...(latestNetwork || {}), auth: event.auth || {} };
      addEvent(`remote PIN auth ${event.auth?.enabled ? "enabled" : "disabled"}`, event.auth?.enabled ? "warn" : "info");
      renderNetworkStatus();
      break;
    case "pi_process_exit":
      if (compactOutputActive()) compactLiveScheduler.flushNow();
      surfaceRuntimeDiagnostic("Pi process exited", `Pi RPC exited (${event.code ?? event.signal ?? "unknown"}).`);
      clearRunIndicatorActivity();
      refreshTabs().catch((error) => addEvent(error.message, "error"));
      break;
    case "pi_process_error":
      if (compactOutputActive()) compactLiveScheduler.flushNow();
      surfaceRuntimeDiagnostic("Pi process error", event.error || "Pi RPC process error.");
      clearRunIndicatorActivity();
      refreshTabs().catch((error) => addEvent(error.message, "error"));
      break;
    case "pi_stderr": {
      const message = String(event.text || "").trim();
      if (message) surfaceRuntimeDiagnostic("Pi runtime diagnostic", message, stderrDiagnosticLevel(message));
      break;
    }
    case "pi_stderr_sink_error":
    case "pi_stdout_line_too_large":
    case "pi_stdout_parse_error":
      surfaceRuntimeDiagnostic("Pi RPC transport error", event.error || "Pi RPC transport diagnostic.");
      break;
    case "queue_update":
      renderQueue(event);
      scheduleRefreshState();
      break;
    case "webui_compaction_queue_update":
      renderQueue(event);
      if (currentState) currentState = { ...currentState, pendingMessageCount: Number(event.pendingMessageCount ?? event.queueLength ?? currentState.pendingMessageCount ?? 0) };
      if (event.error) {
        addEvent(`queued compaction prompt resume failed: ${event.error}`, "error");
      } else if (event.drained) {
        addEvent("queued compaction prompt sent; Pi is resuming");
      } else if (event.draining) {
        setRunIndicatorActivity("Sending queued prompt after compaction…");
        addEvent("sending queued compaction prompt after compaction");
      } else if (event.queuedId) {
        setRunIndicatorActivity("Prompt queued; Pi will resume automatically after compaction…");
        addEvent("prompt queued until compaction finishes");
      }
      renderStatus();
      scheduleRefreshState();
      break;
    case "agent_start":
      promptRoutingTabs.delete(event.tabId || activeTabId);
      assistantErrorSurfacedThisRun = false;
      markTabWorkingLocally(event.tabId || activeTabId, { runStarted: true });
      if (currentState) currentState = { ...currentState, isStreaming: true };
      if (voiceConversationActiveFor(event.tabId || activeTabId)) voiceConversation.setAssistantActivity({ streaming: true });
      setRunIndicatorActivity("Agent run started; waiting for first output or action…");
      addEvent("agent started");
      syncLifecycleComposerState({ force: true });
      scheduleSemanticReconcile({ state: true, footer: true, feedback: true }, tabContext);
      break;
    case "agent_end":
      if (compactOutputActive()) finishCompactLiveOutput(tabContext);
      streamMessageActive = false;
      if (!assistantErrorSurfacedThisRun && event.willRetry !== true) {
        const message = assistantErrorFromAgentEnd(event);
        if (message) {
          surfaceRuntimeDiagnostic("Assistant error", describeAssistantFailure(message), "error", { actions: assistantFailureActions(event.tabId || activeTabId) });
          assistantErrorSurfacedThisRun = true;
        }
      }
      addEvent("agent run ended; waiting for settlement");
      if (runIndicatorIsActive()) setRunIndicatorActivity("Agent run ended; checking for retry or continuation…", { scroll: false });
      scheduleSemanticReconcile({ messages: true, state: true, footerData: true }, tabContext);
      break;
    case "message_start":
      if (event.message?.role === "assistant") {
        resetStreamBubble();
        streamMessageActive = true;
        setRunIndicatorActivity("Starting assistant message…", { scroll: false });
      }
      break;
    case "message_end": {
      if (event.message?.role === "assistant") streamToolCalls.reset();
      if (compactOutputActive()) finishCompactLiveOutput(tabContext);
      streamMessageActive = false;
      if (event.message?.role === "assistant" && event.message.stopReason === "error") {
        const message = String(event.message.errorMessage || streamProviderErrorText || "The assistant request failed without an error message.").trim();
        surfaceRuntimeDiagnostic("Assistant error", describeAssistantFailure(message), "error", { actions: assistantFailureActions(event.tabId || activeTabId) });
        assistantErrorSurfacedThisRun = true;
      }
      streamProviderErrorText = "";
      if (runIndicatorIsActive()) setRunIndicatorActivity("Assistant message finished; waiting for the next step…", { scroll: false });
      // Authoritative message reconciliation derives the todo-progress record;
      // raw assistant tokens never rebuild widgets.
      scheduleSemanticReconcile({ messages: true, state: true, footerData: true }, tabContext);
      break;
    }
    case "tool_execution_start":
      streamToolCallSeen = true;
      if (voiceConversationActiveFor(event.tabId || activeTabId)) voiceConversation.setAssistantActivity({ toolRunning: true });
      if (isIntercomTransportToolName(event.toolName)) {
        resetStreamingToolCallState({ remove: true });
        setRunIndicatorActivity("Agent is coordinating with another agent…");
        break;
      }
      if (compactOutputActive()) {
        compactLiveScheduler.flushNow();
        renderCompactToolShell(event);
      } else {
        suppressStreamingAssistantTextBeforeToolCall();
        removeStreamingToolCallCard();
        handleToolExecutionStart(event);
      }
      setRunIndicatorActivity(`Running tool: ${runIndicatorToolName(event.toolName)}…`);
      if (claimToolBoundaryRecord(event, "log:start")) addEvent(...toolLifecycleEventArguments(event, "start"));
      break;
    case "tool_execution_end": {
      if (voiceConversationActiveFor(event.tabId || activeTabId)) voiceConversation.setAssistantActivity({ toolRunning: false });
      if (isIntercomTransportToolName(event.toolName)) {
        resetStreamingToolCallState({ remove: true });
        setRunIndicatorActivity("Agent coordination finished; waiting for the next step…");
        scheduleSemanticReconcile({ messages: true, footerData: true }, tabContext);
        break;
      }
      const imagePayloadError = toolImagePayloadError(event);
      if (imagePayloadError) surfaceRuntimeDiagnostic("Tool image payload error", imagePayloadError);
      if (compactOutputActive()) {
        compactLiveScheduler.flushNow();
        renderCompactToolShell(event, { complete: true });
        finishCompactLiveOutput(tabContext);
      } else {
        handleToolExecutionEnd(event);
      }
      setRunIndicatorActivity(`Tool ${runIndicatorToolName(event.toolName)} ${event.isError ? "failed" : "finished"}; waiting for the agent's next step…`);
      if (claimToolBoundaryRecord(event, "log:end")) addEvent(...toolLifecycleEventArguments(event, "finish"));
      // Compact tool shells deliberately defer rich body construction to the
      // final transcript reconciliation; normal mode retains its live card.
      scheduleSemanticReconcile({ footerData: true }, tabContext);
      break;
    }
    case "compaction_start":
      if (currentState) currentState = { ...currentState, isCompacting: true };
      markContextUsageUnknownAfterCompaction(event.tabId || activeTabId);
      setRunIndicatorActivity(`Compacting context${event.reason ? ` (${event.reason})` : ""}…`);
      addEvent(`compaction started (${event.reason})`);
      renderStatus();
      break;
    case "compaction_end":
      if (compactOutputActive()) finishCompactLiveOutput(tabContext);
      if (currentState) currentState = { ...currentState, isCompacting: false };
      if (event.aborted) clearContextUsageUnknownAfterCompaction(event.tabId || activeTabId);
      else markContextUsageUnknownAfterCompaction(event.tabId || activeTabId);
      if (event.errorMessage) surfaceRuntimeDiagnostic("Compaction error", event.errorMessage);
      else addEvent(`compaction ${event.aborted ? "aborted" : "finished"}`);
      if (!currentState?.isStreaming) clearRunIndicatorActivity();
      markTabOutputSeen();
      renderStatus();
      scheduleSemanticReconcile({ state: true, messages: true, footerData: true }, tabContext);
      break;
    case "agent_settled":
      promptRoutingTabs.delete(event.tabId || activeTabId);
      if (compactOutputActive()) finishCompactLiveOutput(tabContext);
      streamMessageActive = false;
      addEvent("agent finished");
      notifyAgentDone(event.tabId || activeTabId, { activity: event.tabActivity, tabTitle: event.tabTitle });
      clearContextUsageUnknownAfterCompaction(event.tabId || activeTabId);
      if (currentState) currentState = { ...currentState, isStreaming: false };
      // handleAssistantTurnEnd resets the controller's streaming/tool flags and
      // flushes queued interruptions itself; calling setAssistantActivity here
      // first would flush the queue and then speak the interrupted answer.
      if (voiceConversationActiveFor(event.tabId || activeTabId)) void handleVoiceConversationTurnEnd(tabContext);
      clearRunIndicatorActivity({ deferRemoval: !autoFollowChat || !isChatNearBottom() });
      markTabOutputSeen();
      requestGitFooterWebuiPayload(tabContext, { force: true });
      // Settlement is the one boundary allowed to reconcile the full changed
      // set; it runs once here through the coalesced semantic scheduler.
      syncLifecycleComposerState({ force: true });
      scheduleSemanticReconcile({
        state: true,
        messages: true,
        footerData: true,
        feedback: true,
        usage: true,
        workflow: true,
      }, tabContext);
      break;
    case "auto_retry_start": {
      const seconds = Math.max(0, Math.ceil(Number(event.delayMs || 0) / 1000));
      const retryText = `Retrying (${event.attempt || "?"}/${event.maxAttempts || "?"}) in ${seconds}s after: ${event.errorMessage || "model/provider error"}`;
      setRunIndicatorActivity(retryText);
      addEvent(retryText, "warn", { notify: false });
      addTransientMessage({ role: "warn", title: "auto retry", content: retryText, level: "warn", key: "auto-retry" });
      break;
    }
    case "auto_retry_end":
      if (event.success === false) {
        const retryError = `Retry failed after ${event.attempt || "?"} attempt(s): ${event.finalError || "Unknown error"}`;
        addEvent(retryError, "error", { notify: false });
        addTransientMessage({ role: "error", title: "auto retry failed", content: describeAssistantFailure(retryError), level: "error", key: "auto-retry", actions: assistantFailureActions(event.tabId || activeTabId) });
      } else {
        addEvent(`retry recovered after ${event.attempt || "?"} attempt(s)`);
        transientMessages = transientMessages.filter((message) => message?.key !== "auto-retry");
        renderAllMessages();
      }
      break;
    case "extension_error": {
      const message = `${event.extensionPath || "extension"}${event.event ? ` during ${event.event}` : ""}: ${event.error || "unknown extension error"}`;
      addEvent(message, "error", { notify: false });
      addTransientMessage({ role: "error", title: "extension error", content: message, level: "error" });
      break;
    }
    case "extension_ui_request":
      handleExtensionUiRequest(event);
      break;
    case "response":
      if (event.success === false) surfaceRuntimeDiagnostic(`${event.command || "Pi command"} failed`, event.error || "Unknown RPC command error.");
      else if (event.command === "get_state" && event.tabId === activeTabId) {
        currentState = event.data || currentState;
        syncActiveTabActivityFromState(currentState);
        syncRunIndicatorFromState(currentState);
        renderStatus();
      } else if (["set_model", "cycle_model", "set_thinking_level", "cycle_thinking_level", "new_session", "compact"].includes(event.command)) {
        if (event.command === "set_model") {
          applyOptimisticModelSelection(event.data, tabContext);
        } else if (event.command === "cycle_model") {
          applyOptimisticModelSelection(event.data?.model, tabContext);
        } else if (event.command === "set_thinking_level" || event.command === "cycle_thinking_level") {
          applyOptimisticThinkingSelection(event.data, tabContext);
        } else if (event.command === "new_session") {
          const tabId = event.tabId || activeTabId;
          clearContextUsageUnknownAfterCompaction(tabId);
          forgetLastUserPrompt(tabId);
          resetGitWorkflowForTab(tabId);
        }
        scheduleRefreshState();
        scheduleRefreshMessages();
        scheduleRefreshFooter();
      }
      break;
    default:
      break;
  }
}

function connectEvents(tabContext = activeTabContext(), { requestedMode = "auto", fallbackAttempted = false } = {}) {
  flushNormalStreamRenders("reconnect");
  cancelNormalStreamRenders();
  eventSource?.close();
  eventSource = null;
  streamOutputController.cancel();
  fallbackStreamDerivedOutput("reconnect");
  resetCompactLiveOutput();
  activeOutputMode = "normal";
  outputModeAcknowledged = false;
  eventSourceOutputModeRequest = requestedMode === "normal" ? "normal" : "auto";
  eventSourceOutputModeFallbackAttempted = !!fallbackAttempted;
  if (!tabContext.tabId || !isCurrentTabContext(tabContext)) return;
  const parameters = new URLSearchParams({
    tab: tabContext.tabId,
    outputMode: eventSourceOutputModeRequest,
    outputModeProtocol: "1",
  });
  const source = new EventSource(`/api/events?${parameters.toString()}`);
  eventSource = source;
  source.onopen = () => {
    if (eventSource !== source || !isCurrentTabContext(tabContext)) return;
    if (!eventStreamPausedForBackground) refreshOptionalFeaturePackageStatuses().catch(() => {});
    scheduleIntercomConversationRefresh(tabContext, 0);
  };
  source.onmessage = (message) => {
    if (eventSource !== source || !isCurrentTabContext(tabContext)) return;
    try {
      const event = JSON.parse(message.data);
      if (!acceptSupervisorEvent(event, tabContext.tabId)) return;
      handleEvent(event);
    } catch (error) {
      if (isCurrentTabContext(tabContext)) addEvent(error.message, "error");
    }
  };
  source.onerror = () => {
    if (eventSource !== source || !isCurrentTabContext(tabContext)) return;
    streamOutputController.flush();
    flushNormalStreamRenders("disconnect");
    streamOutputController.cancel();
    fallbackStreamDerivedOutput("disconnect");
    if (compactOutputActive()) compactLiveScheduler.flushNow();
    addEvent("event stream disconnected; browser will retry", "warn");
    fetch("/api/health", { cache: "no-store" }).catch((error) => setBackendOffline(true, error));
  };
}

